// APP_VERSION (serial de zona DNS) vem de js/version.js — carregado antes deste.
const TRANSIENT_RETRY_ATTEMPTS = 2;
const TRANSIENT_RETRY_DELAYS_MS = [1500, 3500];
const STATS_KEY = 'waze_places_stats';
const FILTERS_KEY = 'waze_places_filters';
const PREFERENCES_KEY = 'waze_places_preferences';
const DEVMODE_KEY = 'waze_places_devmode';
const THEME_KEY = 'waze_places_theme';
const LANG_KEY = 'waze_places_lang';
const HISTORY_KEY = 'waze_places_history';
const SESSAO_KEY = 'waze_places_sessao_expira';
// Rank e staff do último perfil que CARREGOU. Não é preferência — é memória do
// que o Waze já respondeu, e existe por um motivo medido: sem ela, abrir o app
// com a conexão ruim faz o `/api/perfil` falhar, o perfil fica nulo, e a cota
// do Desfazer volta a travar. O editor que já tinha conquistado o direito de
// desligar leva a janela de 3s de volta — e a tela ainda diz "disponível
// depois que o app carregar seu perfil", como se fosse culpa dele.
const PERFIL_GATE_KEY = 'waze_places_perfil_gate';
// DE QUEM são os dados deste aparelho: o id do Waze da conta, e a marca da
// sessão em que ele foi visto (ver `contaAgora`). Sai no "Sair".
const CONTA_KEY = 'waze_places_conta';
const DEVMODE_TAPS_NEEDED = 7;
const DEVMODE_TAP_TIMEOUT_MS = 3000;
const UNDO_WINDOW_MS = 3000;

// Endereço oficial do Waze Map Editor. SEM segmento de idioma, sempre: o Waze
// pode redirecionar conforme o idioma da conta, e essa escolha é de quem abre,
// não nossa. Cravar `/pt-BR/` mandava todo mundo pro português.
const WME_EDITOR_URL = 'https://www.waze.com/editor';

// Forma DOCUMENTADA da Google Maps URLs API pra panorama. Existe a antiga
// `?layer=c&cbll=`, que é caminho interno e não contrato publicado — esta é a
// que a Google mantém como estável, e o custo de escolher errado aqui é o
// botão levar a um erro do Google na cara do editor.
const STREET_VIEW_URL = 'https://www.google.com/maps/@';

// A duração da janela aparece em DUAS frases (o toggle nas Preferências e a dica
// "você nunca desfaz"), nas três línguas — seis lugares onde o número estava
// escrito à mão. Registrado como variável global de i18n, ele vem daqui: mexer
// no UNDO_WINDOW_MS acima corrige os seis de uma vez.
//
// Função, não valor: é reavaliada a cada t(), então trocar de idioma reformata no
// locale novo. Registrar o resultado formatado congelaria o separador decimal do
// idioma que estava ativo na carga.
//
// Ponto conhecido: valor abaixo de 2000 produziria "1 segundos" no pt/es (o
// projeto não tem ICU; plural são chaves separadas, ver CLAUDE.md). Nenhum valor
// realista de janela de desfazer é < 2s, então não construí a maquinaria de
// plural pra uma hipótese — mas se alguém baixar, é aqui que quebra.
if (typeof setI18nVars === 'function') {
    setI18nVars({ undoSeg: () => (UNDO_WINDOW_MS / 1000).toLocaleString(i18nLocale()) });
}

// Nível mínimo pra entrar, COMO O EDITOR VÊ (o Waze conta rank de 0; a UI conta
// de 1 — gotcha #15). A verdade mora no `MIN_RANK_WAZE` do `server/core.mjs`,
// que é quem barra de fato; aqui é só o número que a tela de entrada mostra
// ANTES de existir qualquer resposta do servidor pra citar. `test/consistencia`
// reprova se os dois divergirem — divergir aqui é o app prometer um critério e
// aplicar outro, que é pior do que não avisar nada.
//
// Vai por `setI18nVars` e não escrito na frase porque `applyI18n()` chama
// `t(chave)` SEM parâmetro: sem o registro, o número seria digitado à mão em
// quatro línguas e alguém esqueceria uma na próxima mudança (já aconteceu com
// o "3s" da janela de desfazer).
const NIVEL_MINIMO_EXIBIDO = 2;
if (typeof setI18nVars === 'function') {
    setI18nVars({ nivelMinimo: () => NIVEL_MINIMO_EXIBIDO });
}

// Os prazos do SERVIDOR que a tela cita: a sessão vale 21 dias sem uso e o
// código de pareamento, 5 minutos. A verdade mora no core (`SESSION_TTL` e
// `PAIR_TTL`, em segundos) — o app é script clássico e não importa de lá —, e
// `test/consistencia` reprova se os números daqui divergirem dos de lá. Eram
// escritos à mão em cinco frases × quatro línguas (auditoria de 2026-09-26), e
// quem mudasse o prazo no servidor deixaria a Ajuda prometendo o antigo.
// Contagem inteira, então sai crua (regra do projeto); e as frases estão no
// plural ("dias", "minutos"): o mesmo teste cobra que os dois passem de 1.
const SESSAO_DIAS_EXIBIDO = 21;
const PAREAR_MIN_EXIBIDO = 5;
if (typeof setI18nVars === 'function') {
    setI18nVars({ sessaoDias: () => SESSAO_DIAS_EXIBIDO, parearMin: () => PAREAR_MIN_EXIBIDO });
}
// O outro prazo do servidor que a Ajuda cita: a lista de fotos da lixeira sai
// do servidor 1 minuto depois da ÚLTIMA gravação dela (`RELEITURA_TTL_STORE`,
// no core). E há duas: a do toque na lixeira e a de DEPOIS de cada exclusão —
// esta existe pra a exclusão seguinte usar a lista já sem a foto (gotcha #57) —,
// então a frase conta a partir da última exclusão, não do toque (dizia "do
// toque", e a lista ficava 74 s depois dele; auditoria de 2026-09-29). A frase
// está no SINGULAR ("minuto"): `test/consistencia` cobra que o valor siga 1.
const LISTA_FOTOS_MIN_EXIBIDO = 1;
if (typeof setI18nVars === 'function') {
    setI18nVars({ listaFotosMin: () => LISTA_FOTOS_MIN_EXIBIDO });
}
// Sem cap: a caixa de mudanças rola por dentro, cresce com o card e avisa que
// rola (esmaecido de borda). Com `MAX_CHANGES_DISPLAY = 4` a 5ª mudança era
// INALCANÇÁVEL — nem rolando — e a linha "+1 mais" gastava exatamente o espaço
// de uma linha de mudança pra dizer menos.

// Formato canônico do código de pareamento: XXX-XXX. O agrupamento 3+3 existe
// porque facilita ler em voz alta e digitar — mas quem MOSTRA e quem LÊ têm que
// concordar. Mostrar "6C4-97S" e pedir "ABC123" convida o editor a errar: ou ele
// digita o hífen sem saber se pode, ou omite achando que o que viu estava errado.
// Antes isso só não quebrava por duas coincidências (maxlength dimensionado pro
// hífen e o servidor limpando o que não é alfanumérico) — nenhuma delas
// combinada de propósito. Agora é UMA função, usada nos dois lados.
const PAIR_CODE_LEN = 6;
const PAIR_CODE_GRUPO = 3;
function formatarCodigoPareamento(bruto) {
    const limpo = String(bruto || '').toUpperCase().replace(/[^0-9A-Z]/g, '').slice(0, PAIR_CODE_LEN);
    return limpo.length > PAIR_CODE_GRUPO
        ? limpo.slice(0, PAIR_CODE_GRUPO) + '-' + limpo.slice(PAIR_CODE_GRUPO)
        : limpo;
}

// O código que a pessoa COLOU vem do jeito que ela o copiou: com espaço em
// volta, quebra de linha, ou de dentro de uma mensagem ("Código: 6C4-97S").
// O formatador pega os seis PRIMEIROS alfanuméricos, e aí o rótulo virava o
// código ("Código: ABC-123" → "CDI-GOA"); e o `maxlength` do campo cortava o
// colado ANTES de qualquer formatação (" ABC-123" → "ABC-12") — auditoria de
// 2026-09-26. Aqui se acha o código DENTRO do texto, por ordem de certeza:
//   1) o formato que a tela MOSTRA (3 + traço + 3), solto no texto — qualquer
//      traço, porque aplicativo de mensagem troca o hífen por outro;
//   2) seis símbolos soltos do ALFABETO do código (o do servidor, sem 0/O/1/I):
//      palavra como "codigo" ou "expira" tem O ou I, e não passa. Entre vários,
//      o que tem algarismo (palavra não tem) e, empatando, o ÚLTIMO — o código
//      costuma vir depois do rótulo.
// Sem nenhum dos dois, `null`: o navegador cola, e o `input` formata o que
// entrou (que é o caso de "ABC 123" e dos seis juntos).
const PAIR_ALFABETO = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
function extrairCodigoPareamento(texto) {
    const s = String(texto || '').toUpperCase();
    const m = /(?:^|[^0-9A-Z])([0-9A-Z]{3})\s*[-‐‑‒–—−]\s*([0-9A-Z]{3})(?![0-9A-Z])/.exec(s);
    if (m) return m[1] + m[2];
    const validos = (s.match(/[0-9A-Z]+/g) || [])
        .filter((p) => p.length === PAIR_CODE_LEN && [...p].every((c) => PAIR_ALFABETO.includes(c)));
    const comAlgarismo = validos.filter((p) => /\d/.test(p));
    return (comAlgarismo.length ? comAlgarismo : validos).pop() || null;
}

// O colar do campo do código: achou o código no texto, ele ENTRA no campo no
// formato da tela, no lugar do que houvesse lá; senão, o colar segue normal.
function colarCodigoPareamento(e) {
    const dados = e.clipboardData || window.clipboardData;
    const codigo = extrairCodigoPareamento(dados ? dados.getData('text') : '');
    if (!codigo) return;
    e.preventDefault();
    const campo = e.target;
    campo.value = formatarCodigoPareamento(codigo);
    try { campo.setSelectionRange(campo.value.length, campo.value.length); } catch (err) { /* tipo sem seleção */ }
}
const PREFETCH_THRESHOLD = 3;

// ── Aquecimento dos próximos cards ────────────────────────────────────────
// A regra do owner: **o próximo card sempre pronto, e pronto por inteiro** —
// foto, as outras fotos e os tiles do mapa. Isso é a LARGURA, e ela vale só
// pro card seguinte (segundo laço do prefetchNextImage).
//
// PROFUNDIDADE é outra grandeza: quantos cards à frente têm o PRIMEIRO SLIDE
// pronto — a imagem que aparece quando o card entra na tela, antes de tocar
// nas setas do carrossel. Ela é **de graça em total de bytes**: a fila é
// sequencial, esses cards vão aparecer de qualquer jeito, então só se move
// byte no tempo. Medido: sessão de 200 cards fica em ~35MB com profundidade
// 1 ou 3.
//
// O que ela compra é converter TEMPO OCIOSO em reserva. Com profundidade 1 o
// aquecimento só começa quando um card aparece: quem para 10s lendo um diff
// gasta 0,4s baixando o seguinte e deixa o link parado o resto. Triagem real
// é pausa, pausa, três swipes rápidos — a profundidade guarda a pausa. Numa
// rede boa 1 e 3 são indistinguíveis; a diferença aparece em rede sofrível
// com swipe rápido, que é justamente o caso que dói.
//
// O laço é genérico: esta constante é a única coisa a mexer pra mudar de
// ideia, e ela NUNCA afeta a largura.
const PREFETCH_PROFUNDIDADE = 3;
// Teto de fotos por card, escolhido pelo owner. Medido na fila real de 12
// países: 91,7% dos cards têm 4 fotos ou menos e são aquecidos por INTEIRO;
// nos 8,3% restantes as fotos além da 4ª carregam quando a pessoa chegar nelas
// no carrossel — e quem está navegando o carrossel não está passando rápido.
// O teto também segura o rabo: o pior card da fila tem TRINTA fotos, 2,3MB de
// dados móveis sozinho.
const PREFETCH_TETO_FOTOS = 4;

// Páginas SEGUIDAS sem nenhum pedido que o editor possa tratar (a região é de
// quem ele não edita, e o Waze segue dizendo `hasMore`): a busca desiste.
const MAX_EMPTY_PAGES = 5;
// Teto de páginas numa busca só. Ela relê a partir da página 1 (ver
// `fetchNextPage`), e no filtro "lidos também" as primeiras páginas são as que
// a pessoa já leu, que continuam pendentes no Waze — ela anda por elas até
// achar pedido novo. A maior fila medida tem ~800 pedidos (2 páginas); 20 são
// 10 mil, e o teto existe só pro Waze que dissesse `hasMore` pra sempre.
const MAX_PAGINAS_POR_BUSCA = 20;
// Os 7 tipos do WME, na ordem em que aparecem no filtro (local → foto). É a
// MESMA ordem do index.html de propósito: duas listas com a mesma ideia em
// ordens diferentes é como o editor descobre que o app se contradiz.
const TYPES_ALL = ['NEW_PLACE', 'DETAILS_UPDATE', 'FLAGGED_PLACE', 'DELETE_PLACE',
                   'NEW_PHOTO', 'FLAGGED_PHOTO', 'DELETE_PHOTO'];
// Quais vêm MARCADOS numa instalação nova. `DETAILS_UPDATE` e `FLAGGED_PLACE`
// ficam de fora, e o motivo é de PRODUTO, não de layout: o app é estilo Tinder,
// e o gesto rápido funciona quando há o que OLHAR. Decisão do owner.
//
// Os dois já estiveram desmarcados por um motivo diferente — o card deles não
// cabia na tela — e isso foi corrigido (1872 renders, zero estouro). A troca de
// motivo importa pro próximo que vier aqui: não adianta mexer no layout de novo
// pra tentar remarcá-los, porque não é o layout que os mantém fora.
//
// Medido na fila real, o argumento se sustenta em número: os 5 tipos do padrão
// somam 178 cards com 66% de foto (e `NEW_PHOTO` tem 2,27 fotos por card),
// contra 117 cards e 44% nos dois de fora.
//
// **Desmarcado ≠ escondido**: a caixa continua no filtro, com o nome do WME, a
// um toque. Esconder faria o editor achar que a fila acabou; desmarcar diz
// "existe, e você decide".
//
// A constante fica separada do TYPES_ALL mesmo quando os conjuntos coincidem:
// "todos os tipos que existem" e "os que vêm marcados" são perguntas
// diferentes, e só a primeira decide se vale mandar o filtro ao Waze.
const TYPES_PADRAO = TYPES_ALL.filter((t) => t !== 'DETAILS_UPDATE' && t !== 'FLAGGED_PLACE');
// O filtro salvo pode trazer lixo: storage de uma versão que não existe mais,
// chave editada à mão, JSON meio gravado. Fica só o que o app conhece — e se
// não sobrar NADA, volta ao padrão em vez de virar filtro vazio, que abriria o
// app numa fila sem um card e sem um erro na tela. "Parece que acabou o
// trabalho" é o defeito mais caro possível, porque ninguém reporta.
function sanearTiposSalvos(lista) {
    if (!Array.isArray(lista)) return TYPES_PADRAO.slice();
    const validos = TYPES_ALL.filter((t) => lista.includes(t));
    return validos.length ? validos : TYPES_PADRAO.slice();
}
const UNAUTHORIZED_REDIRECT_MS = 800;
// Espera antes de confirmar se a sessão morreu mesmo. Curto o bastante pra não
// atrasar quem precisa relogar de verdade, e longo o bastante pra a rajada que
// provocou o 403 do WAF já ter passado.
const VERIFICA_SESSAO_MS = 1200;
const STATE_RECOVERY_MS = 200;

// A ordem de fábrica. Declarada aqui, antes do `AppState`, porque os filtros de
// fábrica a usam na criação dele (um `const` declarado depois estaria na zona
// morta). O resto do "Perto de mim" mora na seção dele.
const ORDEM_PADRAO = 'newest';

// A ordem que se pede ao WAZE. Ele só ordena pela hora de atualização do LOCAL
// (MEDIDO em 2026-09-26, só leitura, conta do owner: o `SORTING_UPDATE_TIME_ASC`
// é aceito, HTTP 200, e muda a página 1 — mas o critério não é a data do pedido,
// então a ordem fina segue sendo do aparelho). "⏳ Mais antigos" pede do mais
// antigo pro mais novo, e a página 1 já vem perto do certo; as outras vão como
// sempre.
function ordemDoWaze() {
    return AppState.filters.sortOrder === 'oldest' ? 'SORTING_UPDATE_TIME_ASC' : 'SORTING_UPDATE_TIME_DESC';
}

// Uma ordem que NÃO é a do Waze ("Mais antigos", "Perto de…") só vale sobre a
// fila INTEIRA. Até 500 pedidos ela vem numa página; acima disso a busca parava
// na primeira que bastasse, e a ordem valia só pra ela — MEDIDO na fila do owner
// (554 não lidos): o mais antigo, e o mais perto de casa, só apareciam no card
// 499 (auditoria da fila, 2026-09-26). Com ela, a busca lê as páginas seguintes
// ANTES de ordenar: uma requisição a mais por página, só pra quem escolheu a
// ordem e tem mais de 500 pedidos.
//
// Pela ordem que VALE (`ordemValida`), não pela salva: "Perto de casa" salva com
// um perfil sem casa (tirada no WME, ou outra conta no aparelho), ou o GPS sem
// posição, ordenam por DATA — os Filtros mostram "Mais recentes" — e mesmo assim
// toda busca lia TODAS as páginas antes do primeiro card, uma requisição a mais
// por página no free tier (MEDIDO, n1-casa: páginas [1,2] na abertura e no ↻,
// contra [1] com "Mais recentes"; R56-3). Antes do perfil, a ordem salva segue
// valendo (`ordemSalvaEsperaOPerfil`): pode ser que a casa exista.
function ordemPrecisaDaFilaInteira() {
    const v = AppState.filters.sortOrder;
    return v !== ORDEM_PADRAO && ordemValida(v) !== ORDEM_PADRAO;
}

// Os filtros DE FÁBRICA — fonte ÚNICA do app recém-aberto e do "Sair". O "Sair"
// repunha um literal próprio, SEM `categories` e SEM `sortOrder`: quem saía e
// entrava de novo sem fechar o app ficava com filtros diferentes, e trocar SÓ a
// ordem virava uma busca (o "Aplicar" escreve `categories`, e a assinatura da
// busca mudava) — os pedidos pulados voltavam (auditoria da fila, 2026-09-26).
// Filtro novo entra AQUI.
function filtrosDeFabrica() {
    return { types: TYPES_PADRAO.slice(), residential: '', stateId: '', managedAreaId: '', myArea: false,
             unreadOnly: true, categories: [], sortOrder: ORDEM_PADRAO };
}

// As preferências DE FÁBRICA, pelo mesmo motivo dos filtros logo acima: o app
// recém-aberto, o "Sair" e a releitura do que outra aba gravou partem daqui. O
// "Sair" repunha um literal próprio, SEM `semUndoSeguidas` e SEM `pularGuarda`
// (auditoria de 2026-09-29, R4-5): inofensivo só porque as leituras de hoje
// tratam `undefined` como o padrão — a próxima preferência que não tratasse
// nasceria diferente depois de sair e entrar de novo. Preferência nova entra
// AQUI (e a leitura dela, em `lerPreferenciasGuardadas`).
function preferenciasDeFabrica() {
    return { undoEnabled: true, semUndoSeguidas: 0, presenca: true, pularGuarda: false };
}

const AppState = {
    authenticated: false,
    currentPlace: null,
    queue: [],
    hasMore: true,
    fetching: false,
    // A última busca, em números (páginas lidas, novos, já vistos, já
    // decididos): vai no diagnóstico. Não há "próxima página" — ver
    // `fetchNextPage`.
    ultimaBusca: null,
    serverTotal: 0,
    serverBlocked: 0,   // D13: pedidos da região que este editor não pode editar
    blockedPartial: false, // true = paramos antes do fim → serverBlocked é piso
    stats: { read: 0, rejected: 0, skipped: 0 },
    pendingAction: null,
    inFlightActions: 0,
    fetchEpoch: 0,
    _fetchPromise: null,
    _profilePromise: null,
    // A decisão da caixa de "Minha área" no ar (ver `completarPerfilChegado`).
    _caixaDaMinhaAreaNoAr: null,
    loadError: false,
    filters: filtrosDeFabrica(),
    preferences: preferenciasDeFabrica(),
    devMode: { unlocked: false, active: false },
    profile: null,
    countries: [],
    statesByCountry: {},
    seenCategories: [],      // categorias vistas nos places carregados (fonte do filtro de categoria)
    history: null,           // acumulado histórico { 'YYYY-MM-DD': { read, rejected } } (carregado lazy)
    autores: null,           // reincidência por autor: { v: [ids vistos 1x], r: { id: [n, nome, dia] } }
    sessaoExpiraEm: null     // quando a sessão do WAZE vence (epoch em segundos). Prazo FIXO, ver AVISO_SESSAO_DIAS
};

window.AppState = AppState;

// ÉPOCA DA SESSÃO — sobe a cada "Sair" e a cada queda de sessão.
//
// Toda continuação que GRAVA alguma coisa depois de um `await` de rede confere
// se a época ainda é a do gesto. Sem isto, a resposta de uma ação em voo que
// chegava depois do "Sair" recriava o histórico, a reincidência por autor (dado
// de TERCEIRO) e a fila de saída — de quem saiu, no aparelho de quem pode estar
// entrando; e a decisão na fila de saída sairia com a sessão de OUTRA pessoa.
// O `fetchEpoch` já fazia isso pela fila de pedidos; este é o mesmo cuidado
// pro resto.
let epocaDaSessao = 0;

// Desligar o modo dev com captura não baixada pede um SEGUNDO toque (ver o
// interruptor em `setupEventListeners`): até aqui, o segundo vale.
let desligarDevConfirmadoAte = 0;
// O número do último toque no interruptor do modo dev: a conta do aparelho é
// assíncrona, e só o toque mais novo decide (ver o interruptor).
let desligarDevVez = 0;

// Os códigos de pareamento que ESTE aparelho emitiu nesta página: o "Sair" os
// cancela no servidor, senão o QR mostrado antes seguia valendo 5 min e entrava
// numa conta que acabou de sair (auditoria de 2026-09-25).
const pareamentosEmitidos = new Set();

document.addEventListener('DOMContentLoaded', () => {
    initApp();
});

// Aviso do browser, não defeito do app: o navegador emite isto quando um
// ResizeObserver provoca layout que exige mais uma rodada de entrega no mesmo
// quadro. Nada quebrou, não há o que o editor fazer, e o app já convergiu no
// quadro seguinte — mas chegava como toast VERMELHO "Erro inesperado" em cima
// do card. Fica no console pra não virar invisível; some da cara de quem tria.
// Filtro estreito de propósito: só esta família de mensagem, nunca "todo erro
// que eu não quero ver".
const RUIDO_RESIZE_OBSERVER = /ResizeObserver loop/i;

window.addEventListener('error', (e) => {
    if (RUIDO_RESIZE_OBSERVER.test(e.message || '')) {
        console.warn('Ruído de ResizeObserver ignorado:', e.message);
        return;
    }
    console.error('Erro JS não-tratado:', e.error || e.message, e.filename, e.lineno);
    if (window.showToast) {
        window.showToast(t('toast.unexpectedError', { msg: e.message || t('toast.unexpectedError.reload') }), 'error');
    }
    if (window.AppState && window.AppState.authenticated) {
        const cardStack = document.getElementById('cardStack');
        if (cardStack && !cardDaFrente() &&
            document.getElementById('loadingCard').classList.contains('hidden') &&
            document.getElementById('noMoreCards').classList.contains('hidden')) {
            console.warn('Estado inconsistente detectado, tentando recuperar…');
            setTimeout(() => {
                if (typeof advanceQueue === 'function') advanceQueue();
            }, 100);
        }
    }
});

window.addEventListener('unhandledrejection', (e) => {
    console.error('Promise rejeitada:', e.reason);
});

function initApp() {
    // Armado ANTES de tudo: erro que acontece na carga é justamente o que não
    // aparece em lugar nenhum depois, e é o que mais interessa num socorro.
    diagCapturarErros();
    // Carimba a IDADE DESTE ARMAZENAMENTO, pelo mesmo motivo da linha acima e
    // com a mesma urgência: tem que acontecer antes de qualquer ramo.
    //
    // Por que AQUI e não junto do `marcarSessaoJaAtiva()`, que é o irmão dele:
    // aquele só roda no ramo `if (savedToken)`, e o `initApp` ainda tem um
    // `return` antes disso (o código de pareamento na URL). O carimbo é sobre o
    // ARMAZENAMENTO, não sobre a sessão — abrir sem token, ou cair no
    // pareamento, é carga igual, e pular a marcação nesses casos daria uma
    // idade menor do que a real, justamente na direção que INVENTA um
    // apagamento que não houve.
    //
    // Ele nasceu sem chamador na v2026.09.18-02 (a #219 trouxe a constante, a
    // função, a leitura no `diagSessao` e a remoção no logout — e nenhuma
    // chamada), então `nascimento` e `idadeDoArmazenamentoH` saíram `null` em
    // TODO diagnóstico desde então. Medido nos bytes de produção, com o diário
    // ao lado gravando normalmente: 3 entradas e 2 ciclos contra carimbo nunca
    // escrito.
    nascimentoDoArmazenamento();
    ligarFabDev();
    const versionEl = document.getElementById('appVersionDisplay');
    if (versionEl) {
        versionEl.textContent = 'v' + (typeof verLabel === 'function' ? verLabel(APP_VERSION) : APP_VERSION);
        setupDevModeTapTrigger(versionEl);
    }

    // i18n: idioma salvo (localStorage) ou detectado do navegador; aplica o
    // dicionário ao DOM estático logo no início (antes de renderizar o resto).
    if (typeof setLang === 'function') {
        setLang(safeLS.get(LANG_KEY) || undefined);
        applyI18n();
    }

    // Preferências ANTES das stats, e não é arrumação: `loadStats()` chama
    // `updateStats()`, que avalia o portão da conquista. Avaliar o portão sem
    // ter lido as preferências fazia o aviso "Mandou bem" sair a CADA recarga —
    // ele disparava, marcava na memória e a marca era descartada por
    // `savePreferences()` (que corretamente recusa gravar antes de ler).
    loadPreferences();
    loadStats();
    puladosNoInicioDaFila = AppState.stats.skipped || 0;
    // Com o perfil em CACHE a cota já é conhecida aqui, então a linha de base se
    // decide na hora; sem ele, `guardarPerfilDoPortao` decide quando o perfil
    // chegar. Sem esta chamada existe uma janela — entre abrir e o /api/perfil
    // responder — em que cruzar a cota não seria comemorado.
    initUndoGateSeen();
    loadFilters();
    carregarPrazoDaSessao();
    loadDevMode();
    enforceDevGatedFilters();
    // O que as aberturas anteriores deixaram guardado (só com o modo dev
    // ligado — sem ele a função sai na primeira linha e nem abre a base).
    diagCarregarAberturas();
    // E, com ele DESLIGADO, o que tenha sobrado no aparelho sai (sem criar a base).
    diagFaxinaSemModoDev();
    // Tema: segue o sistema até o user escolher manualmente (M3/HIG).
    applyTheme(getPreferredTheme());
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)');
    if (systemTheme.addEventListener) {
        systemTheme.addEventListener('change', (e) => {
            let stored = null;
            try { stored = localStorage.getItem(THEME_KEY); } catch (err) {}
            if (!stored) applyTheme(e.matches ? 'dark' : 'light');
        });
    }

    API.getRegion();
    API.getCountry();

    // ANTES de todo ouvinte da volta à página: quem pede alguma coisa ao voltar
    // do fundo (a presença, no `setupAppListeners`) já pede com o modo "saindo"
    // desligado (ver a função, R8-5-02).
    setupFimDoModoSaindo();
    setupAuthListeners();
    setupAppListeners();
    setupModalListeners();
    setupLightbox();
    setupMapaLightbox();
    setupKeyboardInset();
    setupAlturaDoHeader();
    setupDescargaAoSair();
    // DEPOIS do de cima, e a ordem importa: os dois ouvem o ir-pro-fundo, e a
    // ação que estava na janela do Desfazer tem que ir pra fila de saída antes
    // de o diagnóstico ser guardado — senão o diário guardado não a mostra.
    setupGuardaDoDiagnostico();
    marcarSuporteAExtensao();
    ajustarEntradaAoIPhoneInstalado();
    setupInstalarApp();
    setupSincroniaEntreAbas();   // o app aberto em duas abas (ver a função)

    // Link de pareamento (/#pair=SEGREDO): o editor apontou a câmera ou mandou o
    // link pra si mesmo — entra direto, sem digitar nada. Tratado ANTES da
    // sessão salva porque um código novo deve vencer uma sessão velha do mesmo
    // aparelho.
    //
    // FRAGMENTO, não query. O navegador não envia o fragmento ao servidor, então
    // o segredo não entra no log de acesso — e ele é justamente a chave que
    // decifra o registro de pareamento (ver `derivarChave` no core). Com
    // `?pair=` o segredo ia parar no log ao lado do dado que ele protege, o que
    // anulava a proteção inteira. A query segue sendo LIDA por tolerância (link
    // antigo ainda no histórico de alguém), mas nunca mais é GERADA.
    const codigoNaURL = (() => {
        try {
            const frag = new URLSearchParams(String(window.location.hash || '').replace(/^#/, ''));
            return frag.get('pair') || new URLSearchParams(window.location.search).get('pair');
        } catch (e) { return null; }
    })();
    if (codigoNaURL) {
        try { window.history.replaceState({}, '', window.location.pathname); } catch (e) {}
        abrirPeloCodigoDaURL(codigoNaURL);
        return;
    }

    if (API.getSession()) {
        abrirComSessaoSalva();
    } else {
        // Sem sessão o atalho do ícone não vale, mas a query dele sai da URL
        // AGORA: senão um F5 depois do login a executava (ver a função).
        tirarAcaoDaURL();
        // Os controles da Ajuda que só existem com sessão somem JÁ, e não só
        // quando a tela de entrada aparecer: enquanto a extensão é perguntada
        // (até EXT_ESPERA_MS) a Ajuda já abre, e mostrava Praticar, Conectar
        // outro aparelho, Sair e o "Como funciona" pra quem não entrou.
        mostrarControlesDeSessao(false);
        // Sem sessão: antes de mostrar a tela de login, PERGUNTA à extensão.
        // Quem tem a extensão instalada e está logado no WME entra sem tocar em
        // nada; quem não tem cai na tela de sempre depois de EXT_PRESENTE_MS (sem o
        // `aguarde` da ponte; com ele, a espera vai até EXT_ESPERA_MS).
        entrarPelaExtensao().then(aoFimDaPerguntaDaAbertura);
    }
}

// O fim da pergunta à extensão na ABERTURA sem sessão (o `initApp`).
//
// Escrita ATRASADA não pode atropelar estado novo. Entre o pedido e o fim da
// pergunta passam centenas de ms (até `EXT_ESPERA_MS`), e nesse meio alguém
// pode ter entrado por outro caminho (colar cookies, código de pareamento,
// token injetado). Sem a primeira guarda o `showAuthScreen` derrubava a sessão
// recém-criada e escondia o app JÁ montado — apareceu como "card sem endereço /
// botões 0px" no smoke, mudando de aparelho a cada rodada porque atinge sempre
// o PRIMEIRO card medido.
//
// O login DESTA aba passa pelo `setSession`, que o põe na MEMÓRIA, e é ela que
// se pergunta (`temSessaoNaMemoria`). A guarda perguntava pelo `getSession`,
// que com a memória vazia lê o APARELHO e GRAVA na memória o que leu: a sessão
// que OUTRA aba guardou nesse meio (a pessoa entrou lá enquanto esta
// perguntava) passava por ela como se fosse desta. A aba saía sem mostrar a
// tela de entrada — e o "Entrando pelo WME…" já tinha se escondido —, e ficava
// EM BRANCO, só com o cabeçalho e sem caminho nenhum pra entrar, até recarregar
// (auditoria de 2026-10-06, R9-1-03).
//
// Essa sessão é ADOTADA, como numa abertura com sessão salva — a decisão de
// produto que a auditoria deixou em aberto (a outra saída era a tela de
// entrada; em branco, nunca): é a abertura que esta aba teria feito um
// instante depois, e a que recarregar faz. A recusa que a extensão tenha
// repassado (o portão negou a conta do WME) não aparece: quem fica é a sessão
// do aparelho, de quem entrou na outra aba. E o que a tela de entrada tinha
// aberto sai com a limpeza, como na entrada pela extensão (ver
// `MODAIS_DA_ENTRADA`). A adoção mora em `adotarSessaoDoAparelho`, que a volta à
// aba e o link de pareamento que falhou também usam (R10-1-03 e R10-1-04).
function aoFimDaPerguntaDaAbertura(entrou) {
    if (entrou) return;
    if (API.temSessaoNaMemoria() || AppState.authenticated) return;
    // A sessão guardada no aparelho entra como na abertura com sessão salva. Sem
    // nenhuma (ou sem poder adotá-la), a tela de entrada — um caminho ou o outro,
    // nunca nenhum dos dois.
    if (adotarSessaoDoAparelho()) return;
    showAuthScreen();
    mostrarNegadoDaExtensao();   // o portão recusou: o motivo, não o silêncio
}

// A sessão que OUTRA aba guardou no aparelho, ADOTADA por esta, que está sem
// sessão: é a abertura com sessão salva — a que recarregar faz. Chegam aqui o
// fim da pergunta da abertura (R9-1-03), a volta a esta aba na tela de entrada
// (`aoVoltarAAba`) e o link de pareamento que falhou (`abrirPeloCodigoDaURL`).
// Eram desfechos diferentes pra mesma situação: a abertura adotava, e a volta à
// aba e o link vencido deixavam a pessoa no "Bem-vindo!" com a sessão viva no
// aparelho, sem perguntar nada a ninguém, até recarregar (auditoria da rodada
// 10, R10-1-03 e R10-1-04, MEDIDO).
//
// O que a tela de entrada tinha aberto sai com a limpeza (ver
// `MODAIS_DA_ENTRADA`). A fila é NOVA, como em todo login: a que sobrou na
// memória é da sessão que caiu NESTA aba (a queda a mantém pra renovação), e
// sem o `resetQueue` o app voltava com o card dela na tela. E as marcas da
// página recomeçam (`aoEntrarNestaPagina`), como em todo login que dá certo:
// a recusa que a extensão tenha repassado não aparece — quem fica é a sessão do
// aparelho, de quem entrou na outra aba.
//
// NÃO adota, e a tela fica como está:
//   · com uma pergunta à extensão ou um resgate de código no ar: o fim deles
//     decide, e passa por aqui; e com os cookies DESTA aba sendo conferidos (o
//     "Colar" já confirmado): o login que a pessoa pediu vence, e adotar antes
//     mostraria por um instante a conta da outra aba;
//   · com TEXTO DIGITADO num diálogo da entrada (o cookies.txt colado, o
//     código): a pessoa estava entrando por ali — talvez com OUTRA conta —, e a
//     adoção fecharia o diálogo jogando fora o que ela digitou. É o R9-1-03 (b):
//     a aba da tela de entrada nunca vira "logada" sem mostrar o app, e aqui ela
//     segue sem sessão nenhuma na memória (o "Sair" de lá não a encerra). Sem
//     texto, o diálogo vazio fecha e a sessão entra.
// O foco que estava NA tela de entrada vai ao ✕ do primeiro card (R10-1-05).
// Devolve se adotou.
function adotarSessaoDoAparelho() {
    if (API.temSessaoNaMemoria() || AppState.authenticated) return false;
    if (extPerguntando || resgateEmVoo || authInFlight) return false;
    // O aparelho se lê pelo `safeLS`: o `getSession`, com a memória vazia, GRAVA
    // nela o que lê — e isso já é adotar (R9-1-03).
    if (!safeLS.get('waze_session_token')) return false;
    if (textoDigitadoNaEntrada()) return false;
    const focoNaEntrada = focoNaTelaDeEntrada();
    API.getSession();   // a adoção: a sessão guardada vai pra memória desta aba
    aoEntrarNestaPagina();
    fecharModaisDaEntrada({ focoComDestino: focoNaEntrada });
    resetQueue();
    abrirComSessaoSalva();
    if (focoNaEntrada) focoDoTeclado = BOTAO_DA_ACAO.left;
    return true;
}

// O que a pessoa DIGITOU (ou colou) num diálogo ABERTO da tela de entrada: o
// cookies.txt no "Colar cookies", o código no "Entrar com um código". O diálogo
// fechado já teve o campo limpo (`LIMPEZA_AO_FECHAR`), e só um abre por vez.
function textoDigitadoNaEntrada() {
    return [['pasteModal', 'cookiesTextarea'], ['pairEnterModal', 'pairCodeInput']].some(([modal, campo]) => {
        const m = document.getElementById(modal);
        const c = document.getElementById(campo);
        return !!(m && !m.classList.contains('hidden') && c && String(c.value || '').trim());
    });
}

// O foco está NA tela de entrada — num botão dela ou num diálogo dela? Quem a
// esconde sem gesto (a extensão que entra, a sessão do aparelho adotada) levava
// o foco junto: o diálogo fechado o devolve ao botão da própria tela de
// entrada, que some logo depois, e ele caía no <body> — o Tab seguinte ia ao
// mapa do card, não ao ✕ (auditoria da rodada 10, R10-1-05, MEDIDO). Com ele
// aqui, o foco fica prometido ao ✕ do primeiro card (`focoDoTeclado`), como no
// login pelo teclado (R7-1-04); com o foco no <body> (ninguém estava na tela de
// entrada), nada se move. Lido ANTES de fechar os diálogos.
function focoNaTelaDeEntrada() {
    const ativo = document.activeElement;
    if (!ativo || ativo === document.body || ativo === document.documentElement) return false;
    if (document.getElementById('authScreen')?.contains(ativo)) return true;
    return MODAIS_DA_ENTRADA.some((id) => !!document.getElementById(id)?.contains(ativo));
}

// O link de pareamento aberto neste aparelho. Num aparelho JÁ logado, o link
// costuma estar VENCIDO (o QR de ontem, o link que ficou na conversa): o
// resgate falhava e a pessoa caía no "Bem-vindo!" com a sessão válida guardada
// no aparelho, sem saber que bastava recarregar (auditoria de 2026-09-26). Com
// sessão salva, a tela de entrada não aparece antes da resposta; se o código
// valer, ele vence a sessão velha (é o pedido explícito de agora); se não
// valer, o aviso de sempre sai e a sessão salva segue o caminho normal.
//
// SEM sessão salva, o link que falha deixava a pessoa no "Bem-vindo!" com o
// "Código inválido" e mais nada: a abertura pelo link não pergunta à extensão,
// e a sessão que OUTRA aba guardou durante o resgate não era adotada (auditoria
// da rodada 10, R10-1-04, MEDIDO). Agora a sessão do aparelho entra, como na
// abertura; sem ela, a extensão é perguntada como na abertura comum. O aviso do
// código inválido já saiu e fica — o resgate é que o mostra.
function abrirPeloCodigoDaURL(codigo) {
    const sessaoSalva = !!API.getSession();
    if (!sessaoSalva) showAuthScreen();
    return resgatarPareamento(codigo, { silencioso: true }).then((entrou) => {
        if (entrou) return;
        if (sessaoSalva) {
            if (API.getSession()) abrirComSessaoSalva();
            else showAuthScreen();
            return;
        }
        // Entrou NESTA aba durante o resgate (o colar, outro código): nada aqui.
        if (API.temSessaoNaMemoria() || AppState.authenticated) return;
        // Nem com um login DESTA aba ainda no ar — os cookies colados e
        // confirmados durante o resgate esperaram o desfecho dele (R12-1-01) e,
        // com ele recusado, seguem AGORA — nem com TEXTO DIGITADO num diálogo da
        // entrada: o fim desse login (ou a pessoa) decide, a régua da adoção
        // (`adotarSessaoDoAparelho`) e da volta à aba (`perguntarAExtensaoAoVoltar`).
        // A pergunta trazia a sessão da conta do WME por cima: dois logins na
        // mesma aba — a extensão trocava a conta que a pessoa colou (ou o
        // contrário, com o aviso "Outra conta entrou neste aparelho" sobre o
        // login dela), uma das duas sessões ficava órfã no servidor, e o que
        // estava colado e não confirmado ia embora com a limpeza do diálogo
        // (auditoria da rodada 13, R13-1-03, MEDIDO). Outro resgate não cabe
        // aqui: este acabou de terminar, e nada começa entre o fim dele e isto.
        if (authInFlight || textoDigitadoNaEntrada()) return;
        // Com sessão no aparelho a extensão não é perguntada (traria uma sessão
        // nova por cima da guardada): ela é adotada, ou — com texto digitado na
        // tela de entrada — a tela fica como está.
        if (safeLS.get('waze_session_token')) { adotarSessaoDoAparelho(); return; }
        return entrarPelaExtensao().then(aoFimDaPerguntaDaAbertura);
    });
}

// A abertura com a sessão GUARDADA no aparelho: o caminho de sempre, e também o
// de quem abriu um link de pareamento vencido num aparelho já logado.
function abrirComSessaoSalva() {
    // O token veio do armazenamento, não do login: sem isto o ciclo desta
    // sessão nasce sem início e a duração não existe (ver a função).
    marcarSessaoJaAtiva();
    // O que a fila de saída guardou por versão anterior, sem a marca da
    // sessão, é desta sessão aberta (ver a função). ANTES do esvaziamento.
    adotarSaidaSemMarca();
    showMainScreen();
    // O que ficou esperando de uma sessão anterior aparece e sai agora.
    // É o segundo (e último) gatilho: o outro é o evento `online`. Nenhum
    // dos dois é polling — a regra do free tier proíbe.
    //
    // DEPOIS do `showMainScreen`, e isso é load-bearing: é ELE que põe
    // `AppState.authenticated = true`, e o esvaziamento sai na primeira
    // linha sem isso. Chamado antes, o gatilho da abertura não fazia nada —
    // calado, e justamente pra quem ficou offline e fechou o app.
    updateInFlightIndicator();
    esvaziarFilaDeSaida();
    AppState._profilePromise = loadProfileAndAuxData();
    // Sem rede, a fila guardada entra no lugar da tela de falha — e aí NÃO
    // se chama `startFetching`, que só gastaria uma requisição fadada a
    // falhar. Com rede, segue o caminho de sempre e a varredura pega
    // carona na resposta que chegar.
    offlineTentarAbrirSemRede().then(async (abriu) => {
        if (abriu) return;
        // COM rede, a janela da última preparação completa vale também. Sem
        // ela o app renascido (o Android encerra app em segundo plano)
        // pedia a foto CRUA até a próxima varredura terminar — e se o sinal
        // caísse antes disso, "a foto precisa de sinal" com a cópia `?w=`
        // viva no cache. Só lê com o toggle ligado: quem não usa não paga.
        // Vem com ela QUAL fila a preparação cobriu: no lie-fi a busca falha e
        // a guardada abre (`abrirGuardadaDepoisDaFalha`) com a janela já na
        // memória, e sem a cobertura a linha diria "Ainda não preparado" de
        // uma fila pronta.
        if (offlineLigado() && offlineJanelaServida === null) await offlineRecuperarJanela();
        startFetching();
    });
    handleLaunchAction();
}

// ── Handshake com a extensão WazePlaces Rapid Access (@daflash) ───────────
//
// A extensão já sabia fazer login sozinha, mas só reagia ao botão dela dentro
// do WME: abrir o app direto não acionava nada, e sessão vencida obrigava a
// voltar ao WME e clicar de novo. O handshake inverte quem começa a conversa —
// o APP pede, a extensão responde —, e com isso o login vira invisível nos dois
// momentos que importam: ao abrir, e quando a sessão morre no meio do uso.
//
// O protocolo é `postMessage` na própria janela porque a extensão já injeta um
// content script no app (`auto-login.js`): é o canal que existe sem pedir
// permissão nova no manifesto dela.
//
// SEGURANÇA: aceitar um token por postMessage NÃO abre superfície nova —
// qualquer script na página já pode escrever `localStorage.waze_session_token`
// direto. Mesmo assim exigimos `event.source === window` e origem própria, pra
// não aceitar nada vindo de iframe ou de outra janela.
// Dois prazos, e a diferença entre eles é o desenho todo.
//
// A extensão leva ~1,8s pra responder — ela faz ida e volta ao Waze de verdade
// (medido com a extensão carregada). Esperar isso calado penalizaria QUEM NÃO
// TEM a extensão com 2 segundos de tela vazia; e mostrar o login na hora faria
// quem TEM ver a tela piscar antes de entrar.
//
// Por isso a ponte responde `aguarde` IMEDIATAMENTE (é mensagem local, sem
// rede) e só depois manda o token. Quem não tem extensão não recebe `aguarde`
// nenhum e cai no login em EXT_PRESENTE_MS — tempo que ninguém percebe.
const EXT_PRESENTE_MS = 350;    // "tem extensão aí?" — só espera local
const EXT_ESPERA_MS = 8000;     // depois do `aguarde`, o prazo da ida ao Waze
// A renovação da QUEDA mantém a fila, e o aviso "sua fila continua aqui" espera
// o perfil dizer de quem é a sessão nova (a extensão publicada hoje não diz):
// com OUTRA conta a fila é trocada, e o aviso seria desmentido pelo da troca
// (ver `derrubarSessao`). O teto é só pra o aviso não depender de uma resposta
// que pode não vir: passado ele, a fila continuou mesmo, e o perfil que chegar
// depois ainda a troca, com o aviso dele.
const AVISO_RENOVADA_ESPERA_PERFIL_MS = 4000;
let extPerguntando = false;
// A extensão RESPONDEU que está buscando a sessão (o `aguarde` da ponte): só daí
// em diante há uma renovação de verdade a esperar. A pergunta sozinha
// (`extPerguntando`) não diz que a extensão existe — a queda pergunta "tem
// extensão aí?" por 350 ms em todo aparelho, inclusive no celular, onde ela não
// instala —, e o toque no card travado nesse meio mandava "esperar a
// conferência e tocar de novo", logo antes do "a sessão não vale mais"
// (auditoria de 2026-10-02, R6-1-03). Ver `avisoDaTrava`.
let extRenovando = false;
// A extensão disse que o PORTÃO recusou esta conta (nível ou área — ver o
// `autenticar` do background.js dela). Antes a recusa chegava como um
// `sem-sessao` qualquer: quem não passa no portão e usa a extensão NUNCA via o
// motivo, a extensão tentava 4 vezes (4 idas ao /Session do Waze no nome da
// pessoa) e tudo se repetia a cada volta à aba (auditoria de 2026-09-26).
// Agora o app mostra o MESMO "Acesso restrito" do login por arquivo, e não
// pergunta de novo nesta página ao voltar à aba.
let extNegadoNestaPagina = false;
let extNegado = null;   // a recusa que ainda não foi mostrada (quem mostra, consome)
// A fila NA TELA atravessou uma troca de sessão (a renovação silenciosa a
// manteve): ela é da sessão anterior, e se o perfil revelar OUTRA conta ela sai
// (ver `esquecerOutraConta`). Todo `resetQueue` a zera.
let filaAtravessouSessao = false;

// `silencioso`: sem o "Entrando pelo WME…" por cima da tela. `manterFila`: a fila
// que está na tela continua — só a renovação da QUEDA (`derrubarSessao`), com a
// pessoa no meio da triagem. Eram a mesma chave, e a volta à aba (que vem da
// TELA DE ENTRADA, com a fila da sessão que caiu na memória) mantinha a fila
// velha — com o perfil de quem entrou no WME, que pode ser OUTRA conta
// (auditoria da costura, 2026-09-26, K2).
function entrarPelaExtensao({ silencioso = false, manterFila = false } = {}) {
    if (extPerguntando) return Promise.resolve(false);
    extPerguntando = true;
    extNegado = null;   // uma recusa de pergunta ANTERIOR não é desta
    // A época de quando a pergunta SAIU. A resposta leva até 8 s, e o "Sair"
    // pode acontecer nesse meio (o botão fica na Ajuda durante a renovação da
    // queda): o token que chegava depois entrava de novo, e o "Sair" era
    // desfeito — MEDIDO, token de volta e o app aberto (auditoria da costura,
    // 2026-09-26, K3). O "Sair" sobe a época na primeira linha, então ela
    // cobre também o `saiuNestaPagina`.
    const epoca = epocaDaSessao;

    return new Promise((resolve) => {
        let terminou = false;
        let prazo = setTimeout(() => fim(false), EXT_PRESENTE_MS);
        function fim(ok) {
            if (terminou) return;
            terminou = true;
            window.removeEventListener('message', ouvir);
            clearTimeout(prazo);
            extPerguntando = false;
            extRenovando = false;
            mostrarEntrandoPelaExtensao(false);
            resolve(ok);
        }
        function ouvir(ev) {
            if (ev.source !== window || ev.origin !== window.location.origin) return;
            const d = ev.data;
            if (!d || d.source !== 'wazeplaces-ext') return;
            // "estou aqui, trabalhando" — só agora vale mostrar o spinner e
            // esperar de verdade. Sem isto, quem não tem a extensão pagaria a
            // espera dela.
            if (d.action === 'aguarde') {
                clearTimeout(prazo);
                prazo = setTimeout(() => fim(false), EXT_ESPERA_MS);
                // A renovação de verdade começou: o card travado pede pra
                // esperar (ver `avisoDaTrava`).
                extRenovando = true;
                if (!silencioso) mostrarEntrandoPelaExtensao(true);
                return;
            }
            if (d.action === 'sem-sessao') {
                // Instalada, mas sem sessão pra dar. Com o motivo `negado`, vem
                // junto o que o servidor disse (perfil e motivo). Continua sendo
                // `sem-sessao` de propósito: o app de ANTES não conhece o motivo
                // e cai no login na hora, como sempre fez.
                if (d.motivo === 'negado') {
                    extNegadoNestaPagina = true;
                    extNegado = negadoDaExtensao(d.negado);
                }
                return fim(false);
            }
            if (d.action !== 'sessao' || !d.token) return;
            const tokenDaExtensao = String(d.token);
            // Saiu no meio (ver acima): a resposta não entra — e a sessão que a
            // extensão acabou de criar, com os cookies válidos da pessoa, SAI do
            // servidor. Só ignorada, ela ficava lá sem dono por até 21 dias,
            // depois de a pessoa pedir pra sair (auditoria da rodada 12, R12-1-02,
            // MEDIDO). Menos se ela já é a do APARELHO: a ponte dá o desfecho de UM
            // login a todas as abas que perguntam juntas, e a outra aba (que entrou
            // de novo depois do "Sair") pode estar com ela — a régua logo abaixo.
            if (epoca !== epocaDaSessao) {
                if (tokenDaExtensao !== safeLS.get('waze_session_token')) {
                    callWithRetry(() => API.destroySession(tokenDaExtensao), null).catch(() => {});
                }
                return fim(false);
            }
            // Um login DESTA aba no meio da pergunta: a pessoa colou os cookies,
            // digitou o código ou abriu o link enquanto a extensão respondia. O
            // login que ela pediu vence, como na adoção (`adotarSessaoDoAparelho`)
            // — e a resposta da extensão o TROCAVA: duas sessões no servidor (o
            // "Sair" apaga uma, a outra fica órfã por até 21 dias) e, com outra
            // conta no WME, a conta que a pessoa acabou de escolher ia embora com
            // "Outra conta entrou neste aparelho…" (auditoria da rodada 11,
            // R11-1-03, MEDIDO). Vale o login que já entrou (a memória com OUTRA
            // sessão) e o que ainda está no ar. A sessão da extensão sai do
            // servidor, menos se ela já é a do aparelho: a ponte dá o desfecho de
            // UM login a todas as abas que perguntam juntas, e a outra pode estar
            // com ela.
            //
            // Em TODA pergunta que não é a renovação da QUEDA (`manterFila`): a
            // abertura e o link de pareamento que falhou (R10-1-04) também. A régua
            // valia só pra pergunta da volta à aba, e o link recusado com os
            // cookies colados e confirmados durante o resgate (que esperaram o
            // desfecho dele e seguiam) fazia dois logins na mesma aba — o que
            // respondesse por último trocava o outro, e uma das sessões ficava
            // órfã no servidor (auditoria da rodada 13, R13-1-03, MEDIDO). A
            // renovação da queda fica de fora: ali não há tela de entrada nem login
            // desta aba, e a resposta da extensão É o login que a aba espera.
            //
            // E o TEXTO DIGITADO num diálogo da entrada (o cookies.txt colado, o
            // código) é um login desta aba começando: a régua da adoção e da volta
            // (`perguntarAExtensaoAoVoltar`, R12-1-05). Ela era conferida só na
            // hora de PERGUNTAR — e a pergunta silenciosa da volta deixa a tela de
            // entrada usável enquanto corre (~1,8 s com a extensão de verdade, até
            // 8 s): o que a pessoa colava nesse meio ia embora com a limpeza do
            // diálogo quando a extensão entrava (auditoria da rodada 13, R13-1-05,
            // MEDIDO).
            const loginDestaAbaVence = !manterFila
                && ((API.temSessaoNaMemoria() && API.sessionToken !== tokenDaExtensao) || authInFlight || resgateEmVoo
                    || textoDigitadoNaEntrada());
            if (loginDestaAbaVence) {
                if (tokenDaExtensao !== safeLS.get('waze_session_token')) {
                    callWithRetry(() => API.destroySession(tokenDaExtensao), null).catch(() => {});
                }
                return fim(false);
            }
            API.setSession(String(d.token), 'extensao');
            aoEntrarNestaPagina();
            // O foco que estava NA tela de entrada (no "Colar cookies", no campo
            // dele) vai ao ✕ do primeiro card: ela some agora, sem gesto, e ele
            // caía no <body> (R10-1-05; ver a função). Lido antes de fechar.
            const focoNaEntrada = focoNaTelaDeEntrada();
            // O que a tela de entrada tinha aberto (o "Colar", com o chaveiro
            // colado) sai COM a limpeza — ver `MODAIS_DA_ENTRADA`.
            fecharModaisDaEntrada({ focoComDestino: focoNaEntrada });
            showMainScreen();
            // Fila NOVA, como no login por cookies: a que sobrou na memória é
            // da sessão que caiu (e o treino, se aberto, sai junto). Menos na
            // renovação da QUEDA (`manterFila`): ali a pessoa estava no meio da
            // triagem e a fila tem que continuar na tela — até o perfil dizer
            // de quem é a sessão nova (ver `filaAtravessouSessao`).
            if (manterFila) filaAtravessouSessao = true;
            else resetQueue();
            // O perfil da sessão nova é pedido ANTES de a conta ser conhecida: com
            // OUTRA conta, a troca (`esquecerOutraConta`) refaz JÁ a fila que
            // atravessou a sessão, e a busca de "Minha área" espera o perfil
            // (`startFetching`). Pedido depois, a busca esperava o da sessão que
            // caiu, já resolvido, e saía sem perfil: a tela de falha aparecia até o
            // novo chegar (MEDIDO: ~1,5 s) — ou, com a carga anterior há mais de
            // um minuto, o `refazerPerfilSeFaltar` da busca pedia o perfil e esta
            // linha pedia de novo: DOIS `/Session` por servidor (auditoria da
            // rodada 11, R11-6-02).
            AppState._profilePromise = loadProfileAndAuxData();
            // A conta, quando a ponte a repassa (a versão da extensão que
            // repassa o `conta` do `testar-cookies`): com OUTRA conta, a fila
            // que atravessou a sessão sai JÁ, sem esperar o perfil (K2/K8).
            conhecerContaDoLogin(d.conta);
            if (focoNaEntrada) focoDoTeclado = BOTAO_DA_ACAO.left;
            startFetching();
            esvaziarFilaDeSaida();   // o que ficou esperando a sessão sai agora
            fim(true);
        }
        window.addEventListener('message', ouvir);
        // A `espera` vai junto: é o prazo de quem pergunta, e o login da extensão
        // (desde a 0.3.4) acaba antes dele, com folga pra resposta voltar. Sem
        // prazo, a extensão seguia indo ao Waze no nome da pessoa depois de o app
        // desistir, e a sessão que dava certo chegava a esta página já sem
        // ouvinte — sem dono no servidor (auditoria da rodada 9, R9-1-02 =
        // R9-6-02). A extensão de antes ignora o campo.
        try {
            window.postMessage({ source: 'wazeplaces', action: 'precisa-de-sessao', espera: EXT_ESPERA_MS }, window.location.origin);
        } catch (e) { fim(false); }
    });
}

// A recusa que a extensão repassou, copiada CAMPO A CAMPO, com tipo e teto: ela
// chega por `postMessage`, e nada do outro lado entra cru no diálogo. Sai no
// MESMO formato da resposta do `testar-cookies`, que é o que o
// `showAccessDenied` já sabe mostrar.
function negadoDaExtensao(n) {
    const o = n && typeof n === 'object' ? n : {};
    const p = o.profile && typeof o.profile === 'object' ? o.profile : null;
    const vars = {};
    if (o.errorVars && typeof o.errorVars === 'object') {
        for (const [k, v] of Object.entries(o.errorVars)) {
            if (!/^[A-Za-z]{1,24}$/.test(k)) continue;
            if (Number.isFinite(v)) vars[k] = v;
            else if (typeof v === 'string') vars[k] = v.slice(0, 40);
        }
    }
    return {
        success: false,
        errorCategory: 'access_denied',
        errorKey: typeof o.errorKey === 'string' && /^srv\.err\.[A-Za-z]+$/.test(o.errorKey) ? o.errorKey : undefined,
        errorVars: vars,
        error: typeof o.error === 'string' ? o.error.slice(0, 300) : undefined,
        profile: p && typeof p.userName === 'string' && p.userName ? {
            userName: p.userName.slice(0, 64),
            rank: Number.isInteger(p.rank) ? p.rank : null,
            isAreaManager: p.isAreaManager === true,
            isStaff: p.isStaff === true,
        } : null,
    };
}

// Quem mostra a recusa, consome: o diálogo sai UMA vez por pergunta.
function tirarNegadoDaExtensao() {
    const r = extNegado;
    extNegado = null;
    return r;
}

// Menos com TEXTO DIGITADO num diálogo da entrada (o cookies.txt colado, o
// código): a pessoa está entrando por ali — talvez com OUTRA conta —, e o
// "Acesso restrito" abria por cima, escondendo o diálogo dela com a limpeza (o
// que estava colado ia embora). A pergunta da volta é silenciosa e deixa a tela
// de entrada usável enquanto corre, e a recusa que chegava depois do colar
// apagava o texto (auditoria da rodada 13, R13-1-05, MEDIDO). Sem o diálogo, a
// marca da página volta: ela quer dizer "a pessoa já viu o motivo", e ela não
// viu — a próxima volta à aba, sem nada digitado, pergunta de novo e o mostra.
function mostrarNegadoDaExtensao() {
    const r = tirarNegadoDaExtensao();
    if (!r) return;
    if (textoDigitadoNaEntrada()) { extNegadoNestaPagina = false; return; }
    showAccessDenied(r);
}

// Todo login que DEU CERTO começa um ciclo novo NESTA página. As duas marcas de
// "não pergunte de novo à extensão ao voltar à aba" — o "Sair" deliberado e a
// recusa do portão — são do ciclo anterior. O `saiuNestaPagina` nunca voltava a
// falso: quem saía e entrava de novo na mesma página, se a sessão caísse depois,
// não era mais relogado pela extensão ao voltar à aba (auditoria de 2026-09-26).
function aoEntrarNestaPagina() {
    saiuNestaPagina = false;
    extNegadoNestaPagina = false;
    extNegado = null;
}

// Ao LIGAR esconde a tela de login e mostra o spinner. Ao desligar, esconde só
// o spinner — quem decide se a tela de login volta é o CHAMADOR, que sabe se o
// handshake deu certo. A primeira versão fazia o `toggle` nos dois no mesmo
// lugar e, ao terminar com sucesso, re-exibia o "Bem-vindo!" por cima do app já
// logado. Só apareceu com a extensão carregada de verdade.
function mostrarEntrandoPelaExtensao(ligado) {
    document.getElementById('extLoginState')?.classList.toggle('hidden', !ligado);
    if (ligado) document.getElementById('authScreen')?.classList.add('hidden');
}

// ── Gerenciador de modais ─────────────────────────────────────────────────
// Todos os diálogos (role="dialog") passam por aqui: foco entra no modal ao
// abrir e volta pro elemento de origem ao fechar; Esc fecha o modal aberto
// (via handleKeyDown); clique no scrim fecha; body trava o scroll.
// Novo modal? Adicionar o id em MODAL_IDS e usar openModal/closeModal.
const MODAL_IDS = ['pasteModal', 'logoutModal', 'accessDeniedModal', 'filtersModal', 'helpModal', 'batchReadModal', 'pairShowModal', 'pairEnterModal', 'comoFuncionaModal', 'treinoFimModal', 'presencaModal', 'conversaModal', 'pedidoModal', 'autorModal', 'resumoModal'];

// Os modais que só existem na tela de ENTRADA. Quem entra pela extensão entra
// "de fora" — em silêncio, sem tocar em nada desta tela (ao voltar à aba, por
// exemplo) —, e o que estava aberto nela tem que sair pelo `closeModal`, que
// roda a limpeza de cada um. Sem isto o "Como funciona" da primeira vez os
// escondia por cima sem limpar, e o cookies.txt colado — o chaveiro do
// navegador inteiro — ficava no campo escondido e sobrevivia ao "Sair": a
// pessoa seguinte abria "Colar" e o encontrava (auditoria de 2026-09-26).
const MODAIS_DA_ENTRADA = ['pasteModal', 'pairEnterModal', 'accessDeniedModal'];

// `focoComDestino`: o foco que estava na tela de entrada já foi prometido ao ✕
// do primeiro card (R10-1-05), e o fechamento não o devolve a quem abriu o
// diálogo — o "Acesso restrito" que o app abriu sozinho o devolvia ao ⓘ do topo.
function fecharModaisDaEntrada({ focoComDestino = false } = {}) {
    // Só os abertos: o `closeModal` anota no diário antes de conferir, e três
    // "fechou" de modal que nem estava aberto contariam uma história falsa.
    for (const id of MODAIS_DA_ENTRADA) {
        const m = document.getElementById(id);
        if (m && !m.classList.contains('hidden')) closeModal(id, { focoComDestino });
    }
}

let lastFocusedBeforeModal = null;

// ── O VOLTAR do aparelho fecha o que está por cima ────────────────────────
// Pedido de uma editora: no ritmo do swipe, ir até o ✕ do lightbox quebra a
// cadência. No Android o reflexo é o botão/gesto de voltar, que em todo app
// nativo significa "fecha a camada de cima".
//
// Vale pra lightbox E pra modais de propósito. Fazer só na foto seria PIOR que
// não fazer: a pessoa aprenderia que voltar fecha, tentaria em Filtros e SAIRIA
// DO APP — e ainda perderia os filtros que estava montando.
//
// O detalhe que decide se isto ajuda ou atrapalha é CONSUMIR a entrada quando a
// camada fecha por outro caminho (✕, Esc, scrim, arrastar). Sem isso sobra uma
// entrada morta no histórico e o próximo voltar não faz nada — o usuário aperta,
// olha pra tela parada e aperta de novo, aí sai do app. Pior que o ✕.
//
// iOS em modo standalone não tem voltar; lá o ✕ e o arrastar pra baixo seguem
// sendo o caminho. Isto ADICIONA um jeito, não substitui nenhum.
const CamadaVoltar = {
    profundidade: 0,
    // Ligado só durante o history.back() que nós mesmos disparamos, pra o
    // popstate resultante não fechar uma segunda camada por engano.
    consumindo: false,

    empilhar() {
        try {
            this.profundidade++;
            history.pushState({ wpCamada: this.profundidade }, '');
        } catch (e) { /* histórico indisponível: o ✕ continua funcionando */ }
    },

    consumir() {
        if (this.profundidade <= 0) return;
        this.profundidade--;
        this.consumindo = true;
        try { history.back(); } catch (e) { this.consumindo = false; }
    },
};

window.addEventListener('popstate', () => {
    if (CamadaVoltar.consumindo) { CamadaVoltar.consumindo = false; return; }
    // O mapa ampliado é a camada de cima: o voltar do aparelho fecha ELE
    // primeiro, como faz com o lightbox de foto.
    if (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()) {
        CamadaVoltar.profundidade = Math.max(0, CamadaVoltar.profundidade - 1);
        MapaLightbox.close(true);
        return;
    }
    // Veio do usuário. Fecha a camada de cima — o lightbox está acima dos modais
    // (z-[65] contra z-[60]), então ele tem prioridade.
    if (Lightbox.isOpen()) {
        CamadaVoltar.profundidade = Math.max(0, CamadaVoltar.profundidade - 1);
        Lightbox.close({ viaHistorico: true });
        return;
    }
    const m = topOpenModal();
    if (m) {
        CamadaVoltar.profundidade = Math.max(0, CamadaVoltar.profundidade - 1);
        closeModal(m.id, { viaHistorico: true });
    }
});

function openModal(id) {
    dfato('tela.modal', { abre: id });
    const m = document.getElementById(id);
    if (!m) return;
    const jaHaviaModal = !!topOpenModal();
    // Modais não empilham: fecha qualquer outro aberto (ex.: Sair a partir da Ajuda).
    //
    // E o que sai da tela aqui FECHOU, pra todos os efeitos: a limpeza dele
    // roda, como em qualquer outro caminho de fechamento. Só esconder deixava o
    // estado do modal de baixo vazando — a escada aberta e a conquista tocada
    // do Histórico voltavam na próxima abertura de Filtros depois do Resumo do
    // mês, e a conversa escondida pelo pedido que chegou nela seguia "aberta"
    // (auditoria de 2026-09-25).
    //
    // A limpeza é chamada DIRETO, nunca pelo `closeModal`: ele agenda um
    // `history.back()` e o empilhar logo abaixo seria comido por ele — o voltar
    // do aparelho passaria a tirar a pessoa do app (gotcha #65). Trocar de modal
    // é a MESMA camada.
    MODAL_IDS.forEach(other => {
        if (other === id) return;
        const o = document.getElementById(other);
        if (!o || o.classList.contains('hidden')) return;
        o.classList.add('hidden');
        try { LIMPEZA_AO_FECHAR[other]?.(); } catch (e) { /* limpeza nunca derruba a abertura */ }
    });
    // Empilha uma entrada só por CAMADA, não por modal: openModal fecha o modal
    // anterior antes de abrir o novo (eles não empilham), então trocar de modal
    // não pode empilhar histórico — senão um voltar fecharia nada.
    if (!jaHaviaModal) CamadaVoltar.empilhar();
    // O foco volta, no fechamento, pra quem abriu a CAMADA. Trocando de modal, o
    // elemento focado agora é um botão DO MODAL QUE ACABOU DE SUMIR (o "Resumo
    // do mês" dentro de Filtros): devolver o foco a ele não pega — está
    // escondido — e o foco caía no `<body>`, perdido pra quem usa teclado ou
    // leitor de tela. Quem abriu Filtros (o botão do cabeçalho) continua na tela.
    if (!jaHaviaModal) lastFocusedBeforeModal = document.activeElement;
    m.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    const focusable = m.querySelector('textarea, input:not([type=hidden]):not(:disabled), select, button');
    if (focusable) focusable.focus();
}

// Limpeza específica de cada modal. Fica AQUI e não no botão de fechar porque
// modal fecha por três caminhos — botão, Esc e clique no scrim — e amarrar a
// limpeza a um deles deixa os outros dois vazando. Foi o que aconteceu com o
// ticker do pareamento: fechando por Esc, o setInterval seguia rodando pelo
// resto da sessão.
const LIMPEZA_AO_FECHAR = {
    // A imagem do Resumo é um object URL: solta a memória e o blob por
    // qualquer caminho de fechamento (✕, Esc, scrim, voltar).
    resumoModal() {
        resumoAtual = null;
        const img = document.getElementById('resumoImg');
        if (img && img.src) { try { URL.revokeObjectURL(img.src); } catch (e) {} img.removeAttribute('src'); }
    },
    // O padrão da lista de autores é a forma CURTA. Amarrar isto ao botão de
    // fechar deixaria os outros dois caminhos (Esc e scrim) vazando o estado
    // expandido pra próxima abertura — o gotcha dos modais deste projeto.
    filtersModal() {
        autoresExpandido = false; escadaAberta = false; conquistaTocada = null; novasDestaAbertura = null;
        // A lista de autores que você rejeitou — nome e id de TERCEIRO — não fica
        // no DOM do painel fechado (a próxima abertura a desenha de novo): ela
        // ficava depois do "Sair", e a próxima conta que ligasse o modo dev na
        // mesma página a levava no relatório (auditoria de 2026-10-02, R6-1-05).
        // Nem o resto do painel do Histórico: a patente, os totais e o Resumo do
        // mês de quem estava (R8-7-06).
        esvaziarPainelDoHistorico();
        // Nem as áreas gerenciadas da conta, no seletor da aba Filtros (R11-1-05).
        esvaziarSeletorDeAreas();
    },
    // A folha do autor: o nome dele e as linhas com a contagem (R6-1-05).
    autorModal() {
        const titulo = document.getElementById('autorTitle');
        if (titulo) titulo.textContent = '';
        const corpo = document.getElementById('autorCorpo');
        if (corpo) corpo.innerHTML = '';
    },
    // O "Acesso restrito": o nome, o nível e a área de quem o portão recusou
    // ficavam no diálogo fechado, na tela de entrada (R6-1-05).
    accessDeniedModal() {
        const perfil = document.getElementById('accessDeniedProfile');
        if (perfil) { perfil.innerHTML = ''; perfil.classList.add('hidden'); }
    },
    pairShowModal() {
        // A resposta de um pedido de código que ainda voava é de um diálogo que
        // fechou: não escreve nada, e o código que ela trouxer é cancelado
        // (`pareamentoTardio`, R6-1-09).
        aberturaDoPareamento++;
        pararTickerPareamento();
        // O código é credencial e já não vale nada aqui: não fica desenhado
        // esperando alguém reabrir o modal e escanear um QR morto.
        const code = document.getElementById('pairCode');
        if (code) {
            code.textContent = '······';
            delete code.dataset.raw;
            delete code.dataset.curto;
            code.classList.remove('opacity-40', 'line-through');
        }
        for (const id of ['pairExpiry', 'pairCodeExpiry']) {
            const el = document.getElementById(id);
            if (el) el.textContent = '';
        }
        // O código revelado volta a ficar escondido: revelar é um pedido, e cada
        // pedido cria um registro fraco novo no servidor. Herdar o estado da vez
        // passada faria a próxima abertura já nascer com a cópia fraca à mostra.
        document.getElementById('pairCodeReveal')?.classList.add('hidden');
        const btnCodigo = document.getElementById('pairShowCodeBtn');
        if (btnCodigo) { btnCodigo.classList.remove('hidden'); btnCodigo.disabled = false; }
        // As instruções que o vencimento escondeu voltam pra próxima abertura.
        mostrarInstrucoesDoPareamento();
        limparQrPareamento();
        pairQrVenceEm = 0;
        const copiar = document.getElementById('pairCopyLinkBtn');
        if (copiar) copiar.disabled = true;
    },
    conversaModal() {
        // Fechar a conversa por QUALQUER caminho (✕, Esc, scrim, voltar) tem
        // que soltar o `aberta` — senão a próxima mensagem daquela pessoa
        // continua chegando como "conversa aberta" e nunca vira aviso.
        window.Presenca?.esquecerAberta?.();
    },
    // Fechada, a lista não fica no DOM: a captura do diagnóstico (que leva o
    // DOM inteiro) mostra o que estava NA TELA, não uma lista velha escondida.
    presencaModal() { window.Presenca?.esquecerLista?.(); },
    // A folha do pedido que CHEGOU pela conversa: o nome do local, de quem
    // veio, o endereço, a foto e o link são de TERCEIRO, e ficavam no DOM depois
    // de fechar — e depois do "Sair", que passa por aqui (o `Presenca.desligar`
    // fecha a folha pelo `closeModal`, e abrir outro modal a esconde com esta
    // limpeza). A próxima abertura preenche tudo de novo (`abrirPedidoRecebido`).
    pedidoModal() {
        for (const id of ['pedidoNome', 'pedidoDe', 'pedidoTipo', 'pedidoCat', 'pedidoEnd']) {
            const el = document.getElementById(id);
            if (el) el.textContent = '';
        }
        for (const id of ['pedidoTipoRow', 'pedidoCatRow', 'pedidoEndRow', 'pedidoFoto']) {
            document.getElementById(id)?.classList.add('hidden');
        }
        const img = document.getElementById('pedidoFotoImg');
        if (img) { img.onerror = null; img.removeAttribute('src'); }
        document.getElementById('pedidoWme')?.removeAttribute('href');
    },
    pairEnterModal() {
        const campo = document.getElementById('pairCodeInput');
        if (campo) campo.value = '';
        document.getElementById('pairEnterError')?.classList.add('hidden');
    },
    // O `cookies.txt` colado é o CHAVEIRO do navegador inteiro (medido no do
    // owner: 4.370 cookies de 362 domínios). Só o ✕ Cancelar e o Entrar o
    // limpavam: fechado por Esc, pelo fundo ou pelo voltar, ele ficava no campo —
    // e depois do "Sair", num aparelho compartilhado, a pessoa seguinte reabria
    // e lia tudo (auditoria de 2026-09-25).
    pasteModal() {
        const campo = document.getElementById('cookiesTextarea');
        if (campo) campo.value = '';
    },
    // O fim do treino fecha pelos mesmos quatro caminhos, e só o "Ir para a
    // fila" saía do treino: por Esc, pelo fundo ou pelo voltar do aparelho
    // ficavam o card de TREINO já tratado na tela, "Restam 0" e os botões
    // mortos, com a fila real guardada por baixo (auditoria de 2026-09-29, A5).
    // Sair mora aqui pra valer nos quatro; o botão só fecha o modal.
    //
    // Pelo TECLADO (o Enter no "Ir para a fila", o Esc), o foco vai ao ✕ do card
    // que volta — ou ao botão do painel do fim, quando não volta card —, a régua
    // do "Sair" da faixa (`prometerFocoAoCardQueVem`). O fechamento o devolvia a
    // quem abriu o modal, o ✓ do último card de TREINO, que saiu junto: caía no
    // ⓘ do topo, e quem usa teclado ou leitor de tela recomeçava da Ajuda
    // (R8-7-07, MEDIDO nos dois motores; auditoria de 2026-10-03). Prometido
    // ANTES do `sair()`, que monta o card e agenda o foco prometido; o `true`
    // diz ao `closeModal` que o foco já tem destino. Pelo mouse, pelo dedo, pelo
    // fundo e pelo voltar, nada muda.
    treinoFimModal({ peloTeclado = false } = {}) {
        if (peloTeclado) focoDoTeclado = BOTAO_DA_ACAO.left;
        Treino.sair();
        return peloTeclado;
    },
    // O "Como funciona" explica os três botões do CARD. Fechado pelo TECLADO (o
    // Enter no "Entendi", o Esc), o foco vai ao ✕ do card na tela — o que diz a
    // frase publicada ("pelo teclado, fechar o 'Como funciona' devolve o foco
    // ao ✕ do pedido, e não ao botão da Ajuda") e o que o "Quero treinar antes"
    // já faz (R9-7-03). Ela só valia no diálogo ADIADO, em que quem abriu era o
    // ✕: no que abre SOZINHO no 1º card, quem abriu é o <body>, o fechamento
    // caía na reserva — o ⓘ do topo — e o Enter seguinte reabria a Ajuda
    // (R10-7-03, MEDIDO no navegador; auditoria de 2026-10-07). O card já está
    // na tela: o foco prometido pousa logo depois do fechamento, e espera a
    // trava acabar, se houver (`aplicarFocoDoTeclado`). Sem card, ele volta a
    // quem abriu, como sempre; pelo mouse, pelo dedo, pelo fundo e pelo voltar,
    // nada muda.
    comoFuncionaModal({ peloTeclado = false } = {}) {
        if (!peloTeclado || !cardDaFrente()) return false;
        focoDoTeclado = BOTAO_DA_ACAO.left;
        queueMicrotask(aplicarFocoDoTeclado);
        return true;
    },
};

function closeModal(id, { viaHistorico = false, peloTeclado = false, focoComDestino = false } = {}) {
    dfato('tela.modal', { fecha: id, viaHistorico });
    const m = document.getElementById(id);
    if (!m || m.classList.contains('hidden')) return;
    m.classList.add('hidden');
    if (!viaHistorico) CamadaVoltar.consumir();
    // A limpeza sabe se o fechamento veio do TECLADO (o Esc, o Enter no botão
    // que fecha) e devolve `true` quando ela mesma deu destino ao foco (o fim do
    // treino, R8-7-07): aí ele não volta a quem abriu. Quem FECHA também pode
    // dizer isso (`focoComDestino`): o "Quero treinar antes" pelo teclado, que
    // prometeu o foco ao ✕ do card de treino (R9-7-03).
    try { if (LIMPEZA_AO_FECHAR[id]?.({ peloTeclado }) === true) focoComDestino = true; } catch (e) { /* limpeza nunca derruba o fechamento */ }
    if (!topOpenModal() && !Lightbox.isOpen()) document.body.style.overflow = '';
    const alvo = lastFocusedBeforeModal;
    lastFocusedBeforeModal = null;
    if (!focoComDestino) devolverFoco(alvo);
    // O "Como funciona" que esperava a camada fechar (R6-7-2, R7-7-01).
    aoFecharCamada(viaHistorico);
}

// Pra onde o foco volta quando um modal fecha. Primeiro, quem o abriu — mas ele
// pode ter sumido junto com OUTRO modal: a Ajuda abre o "Conectar outro
// aparelho" e o "Sair", o `openModal` esconde a Ajuda, e o botão de dentro dela
// fica escondido. `focus()` num elemento escondido não faz nada, e o foco caía
// no BODY — quem navega pelo teclado recomeçava do topo da página (auditoria de
// 2026-09-26, medido fechando o pareamento com Esc e saindo pelo teclado).
// Aí vale o último foco que houve FORA das camadas (quem abriu a Ajuda) e, por
// fim, o botão da Ajuda, que existe na tela de entrada e na dos cards.
let ultimoFocoForaDasCamadas = null;

function dentroDeCamada(el) {
    return !!(el && el.closest && el.closest('[role="dialog"]'));
}

function focavelNaTela(el) {
    return !!(el && el.isConnected && typeof el.focus === 'function' && !el.disabled
        && el.getClientRects && el.getClientRects().length > 0);
}

function devolverFoco(alvo) {
    const reserva = focavelNaTela(ultimoFocoForaDasCamadas) && !dentroDeCamada(ultimoFocoForaDasCamadas)
        ? ultimoFocoForaDasCamadas : null;
    for (const el of [alvo, reserva, document.getElementById('helpBtn')]) {
        // O <body> (ou a raiz) não é alvo: é o foco PERDIDO. O modal que o app
        // abre sozinho — o "Acesso restrito" do login (o botão que entrou fica
        // `disabled` durante a validação), o da recusa na abertura, o "Como
        // funciona" da primeira vez — nasce com o foco no <body>, e o
        // `focavelNaTela` o aceita: fechar devolvia o foco pra lá, e quem usa
        // teclado ou leitor de tela recomeçava do topo (auditoria de
        // 2026-10-02, R6-1-07). Cai na reserva e no ⓘ da Ajuda, como o
        // `fecharCamadasAbertas` já fazia.
        if (el === document.body || el === document.documentElement) continue;
        if (focavelNaTela(el)) { el.focus(); return; }
    }
}

function topOpenModal() {
    for (const id of MODAL_IDS) {
        const m = document.getElementById(id);
        if (m && !m.classList.contains('hidden')) return m;
    }
    return null;
}

function setupAuthListeners() {
    const $ = id => document.getElementById(id);

    // O seletor de arquivo é do SISTEMA, e o `change` que ele dispara não diz
    // como ele foi aberto: o TECLADO se lê aqui, no toque que o abre (ver
    // `arquivoPeloTeclado`).
    $('uploadBtn').addEventListener('click', (ev) => {
        arquivoPeloTeclado = veioDoTeclado(ev);
        $('fileInput').click();
    });
    $('fileInput').addEventListener('change', handleFileUpload);
    $('pasteBtn').addEventListener('click', () => openModal('pasteModal'));
    $('confirmPaste').addEventListener('click', handlePasteConfirm);
    // A limpeza do campo mora no `LIMPEZA_AO_FECHAR` (vale pros quatro caminhos).
    $('cancelPaste').addEventListener('click', () => closeModal('pasteModal'));
    $('byAuthor').addEventListener('click', () => {
        window.open('https://www.waze.com/user/editor/antigerme', '_blank', 'noopener');
    });
    $('closeAccessDenied').addEventListener('click', () => closeModal('accessDeniedModal'));
    // Região default sempre 'row' pra fluxos novos (público alvo BR/Latam).
    // Quem precisa de NA/IL/world muda no modal "Filtros e Preferências"
    // depois de logar (filterRegion). Não exibimos picker no authScreen
    // porque era fricção desnecessária pra 95% dos usuários.
}

function setupAppListeners() {
    const $ = id => document.getElementById(id);

    // openModal fecha o helpModal automaticamente (modais não empilham)
    $('logoutBtn').addEventListener('click', () => {
        desenharAvisoDoSair();   // quantas decisões o "Sair" descarta, se houver
        openModal('logoutModal');
    });
    // Sem o evento: o `handleLogout` lê o 1º argumento como opções.
    $('confirmLogout').addEventListener('click', () => handleLogout());
    $('cancelLogout').addEventListener('click', () => closeModal('logoutModal'));

    // "Verificar novamente" e "Tentar de novo" somem com o painel quando o
    // card volta, com o foco neles: pelo teclado, o foco vai ao card que chega
    // (`prometerFocoAoCardQueVem`, R6-2-13).
    $('reloadBtn').addEventListener('click', (ev) => {
        prometerFocoAoCardQueVem(ev);
        resetQueue();
        startFetching();
    });
    $('refreshBtn').addEventListener('click', () => {
        if (AppState.fetching) return;
        // Sem rede, "atualizar" só jogava fora a fila (inclusive a guardada do
        // offline, que só voltava fechando e reabrindo o app): fica a de agora.
        if (navigator.onLine === false) { showToast(t('states.error.titleOffline'), 'info'); return; }
        // Com o treino aberto, o aviso do país que espera o "Sair" dele (R10-7-02).
        const avisoDoTreino = Treino.avisoDoPaisAnotado();
        resetQueue();
        startFetching();
        showToast(t('toast.refreshing'), 'info');
        avisarPaisDoTreinoEncerrado(avisoDoTreino);
    });
    $('retryLoadBtn')?.addEventListener('click', async (ev) => {
        // Antes do `await`: depois dele o evento já não diz quem tinha o foco.
        prometerFocoAoCardQueVem(ev);
        // Sem rede — ou com a última busca tendo falhado por rede ou pelo
        // servidor (o "lie-fi", a origem fora do ar), com o `onLine` dizendo que
        // há rede — e com o "Disponível offline": a fila guardada, que antes só
        // voltava fechando e reabrindo o app (e, com o `onLine` verdadeiro, nem
        // assim: auditoria de 2026-09-29, O1).
        if (await offlineTentarAbrirSemRede(ultimaBuscaFalhouPorRede)) return;
        retomarBusca();
    });
    $('diagBtn')?.addEventListener('click', baixarDiagnostico);
    $('helpBtn').addEventListener('click', () => openModal('helpModal'));
    $('presencaClose').addEventListener('click', () => closeModal('presencaModal'));
    $('pedidoClose').addEventListener('click', () => closeModal('pedidoModal'));
    $('filterSort')?.addEventListener('change', aoTrocarOrdenacao);
    $('resumoClose')?.addEventListener('click', () => closeModal('resumoModal'));
    $('resumoCompartilhar')?.addEventListener('click', compartilharResumo);
    $('resumoBaixar')?.addEventListener('click', baixarResumo);
    $('autorClose').addEventListener('click', () => closeModal('autorModal'));
    $('conversaClose').addEventListener('click', () => Presenca.fecharConversa());
    // O resto da presença (pílula, lista, envio) se liga sozinho: `montar` é do
    // js/presenca.js, que carrega depois deste arquivo.
    window.Presenca?.montar?.();
    $('closeHelp').addEventListener('click', () => closeModal('helpModal'));
    // Despacha a janela do Desfazer antes de abrir (R12-7-03, ver a função).
    $('reverComoFunciona')?.addEventListener('click', verDeNovoComoFunciona);
    // Só fecha: o foco de quem usa o TECLADO é da limpeza do modal, que vale
    // também pro Esc (`LIMPEZA_AO_FECHAR.comoFuncionaModal`, R10-7-03).
    $('comoFuncionaOk')?.addEventListener('click', (ev) => closeModal('comoFuncionaModal', { peloTeclado: veioDoTeclado(ev) }));
    // O treino pedido por um diálogo que o `Treino.entrar` vai RECUSAR — sem
    // sessão (a renovação silenciosa pela extensão), com o "Marcar todos" ou a
    // aprovação de uma foto no ar: diz o que esperar e o diálogo fica
    // (`recusarTreino`, R8-7-09, R9-7-07). E o "Quero treinar antes" pelo
    // TECLADO: o foco vai ao ✕ do card de treino, como no "Sair" da faixa
    // (`prometerFocoAoCardQueVem`), prometido ANTES de fechar: depois do
    // fechamento, o evento já não diz quem tinha o foco (R8-7-08). E o
    // fechamento NÃO o devolve a quem abriu (`focoComDestino`): no "Como
    // funciona" que abre SOZINHO no 1º card, quem abriu é o <body>, a reserva é
    // o ⓘ do topo — um controle VIVO, e o foco prometido desistia dele. O
    // teclado caía no ⓘ, e o Enter seguinte reabria a Ajuda (R9-7-03, MEDIDO
    // nos dois motores; auditoria de 2026-10-06). No adiado, o fechamento o
    // devolvia ao ✕ do card real, que saía com o `Treino.entrar`: só ali dava
    // certo. Já DENTRO do treino (o "Ver de novo" da Ajuda), o `entrar` não troca
    // o card: o fechamento devolve o foco a quem abriu, como sempre — sem isso
    // ele ficava no botão escondido.
    $('comoFuncionaTreinar')?.addEventListener('click', (ev) => {
        if (recusarTreino()) return;
        const focoNoCardDeTreino = veioDoTeclado(ev) && !Treino.ativo;
        prometerFocoAoCardQueVem(ev);
        closeModal('comoFuncionaModal', { focoComDestino: focoNoCardDeTreino });
        Treino.entrar();
    });
    // O "Praticar" (na Ajuda) pelo TECLADO, a MESMA regra do "Quero treinar
    // antes": o foco vai ao ✕ do primeiro card de treino. O fechamento o
    // devolvia a quem abriu a Ajuda — o ⓘ do topo —, e o Enter seguinte reabria
    // a Ajuda: os dois botões que abrem o treino levavam o foco a lugares
    // diferentes (R10-7-04, MEDIDO no navegador; auditoria de 2026-10-07). O
    // recusado (`recusarTreino`) sai antes de prometer: a Ajuda fica, e o foco
    // fica no "Praticar". Já dentro do treino, o fechamento devolve o foco a
    // quem abriu, como no "Quero treinar antes".
    $('abrirTreino')?.addEventListener('click', (ev) => {
        if (recusarTreino()) return;
        const focoNoCardDeTreino = veioDoTeclado(ev) && !Treino.ativo;
        prometerFocoAoCardQueVem(ev);
        closeModal('helpModal', { focoComDestino: focoNoCardDeTreino });
        Treino.entrar();
    });
    // O "Sair" some com a faixa do treino, e o card real volta: pelo teclado, o
    // foco caía no <body> (R7-2-06, MEDIDO nos dois motores; auditoria de
    // 2026-10-02). Ele vai ao ✕ do card que volta, a regra do C10 pra todo
    // controle que some com o foco (`prometerFocoAoCardQueVem`); com o mouse e
    // o dedo, nada se move.
    $('treinoSairBtn')?.addEventListener('click', (ev) => {
        prometerFocoAoCardQueVem(ev);
        Treino.sair();
    });
    // Só fecha: quem sai do treino é a limpeza do modal (`LIMPEZA_AO_FECHAR`),
    // que vale também pro Esc, o fundo e o voltar. O fechamento leva junto se o
    // gesto veio do TECLADO: aí a limpeza leva o foco ao card que volta (R8-7-07).
    $('treinoFimOk')?.addEventListener('click', (ev) => closeModal('treinoFimModal', { peloTeclado: veioDoTeclado(ev) }));

    // "Instalei… e agora?" — o beco sem saída medido: o app pergunta à extensão
    // UMA vez, no carregamento, com 350ms de janela, e o `ponte.js` não é
    // injetado numa aba que já estava aberta. Quem instala olhando pra esta tela
    // fica aqui pra sempre. Aparece só DEPOIS do clique em instalar, pra não ser
    // ruído pra quem nem foi à loja.
    $('extInstallLink')?.addEventListener('click', () => {
        const b = $('extJaInstalei');
        if (!b) return;
        b.hidden = false;
        b.classList.replace('hidden', 'flex');
    });
    $('extJaInstalei')?.addEventListener('click', () => window.location.reload());

    // E ao voltar pra esta aba, na tela de entrada: a sessão que outra aba
    // guardou entra (em TODO aparelho), e sem ela a extensão é perguntada de
    // novo, em silêncio, onde ela instala (ver `aoVoltarAAba`). A pergunta cobre
    // quem recarregou noutro lugar ou reabriu o WME; quando a extensão passar a
    // se injetar nas abas abertas (onInstalled + scripting, versão futura dela),
    // este mesmo caminho resolve a instalação sem toque nenhum e o botão acima
    // deixa de ser necessário.
    document.addEventListener('visibilitychange', aoVoltarAAba);
    // E com o Histórico aberto: o que destravou com a página no fundo fica
    // visto na volta (`verConquistasAoVoltar`, R12-7-01).
    document.addEventListener('visibilitychange', verConquistasAoVoltar);
    // E o aviso de UMA vez que saiu com a página no fundo espera a volta
    // (`avisosAdiadosAoVoltar`, R13-7-01).
    document.addEventListener('visibilitychange', avisosAdiadosAoVoltar);
    $('themeBtn').addEventListener('click', toggleTheme);
    $('filtersBtn').addEventListener('click', () => {
        // O ponto aceso é o MOTIVO do toque: leva direto ao que destravou, como
        // o aviso do Desfazer já fazia. Sem ponto, o botão faz o que promete.
        //
        // Isso acontece NO MÁXIMO uma vez por conquista, e por CONSTRUÇÃO, não
        // por regra escrita: abrir a aba Histórico apaga o ponto (o
        // `marcarConquistasVistas` do `switchFilterTab`), então o próximo toque
        // já cai em Filtros. Medido com o app de pé, não deduzido — eu cheguei a
        // recusar este desvio achando que ele se repetiria por dias.
        //
        // O atalho do PWA (`/?action=filters`) NÃO passa por aqui de propósito:
        // ali a pessoa escolheu "Filtros" num menu, e o pedido é explícito.
        if (temConquistaNova()) abrirConquistaNova();
        else openFiltersModal();
    });

    // Clique no scrim fecha o modal (padrão M3/HIG pra diálogos dispensáveis)
    MODAL_IDS.forEach(id => {
        const m = $(id);
        if (m) m.addEventListener('click', (e) => { if (e.target === m) closeModal(id); });
    });

    window.addEventListener('keydown', handleKeyDown);
    // Quem pegou o mouse ou o dedo deixou de operar pelo teclado: o foco
    // prometido ao teclado (`focoDoTeclado`, C10) não vale mais.
    window.addEventListener('pointerdown', () => { focoDoTeclado = null; }, true);
}

// A VOLTA a esta aba (o `visibilitychange`; o ouvinte mora no
// `setupAppListeners`), em TODO aparelho. Na tela de entrada, sem sessão na
// memória: a sessão que OUTRA aba guardou no aparelho é adotada, como na
// abertura (`adotarSessaoDoAparelho`); sem nenhuma, a extensão é perguntada em
// silêncio — só onde ela instala: no celular seria uma espera de 350 ms por
// nada, a cada troca de aba. O ouvinte inteiro morava só onde a extensão
// instala, e a volta ADOTAVA em caso nenhum: a pessoa entrava pela outra aba,
// voltava a esta e seguia no "Bem-vindo!" até recarregar (auditoria da rodada
// 10, R10-1-03, MEDIDO no Chromium e decidido como o R9-1-03).
function aoVoltarAAba() {
    if (document.visibilityState !== 'visible') return;
    if (document.getElementById('authScreen')?.classList.contains('hidden')) return;
    if (adotarSessaoDoAparelho()) return;
    if (podeInstalarExtensao()) perguntarAExtensaoAoVoltar();
}

// A volta a esta aba na TELA DE ENTRADA pergunta à extensão, em silêncio (onde
// ela instala: ver `aoVoltarAAba`).
function perguntarAExtensaoAoVoltar() {
    if (document.visibilityState !== 'visible') return;
    // Quem deu "Sair" NESTA página não é relogado por trocar de aba:
    // era o que acontecia — sair, ir ao WME e voltar entrava de novo
    // sozinho. Recarregar a página (ou tocar em entrar) começa do zero.
    if (saiuNestaPagina) return;
    // E quem o portão recusou pela extensão já viu o motivo: perguntar
    // de novo a cada volta à aba era uma ida ao Waze e um diálogo a mais
    // por troca de aba, com a mesma resposta.
    if (extNegadoNestaPagina) return;
    // Com sessão não pergunta: a DESTA aba (a memória) ou a que OUTRA aba
    // guardou no aparelho — a pergunta traria uma sessão nova por cima dela,
    // com mais uma ida ao Waze no nome da pessoa. O aparelho se lê SEM o
    // `getSession`, que com a memória vazia GRAVAVA nela a sessão da outra
    // aba: esta, que nunca entrou, passava a contar como logada, e o "Sair"
    // dado lá a encerrava junto — o "Colar cookies" aberto fechava, apagando o
    // que estava sendo colado, e o aviso dizia "Você saiu em outra aba" a quem
    // nem tinha entrado (auditoria de 2026-10-06, R9-1-03).
    if (AppState.authenticated || API.temSessaoNaMemoria() || safeLS.get('waze_session_token')) return;
    // Nem com um login DESTA aba no ar (os cookies sendo conferidos, o código ou
    // o link sendo resgatado): o fim dele decide, como na adoção
    // (`adotarSessaoDoAparelho`). A pergunta trazia uma sessão NOVA por cima do
    // login que a pessoa pediu — duas sessões no servidor, e o "Sair" apagava só
    // a última (auditoria da rodada 11, R11-1-03, MEDIDO).
    if (authInFlight || resgateEmVoo) return;
    // Nem com TEXTO DIGITADO num diálogo da entrada (o cookies.txt colado, o
    // código): a pessoa estava entrando por ali — talvez com OUTRA conta —, a
    // MESMA régua da adoção (`adotarSessaoDoAparelho`). A adoção a respeitava, e
    // a pergunta da mesma volta não: a resposta da extensão fechava o diálogo
    // com a limpeza e entrava com a conta do WME (o que estava colado ia
    // embora), e o "negado" abria o "Acesso restrito" por cima dele (auditoria
    // da rodada 12, R12-1-05, MEDIDO).
    if (textoDigitadoNaEntrada()) return;
    if (document.getElementById('authScreen')?.classList.contains('hidden')) return;
    entrarPelaExtensao({ silencioso: true }).then((entrou) => {
        // A outra aba entrou enquanto a extensão respondia: a sessão dela entra,
        // como no fim da pergunta da abertura (a volta não a adota com uma
        // pergunta no ar — ver `adotarSessaoDoAparelho`).
        if (entrou || adotarSessaoDoAparelho()) return;
        mostrarNegadoDaExtensao();
    });
}

// Seletor de idioma. São DOIS controles: um em Filtros → Preferências (onde se
// procura por preferência) e outro na Ajuda — porque o botão de Filtros fica
// escondido sem sessão, e quem caiu num idioma que não lê precisa trocar ANTES
// de conseguir entrar. Os dois ficam em sincronia.
const SELETORES_IDIOMA = ['langSelect', 'langSelectHelp'];

function aplicarIdioma(valor) {
    setLang(valor);
    // O idioma NÃO entra na "Poliglota" aqui: ela é sobre TRABALHAR em dois
    // idiomas, e quem registra é a ação confirmada (`registrarAcaoConfirmada`).
    // Registrado aqui, abrir o seletor e voltar destravava a conquista — e,
    // deslogado (o seletor da Ajuda), recriava `waze_places_conquistas` depois
    // do "Sair", herdado pela próxima conta (auditoria de 2026-09-25).
    safeLS.set(LANG_KEY, valor);
    applyI18n();
    // Os dois seletores mostram a mesma escolha, tenha sido feita em qual for.
    for (const id of SELETORES_IDIOMA) {
        const s = document.getElementById(id);
        if (s && s.value !== valor) s.value = valor;
    }
    // O `applyI18n` acima reescreveu o texto das opções de data (elas têm
    // `data-i18n`), levando o ícone junto — redecora.
    popularOrdenacoes();
    // A dica sob o "Ordenar por" é texto do JS com valor interpolado: o
    // `applyI18n` não a alcança, e ela ficava em português na aba Filtros depois
    // de trocar o idioma nas Preferências do MESMO modal (auditoria de
    // 2026-09-29, F6). As opções de texto dos seletores ("Todas as categorias",
    // "Todos os estados", "Nenhuma", "Carregando…") levam `data-i18n` e já foram.
    atualizarDicaDeOrdem(estadoDaDicaDeOrdem);
    if (AppState.profile) renderProfileHeader(AppState.profile);
    // Os exemplos do treino têm o texto no card (R6-7-10): retraduzidos ANTES de
    // o card ser redesenhado.
    Treino.retraduzirExemplos();
    if (AppState.currentPlace) showCurrentPlace();
    updateStats();
    updatePendingCount();
    // A frase do indicador "esperando envio"/"Enviando N…" (o `title` e o que o
    // leitor de tela anuncia) também é do JS: ficava no idioma de antes (R6-7-10).
    updateInFlightIndicator();
    // O que o JS escreve com `t()` fora do `data-i18n`, e que o `applyI18n` não
    // alcança. MEDIDO trocando pra inglês com as Preferências abertas — a tela
    // onde a troca acontece: o aviso do Desfazer ficava em português, e o nome
    // da pílula da presença também (auditoria de 2026-09-25). Junto, a linha do
    // offline (também das Preferências) e o nome do botão de Filtros, que o
    // `applyI18n` devolve ao padrão tirando o aviso da conquista nova.
    if (AppState.authenticated) {
        renderUndoGateUI();
        atualizarLinhaDoOffline(0, 0);
        atualizarSeloDeConquista();
        window.Presenca?.renderPilula?.();
        // O painel do Histórico também é texto do JS. Entrar na aba já o
        // redesenha (`switchFilterTab`); isto cobre ele estar NA TELA na troca.
        if (historicoNaTela()) renderHistory();
    }
    if (typeof showToast === 'function') showToast(t('toast.langChanged'), 'success');
}

// Os <option> vinham escritos DUAS vezes no index.html, um par por seletor —
// idioma novo exigia lembrar dos dois, e o de baixo (o da Ajuda) já tinha sido
// esquecido antes. Agora saem de LANG_NOMES, que é a mesma fonte do dicionário.
function popularSeletoresDeIdioma() {
    const nomes = (typeof LANG_NOMES === 'object' && LANG_NOMES) || {};
    const langs = (typeof LANGS_SUPORTADOS !== 'undefined' && LANGS_SUPORTADOS) || Object.keys(nomes);
    for (const id of SELETORES_IDIOMA) {
        const sel = document.getElementById(id);
        if (!sel) continue;
        sel.textContent = '';
        for (const l of langs) {
            const o = document.createElement('option');
            o.value = l;
            // Sem entrada em LANG_NOMES o código cru aparece — feio, nunca invisível.
            o.textContent = nomes[l] || l;
            sel.appendChild(o);
        }
    }
}

function setupLanguageSwitcher() {
    if (typeof setLang !== 'function') return;
    popularSeletoresDeIdioma();
    const atual = (typeof getLang === 'function') ? getLang() : 'pt';
    for (const id of SELETORES_IDIOMA) {
        const sel = document.getElementById(id);
        if (!sel) continue;
        sel.value = atual;
        sel.addEventListener('change', () => aplicarIdioma(sel.value));
    }
}

// Abas do modal "Filtros e Preferências" (padrão WAI-ARIA Tabs: aria-selected,
// roving tabindex, navegação por setas). Cada aba mostra seu painel e ajusta o
// rodapé: Filtros é formulário (Cancelar/Aplicar); Preferências aplicam na hora
// e Histórico é só leitura (ambas mostram só "Fechar").
const FILTER_TABS = [
    { tab: 'filtersTabFilters', panel: 'filtersPanelFilters' },
    { tab: 'filtersTabPrefs', panel: 'filtersPanelPrefs' },
    { tab: 'filtersTabHistory', panel: 'filtersPanelHistory' }
];

function switchFilterTab(tabId) {
    const $ = id => document.getElementById(id);
    FILTER_TABS.forEach(({ tab, panel }) => {
        const selected = tab === tabId;
        const btn = $(tab);
        if (!btn) return;
        btn.setAttribute('aria-selected', selected ? 'true' : 'false');
        btn.tabIndex = selected ? 0 : -1;
        $(panel).classList.toggle('hidden', !selected);
    });
    // Abrir a aba Histórico apaga o selo (decisão do owner). Fica AQUI e não no
    // handler do botão porque a aba também se alcança pelo teclado (setas, Home,
    // End) — amarrar ao clique deixaria o selo aceso pra quem navega assim.
    //
    // E o painel é desenhado ao ENTRAR, não só quando o modal abre: trocar o
    // idioma nas Preferências (o mesmo modal) deixava a aba no idioma antigo
    // (auditoria de 2026-09-25). ANTES de marcar as novas como vistas — o
    // desenho é que põe o anel nelas (ver `abrirModalNaAba`).
    if (tabId === 'filtersTabHistory') {
        renderHistory();
        marcarConquistasVistas();
    }
    const isFilters = tabId === 'filtersTabFilters';
    $('cancelFilters').classList.toggle('hidden', !isFilters);
    $('applyFilters').classList.toggle('hidden', !isFilters);
    $('closeFiltersFooter').classList.toggle('hidden', isFilters);
}

function setupFilterTabs() {
    const $ = id => document.getElementById(id);
    FILTER_TABS.forEach(({ tab }, i) => {
        const btn = $(tab);
        if (!btn) return;
        btn.addEventListener('click', () => switchFilterTab(tab));
        btn.addEventListener('keydown', (e) => {
            // Com Ctrl, ⌘ ou Alt a tecla é do navegador (o Voltar e o Avançar; com
            // Home e End, o topo e o fim da página): a aba não troca (ver
            // `handleKeyDown`). Sem `preventDefault`, o Voltar fecha os Filtros.
            if (atalhoDoNavegador(e)) return;
            let target = null;
            if (e.key === 'ArrowRight') target = FILTER_TABS[(i + 1) % FILTER_TABS.length];
            else if (e.key === 'ArrowLeft') target = FILTER_TABS[(i - 1 + FILTER_TABS.length) % FILTER_TABS.length];
            else if (e.key === 'Home') target = FILTER_TABS[0];
            else if (e.key === 'End') target = FILTER_TABS[FILTER_TABS.length - 1];
            if (!target) return;
            e.preventDefault();
            switchFilterTab(target.tab);
            $(target.tab).focus();
        });
    });
}

// Atalhos do manifest PWA (long-press no ícone do app): /?action=filters e
// /?action=refresh. Só valem com sessão ativa — deslogado a tela de auth manda.
// A query é limpa da URL depois (replaceState) pra um F5 não repetir a ação.
function handleLaunchAction() {
    const action = tirarAcaoDaURL();
    if (!action) return;
    if (action === 'filters') {
        openFiltersModal();
    } else if (action === 'refresh') {
        resetQueue();
        startFetching();
        showToast(t('toast.refreshing'), 'info');
    }
}

// Lê o atalho e o TIRA da URL na hora, com ou sem sessão. Sem sessão a query
// ficava: a pessoa entrava, e um F5 bem depois (horas, no PWA que o Android
// retoma) disparava o "Atualizando fila…" ou os Filtros que ninguém pediu
// naquela hora (auditoria de 2026-09-26). Sem sessão o atalho não vale — a tela
// de entrada manda —, então ele é só descartado.
function tirarAcaoDaURL() {
    let action = null;
    try {
        action = new URLSearchParams(window.location.search).get('action');
    } catch (e) { return null; }
    if (!action) return null;
    try {
        window.history.replaceState({}, '', window.location.pathname);
    } catch (e) {}
    return action;
}

// ── Pareamento computador → celular ────────────────────────────────────────
// O problema que isto resolve: copiar cookies num celular é inviável na prática.
// Aqui o editor loga UMA vez no computador (onde a extensão faz num clique) e
// traz a sessão pro telefone com um código de 6 caracteres, válido 5 minutos.
const pairTickers = new Map();

// Até quando o QR aberto VALE, no relógio do aparelho (ms; zero = nada a
// copiar). O servidor conta os 5 min da criação, e a conta daqui parte da
// chegada da resposta: erra pra MAIS tarde por uma ida à rede, e o resgate de um
// link vencido nesse meio só leva "código inválido" (a validade mora no valor
// guardado). Quem consulta é o "Copiar link": ele não entrega link vencido.
let pairQrVenceEm = 0;

// A ABERTURA do diálogo do QR em curso: sobe a cada abertura e a cada fechamento
// (a limpeza dele, por qualquer caminho). Com a época da sessão, é o que diz se
// a resposta de um pedido de código ainda é DESTE diálogo (ver
// `pareamentoTardio`).
let aberturaDoPareamento = 0;

// O código pedido pra um diálogo que JÁ NÃO É ESTE — fechado (o "Sair" passa
// pela Ajuda, que o esconde com a limpeza), ou com a sessão trocada embaixo
// dele (o "Sair" noutra aba, a queda). A resposta que chega depois não escreve
// nada, e o código que ela traz é CANCELADO no servidor. Antes ele entrava no
// `pareamentosEmitidos` que o "Sair" já tinha limpado: seguia valendo 5 min (e
// abria uma sessão nova da conta que acabou de sair), e ficava no DOM da tela de
// entrada, com o "Copiar link" habilitado e a contagem correndo — MEDIDO com a
// resposta chegando 2,5 s depois do "Sair" (auditoria de 2026-10-02, R6-1-09).
// Devolve se a resposta é de outro diálogo ou de outra sessão.
function pareamentoTardio(r, epoca, abertura) {
    if (epoca === epocaDaSessao && abertura === aberturaDoPareamento) return false;
    if (r && r.success && r.code) API.cancelarPareamento(r.code).catch(() => {});
    return true;
}

// O pedido de código NÃO DEU (`tardio`: a resposta é de outra sessão). Um 401
// não é prova de sessão morta (gotcha #42): no resto do app ele é CONFERIDO
// (`handleUnauthorized`) antes de virar "sessão expirada", e aqui o app
// afirmava a queda sem conferir — pode ser o WAF —, e com a sessão morta de
// verdade seguia na tela da fila, sem tentar a extensão nem levar à entrada
// (auditoria de 2026-10-02, R6-1-08). O aviso é o do PEDIDO ("não deu pra
// gerar o código"); o da sessão, se ela caiu, vem da conferência. O 401 de uma
// resposta TARDIA é da sessão que já se foi: não confere a de agora.
function avisarFalhaDoPareamento(r, tardio) {
    const sessao = !tardio && !!r && r.errorCategory === 'unauthorized';
    showToast(tardio || sessao ? t('toast.pairCreateError') : msgDoServidor(r, t('toast.pairCreateError')), 'error');
    if (sessao) handleUnauthorized();
}

// Desenha o QR do link de pareamento. É a única forma de conectar que não
// precisa de instrução nenhuma: aponta a câmera e entra — sem memorizar caminho
// de menu no outro aparelho, sem trocar de aparelho com um código na cabeça,
// sem a dúvida de digitar ou não o separador.
// Escala inteira de propósito: módulo em fração de pixel borra a leitura.
// Apaga o QR desenhado. Canvas guarda o último desenho pra sempre; sem isto,
// reabrir o modal mostra o QR do código ANTERIOR até a resposta chegar.
function limparQrPareamento() {
    const canvas = document.getElementById('pairQr');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
}

// O gerador de QR (12KB) só serve ao pareamento, que a maioria dos editores
// nunca abre — e era baixado em TODA abertura do app. Aqui ele vem sob demanda,
// uma vez por sessão. É `self` na CSP, então injetar a tag é permitido.
let _qrCarregando = null;
function carregarQr() {
    if (typeof gerarQR === 'function') return Promise.resolve(true);
    if (_qrCarregando) return _qrCarregando;
    _qrCarregando = new Promise((resolve) => {
        const s = document.createElement('script');
        s.src = 'js/min/qr.js';
        s.onload = () => resolve(typeof gerarQR === 'function');
        // Falhar não pode travar o pareamento: o código digitável continua lá.
        s.onerror = () => { _qrCarregando = null; resolve(false); };
        document.head.appendChild(s);
    });
    return _qrCarregando;
}

async function desenharQrPareamento(url) {
    const canvas = document.getElementById('pairQr');
    if (!canvas) return;
    if (!(await carregarQr())) { canvas.classList.add('hidden'); return; }
    const qr = gerarQR(url);
    if (!qr) { canvas.classList.add('hidden'); return; }
    canvas.classList.remove('hidden');
    const QUIET = 4;                         // margem exigida pela norma
    const lado = qr.tamanho + QUIET * 2;
    const escala = Math.max(2, Math.floor(220 / lado));
    const px = lado * escala;
    canvas.width = px * (window.devicePixelRatio || 1);
    canvas.height = canvas.width;
    canvas.style.width = px + 'px';
    canvas.style.height = px + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(window.devicePixelRatio || 1, window.devicePixelRatio || 1);
    // Fundo claro SEMPRE, inclusive no tema escuro: leitor de QR espera
    // módulos escuros sobre claro, e inverter derruba a taxa de leitura.
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, px, px);
    ctx.fillStyle = '#0f172a';
    for (let l = 0; l < qr.tamanho; l++) {
        for (let c = 0; c < qr.tamanho; c++) {
            if (qr.modulos[l][c]) {
                ctx.fillRect((c + QUIET) * escala, (l + QUIET) * escala, escala, escala);
            }
        }
    }
}

async function abrirPareamento() {
    // `openModal` sozinho: ele JÁ esconde os outros modais, e trocar de modal
    // é a MESMA camada — não empilha histórico.
    //
    // Fechar antes, no mesmo quadro, dessincronizava o contador do voltar do
    // jeito mais traiçoeiro possível: o `closeModal` agenda um `history.back()`,
    // o `openModal` seguinte empilha uma entrada NOVA, e o back que estava
    // pendente come justamente essa. Sobra `profundidade: 1` sem entrada real
    // por trás — e o próximo fechamento manda o `back()` pra fora do app.
    //
    // MEDIDO: Ajuda → Conectar outro aparelho → fechar tirava o editor da
    // página. O contador não denuncia (fica em 1, com history.length 3): só
    // a navegação mostra.
    openModal('pairShowModal');
    // O foco inicial NÃO é o primeiro botão: ele é o "Sem câmera? Mostrar um
    // código", que CRIA o código FRACO (~30 bits) — um Enter a mais, e a cópia
    // fraca passava a existir no servidor ao lado do QR (auditoria de
    // 2026-09-26). O "Fechar" não cria nada e é a saída de quem só olhou.
    document.getElementById('pairShowClose')?.focus();
    const codeEl = document.getElementById('pairCode');
    const expEl = document.getElementById('pairExpiry');
    codeEl.textContent = '······';
    delete codeEl.dataset.raw;
    pairQrVenceEm = 0;
    codeEl.classList.remove('opacity-40', 'line-through');
    expEl.textContent = '';
    anunciarNoPareamento('');
    // O código volta a ficar escondido a cada abertura: revelar é um pedido, e
    // pedido não se herda da vez passada — cada revelação cria um registro
    // fraco novo no servidor.
    document.getElementById('pairCodeReveal').classList.add('hidden');
    document.getElementById('pairShowCodeBtn').classList.remove('hidden');
    document.getElementById('pairShowCodeBtn').disabled = false;
    document.getElementById('pairCodeExpiry').textContent = '';
    mostrarInstrucoesDoPareamento();
    limparQrPareamento();
    document.getElementById('pairCopyLinkBtn').disabled = true;

    // A conta vai junto: o aparelho que resgatar sabe de quem é a sessão NA
    // HORA (ver `resgatarPareamento`, K8).
    const epoca = epocaDaSessao;
    const abertura = ++aberturaDoPareamento;
    const r = await API.criarPareamento({ conta: contaAgora() });
    // A resposta de outro diálogo, ou de outra sessão (ver `pareamentoTardio`).
    // O MESMO diálogo ainda na tela, com a sessão trocada embaixo dele (a queda,
    // com a extensão renovando), ficaria um QR vazio esperando nada: fecha, como
    // a falha.
    const tardio = pareamentoTardio(r, epoca, abertura);
    if (tardio && abertura !== aberturaDoPareamento) return;
    if (tardio || !r.success) {
        closeModal('pairShowModal');
        avisarFalhaDoPareamento(r, tardio);
        return;
    }
    // O segredo do QR NÃO é exibido: ele tem 20 símbolos e ninguém vai digitar
    // isso. Quem não tem câmera pede um código curto no botão, e aí sim.
    codeEl.dataset.raw = r.code;
    pareamentosEmitidos.add(r.code);
    pairQrVenceEm = Date.now() + r.expiresIn * 1000;
    desenharQrPareamento(location.origin + '/#pair=' + r.code);
    document.getElementById('pairCopyLinkBtn').disabled = false;

    iniciarTickerPareamento(expEl, r.expiresIn, aoVencerQrPareamento);
}

// O QR venceu: o desenho sai (é credencial morta), o link sai do "Copiar link"
// e o botão apaga. Antes só o desenho saía, e o botão seguia copiando um link
// que já não entrava em lugar nenhum (auditoria de 2026-09-26). O texto de
// vencido diz o caminho de um novo (`pair.expired`).
function aoVencerQrPareamento() {
    // Lido ANTES de mexer: o botão focado que vira `disabled` perde o foco.
    const focado = document.activeElement;
    // Este QR JÁ tinha vencido (o "Copiar link" descobriu pelo relógio, e o tique
    // chega depois): o anúncio dele já foi feito, e não se repete.
    const jaVencido = !pairQrVenceEm;
    limparQrPareamento();
    pairQrVenceEm = 0;
    const code = document.getElementById('pairCode');
    if (code) delete code.dataset.raw;
    const copiar = document.getElementById('pairCopyLinkBtn');
    if (copiar) copiar.disabled = true;
    // A instrução da câmera aponta pra um QR que acabou de sair, e o "Sem
    // câmera? Mostrar um código" criava um código NOVO, válido, embaixo da frase
    // que manda fechar e pedir outro (auditoria de 2026-09-29, A15). Os dois
    // saem: o caminho de um código novo é o que o aviso de vencido diz.
    document.getElementById('pairShowBody')?.classList.add('hidden');
    const semCamera = document.getElementById('pairShowCodeBtn');
    semCamera?.classList.add('hidden');
    // O código curto já pedido vale até o prazo DELE (nasceu depois do QR):
    // enquanto ele vale, o "Código expirado" do QR ficaria em cima de um código
    // que ainda entra. Quem fala é a contagem dele, que vence do mesmo jeito.
    if (codigoCurtoValendo()) {
        const exp = document.getElementById('pairExpiry');
        if (exp) exp.textContent = '';
    } else if (!jaVencido) {
        // O vencimento DITO ao leitor de tela (ver `anunciarNoPareamento`), pela
        // MESMA regra da frase visível: só quando nenhum código vale mais. Era
        // dito em todo vencimento, pelo contador: com o código curto valendo, o
        // leitor de tela ouvia "Código expirado — feche e toque de novo" 4
        // minutos antes de ele vencer, e quem não enxerga jogava fora um código
        // que ainda entrava (auditoria de 2026-10-02, R6-1-02). O do código
        // curto é dito no vencimento DELE (`revelarCodigoPareamento`).
        anunciarNoPareamento(t('pair.expired'));
    }
    // Com o foco no "Copiar link" (que apagou) ou no "Sem câmera?" (que sumiu),
    // o foco caía no <body> e o leitor de tela perdia a posição (auditoria de
    // 2026-10-01, R56-5). Vai ao "Fechar", que é o passo que o aviso de vencido
    // manda dar.
    if (focado && (focado === copiar || focado === semCamera)) devolverFocoNoPareamento(focado, ['pairShowClose']);
}

// O controle do pareamento que SAI de cena com o foco do teclado nele —
// escondido, ou `disabled` — largava o foco no <body> (a regra do C10: o foco
// vai a um alvo que existe). Vai ao primeiro alvo vivo da lista, e só se o foco
// ainda está perdido: quem o levou a outro lugar nesse meio (um Tab durante o
// pedido do código) escolheu o lugar dele.
function devolverFocoNoPareamento(saiu, alvos) {
    const ativo = document.activeElement;
    if (ativo && ativo !== document.body && ativo !== saiu) return;
    const alvo = alvos.map((id) => document.getElementById(id)).find(focavelNaTela);
    if (alvo) alvo.focus();
}

// O código curto está na tela e ainda vale? Revelado e não riscado — o risco é
// o que o vencimento dele põe (`revelarCodigoPareamento`).
function codigoCurtoValendo() {
    const revelado = document.getElementById('pairCodeReveal');
    const code = document.getElementById('pairCode');
    return !!(revelado && !revelado.classList.contains('hidden')
        && code && code.dataset.curto && !code.classList.contains('line-through'));
}

// O que o vencimento (do QR e do código curto) esconde, de volta a cada
// abertura: o modal é reaproveitado.
function mostrarInstrucoesDoPareamento() {
    for (const id of ['pairShowBody', 'pairOrType']) document.getElementById(id)?.classList.remove('hidden');
}

// O vencimento (do QR ou do código curto) é dito ao leitor de tela UMA vez, na
// região viva à parte do modal (`#pairAnuncio`): a contagem muda a cada segundo,
// e região viva nela falaria o tempo todo. O foco inicial é o "Fechar", então
// sem isto o "Código expirado" só era lido por quem fosse procurar. Quem anuncia
// é o vencimento de CADA um (`aoVencerQrPareamento` e o do código curto em
// `revelarCodigoPareamento`), não o contador: o contador não sabe se OUTRO
// código ainda vale.
function anunciarNoPareamento(texto) {
    const el = document.getElementById('pairAnuncio');
    if (el) el.textContent = texto;
}

// Contagem regressiva: deixa claro que o segredo morre — e evita o editor ficar
// tentando um código velho achando que o app quebrou. Vale pro QR e pro código
// digitado, que são registros SEPARADOS e vencem cada um no seu tempo.
//
// Pelo RELÓGIO, não pela contagem de tiques: aba em segundo plano estrangula o
// `setInterval` (um por minuto, ou menos), e contar tiques mostrava "Vale por
// mais 3:40" ao voltar pra um código que já tinha vencido.
function iniciarTickerPareamento(elemento, segundos, aoVencer) {
    const venceEm = Date.now() + segundos * 1000;
    const tick = () => {
        const restante = Math.ceil((venceEm - Date.now()) / 1000);
        if (restante <= 0) {
            elemento.textContent = t('pair.expired');
            if (aoVencer) aoVencer();
            pararTickerPareamento(elemento);
            return false;
        }
        const m = Math.floor(restante / 60);
        const seg = String(restante % 60).padStart(2, '0');
        elemento.textContent = t('pair.expiresIn', { time: m + ':' + seg });
        return true;
    };
    pararTickerPareamento(elemento);
    // Já vencido na largada, nenhum intervalo nasce (senão o aoVencer rodaria
    // a cada segundo, pra sempre).
    if (tick()) pairTickers.set(elemento, setInterval(tick, 1000));
}

// Um ticker por elemento: o QR e o código correm juntos, e um `clearInterval`
// só derrubaria o outro em silêncio. Sem argumento, para todos — é o que a
// LIMPEZA_AO_FECHAR precisa, e é o caminho que já mordeu antes (o ticker seguia
// rodando pelo resto da sessão porque a limpeza morava no handler do botão).
function pararTickerPareamento(elemento) {
    if (elemento) {
        clearInterval(pairTickers.get(elemento));
        pairTickers.delete(elemento);
        return;
    }
    for (const id of pairTickers.values()) clearInterval(id);
    pairTickers.clear();
}

// Cria um registro de pareamento CURTO (6 chars, digitável) — só quando pedido.
// Ver o comentário no index.html: o curto é fraco por construção, e existir só
// sob demanda é o que impede que ele enfraqueça o QR de todo mundo.
async function revelarCodigoPareamento(ev) {
    const btn = document.getElementById('pairShowCodeBtn');
    const codeEl = document.getElementById('pairCode');
    const expEl = document.getElementById('pairCodeExpiry');
    // O botão trava no pedido e SOME quando o código chega: o Enter que pediu o
    // código deixava o foco no <body> (a mesma costura do R56-5, no mesmo botão).
    // Só pelo teclado (`veioDoTeclado`, a regra do C10): quem toca não tem o
    // foco movido.
    const tinhaFoco = veioDoTeclado(ev);
    const epoca = epocaDaSessao;
    const abertura = aberturaDoPareamento;
    btn.disabled = true;
    const r = await API.criarPareamento({ comCodigo: true, conta: contaAgora() });
    // A resposta de outro diálogo, ou de outra sessão (ver `pareamentoTardio`):
    // o código que veio é cancelado; com o diálogo fechado, nada se escreve. O
    // MESMO diálogo ainda na tela (a sessão trocada embaixo dele) volta como a
    // falha.
    const tardio = pareamentoTardio(r, epoca, abertura);
    if (tardio && abertura !== aberturaDoPareamento) return;
    if (tardio || !r.success) {
        btn.disabled = false;
        // O botão volta, e o foco com ele — ou o "Fechar", se o QR venceu nesse meio.
        if (tinhaFoco) devolverFocoNoPareamento(btn, ['pairShowCodeBtn', 'pairShowClose']);
        avisarFalhaDoPareamento(r, tardio);
        return;
    }
    pareamentosEmitidos.add(r.code);
    btn.classList.add('hidden');
    document.getElementById('pairCodeReveal').classList.remove('hidden');
    codeEl.textContent = formatarCodigoPareamento(r.code);
    // O CRU é o que vale pro resgate — o separador é só apresentação.
    codeEl.dataset.curto = r.code;
    codeEl.classList.remove('opacity-40', 'line-through');
    // Pedido no último instante do QR, a resposta chega com ele já vencido: o
    // "Código expirado" dele não fica em cima deste, que acabou de nascer — nem
    // na tela, nem na região viva. Esvaziada aqui, ela MUDA quando este vencer, e
    // o leitor de tela ouve o vencimento dele (texto igual reescrito pode não ser
    // lido de novo).
    const expQr = document.getElementById('pairExpiry');
    if (expQr && expQr.textContent === t('pair.expired')) expQr.textContent = '';
    anunciarNoPareamento('');
    iniciarTickerPareamento(expEl, r.expiresIn, () => {
        codeEl.classList.add('opacity-40', 'line-through');
        // "Digite este código" sobre um código morto é a mesma instrução falsa
        // da câmera sobre o QR vencido (A15): sai junto.
        document.getElementById('pairOrType')?.classList.add('hidden');
        // E o leitor de tela ouve: ele nasceu depois do QR, então quando ele
        // vence nenhum código vale mais (R6-1-02).
        anunciarNoPareamento(t('pair.expired'));
    });
    // O código está na tela: o foco vai ao "Copiar link", o controle seguinte
    // (onde o próximo Tab iria) — ou ao "Fechar", com o QR já vencido.
    if (tinhaFoco) devolverFocoNoPareamento(btn, ['pairCopyLinkBtn', 'pairShowClose']);
}

async function copiarLinkPareamento() {
    const raw = document.getElementById('pairCode').dataset.raw;
    if (!raw) return;
    // Vencido pelo RELÓGIO, ainda que o tique do contador não tenha passado (aba
    // que voltou do segundo plano): recusa e diz o caminho de um novo, em vez de
    // entregar um link que já não entra.
    if (Date.now() >= pairQrVenceEm) {
        aoVencerQrPareamento();
        showToast(t('pair.expired'), 'error');
        return;
    }
    const url = location.origin + '/#pair=' + raw;
    try {
        await navigator.clipboard.writeText(url);
        showToast(t('toast.pairLinkCopied'), 'success');
    } catch (e) {
        // clipboard exige contexto seguro e permissão; sem ele, mostra o link
        // pro editor copiar na mão em vez de falhar em silêncio. COPIÁVEL: o
        // toast não some enquanto ele seleciona, e fica o bastante pra isso.
        // SENSÍVEL: o link É o segredo do pareamento (vale uma sessão nova por
        // 5 min) — fora do diário, que vai pro diagnóstico e pra cópia guardada.
        showToast(url, 'info', TOAST_COPIAVEL_MS, null, { copiavel: true, sensivel: true });
    }
}

// Quanto o link pra copiar à mão fica na tela: 12 s não davam pra achar o link,
// selecionar e copiar. E enquanto houver texto dele selecionado, o relógio
// confere de novo a cada `TOAST_COPIAVEL_RECHECA_MS` em vez de dispensá-lo.
const TOAST_COPIAVEL_MS = 30000;
const TOAST_COPIAVEL_RECHECA_MS = 1500;

// O resgate NO AR. O Enter e o "Entrar" do campo mandavam o resgate duas vezes
// (Enter duplo, Enter + toque): MEDIDO, dois resgates, duas cargas de perfil e
// de fila, e um token jogado fora (auditoria de 2026-09-29, R4-5 A7). É o
// `authInFlight` do login por cookies, pro código.
let resgateEmVoo = false;
// O DESFECHO do resgate no ar (entrou?), pro login por cookies que a pessoa
// confirma com ele no ar: esse ESPERA por ele (ver `authenticateWithCookies`,
// R12-1-01). `null` sem resgate no ar.
let resgateNoAr = null;

// `peloTeclado`: o Enter no campo, ou no "Entrar" focado. A tela de entrada some
// com o foco nela (o "Entrar com um código", a quem o fechamento do diálogo o
// devolve), e o foco caía no <body> — o mesmo do login pelo colar (R7-1-04, ver
// `authenticateWithCookies`): fica prometido ao ✕ do primeiro card.
async function resgatarPareamento(code, { silencioso = false, peloTeclado = false } = {}) {
    if (resgateEmVoo) return false;
    // Pelo diálogo, só com o diálogo NA TELA. Contra a VM de verdade o resgate
    // volta em milissegundos, e o 2º Enter chegava DEPOIS dele, com o diálogo já
    // fechado: mandava o código usado de novo, e o "código inválido" ia parar no
    // diálogo escondido (a trava acima não o pega: o 1º já tinha terminado).
    if (!silencioso && document.getElementById('pairEnterModal')?.classList.contains('hidden')) return false;
    resgateEmVoo = true;
    let entrou = false;
    let terminou = null;
    resgateNoAr = new Promise((ok) => { terminou = ok; });
    try {
        const err = document.getElementById('pairEnterError');
        const r = await API.resgatarPareamento(code);
        if (!r.success) {
            if (silencioso) {
                showToast(msgDoServidor(r, t('toast.pairInvalid')), 'error');
            } else if (err) {
                err.textContent = msgDoServidor(r, t('toast.pairInvalid'));
                err.classList.remove('hidden');
            }
            return false;
        }
        // A tela de entrada some agora, e com ela o OUTRO diálogo que a pessoa
        // abriu durante a espera (o link mostra a tela de entrada durante o
        // resgate): o "Colar cookies", com o cookies.txt colado, ficava POR CIMA
        // do app, e o "Confirmar" ali criava uma segunda sessão, com a primeira
        // órfã no servidor (auditoria da rodada 11, R11-1-04, MEDIDO). Sai com a
        // limpeza, como na entrada pela extensão (`MODAIS_DA_ENTRADA`). E o foco
        // que estava NA tela de entrada vai ao ✕ do primeiro card: ela some sem
        // gesto, e ele caía no <body> (R10-1-05; lido ANTES de fechar). O "Entrar
        // com um código" de onde o resgate saiu segue a regra do teclado (R7-1-04):
        // pelo mouse, o foco nele não se move.
        const dialogoDoGesto = silencioso ? null : document.getElementById('pairEnterModal');
        const focoNaEntrada = focoNaTelaDeEntrada() && !(dialogoDoGesto && dialogoDoGesto.contains(document.activeElement));
        const focoNoCard = peloTeclado || focoNaEntrada;
        fecharModaisDaEntrada({ focoComDestino: focoNoCard });
        aoEntrarNestaPagina();
        showToast(t('toast.pairSuccess'), 'success');
        showMainScreen();
        resetQueue();   // fila NOVA, como no login por cookies
        conhecerContaDoLogin(r.conta);   // a conta, na hora (ver `authenticateWithCookies`)
        AppState._profilePromise = loadProfileAndAuxData();
        if (focoNoCard) focoDoTeclado = BOTAO_DA_ACAO.left;
        startFetching();
        esvaziarFilaDeSaida();   // o que ficou esperando a sessão sai agora
        entrou = true;
        return true;
    } finally {
        resgateEmVoo = false;
        resgateNoAr = null;
        terminou(entrou);
    }
}

function setupModalListeners() {
    const $ = id => document.getElementById(id);
    // O último foco FORA das camadas é a reserva do `devolverFoco`.
    document.addEventListener('focusin', (e) => {
        if (!dentroDeCamada(e.target)) ultimoFocoForaDasCamadas = e.target;
    });
    $('closeFilters').addEventListener('click', () => closeModal('filtersModal'));
    $('cancelFilters').addEventListener('click', () => closeModal('filtersModal'));
    $('closeFiltersFooter').addEventListener('click', () => closeModal('filtersModal'));
    $('applyFilters').addEventListener('click', applyFiltersFromModal);
    $('batchReadBtn')?.addEventListener('click', openBatchReadConfirm);
    $('confirmBatchRead')?.addEventListener('click', handleBatchMarkRead);
    $('cancelBatchRead')?.addEventListener('click', () => closeModal('batchReadModal'));
    $('lightboxDelete')?.addEventListener('click', pedirExclusaoDaFoto);
    $('lightboxApprove')?.addEventListener('click', aprovarFotoAtual);
    $('lightboxNomeBtn')?.addEventListener('click', abrirEdicaoNome);
    $('lightboxNomeOk')?.addEventListener('click', confirmarRenomear);
    $('lightboxNomeCancel')?.addEventListener('click', sairDaEdicaoNome);
    $('lightboxNomeInput')?.addEventListener('input', atualizarBotaoSalvarNome);
    $('lightboxNomeInput')?.addEventListener('keydown', (ev) => {
        // Enter confirma, Esc cancela — e o Esc PARA aqui (`stopPropagation`),
        // senão ele fecha o lightbox inteiro e a pessoa perde a foto que estava
        // usando de prova só por desistir de um caractere.
        if (ev.key === 'Enter') { ev.preventDefault(); confirmarRenomear(); }
        else if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); sairDaEdicaoNome(); }
    });

    // Pareamento
    $('pairCreateBtn')?.addEventListener('click', abrirPareamento);
    $('pairCopyLinkBtn')?.addEventListener('click', copiarLinkPareamento);
    $('pairShowCodeBtn')?.addEventListener('click', revelarCodigoPareamento);
    $('pairShowClose')?.addEventListener('click', () => { pararTickerPareamento(); closeModal('pairShowModal'); });
    $('pairEnterBtn')?.addEventListener('click', () => {
        const input = $('pairCodeInput');
        if (input) input.value = '';
        $('pairEnterError')?.classList.add('hidden');
        openModal('pairEnterModal');
    });
    $('pairEnterCancel')?.addEventListener('click', () => closeModal('pairEnterModal'));
    $('pairEnterConfirm')?.addEventListener('click', (ev) => resgatarPareamento($('pairCodeInput').value,
        { peloTeclado: veioDoTeclado(ev) }));
    $('pairCodeInput')?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); resgatarPareamento(e.target.value, { peloTeclado: true }); }
    });
    // Colado de dentro de uma mensagem, com espaço ou quebra de linha: o código
    // é achado no texto (ver `extrairCodigoPareamento`).
    $('pairCodeInput')?.addEventListener('paste', colarCodigoPareamento);
    // O campo assume o MESMO formato da tela que mostra o código: digitou 3
    // caracteres, o hífen entra sozinho. Assim tanto faz o editor digitar o
    // separador ou não — o resultado na tela é o mesmo que ele está copiando.
    $('pairCodeInput')?.addEventListener('input', (e) => {
        const el = e.target;
        // Reformatar e jogar o cursor pro fim atrapalha quem corrige no meio;
        // conta quantos caracteres ÚTEIS havia antes do cursor e recoloca ali.
        const uteisAntes = el.value.slice(0, el.selectionStart).replace(/[^0-9A-Za-z]/g, '').length;
        el.value = formatarCodigoPareamento(el.value);
        let pos = 0, vistos = 0;
        while (pos < el.value.length && vistos < uteisAntes) {
            if (el.value[pos] !== '-') vistos++;
            pos++;
        }
        if (el.value[pos] === '-') pos++;   // o cursor pula o separador sozinho
        el.setSelectionRange(pos, pos);
    });
    setupFilterTabs();
    setupLanguageSwitcher();
    // O toque faz o que a barra diz: volta à ordem normal (ver `voltarAOrdemNormal`).
    $('focoAutorBar').addEventListener('click', voltarAOrdemNormal);
    $('filterCountry').addEventListener('change', (e) => {
        aoMudarPaisNaTela();
        loadStatesIntoSelect(parseInt(e.target.value, 10), $('filterRegion').value);
    });
    $('filterRegion').addEventListener('change', aoTrocarRegiaoNoModal);
    $('filterMyArea').addEventListener('change', (e) => {
        const checked = e.target.checked;
        $('filterCountry').disabled = checked;
        $('filterState').disabled = checked;
        $('filterManagedArea').disabled = checked;
    });

    // Preferências aplicam NA HORA (padrão M3 pra settings: switch = efeito
    // imediato; o "Aplicar" do rodapé pertence só à aba Filtros). O idioma já
    // funcionava assim (setupLanguageSwitcher); undo e dev mode agora também —
    // antes, trocar o switch e fechar sem "Aplicar" perdia a mudança em silêncio.
    $('prefUndoEnabled').addEventListener('change', (e) => {
        // Gate: sem cota o checkbox fica disabled e nem dispara change; o
        // canDisableUndo aqui é cinto de segurança contra DOM editado à mão.
        AppState.preferences.undoEnabled = canDisableUndo() ? e.target.checked : true;
        savePreferences();
    });
    $('prefOfflineDisponivel')?.addEventListener('change', (e) => offlineAoMudarInterruptor(e.target.checked));
    $('prefPularGuarda').addEventListener('change', (e) => {
        AppState.preferences.pularGuarda = e.target.checked;
        savePreferences();
        // O selo do ↑ muda de texto com a preferência, e o card já está na tela
        // atrás do modal — sem isto ele só se corrigiria no próximo swipe, e a
        // primeira vez que a pessoa arrastasse veria o texto antigo.
        atualizarSeloDePular();
    });
    $('prefPresenca').addEventListener('change', (e) => {
        AppState.preferences.presenca = e.target.checked;
        // O carimbo é do DESLIGAR. Religar à mão zera: quem voltou por vontade
        // própria não está no meio de nenhuma contagem. E a mesma chave vale
        // pro mapa do WME (fase 2): desligar some de lá na hora, religar volta
        // na próxima ação.
        if (e.target.checked) {
            delete AppState.preferences.presencaOffEm;
            presencaWmeReligar();
        } else {
            AppState.preferences.presencaOffEm = Date.now();
            presencaWmeDesligar();
        }
        savePreferences();
        window.Presenca?.sincronizar?.();
    });
    $('prefDevModeActive').addEventListener('change', async (e) => {
        if (!AppState.devMode.unlocked) return;
        // Desligar APAGA o que o dev gravou — senão "desligado" é mentira: o
        // dado continua no aparelho. Mas nunca em silêncio: captura que ainda
        // não foi baixada é trabalho, e perder trabalho sem avisar é o pior
        // desfecho possível pra um instrumento de socorro.
        //
        // O aviso vem ANTES de apagar, e o primeiro toque NÃO desliga: antes o
        // toast dizia "baixe antes de desligar" no mesmo instante em que as
        // capturas eram apagadas — conselho impossível de seguir. Agora o toque
        // volta o interruptor e avisa; um segundo toque (em até 15 s) desliga.
        //
        // E a conta é a do APARELHO, não a desta aba (R6-4-4): desligar aqui apaga
        // a base e, pelo aviso do navegador, a memória da OUTRA aba aberta — e as
        // capturas que ela fez depois de esta abrir não estavam na conta: o 1º
        // toque desligava calado. Elas estão na base, que se lê de forma
        // assíncrona (`diagAtualizarAnteriores`, que também as põe no próximo
        // relatório desta aba, como o aviso promete). Cada toque tira um número:
        // um toque que chegar durante a leitura decide, e não a leitura antiga.
        const vez = ++desligarDevVez;
        if (!e.target.checked && Date.now() > desligarDevConfirmadoAte) {
            // O que ESTA aba tem já se sabe: o interruptor volta na hora, sem piscar.
            if (dlogNaoBaixados() > 0) e.target.checked = true;
            await diagAtualizarAnteriores().catch(() => false);
            if (vez !== desligarDevVez) return;
            const naoBaixados = dlogNaoBaixados();
            if (naoBaixados > 0) {
                e.target.checked = true;
                desligarDevConfirmadoAte = Date.now() + 15000;
                showToast(t(naoBaixados === 1 ? 'toast.devPerdeCapturaUm' : 'toast.devPerdeCaptura', { n: naoBaixados }), 'error', 9000);
                return;
            }
            // Nada a perder no aparelho: desliga (o interruptor pode ter voltado acima).
            e.target.checked = false;
        }
        desligarDevConfirmadoAte = 0;
        AppState.devMode.active = e.target.checked;
        saveDevMode();
        updateDevBadge();
        atualizarFabDev();
        diagAjustarRecursos();
        if (!e.target.checked) {
            dlogApagar();
            enforceDevGatedFilters();
            // Dev off pode re-travar o gate do undo → força ligado de novo.
            if (!canDisableUndo() && AppState.preferences.undoEnabled === false) {
                AppState.preferences.undoEnabled = true;
                savePreferences();
            }
        }
        renderUndoGateUI();
    });
}

// SOBRE O `thumb100_` DO WAZE, E POR QUE ELE NÃO É USADO AQUI
//
// O Waze serve `thumb100_` (100x75, 3,2 KB) além do `thumb700_` (700x525,
// 80,8 KB) — 25x menos bytes. A tira de miniaturas chegou usando ele, e estava
// ERRADO. O owner apontou: o aquecimento JÁ baixou os `thumb700` deste card.
//
// Medido: renderizar um card dispara o aquecimento das 4 fotos do SEGUINTE em
// `thumb700` (`PREFETCH_TETO_FOTOS = 4`, cobrindo 91,7% dos cards por inteiro),
// e o `venue-image.waze.com` responde com `max-age=3600`. Quando o lightbox
// abre, essas fotos estão em cache e custam ZERO.
//
// O `thumb100` é outra URL, então nunca aproveita esse cache: seriam 4
// requisições novas e ~12,8 KB por local, por fotos que o aparelho já tem. Numa
// sessão de triagem com dezenas de locais de várias fotos, isso vira centenas
// de KB de duplicata — na conta de dados do editor.
//
// E tem o outro lado: reusar o `thumb700` na tira PRÉ-AQUECE o carrossel (é a
// mesma imagem que aparece ao tocar em ›), enquanto o `thumb100` baixa algo que
// nunca mais é usado. O preço é decodificar 700x525 pra desenhar em 59x44 —
// pago em memória, não em rede, e limitado pelo `loading="lazy"` (só as
// miniaturas visíveis decodificam).
//
// Resumo pro próximo que achar o `thumb100`: ele é ótimo em abstrato e inútil
// aqui, porque o app já tem a foto grande antes de precisar da pequena.

// Quando a foto foi tirada, na forma que o editor usa pra decidir.
//
// POR QUE ISTO IMPORTA: no lightbox mora a lixeira, e a pergunta que antecede
// excluir é "isto ainda é este lugar?". MEDIDO nos 6 países obrigatórios (3176
// fotos): a distribuição é BIMODAL — 48,5% têm menos de um mês (são as
// propostas) e 39,2% têm MAIS DE TRÊS ANOS, chegando a 12. Quase nada no meio.
// Ou seja, a data separa na hora "esta é a proposta" de "este é o acervo
// antigo", e hoje 39% das fotos chegam sem nenhum sinal disso na tela.
//
// FORMATO guiado pelos próprios dados: relativo pras recentes (metade dos
// casos, e "há 3 dias" lê melhor que uma data) e ANO pras antigas ("2019" lê
// melhor que "há 2350 dias"). O corte é 1 ano.
//
// `Intl.RelativeTimeFormat` em vez de chaves no dicionário: ele resolve plural
// por idioma sozinho, e o projeto não tem ICU — chave manual é exatamente onde
// nasce o "1 dias" (ver a nota do {undoSeg} no CLAUDE.md). Aqui não há string
// nossa pra traduzir: é dado formatado no locale, como o resto dos números.
function idadeDaFoto(ms) {
    if (!Number.isFinite(ms) || ms <= 0) return null;
    const dias = Math.floor((Date.now() - ms) / 86400000);
    if (dias < 0) return null;   // relógio torto ou data no futuro: não inventa
    const loc = i18nLocale();
    try {
        if (dias >= 365) return new Date(ms).toLocaleDateString(loc, { year: 'numeric' });
        const rtf = new Intl.RelativeTimeFormat(loc, { numeric: 'auto' });
        if (dias < 1) return rtf.format(0, 'day');
        if (dias < 30) return rtf.format(-dias, 'day');
        return rtf.format(-Math.round(dias / 30), 'month');
    } catch (e) {
        return new Date(ms).toLocaleDateString(loc);
    }
}

// As duas ações de foto (excluir / aprovar) aparecem por REGRA DE ESTADO,
// avaliada a cada render — nunca por um esconder de disparo único.
//
// Foi exatamente isso que quebrou, relatado pelo owner: `abrirEdicaoNome()`
// escondia os botões UMA vez, e o render da foto seguinte os reacendia sem
// saber que havia renomeação em curso. Reapareciam logo ABAIXO do
// confirmar/cancelar do nome — o canto pra onde o dedo já estava indo, com
// duas ações que gravam no mapa.
//
// Mesma lição do `acoesTravadas()` (gotcha #63): regra que vale em dois
// momentos mora em UMA função, senão os dois momentos divergem sem ninguém ver.
function atualizarAcoesDeFoto() {
    // No treino as duas ações NÃO existem: escrevem no mapa e não têm ensaio
    // possível. Some em vez de desabilitar — botão morto com cara de vivo lê
    // como app quebrado, e "desabilitado" convida à pergunta "por que não
    // posso?", que num treino não tem resposta boa.
    //
    // Renomeando, mesma coisa: elas ficam no mesmo canto do confirmar/cancelar.
    // Trocar de foto DURANTE a renomeação continua valendo (é legítimo conferir
    // a grafia noutra fachada) — o que não pode é a ação destrutiva voltar.
    //
    // E com a foto que NÃO CARREGOU (ou ainda carregando), também somem: as
    // duas são decisões sobre o PIXEL, e a regra de ouro que abriu a exceção da
    // foto é que pra aprovar é preciso tê-la VISTO em tamanho de decisão.
    // MEDIDO: pelo carrossel, a proposta com 404 abria no lightbox com o ícone
    // de imagem quebrada, o ✨ e o "Aprovar" ativo — e aprovar mandava
    // `approve: true` de uma foto que ninguém viu (auditoria de 2026-09-26). O
    // `load`/`error` da imagem reavaliam isto (ver `setupLightbox`).
    const some = Treino.ativo || editandoNome() || !fotoDoLightboxNaTela();
    const del = document.getElementById('lightboxDelete');
    if (del) del.classList.toggle('hidden', some || !Lightbox.idFotoAtual());
    // Mutuamente exclusivos: pendente se APROVA, aprovada se EXCLUI. Sem isso
    // os dois brigariam pelo mesmo canto, e o editor teria que adivinhar qual
    // vale pra foto que está vendo. A exclusão é por CONSTRUÇÃO: as duas
    // perguntas leem a mesma régua de "aprovada" (`Lightbox.idAprovadoDaFoto`),
    // uma pelo sim e a outra pelo não (R10-3-04).
    const apr = document.getElementById('lightboxApprove');
    if (apr) apr.classList.toggle('hidden', some || !Lightbox.podeAprovarAtual());
}

// A foto do lightbox está NA TELA: carregou e tem pixel. `complete` sozinho não
// basta — ele é verdadeiro também pra imagem quebrada —, então vale o
// `naturalWidth`. FONTE ÚNICA de quem mostra as ações de foto e de quem as
// executa (`aprovarFotoAtual`, `pedirExclusaoDaFoto`): um clique por fora do
// botão escondido (teclado, script) não pode furar a regra.
function fotoDoLightboxNaTela() {
    const img = document.getElementById('lightboxImage');
    return !!(img && img.complete && img.naturalWidth > 0);
}

// Pra onde o foco volta quando a foto ou o mapa AMPLIADOS fecham (Esc, ✕, ↓,
// arrastar, voltar). Caía no <body>, e quem usa teclado ou leitor de tela
// recomeçava do topo da página — o Filtros, de controle, devolvia ao botão que
// o abriu (auditoria de 2026-09-26). A régua é a do `devolverFoco` dos modais:
// quem ABRIU, se ainda está na tela; senão o mesmo lugar no card da FRENTE (a
// fila pode ter andado: aprovar e fechar avança o card); senão a reserva dos
// modais. Com um modal aberto por cima, o foco é dele e fica onde está.
//
// Sem card na frente porque a fila ACABOU com a ampliação aberta — aprovar a
// foto do ÚLTIMO pedido e fechar, a aprovação que pousa com a foto fechada —, o
// lugar dele é o botão do painel que tomou o lugar do card (`botaoDoPainelDoFim`).
// Ia pro ⓘ da Ajuda, no topo da página: o que o R7-2-06 tirou do ✕ ↑ ✓, de volta
// pela foto ampliada (auditoria de 2026-10-03, R8-3-06, MEDIDO nos dois motores).
//
// E sem card E sem painel — a fila acabou com a próxima página ainda no ar (o
// esqueleto na tela) —, o foco ia pro ⓘ e FICAVA lá quando o painel ou o card
// novo chegavam (auditoria de 2026-10-06, R9-3-02, MEDIDO nos dois motores). Ele é
// PROMETIDO a quem chegar, pela régua do `aplicarFocoDoTeclado`
// (`focoDoTeclado`, aqui a lista `noCard`): o card, ao mesmo lugar dele (a foto
// ou o mapa); o painel, ao botão dele. Até lá ele fica onde a camada o largou,
// como o do ✕ ↑ ✓ do último card decidido pelo teclado. Só com a sessão de pé:
// sem ela (a queda fecha as camadas, `fecharCamadasAbertas`) não vem card, e
// vale a reserva.
function devolverFocoDaAmpliacao(quem, noCard) {
    if (topOpenModal()) return;
    const card = cardDaFrente();
    const painel = card ? null : botaoDoPainelDoFim();
    const candidatos = [quem, ...(card ? noCard.map((s) => card.querySelector(s)) : [painel])];
    for (const el of candidatos) {
        if (!el || el === document.body || dentroDeCamada(el) || !focavelNaTela(el)) continue;
        try { el.focus({ preventScroll: true }); } catch (e) { continue; }
        if (document.activeElement === el) return;
    }
    if (!card && !painel && AppState.authenticated) { focoDoTeclado = noCard.slice(); return; }
    devolverFoco(null);
}

// O botão do painel que toma o lugar do card quando a fila ACABA, o caminho de
// volta: "Tentar de novo" na falha ao carregar, "Verificar novamente" no "Tudo
// limpo!"/"Fim da fila". É a régua do `aplicarFocoDoTeclado` sem card (R7-2-06;
// test/lightbox-foco-card confere que os dois escolhem o MESMO botão). Sem
// painel na tela — a busca ainda corre —, nenhum.
function botaoDoPainelDoFim() {
    const naTela = (id) => {
        const p = document.getElementById(id);
        return !!p && !p.classList.contains('hidden');
    };
    return naTela('loadErrorState') ? document.getElementById('retryLoadBtn')
        : naTela('noMoreCards') ? document.getElementById('reloadBtn') : null;
}

// O foco PERDIDO: no <body>, ou num elemento que saiu da página.
function focoPerdido() {
    const a = document.activeElement;
    return !a || a === document.body || !a.isConnected;
}

// Nenhuma camada por cima do card (modal, foto ou mapa ampliados).
function semCamadaAberta() {
    return !topOpenModal() && !(typeof Lightbox !== 'undefined' && Lightbox.isOpen())
        && !(typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen());
}

// Uma escrita do lightbox que POUSA (ou volta) com a foto já fechada TROCA ou
// REDESENHA o card da frente — e o foco que estava nele caía no <body>: o
// fechar da foto o devolve à foto do card (L12), a aprovação pousa e o card
// anda (`tirarAprovadoDaFila`), a exclusão sem Desfazer pousa ou o Desfazer
// pela tecla z devolve a foto e o card é redesenhado (`showCurrentPlace`).
// MEDIDO nos três, no Chromium e no WebKit (auditoria de 2026-09-30, R5-3-07,
// a família do C10). O foco vai ao equivalente no card que ficou: a foto ou o
// mapa dele. Só quando o foco ESTAVA no card — quem o pôs ali foi o app, ao
// fechar a ampliação; o foco que a pessoa levou a outro lugar fica onde está.
//
// `mesmoBotao`: o redesenho é do MESMO pedido, e o foco num ✕ ↑ ✓ vai ao MESMO
// botão do card novo — travado ou ausente, ao ✕ (que agora pode estar vivo) ou
// ao ↑; senão, a foto ou o mapa. É o card "sem foto" que o sinal de volta
// redesenha (`recuperarCardSemFoto`): o ↑ era o único botão vivo, o teclado
// estava nele, e o foco caía no <body> (R8-4-03, MEDIDO no Chromium: "foco
// antes: card-btn-skip · foco depois: BODY", com a foto que volta e com a que o
// Waze tirou do ar).
function mantendoFocoNoCard(redesenhar, { mesmoBotao = false } = {}) {
    const card = cardDaFrente();
    const a = document.activeElement;
    const estavaNoCard = !!(card && a && a !== document.body && card.contains(a));
    const botao = mesmoBotao && estavaNoCard && typeof a.matches === 'function'
        ? ['.card-btn-reject', '.card-btn-skip', '.card-btn-read'].find((s) => a.matches(s)) : null;
    redesenhar();
    if (estavaNoCard && focoPerdido() && semCamadaAberta()) {
        devolverFocoDaAmpliacao(null, [...(botao ? [botao, '.card-btn-reject', '.card-btn-skip'] : []), '.card-image', '.card-map']);
    }
}

// O foco não pode CAIR no <body> com a foto ampliada aberta: ela é
// `aria-modal`, e o Tab recomeçaria do topo da página, atrás da camada.
// Quando o controle com o foco some ou trava — a edição do nome fechando, o
// "Aprovar" virando lixeira travada na janela —, o foco vai pra pílula do nome
// e, travada ou ausente, pro ✕ do lightbox, que é onde ele nasce ao abrir.
// Quem já está num controle vivo da camada (ou no Desfazer, que entra na volta
// do Tab dela) não é mexido.
//
// Com a EDIÇÃO do nome aberta, o foco vai primeiro ao CAMPO do nome. A trava que
// acende com o foco no ✓ "Salvar nome" (a sessão caindo com a extensão
// renovando, a conferência de um 401) o desabilita; a pílula é rótulo na
// edição, e o foco ia pro ✕ que FECHA A FOTO: o Enter seguinte — de quem estava
// no ✓ justamente pra salvar — fechava a foto e jogava fora o nome digitado
// (auditoria de 2026-10-03, R8-3-04, MEDIDO nos dois motores). No campo, o
// Enter diz o que esperar e a edição fica aberta (`confirmarRenomear`). Quem
// estava no ✓ chegou pelo Tab, a partir do campo: está no teclado físico.
function manterFocoNoLightbox() {
    if (!Lightbox.isOpen()) return;
    const lb = document.getElementById('imageLightbox');
    const atual = document.activeElement;
    if (atual && atual !== document.body && focavelNaTela(atual)
        && (lb.contains(atual) || (atual.closest && atual.closest('#undoContainer')))) return;
    const alvos = editandoNome() ? ['lightboxNomeInput', 'lightboxNomeBtn', 'lightboxClose'] : ['lightboxNomeBtn', 'lightboxClose'];
    for (const id of alvos) {
        const el = document.getElementById(id);
        if (!focavelNaTela(el)) continue;
        try { el.focus({ preventScroll: true }); } catch (e) { continue; }
        if (document.activeElement === el) return;
    }
}

// Entre limpar uma região viva e dizer nela de novo a MESMA frase (ver
// `dizerNaRegiao`). O atraso da conversa (`PRESENCA_ANUNCIO_DE_NOVO_MS`, R12-5-02)
// e o da CDK do Angular, pelo mesmo motivo.
const ANUNCIO_DE_NOVO_MS = 100;
// A frase A CAMINHO de cada região (região → relógio dela).
const anunciosDeNovo = new Map();

// Escreve `texto` na região viva `el` — a da foto ampliada e a do card. A MESMA
// frase que a região JÁ diz era reescrita igual, e região viva reescrita com o
// mesmo texto pode não ser lida de novo (o precedente do R12-5-02, na conversa;
// leitor de tela não há aqui pra medir). Calava dois desfechos (auditoria da
// rodada 14, R14-3-01, MEDIDO com um MutationObserver nos dois motores): o
// Desfazer de uma exclusão depois de navegar até a foto — a região seguia com
// "Foto 1 de 3" da navegação, e a foto que volta dizia "Foto 1 de 3" de novo (o
// R9-3-05 prometeu que ela é anunciada) —, e, sem o Desfazer, a segunda exclusão
// seguida ("Foto excluída" duas vezes). Agora a região que já diz a frase é
// limpa AGORA e a frase volta `ANUNCIO_DE_NOVO_MS` depois. Frase diferente sai na
// hora, como sempre. Quem chega com a região RECÉM-LIMPA por aqui (uma frase
// ainda a caminho) só troca a frase e a adia: escrever já seria limpar e
// escrever sem o atraso no meio. Sem texto, a região se esvazia na hora, e a
// frase a caminho não sai. A frase a caminho só sai se a região SEGUE limpa —
// outro anúncio escrito nela nesse meio (o card novo, o fim da fila) vale, e
// ela não fala por cima dele — e se a tela ainda é a dela (`aindaDaTela`).
function dizerNaRegiao(el, texto, aindaDaTela) {
    const frase = texto || '';
    const recemLimpa = anunciosDeNovo.has(el) && !el.textContent;
    clearTimeout(anunciosDeNovo.get(el));
    anunciosDeNovo.delete(el);
    if (!frase || (!recemLimpa && el.textContent !== frase)) { el.textContent = frase; return; }
    if (el.textContent) el.textContent = '';
    anunciosDeNovo.set(el, setTimeout(() => {
        anunciosDeNovo.delete(el);
        if (!el.textContent && aindaDaTela()) el.textContent = frase;
    }, ANUNCIO_DE_NOVO_MS));
}

// O que o leitor de tela OUVE da foto ampliada, pela região viva DELA
// (`#lightboxAnuncio`, `sr-only`: nada muda na tela). A troca de foto e, no
// caminho SEM o Desfazer, o desfecho de aprovar, excluir e renomear — com o
// Desfazer quem anuncia é o banner dele. Eles mudavam a tela e nada era dito
// (R6-3-08, auditoria de 2026-10-01). `place`: o desfecho que chega depois do
// gesto só é dito com a foto DESTE pedido aberta — com a de outro na tela, "Foto
// aprovada" falaria da foto errada. Sem texto, a região se esvazia (ao fechar).
// A mesma frase outra vez sai depois de a região ser limpa (`dizerNaRegiao`,
// R14-3-01), com a foto deste pedido ainda aberta.
function anunciarNoLightbox(texto, place) {
    const el = document.getElementById('lightboxAnuncio');
    if (!el) return;
    if (place !== undefined && !(Lightbox.isOpen() && Lightbox.place === place)) return;
    dizerNaRegiao(el, texto, () => Lightbox.isOpen() && (place === undefined || Lightbox.place === place));
}

// O desfecho de uma escrita da foto que FECHOU a camada é dito pela região viva
// do CARD (`#cardLiveRegion`), pra onde o foco foi. Sem o Desfazer, excluir a
// ÚLTIMA foto do local fecha a foto ampliada (`removerFoto`) antes do anúncio,
// e a região dela já não fala: o foco ia pro mapa do card e nada dizia que a
// foto saiu — o card é redesenhado com o MESMO pedido, então nem o "Novo
// pedido" sai (`pedidoAnunciado`; auditoria de 2026-10-02, R7-3-04, MEDIDO nos
// dois motores). A mesma frase outra vez — a segunda exclusão seguida com a foto
// já fechada — sai depois de a região ser limpa (`dizerNaRegiao`, R14-3-01), só
// com a sessão de pé: a tela de entrada limpa esta região (`showAuthScreen`), e
// o desfecho de uma foto não é dito lá.
function anunciarNoCard(texto) {
    const el = document.getElementById('cardLiveRegion');
    if (el) dizerNaRegiao(el, texto, () => AppState.authenticated === true);
}

// O desfecho de uma escrita da foto SEM o Desfazer (a exclusão, o nome), dito
// onde a pessoa está. Com a foto DESTE pedido aberta, pela região da camada
// (R6-3-08). Com ela FECHADA antes da resposta — a pessoa fechou a foto e seguiu
// no card —, a região da camada não fala, e o card do local é redesenhado sem a
// foto (ou com o nome novo) com o MESMO pedido na frente, então nem o "Novo
// pedido" sai (`pedidoAnunciado`): o leitor de tela não ouvia que valeu
// (auditoria de 2026-10-06, R9-3-05, MEDIDO nos dois motores). Aí vale a região
// do CARD, como no desfecho que fecha a camada (R7-3-04) — só com um card DESTE
// local na frente (o pedido, ou um irmão, que recebe a mesma escrita:
// `aplicarNosIrmaos`) e nenhuma camada por cima. Com outro local na tela, ou
// outra camada aberta, o desfecho não é do que se vê, e nada é dito.
//
// A camada aberta pode ser a de um IRMÃO do mesmo local: a pessoa decidiu o
// pedido, o irmão veio pra frente e ela abriu a foto dele com a escrita no ar. A
// escrita muda a camada dele junto (`aplicarNosIrmaos`) — a foto sai da tela e a
// contagem cai, a pílula e o `alt` ganham o nome novo — e nada era dito, nem
// pela camada nem pelo card (auditoria de 2026-10-07, R10-3-02, MEDIDO nos dois
// motores). Ela fala pela região dela, com o mesmo texto, quando é de um irmão
// NA FILA — o que o `aplicarNosIrmaos` alcança; uma camada que ele não alcançou
// não mudou, e o desfecho não é dela.
//
// `soDosIrmaos`: o desfecho de uma escrita feita COM o Desfazer, que pousa
// depois da janela (auditoria da rodada 11, R11-3-05). O banner já disse o
// desfecho no gesto, e a tela do PRÓPRIO pedido mudou ali (a foto saiu, o nome
// trocou); o que muda quando o Waze confirma é a do IRMÃO — a camada dele aberta,
// ou o card dele na frente —, e só ela fala. Com a camada ou o card do próprio
// pedido na tela, nada é dito de novo.
function anunciarDesfechoDaFoto(texto, place, soDosIrmaos = false) {
    const aberta = Lightbox.isOpen() ? Lightbox.place : null;
    const irmaoAberto = !!aberta && aberta !== place && !!place && place.venueID != null
        && aberta.venueID === place.venueID
        && ((AppState.queue || []).includes(aberta) || filaRealComDevolvidos().includes(aberta));
    if (aberta && (aberta === place || irmaoAberto)) {
        if (!(soDosIrmaos && aberta === place)) anunciarNoLightbox(texto, aberta);
        return;
    }
    const frente = AppState.currentPlace;
    if (!place || place.venueID == null || !frente || frente.venueID !== place.venueID) return;
    if (soDosIrmaos && frente === place) return;
    if (semCamadaAberta()) anunciarNoCard(texto);
}

// O desfecho que FECHA a camada pode chegar com o card TROCADO pelo próprio
// fechamento: a aprovação que pousou esperando a foto fechar anda a fila
// (`avancarSeAprovado`) — aprovar a foto proposta e excluí-la (a lixeira é o
// caminho de volta da aprovação) num local em que ela é a única foto. O card
// seguinte ("Novo pedido: …") ou o fim da fila ("Tudo limpo!") é dito na MESMA
// tarefa, e "Foto excluída" por cima o apagava: o leitor de tela ouvia só "Foto
// excluída", e o card novo nem seria dito depois (`pedidoAnunciado` já é ele)
// (auditoria de 2026-10-03, R8-3-07, MEDIDO nos dois motores). Lido ANTES de
// fechar, devolve quem diz o desfecho DEPOIS: com o card trocado, as duas frases
// vão juntas, na ordem em que aconteceram; sem troca, só o desfecho (R7-3-04).
// "Trocado" é o card da FRENTE que mudou, não o pedido da foto: com a foto de
// outro pedido aberta (o Desfazer de um ✕ devolveu outro à frente, L22), o
// fechamento só tira o aprovado pela identidade, e nada novo foi dito.
function anuncioDoCardAoFechar() {
    const regiao = document.getElementById('cardLiveRegion');
    const frenteAntes = AppState.currentPlace;
    const ditoAntes = regiao ? regiao.textContent : '';
    return (texto) => {
        const agora = regiao ? regiao.textContent : '';
        const frente = AppState.currentPlace;
        // O card que entrou foi dito (o `renderCurrentCard` diz o pedido que
        // MUDA). Sem card, só o painel do fim que APARECEU escreve: a busca que
        // ainda corre e a falha (que o painel dela diz sozinho, `role="alert"`)
        // não escrevem nada, e o que a região tem é do card que SAIU.
        const disseOQueVeio = frente !== frenteAntes && !!agora && (!!frente || agora !== ditoAntes);
        anunciarNoCard(disseOQueVeio ? texto + '. ' + agora : texto);
    };
}

// Quantos pixels a MAIS no maior lado da foto ampliada fazem o zoom se ver (ver
// `Lightbox.ampliada`): abaixo disto a foto é 1× pra quem lê a escala. O zoom
// invisível MEDIDO foi de 1,5 px (um evento de roda de 1 px) a 7 px (12 eventos
// de 0,4 px) numa foto de 800; o primeiro zoom de verdade (um dente de roda, ou o
// + do teclado, 1,2×) passa de 160 px.
const ZOOM_VISIVEL_PX = 8;

const Lightbox = {
    urls: [],
    idx: 0,
    newIdx: -1,
    placeName: '',
    // Estado de zoom/pan (gestos estilo visualizador de fotos: pinch,
    // double-tap, arrastar pra trocar/fechar quando sem zoom)
    scale: 1,
    tx: 0,
    ty: 0,
    // A foto (a URL) de quem é o zoom de agora: o `_render` só o zera quando a
    // foto na tela MUDA (R11-3-04). Abrir começa do 1× porque o `close` já o
    // zera — e a camada fechada não redesenha.
    _fotoComZoom: null,
    isOpen() {
        return !document.getElementById('imageLightbox').classList.contains('hidden');
    },
    open(urls, startIdx, newImageIdx, placeName, eDenuncia, place) {
        if (!urls || urls.length === 0) return;
        // O place vem EXPLÍCITO em vez de sair do AppState: a lixeira grava no
        // Waze, e ler o alvo de uma variável global é como se apaga a foto do
        // card errado quando a fila anda embaixo de um lightbox aberto.
        this.place = place || null;
        // CÓPIA, nunca a lista do pedido: o card passa `place.imageUrls`, e com
        // o mesmo array nas duas mãos o `devolverFoto` (Desfazer de uma
        // exclusão) recolocava a foto no pedido e o `recolocarFoto` a achava
        // JÁ presente e saía sem acertar o ✨ nem redesenhar — com o lightbox
        // reaberto dentro da janela, o selo apontava a foto errada e a foto do
        // pedido deixava de poder ser aprovada (auditoria de 2026-09-26). Cada
        // mão mexe na sua, e quem mexe nas duas (`removerFoto`, `devolverFoto`)
        // já as trata separadas.
        this.urls = urls.slice();
        this.idx = Math.max(0, Math.min(startIdx || 0, urls.length - 1));
        this.newIdx = (newImageIdx !== undefined && newImageIdx !== null) ? newImageIdx : -1;
        this.eDenuncia = !!eDenuncia;
        // A PROPOSTA que já está entre as aprovadas não leva o ✨: ela deixou de
        // ser "a foto em decisão". O card a aponta pelo pedido (`fotosDoCard`), e
        // o pedido segue na tela até a resposta da aprovação: aprovada com o
        // Desfazer e despachada ao fechar a foto, a camada REABERTA pelo card
        // voltava com o ✨ na foto que a pessoa acabou de aprovar e com o
        // "Aprovar" e a lixeira no mesmo canto — e, com a resposta, o "Aprovar"
        // vivo por cima da lixeira, sem fazer nada (auditoria de 2026-10-07,
        // R10-3-04, MEDIDO nos dois motores). A 🚩 fica: a foto denunciada é
        // uma das aprovadas por definição (ela está no mapa).
        if (!this.eDenuncia && this.newIdx >= 0 && this.idAprovadoDaFoto(this.urls[this.newIdx])) this.newIdx = -1;
        this.placeName = placeName || '';
        // Quem abriu (a foto do card, que tem `tabindex="-1"` pra isso): é pra
        // ela que o foco volta no fechamento (ver `devolverFocoDaAmpliacao`).
        this._quemAbriu = document.activeElement;
        CamadaVoltar.empilhar();
        document.getElementById('imageLightbox').classList.remove('hidden');
        document.body.style.overflow = 'hidden';
        const closeBtn = document.getElementById('lightboxClose');
        if (closeBtn) closeBtn.focus(); // foco entra no lightbox (Esc/Enter acessíveis)
        const hint = document.getElementById('lightboxZoomHint');
        if (hint) {
            hint.classList.remove('hidden');
            clearTimeout(this._hintTimer);
            this._hintTimer = setTimeout(() => hint.classList.add('hidden'), 4000);
        }
        this._render();
        mostrarNomeNoLightbox();
    },
    close({ viaHistorico = false } = {}) {
        fecharEdicaoNome();
        if (!this.isOpen()) return;
        if (!viaHistorico) CamadaVoltar.consumir();
        document.getElementById('imageLightbox').classList.add('hidden');
        // Aprovou aqui dentro? O pedido está resolvido no Waze, então o card sai
        // agora — decisão do owner: ficar visível enquanto se olham as outras
        // fotos, e avançar ao fechar. Fica DEPOIS de esconder o lightbox pra o
        // card novo não aparecer por baixo de uma camada que ainda está aberta.
        avancarSeAprovado();
        if (!topOpenModal()) document.body.style.overflow = '';
        const img = document.getElementById('lightboxImage');
        img.removeAttribute('src');
        // E o NOME do local e o de quem mandou a foto (a pílula, a contagem e o
        // `alt`): ficavam no DOM do lightbox fechado, até na tela de entrada
        // depois do "Sair" (auditoria de 2026-10-02, R6-1-05). O `alt` volta ao
        // vazio do HTML; abrir escreve tudo de novo (`_render`, `mostrarNomeNoLightbox`).
        img.alt = '';
        const contagem = document.getElementById('lightboxCount');
        if (contagem) { contagem.textContent = ''; contagem.removeAttribute('title'); contagem.classList.add('hidden'); }
        const nome = document.getElementById('lightboxNomeTxt');
        if (nome) nome.textContent = '';
        this.resetZoom();
        // A camada SOLTA o pedido. Ele seguia aqui depois de fechar, e a escrita
        // que terminava com a foto já fechada — a exclusão sem o Desfazer, com a
        // foto fechada antes da resposta — achava "a foto deste pedido aberta" e
        // REDESENHAVA a camada escondida: pedia a foto de novo e refazia a tira
        // (MEDIDO, a `src` do #lightboxImage voltando depois de fechar). Agora
        // só o que está na tela recebe o resultado, pela régua de sempre
        // (`pedidoAindaNaTela`): o pedido e os irmãos na fila, sim; a camada
        // fechada, não — ela nasce de novo do card no próximo `open`. As
        // miniaturas da tira (as fotos do pedido) saem junto, como a foto
        // grande já saía.
        this.place = null;
        this.urls = [];
        this.idx = 0;
        this.newIdx = -1;
        this.eDenuncia = false;
        this.placeName = '';
        const tira = document.getElementById('lightboxStrip');
        if (tira) { tira.innerHTML = ''; tira.dataset.chave = ''; }
        // O anúncio era DESTA foto (e o da renomeação leva o nome do local):
        // não fica no DOM depois de ela fechar.
        anunciarNoLightbox('');
        // DEPOIS do avanço: se o card andou, o foco vai pro card NOVO.
        const quem = this._quemAbriu;
        this._quemAbriu = null;
        devolverFocoDaAmpliacao(quem, ['.card-image', '.card-map']);
        // O "Como funciona" que esperava a camada fechar — e o card que o
        // `avancarSeAprovado` montou aqui em cima pediu o dele no mesmo tique
        // do voltar pendente (R7-3-01): os dois decidem depois, na microtarefa.
        aoFecharCamada(viaHistorico);
    },
    prev() {
        if (this.urls.length < 2) return;
        this.idx = (this.idx - 1 + this.urls.length) % this.urls.length;
        this._render();
        this._anunciarFoto();
    },
    next() {
        if (this.urls.length < 2) return;
        this.idx = (this.idx + 1) % this.urls.length;
        this._render();
        this._anunciarFoto();
    },
    // A foto TROCOU (‹ ›, as setas, o arraste, a tira): quem usa leitor de tela
    // não ficava sabendo — o foco fica onde estava (o ✕) e nada era anunciado,
    // nem qual foto estava na tela nem se era a proposta (R6-3-08, auditoria de
    // 2026-10-01). Vai pela região viva da camada, com a posição e o selo — o
    // MESMO termo do selo desenhado (✨/🚩) e da tira.
    _anunciarFoto() {
        const n = this.urls.length;
        if (n < 2) return;
        const vars = { i: this.idx + 1, n };
        const comSelo = this.idx === this.newIdx && this.newIdx >= 0;
        anunciarNoLightbox(comSelo
            ? t('lightbox.anuncio.fotoSelo', { ...vars, selo: t(this.eDenuncia ? 'card.flaggedPhoto.title' : 'card.newPhoto.title') })
            : t('lightbox.anuncio.foto', vars));
    },
    resetZoom() {
        this.scale = 1;
        this.tx = 0;
        this.ty = 0;
        this._applyTransform();
    },
    // A foto está AMPLIADA DE VERDADE? A régua ÚNICA de quem lê a escala: as
    // setas (andam, ou trocam de foto e o ↓ fecha), o arraste (anda, ou troca e
    // fecha), o duplo toque (volta a 1× ou amplia) e o `panBy`. O zoom que não
    // se VÊ é 1×, e o `zoomTo` usa a MESMA conta pra decidir quando o afastar
    // volta a 1× exato. Cada um perguntava `=== 1` ou `> 1`: um fio de zoom pra
    // DENTRO — a roda fina e a pinça lenta do trackpad, que o R7-3-03 deixou
    // começar a ampliar a partir de 1× — parava a escala em 1,00073, invisível
    // (a foto de 800 px com 801), e a → ANDAVA a foto 80 px em vez de trocá-la, o
    // ↓ a andava em vez de fechar e o arraste nem trocava nem fechava: o R6-3-05
    // de volta por outra porta (auditoria de 2026-10-03, R8-3-01, MEDIDO no
    // Chromium com um evento de roda de −0,4 px).
    //
    // E a régua é em PIXELS NA TELA, não em fração da escala: os 0,1% de antes
    // cobriam só o PRIMEIRO evento da roda fina. Um evento de roda de −1 px (o
    // menor que o WebKit entrega) dava 1,00182 — a foto de 800 px com 801,5 —, 12
    // eventos de −0,4 px davam 1,00879 (+7 px) e a pinça com 0,5 px de tremor,
    // 1,0025: tudo invisível, e de novo as setas andavam a foto, o ↓ não fechava,
    // o arraste não trocava e o duplo toque não ampliava (auditoria de
    // 2026-10-06, R9-3-01, MEDIDO nos dois motores). Menos de `ZOOM_VISIVEL_PX` a
    // mais no MAIOR lado da foto é 1×. O tamanho é o da caixa da <img> SEM a
    // transformação (`offsetWidth`): com `object-contain` e `max-w/h-full`, a
    // caixa É a foto. Sem foto na tela (carregando, quebrada) não há pixel pra
    // medir, e vale a fração de antes (0,1%).
    ampliada() {
        if (!(this.scale > 1)) return false;
        const img = document.getElementById('lightboxImage');
        const lado = img ? Math.max(img.offsetWidth || 0, img.offsetHeight || 0) : 0;
        if (!lado) return this.scale > 1.001;
        return (this.scale - 1) * lado >= ZOOM_VISIVEL_PX;
    },
    zoomTo(scale, cx, cy) {
        // cx/cy em coordenadas de viewport; mantém o ponto tocado sob o dedo
        const img = document.getElementById('lightboxImage');
        const rect = img.getBoundingClientRect();
        const prevScale = this.scale;
        this.scale = Math.max(1, Math.min(4, scale));
        // A roda e o trackpad aproximam e afastam por PRODUTO de fatores
        // (1,2^(Δ/100)), e ir e voltar na mesma medida não dá 1 exato: MEDIDO,
        // dois dentes de 53 px pra dentro e dois pra fora param em
        // 1,0000000000000002. A tela parece 1×, mas as setas passavam a ANDAR a
        // foto em vez de trocá-la, o ↓ não fechava e o arraste não trocava nem
        // fechava — tudo isso pergunta `=== 1` ou `> 1` (R6-3-05, auditoria de
        // 2026-10-01). O zoom que não se vê (a régua do `ampliada`, em pixels) é
        // 1× — AFASTANDO. Aproximando, não: partindo de 1×, cada evento da roda e da
        // pinça do trackpad é aplicado sobre a escala de agora, e todo evento
        // abaixo de ~0,55 px (1,2^0,0055 = 1,001) caía de volta em 1. A roda fina
        // e a pinça LENTA do trackpad (centenas de eventos de 0,2 a 0,4 px) nunca
        // começavam a ampliar (auditoria de 2026-10-02, R7-3-03, MEDIDO no
        // Chromium: 301 eventos e a escala parada em 1). Quem aproxima quer zoom,
        // por menor que seja o passo; quem afasta até perto de 1 quer o 1× exato.
        // O "perto de 1" é a régua de quem LÊ a escala (`ampliada`, R8-3-01): o
        // passo pequeno pra dentro fica guardado, e até passar dela a foto segue
        // sendo 1× pras setas, o arraste e o duplo toque.
        if (this.scale < prevScale && !this.ampliada()) this.scale = 1;
        if (this.scale === 1) {
            this.tx = 0;
            this.ty = 0;
        } else if (cx !== undefined) {
            // O `rect` já inclui a transformação: o centro dele é o centro
            // VISUAL (o de layout + t). Com d = dedo − centro visual, o ponto sob
            // o dedo fica parado quando t' = t + d·(1 − r). A fórmula de antes,
            // (t − d)·r + d, só coincide com esta quando t = 0 — depois do
            // primeiro zoom a foto ESCORREGAVA t·(r − 1) a cada passo da pinça
            // (auditoria de 2026-09-25; invariante em test/lightbox-zoom).
            const imgCx = rect.left + rect.width / 2;
            const imgCy = rect.top + rect.height / 2;
            const ratio = this.scale / prevScale;
            this.tx = this.tx + (cx - imgCx) * (1 - ratio);
            this.ty = this.ty + (cy - imgCy) * (1 - ratio);
        }
        this._applyTransform();
    },
    // Um passo de zoom pelo TECLADO (+ e −), no CENTRO da camada — sem cursor, é
    // pra onde a pessoa está olhando. O passo é o de um dente da roda (1,2×,
    // ver o `wheel` do `setupLightbox`): cada ampliação com a sua régua, e a do
    // mapa dá um nível por tecla como dá por dente (L33).
    zoomPeloTeclado(sentido) {
        const lb = document.getElementById('imageLightbox');
        const r = lb ? lb.getBoundingClientRect() : null;
        const cx = r ? r.left + r.width / 2 : undefined;
        const cy = r ? r.top + r.height / 2 : undefined;
        this.zoomTo(this.scale * Math.pow(1.2, sentido > 0 ? 1 : -1), cx, cy);
    },
    panBy(dx, dy) {
        if (!this.ampliada()) return;
        this.tx += dx;
        this.ty += dy;
        this._applyTransform();
    },
    _applyTransform() {
        const img = document.getElementById('lightboxImage');
        if (!img) return;
        img.style.transform = this.scale === 1 && this.tx === 0 && this.ty === 0
            ? ''
            : `translate(${this.tx}px, ${this.ty}px) scale(${this.scale})`;
    },
    _render() {
        // O zoom e o deslocamento são da FOTO na tela. Trocar de foto (‹ ›, as
        // setas, a tira, a que volta pelo Desfazer, a que sai da tela) recomeça
        // em 1×; a MESMA foto redesenhada segue ampliada onde a pessoa a deixou.
        // O `_render` zerava sempre, e o redesenho que não troca a foto — a
        // RESPOSTA da aprovação (que marca a foto de novo, R10-3-04), o ✨ que
        // volta na falha, a exclusão de OUTRA foto do pedido que pousa — tirava o
        // zoom de quem conferia a fachada: com o Desfazer, uns 3 s depois do
        // toque em "Aprovar" a foto voltava a 1× sozinha (auditoria da rodada 11,
        // R11-3-04, MEDIDO nos dois motores; a da exclusão já existia antes).
        const naTela = this.urls[this.idx];
        if (naTela !== this._fotoComZoom) this.resetZoom();
        this._fotoComZoom = naTela;
        const img = document.getElementById('lightboxImage');
        img.src = urlDaFoto(this.urls[this.idx]);
        // O MESMO texto do card (ver `altDaFoto`), com a posição desta foto.
        img.alt = altDaFoto(this.place || { name: this.placeName }, this.idx + 1, this.urls.length);
        const prevBtn = document.getElementById('lightboxPrev');
        const nextBtn = document.getElementById('lightboxNext');
        const count = document.getElementById('lightboxCount');
        const badge = document.getElementById('lightboxNewBadge');
        const multiple = this.urls.length > 1;
        prevBtn.classList.toggle('hidden', !multiple);
        nextBtn.classList.toggle('hidden', !multiple);
        // A pílula do canto passa a dizer DUAS coisas: qual foto e de quando.
        // Vai junto porque é o mesmo assunto ("a foto que estou vendo") e
        // porque espaço no lightbox é disputado — elemento novo brigaria com
        // fechar, selo, dica de zoom, ações e a tira. Com uma foto só, o
        // "1 / 1" seria ruído: fica só a idade.
        const ms = this.dataDaFotoAtual();
        const idade = idadeDaFoto(ms);
        const autor = this.autorDaFotoAtual();
        // Ordem: QUAL foto · DE QUEM · DE QUANDO. Posição, identidade, tempo —
        // é a que se lê sem tropeçar, e foi a escolhida pelo owner nos mockups.
        //
        // Montado com nós, não com `textContent` de uma string só, porque o
        // NOME vem da rede e precisa encolher sozinho: no Galaxy Fold a pílula
        // com `world_onm8fgfi` media 260px e ATROPELAVA o ✕ (medido por
        // hit-test). Só o nome tem `text-overflow`; contador e idade são
        // `flex:none` e sobrevivem sempre — cortar a idade seria perder a
        // informação que já existia pra caber a que chegou depois.
        //
        // `textContent` em cada nó, nunca innerHTML: nome de usuário é dado de
        // terceiro.
        const partes = [];
        if (multiple) partes.push({ txt: `${this.idx + 1} / ${this.urls.length}`, fixo: true });
        if (autor) partes.push({ txt: autor, fixo: false });
        if (idade) partes.push({ txt: idade, fixo: true });
        count.classList.toggle('hidden', partes.length === 0);
        count.textContent = '';
        partes.forEach((parte, i) => {
            if (i) {
                const sep = document.createElement('span');
                sep.className = 'lb-pill-fixo';
                sep.textContent = ' · ';
                count.appendChild(sep);
            }
            const n = document.createElement('span');
            n.className = parte.fixo ? 'lb-pill-fixo' : 'lb-pill-nome';
            n.textContent = parte.txt;
            count.appendChild(n);
        });
        // A data exata fica no title: a forma curta responde "é velha?", que é
        // a pergunta de decisão; quem precisar do dia tem onde olhar.
        if (ms) count.title = new Date(ms).toLocaleString(i18nLocale());
        else count.removeAttribute('title');
        badge.textContent = this.eDenuncia ? '🚩' : '✨';
        const chaveSelo = this.eDenuncia ? 'card.flaggedPhoto.title' : 'card.newPhoto.title';
        badge.setAttribute('data-i18n-title', chaveSelo);
        badge.title = t(chaveSelo);
        // O NOME que o leitor de tela ouve: sem ele o selo chegava como o emoji
        // ("brilhos", "bandeira") colado no texto da pílula ao lado (auditoria de
        // 2026-09-26). `role="img"` está no HTML; o nome é o mesmo do `title`.
        badge.setAttribute('data-i18n-aria', chaveSelo);
        badge.setAttribute('aria-label', t(chaveSelo));
        badge.classList.toggle('hidden', this.idx !== this.newIdx);
        // No treino as duas ações de foto NÃO existem: elas escrevem no mapa e
        // não têm ensaio possível. Some em vez de desabilitar — botão morto com
        // cara de vivo lê como app quebrado, e "desabilitado" convida à pergunta
        // "por que não posso?", que num treino não tem resposta boa.
        atualizarAcoesDeFoto();
        this._renderTira();
        // A ação com o foco é DESTA foto: trocar de foto pelo teclado (← → com o
        // foco no "Aprovar" ou na lixeira) a escondia, e o foco caía no <body>
        // com a camada `aria-modal` aberta — o Tab seguinte recomeçava atrás
        // dela (R6-3-06, auditoria de 2026-10-01, MEDIDO nos dois motores). O
        // foco vai à pílula do nome, senão ao ✕; não à ação que ocupou o lugar,
        // que pode ser a lixeira — um Enter a mais apagaria uma foto.
        manterFocoNoLightbox();
    },
    // Todas as fotos do local de uma vez, tocáveis pra pular direto.
    //
    // O problema que resolve: 32% dos pedidos da fila real têm 2+ fotos (até 7),
    // e hoje só dá pra tatear no `‹ ›` sem saber quantas faltam nem o que vem.
    // Em `FLAGGED_PHOTO` e `NEW_PHOTO` isso é a própria decisão — "esta, entre
    // estas" e "a proposta ao lado das que o local já tem".
    _renderTira() {
        const tira = document.getElementById('lightboxStrip');
        const lb = document.getElementById('imageLightbox');
        if (!tira || !lb) return;
        const varias = this.urls.length > 1;
        lb.classList.toggle('com-tira', varias);
        tira.classList.toggle('hidden', !varias);
        if (!varias) { tira.innerHTML = ''; tira.dataset.chave = ''; return; }
        // Reconstrói só quando a LISTA muda. Excluir uma foto muda; trocar de
        // foto não — e recriar a cada troca perderia a rolagem da tira e
        // rebaixaria as miniaturas já carregadas.
        const chave = this.urls.join('|');
        if (tira.dataset.chave !== chave) {
            tira.innerHTML = '';
            this.urls.forEach((u, i) => {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'lb-mini';
                const im = document.createElement('img');
                // a MESMA URL da foto grande: já está em cache (ver a nota acima).
                // `urlDaFoto` é o que a torna a mesma — com o offline ligado a
                // grande leva o sufixo, e a crua seria outra cópia, baixada à toa
                // com sinal e quebrada sem ele.
                im.src = urlDaFoto(u);
                im.alt = '';
                im.decoding = 'async';
                im.loading = 'lazy';
                b.appendChild(im);
                b.addEventListener('click', () => { this.idx = i; this._render(); this._anunciarFoto(); });
                tira.appendChild(b);
            });
            tira.dataset.chave = chave;
        }
        [...tira.children].forEach((b, i) => {
            const atual = i === this.idx;
            b.classList.toggle('atual', atual);
            b.setAttribute('aria-current', atual ? 'true' : 'false');
            // O selo vai junto: sem ele a tira mostra N fotos iguais e esconde
            // qual delas É o pedido — que é a única coisa que importa aqui. E
            // vai no NOME também: o selo desenhado é `aria-hidden`, e quem usa
            // leitor de tela ouvia "Ver foto 2 de 3" nas três sem saber qual era
            // a proposta (auditoria de 2026-09-26). O termo é o do selo grande.
            const comSelo = i === this.newIdx && this.newIdx >= 0;
            b.setAttribute('aria-label', comSelo
                ? t('lightbox.strip.itemSelo', { i: i + 1, n: this.urls.length,
                    selo: t(this.eDenuncia ? 'card.flaggedPhoto.title' : 'card.newPhoto.title') })
                : t('lightbox.strip.item', { i: i + 1, n: this.urls.length }));
            const velho = b.querySelector('.lb-mini-selo');
            if (velho) velho.remove();
            if (comSelo) {
                const selo = document.createElement('span');
                selo.className = 'lb-mini-selo';
                selo.setAttribute('aria-hidden', 'true');
                selo.textContent = this.eDenuncia ? '🚩' : '✨';
                b.appendChild(selo);
            }
        });
        const atual = tira.children[this.idx];
        if (atual && atual.scrollIntoView) atual.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    },
    // A foto aberta é a PENDENTE deste pedido e este editor pode aprovar?
    //
    // `newIdx` é o índice do ✨, derivado do `updateRequestID` — então "a foto
    // pendente" é exatamente a que este card propõe. Denúncia (🚩) fica de
    // fora: ali a foto JÁ está no mapa e o que se decide é outra coisa.
    //
    // E o pedido tem que ser de FOTO NOVA, com a foto aberta sendo a DELE (a URL
    // traz o id do pedido): aprovar é `approve: true` no `validar-place`, que
    // num pedido de local NOVO aprovaria o LOCAL — a regra de ouro inteira. O
    // `newIdx` sozinho não prova nada: ele é estado da tela, e uma continuação
    // de OUTRO pedido chegou a escrevê-lo aqui (ver `desmarcarAprovada`).
    //
    // E o pedido cuja aprovação JÁ POUSOU (ele só espera esta foto fechar pra
    // sair da fila, `placeResolvidoPorAprovacao`) não se aprova de novo: seria
    // uma segunda escrita ao Waze ("já tratado") e o "Restam" descendo duas
    // vezes pelo mesmo pedido — o que a aprovação pousada depois da queda deixava
    // acontecer (R6-3-01). É aqui, e não só no toque, porque esta função decide
    // também se o botão APARECE: o que a tela mostra e o que ela aceita juntos.
    //
    // E a foto que JÁ está entre as aprovadas não se aprova: ela é da lixeira
    // (`idFotoAtual`), pela MESMA régua (`idAprovadoDaFoto`). Com as duas
    // perguntas lendo a mesma lista, o "Aprovar" e a lixeira nunca disputam o
    // canto — o slot é exclusivo por construção, e não por cada caminho que
    // mexe no ✨ lembrar de tirá-lo (R10-3-04: a camada reaberta com a
    // aprovação no ar mostrava os dois).
    podeAprovarAtual() {
        const p = this.place;
        if (!p || this.eDenuncia) return false;
        if (p === placeResolvidoPorAprovacao) return false;
        if (p.purType !== 'NEW_PHOTO') return false;
        if (this.idx !== this.newIdx || this.newIdx < 0) return false;
        if (!p.venueID || !p.updateRequestID) return false;
        if ((this.urls[this.idx] || '').indexOf(String(p.updateRequestID)) === -1) return false;
        if (this.idAprovadoDaFoto(this.urls[this.idx])) return false;
        return podeAgirComoL6Aqui();   // mesmo portão, decisão do owner
    },
    // O id que a foto desta URL tem entre as APROVADAS do pedido aberto (a foto
    // já está no mapa), ou nulo. A URL traz o id da foto, como no
    // `indiceDaFoto`. É a régua ÚNICA de "aprovada" da camada: a lixeira
    // (`idFotoAtual`) é dela, e o "Aprovar" (`podeAprovarAtual`) e o ✨ da
    // proposta (`open`) são do contrário.
    idAprovadoDaFoto(url) {
        const p = this.place;
        const ids = p && Array.isArray(p.approvedImageIds) ? p.approvedImageIds : [];
        const u = String(url || '');
        return ids.find((id) => id && u.indexOf(id) !== -1) || null;
    },
    // Depois de aprovada, a foto passa a estar no mapa: o ✨ some e ela entra
    // na lista de excluíveis — o botão vira lixeira sozinho.
    //
    // As duas recebem o ALVO (o pedido e a foto), nunca leem o `this.place`:
    // quem chama pode ser uma resposta que chegou DEPOIS de a pessoa fechar
    // este lightbox e abrir o de outro pedido. Lendo o de agora, a falha tardia
    // de uma aprovação punha o ✨ — e o botão de aprovar — na foto de OUTRO
    // pedido, até de um local novo.
    //
    // E a foto é achada pelo ID na lista de AGORA, nunca pelo índice que ela
    // tinha no gesto: excluir uma foto ANTERIOR à proposta, com a aprovação no
    // ar, desloca os índices (`removerFoto`). Pelo índice, a aprovação que
    // voltava deixava o ✨ e o "Aprovar" na proposta — e dava pra aprová-la DE
    // NOVO, com o "Restam" caindo duas vezes —, e a que falhava devolvia o ✨ à
    // foto SEGUINTE (auditoria de 2026-09-26).
    marcarComoAprovada(alvo) {
        const p = alvo.place;
        if (p && Array.isArray(p.approvedImageIds) && !p.approvedImageIds.includes(alvo.id)) p.approvedImageIds.push(alvo.id);
        if (this.place !== p) return;
        const i = this.indiceDaFoto(alvo.id);
        if (i >= 0 && this.newIdx === i) this.newIdx = -1;
        if (this.isOpen()) this._render();
    },
    desmarcarAprovada(alvo) {
        const p = alvo.place;
        if (p && Array.isArray(p.approvedImageIds)) p.approvedImageIds = p.approvedImageIds.filter((x) => x !== alvo.id);
        if (this.place !== p) return;
        this.newIdx = this.indiceDaFoto(alvo.id);
        if (this.isOpen()) this._render();
    },
    // Outro editor TRATOU o pedido antes desta aprovação (L30): a foto deixa de
    // ser a PROPOSTA — sem ✨ e sem "Aprovar", o pedido acabou —, mas também não
    // entra nas aprovadas: quem tratou pode tê-la recusado, e a lixeira
    // ofereceria apagar o que não está no mapa. Sem ação nenhuma, que é o que
    // se sabe dela.
    esquecerProposta(alvo) {
        const p = alvo.place;
        if (p && Array.isArray(p.approvedImageIds)) p.approvedImageIds = p.approvedImageIds.filter((x) => x !== alvo.id);
        if (this.place !== p) return;
        const i = this.indiceDaFoto(alvo.id);
        if (i >= 0 && this.newIdx === i) this.newIdx = -1;
        if (this.isOpen()) this._render();
    },
    // Onde está, na lista aberta AGORA, a foto deste id (-1 se ela saiu). A
    // URL traz o id da foto, como no `idFotoAtual` e no `podeAprovarAtual`.
    indiceDaFoto(id) {
        if (id === undefined || id === null || id === '') return -1;
        return this.urls.findIndex((u) => String(u || '').indexOf(String(id)) !== -1);
    },
    // Devolve o id da foto aberta SÓ se ela puder ser excluída — as duas
    // perguntas numa função só, de propósito: separadas, uma delas acaba
    // esquecida em algum caminho novo e a lixeira aparece onde não deve.
    //
    // Excluível é a foto JÁ APROVADA (o core manda `approvedImageIds`). A
    // pendente — a do ✨ — ainda não está no mapa: tirá-la por aqui apagaria a
    // imagem e deixaria o pedido órfão, sem ninguém tratar. O caminho dela é o
    // ✕/✓ do card.
    // A data da foto ABERTA. Busca pelo id contido na URL, mesmo padrão do
    // `idFotoAtual` — o índice não identifica foto (o carrossel reordena).
    dataDaFotoAtual() {
        const mapa = this.place && this.place.imageDates;
        if (!mapa) return null;
        const url = this.urls[this.idx] || '';
        const id = Object.keys(mapa).find((k) => k && url.indexOf(k) !== -1);
        return id ? mapa[id] : null;
    },
    // QUEM mandou a foto aberta. Duas fontes, e a ordem importa:
    //
    //  1. `imageAuthors` (o `creatorUserId` da própria foto). É a única
    //     atribuição que vale pro carrossel inteiro — MEDIDO: 23,7% dos locais
    //     têm fotos de pessoas DIFERENTES, então herdar o autor do pedido
    //     estaria errado num de cada quatro. E aqui se APROVA e se EXCLUI: uma
    //     atribuição errada numa tela dessas é o pior lugar possível.
    //  2. Só a foto do ✨ — a proposta NESTE pedido, que ainda não está no mapa
    //     e por isso não tem `creatorUserId` — cai no `createdBy` do pedido.
    //     Aí não há ambiguidade: o card é de UM pedido, e quem o enviou enviou
    //     essa foto. É o mesmo par que o WME mostra.
    //
    // Sem nenhuma das duas, devolve null e a pílula simplesmente não fala do
    // assunto — mesmo comportamento do contador quando há uma foto só.
    autorDaFotoAtual() {
        const p = this.place;
        if (!p) return null;
        const url = this.urls[this.idx] || '';
        const mapa = p.imageAuthors;
        if (mapa) {
            const id = Object.keys(mapa).find((k) => k && url.indexOf(k) !== -1);
            if (id && mapa[id]) return String(mapa[id]);
        }
        if (this.newIdx >= 0 && this.idx === this.newIdx && p.createdBy) return String(p.createdBy);
        return null;
    },
    idFotoAtual() {
        const p = this.place;
        if (!p || !p.venueID || !Number.isFinite(Number(p.lat)) || !Number.isFinite(Number(p.lon))) return null;
        if (!podeExcluirFotoAqui()) return null;
        // A régua de "aprovada" é UMA, e o "Aprovar" pergunta o contrário dela
        // (R10-3-04, ver `podeAprovarAtual`).
        return this.idAprovadoDaFoto(this.urls[this.idx]);
    },
    // Recoloca a foto na posição em que estava — usado pelo Desfazer e quando o
    // envio falha. Sem isto, desfazer devolveria a foto pro fim da lista e a
    // pessoa veria a ordem mudar sozinha.
    //
    // A foto que volta passa a ser a da TELA: é uma troca de foto, e a troca é
    // dita como as outras (`_anunciarFoto`: a posição e o selo). O Desfazer de
    // uma exclusão com a foto aberta a trazia de volta calado — o ✨ mudava de
    // lugar e quem usa leitor de tela ouvia só o banner saindo, enquanto o
    // Desfazer do ✕ do card diz o pedido que voltou (auditoria de 2026-10-06,
    // R9-3-05, MEDIDO nos dois motores).
    //
    // `eraSelo`: a foto que volta era a do selo (a 🚩 de um pedido de foto
    // denunciada). O `removerFoto` tira o selo junto com ela, e sem isto o
    // Desfazer a devolvia SEM o 🚩 na camada aberta — o card, redesenhado,
    // mostrava o selo, e o anúncio dizia "Foto 1 de 2" sem ele (achado de
    // passagem do lote 13, medido com os métodos de verdade).
    //
    // `eDenuncia`: QUAL selo ela tinha, o do gesto (o alvo da exclusão o guarda).
    // A camada REABERTA pelo card dentro da janela do Desfazer nasce sem a foto
    // denunciada — o card já não a tem —, e com ela o `open` recebe
    // `eDenuncia: false`: o Desfazer (ou a exclusão que falha) devolvia a foto com
    // o selo no lugar certo e do TIPO errado, o ✨ "Foto nova proposta neste
    // pedido" sobre a foto DENUNCIADA, na camada, na tira e no anúncio (auditoria
    // de 2026-10-07, R10-3-01, MEDIDO nos dois motores). Sem o tipo, fica o da
    // camada.
    recolocarFoto(url, idx, eraSelo = false, eDenuncia = this.eDenuncia) {
        if (!url || this.urls.some((u) => u === url)) return;
        const pos = Math.max(0, Math.min(idx, this.urls.length));
        this.urls.splice(pos, 0, url);
        if (eraSelo === true) { this.newIdx = pos; this.eDenuncia = eDenuncia === true; }
        else if (this.newIdx >= pos) this.newIdx += 1;
        this.idx = pos;
        if (!this.isOpen()) return;
        this._render();
        this._anunciarFoto();
    },
    // Tira a foto da lista aberta depois que o Waze confirmou. Sem fila e sem
    // recarregar: quem está olhando quer ver a foto sumir.
    //
    // `place` é o do PEDIDO que excluiu (o padrão é o aberto): a confirmação
    // pode chegar com o lightbox já em outro pedido, e aí só o dado muda.
    removerFoto(id, place = this.place) {
        const p = place;
        const fora = (u) => u.indexOf(id) === -1;
        if (p) {
            if (Array.isArray(p.imageUrls)) p.imageUrls = p.imageUrls.filter(fora);
            if (Array.isArray(p.approvedImageIds)) p.approvedImageIds = p.approvedImageIds.filter(x => x !== id);
            p.imageUrl = (p.imageUrls && p.imageUrls[0]) || null;
        }
        if (this.place !== p) return;
        // O índice da foto que SAIU, achado pelo id — não o da foto na tela: a
        // confirmação pode chegar com a pessoa já em outra foto do carrossel.
        const saiu = this.urls.findIndex((u) => !fora(u));
        if (saiu < 0) return;
        this.urls = this.urls.filter(fora);
        if (!this.urls.length) { this.close(); return; }
        // O ✨ é apontado por ÍNDICE; tirar uma foto antes dele desloca tudo.
        if (this.newIdx > saiu) this.newIdx -= 1;
        else if (this.newIdx === saiu) this.newIdx = -1;
        if (this.idx > saiu) this.idx -= 1;
        this.idx = Math.min(this.idx, this.urls.length - 1);
        this._render();
    }
};

// ═══════════════════════════════════════════════════════════════════════════
//  O portão dos recursos destrutivos: L6 + Area Manager, ou staff
// ═══════════════════════════════════════════════════════════════════════════
//
// O app tem DOIS níveis, e o par é deliberado:
//   · ENTRAR é L2+AM (`isUserAllowed`, no core) — é o portão de verdade, no
//     SERVIDOR, e é ele que impede que qualquer um com cookies do Waze use o app.
//   · AGIR de forma destrutiva é L6+AM — este aqui, só do CLIENTE.
//
// Só do cliente é decisão, não esquecimento: o Waze valida `permissions` e
// `lockRank` na gravação, então quem não pode por aqui também não consegue por
// lá. Isto nunca foi fronteira de segurança — é trava de produto pra o recurso
// não aparecer pra qualquer editor na NOSSO app. Houve um espelho no servidor,
// com cache de perfil pra não custar caro, e SAIU: a chamada que ele exigia era
// a mais lenta das três (977ms medidos) e existia pra reconfirmar o que o Waze
// reconfirma de novo ao gravar (gotcha #59).
//
// O nome NÃO fala de foto de propósito. Ele já guardava três recursos — excluir
// foto, aprovar foto e renomear local — e chamá-lo de "excluir foto" fazia cada
// novo call site parecer estranho, o que empurra a próxima pessoa a
// re-implementar `rank >= 5` em vez de delegar. `test/gates.test.mjs` reprova
// quem re-implementar.
//
// Recurso novo entra por uma função PRÓPRIA que delega (ver `podeRenomearAqui`),
// nunca chamando esta direto: são decisões de produto que hoje COINCIDEM, e se
// um dia o owner separar uma delas, o call site não muda.
function podeAgirComoL6Aqui() {
    const p = AppState.profile;
    if (!p) return false;
    if (p.isStaff) return true;
    // Rank CRU do Waze, 0-indexed: 5 aqui é o L6 que o editor vê (gotcha #15).
    const rank = Number.isInteger(p.rank) ? p.rank : parseInt(p.rank, 10);
    return rank >= 5 && !!p.isAreaManager;
}

// Excluir foto: o primeiro recurso a usar o portão, e agora um delegador como
// os outros dois. Existir como função própria — em vez de o call site chamar a
// base — é o que mantém a invariante que o teste cobra: NENHUM recurso fala
// direto com `podeAgirComoL6Aqui`, cada um tem o seu nome. Assim, separar um
// deles um dia é editar uma função, não caçar call sites.
function podeExcluirFotoAqui() {
    return podeAgirComoL6Aqui();
}

// A RODA do mouse e o trackpad, como ZOOM da foto e do mapa ampliados.
//
// Os dois tratavam cada EVENTO como um passo: o trackpad manda dezenas de
// eventos pequenos por gesto, e MEDIDO no mapa, 20 eventos de deltaY −4 (menos
// que UM dente de mouse, que é 100) subiam o zoom de 17 pra 19; na foto, cada
// um multiplicava por 1,2. E a rolagem só HORIZONTAL (deltaY 0) caía no ramo do
// "afastar": 6 rolagens pro lado levavam o mapa do 17 ao 11 (auditoria de
// 2026-09-26). Aqui o delta vira PIXELS (a roda em modo linha ou página
// multiplica) e só a vertical conta — a horizontal, pura ou a que domina, não
// é zoom (0). Quem usa decide a escala: o mapa ACUMULA até um dente por nível,
// a foto aplica proporcional (um dente dá o 1,2× de antes).
const RODA_DENTE_PX = 100;

function deltaDaRoda(e) {
    const escala = e.deltaMode === 1 ? 40 : e.deltaMode === 2 ? (window.innerHeight || 800) : 1;
    const dy = (Number(e.deltaY) || 0) * escala;
    const dx = (Number(e.deltaX) || 0) * escala;
    if (!dy || Math.abs(dx) > Math.abs(dy)) return 0;
    return dy;
}

// O DUPLO TOQUE da foto e do mapa ampliados: dois toques em até 300 ms e a
// até 40 px um do outro (a régua que a foto sempre usou). E o que separa um
// TOQUE de um ARRASTE no mapa: o dedo real treme 1 a 3 px (o "touch slop" do
// Android é 8 dp), e o mapa tratava QUALQUER movimento como arraste — com 1 px
// de tremor o duplo toque não aproximava, enquanto a foto aproximava com 3
// (auditoria de 2026-09-26). 10 px fica acima do tremor e abaixo do que já é
// arrastar de propósito.
const DUPLO_TOQUE_MS = 300;
const DUPLO_TOQUE_RAIO_PX = 40;
const TOQUE_FOLGA_PX = 10;

// Gestos do mapa ampliado. Ponteiros unificados (mouse e dedo pelo mesmo
// caminho) porque o mapa é o mesmo nos dois; o que muda é só quantos pontos
// tocam a tela.
function setupMapaLightbox() {
    const lb = document.getElementById('mapaLightbox');
    if (!lb) return;
    document.getElementById('mapaLbClose').addEventListener('click', () => MapaLightbox.close());
    document.getElementById('mapaLbMais').addEventListener('click', () => MapaLightbox.zoom(1));
    document.getElementById('mapaLbMenos').addEventListener('click', () => MapaLightbox.zoom(-1));
    document.getElementById('mapaLbCentrar').addEventListener('click', () => MapaLightbox.recentrar());

    // Os listeners de mover/soltar vão na JANELA, não no elemento.
    //
    // A primeira versão usava `setPointerCapture` no próprio mapa e PERDIA o
    // arrasto: medido, só 2 de 14 movimentos chegavam e o `pointerup` nunca
    // vinha. O motivo é o próprio redesenho — `desenhar()` remove e recria os
    // <img> dos tiles no meio do gesto, e a captura não sobrevive a isso.
    // Escutar na janela não depende de nenhum elemento continuar existindo.
    //
    // E o desenho é AGENDADO por quadro em vez de rodar a cada evento: mover o
    // dedo dispara dezenas de eventos por segundo, e reposicionar 20 tiles em
    // cada um trava a mão. Mesma lição do gotcha #35 — o handler decide, o
    // quadro seguinte escreve.
    const ativos = new Map();
    let acumX = 0, acumY = 0, quadro = 0, arrastou = false, ultimo = null, distPinch = 0, inicio = null;
    // O gesto teve DOIS dedos (a pinça, ou um toque de dois dedos) ou começou
    // com outro botão do mouse que não o principal: não é toque.
    let multitoque = false, botaoPrincipal = true;
    // Duplo toque aproxima, como em qualquer mapa — com a MESMA régua da foto
    // (tempo E distância entre os toques), e zerando depois, como a foto: um
    // terceiro toque não aproxima de novo.
    //
    // Decidido no SOLTAR do ponteiro, e não no `click`: o `pointerdown` do mapa
    // chama `preventDefault()` (sem ele o mouse arrasta a <img> do tile como
    // imagem), e no WebKit — o Safari, e TODO navegador do iPhone — o toque que
    // teve o `pointerdown` impedido NÃO gera `click`. MEDIDO no WebKit do
    // Playwright com toque de verdade: 2 toques no mapa → 0 `click`, zoom 17 →
    // 17; no Chromium, 2 e 18 (auditoria de 2026-09-29, L20). O `click` só
    // funcionava no Android. A foto já decide o duplo toque pelos ponteiros.
    let ultimoToque = 0, ultimoToqueX = 0, ultimoToqueY = 0;
    const tocou = (x, y) => {
        const agora = Date.now();
        if (agora - ultimoToque < DUPLO_TOQUE_MS && Math.hypot(x - ultimoToqueX, y - ultimoToqueY) < DUPLO_TOQUE_RAIO_PX) {
            ultimoToque = 0;
            MapaLightbox.zoom(1, x, y);
            return;
        }
        ultimoToque = agora; ultimoToqueX = x; ultimoToqueY = y;
    };
    const aplicar = () => {
        quadro = 0;
        const dx = acumX, dy = acumY;
        acumX = acumY = 0;
        if (dx || dy) MapaLightbox.arrastar(dx, dy);
    };
    const agendar = () => { if (!quadro) quadro = requestAnimationFrame(aplicar); };
    const doisDedos = () => {
        const [a, b] = [...ativos.values()];
        return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, d: Math.hypot(a.x - b.x, a.y - b.y) };
    };
    const mover = (e) => {
        if (!ativos.has(e.pointerId)) return;
        ativos.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (ativos.size >= 2) {
            const c = doisDedos();
            // Um degrau por DOBRO de distância: é a relação natural do pinch e
            // não dispara com tremor de dedo.
            if (distPinch > 0 && (c.d / distPinch > 1.6 || distPinch / c.d > 1.6)) {
                MapaLightbox.zoom(c.d > distPinch ? 1 : -1, c.x, c.y);
                distPinch = c.d;
            }
            arrastou = true;
            return;
        }
        if (!ultimo) return;
        const dx = e.clientX - ultimo.x, dy = e.clientY - ultimo.y;
        if (!dx && !dy) return;
        // O mapa acompanha o dedo desde o primeiro pixel, mas só é ARRASTE (e
        // não um toque que tremeu) passada a folga — ver `TOQUE_FOLGA_PX`.
        if (inicio && Math.hypot(e.clientX - inicio.x, e.clientY - inicio.y) > TOQUE_FOLGA_PX) arrastou = true;
        ultimo = { x: e.clientX, y: e.clientY };
        acumX += dx; acumY += dy;
        agendar();
    };
    const soltar = (e) => {
        if (!ativos.has(e.pointerId)) return;
        ativos.delete(e.pointerId);
        if (ativos.size === 0) {
            ultimo = null;
            removeEventListener('pointermove', mover);
            removeEventListener('pointerup', soltar);
            removeEventListener('pointercancel', soltar);
            if (quadro) { cancelAnimationFrame(quadro); aplicar(); }
            // Um dedo que desceu e subiu sem arrastar é um TOQUE (ver `tocou`).
            // O `pointercancel` é o navegador tomando o gesto: não é toque.
            if (e.type !== 'pointercancel' && !arrastou && !multitoque && botaoPrincipal) tocou(e.clientX, e.clientY);
        } else {
            const p0 = [...ativos.values()][0];
            ultimo = { x: p0.x, y: p0.y };
        }
    };
    lb.addEventListener('pointerdown', (e) => {
        // Botão é botão, e LINK é link: o Street View é um <a>, e o
        // `preventDefault` daqui embaixo, no WebKit, mata o `click` dele — no
        // iPhone o toque nele não abria nada (0 de 2, com o ↗ do card abrindo
        // 2 de 2; L20). O `touch-none` da camada já segura o gesto nativo.
        if (e.target.closest('button, a')) return;
        e.preventDefault();
        ativos.set(e.pointerId, { x: e.clientX, y: e.clientY });
        arrastou = false;
        if (ativos.size === 1) { multitoque = false; botaoPrincipal = !(e.button > 0); }
        if (ativos.size === 2) { distPinch = doisDedos().d; multitoque = true; }
        else { ultimo = { x: e.clientX, y: e.clientY }; inicio = ultimo; }
        addEventListener('pointermove', mover);
        addEventListener('pointerup', soltar);
        addEventListener('pointercancel', soltar);
    });
    // Roda do mouse: o desktop não tem pinch. Um nível por DENTE acumulado
    // (ver `deltaDaRoda`): o trackpad chega lá somando os eventos pequenos. O
    // acumulado recomeça com o gesto (pausa de 250 ms) e com a troca de sentido,
    // e depois de cada nível — um evento grande de roda acelerada dá UM nível,
    // como sempre deu. O `preventDefault` vale pra toda roda, a horizontal
    // inclusive: sem ele o trackpad do Mac rola a página de trás ou volta uma
    // página no histórico.
    let rodaAcum = 0, rodaEm = 0;
    lb.addEventListener('wheel', (e) => {
        e.preventDefault();
        const dy = deltaDaRoda(e);
        if (!dy) return;
        const agora = performance.now();
        if (agora - rodaEm > 250 || Math.sign(dy) !== Math.sign(rodaAcum)) rodaAcum = 0;
        rodaEm = agora;
        rodaAcum += dy;
        if (Math.abs(rodaAcum) < RODA_DENTE_PX) return;
        const passo = rodaAcum < 0 ? 1 : -1;
        rodaAcum = 0;
        MapaLightbox.zoom(passo, e.clientX, e.clientY);
    }, { passive: false });
    // Girar o aparelho muda a caixa: sem redesenhar, sobra faixa sem tile.
    addEventListener('resize', () => { if (MapaLightbox.isOpen()) MapaLightbox.desenhar(); });
}

function setupLightbox() {
    const lb = document.getElementById('imageLightbox');
    const img = document.getElementById('lightboxImage');
    // As ações de foto só existem com a foto NA TELA (`fotoDoLightboxNaTela`):
    // ela chega depois do `_render`, e a que falha não chega nunca.
    img.addEventListener('load', atualizarAcoesDeFoto);
    img.addEventListener('error', atualizarAcoesDeFoto);
    document.getElementById('lightboxClose').addEventListener('click', () => Lightbox.close());
    document.getElementById('lightboxPrev').addEventListener('click', (e) => { e.stopPropagation(); Lightbox.prev(); });
    document.getElementById('lightboxNext').addEventListener('click', (e) => { e.stopPropagation(); Lightbox.next(); });
    // O fundo é um passo pra trás — editando o nome, só sai da edição.
    lb.addEventListener('click', (e) => {
        if (e.target === lb) recuarNaFoto();
    });
    // O toque nas ações TRAVADAS da foto (o "Aprovar", a lixeira, a pílula do
    // nome) responde com o porquê, como o ✕ ↑ ✓ do card (C14, ver
    // `avisarTravaAoTocar`): elas travam pela MESMA função
    // (`aplicarTravaDeAcao`) e ficavam caladas — com o "Marcar todos" no ar, o
    // toque no "Aprovar" não dizia nada (auditoria de 2026-10-02, R7-3-07,
    // MEDIDO nos dois motores). Botão `disabled` não recebe `click`, mas o
    // `pointerdown`/`pointerup` chegam e sobem até a camada; o par no MESMO
    // botão é o "clique". A pílula que é RÓTULO na edição não trava as ações
    // (`acoesTravadas`), e aí o aviso sai calado.
    // E o ✓ "Salvar nome" da edição (R8-3-03): travado pela MESMA trava (a
    // sessão renovando, a conferência de um 401), o toque nele ficava calado,
    // enquanto o Enter no campo, na mesma trava, dizia "Espere a conferência…"
    // (`confirmarRenomear`) — o mesmo gesto com duas respostas (MEDIDO nos dois
    // motores). Desabilitado só por estar vazio ou igual ao nome de agora, ele
    // segue calado: aí não há trava (`avisarTravaAoTocar` sai sem ela).
    let tocouTravada = null;
    const acaoTravada = (ev) => {
        const b = ev.target && ev.target.closest
            && ev.target.closest('#lightboxApprove, #lightboxDelete, #lightboxNomeBtn, #lightboxNomeOk');
        return b && b.disabled ? b : null;
    };
    lb.addEventListener('pointerdown', (ev) => { tocouTravada = acaoTravada(ev); });
    lb.addEventListener('pointerup', (ev) => {
        const b = acaoTravada(ev);
        if (b && b === tocouTravada) avisarTravaAoTocar();
        tocouTravada = null;
    });

    // ── Gestos (Pointer Events): pinch zoom, double-tap, pan, swipe ──
    const pointers = new Map();
    let pinchStartDist = 0;
    let pinchStartScale = 1;
    let lastTapTime = 0;
    let lastTapX = 0;
    let lastTapY = 0;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragging = false;

    img.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        img.setPointerCapture(e.pointerId);
        pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

        if (pointers.size === 2) {
            const [a, b] = [...pointers.values()];
            pinchStartDist = Math.hypot(b.x - a.x, b.y - a.y);
            pinchStartScale = Lightbox.scale;
            dragging = false;
            return;
        }

        // Double-tap → alterna zoom no ponto tocado (a régua é a do mapa também).
        // "Ampliada" é a régua única (`ampliada`, R8-3-01): num fio de zoom
        // invisível o toque duplo amplia, em vez de "voltar" ao 1× que a tela já
        // mostra.
        const now = performance.now();
        if (now - lastTapTime < DUPLO_TOQUE_MS && Math.hypot(e.clientX - lastTapX, e.clientY - lastTapY) < DUPLO_TOQUE_RAIO_PX) {
            lastTapTime = 0;
            if (Lightbox.ampliada()) Lightbox.resetZoom();
            else Lightbox.zoomTo(2.5, e.clientX, e.clientY);
            return;
        }
        lastTapTime = now;
        lastTapX = e.clientX;
        lastTapY = e.clientY;

        dragging = true;
        dragStartX = e.clientX;
        dragStartY = e.clientY;
    });

    img.addEventListener('pointermove', (e) => {
        if (!pointers.has(e.pointerId)) return;
        const prev = pointers.get(e.pointerId);
        pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

        if (pointers.size === 2) {
            const [a, b] = [...pointers.values()];
            const dist = Math.hypot(b.x - a.x, b.y - a.y);
            if (pinchStartDist > 0) {
                const cx = (a.x + b.x) / 2;
                const cy = (a.y + b.y) / 2;
                Lightbox.zoomTo(pinchStartScale * (dist / pinchStartDist), cx, cy);
            }
            return;
        }

        if (Lightbox.ampliada()) {
            Lightbox.panBy(e.clientX - prev.x, e.clientY - prev.y);
        }
    });

    const endPointer = (e) => {
        if (!pointers.has(e.pointerId)) return;
        pointers.delete(e.pointerId);
        if (pointers.size < 2) pinchStartDist = 0;

        // Sem zoom: swipe horizontal troca foto, vertical pra baixo fecha
        // (editando o nome, sai só da edição — ver `recuarNaFoto`). "Sem zoom"
        // é a régua única (`ampliada`, R8-3-01), não o 1 exato.
        if (dragging && pointers.size === 0 && !Lightbox.ampliada()) {
            const dx = e.clientX - dragStartX;
            const dy = e.clientY - dragStartY;
            if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)) {
                if (dx < 0) Lightbox.next();
                else Lightbox.prev();
            } else if (dy > 80 && Math.abs(dy) > Math.abs(dx)) {
                recuarNaFoto();
            }
        }
        if (pointers.size === 0) dragging = false;
    };
    img.addEventListener('pointerup', endPointer);
    img.addEventListener('pointercancel', endPointer);

    // Desktop: scroll do mouse dá zoom no cursor — PROPORCIONAL ao delta (ver
    // `deltaDaRoda`): um dente de mouse dá o 1,2× de sempre, e o trackpad, que
    // manda dezenas de eventos pequenos, um zoom contínuo em vez de 1,2× por
    // evento. Rolagem só horizontal não é zoom (afastava). O teto de 3 dentes
    // por evento segura a roda em modo PÁGINA, que chega com centenas.
    lb.addEventListener('wheel', (e) => {
        if (!Lightbox.isOpen()) return;
        e.preventDefault();
        const dy = Math.max(-3 * RODA_DENTE_PX, Math.min(3 * RODA_DENTE_PX, deltaDaRoda(e)));
        if (!dy) return;
        Lightbox.zoomTo(Lightbox.scale * Math.pow(1.2, -dy / RODA_DENTE_PX), e.clientX, e.clientY);
    }, { passive: false });
}

function openLightbox(urls, startIdx, newImageIdx, placeName, eDenuncia, place) {
    Lightbox.open(urls, startIdx, newImageIdx, placeName, eDenuncia, place);
}

// ── Excluir a foto aberta ─────────────────────────────────────────────────
//
// SEM diálogo de confirmação, por decisão do owner: a pessoa já fez três gestos
// deliberados pra chegar aqui (abrir a foto, navegar até ela, mirar num alvo
// pequeno), e perguntar de novo é desconfiar dela. No lugar entra a JANELA DE
// DESFAZER que o app já usa no swipe — que não desfaz depois, ADIA o envio.
//
// A janela respeita a preferência do editor, igual ao swipe. Quem a desligou
// paga o preço da própria escolha: a exclusão vai na hora, e não há volta —
// medimos que re-adicionar a foto não persiste (o Waze responde 200 com
// `synced: true` e ignora).
//
// A janela daqui NÃO usa o `AppState.pendingAction` do card, e isso é
// deliberado: lá a trava existe porque a próxima ação despacharia a anterior,
// mas prender ✕/↑/✓ por 3s porque alguém apagou uma foto no lightbox seria
// efeito colateral sem motivo.
let exclusaoPendente = null;   // { id, place, timer, enviar, desfazer }

// A VEZ de cada local nas escritas da LISTA DE FOTOS: as exclusões (auditoria de
// 2026-10-07, R10-3-03) e as aprovações (R11-3-01, logo abaixo). O Waze não
// apaga uma foto: ele SUBSTITUI a lista inteira do local (gotcha #57), e o
// servidor monta essa lista a partir da releitura guardada, que só é regravada
// DEPOIS de a escrita voltar. Com o Desfazer, a exclusão que já tinha saído (a
// janela venceu) e esperava o Waze não segurava a próxima do MESMO local: ela
// saía 3 s depois, o servidor relia a lista de ANTES da primeira — com a foto
// que ela tirou — e a última escrita a chegar ganhava. Uma das duas exclusões
// se desfazia no Waze com as DUAS respostas `success: true`, e a tela mostrando
// as duas fotos fora (MEDIDO no navegador, nos dois motores, e no core). Sem o
// Desfazer não acontecia: a lixeira fica travada até a resposta
// (`excluindoAgora`).
//
// O ENVIO da próxima espera a resposta da anterior do mesmo local; o GESTO não:
// a lixeira segue livre, e a foto seguinte sai da tela na hora, como sempre.
// Cada exclusão entra na vez do local quando sai pro Waze (`enviarExclusao`) e a
// solta quando termina, dê certo ou não. Sem outra do local no ar, nada espera.
// A vez vale também com a página SAINDO (a descarga da janela): sem esperar, as
// duas cruzariam no servidor, que desfaz uma delas; esperando, a segunda se
// perde se a página morrer antes da resposta da primeira — a mesma perda, e a
// espera é a que acerta quando a página só foi pro fundo e volta.
//
// A MESMA foto pode ser excluída de novo pela foto ampliada de um IRMÃO do local
// — o irmão só a perde quando a primeira pousa (`aplicarNosIrmaos`) —, e a
// segunda não vai ao Waze: iria só pra voltar "já excluída", e a tela diria
// "Outro editor já tinha excluído 👍" sobre a exclusão da própria pessoa. Quem
// lembra que ela saiu é a página, não a vez (`fotosQueSairamDoMapa`, R12-3-02).
//
// A APROVAÇÃO de uma foto do local entra na MESMA vez (auditoria da rodada 11,
// R11-3-01): ela também muda a lista do local (a pendente vira aprovada), e o
// servidor ESQUECE a lista guardada quando ela pousa. Com o Desfazer, a exclusão
// de X que já tinha saído (a janela venceu) não segurava a aprovação de P, do
// mesmo local: ela saía e pousava, a resposta da exclusão chegava depois e
// regravava a lista de antes (P pendente), e a exclusão seguinte, nos 15 s dela,
// mandava P de volta como `approved: false` — a tela com P aprovada e a lixeira,
// e no Waze a foto de volta a pendente, sem pedido nenhum (MEDIDO de ponta a
// ponta, no navegador e no core). Agora a aprovação espera a exclusão do local
// no ar, e a exclusão espera a aprovação; o servidor também não recria a lista
// que sumiu no meio da exclusão (`handleExcluirFoto`). O renomear fica de fora:
// ele grava só o nome (PATCH), não a lista.
//
// O AQUECIMENTO da lixeira (a leitura do local que o toque dispara, `preparar`)
// entra também, como uma leitura (auditoria da rodada 12, R12-3-01): fora da
// vez, ele podia voltar DEPOIS de uma escrita do local e guardar no servidor a
// lista de antes dela (ver o `pedirExclusaoDaFoto`). Menos com a página SAINDO:
// a escrita não espera um aquecimento — a página morreria antes da resposta
// dele, e a escrita, que saía na hora com `keepalive`, sumia. A da janela, que a
// descarga despacha, nem entra na espera (`soAquecimentoNaFrente` +
// `API.saindo`); e a que JÁ esperava (a janela venceu com o Waze lento) é solta
// pela descarga (`vezLiberada`, auditoria da rodada 13, R13-3-01). Sem esperar,
// quem garante que o aquecimento que volta depois não estraga nada é o
// servidor: a lista dele mora numa chave do GESTO, que só a exclusão daquele
// gesto lê (R13-3-02 e R13-3-03, `chaveDoToque` no core). Uma ESCRITA na frente
// segue sendo esperada, como acima.
//
// `tipo`: 'excluir', 'aprovar' ou 'aquecer'. `exclusoes`: quantas escritas da
// vez são exclusões — com uma no ar, a pílula do nome do local trava
// (`exclusaoDoLocalNoAr`, R11-3-06); o aquecimento não trava nada. `escritas`:
// quantas não são aquecimento.
const escritasDeFotoNoLocal = new Map();   // venueID → { ultima, n, exclusoes, escritas }

function vezDasFotosNoLocal(alvo, tipo) {
    const local = alvo.place.venueID;
    let vez = escritasDeFotoNoLocal.get(local);
    if (!vez) { vez = { ultima: null, n: 0, exclusoes: 0, escritas: 0 }; escritasDeFotoNoLocal.set(local, vez); }
    const anterior = vez.ultima;
    const soAquecimentoNaFrente = vez.escritas === 0;
    let soltar;
    vez.ultima = new Promise((ok) => { soltar = ok; });
    vez.n++;
    const excluir = tipo === 'excluir';
    const escrita = tipo !== 'aquecer';
    if (excluir) vez.exclusoes++;
    if (escrita) vez.escritas++;
    const v = vez;
    return {
        anterior,                                   // nula: a vez já é desta
        soAquecimentoNaFrente,                      // na frente, só aquecimento (ou nada)
        soltar: () => {
            soltar();
            if (excluir) v.exclusoes--;
            if (escrita) v.escritas--;
            if (--v.n === 0 && escritasDeFotoNoLocal.get(local) === v) escritasDeFotoNoLocal.delete(local);
        },
    };
}

// A escrita espera a vez do local? Sempre que houver alguém na frente — menos a
// página SAINDO com só o aquecimento na frente (ver acima).
function esperaAVezDoLocal(vez) {
    return !!vez.anterior && !(vez.soAquecimentoNaFrente && typeof API !== 'undefined' && API.saindo === true);
}

// O que a escrita espera pra ter a vez do local (quando `esperaAVezDoLocal`). Com
// só AQUECIMENTO na frente, a página saindo também solta a espera
// (`soltarEsperasDoAquecimento`, na descarga): a exclusão — ou a aprovação — que
// já tinha saído da janela do Desfazer e esperava a resposta de um toque lento
// ficava pendurada quando o app fechava, porque a descarga só alcançava o que
// estava na janela, e a foto seguia no mapa sem aviso nenhum (auditoria da
// rodada 13, R13-3-01, MEDIDO no navegador, nos dois motores). Solta, ela sai na
// hora, com `keepalive`; o aquecimento que ainda vai voltar não estraga nada (a
// lista dele é do gesto). Uma ESCRITA na frente não é solta: as duas cruzariam
// no servidor, que desfaz uma delas.
const esperasSoDoAquecimento = new Set();

function vezLiberada(vez) {
    if (!vez.soAquecimentoNaFrente) return vez.anterior;
    return new Promise((ok) => {
        const soltar = () => { esperasSoDoAquecimento.delete(soltar); ok(); };
        esperasSoDoAquecimento.add(soltar);
        vez.anterior.then(soltar);
    });
}

// A página está saindo (`descarregarAcaoPendente`): solta as escritas que
// esperam só um aquecimento — com o transporte já no modo "saindo", pra elas
// saírem com `keepalive`. O envio de cada uma corre nas microtarefas logo depois,
// ainda dentro do `pagehide`. Devolve se soltou alguma.
function soltarEsperasDoAquecimento() {
    if (!esperasSoDoAquecimento.size) return false;
    if (typeof API !== 'undefined' && API.setSaindo) API.setSaindo(true);
    for (const soltar of [...esperasSoDoAquecimento]) soltar();
    return true;
}

// Um id novo por TOQUE na lixeira: o toque e a exclusão dele levam o mesmo, e a
// lista que o toque lê só serve à exclusão deste gesto (`chaveDoToque` no core,
// R13-3-03). Dígitos ao acaso, que não identificam ninguém.
function idDoGestoDaLixeira() {
    const b = new Uint8Array(8);
    try { crypto.getRandomValues(b); } catch (e) { for (let i = 0; i < b.length; i++) b[i] = Math.floor(Math.random() * 256); }
    return Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
}

// As fotos que SAÍRAM do mapa por uma exclusão desta página, por LOCAL
// (`venueID|foto`) e com a época da sessão em que saíram (auditoria da rodada 12,
// R12-3-02). Morava na VEZ do local (R10-3-03), que é apagada quando esvazia: a
// exclusão de X pela camada de A que POUSAVA com a de X pela camada do IRMÃO B
// ainda na janela do Desfazer (não tinha entrado na vez) esvaziava a vez e
// esquecia que X saiu. A de B saía depois: um 2º pedido ao Waze, e "Outro editor
// já tinha excluído 👍" sobre a exclusão da própria pessoa. E o Desfazer de B
// nesse meio devolvia X à camada e ao dado de B como aprovada, com a lixeira,
// com a foto já fora do mapa (MEDIDO nos dois casos, s12 e s12b, com os
// controles).
//
// Duas perguntas, e a sessão só entra numa:
//   · a exclusão NÃO VAI ao Waze (e não diz "outro editor") com a foto que saiu
//     NESTA sessão (`soNestaSessao`) — quem a tirou foi esta pessoa;
//   · o `devolverFoto` não devolve à tela a foto que saiu, seja de que sessão
//     for: é fato do mapa. E a queda sobe a época ANTES de cancelar a janela do
//     Desfazer (`derrubarSessao`), que devolve a foto.
// Sai no "Sair" (`handleLogout`), com a memória das idas sem resposta. O teto é
// o da corrida, não o do dia: a pergunta só importa enquanto uma janela do
// Desfazer (3 s) ou uma escrita do local estiver no ar.
const fotosQueSairamDoMapa = new Map();   // 'venueID|foto' → epocaDaSessao
const FOTOS_QUE_SAIRAM_TETO = 50;

function fotoSaiuDoMapa(place, id, soNestaSessao = false) {
    if (!place || place.venueID == null) return false;
    const epoca = fotosQueSairamDoMapa.get(place.venueID + '|' + id);
    return epoca !== undefined && (!soNestaSessao || epoca === epocaDaSessao);
}

function anotarFotoQueSaiuDoMapa(place, id) {
    if (!place || place.venueID == null) return;
    const chave = place.venueID + '|' + id;
    fotosQueSairamDoMapa.delete(chave);
    fotosQueSairamDoMapa.set(chave, epocaDaSessao);
    if (fotosQueSairamDoMapa.size > FOTOS_QUE_SAIRAM_TETO) {
        fotosQueSairamDoMapa.delete(fotosQueSairamDoMapa.keys().next().value);
    }
}

// Uma EXCLUSÃO de foto do local deste pedido está no ar — saiu pro Waze, ou
// espera a vez do local pra sair (`vezDasFotosNoLocal`). A pílula do nome desse
// local fica travada até a resposta (auditoria da rodada 11, R11-3-06): a
// exclusão que tira a ÚLTIMA foto da camada a FECHA quando pousa
// (`removerFoto`), e com ela a correção do nome que estivesse aberta — o nome
// digitado sumia sem aviso nem nada dito ao leitor de tela (MEDIDO nos dois
// motores, no próprio pedido sem o Desfazer e no IRMÃO com ele). Como a trava do
// nome no ar (`renomeacaoNoAr`, L23): por LOCAL, que os irmãos dividem.
function exclusaoDoLocalNoAr(place) {
    if (!place || place.venueID == null) return false;
    const vez = escritasDeFotoNoLocal.get(place.venueID);
    return !!(vez && vez.exclusoes > 0);
}

// Uma escrita de FOTO SEM janela no ar (o caminho sem Desfazer): a aprovação ou
// a exclusão já saiu e espera o Waze. Enquanto isso os dois botões de foto
// ficam travados — e quem ESCREVE o `disabled` deles é só a função da trava
// (`aplicarTravaDeAcao`), que lê estes dois. Eram dois escritores do mesmo
// atributo (gotcha #63 outra vez): o `estadoAprovando` e a `lixeiraOcupada`
// desabilitavam o botão, e a trava, que roda a cada abrir e fechar da edição do
// nome — e em todo fechar do lightbox —, o reabria no meio do envio. MEDIDO: o
// "Aprovar" com o spinner voltava vivo, e o segundo toque mandava uma 2ª
// aprovação ("Restam" caindo 2 por um pedido); a lixeira, uma 2ª exclusão
// (auditoria de 2026-09-29, L24 / V11).
let aprovandoAgora = false;
let excluindoAgora = false;

// A lixeira vira spinner SÓ quando há espera de verdade — ou seja, no caminho
// SEM Desfazer. Com Desfazer a foto some na hora e nada foi enviado ainda:
// spinner ali seria mentira sobre uma espera que não existe, e ainda
// bloquearia excluir a PRÓXIMA foto, que passou a ocupar aquele botão.
function lixeiraOcupada(ligado) {
    excluindoAgora = !!ligado;
    const btn = document.getElementById('lightboxDelete');
    if (btn) btn.classList.toggle('lixeira-ocupada', !!ligado);
    aplicarTravaDeAcao();   // o `disabled` é dela (ver acima)
}

// 401 numa escrita do lightbox — aprovar, excluir ou renomear (auditoria de
// 2026-09-26). O 401 muitas vezes é ALARME FALSO (WAF, blip do KV: gotcha
// #42), e a tela já mostra a escrita feita: a foto sumiu, o ✨ saiu, o nome é o
// novo. O ramo `unauthorized` só chamava o `handleUnauthorized` e saía, sem
// devolver nada — MEDIDO com a sonda do perfil respondendo viva: a foto seguia
// fora, a proposta "aprovada" e o nome trocado, e nada tinha chegado ao Waze.
//
// A sessão é conferida pelo mesmo `handleUnauthorized` do resto do app e, se a
// sonda a confirmar VIVA depois deste 401 (`sessaoVivaDepoisDe`, a prova que a
// fila de saída já usa), a escrita sai de novo UMA vez — sem requisição à toa,
// porque só sai com a sessão provada. Devolve a resposta dessa segunda ida, ou
// `null` quando ela não houve (sessão não confirmada, ou conferência já em
// curso por outro 401) ou quando levou OUTRO 401: com a sessão viva, é esta
// escrita que o Waze recusa, não a sessão — o critério do `u401` da fila de
// saída. Com `null`, quem chamou toma o caminho de toda falha: devolve a tela e
// avisa. Queda de sessão de verdade muda a época, e quem chamou sai sem mexer
// em nada, como já fazia.
//
// Enquanto confere, NADA prossegue (`acoesTravadas`, como na janela do
// Desfazer): a segunda ida sai uns 2 s depois da primeira, e uma decisão nova
// sobre o mesmo local nesse meio — rejeitar o card da foto que está sendo
// aprovada, excluir outra foto do local — cruzaria com ela.
let escritasConferindo = 0;

async function refazerDepoisDo401(epoca, enviar) {
    const levou = Date.now();
    escritasConferindo++;
    aplicarTravaDeAcao();
    try {
        // Outra chamada JÁ abriu a conferência (o WAF e o KV devolvem 401 a
        // várias de uma vez): o `handleUnauthorized` volta na hora, sem
        // desfecho, e a escrita desistia — MEDIDO: 1 envio, a foto de volta a
        // pendente, e a sessão confirmada VIVA 1 s depois (auditoria de
        // 2026-09-29, V5). Espera o desfecho DELA, que é o mesmo pra todo 401.
        await (verificandoSessao && conferenciaDaSessao ? conferenciaDaSessao : handleUnauthorized());
        if (epoca !== epocaDaSessao || !sessaoVivaDepoisDe(levou)) return null;
        const r = await callWithRetry(enviar);
        return r && r.errorCategory === 'unauthorized' ? null : r;
    } finally {
        escritasConferindo = Math.max(0, escritasConferindo - 1);
        aplicarTravaDeAcao();
    }
}

// As idas de UMA escrita do lightbox, contadas: quantas terminaram SEM resposta
// (`transient` — a rede que caiu na volta, o prazo que estourou, o Waze lento
// que o servidor largou) e por isso podem ter POUSADO. A retentativa do
// `callWithRetry` vai de novo, e a 2ª volta "já feito": o Waze não diz por
// quem, só o aparelho sabe que houve uma ida dele antes. Sem esta conta, a
// exclusão dizia "Outro editor já tinha excluído 👍" e a aprovação "Já tratado
// por outro editor 👍" — atribuindo a escrita da PRÓPRIA pessoa a outro, e na
// aprovação ainda tirando a foto das aprovadas (sem a lixeira, com ela no mapa)
// e não contando o "Curador". MEDIDO: 2 idas, a 1ª com a resposta perdida, nos
// dois (auditoria de 2026-09-30, R5-3-04/R56-4). "Já feito" depois de uma ida
// sem resposta é desta pessoa.
//
// `antes`: as idas sem resposta de um GESTO ANTERIOR sobre o mesmo alvo, nesta
// sessão (`idasSemRespostaDeAntes`, R6-3-04 logo abaixo).
function contarIdasSemResposta(ir, antes = 0) {
    const enviar = async () => {
        // A ida que nem SAIU (o aparelho sem rede na hora: o `fetch` falha ali
        // mesmo) não pode ter pousado, e contá-la daria a esta pessoa, no gesto
        // seguinte, o "já feito" de outro editor.
        const saiu = navigator.onLine !== false;
        const r = await ir();
        if (saiu && r && !r.success && r.errorCategory === 'transient') enviar.semResposta++;
        return r;
    };
    enviar.semResposta = Number(antes) || 0;
    return enviar;
}

// R6-3-04 (auditoria de 2026-10-01): a ida que POUSOU e cuja resposta se perdeu
// com a REDE caindo (o `navigator.onLine` falso na volta) não é retentada — o
// `callWithRetry` não insiste sem rede, de propósito. A pessoa via "Erro de
// conexão" e a foto de volta a pendente, e tentava de novo com a rede de volta:
// o Waze dizia "já feito", e o gesto NOVO, com o contador zerado, dizia "Já
// tratado por outro editor 👍" (sem a lixeira e sem o "Curador"; na exclusão,
// "Outro editor já tinha excluído 👍"). MEDIDO nos dois motores. O que o
// aparelho sabe — houve uma ida dele, sem resposta — fica guardado por ALVO (o
// pedido aprovado; a foto excluída, no local) e entra no gesto seguinte sobre
// ele. Só na MESMA sessão (`epocaDaSessao`; o "Sair" esquece tudo): com outra
// sessão, outra pessoa pode ter entrado. Sai quando o alvo tem desfecho (pousou:
// um "já feito" depois disso é de outro), e o mapa tem teto.
const idasSemRespostaGuardadas = new Map();   // alvo → { epoca, n }
const IDAS_SEM_RESPOSTA_TETO = 50;

function idasSemRespostaDeAntes(alvo) {
    const g = idasSemRespostaGuardadas.get(alvo);
    return g && g.epoca === epocaDaSessao ? g.n : 0;
}

// O fim de um gesto sobre o alvo. `pousou` é o desfecho do Waze (a escrita está
// lá, desta pessoa ou de outra): o alvo é esquecido. Sem desfecho, e com alguma
// ida sem resposta (deste gesto ou dos anteriores), o número fica pro gesto
// seguinte. A resposta de OUTRA sessão não guarda nada.
function lembrarIdasSemResposta(alvo, n, pousou, epoca) {
    idasSemRespostaGuardadas.delete(alvo);
    if (pousou || !(n > 0) || epoca !== epocaDaSessao) return;
    idasSemRespostaGuardadas.set(alvo, { epoca, n });
    if (idasSemRespostaGuardadas.size > IDAS_SEM_RESPOSTA_TETO) {
        idasSemRespostaGuardadas.delete(idasSemRespostaGuardadas.keys().next().value);
    }
}

// A decisão do CARD (✕ ou ✓) que volta "já tratado" depois de uma APROVAÇÃO
// desta foto sem resposta (auditoria de 2026-10-02, R7-3-08). A aprovação pousou
// e a resposta se perdeu com a rede caindo: o app disse "Erro de conexão" e
// devolveu o ✨ e o "Aprovar", e a memória das idas guardou a ida (R6-3-04) — só
// pro gesto seguinte NA FOTO. Com a rede de volta, a pessoa decide pelo card, o
// Waze responde "já tratado" (quem resolveu o pedido foi a aprovação DELA), e o
// card dizia "Já tratado por outro editor 👍" e contava um Rejeitado (ou um
// Lido) no placar e no Histórico, de um pedido APROVADO — MEDIDO nos dois
// motores. O desfecho é o da aprovação: sem "outro editor" e sem contar a
// decisão do card (o placar do gesto desce), com o "Curador", como a aprovação
// que pousa (`enviarAprovacao`). A memória do alvo sai: um "já feito" depois
// disto é de outro editor. Dizer na tela que a foto já estava aprovada pediria
// uma frase que o app não tem — fica calado, como o pouso por outra aba.
//
// Os LOTES perguntam a mesma coisa (auditoria de 2026-10-06, R8-2-01): o
// "Rejeitar os N" e a recusa automática (`enviarLote`) e o "Marcar todos"
// (`handleBatchMarkRead`) levavam junto o pedido aprovado, e o "já tratado" dele
// contava um rejeitado (ou um lido) no placar e no Histórico, sem o "Curador" —
// e a folha do lote dizia "1 já tratado por outro editor" sobre a aprovação da
// própria pessoa (MEDIDO nos dois motores).
function aprovacaoDelaJaPousou(place) {
    return !!place && idasSemRespostaDeAntes('aprovar|' + chaveDoPedido(place)) > 0;
}

// `contado`: a decisão JÁ entrou no placar no GESTO (o ✕ e o ✓ do card, a fila
// de saída e o "Rejeitar os N", que contam antes de mandar) e desce aqui. O
// "Marcar todos" e a recusa automática contam quando o pedido POUSA: neles o
// pedido aprovado nunca subiu o placar, e não há o que descer (R8-2-01).
function desfechoDaAprovacaoDela(actionType, place, contado = true) {
    lembrarIdasSemResposta('aprovar|' + chaveDoPedido(place), 0, true, epocaDaSessao);
    if (contado) {
        const k = actionType === 'read' ? 'read' : 'rejected';
        AppState.stats[k] = Math.max(0, AppState.stats[k] - 1);
        updateStats();
        saveStats();
    }
    contarConquista('fotos');
}

// Manda pro Waze de verdade. Se falhar, a foto VOLTA — mesma gramática do
// swipe, que reverte o placar quando o Waze recusa.
// Devolve se a foto SAIU do mapa: quem espera a resposta (o caminho sem
// Desfazer) só tira a foto da tela com `true` — antes o `.finally` a tirava
// mesmo na falha, e a tela afirmava uma exclusão que não houve.
async function enviarExclusao(alvo) {
    const epoca = epocaDaSessao;
    // A foto, no local: o mesmo alvo visto de qualquer pedido do local (R6-3-04).
    const alvoDasIdas = 'excluir|' + alvo.place.venueID + '|' + alvo.id;
    // A vez do LOCAL (R10-3-03): com outra escrita da lista dele no ar — outra
    // exclusão, ou a aprovação de uma foto dele (R11-3-01) —, o envio espera a
    // resposta dela — e a do aquecimento da lixeira (R12-3-01), menos com a página
    // saindo (`esperaAVezDoLocal`, e a que já esperava é solta quando a página
    // sai, `vezLiberada`). Sem nenhuma, nada espera — o envio sai na hora, como
    // antes. A pílula do nome do local trava com ela no ar (R11-3-06): a trava é
    // reaplicada quando ela entra na vez e quando sai. O GESTO do toque
    // (`alvo.aquecimento`) vai junto: a lista que ele leu é desta exclusão.
    const vez = vezDasFotosNoLocal(alvo, 'excluir');
    aplicarTravaDeAcao();
    try {
        if (esperaAVezDoLocal(vez)) await vezLiberada(vez);
        // A MESMA foto já saiu do mapa por outra exclusão DESTA sessão — a do
        // irmão, que estava no ar com esta na vez (R10-3-03) ou que pousou com
        // esta ainda na janela do Desfazer (R12-3-02, `fotosQueSairamDoMapa`):
        // nada a mandar. O fim é o de uma exclusão que pousou — depois da queda,
        // só pra quem ainda vê o pedido.
        if (fotoSaiuDoMapa(alvo.place, alvo.id, true)) return epoca === epocaDaSessao || pedidoAindaNaTela(alvo.place);
        // Com a MESMA política de retentativa do resto (o renomear já a tinha):
        // uma oscilação de rede virava "não deu pra excluir" na primeira falha
        // (auditoria de 2026-09-25). Repetir é seguro: a exclusão relê o local,
        // e a foto que já saiu volta como `jaExcluida` — de quem, diz a conta
        // das idas (`contarIdasSemResposta`), deste gesto e dos anteriores. A
        // época é a do GESTO, explícita: a espera pela vez pode atravessar a
        // queda, e a ida não sai com a sessão de quem entrou depois (o
        // `callWithRetry` a confere antes de CADA tentativa).
        const enviar = contarIdasSemResposta(() => API.excluirFoto(alvo.place.venueID, alvo.id, alvo.place.lat, alvo.place.lon, alvo.regiao, alvo.aquecimento), idasSemRespostaDeAntes(alvoDasIdas));
        let r = await callWithRetry(enviar, epoca);
        if (epoca === epocaDaSessao && r && r.errorCategory === 'unauthorized') {
            r = await refazerDepoisDo401(epoca, enviar);
        }
        lembrarIdasSemResposta(alvoDasIdas, enviar.semResposta, !!(r && r.success), epoca);
        // A sessão acabou no meio (ver `epocaDaSessao`): nada grava — e a foto
        // que a exclusão não tirou do mapa volta pra tela (V2).
        const outraSessao = epoca !== epocaDaSessao;
        if (outraSessao && !(r && r.success)) {
            escritaDoLightboxSemSessao(alvo.place, () => devolverFoto(alvo), 'toast.photoDeleteFailed');
            return false;
        }
        if (r && r.success) {
            // A exclusão que POUSOU depois da queda (a renovação com a MESMA
            // conta mantém a fila e a foto aberta) vai pra tela como qualquer
            // outra: a foto SAIU do mapa, e isso é fato do Waze, não gravação
            // desta sessão — excluir não tem placar, Histórico nem conquista.
            // Ela seguia na foto ampliada (com a lixeira oferecendo apagá-la de
            // novo), no pedido e no irmão (auditoria de 2026-10-01, R6-3-01).
            // Só pra quem ainda vê o pedido: depois do "Sair" não há tela.
            if (outraSessao && !pedidoAindaNaTela(alvo.place)) return false;
            // A foto saiu do mapa: a MESMA foto, pela camada de um irmão — na vez
            // ou ainda na janela do Desfazer —, não sai de novo nem volta à tela
            // (R12-3-02, `fotosQueSairamDoMapa`).
            anotarFotoQueSaiuDoMapa(alvo.place, alvo.id);
            // Sem toast de sucesso: a foto sumindo JÁ é a confirmação, e
            // anunciar o que a pessoa está vendo acontecer é ruído. O aviso
            // fica só pro caso em que nada muda na tela por causa dela — e só
            // se a foto saiu por OUTRO: "já excluída" depois de uma ida sem
            // resposta é a exclusão desta pessoa (R5-3-04).
            if (r.jaExcluida && !enviar.semResposta) showToast(t('toast.photoAlreadyGone'), 'info');
            // O irmão na frente é redesenhado com o MESMO pedido: o foco num ✕
            // ↑ ✓ dele fica no mesmo botão (`mesmoBotao`, R9-3-04).
            aplicarNosIrmaos(alvo.place, (q) => {
                Lightbox.removerFoto(alvo.id, q);
                if (AppState.currentPlace === q) mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
            });
            return true;
        }
        devolverFoto(alvo);
        showToast(msgDoServidor(r) || t('toast.photoDeleteFailed'), 'error');
        return false;
    } catch (e) {
        if (epoca !== epocaDaSessao) {
            escritaDoLightboxSemSessao(alvo.place, () => devolverFoto(alvo), 'toast.photoDeleteFailed');
            return false;
        }
        devolverFoto(alvo);
        showToast(t('toast.photoDeleteFailed'), 'error');
        return false;
    } finally {
        // A vez do local passa pra próxima, dê certo ou não (R10-3-03) — e a
        // pílula do nome do local destrava (R11-3-06).
        vez.soltar();
        aplicarTravaDeAcao();
    }
}

// Os OUTROS pedidos do mesmo local na fila (irmãos) foram montados com o local
// de ANTES: sem isto, o card seguinte do mesmo local mostrava a foto que acabou
// de sair (com a lixeira oferecendo apagá-la de novo) e o nome velho (com a
// pílula oferecendo corrigir o que já foi corrigido). Só depois de o Waze
// CONFIRMAR — na janela do Desfazer ou na falha, o mapa ainda é o de antes
// (auditoria de 2026-09-25).
//
// Com o TREINO aberto, a `AppState.queue` é a fila de EXEMPLOS (clones), e a fila
// REAL mora em `Treino._salvo.queue` até ele fechar. A escrita que pousava ali —
// a exclusão sem o Desfazer, ou a da janela despachada ao entrar no treino —
// mudava só os clones: ao sair, o irmão real seguia com a foto que saiu (e a
// lixeira dele dizia "Outro editor já tinha excluído 👍" sobre a exclusão da
// própria pessoa) e com o nome velho (auditoria de 2026-10-02, R7-3-05, MEDIDO
// nos dois motores). As duas filas são percorridas: a da tela e a real, com o
// recusado que espera o "Sair" do treino (`filaRealComDevolvidos`, R9-7-01), que
// fora do treino são a mesma.
function aplicarNosIrmaos(place, aplicar) {
    if (!place || place.venueID == null) return;
    const filas = [AppState.queue || []];
    const real = filaRealComDevolvidos();
    if (real !== filas[0]) filas.push(real);
    const irmaos = [];
    for (const fila of filas) {
        for (const q of fila) if (q && q !== place && q.venueID === place.venueID && !irmaos.includes(q)) irmaos.push(q);
    }
    for (const q of irmaos) aplicar(q);
    // O card de FUNDO da pilha foi desenhado com o local de antes.
    if (irmaos.includes(AppState.queue[1])) montarCardDeFundo();
}

// Recoloca a foto onde estava — no desfazer e na falha do envio.
//
// Menos a foto que JÁ SAIU do mapa por outra exclusão desta página — a da camada
// de um IRMÃO, que pousou com esta na janela do Desfazer (R12-3-02,
// `fotosQueSairamDoMapa`): ela voltava à camada e ao pedido como aprovada, com a
// lixeira, sem estar no mapa. Nada volta, e devolve `false`: quem avisa que a
// foto voltou (`escritaDoLightboxSemSessao`) fica calado.
function devolverFoto(alvo) {
    const p = alvo.place;
    if (fotoSaiuDoMapa(p, alvo.id)) return false;
    if (p && Array.isArray(p.imageUrls) && !p.imageUrls.some((u) => u.indexOf(alvo.id) !== -1)) {
        p.imageUrls.splice(Math.min(alvo.idx, p.imageUrls.length), 0, alvo.url);
        if (Array.isArray(p.approvedImageIds) && !p.approvedImageIds.includes(alvo.id)) p.approvedImageIds.push(alvo.id);
        p.imageUrl = p.imageUrls[0] || null;
    }
    if (Lightbox.place === p) Lightbox.recolocarFoto(alvo.url, alvo.idx, alvo.selo === true, alvo.eDenuncia);
    // O card é redesenhado debaixo do foco — o Desfazer pela tecla z, com a foto
    // já fechada, e a falha que chega depois (R5-3-07). É o MESMO pedido: o foco
    // num ✕ ↑ ✓ fica no mesmo botão (`mesmoBotao`, R9-3-04).
    if (AppState.currentPlace === p) mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
}

function pedirExclusaoDaFoto() {
    // Treino não escreve. Antes isto era garantido pelo DADO — os cards de
    // treino não tinham foto, então o lightbox nem abria. Com pedido real na
    // fila de treino essa proteção acidental some, e o `venueID` é REAL: sem
    // este guard, a lixeira apagaria uma foto do mapa enquanto a faixa promete
    // que nada é enviado. Proteção não pode depender de a fixture ser pobre.
    if (Treino.ativo) return;
    // Sem sessão não se escreve: a janela desta exclusão correria com o token
    // de quem entrasse depois (ver `acoesTravadas`, K1).
    if (!AppState.authenticated) return;
    // Foto que não carregou não se exclui (ver `atualizarAcoesDeFoto`).
    if (!fotoDoLightboxNaTela()) return;
    // Uma escrita de foto sem janela ainda no ar: o botão está travado, e o
    // teclado ou um script não furam a trava (L24).
    if (aprovandoAgora || excluindoAgora) return;
    const id = Lightbox.idFotoAtual();
    if (!id) return;
    const place = Lightbox.place;
    // A região é a do GESTO (L26): o envio sai até 3 s depois.
    // `selo`: a foto excluída é a do selo da camada (a 🚩 denunciada, num pedido de
    // foto denunciada) — o Desfazer o devolve junto com ela (ver `recolocarFoto`).
    // `eDenuncia`: e QUAL selo, que a camada reaberta pelo card dentro da janela
    // já não sabe (R10-3-01).
    const alvo = { id, place, idx: Lightbox.idx, url: Lightbox.urls[Lightbox.idx], regiao: API.getRegion(),
        selo: Lightbox.newIdx >= 0 && Lightbox.newIdx === Lightbox.idx, eDenuncia: Lightbox.eDenuncia === true };

    // Uma exclusão por vez: tocar na lixeira de novo despacha a anterior, como
    // o swipe faz. Sem isto, duas janelas correndo escreveriam listas que se
    // ignoram — a segunda apagaria só a dela, ressuscitando a primeira.
    if (exclusaoPendente) exclusaoPendente.enviar();
    // E a APROVAÇÃO pendente também: a foto recém-aprovada vira alvo da lixeira
    // no mesmo canto, e sem despachar antes as duas escritas cruzam — a
    // exclusão relê um local onde a foto ainda está pendente, monta a lista sem
    // ela, e aí a aprovação chega depois e a devolve. O editor mandou excluir e
    // a foto fica. Hoje o banner do Desfazer TAPA a lixeira (medido:
    // elementFromPoint devolve #undoBtn), mas isso é acidente de sobreposição —
    // se o banner mudar de lugar a proteção some sem ninguém notar.
    if (aprovacaoPendente) aprovacaoPendente.enviar();

    // Gate de experiência igual ao do swipe: a preferência salva como false só
    // vale se o editor qualifica (senão um legado de versão sem gate liberaria).
    const semJanela = AppState.preferences.undoEnabled === false && canDisableUndo();
    if (semJanela) {
        // Espera REAL: a chamada sai agora. Spinner no lugar da lixeira e a
        // foto só sai da tela quando o Waze confirmar.
        lixeiraOcupada(true);
        enviarExclusao(alvo).then((saiuDoMapa) => {
            lixeiraOcupada(false);
            if (!saiuDoMapa) return;
            // A foto DESTE pedido estava aberta? Lido antes do `removerFoto`: a
            // última foto do local fecha a camada (R7-3-04). E o que a região do
            // card diz agora, e de qual card: o fechamento pode TROCAR o card,
            // e o que ele disser não pode ser apagado (R8-3-07).
            const naCamada = Lightbox.isOpen() && Lightbox.place === place;
            const anunciarAoFechar = anuncioDoCardAoFechar();
            Lightbox.removerFoto(alvo.id, place);
            // Com a foto já fechada, o card é redesenhado debaixo do foco
            // (R5-3-07) — o MESMO pedido: o foco num ✕ ↑ ✓ fica no mesmo botão
            // (`mesmoBotao`, R9-3-04).
            if (AppState.currentPlace === place) mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
            // Sem o banner do Desfazer, nada dizia ao leitor de tela que valeu
            // (R6-3-08): pela região da camada — ou pela do card, quando a
            // exclusão FECHOU a camada (R7-3-04), junto do card que o
            // fechamento trouxe, se trouxe (R8-3-07), e quando a pessoa a
            // fechou antes da resposta (R9-3-05, `anunciarDesfechoDaFoto`).
            if (naCamada && !Lightbox.isOpen()) anunciarAoFechar(t('undo.photoDeleted'));
            else anunciarDesfechoDaFoto(t('undo.photoDeleted'), place);
        });
        // A lixeira com o foco virou spinner (`disabled`): o foco fica na camada.
        manterFocoNoLightbox();
        return;
    }

    // Com janela: a foto some JÁ (é o retorno imediato) e o envio espera.
    // A releitura é aquecida agora — os ~557ms dela cabem dentro da janela.
    // Menos com outra escrita da lista deste local no ar (R10-3-03): esta só sai
    // depois da resposta dela (`vezDasFotosNoLocal`), e o servidor usa a lista
    // que ELA deixou guardada. Aquecida agora, a releitura podia ler o local
    // ANTES da escrita da outra e guardá-lo com a hora nova, por cima: MEDIDO no
    // core, a exclusão seguinte mandava de volta a foto que a primeira tirou, as
    // duas com `success: true`. Sem o aquecimento, o servidor relê na hora (ou
    // usa a lista da outra), e é uma ida a menos. Com uma APROVAÇÃO do local no
    // ar (R11-3-01) vale o mesmo: lida antes de ela pousar, a lista guardada via a
    // foto pendente.
    //
    // E o próprio aquecimento ENTRA na vez do local, como uma leitura (auditoria
    // da rodada 12, R12-3-01): a exclusão desta foto (e a de outra, e a aprovação
    // de uma foto do local) só sai depois da resposta dele. Fora da vez, com o
    // Waze lento, ele voltava DEPOIS de a exclusão sair e guardava no servidor a
    // lista de antes, por cima — a exclusão seguinte do local mandava a foto de
    // volta (e uma foto recém-aprovada, como pendente), com tudo `success: true`
    // (MEDIDO de ponta a ponta). Não custa espera: ele leva ~0,7 s, e a janela do
    // Desfazer, 3 s. O que não saiu (sem sessão) não segura nada.
    //
    // O toque leva o GESTO (`idDoGestoDaLixeira`), e a exclusão dele também
    // (`alvo.aquecimento`): no servidor, a lista que o toque lê mora numa chave
    // do gesto, que nenhuma outra escrita lê — com a página saindo, a escrita não
    // espera o toque, e a leitura dele, que volta depois, guardava a lista de
    // antes por cima (auditoria da rodada 13, R13-3-02 e R13-3-03).
    if (!escritasDeFotoNoLocal.has(place.venueID)) {
        const gesto = idDoGestoDaLixeira();
        const aquecendo = API.prepararExclusao(place.venueID, place.lat, place.lon, alvo.regiao, gesto);
        if (aquecendo && typeof aquecendo.then === 'function') {
            alvo.aquecimento = gesto;
            const vez = vezDasFotosNoLocal(alvo, 'aquecer');
            aquecendo.then(vez.soltar, vez.soltar);
        }
    }
    Lightbox.removerFoto(alvo.id, place);
    // A ÚLTIMA foto do local saiu: o `removerFoto` FECHOU a foto ampliada e o
    // foco voltou à foto do card — que este redesenho tira da página. O foco
    // caía no <body>, com o banner do Desfazer na tela (R6-3-02, auditoria de
    // 2026-10-01, MEDIDO nos dois motores); o caminho sem o Desfazer, acima, já
    // passava pelo foco do card (R5-3-07). O MESMO pedido (`mesmoBotao`, R9-3-04).
    if (AppState.currentPlace === place) mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });

    let saiu = false;
    const enviar = () => {
        if (saiu) return;
        saiu = true;
        clearTimeout(exclusaoPendente && exclusaoPendente.timer);
        if (exclusaoPendente && exclusaoPendente.id === alvo.id) exclusaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        // O banner disse "Foto excluída" no GESTO, sobre ESTE pedido, e a tela
        // dele mudou ali. Quando o Waze confirma (3 s depois, ou mais), quem muda
        // é o IRMÃO do mesmo local (`aplicarNosIrmaos`): a foto sai da camada
        // ampliada dele, ou do card dele na frente — e nada era dito ao leitor
        // de tela, que no caminho SEM o Desfazer ouve o desfecho (auditoria da
        // rodada 11, R11-3-05, MEDIDO nos dois motores). O mesmo anúncio, só
        // pelo irmão: o próprio pedido já foi dito.
        enviarExclusao(alvo).then((saiuDoMapa) => {
            if (saiuDoMapa) anunciarDesfechoDaFoto(t('undo.photoDeleted'), place, true);
        });
    };
    // Volta atrás sem enviar. É o Desfazer do editor e também o cancelamento
    // que o APP faz quando a sessão acaba (ver `cancelarPendenciasDoLightbox`).
    const cancelar = () => {
        if (saiu) return false;
        saiu = true;
        clearTimeout(exclusaoPendente && exclusaoPendente.timer);
        if (exclusaoPendente && exclusaoPendente.id === alvo.id) exclusaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        devolverFoto(alvo);
        return true;
    };
    // É o MESMO Desfazer do card (o mesmo banner): zera a "Mão firme" e conta a
    // "Segunda chance" como lá (auditoria de 2026-09-25). O cancelamento do app
    // não conta: quem desfez não foi o editor.
    const desfazer = () => { if (cancelar()) registrarDesfazer(); };
    const timer = setTimeout(enviar, UNDO_WINDOW_MS);
    exclusaoPendente = { id: alvo.id, place, timer, enviar, desfazer, cancelar };
    aplicarTravaDeAcao();
    mostrarDesfazer(t('undo.photoDeleted'), () => exclusaoPendente && exclusaoPendente.desfazer());
    // A lixeira com o foco travou (ou sumiu com a foto): o foco fica na camada.
    manterFocoNoLightbox();
}

// ── Aprovar a foto pendente ───────────────────────────────────────────────
//
// Espelho da lixeira, e de propósito: mesmo portão (L6+AM ou staff), mesma
// janela de Desfazer, mesma regra de que o envio só sai quando a janela fecha
// SOZINHA. O que muda é o sentido — aqui a foto passa a valer no mapa.
//
// Por que aprovar foto não fere a regra de ouro ("o app nunca aprova"): a regra
// existe porque aprovar dado de LOCAL exige ajuste no WME — nome, categoria,
// posição têm campo pra corrigir. Foto não tem: ou serve ou não serve, e a
// decisão está inteira na tela. Decisão do owner, a pedido de um global champ.
let aprovacaoPendente = null;
// As aprovações que SAÍRAM e esperam a resposta, pela chave do pedido (ver
// `aprovacaoDaTelaNoAr`). São da SESSÃO que as mandou, como o lote de lidos
// (V6): o "Sair" as solta, a queda as passa pra `aprovacoesDaQueda`, e a
// resposta velha não solta a aprovação de uma sessão que vem.
const aprovacoesNoAr = new Set();
// As da sessão que CAIU com a resposta ainda no ar, com a fila (`fetchEpoch`) em
// que estavam. A renovação com a MESMA conta mantém a fila, e o card do pedido
// aprovado voltava DESTRAVADO até a resposta chegar: um ✕ ali mandava uma
// segunda decisão ao Waze, e o placar e a reincidência do autor contavam a
// rejeição de uma foto que a pessoa tinha aprovado — com a recusa automática,
// contra quem não errou (MEDIDO no navegador, follow-up do R5-2-03). Elas seguem
// travando o card SÓ nessa fila: a fila refeita (outra conta, ↻, filtro, o
// "Sair") não as vê, e o pedido nem volta a ela, porque segue em
// `pedidosEmAndamento` até a resposta. Saem quando a resposta chega, pousando ou
// não (`enviarAprovacao`), e no "Sair". Nunca duram mais que a própria ida: ela
// tem teto, e a retentativa não sai depois da queda (`callWithRetry`).
const aprovacoesDaQueda = new Map();

function aprovacoesAtravessamAQueda() {
    for (const chave of aprovacoesNoAr) aprovacoesDaQueda.set(chave, AppState.fetchEpoch);
    aprovacoesNoAr.clear();
}

// O card fica na tela depois de aprovar (decisão do owner) e só avança quando o
// lightbox fechar. Sem isto, o pedido ficaria resolvido no Waze e pendurado na
// fila — e o ✓ seguinte devolveria "já tratado por outro editor", que é um
// toast confuso pra quem acabou de tratar ele mesmo.
let placeResolvidoPorAprovacao = null;

function estadoAprovando(ligado) {
    aprovandoAgora = !!ligado;
    const spin = document.getElementById('lightboxApproveSpinner');
    const ico = document.getElementById('lightboxApproveIcon');
    if (spin) spin.classList.toggle('hidden', !ligado);
    if (ico) ico.classList.toggle('hidden', !!ligado);
    aplicarTravaDeAcao();   // o `disabled` é dela (ver `aprovandoAgora`)
}

// Devolve se ESTA aprovação valeu: quem espera a resposta (o caminho sem
// Desfazer) só marca a foto como aprovada com `true`. O "outro editor tratou
// antes" resolve o pedido e devolve `false` — a foto não é dada como aprovada
// por quem não a aprovou (L30). Depois da queda, quem leva o desfecho à tela é
// o `aprovacaoPousouDepoisDaQueda`, e aqui sai `false`: nada mais a fazer.
async function enviarAprovacao(alvo) {
    const epoca = epocaDaSessao;
    // QUEM decide, pro aviso às outras abas se ela pousar depois da queda (R12-2-04).
    const quem = typeof quemDecideAgora === 'function' ? quemDecideAgora() : null;
    // No ar: o card do pedido trava até a resposta (ver `aprovacaoDaTelaNoAr`).
    const chave = chaveDoPedido(alvo.place);
    aprovacoesNoAr.add(chave);
    aplicarTravaDeAcao();
    // O pedido aprovado é o alvo das idas sem resposta (R6-3-04).
    const alvoDasIdas = 'aprovar|' + chave;
    let vez = null;
    try {
        // A vez do LOCAL nas escritas da lista de fotos (R11-3-01, ver
        // `vezDasFotosNoLocal`): com uma exclusão do local no ar, a aprovação
        // espera a resposta dela — saindo junto, a resposta da exclusão
        // regravava no servidor a lista de antes, com esta foto pendente, e a
        // exclusão seguinte a devolvia ao Waze como `approved: false`. E o
        // aquecimento da lixeira também é esperado (R12-3-01), menos com a página
        // saindo (`esperaAVezDoLocal`, e a que já esperava é solta quando a página
        // sai, `vezLiberada`, R13-3-01).
        vez = vezDasFotosNoLocal(alvo, 'aprovar');
        if (esperaAVezDoLocal(vez)) {
            await vezLiberada(vez);
            // A OUTRA aba decidiu o pedido enquanto esta esperava a vez (o
            // R11-3-02, na espera que a vez abriu): vale a decisão de lá. A
            // aprovação não sai — o Waze receberia as duas, e a tela diria "Já
            // tratado por outro editor" sobre a decisão da própria pessoa. Volta
            // como no Desfazer (o ✨ e o "Aprovar"), e diz por quê.
            if (epoca === epocaDaSessao && typeof decididosPorOutraAbaComCardAqui !== 'undefined'
                && decididosPorOutraAbaComCardAqui.has(alvo.place) === true) {
                Lightbox.desmarcarAprovada(alvo);
                showToast(t('toast.decididoNaOutraAba'), 'info');
                return false;
            }
        }
        // Retentativa como no excluir e no renomear; repetir é seguro — a 2ª
        // de uma aprovação que passou volta `already_processed`, e é DESTA
        // pessoa quando houve uma ida sem resposta antes, neste gesto ou num
        // anterior (`contarIdasSemResposta`). A época é a do GESTO, explícita,
        // como na exclusão: a espera pela vez pode atravessar a queda, e a ida
        // não sai com a sessão de quem entrou nesse meio.
        const enviar = contarIdasSemResposta(() => API.aprovarPedido(alvo.place.venueID, alvo.place.updateRequestID, alvo.regiao), idasSemRespostaDeAntes(alvoDasIdas));
        let r = await callWithRetry(enviar, epoca);
        if (epoca === epocaDaSessao && r && r.errorCategory === 'unauthorized') {
            r = await refazerDepoisDo401(epoca, enviar);
        }
        lembrarIdasSemResposta(alvoDasIdas, enviar.semResposta, pousouNoWaze(r), epoca);
        const jaFeito = !!(r && (r.errorCategory === 'already_processed' || r.errorCategory === 'not_found'));
        // "Já feito" depois de uma ida SEM resposta é a aprovação DESTA pessoa
        // que pousou e cuja resposta se perdeu (R5-3-04): vale como o sucesso —
        // a foto aprovada, com a lixeira, e o "Curador" — e sem o aviso de
        // "outro editor".
        const valeu = !!((r && r.success) || (jaFeito && enviar.semResposta));
        // A sessão acabou no meio (ver `epocaDaSessao`): nada grava — e a
        // aprovação que não pousou devolve o ✨ e o "Aprovar" (V2); a que
        // pousou vai pra tela como pousou (R6-3-01).
        if (epoca !== epocaDaSessao) {
            if (!pousouNoWaze(r)) escritaDoLightboxSemSessao(alvo.place, () => Lightbox.desmarcarAprovada(alvo), 'toast.photoApproveFailed');
            else aprovacaoPousouDepoisDaQueda(alvo, valeu, quem);
            return false;
        }
        if (valeu) {
            // Sem toast de sucesso: o ✨ sumindo e o botão virando lixeira JÁ
            // dizem que valeu — mesma razão do excluir.
            //
            // A foto vira APROVADA aqui, com e sem a janela do Desfazer — o
            // mesmo gesto idempotente, que redesenha a camada DESTE pedido se ela
            // estiver aberta. Com a janela, só o gesto a marcava, na camada de
            // antes: a camada REABERTA pelo card com a aprovação no ar voltava
            // com o ✨, e a resposta não o tirava (R10-3-04).
            Lightbox.marcarComoAprovada(alvo);
            // E nos IRMÃOS do local, como a exclusão e o nome (auditoria da rodada
            // 12, R12-3-03): aprovada, a foto está no mapa e é da lixeira em
            // qualquer pedido do local. Na camada do irmão ela seguia sem a
            // lixeira até recarregar, com as outras aprovadas tendo a dela (MEDIDO
            // no s13). O mesmo gesto, no pedido do irmão: a camada aberta dele é
            // redesenhada. O "já tratado" por outro editor (logo abaixo) não mexe
            // nos irmãos: não se sabe o que houve.
            aplicarNosIrmaos(alvo.place, (q) => Lightbox.marcarComoAprovada({ ...alvo, place: q }));
            concluirAprovacao(alvo);
            // "Curador" conta CURADORIA SUA. O `already_processed` logo abaixo
            // (sem ida perdida antes) é outro editor que tratou antes — conta
            // pro placar, não pra esta.
            contarConquista('fotos');
            return true;
        }
        // Outro editor TRATOU o pedido antes: o objetivo de quem tocou foi
        // cumprido e ele pousa (mesma lógica do resto do app), com o MESMO aviso
        // do ✕ e do ✓ do card — aqui saía calado (L30, auditoria de 2026-09-29).
        // E a foto NÃO vira "aprovada" na tela: quem tratou pode tê-la RECUSADO,
        // e aí ela nem está no mapa — a lixeira que aparecia no lugar do
        // "Aprovar" ofereceria apagar o que não existe. Ela deixa de ser a
        // proposta (o pedido acabou) e fica sem ação nenhuma.
        if (jaFeito) {
            Lightbox.esquecerProposta(alvo);
            concluirAprovacao(alvo);
            showToast(t('toast.alreadyProcessed'), 'info');
            return false;
        }
        Lightbox.desmarcarAprovada(alvo);
        voltarDaAprovacaoRecusada(alvo);
        showToast(msgDoServidor(r) || t('toast.photoApproveFailed'), 'error');
        return false;
    } catch (e) {
        if (epoca !== epocaDaSessao) {
            escritaDoLightboxSemSessao(alvo.place, () => Lightbox.desmarcarAprovada(alvo), 'toast.photoApproveFailed');
            return false;
        }
        Lightbox.desmarcarAprovada(alvo);
        voltarDaAprovacaoRecusada(alvo);
        showToast(t('toast.photoApproveFailed'), 'error');
        return false;
    } finally {
        // A vez do local passa pra próxima escrita da lista (R11-3-01).
        if (vez) vez.soltar();
        // O envio acabou: pousou (o `registrarPouso` passa a segurar o pedido
        // fora da fila) ou falhou (ele volta a ser um pedido como outro).
        marcarEmAndamento(alvo.place, false);
        // A aprovação que FALHOU devolve o pedido à série do autor: o "Ver +N" do
        // card da frente volta a contá-lo (R5-2-02).
        refazerSelosSeOutroNaTela(alvo.place);
        // E o card destrava — travar tem volta (gotcha #63). A aprovação DESTA
        // sessão sai do conjunto dela; a de uma sessão que CAIU sai das que
        // atravessaram a queda (`aprovacoesDaQueda`), tenha pousado ou não: a
        // resposta chegou. Uma resposta velha nunca toca no conjunto de uma
        // sessão nova.
        if (epoca === epocaDaSessao) aprovacoesNoAr.delete(chave);
        else aprovacoesDaQueda.delete(chave);
        aplicarTravaDeAcao();
    }
}

// Aprovar RESOLVE o pedido no Waze: é um pouso como o do ✕ e o do ✓. O card
// sai quando o lightbox DESTE pedido fechar (decisão do owner) — e se ele já
// fechou (a pessoa aprovou e fechou dentro da janela do Desfazer, e o envio só
// saiu no fechamento), sai AGORA: antes ele ficava pendurado na fila, e o ✓
// seguinte contava o pedido de novo e dizia "já tratado por outro editor".
function concluirAprovacao(alvo) {
    registrarPouso(alvo.place);
    // Aprovar RESOLVE o pedido, como o ✓: é tratar algo nesta fila. Antes dos
    // `show*` (o `advanceQueue` aqui embaixo ou o do fechar do lightbox): sem a
    // marca, aprovar o ÚLTIMO pedido terminava no "Tudo limpo!" de quem não
    // tratou nada ("Confira o país e a região"), sem festa (auditoria de 2026-09-26).
    tratouNestaFila = true;
    // Só na fila do GESTO: o ↻ e a troca de filtro durante a janela ou o envio
    // refazem a fila (`fetchEpoch`), e descontar o "Restam" da fila nova deixava
    // o número abaixo dela (auditoria da fila, 2026-09-26).
    if (alvo.epocaFila === AppState.fetchEpoch) AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
    updateStats();
    if (Lightbox.isOpen() && Lightbox.place === alvo.place) { placeResolvidoPorAprovacao = alvo.place; return; }
    tirarAprovadoDaFila(alvo.place);
}

// O pedido aprovado SAI da fila: é o card da frente, e ela anda — ou NÃO é, e
// ele sai pela IDENTIDADE, sem mexer no card que a pessoa está vendo. O segundo
// caso acontece: com a foto de B aberta, o Desfazer de um ✕ anterior devolve A
// pra frente (o banner fica por cima da foto, e a tecla z também desfaz), e B,
// aprovado em seguida, ficava na fila já resolvido — MEDIDO: [A, B, C] depois
// de fechar, "Restam 2"; chegando em B, o ✓ mandava uma 2ª decisão ao Waze
// ("já tratado") e o "Restam" terminava em 0 com C na tela (auditoria de
// 2026-09-29, L22). O "Restam" já foi descontado no `concluirAprovacao`.
function tirarAprovadoDaFila(place) {
    // A fila anda debaixo do foco, quando a foto já fechou (R5-3-07).
    if (AppState.currentPlace === place) { mantendoFocoNoCard(advanceQueue); return; }
    const i = AppState.queue.indexOf(place);
    if (i < 0) return;   // a fila já andou, ou foi refeita (↻, filtro): ele nem está nela
    AppState.queue.splice(i, 1);
    updatePendingCount();
    // O card de FUNDO pode ser justamente o que saiu.
    if (AppState.currentPlace) aoMudarAFilaPorBaixo();
}

// A aprovação que POUSOU depois de a sessão cair (R5-2-03, o V6b da aprovação).
// Nada grava — a regra da época: nem conquista nem Histórico (aprovar não conta
// no placar) —, mas na fila que ATRAVESSOU a queda (a renovação com a MESMA
// conta) o pedido aprovado seguia como card, contando no "Restam" e decidível de
// novo: MEDIDO (s18, também na main 48d2aea), o ✓ seguinte mandava uma segunda
// decisão ao Waze ("já tratado") e contava um lido a mais. Ele ganha o pouso, sai
// da fila pela identidade e o "Restam" desce. Com OUTRA conta a fila foi refeita,
// e não há o que tirar.
//
// E a TELA mostra o desfecho, como a aprovação de agora mostraria (R6-3-01,
// auditoria de 2026-10-01). Sem o Desfazer, quem marcava a foto como aprovada
// era o `.then` do gesto — que recebe `false` depois da queda —, e a foto aberta
// seguia com o ✨ e o "Aprovar" vivo: MEDIDO, o 2º toque mandava uma segunda
// aprovação ao Waze, dizia "Já tratado por outro editor 👍" e o "Restam" descia
// DUAS vezes pelo mesmo pedido (de 2 a 0, com 1 ainda na fila). O que pousou é
// fato do Waze, não gravação desta sessão: `valeu` (desta pessoa) põe a foto
// entre as aprovadas, com a lixeira; o "já tratado" por outro editor só tira a
// proposta, sem ação nenhuma, e avisa quem ainda vê o pedido (o L30). Em
// qualquer fila: a foto aberta é a mesma, e a marca vive no próprio pedido.
// Placar, Histórico e "Curador" seguem de fora — são da sessão que caiu.
//
// Os IRMÃOS do local também ganham a foto entre as aprovadas (R12-3-03, como no
// `enviarAprovacao`), mas só pra quem ainda vê o pedido — a régua da exclusão
// que pousa depois da queda: depois do "Sair", ou com a fila de OUTRA conta,
// não há tela daquele pedido.
// `quem`: a marca de quem aprovou, tirada no envio — é com ela que as outras
// abas ficam sabendo do pouso, que pode chegar sem sessão na memória (R12-2-04).
// Com a fila REFEITA (a pessoa entrou de novo, ou outra conta entrou), o pouso
// vale do mesmo jeito, pela régua de depois da queda: ele saía no `return` da
// fila sem registrar, e com a MESMA conta entrando de novo a outra aba seguia com
// o pedido como card (R13-2-02, ver `registrarPousoDepoisDaQueda`).
function aprovacaoPousouDepoisDaQueda(alvo, valeu, quem) {
    if (valeu) {
        Lightbox.marcarComoAprovada(alvo);
        if (pedidoAindaNaTela(alvo.place)) aplicarNosIrmaos(alvo.place, (q) => Lightbox.marcarComoAprovada({ ...alvo, place: q }));
    } else {
        Lightbox.esquecerProposta(alvo);
        if (pedidoAindaNaTela(alvo.place)) showToast(t('toast.alreadyProcessed'), 'info');
    }
    if (alvo.epocaFila !== AppState.fetchEpoch) {
        if (typeof registrarPousoDepoisDaQueda === 'function') registrarPousoDepoisDaQueda(alvo.place, quem);
        return;
    }
    registrarPouso(alvo.place, quem);
    // Um gesto da sessão nova já o decidiu (o card ficou destravado na
    // renovação): ele já saiu da fila, e o "Restam" já desceu por ele.
    if (!AppState.queue.includes(alvo.place)) return;
    AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
    updatePendingCount();
    // Com a foto dele aberta de novo (a pessoa a reabriu depois da renovação),
    // ele sai quando ela fechar, como no `concluirAprovacao`.
    if (Lightbox.isOpen() && Lightbox.place === alvo.place) { placeResolvidoPorAprovacao = alvo.place; return; }
    tirarAprovadoDaFila(alvo.place);
}

// O pedido entrou ou saiu de "em andamento" com OUTRO card na tela: o "Ver +N"
// dele conta pela mesma régua da folha (`serieDoAutor`, sem o em andamento), e o
// selo foi desenhado antes. Com o próprio pedido na tela não há selo de outro a
// refazer (e o card dele está travado pela aprovação, A1).
//
// E com o FOCO no autor ("Primeiro os de X"), a série na frente muda junto: o
// pedido que entra em andamento vai pro resto, e o que sai dele (a aprovação que
// o Waze recusou) volta pra série — senão a barra contava uma série diferente da
// que está na frente (R6-2-02).
function refazerSelosSeOutroNaTela(place) {
    if (!AppState.currentPlace || AppState.currentPlace === place) return;
    if (AppState.autorEmFoco !== null && AppState.autorEmFoco !== undefined
        && AppState.currentPlace.creatorId === AppState.autorEmFoco) manterFocoNaFrente();
    aoMudarAFilaPorBaixo();
}

// A aprovação que o Waze RECUSOU deixa o pedido pendente lá. Na fila do gesto o
// card nunca saiu dela: a aprovação só o tira quando vale (`concluirAprovacao`).
// Numa fila REFEITA com ela no ar (↻, filtro), ele não entrou — estava em
// andamento — e ninguém o trazia de volta (auditoria de 2026-09-29, V9): volta
// pela busca (`devolverPedidoRecusado`). Na MESMA fila, se ele não está mais
// nela, outro gesto o decidiu, e devolvê-lo abriria uma segunda decisão.
function voltarDaAprovacaoRecusada(alvo) {
    if (alvo.epocaFila !== AppState.fetchEpoch) devolverPedidoRecusado(alvo.place, alvo.epocaFila);
}

// Avança o card cujo pedido foi aprovado — chamado ao fechar o lightbox.
// A aprovação em voo (janela do Desfazer aberta) é despachada antes: fechar o
// lightbox é sinal de que a pessoa terminou, e deixar a janela correndo com o
// card já fora da tela é pedir pra ela desfazer algo que não vê mais.
function avancarSeAprovado() {
    if (aprovacaoPendente) aprovacaoPendente.enviar();
    const alvo = placeResolvidoPorAprovacao;
    if (!alvo) return;
    placeResolvidoPorAprovacao = null;
    tirarAprovadoDaFila(alvo);
}

function aprovarFotoAtual() {
    // Treino não escreve. Antes isto era garantido pelo DADO — os cards de
    // treino não tinham foto, então o lightbox nem abria. Com pedido real na
    // fila de treino essa proteção acidental some, e o `venueID` é REAL: sem
    // este guard, a lixeira apagaria uma foto do mapa enquanto a faixa promete
    // que nada é enviado. Proteção não pode depender de a fixture ser pobre.
    if (Treino.ativo) return;
    if (!AppState.authenticated) return;   // sem sessão não se escreve (K1)
    // Aprovar é decidir sobre o pixel: sem a foto na tela, não há o que aprovar.
    if (!fotoDoLightboxNaTela()) return;
    // Uma escrita de foto sem janela ainda no ar: o botão está travado, e o
    // teclado ou um script não furam a trava (L24).
    if (aprovandoAgora || excluindoAgora) return;
    if (!Lightbox.podeAprovarAtual()) return;
    // O pedido que a OUTRA aba já decidiu (R10-2-02): vale a decisão de lá, e
    // aprovar a foto seria a segunda — o Waze receberia as duas. Como o gesto no
    // card (`gestoNoDecididoPorOutraAba`), ela não sai, e a pessoa fica sabendo
    // por quê; o botão fica, porque é o toque que explica. Excluir e renomear não
    // decidem o pedido, e seguem.
    if (typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(Lightbox.place) === true) {
        showToast(t('toast.decididoNaOutraAba'), 'info');
        return;
    }
    const place = Lightbox.place;
    // `epocaFila`: a fila do gesto (ver `concluirAprovacao`). `regiao`: a do
    // gesto, que viaja com a escrita (L26).
    const alvo = { id: place.updateRequestID, place, idx: Lightbox.idx, epocaFila: AppState.fetchEpoch,
        regiao: API.getRegion() };
    if (aprovacaoPendente) aprovacaoPendente.enviar();
    // Mesma razão do lado de lá: as duas escritas mexem no mesmo local, então
    // quem chega depois tem que ver o resultado de quem chegou antes.
    if (exclusaoPendente) exclusaoPendente.enviar();
    // Aprovar DECIDE o pedido: do gesto ao fim do envio ele está "em andamento",
    // como no ✕ e no ✓ (`scheduleAction`), e uma busca nesse meio não o traz de
    // volta (`semOsJaDecididos`). Sem isto, um ↻ na janela do Desfazer punha o
    // pedido aprovado de volta como card na fila nova, e depois a aprovação saía
    // e o card virava "já tratado" (achado da auditoria da fila, 2026-09-26).
    // Solta no Desfazer e no fim do envio (`enviarAprovacao`), dê certo ou não.
    marcarEmAndamento(place, true);
    // E o "Ver +N" do card da frente deixa de contá-lo (R5-2-02): o card na tela
    // pode ser OUTRO — o Desfazer de um ✕ devolveu A pra frente com a foto de B
    // aberta (L22) —, e o selo dele seguia contando B, que a folha já não conta.
    refazerSelosSeOutroNaTela(place);

    const semJanela = AppState.preferences.undoEnabled === false && canDisableUndo();
    if (semJanela) {
        estadoAprovando(true);
        // Só marca com a aprovação VALENDO: o `.finally` de antes marcava
        // também na falha, e a foto pendente virava "aprovada" na tela — com a
        // lixeira no lugar, que então apagava a foto e deixava o pedido órfão.
        // Quem marca é o próprio envio, no sucesso (`enviarAprovacao`, R10-3-04).
        enviarAprovacao(alvo).then((valeu) => {
            estadoAprovando(false);
            if (!valeu) return;
            // Sem o banner do Desfazer, nada dizia ao leitor de tela que valeu (R6-3-08).
            anunciarNoLightbox(t('undo.photoApproved'), place);
        });
        // O "Aprovar" com o foco virou spinner (`disabled`): o foco fica na camada.
        manterFocoNoLightbox();
        return;
    }

    // Com janela: o ✨ some JÁ (é o retorno imediato) e o envio espera.
    Lightbox.marcarComoAprovada(alvo);
    let saiu = false;
    const enviar = () => {
        if (saiu) return;
        // A OUTRA aba decidiu o pedido DURANTE a janela (auditoria da rodada 11,
        // R11-3-02): a guarda de cima só vale no toque, e a aprovação saía no fim
        // da janela — o Waze recebia as duas decisões, e a resposta "já tratado"
        // virava "Já tratado por outro editor 👍" sobre a decisão da própria
        // pessoa, na outra aba (MEDIDO nos dois motores). Vale a primeira decisão,
        // como o ✕ do card na janela (`enfileirarSaida` → repetida): a aprovação
        // é descartada como no Desfazer (sem contar como Desfazer do editor), e a
        // frase diz por quê. Vale pra todo fim da janela — o relógio, o fechar da
        // foto, a lixeira, o ↻, a página saindo.
        if (typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(place) === true) {
            if (cancelar()) showToast(t('toast.decididoNaOutraAba'), 'info');
            return;
        }
        saiu = true;
        clearTimeout(aprovacaoPendente && aprovacaoPendente.timer);
        aprovacaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        enviarAprovacao(alvo);
    };
    const cancelar = () => {
        if (saiu) return false;
        saiu = true;
        clearTimeout(aprovacaoPendente && aprovacaoPendente.timer);
        aprovacaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        Lightbox.desmarcarAprovada(alvo);
        // Volta a ser só um pedido da fila — no Desfazer E no cancelamento da
        // queda/"Sair" (L6 passa por aqui): a marca de "em andamento" não pode
        // sobrar, senão a busca nunca mais o traz.
        marcarEmAndamento(place, false);
        refazerSelosSeOutroNaTela(place);
        return true;
    };
    // O mesmo Desfazer do card — ver a exclusão acima.
    const desfazer = () => { if (cancelar()) registrarDesfazer(); };
    aprovacaoPendente = { timer: setTimeout(enviar, UNDO_WINDOW_MS), enviar, desfazer, cancelar };
    aplicarTravaDeAcao();
    mostrarDesfazer(t('undo.photoApproved'), () => aprovacaoPendente && aprovacaoPendente.desfazer());
    // O "Aprovar" com o foco virou lixeira travada: o foco fica na camada.
    manterFocoNoLightbox();
}

// ── Renomear o local, do lightbox ──────────────────────────────────────────
//
// A ÚNICA escrita de dado de LOCAL do app, e o que a justifica é a natureza da
// decisão, não a conveniência: o editor está com a FACHADA ampliada na tela, que
// é prova primária do nome. E a alternativa não é decidir melhor no WME — é a
// MESMA gravação com uma ida e volta no meio. Medido no HAR do owner renomeando
// lá: o WME não busca duplicado, não valida convenção, não confere nada. Manda
// `{id, name}`.
//
// Portão: o mesmo dos outros destrutivos (`podeAgirComoL6Aqui`), e só do
// CLIENTE — o Waze valida `permissions`/`lockRank` na gravação, então quem não
// pode por aqui também não consegue por lá.
let renomeacaoPendente = null;   // { timer, enviar, desfazer }

// Os locais (pelo `venueID`, que os pedidos irmãos dividem) com uma renomeação
// SAINDO — do envio até a resposta final, retentativas e a segunda ida depois
// de um 401 incluídas. A pílula desse local fica travada até lá: renomear uma
// vez e "corrigir de novo" com a primeira ainda no ar fazia as duas cruzarem.
// MEDIDO (sem Desfazer): a 1ª com uma falha passageira era retentada DEPOIS
// da 2ª e o Waze ficava com o nome do meio ("B") com a tela dizendo "C"; a 1ª
// que falhava de vez voltava a tela ao nome de ANTES ("A") com o Waze em "C"
// (auditoria de 2026-09-29, L23). Uma por local, e o nome da tela é sempre o
// da última escrita que valeu.
const renomeacoesNoAr = new Set();

function renomeacaoNoAr(place) {
    return !!(place && place.venueID != null && renomeacoesNoAr.has(place.venueID));
}

function podeRenomearAqui() {
    // Mesmo portão da foto. Função própria (em vez de chamar a outra direto)
    // porque são DUAS decisões de produto que hoje coincidem: se um dia o owner
    // separar, o call site não muda.
    if (!podeAgirComoL6Aqui()) return false;
    const p = Lightbox.place;
    // v1 só CORRIGE nome existente. Batizar local sem nome é outra decisão (e
    // outra conversa) — sem isto, um toque acidental nomearia um lugar anônimo.
    if (!(p && p.venueID && String(p.name || '').trim())) return false;
    // O Waze RECUSA escrever atributo em local que ainda não existe no mapa —
    // MEDIDO com controle: mesmo payload, mesma sessão, `approved:false` → 406,
    // `approved:true` → 200. Oferecer aqui é beco sem saída: o editor abre a
    // foto, digita o nome certo, confirma e leva "Erro do Waze (HTTP 406)" —
    // que ainda por cima cai em `errorCategory: unknown`, o balde que reverte o
    // placar e mostra erro genérico.
    // Não é caso de canto: 711 de 2420 cards com nome (29%) estão em local não
    // aprovado nos 6 países obrigatórios, e 40% da fila do owner no Brasil.
    return p.localAprovado !== false;
}

function mostrarNomeNoLightbox() {
    const cx = document.getElementById('lightboxNome');
    if (!cx) return;
    const pode = podeRenomearAqui() && !Treino.ativo;
    cx.classList.toggle('hidden', !pode);
    // A dica de zoom mora no mesmo canto. Some pra quem tem a pílula — é editor
    // L6+AM, que já sabe dar zoom; pro resto ela fica o tempo que o `open` dá.
    // Daqui ela só SAI: quem a mostra é o `open`, que tem o relógio que a tira
    // em 4 s. Esta função passou a rodar também com o perfil chegando com a foto
    // aberta (`reavaliarFotoAbertaPeloPerfil`, R6-3-07) — o perfil atrasado, a
    // renovação da sessão e a sonda de todo 401 —, e o `toggle` que estava aqui
    // trazia a dica de volta pra quem não tem a pílula, sem relógio nenhum: ela
    // FICAVA sobre a foto até fechar (auditoria de 2026-10-02, R7-3-02, MEDIDO
    // nos dois motores com um L4+AM).
    const dica = document.getElementById('lightboxZoomHint');
    if (dica && pode) dica.classList.add('hidden');
    if (!pode) { fecharEdicaoNome(); return; }
    const txt = document.getElementById('lightboxNomeTxt');
    if (txt) txt.textContent = Lightbox.place.name;
    // A trava da pílula é do LOCAL da camada (o nome dele no ar, L23; uma
    // exclusão dele no ar, R11-3-06), e o `disabled` dela era o que a trava
    // escreveu da última vez — com a camada de OUTRO pedido, ou fechada. A camada
    // aberta num IRMÃO com uma escrita do local no ar nascia com a pílula VIVA: o
    // toque nela não fazia nada (`abrirEdicaoNome` recusa calado) ou, antes do
    // R11-3-06, abria a correção que a exclusão fechava ao pousar (MEDIDO nos dois
    // motores). Quem escreve o `disabled` segue sendo só a trava (gotcha #63).
    aplicarTravaDeAcao();
}

function abrirEdicaoNome() {
    if (!podeRenomearAqui() || Treino.ativo || acoesTravadas() || renomeacaoNoAr(Lightbox.place)) return;
    // Uma exclusão de foto deste local no ar (R11-3-06): a pílula já está
    // travada, e o teclado ou um script não furam a trava.
    if (exclusaoDoLocalNoAr(Lightbox.place)) return;
    const cx = document.getElementById('lightboxNome');
    const nome = Lightbox.place.name;
    cx.classList.add('editando');
    // A pílula CONTINUA na tela, mostrando o nome antigo — é ela a referência
    // enquanto se digita. Vira RÓTULO: `disabled` tira do Tab e mata o clique,
    // e o lápis sai porque prometer ação onde não há é o que faz botão morto
    // parecer vivo. Isto substitui a linha "Antes:" que eu tinha posto embaixo:
    // o owner viu o nome DUAS vezes na tela e preferiu, com razão, ficar só com
    // a pílula — ela flutua sobre a foto e não custa altura de layout. O
    // `disabled` vem da função da trava, que é o escritor ÚNICO dele (L9).
    const btn = document.getElementById('lightboxNomeBtn');
    aplicarTravaDeAcao();
    btn.querySelector('.lb-nome-lapis')?.classList.add('hidden');
    document.getElementById('lightboxNomeEdit').classList.remove('hidden');
    const inp = document.getElementById('lightboxNomeInput');
    inp.value = nome;
    // As ações de foto somem enquanto edita — mas quem decide é
    // `atualizarAcoesDeFoto()`, e não um esconder aqui: esconder aqui era um
    // disparo único, e a próxima troca de foto o desfazia.
    document.getElementById('imageLightbox').classList.add('editando-nome');
    atualizarAcoesDeFoto();
    inp.focus();
    // Cursor no FIM, não seleção: quem vem corrigir grafia quer ajustar, e
    // selecionar tudo faz a primeira tecla apagar o nome inteiro.
    try { inp.setSelectionRange(inp.value.length, inp.value.length); } catch (e) { /* tipo sem seleção */ }
    atualizarBotaoSalvarNome();
}

function fecharEdicaoNome() {
    const cx = document.getElementById('lightboxNome');
    if (!cx) return;
    cx.classList.remove('editando');
    const btn = document.getElementById('lightboxNomeBtn');
    const ed = document.getElementById('lightboxNomeEdit');
    // Volta a ser botão — ou fica travada, se a janela do Desfazer corre: quem
    // decide é a função da trava, não um `disabled = false` daqui (L9).
    aplicarTravaDeAcao();
    if (btn) btn.querySelector('.lb-nome-lapis')?.classList.remove('hidden');
    if (ed) ed.classList.add('hidden');
    document.getElementById('imageLightbox').classList.remove('editando-nome');
    // Recalcula em vez de restaurar o que foi guardado: a foto pode ter mudado
    // durante a edição, e restaurar devolveria o estado da foto ERRADA.
    atualizarAcoesDeFoto();
}

function editandoNome() {
    const cx = document.getElementById('lightboxNome');
    return !!(cx && cx.classList.contains('editando'));
}

// A pessoa SAI da edição do nome com a foto ainda aberta: o ✕, o Esc do campo
// e os passos pra trás de `recuarNaFoto`. É desistir da edição, não da foto —
// que segue na tela como a prova do nome. O campo e o ✓/✕ somem, e o foco
// (que estava num deles) volta pra pílula do nome em vez de cair no <body>.
function sairDaEdicaoNome() {
    fecharEdicaoNome();
    manterFocoNoLightbox();
}

// Um passo pra TRÁS na foto ampliada: o Esc e o ↓ (com o foco fora do campo),
// o toque no fundo e o arraste da foto pra baixo. Editando o nome, o passo é
// sair da EDIÇÃO — como o Esc do campo sempre fez —, e não fechar a foto: os
// quatro fechavam, jogando fora o nome digitado e a foto que servia de prova
// (auditoria de 2026-09-26, medido nos três aparelhos). Sem edição, fecha.
function recuarNaFoto() {
    if (editandoNome()) { sairDaEdicaoNome(); return; }
    Lightbox.close();
}

function atualizarBotaoSalvarNome() {
    const inp = document.getElementById('lightboxNomeInput');
    const ok = document.getElementById('lightboxNomeOk');
    if (!inp || !ok) return;
    const v = inp.value.trim();
    // Vazio ou igual ao atual não é renomeação. Botão morto com cara de vivo lê
    // como app quebrado, então ele fica `disabled` E esmaecido. Com as ações
    // travadas (a conferência de um 401, a sessão caindo) ele também não salva
    // — o `confirmarRenomear` confere a MESMA trava (a hipótese do L23).
    ok.disabled = acoesTravadas() || !v || v === String(Lightbox.place && Lightbox.place.name || '').trim();
}

function confirmarRenomear() {
    if (Treino.ativo) return;
    // O Enter do campo chega aqui direto, sem passar por botão travado: sem
    // sessão (a queda no meio da edição), o nome não sai (K1). E, com a edição
    // aberta, o Enter DIZ o que esperar, como na conferência de um 401 (L23,
    // logo abaixo): na renovação da sessão ele saía calado, com o nome digitado
    // e o ✓ travado sem motivo à vista (R6-3-10, auditoria de 2026-10-01). Antes
    // do portão de propósito: a queda leva o perfil junto, e o portão fechado
    // era o primeiro a sair, calado.
    if (!AppState.authenticated) {
        if (editandoNome()) showToast(t(avisoDaTrava()), 'info');
        return;
    }
    if (!podeRenomearAqui()) return;
    const inp = document.getElementById('lightboxNomeInput');
    const novo = inp ? inp.value.trim() : '';
    const place = Lightbox.place;
    const antigo = String(place.name || '').trim();
    if (!novo || novo === antigo) { sairDaEdicaoNome(); return; }
    // A MESMA trava dos outros botões (a hipótese do L23, confirmada): com a
    // edição aberta, o Enter renomeava DURANTE a conferência de um 401 de outra
    // escrita do lightbox — a que ainda pode sair de novo, e com a qual nada
    // pode cruzar (L1). O ✓ fica travado junto (`atualizarBotaoSalvarNome`), e
    // o Enter diz o que esperar em vez de sair calado. A edição fica aberta,
    // com o nome digitado. Com uma escrita do lightbox na janela do Desfazer a
    // trava também vale, e ela não é mais despachada por aqui: a pílula já
    // travava na janela (L9), e o que decide essa escrita é o Desfazer dela.
    if (acoesTravadas()) { showToast(t(avisoDaTrava()), 'info'); return; }
    // Uma renomeação deste local ainda no ar: a pílula já está travada (L23).
    if (renomeacaoNoAr(place)) return;

    fecharEdicaoNome();
    aplicarNomeNaTela(place, novo);      // retorno imediato; o envio espera

    // A região é a do GESTO (L26): o envio sai até 3 s depois.
    const alvo = { place, antigo, novo, regiao: API.getRegion() };
    const semJanela = AppState.preferences.undoEnabled === false && canDisableUndo();
    // O ✓ que tinha o foco sumiu com a edição: o foco fica na camada (a pílula,
    // ou o ✕ se ela travou na janela do Desfazer). Sem o banner do Desfazer, o
    // nome que pousou é dito ao leitor de tela (R6-3-08) — também com a foto já
    // fechada, pela região do card (R9-3-05, `anunciarDesfechoDaFoto`).
    if (semJanela) {
        enviarRenomeacao(alvo).then((gravou) => {
            if (gravou) anunciarDesfechoDaFoto(t('lightbox.anuncio.renomeado', { nome: novo }), place);
        });
        manterFocoNoLightbox();
        return;
    }

    let saiu = false;
    const enviar = () => {
        if (saiu) return;
        saiu = true;
        clearTimeout(renomeacaoPendente && renomeacaoPendente.timer);
        renomeacaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        // O nome novo vai aos IRMÃOS do local quando o Waze confirma
        // (`aplicarNosIrmaos`): a pílula e o `alt` da camada aberta de um deles,
        // ou o card dele na frente, mudam — e só o banner do gesto, sobre ESTE
        // pedido, tinha falado (R11-3-05, como a exclusão logo acima).
        enviarRenomeacao(alvo).then((gravou) => {
            if (gravou) anunciarDesfechoDaFoto(t('lightbox.anuncio.renomeado', { nome: novo }), place, true);
        });
    };
    const cancelar = () => {
        if (saiu) return false;
        saiu = true;
        clearTimeout(renomeacaoPendente && renomeacaoPendente.timer);
        renomeacaoPendente = null;
        aplicarTravaDeAcao();
        removeUndoBanner();
        aplicarNomeNaTela(place, antigo);
        return true;
    };
    // O mesmo Desfazer do card — ver a exclusão de foto.
    const desfazer = () => { if (cancelar()) registrarDesfazer(); };
    renomeacaoPendente = { timer: setTimeout(enviar, UNDO_WINDOW_MS), enviar, desfazer, cancelar };
    aplicarTravaDeAcao();
    mostrarDesfazer(t('undo.renamed', { nome: novo }), () => renomeacaoPendente && renomeacaoPendente.desfazer());
    manterFocoNoLightbox();
}

// O nome vive em três lugares e os três têm que andar juntos, senão o card diz
// uma coisa e o lightbox outra. E o texto ALTERNATIVO das duas fotos também é
// dele (`altDaFoto`): a pílula e o card mostravam o nome novo e o leitor de tela
// seguia ouvindo "Foto de <nome antigo> (2 de 3)" na foto ampliada e na do card,
// até trocar de foto (R6-3-09, auditoria de 2026-10-01).
function aplicarNomeNaTela(place, nome) {
    place.name = nome;
    if (Lightbox.place === place) Lightbox.placeName = nome;
    const txt = document.getElementById('lightboxNomeTxt');
    if (txt && Lightbox.place === place) txt.textContent = nome;
    const imgLb = document.getElementById('lightboxImage');
    if (imgLb && Lightbox.place === place && Lightbox.isOpen()) {
        imgLb.alt = altDaFoto(place, Lightbox.idx + 1, Lightbox.urls.length);
    }
    const card = cardDaFrente();
    if (card && AppState.currentPlace === place) {
        const el = card.querySelector('.card-name');
        if (el) el.textContent = nome;
        // Qual das fotos o carrossel do card mostra: a da `src` (a mesma URL que
        // ele pediu, `urlDaFoto`); as outras ganham o nome novo quando aparecerem.
        const foto = card.querySelector('.card-image');
        if (foto) {
            const { urls } = fotosDoCard(place);
            const i = urls.findIndex((u) => urlDaFoto(u) === foto.getAttribute('src'));
            if (i >= 0) foto.alt = altDaFoto(place, i + 1, urls.length);
        }
    }
}

// O nome NA TELA ainda é o desta escrita? É a régua das duas decisões que a
// escrita toma sobre a tela depois de sair (L23): repetir o envio (a
// retentativa, a segunda ida depois de um 401) e voltar o nome de antes quando
// ela falha. Nome na tela que não é o dela é de outra escrita — mais nova —, e
// gravar ou voltar por cima dele desfaria o que a pessoa vê.
function nomeDestaEscrita(alvo) {
    return String(alvo.place.name || '').trim() === alvo.novo;
}

// Volta a tela ao nome de antes, se ela ainda mostra o desta escrita. Devolve
// se voltou — e só então há o que avisar.
function devolverNome(alvo) {
    if (!nomeDestaEscrita(alvo)) return false;
    aplicarNomeNaTela(alvo.place, alvo.antigo);
    return true;
}

// Devolve se o nome foi GRAVADO e está na tela de quem ficou: é o que o caminho
// sem o Desfazer anuncia ao leitor de tela (R6-3-08).
async function enviarRenomeacao(alvo) {
    const epoca = epocaDaSessao;
    const local = alvo.place.venueID;
    // No ar até a resposta FINAL: a pílula deste local fica travada (L23).
    renomeacoesNoAr.add(local);
    aplicarTravaDeAcao();
    try {
        // Escrita SUPERADA não sai de novo: sem nome desta escrita na tela, a
        // ida vira nada (`null`), e nada volta nem é avisado lá embaixo.
        const enviar = () => (nomeDestaEscrita(alvo)
            ? API.renomearLocal(local, alvo.novo, alvo.regiao)
            : Promise.resolve(null));
        let r = await callWithRetry(enviar);
        if (epoca === epocaDaSessao && r && r.errorCategory === 'unauthorized') {
            r = await refazerDepoisDo401(epoca, enviar);
        }
        // A sessão ACABOU com o nome no ar (ver `epocaDaSessao`): nada GRAVA. A
        // resposta que chegava depois do "Sair" contava o "Corretor" e recriava
        // `waze_places_conquistas` pra quem entrasse depois (auditoria de
        // 2026-09-25). Mas o nome que não chegou ao Waze não pode seguir na tela
        // como gravado (V2, ver `escritaDoLightboxSemSessao`) — e o que CHEGOU vai
        // aos irmãos do local, como a foto excluída (R6-3-01): é fato do Waze, e o
        // card seguinte do mesmo local mostrava o nome velho, com a pílula
        // oferecendo corrigir o que já foi corrigido. O "Corretor" fica de fora.
        if (epoca !== epocaDaSessao) {
            if (!(r && r.success)) {
                escritaDoLightboxSemSessao(alvo.place, () => devolverNome(alvo), 'toast.renameFailed');
                return false;
            }
            if (!pedidoAindaNaTela(alvo.place)) return false;
            aplicarNosIrmaos(alvo.place, (q) => aplicarNomeNaTela(q, alvo.novo));
            return true;
        }
        if (r && r.success) {   // sem toast: o nome na tela já diz
            aplicarNosIrmaos(alvo.place, (q) => aplicarNomeNaTela(q, alvo.novo));
            contarConquista('nomes');
            return true;
        }
        // Falhou: o nome na tela precisa VOLTAR, senão o app afirma uma gravação
        // que não houve — e o editor segue triando achando que corrigiu.
        if (devolverNome(alvo)) showToast(msgDoServidor(r) || t('toast.renameFailed'), 'error');
        return false;
    } catch (e) {
        if (epoca !== epocaDaSessao) {
            escritaDoLightboxSemSessao(alvo.place, () => devolverNome(alvo), 'toast.renameFailed');
            return false;
        }
        if (devolverNome(alvo)) showToast(t('toast.renameFailed'), 'error');
        return false;
    } finally {
        renomeacoesNoAr.delete(local);
        aplicarTravaDeAcao();
    }
}

// A escrita do lightbox que NÃO chegou ao Waze porque a SESSÃO acabou com ela
// no ar — o 401 dela derrubou a sessão na conferência, ou a queda veio por outra
// chamada no meio do envio (V2, auditoria de 2026-09-29). Ela saía calada, e com
// a extensão RENOVANDO (a fila continua na tela, e a foto ampliada aberta) a
// foto seguia fora, a proposta "aprovada" e o nome trocado: MEDIDO, só o aviso
// de "acesso renovado", e nada no Waze.
//
// A tela VOLTA ao que o Waze tem, e avisa — o mesmo desfecho de toda escrita
// que falha, e a promessa do L1 ("se não der, desfaz na tela e avisa"). Não
// sai de novo com a sessão renovada, ao contrário da decisão do card: o card
// tem a fila de saída, que carrega a CONTA do gesto e só manda com a conta
// confirmada; aqui, reenviar sem essa prova é o buraco do K1 (a escrita de A
// saindo com o token de B). Com a tela de volta, a pessoa refaz com a sessão
// nova — é o que o card faz com a decisão que não pousou (ela volta a ser card).
//
// Só com o pedido AINDA NA TELA de quem ficou (`pedidoAindaNaTela`): depois do
// "Sair" a fila já foi embora, e não há o que voltar nem a quem avisar — e nada
// daqui grava (ver `epocaDaSessao`). `voltar()` devolve `false` quando não havia
// o que voltar (o nome na tela já não era o desta escrita).
function escritaDoLightboxSemSessao(place, voltar, chaveDoAviso) {
    if (!pedidoAindaNaTela(place)) return;
    if (voltar() === false) return;
    showToast(t(chaveDoAviso), 'error');
}

// O pedido de uma escrita do lightbox que a queda da sessão pegou no ar segue na
// tela de quem ficou: na fila (a renovação com a MESMA conta a mantém) ou na
// foto aberta. Depois do "Sair" a fila foi embora; com outra conta, ela é outra.
// É a régua das duas pontas dessa escrita: a que NÃO chegou ao Waze volta
// (`escritaDoLightboxSemSessao`) e a que POUSOU aparece (R6-3-01) — as duas, só
// pra quem ainda vê o pedido.
// A fila é a REAL (`filaReal`): com o treino aberto ela fica guardada nele e
// volta no `sair()`. Pela da tela (os exemplos), a exclusão que pousou depois da
// queda não chegava ao pedido nem ao irmão — de volta à fila, a lixeira oferecia
// a foto que já tinha saído e dizia "Outro editor já tinha excluído 👍" sobre a
// exclusão da própria pessoa —, e a que NÃO chegou ao Waze não voltava nem
// avisava: a foto fora e o nome novo seguiam na tela sem estar no mapa (auditoria
// de 2026-10-03, R8-3-02 = R8-7-02, MEDIDO no navegador). O aviso sai com o
// treino aberto: é sobre uma escrita de verdade. E o pedido que o Waze RECUSOU
// de vez com o treino aberto, que espera o "Sair" pra voltar como card, também é
// da tela (`filaRealComDevolvidos`, R9-7-01).
function pedidoAindaNaTela(place) {
    return filaRealComDevolvidos().includes(place) || (Lightbox.isOpen() && Lightbox.place === place);
}

// A sessão ACABOU (queda ou "Sair") com uma escrita do lightbox na janela do
// Desfazer: ela não sai, e o que ela antecipou na tela volta (a foto que sumiu,
// o ✨ que saiu, o nome novo). O banner some junto com a sessão — sem isto a
// janela corria invisível, `acoesTravadas()` seguia verdadeiro, e a escrita
// saía quando ela vencia, com o token de quem tivesse entrado nesse meio (a
// extensão renova sozinha): MEDIDO, "excluir-foto com token-renovado"
// (auditoria da costura, 2026-09-26, K1). É o `cancel` do `pendingAction`,
// pro lightbox — e não conta como Desfazer do editor.
function cancelarPendenciasDoLightbox() {
    for (const p of [renomeacaoPendente, aprovacaoPendente, exclusaoPendente]) {
        if (!p || typeof p.cancelar !== 'function') continue;
        try { p.cancelar(); } catch (e) { console.error('Falha ao cancelar escrita do lightbox:', e); }
    }
}

// O par do de cima, pra quem troca a fila COM a sessão viva — atualizar (↻),
// aplicar os Filtros, entrar no treino: a escrita do lightbox na janela do
// Desfazer SAI agora, como a do card (`pendingAction.execute()`). Eles só
// tiravam o banner, e a janela seguia correndo sem ele: o card ficava travado
// ~2,5 s sem banner nenhum na tela ("espere o Desfazer" de um Desfazer que
// sumiu) e a escrita saía no fim mesmo assim (auditoria de 2026-09-29, L25). A
// ordem é a do "Marcar todos" (`handleBatchMarkRead`), que já fazia isto.
function enviarPendenciasDoLightbox() {
    for (const p of [aprovacaoPendente, exclusaoPendente, renomeacaoPendente]) {
        if (!p || typeof p.enviar !== 'function') continue;
        try { p.enviar(); } catch (e) { console.error('Falha ao enviar escrita do lightbox:', e); }
    }
}

// Banner próprio, com a MESMA aparência e o mesmo tempo do Desfazer do card —
// é a mesma ideia, e duas gramáticas pro mesmo conceito é como o editor
// descobre que o app se contradiz.
function mostrarDesfazer(mensagem, aoDesfazer) {
    removeUndoBanner();
    const container = document.getElementById('undoContainer');
    if (!container) return;
    const banner = document.createElement('div');
    banner.className = 'undo-banner';
    banner.innerHTML = `
        <span>${escapeHtml(mensagem)}</span>
        <button type="button" id="undoBtn">${escapeHtml(t('undo.button'))}</button>
        <span class="undo-progress" style="animation-duration: ${UNDO_WINDOW_MS}ms" aria-hidden="true"></span>
    `;
    container.appendChild(banner);
    document.getElementById('undoBtn').addEventListener('click', (ev) => {
        // Enter no "Desfazer" com a foto já fechada: o banner some com o foco
        // nele, e o foco caía no <body> — o do card ganhou o par dele no C10, e
        // este não (auditoria de 2026-09-30, R5-3-07). Pelo teclado (o mesmo
        // critério do card), ele vai à foto do card, de onde a escrita saiu. Com
        // a foto ou o mapa abertos, quem segura o foco é a camada.
        const peloTeclado = veioDoTeclado(ev);
        aoDesfazer();
        if (peloTeclado && focoPerdido() && semCamadaAberta()) devolverFocoDaAmpliacao(null, ['.card-image', '.card-map']);
    });
}

// ── Os países editáveis, POR SERVIDOR ──────────────────────────────────────
// O `/Session` traz `editableCountryIDs` de UM servidor só (MEDIDO nas contas do
// owner: [30] no ROW, [] no NA e no IL), e o perfil que fica no `AppState` é o
// do servidor em que ele foi pedido. Quem edita só na NA (ou em Israel) abre na
// ROW (o de fábrica, e depois de todo "Sair"): o perfil de lá vem vazio, o
// `paisDoPerfil` pergunta o NA e leva a pessoa pros EUA — e a lista que ele leu
// lá ia embora. Os Filtros dessa sessão mostravam a lista do NA inteira, sem a
// dica, e dava pra aplicar o Canadá, onde ela não edita (fila vazia); reaberto o
// app, o perfil é lido no NA e a peneira valia: a mesma pessoa via duas listas,
// conforme a sessão começou (auditoria da rodada 7, R7-6-02). Os editáveis que o
// app LEU ficam aqui, por servidor — sem pedido a mais: são os da carga do
// perfil (`loadProfileAndAuxData`) e os que o `paisDoPerfil` já perguntou.
//
// Presos à CONTA (o id do perfil), e só valem com ela no app: o perfil novo da
// MESMA conta (a sonda do alarme falso de um 401, que troca o objeto do perfil)
// segue com o que foi lido, e outra conta não herda nada — a primeira leitura
// dela recomeça a lista, e até lá nada vale. Sem perfil (o "Sair"), nada vale.
//
// `areas`: as áreas de edição do MESMO `/Session`, que também são POR SERVIDOR
// (MEDIDO no Waze real, nas duas contas do owner: 8 e 1 áreas na ROW, 0 na NA e
// na IL). Fica a CAIXA de "Minha área" daquele servidor (`caixas`, lida por
// `caixaDaMinhaAreaEm`); sem a lista (não veio), a daquele servidor não muda.
//
// `gerenciadas`: as ÁREAS GERENCIADAS do mesmo `/Session`, também POR SERVIDOR
// (MEDIDO no Waze real, só leitura, nas duas contas do owner: 9 na ROW e 0 na NA
// e na IL; 1, 0 e 0). O seletor "Área gerenciada" e a conferência da área do
// filtro usavam as do perfil da ABERTURA, mesmo com a fila noutro servidor: quem
// só edita na NA abria na ROW, o app o levava pra NA, e o seletor mostrava só
// "Nenhuma" (auditoria da rodada 10, R10-6-03). Ficam as daquele servidor (lidas
// por `areasGerenciadasLidas`); sem a lista, as daquele servidor não mudam.
let editaveisPorServidor = { conta: null, lidos: {}, caixas: {}, gerenciadas: {} };
function anotarEditaveis(perfil, regiao, lista, areas, gerenciadas) {
    if (!perfil || typeof perfil !== 'object' || perfil.id === null || perfil.id === undefined || !regiao) return;
    const ids = (Array.isArray(lista) ? lista : []).map(Number).filter((n) => Number.isInteger(n) && n > 0);
    if (editaveisPorServidor.conta !== String(perfil.id)) editaveisPorServidor = { conta: String(perfil.id), lidos: {}, caixas: {}, gerenciadas: {} };
    editaveisPorServidor.lidos[regiao] = ids;
    if (Array.isArray(areas)) {
        if (!editaveisPorServidor.caixas) editaveisPorServidor.caixas = {};
        editaveisPorServidor.caixas[regiao] = caixaDaMinhaArea({ areas });
    }
    if (Array.isArray(gerenciadas)) {
        if (!editaveisPorServidor.gerenciadas) editaveisPorServidor.gerenciadas = {};
        editaveisPorServidor.gerenciadas[regiao] = gerenciadas.filter((a) => a && typeof a === 'object');
    }
}
// As áreas gerenciadas do servidor `regiao` que o app leu pra conta de `perfil`
// (por padrão, a de agora), ou `null` quando não leu: aí quem pergunta usa as do
// perfil que tem, como antes (R10-6-03).
function areasGerenciadasLidas(regiao, perfil = AppState.profile) {
    if (!perfil || typeof perfil !== 'object' || perfil.id === null || perfil.id === undefined) return null;
    if (editaveisPorServidor.conta !== String(perfil.id)) return null;
    const lidas = editaveisPorServidor.gerenciadas;
    return lidas && Object.prototype.hasOwnProperty.call(lidas, regiao) ? lidas[regiao] : null;
}
// Os editáveis do servidor `regiao` que o app leu pra conta de agora, ou
// `null` quando não leu (`[]` é "leu, e a pessoa não edita lá").
function editaveisLidos(regiao) {
    const perfil = AppState.profile;
    if (!perfil || typeof perfil !== 'object' || perfil.id === null || perfil.id === undefined) return null;
    if (editaveisPorServidor.conta !== String(perfil.id)) return null;
    const lidos = editaveisPorServidor.lidos;
    return Object.prototype.hasOwnProperty.call(lidos, regiao) ? lidos[regiao] : null;
}
// O servidor `regiao` NUNCA foi lido pra conta do perfil de agora, e outro foi:
// o que o perfil guardado traz (as áreas, as áreas gerenciadas) é de OUTRO
// servidor, e não cruza com este — a mesma régua do país (os ids não cruzam
// servidores). O app anota sempre o servidor em que perguntou o perfil (a carga
// e a sonda), então o perfil de agora tem pelo menos uma leitura; sem nenhuma
// (o perfil sem id), não se sabe de onde ele é, e nada se afirma.
function servidorNuncaLido(regiao) {
    const perfil = AppState.profile;
    if (!perfil || typeof perfil !== 'object' || perfil.id === null || perfil.id === undefined) return false;
    if (editaveisPorServidor.conta !== String(perfil.id)) return false;
    return !Object.prototype.hasOwnProperty.call(editaveisPorServidor.lidos, regiao);
}

// A lista de países que o seletor MOSTRA, pela MESMA régua na abertura dos
// Filtros (a lista da região aplicada, `AppState.countries`) e na troca de
// região (`aoTrocarRegiaoNoModal`, com a lista da região escolhida). A troca
// punha a lista INTEIRA, inclusive ao voltar pra região aplicada: os Filtros
// mostravam duas listas pro mesmo servidor, e na volta dava pra aplicar um país
// que a pessoa não edita — fila vazia, e a reabertura mostrava OUTRO país no
// lugar do aplicado, que o "Aplicar" seguinte gravava calado (auditoria da
// rodada 6, R66-4). A peneira usa os editáveis do servidor DESTA lista
// (`editaveisLidos`, R7-6-02); sem leitura de lá, os do perfil, que são de outro
// servidor e não cruzam com ela: a lista vai inteira, sem a dica.
//
// Devolve se o seletor ficou no país APLICADO (a troca que volta pra região
// aplicada repõe a área com ele).
//
// `manter`: o país que o seletor MOSTRAVA continua na lista e escolhido (o
// perfil que chega com a lista já na tela, `peneirarPaisesComOPerfil`).
function populateCountrySelect(lista = AppState.countries, regiao = API.getRegion(), manter = null) {
    const select = document.getElementById('filterCountry');
    const hint = document.getElementById('filterCountryHint');
    const editable = editaveisLidos(regiao) || (AppState.profile && AppState.profile.editableCountryIDs) || [];
    const todos = lista || [];
    let countries = todos;

    // A dica ("só os países que você pode editar") diz o que ESTA lista é, e
    // por isso é decidida a cada lista: só se ACENDIA, e seguia na tela com a
    // lista inteira depois de uma troca de região ou de um perfil sem países
    // editáveis aqui (auditoria de 2026-09-26).
    let filtrou = false;
    if (editable.length > 0) {
        const filtered = todos.filter(c => editable.includes(c.id));
        if (filtered.length > 0) {
            countries = filtered;
            filtrou = true;
        }
    }
    // O país APLICADO que a peneira tirou (escolhido antes de o perfil chegar,
    // ou um perfil que perdeu o país) entra como opção: o seletor nunca mostra
    // outro país como se fosse o aplicado, e o "Aplicar" não o troca calado
    // (R66-4). E o que o seletor MOSTRAVA quando o perfil chegou (`manter`): a
    // pessoa o escolheu antes de haver peneira, e o perfil não troca a escolha
    // dela calado (a régua do achado 11, R7-6-01). Com eles a lista deixa de ser
    // "só os que você pode editar", e a dica não diz isso.
    const current = API.getCountry();
    const ehOAplicado = (c) => String(c.id) === String(current);
    const ehOMantido = (c) => manter !== null && String(c.id) === String(manter);
    const naRegiaoAplicada = regiao === API.getRegion();
    const peneirou = filtrou;
    for (const fica of [naRegiaoAplicada ? ehOAplicado : null, ehOMantido]) {
        if (!fica || !peneirou || countries.some(fica)) continue;
        const pais = todos.find(fica);
        if (pais) {
            countries = [...countries, pais];
            filtrou = false;
        }
    }
    hint.classList.toggle('hidden', !filtrou);

    select.innerHTML = ordenarPorNome(countries).map(c =>
        `<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}</option>`
    ).join('');

    if (countries.some(ehOMantido)) {
        select.value = String(manter);
        return naRegiaoAplicada && String(manter) === String(current);
    }
    if (naRegiaoAplicada && countries.some(ehOAplicado)) {
        select.value = current;
        return true;
    }
    if (countries.length > 0) {
        // Só ajusta o select visualmente; a persistência do país acontece no
        // Aplicar (antes, abrir o modal já trocava o país mesmo cancelando).
        select.value = countries[0].id;
        // O país mostrado não é o aplicado: a área dele também não vale (F7).
        aoMudarPaisNaTela();
    }
    return false;
}

// Ordena nomes na colação do idioma ATUAL. Fica no cliente porque é o único
// lado que conhece o idioma — o servidor ordenava com 'pt-BR' cravado, aplicando
// regra portuguesa à lista de um editor francês.
//
// MEDIDO contra o Waze de verdade (248 países, cookies reais do owner), e o
// resultado corrige o que eu supunha: os nomes de país vêm SEMPRE EM INGLÊS
// ("France", "Germany", "Spain"), e o Waze ignora Accept-Language, Referer e
// ?language= nesses endpoints. Só 3 nomes têm acento (Curaçao, Côte d’Ivoire,
// Saint Barthélemy) e pt/en/es/fr os ordenam IGUAL — a ordem é idêntica nos
// quatro. Nomes de estado vêm no idioma local (Amapá, Ceará), que é o nome
// próprio deles: não há tradução a fazer.
//
// Ou seja: hoje isto não muda um pixel. Está aqui porque a decisão pertence a
// quem sabe o idioma, e porque a ordem DIVERGE em línguas de colação diferente
// (medido: sueco difere no índice 52, por causa do Å/Ä/Ö no fim do alfabeto).
// Se entrar sueco/polonês/turco, aí a ordem passa a mudar ao trocar de idioma
// com o modal aberto — e só então vale reordenar em aplicarIdioma().
function ordenarPorNome(itens) {
    const colator = new Intl.Collator(i18nLocale(), { sensitivity: 'base', numeric: true });
    return [...itens].sort((a, b) => colator.compare(String(a.name || ''), String(b.name || '')));
}

// Cada carga de estados tem um número: trocar de país (ou de região) no meio de
// uma carga não pode deixar a resposta VELHA sobrescrever a nova.
let cargaDeEstados = 0;
async function loadStatesIntoSelect(countryId, regiao) {
    const select = document.getElementById('filterState');
    const minha = ++cargaDeEstados;
    // As opções de TEXTO levam o `data-i18n`, como a do HTML: é por ele que a
    // troca de idioma com o modal aberto alcança o "Todos os estados" (F6).
    select.innerHTML = '<option value="" data-i18n="filters.state.all">' + escapeHtml(t('filters.state.all')) + '</option>';
    delete select.dataset.carregando;
    if (!countryId) return;

    let states = AppState.statesByCountry[countryId];
    if (!states) {
        // Enquanto carrega, o seletor DIZ que carrega (como o de país), e o
        // "Aplicar" nesse meio não grava nada por cima do estado da pessoa (ver
        // `applyFiltersFromModal`). O "Todos" que ele mostrava não era escolha
        // de ninguém.
        select.innerHTML = '<option value="" data-i18n="filters.carregando">' + escapeHtml(t('filters.carregando')) + '</option>';
        select.dataset.carregando = '1';
        const result = await API.listStates(countryId, regiao);
        if (minha !== cargaDeEstados) return;
        if (!(result && result.success)) {
            // A lista não veio (sinal ruim): segue "carregando" pro "Aplicar" —
            // que assim não apaga o estado salvo — e o seletor diz o que houve.
            // A falha soltava o seletor em "Todos os estados", e o "Aplicar"
            // gravava isso por cima do estado da pessoa, calado (auditoria da
            // fila, 2026-09-26). Reabrir os Filtros tenta de novo.
            select.innerHTML = '<option value="" data-i18n="filters.state.naoCarregou">' + escapeHtml(t('filters.state.naoCarregou')) + '</option>';
            return;
        }
        delete select.dataset.carregando;
        states = result.states || [];
        AppState.statesByCountry[countryId] = states;
        select.innerHTML = '<option value="" data-i18n="filters.state.all">' + escapeHtml(t('filters.state.all')) + '</option>';
    }

    for (const s of ordenarPorNome(states)) {
        const opt = document.createElement('option');
        opt.value = s.id;
        opt.textContent = s.name;
        select.appendChild(opt);
    }
    // O estado SALVO só vale no país em que foi salvo: o mesmo número existe em
    // países diferentes (ver o histórico, que chaveia por `pais:estado`), e
    // trocar de país no modal pré-selecionava um estado alheio — o 2 da Bahia
    // abria a França na Bretanha, e o "Aplicar" o gravava.
    if (AppState.filters.stateId && String(countryId) === String(API.getCountry())) {
        select.value = AppState.filters.stateId;
    }
}

// Trocar a REGIÃO traz os países DELA. Antes o seletor seguia com os da região
// anterior, e o "Aplicar" gravava, por exemplo, NA com o Brasil — uma fila vazia
// sem explicação. A lista passa pela MESMA peneira da abertura
// (`populateCountrySelect`): os editáveis do perfil são POR SERVIDOR (ver
// `paisDoPerfil`), então numa região que não é a do perfil a lista vai inteira,
// e a volta pra ela mostra o que a abertura mostra (R66-4).
//
// E o "Aplicar" ESPERA a lista chegar: com ela carregando, o seletor de país
// dizia "Carregando…" e o "Aplicar" gravava a região nova com o país da ANTIGA —
// MEDIDO no navegador: `na/30` (o Brasil no servidor da América do Norte) e
// "Tudo limpo!" (auditoria da fila, 2026-09-26). Se a lista não vier, a troca
// não se completa: a região aplicada volta, com os países dela, e o app diz.
//
// Cada carga da lista de PAÍSES no seletor tem um número, como a de estados
// (`cargaDeEstados`). São duas que o escrevem — esta troca e a da abertura
// (`popularPaisEstado`) — e só a ÚLTIMA a começar escreve: a lista, o país
// escolhido, a área e a espera do "Aplicar". A conferência era pela REGIÃO, e
// com a região trocada NA → ROW → NA as DUAS idas à NA passavam: a primeira a
// chegar soltava a lista e o "Aplicar", a pessoa escolhia os EUA, e a outra
// punha o 1º da lista de volta (o Canadá) e zerava a área — MEDIDO no
// navegador: 235 escolhido, 40 no fim (auditoria da rodada 5, R56-6). A escolha
// da pessoa vence a lista que chega depois, na régua do
// `redesenharLugarNosFiltros`: ela só escolhe numa lista que já é a da última
// carga, e nenhuma carga mais velha escreve depois dela.
let cargaDePaises = 0;
async function aoTrocarRegiaoNoModal(e) {
    const $ = (id) => document.getElementById(id);
    const regiao = e.target.value;
    const sel = $('filterCountry');
    const minha = ++cargaDePaises;
    // A lista da região nova é a INTEIRA: a dica de "só os que você pode editar"
    // sai junto, porque deixou de ser verdade (T5).
    $('filterCountryHint').classList.add('hidden');
    esperaDosFiltros.regiao = true;
    aplicarEsperaDosFiltros();
    sel.innerHTML = `<option value="" data-i18n="filters.carregando">${escapeHtml(t('filters.carregando'))}</option>`;
    sel.disabled = true;
    sel.dataset.carregando = '1';
    // A lista da região que CHEGOU fica guardada (R9-6-01): a ida e a volta, e o
    // "Aplicar" desta região, não pedem de novo (ver `pedirListaDePaises`).
    const r = await pedirListaDePaises(regiao);
    // Outra carga tomou o seletor no meio (outra troca, a reabertura dos
    // Filtros): esta não escreve nada, e quem solta o "Aplicar" é a de agora.
    if (minha !== cargaDePaises) return;
    delete sel.dataset.carregando;
    sel.disabled = !!$('filterMyArea').checked;
    esperaDosFiltros.regiao = false;
    aplicarEsperaDosFiltros();
    if (!(r && r.success)) {
        $('filterRegion').value = API.getRegion();
        showToast(t('toast.regiaoNaoCarregou'), 'error');
        // A região aplicada volta com os países dela pelo caminho da abertura,
        // que toma o seletor de novo: a carga da abertura que ainda vinha
        // deixou de ser a dona dele quando a troca começou.
        await popularPaisEstado();
        return;
    }
    // De volta à região APLICADA (trocou e voltou), o lugar aplicado volta
    // inteiro: o país — o estado vem com ele, que o `loadStatesIntoSelect` repõe
    // no país aplicado — e a área. Voltava o 1º da lista: aplicado `na/235`, ida
    // à ROW e volta, e o "Aplicar" gravava `na/40`, o Canadá (auditoria de
    // 2026-09-29, achado 12). Outra região é outro país: a área gerenciada que o
    // seletor mostrava era do país de antes, e o `populateCountrySelect` a tira
    // (ver `aoMudarPaisNaTela`).
    //
    // As OPÇÕES de área também são da região que o seletor mostra agora: as
    // áreas gerenciadas são por servidor (R10-6-03), e com as da região de antes
    // dava pra aplicar a área de um servidor junto da região de outro.
    populateManagedAreaSelect({ manterEscolha: true, regiao });
    if (populateCountrySelect(r.countries || [], regiao)) {
        const area = $('filterManagedArea');
        if (area) {
            area.value = AppState.filters.managedAreaId || '';
            if (area.selectedIndex < 0) area.value = '';
        }
    }
    await loadStatesIntoSelect(parseInt(sel.value, 10), regiao);
}

// ── O "Aplicar" dos Filtros ESPERA o que o modal ainda está buscando ────────
// São duas esperas: os países da região nova (`aoTrocarRegiaoNoModal`) e a
// posição do "📍 Perto de mim" (`aoTrocarOrdenacao`). Com o GPS ainda
// respondendo, o "Aplicar" gravava "Mais recentes" sem aviso — a opção sem
// posição cai no padrão — ou, com uma posição de antes, ordenava por ELA, e
// não pela de agora (auditoria de 2026-09-29, F1). O `disabled` do botão tem
// UM escritor só: com dois, o primeiro que terminasse devolveria o botão com o
// outro ainda no ar (gotcha #63). A abertura dos Filtros zera as duas.
const esperaDosFiltros = { regiao: false, gps: false };
function aplicarEsperaDosFiltros() {
    const b = document.getElementById('applyFilters');
    if (b) b.disabled = esperaDosFiltros.regiao || esperaDosFiltros.gps;
}

// O PAÍS mudou no seletor (o gesto da pessoa, a troca de região, ou a lista
// que não tem o país aplicado): a ÁREA GERENCIADA que ele mostrava era do país
// de antes, e o "Aplicar" a mandava junto com o país novo — MEDIDO: busca com
// `countryId 73` e `managedAreaId 9001`, a área de São Paulo na França (auditoria
// de 2026-09-29, F7). Volta pra "Nenhuma", como o `irProPaisDoPerfil` já fazia,
// e a pessoa escolhe outra se quiser. O que se vê é o que o "Aplicar" grava — e
// ele confere de novo (ver `applyFiltersFromModal`).
function aoMudarPaisNaTela() {
    const area = document.getElementById('filterManagedArea');
    if (area) area.value = '';
}

// As áreas gerenciadas vêm do PERFIL. Sem ele ainda — o atalho do PWA
// (`/?action=filters`) abre os Filtros ANTES dele, a rede lenta, o perfil que
// falhou —, a lista era só "Nenhuma", o seletor aparecia VAZIO com uma área
// salva, e o "Aplicar" gravava "nenhuma" por cima dela: a fila do país inteiro
// no lugar da área (auditoria de 2026-09-29, F2). Como a categoria salva
// (`populateCategorySelect`), a área SALVA entra como opção. O nome dela vem
// com o perfil: até lá ela diz "Carregando…", e o perfil que chega com os
// Filtros abertos a redesenha (`redesenharFiltrosComOPerfil`).
//
// `manterEscolha`: redesenhar mantém o que o seletor mostra AGORA — a pessoa
// pode já ter escolhido "Nenhuma" enquanto o perfil não vinha.
//
// As duas opções de texto levam o `data-i18n`, como a do HTML: sem ele, trocar
// o idioma nas Preferências deixava "Nenhuma" em português na aba Filtros do
// mesmo modal (F6), porque o `applyI18n` só alcança quem tem a chave.
//
// E as áreas são as do SERVIDOR da região que o modal mostra (`regiao`; por
// padrão, a do seletor de região), que o app leu (`areasGerenciadasLidas`): as
// áreas gerenciadas do `/Session` são POR SERVIDOR, e o perfil guardado é o do
// servidor em que ele foi pedido (R10-6-03).
//
// Servidor que o app NUNCA LEU pra esta conta (`servidorNuncaLido`): só
// "Nenhuma". As do perfil guardado são de OUTRO servidor, e o seletor as
// mostrava debaixo da região nova — MEDIDO no navegador: quem edita na ROW,
// trocando a região do modal pra NA (nunca lida), via "Área SP (ROW)", e o
// "Aplicar" buscava `na area 7001`, a área de um servidor com a região de outro
// (auditoria da rodada 11, R11-6-03). Decisão (2026-10-07): a mesma régua de
// "não cruzar" do país, sem pedido novo. A área SALVA também é de um servidor
// só, o da região APLICADA: o "Carregando…" dela (sem o perfil) aparece só
// debaixo da região dela.
function populateManagedAreaSelect({ manterEscolha = false, regiao = null } = {}) {
    const select = document.getElementById('filterManagedArea');
    const escolha = manterEscolha ? select.value : AppState.filters.managedAreaId;
    const regiaoNaTela = document.getElementById('filterRegion');
    const mostrada = regiao || (regiaoNaTela && regiaoNaTela.value) || API.getRegion();
    const lidas = areasGerenciadasLidas(mostrada);
    const areas = Array.isArray(lidas) ? lidas
        : servidorNuncaLido(mostrada) ? [] : ((AppState.profile && AppState.profile.managedAreas) || []);
    const salva = AppState.filters.managedAreaId;
    const salvaSemNome = !AppState.profile && !!salva && mostrada === API.getRegion();
    select.innerHTML = '<option value="" data-i18n="filters.managedArea.none">' + escapeHtml(t('filters.managedArea.none')) + '</option>'
        + (salvaSemNome ? `<option value="${escapeHtml(salva)}" data-i18n="filters.carregando">${escapeHtml(t('filters.carregando'))}</option>` : '')
        + areas.map(a => `<option value="${escapeHtml(a.id)}">${escapeHtml(a.name)}</option>`).join('');
    select.value = escolha || '';
    // A área que o perfil NÃO tem mais (tirada no WME) mostra "Nenhuma", que é
    // o que o "Aplicar" grava: com o `value` de uma opção que não existe, o
    // seletor aparecia VAZIO.
    if (select.selectedIndex < 0) select.value = '';
}

// O seletor "Área gerenciada" guarda o NOME das áreas da conta (o `/Session`
// dela), e só era redesenhado ao abrir os Filtros: fechado, ele seguia no DOM
// com as áreas de quem estava — depois do "Sair", na tela de entrada, e na
// sessão de OUTRA conta que entrava pela renovação, cujo relatório do modo dev
// leva o DOM (MEDIDO no navegador; auditoria da rodada 11, R11-1-05). Volta ao
// que o HTML traz — só "Nenhuma", com a chave dela — pelos mesmos caminhos do
// painel do Histórico (`esvaziarPainelDoHistorico`): o modal que fecha, a tela de
// entrada e a troca de conta. Esvaziar é seguro: a abertura dos Filtros
// (`openFiltersModal`, a ÚNICA que os abre) o redesenha antes de mostrar.
function esvaziarSeletorDeAreas() {
    const select = document.getElementById('filterManagedArea');
    if (select) select.innerHTML = '<option value="" data-i18n="filters.managedArea.none">' + escapeHtml(t('filters.managedArea.none')) + '</option>';
}

// Preenche o select de categoria a partir das categorias vistas (B5).
function populateCategorySelect() {
    const sel = document.getElementById('filterCategory');
    if (!sel) return;
    const current = (AppState.filters.categories && AppState.filters.categories[0]) || '';
    // Com o `data-i18n`, como a do HTML: é por ele que a troca de idioma com o
    // modal aberto alcança o "Todas as categorias" (F6).
    const opts = ['<option value="" data-i18n="filters.category.all">' + escapeHtml(t('filters.category.all')) + '</option>'];
    // A categoria SALVA entra mesmo sem pedido dela na fila. As opções saem do
    // que a fila já mostrou (`seenCategories`), e com o filtro ligado numa
    // categoria sem nenhum pendente hoje a fila vem vazia: sem ela na lista, o
    // seletor aparecia VAZIO e o próximo "Aplicar" (pra trocar só a ordem, por
    // exemplo) gravava "Todas" por cima, calado (auditoria da fila, 2026-09-26).
    const vistas = AppState.seenCategories || [];
    const lista = current && !vistas.includes(current)
        ? [...vistas, current].sort((a, b) => String(a).localeCompare(String(b), i18nLocale()))
        : vistas;
    for (const c of lista) {
        opts.push('<option value="' + escapeHtml(c) + '">' + escapeHtml(c) + '</option>');
    }
    sel.innerHTML = opts.join('');
    sel.value = current;
}

async function openFiltersModal() {
    const $ = id => document.getElementById(id);
    // Sempre abre na aba Filtros (uso primário do botão do header); as outras
    // abas ficam a um toque, sem "lembrar" estado velho de forma surpreendente.
    switchFilterTab('filtersTabFilters');
    renderDevModeSection();
    renderUndoGateUI();
    renderPresencaPref();
    renderPularGuardaPref();
    $('filterUnreadOnly').checked = AppState.filters.unreadOnly !== false;
    document.querySelectorAll('.filter-type').forEach(cb => {
        cb.checked = AppState.filters.types.includes(cb.value);
    });
    $('filterResidential').value = AppState.filters.residential;
    $('filterRegion').value = API.getRegion();
    // As esperas do "Aplicar" recomeçam aqui (ver `aplicarEsperaDosFiltros`):
    // a troca de região que ficou no ar desiste, porque a carga da abertura
    // (`popularPaisEstado`, no fim desta função) toma o seletor de país (ver
    // `cargaDePaises`), e o pedido de posição que ficou no ar é abandonado —
    // nenhum dos dois devolveria o botão sozinho.
    esperaDosFiltros.regiao = false;
    esquecerPosicaoDoModal();
    aplicarEsperaDosFiltros();

    populateManagedAreaSelect();
    $('filterMyArea').checked = AppState.filters.myArea;
    const disabled = AppState.filters.myArea;
    $('filterCountry').disabled = disabled;
    $('filterState').disabled = disabled;
    $('filterManagedArea').disabled = disabled;

    populateCategorySelect();
    popularOrdenacoes();
    const sortSel = $('filterSort');
    if (sortSel) sortSel.value = ordemValida(AppState.filters.sortOrder);
    atualizarDicaDeOrdem(sortSel && (sortSel.value === 'casa' || sortSel.value === 'trabalho') ? 'perfil'
        : (sortSel && sortSel.value === 'gps' ? 'ok' : null));
    renderHistory();

    // O modal ABRE AQUI, antes de qualquer rede. País e estado vêm do Waze e,
    // na PRIMEIRA abertura da sessão, são duas idas — MEDIDO com o app de pé:
    // o modal só aparecia aos 480ms em rede boa e aos 1337ms em rede ruim,
    // porque o `openModal` era a última linha de uma função `async`. O editor
    // tocava em Filtros e não acontecia NADA até o Waze responder duas vezes.
    // Da segunda abertura em diante era 80ms, porque as duas listas ficam em
    // cache de memória — daí a lentidão ser intermitente e difícil de nomear.
    //
    // Tudo que é síncrono já está pronto acima; só as duas listas chegam depois
    // e se preenchem sozinhas. Quem abre pra mexer em tipo, categoria, ordem ou
    // preferência não espera rede nenhuma.
    openModal('filtersModal');
    await popularPaisEstado();
}

// A lista de países de UMA região, uma ida por vez (R8-6-04). A carga da
// abertura (`loadProfileAndAuxData`) e os Filtros (`popularPaisEstado`) pediam
// a MESMA lista quando os Filtros abriam antes de ela chegar — pelo atalho do
// ícone (`/?action=filters`) é sempre assim: dois `lista-paises` iguais, cada
// um um pedido ao nosso `/api` (o free tier) e uma ida ao Waze (MEDIDO no
// navegador, auditoria da rodada 8: 2 pelo atalho, 1 com os Filtros abertos
// depois da carga). A ida no ar é COMPARTILHADA, como a do perfil
// (`_profilePromise`): por região e por SESSÃO (`epocaDaSessao`) — a resposta
// da sessão que saiu não serve a quem entrou (o 401 dela, na carga, mandaria a
// sessão nova à conferência). E a lista que CHEGA bem fica na memória
// (`AppState.countries`) na hora, com a região ainda a pedida e a mesma sessão:
// a carga só a guardava junto do perfil, e os Filtros abertos nesse meio
// pediam outra. A que falha não fica: reabrir os Filtros pede de novo.
//
// E a que CHEGOU fica guardada POR REGIÃO (`listasDePaisesGuardadas`) e não é
// pedida de novo enquanto vale: só dividir a ida no ar não bastava. O perfil
// refeito depois de falhar na abertura, a troca de região no modal (a ida e a
// volta, e a lista que ela trouxe, que o "Aplicar" jogava fora), a ida pro país
// do perfil e a renovação pela extensão pediam de novo a lista que estava na
// memória — cada um um pedido ao `/api` e uma ida ao Waze pela MESMA lista
// (MEDIDO no navegador, auditoria da rodada 9, R9-6-01). Países não mudam no
// meio da sessão: a lista vale até o "Sair" ou outra conta entrar
// (`esquecerListasDePaises`). A queda da sessão não a apaga: a renovação é da
// mesma pessoa, e a lista que veio bem não traz o 401 de ninguém.
const listasDePaisesNoAr = new Map();
const listasDePaisesGuardadas = new Map();
// Sobe a cada esquecimento: a ida que estava no ar quando a lista foi esquecida
// não guarda nada nem serve a quem pede depois.
let geracaoDasListasDePaises = 0;
function esquecerListasDePaises() {
    listasDePaisesGuardadas.clear();
    geracaoDasListasDePaises++;
}
function pedirListaDePaises(regiao = API.getRegion()) {
    const guardada = listasDePaisesGuardadas.get(regiao);
    if (guardada) return Promise.resolve({ success: true, countries: guardada });
    const epoca = epocaDaSessao;
    const geracao = geracaoDasListasDePaises;
    const chave = epoca + '|' + geracao + '|' + regiao;
    const noAr = listasDePaisesNoAr.get(chave);
    if (noAr) return noAr;
    const ida = Promise.resolve(API.listCountries(regiao)).then((r) => {
        if (r && r.success && epoca === epocaDaSessao && geracao === geracaoDasListasDePaises) {
            // Lista VAZIA não fica: com ela, o seletor diria "nenhum país" pelo
            // resto da sessão, e quem a pede de novo é o próximo "Filtros".
            if (Array.isArray(r.countries) && r.countries.length) listasDePaisesGuardadas.set(regiao, r.countries);
            if (API.getRegion() === regiao) AppState.countries = r.countries;
        }
        return r;
    }).finally(() => {
        if (listasDePaisesNoAr.get(chave) === ida) listasDePaisesNoAr.delete(chave);
    });
    listasDePaisesNoAr.set(chave, ida);
    return ida;
}

// As duas listas que vêm do Waze. Fora do `openFiltersModal` porque ele agora
// só as AGENDA — e porque um erro aqui não pode impedir o modal de abrir.
async function popularPaisEstado() {
    const select = document.getElementById('filterCountry');
    const estado = document.getElementById('filterState');
    // A lista pedida aqui é a da região APLICADA.
    const regiao = API.getRegion();
    // Esta carga passa a ser a dona do seletor de país (ver `cargaDePaises`):
    // a troca de região que ficou no ar não escreve mais nele.
    const minha = ++cargaDePaises;
    // Enquanto não chega, o seletor diz o que está havendo em vez de ficar
    // vazio: seletor vazio parece defeito, e o editor toca de novo.
    const carregando = AppState.countries.length === 0;
    if (carregando && select) {
        select.innerHTML = `<option value="" data-i18n="filters.carregando">${escapeHtml(t('filters.carregando'))}</option>`;
        select.disabled = true;
        select.dataset.carregando = '1';
    }
    // O ESTADO espera junto: ele só se preenche depois dos países, e até lá
    // mostrava o "Todos os estados" da abertura anterior — que o "Aplicar"
    // gravava por cima do estado salvo, calado (auditoria de 2026-09-29, F3).
    // Carregando, o "Aplicar" não mexe nele (ver `applyFiltersFromModal`).
    if (carregando && estado) {
        estado.innerHTML = `<option value="" data-i18n="filters.carregando">${escapeHtml(t('filters.carregando'))}</option>`;
        estado.dataset.carregando = '1';
    }
    try {
        if (AppState.countries.length === 0) {
            // A MESMA ida da carga da abertura, se ela ainda estiver no ar (ver
            // `pedirListaDePaises`, R8-6-04).
            const r = await pedirListaDePaises(regiao);
            // A lista é da região PEDIDA: aplicada outra enquanto ela vinha,
            // ela não vale como a lista da região de agora...
            if (r.success && API.getRegion() === regiao) AppState.countries = r.countries;
        }
        // ...e só vai pro seletor se esta ainda for a última carga dele.
        // Trocada a região NO MODAL, quem é dono do seletor é a troca
        // (`aoTrocarRegiaoNoModal`); a lista da aplicada, chegando DEPOIS, o
        // sobrescrevia — MEDIDO: o seletor em ROW com os países da NA, e o
        // "Aplicar" gravando `row/235` (auditoria de 2026-09-29, V3). A
        // conferência era pela REGIÃO, e com a região trocada e VOLTADA pra
        // aplicada ela passava: punha o país aplicado por cima do que a pessoa
        // tinha escolhido na lista da troca (R56-6).
        if (minha !== cargaDePaises) return;
        // A lista NÃO veio (a rede, o servidor): o seletor de país ficava VAZIO e
        // destravado, com os estados do país aplicado logo abaixo — o defeito que
        // o de estados já não tem (auditoria da rodada 7, R7-6-04). Ele diz o que
        // houve com a MESMA opção do de estados ("Lista não carregou", em
        // `loadStatesIntoSelect`) e segue "carregando": o "Aplicar" não mexe no
        // país aplicado. O estado diz o mesmo e também fica como está — a lista
        // dele seria de um país que a tela não mostra, e pedi-la é um pedido a
        // mais. Reabrir os Filtros tenta de novo (a lista vazia é pedida de novo).
        if (AppState.countries.length === 0) {
            const naoCarregou = `<option value="" data-i18n="filters.state.naoCarregou">${escapeHtml(t('filters.state.naoCarregou'))}</option>`;
            if (select) { select.innerHTML = naoCarregou; select.dataset.carregando = '1'; }
            // Esta escrita é a ÚLTIMA no seletor de estados (`cargaDeEstados`): a
            // carga de estados que ainda vinha não a sobrescreve.
            cargaDeEstados++;
            if (estado) { estado.innerHTML = naoCarregou; estado.dataset.carregando = '1'; }
            return;
        }
        if (select) delete select.dataset.carregando;
        populateCountrySelect();
        await loadStatesIntoSelect(API.getCountry());
    } finally {
        // O "Minha área" marcado desabilita os três de propósito (regra de
        // cima) — o marcado NA TELA, como faz o ouvinte dele: a pessoa pode tê-lo
        // marcado com a lista chegando, e a troca de região que não carregou
        // devolve o seletor por aqui. Fora isso, devolve o seletor ao editor
        // mesmo se a rede falhou — se ele ainda for desta carga: a troca de
        // região que começou com os estados daqui chegando é dona dele, e o
        // destravava no meio da carga dela.
        if (select && minha === cargaDePaises) select.disabled = !!document.getElementById('filterMyArea').checked;
    }
}

function applyFiltersFromModal() {
    const $ = id => document.getElementById(id);

    // O botão ESPERA o que o modal ainda está buscando (ver
    // `aplicarEsperaDosFiltros`); isto é o cinto pra quem chegar aqui sem
    // passar por ele.
    if (esperaDosFiltros.regiao || esperaDosFiltros.gps) return;

    // Valida ANTES de mutar qualquer estado: 0 tipos = sem filtro = todos os tipos
    // (inclusive REQUEST gated). Bloqueia o Aplicar com aviso.
    const selectedTypes = Array.from(document.querySelectorAll('.filter-type:checked')).map(cb => cb.value);
    if (selectedTypes.length === 0) {
        showToast(t('toast.selectAtLeastOneType'), 'error');
        return;
    }

    // A foto dos filtros de BUSCA antes de qualquer mutação: é ela que decide,
    // no fim, se dá pra reordenar no aparelho ou se é preciso ir ao Waze.
    const buscaAntes = assinaturaDeBusca();

    // Preferências (undo/dev/idioma) NÃO passam por aqui — aplicam na hora,
    // via change listeners na aba Preferências (ver setupModalListeners).
    // Este handler é só da aba Filtros.
    AppState.filters.unreadOnly = $('filterUnreadOnly').checked;
    AppState.filters.types = selectedTypes;
    // Backstop: se REQUEST entrou em selectedTypes com dev mode desligado
    // (DOM editado à mão, estado velho), sai do filtro aqui.
    enforceDevGatedFilters();
    // Segurança: se o gate esvaziou os tipos (edge: só REQUEST + dev desligado),
    // volta ao default em vez de virar "todos os tipos".
    if (AppState.filters.types.length === 0) AppState.filters.types = TYPES_PADRAO.slice();
    AppState.filters.residential = $('filterResidential').value;
    // O LUGAR que vai valer, lido ANTES de gravar qualquer coisa: a região do
    // seletor e o país dele (o país ainda carregando não é escolha).
    const paisNaTela = !$('filterCountry').dataset.carregando && $('filterCountry').value;
    const lugarMudou = $('filterRegion').value !== API.getRegion()
        || (!!paisNaTela && String(paisNaTela) !== String(API.getCountry()));
    // Seletor ainda CARREGANDO não é escolha: gravar o "Todos"/vazio dele
    // apagava o estado da pessoa (e o país voltava pro padrão do servidor).
    if (!$('filterState').dataset.carregando) AppState.filters.stateId = $('filterState').value;
    // ...mas o estado guardado é do lugar de ANTES: trocado o país (ou a
    // região) com os estados do novo sem carregar, a busca saía com o país
    // novo e o estado do velho — MEDIDO: `countryId 73` com `stateId 2`, a
    // Bahia na França (auditoria de 2026-09-29, V10).
    else if (lugarMudou) AppState.filters.stateId = '';
    // A área gerenciada também é do lugar: a que o seletor ainda mostra do país
    // de antes não vai junto pro novo (F7, ver `aoMudarPaisNaTela`). Uma que a
    // pessoa escolheu DEPOIS de trocar o país, vai.
    const areaAplicada = AppState.filters.managedAreaId;
    AppState.filters.managedAreaId = $('filterManagedArea').value;
    if (lugarMudou && AppState.filters.managedAreaId === areaAplicada) AppState.filters.managedAreaId = '';
    AppState.filters.myArea = $('filterMyArea').checked;
    // A decisão do lugar que ficou PENDENTE (`decisaoSemResposta`) é sobre o
    // lugar de antes, e a pessoa escolheu outro: ela sai. Voltar àquele lugar à
    // mão também é escolha dela — com a pendência de pé, a pergunta repetida a
    // levava de volta ao país do perfil, com "Mostrando a fila de…", logo depois
    // de ela trocar em Filtros (auditoria da rodada 13, R13-6-05).
    if (lugarMudou && decisaoDoLugarDe && decisaoDoLugarDe.semResposta) decisaoDoLugarDe.semResposta = null;
    if (!$('filterCountry').dataset.carregando && $('filterCountry').value) API.setCountry($('filterCountry').value);
    // Troca de região: os países e estados em memória eram da região anterior. A
    // lista da região nova é a que a troca no modal acabou de trazer (guardada
    // por região, R9-6-01) — zerada, a reabertura dos Filtros a pedia de novo.
    const newRegion = $('filterRegion').value;
    if (newRegion !== API.getRegion()) {
        AppState.countries = listasDePaisesGuardadas.get(newRegion) || [];
        AppState.statesByCountry = {};
    }
    API.setRegion(newRegion);
    const catVal = $('filterCategory') ? $('filterCategory').value : '';
    AppState.filters.categories = catVal ? [catVal] : [];
    // A posição que o "📍 Perto de mim" pediu NESTE modal passa a valer AGORA, e
    // só agora (F5, ver `posicaoDoModal`). Sem pedido novo no modal, fica a da
    // ordem já aplicada.
    const ordemNaTela = $('filterSort') && $('filterSort').value;
    if (ordemNaTela === 'gps' && posicaoDoModal) posicaoGps = posicaoDoModal;
    AppState.filters.sortOrder = ordemValida(ordemNaTela);
    saveFilters();
    closeModal('filtersModal');
    // A sala É a fila: mudou país ou estado, a companhia é outra.
    window.Presenca?.sincronizar?.();

    // Trocar SÓ a ordem não é motivo pra ir ao Waze: ordenar é 100% no
    // aparelho (`sortQueue` é client-side, e o comentário dele já dizia isso).
    // Antes, qualquer Aplicar caía em `resetQueue` + `startFetching`, e isso
    // custava duas coisas: uma requisição e ~1–2 MB de resposta contra o free
    // tier, e os pedidos PULADOS voltavam — o skip não os marca no Waze, então
    // a fila refeita os traz de novo. Quem só queria outra ordem via o app
    // travar, recarregar e devolver o que ele tinha empurrado pra frente.
    if (assinaturaDeBusca() === buscaAntes && AppState.queue.length) {
        aplicarSoAOrdem();
        return;
    }
    // Com o treino aberto, o aviso do país que espera o "Sair" dele: sai com a
    // fila nova, se ela ainda é do país dele (R10-7-02).
    const avisoDoTreino = Treino.avisoDoPaisAnotado();
    resetQueue();
    startFetching();
    avisarPaisDoTreinoEncerrado(avisoDoTreino);
}

// A ordem nova, sem pedido novo ao Waze. Com o treino aberto, a fila da tela é
// a de EXEMPLOS (na ordem de variedade dele) e a real está guardada: reordenar
// aqui embaralhava os exemplos e deixava a fila real voltar, no "Sair", na
// ordem velha com o filtro dizendo a nova (junção do lote 11, medido com
// "Perto de casa": exemplos v1,v2,v3,v4 → v3,v4,v2,v1, e a real voltando
// u1,u2,u3,u4 em vez de u3,u4,u2,u1). O treino anota, e o `sair()` aplica a
// ordem na fila real, como o `reordenarFilaNaTela` faria — o mesmo caminho do
// perfil que chega no treino (`anotarPerfil`).
function aplicarSoAOrdem() {
    if (typeof Treino !== 'undefined' && Treino.ativo === true) { Treino.anotarOrdem(); return; }
    reordenarFilaNaTela();
}

// O que decide se é preciso RE-BUSCAR. Tudo de `filters` MENOS a ordem, mais
// região e país — e por exclusão de propósito: filtro novo entra aqui sozinho,
// enquanto uma lista de inclusão silenciaria a re-busca no dia em que alguém
// esquecesse de somar o campo dele. As chaves são ordenadas porque a ordem de
// inserção do objeto não é contrato.
// `semOrdem`: só O QUE se pede, sem a ordem em que vem. É a que diz de que busca
// é a fila guardada do offline (ver `lugarAgora`) — trocar só a ordem não faz
// dela a fila de outra busca.
function assinaturaDeBusca(semOrdem) {
    const { sortOrder, ...doServidor } = AppState.filters;
    const chaves = Object.keys(doServidor).sort();
    // Lista é CONJUNTO (os tipos, as categorias) e vai ordenada, e o país vai
    // como texto: a mesma escolha LIDA do armazenamento volta na ordem do
    // `sanearTiposSalvos`, e a assinatura da fila guardada tem que sobreviver a
    // fechar e reabrir o app.
    const valor = (v) => (Array.isArray(v) ? v.map(String).sort() : v);
    const doPedido = [chaves.map((k) => [k, valor(doServidor[k])]), API.getRegion(), String(API.getCountry())];
    // A ordem entra só pelo que ela muda NO PEDIDO ao Waze (`ordemDoWaze`):
    // "Mais recentes" ↔ "Mais antigos" refaz a fila, com o outro `orderBy`; a
    // de distância pede o mesmo que o padrão e só reordena (e traz o resto: ver
    // `reordenarFilaNaTela`).
    return JSON.stringify(semOrdem ? doPedido : [...doPedido, ordemDoWaze()]);
}

// Reordena e mostra o novo topo. O card na tela TROCA, e isso é o certo: a
// pessoa pediu outra ordem, então o primeiro da fila é outro. O que não pode é
// reordenar por baixo do card e deixar `currentPlace` e `queue[0]` diferentes —
// é o mesmo cuidado do `fetchNextPage`, e é ele que mantém o aquecimento
// mirando no card que vem (o `showCurrentPlace` reagenda em cima do novo topo).
function reordenarFilaNaTela() {
    // A ordem nova é o gesto mais recente: ela encerra o foco no autor, senão a
    // série dele seguiria na frente de uma ordem que a pessoa acabou de pedir.
    limparFocoAutor();
    sortQueue();
    AppState.currentPlace = AppState.queue[0];
    removeCurrentCardEl();
    showCurrentPlace();
    updatePendingCount();
    // A ordem escolhida só vale sobre a fila inteira: com páginas ainda no
    // Waze, elas vêm AGORA — a próxima busca só sairia com 3 cards na fila.
    if (ordemPrecisaDaFilaInteira()) buscarORestoDaFila();
}

// Traz as páginas que faltam (ver `ordemPrecisaDaFilaInteira`). O que chega
// entra na ordem JÁ, atrás do card da tela (`sortQueue` com
// `semTrocarOCardDaTela`): trocar o da tela seria trocar o card debaixo do dedo.
// É o `maybePrefetch` sem o limiar.
function buscarORestoDaFila() {
    if (Treino.ativo || !AppState.hasMore || AppState.fetching) return;
    fetchNextPage().then(() => {
        if (!AppState.currentPlace && AppState.queue.length > 0) showCurrentPlace();
    });
}

// Teclas que pertencem ao CURSOR quando o foco está num campo de texto.
const TECLAS_DE_CURSOR = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'];

function focoEmCampoDeTexto() {
    const el = document.activeElement;
    if (!el) return false;
    if (el.isContentEditable) return true;
    const tag = el.tagName;
    if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
    if (tag !== 'INPUT') return false;
    // Checkbox e botão não consomem seta; campo de texto (e range) consomem.
    return !['checkbox', 'radio', 'button', 'submit', 'reset', 'file'].includes(
        String(el.type || 'text').toLowerCase());
}

// As áreas do card que ROLAM pelo teclado: a lista de "Mudanças propostas" e o
// texto do reporte têm `tabindex="0"` justamente pra isso (e são as mesmas que
// o `handleDragStart` deixa de fora do arraste). Com o foco numa delas as
// teclas de cursor são DELA, como num campo de texto. Antes o ↓ rolava a lista
// e o ↑ PULAVA o card — auditoria de 2026-09-26, medido no francês com o diff
// mais longo da fixture —, e ← → rejeitavam/marcavam lido quem só estava lendo.
const AREAS_DO_CARD_QUE_ROLAM = '.card-changes-list, .card-flag-comment-text';

function focoEmAreaQueRola() {
    const el = document.activeElement;
    return !!(el && el.closest && el.closest(AREAS_DO_CARD_QUE_ROLAM));
}

// Ctrl, ⌘ ou Alt junto: a tecla é ATALHO do navegador, não do app. FONTE ÚNICA
// da regra, pra todo caminho de tecla que decide ou navega (`handleKeyDown` e a
// lista de abas dos Filtros). O Shift sozinho não conta: é com ele que se
// digita o "+" em vários teclados.
function atalhoDoNavegador(e) {
    return !!(e && (e.ctrlKey || e.metaKey || e.altKey));
}

// As teclas que, com Ctrl, ⌘ ou Alt, são do NAVEGADOR: as setas — Alt+← e ⌘+←
// são o Voltar, Alt+→ e ⌘+→ o Avançar, ⌘+↑ e ⌘+↓ o topo e o fim da página — e
// + − = (o zoom da página). O z fica de fora: Ctrl/⌘+Z é o Desfazer DO APP.
const TECLAS_DOS_ATALHOS_DO_NAVEGADOR = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', '+', '=', '-', '_'];

// O passo das setas na foto AMPLIADA (mais que 1×): os mesmos 80 px do mapa, e
// no mesmo sentido — a seta mostra o lado pra onde ela aponta (R5-3-06).
const SETAS_QUE_ANDAM = { ArrowLeft: [80, 0], ArrowRight: [-80, 0], ArrowUp: [0, 80], ArrowDown: [0, -80] };

function handleKeyDown(e) {
    // Ctrl, ⌘ ou Alt com uma seta ou com + − =: o atalho é do NAVEGADOR, e nada
    // aqui decide, anda ou amplia. É a PRIMEIRA instrução de propósito: nenhum
    // ramo abaixo vê o atalho. MEDIDO nos dois motores (2026-10-01): na tela do
    // card, Alt+← e ⌘+← — o Voltar — REJEITAVAM o pedido (Ctrl+← também), Alt+→ e
    // ⌘+→ — o Avançar — o marcavam como lido, e Alt+↑ e ⌘+↑ o pulavam; na foto
    // ampliada eles trocavam de foto, e com o ↓ a fechavam; no mapa, o moviam. E
    // as duas ampliações engoliam o zoom da página (auditoria de 2026-09-30,
    // R5-3-05). Sem `preventDefault` o navegador faz o dele, e com uma camada
    // aberta o Voltar a fecha (`CamadaVoltar`). O Shift sozinho segue do app, e o
    // z fica de fora: Ctrl/⌘+Z é o Desfazer do app.
    if (atalhoDoNavegador(e) && TECLAS_DOS_ATALHOS_DO_NAVEGADOR.includes(e.key)) return;

    // Foco num campo de texto: as setas são do CURSOR, não do app.
    //
    // Relatado pelo owner renomeando um local: usar ← → pra corrigir uma letra
    // TROCAVA A FOTO, e o `preventDefault()` do lightbox ainda matava o
    // movimento do cursor — as duas coisas erradas de uma vez.
    //
    // A guarda já existia, mas lá embaixo, DEPOIS do bloco do lightbox — que
    // retorna antes de chegar nela. Ela nasceu pro card e o lightbox foi
    // acrescentado por cima; o buraco é a ordem, não a falta.
    //
    // Só as teclas de cursor: Esc e Tab seguem passando, porque têm significado
    // de CAMADA (fechar, navegar) e o campo do nome já trata o Esc dele.
    if (focoEmCampoDeTexto() && TECLAS_DE_CURSOR.includes(e.key)) return;

    // O mapa ampliado é a camada MAIS alta quando aberto: o Esc fecha ele
    // antes de qualquer outra coisa, como o lightbox de foto faz.
    //
    // No mapa as QUATRO setas andam. O ↓ fechava, copiado da foto (onde ele
    // espelha o arraste pra baixo que fecha) — e no mapa o arraste pra baixo
    // ANDA, então pelo teclado não se chegava ao sul do pedido (auditoria de
    // 2026-09-26). Fechar é o Esc, e o ✕.
    if (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()) {
        if (e.key === 'Escape') { e.preventDefault(); MapaLightbox.close(); }
        else if (e.key === '+' || e.key === '=') { e.preventDefault(); MapaLightbox.zoom(1); }
        else if (e.key === '-' || e.key === '_') { e.preventDefault(); MapaLightbox.zoom(-1); }
        else if (e.key === 'ArrowLeft') { e.preventDefault(); MapaLightbox.arrastar(80, 0); }
        else if (e.key === 'ArrowRight') { e.preventDefault(); MapaLightbox.arrastar(-80, 0); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); MapaLightbox.arrastar(0, 80); }
        else if (e.key === 'ArrowDown') { e.preventDefault(); MapaLightbox.arrastar(0, -80); }
        // z desfaz a escrita da FOTO cuja janela ainda corre (excluir, aprovar,
        // renomear e fechar a foto pra ver o mapa é o caminho natural): o banner
        // aparece por cima do mapa também, e aqui a tecla não chegava a ele — na
        // foto chegava (auditoria de 2026-09-29, L29). O mesmo caminho da foto.
        else if ((e.key === 'z' || e.key === 'Z') && !focoEmCampoDeTexto()) {
            if (desfazerPeloTeclado()) e.preventDefault();
        }
        // As camadas são `aria-modal`: o Tab não pode sair delas pro card de
        // trás (Shift+Tab caía no ✓ — ação escondida atrás da foto). E o
        // Desfazer, desenhado por cima desta camada, entra na volta — como na
        // foto (L29): preso no mapa, o Tab nunca chegava nele.
        else if (e.key === 'Tab') trapTabInModal(e, document.getElementById('mapaLightbox'), document.getElementById('undoContainer'));
        return;
    }
    if (Lightbox.isOpen()) {
        // Esc e ↓ são um passo pra trás: editando o nome (com o foco no ✓ ou no
        // ✕ da edição — no campo o Esc já é dele), saem só da edição.
        if (e.key === 'Escape') { e.preventDefault(); recuarNaFoto(); }
        // AMPLIADA (mais que 1×), as quatro setas ANDAM pela foto, como no mapa:
        // o + do teclado mostrava só o miolo, e a seta trocava de foto e desfazia
        // o zoom — a placa da fachada no canto ficava inalcançável pra quem usa o
        // teclado (auditoria de 2026-09-30, R5-3-06). Em 1×, a de sempre — e um
        // fio de zoom invisível é 1× (`ampliada`, R8-3-01).
        else if (Lightbox.ampliada() && Object.prototype.hasOwnProperty.call(SETAS_QUE_ANDAM, e.key)) {
            e.preventDefault();
            Lightbox.panBy(...SETAS_QUE_ANDAM[e.key]);
        }
        else if (e.key === 'ArrowLeft') { e.preventDefault(); Lightbox.prev(); }
        else if (e.key === 'ArrowRight') { e.preventDefault(); Lightbox.next(); }
        // ↓ fecha, espelhando o arraste pra baixo do toque. Relato do owner:
        // aprendeu o gesto no celular, sentou no laptop e a mão foi pro ↓ —
        // o modelo mental funcionando e o app não correspondendo.
        //
        // Só BAIXO, porque é só o que o toque faz (`dy > 80`); inventar ↑ aqui
        // criaria um gesto que o celular não tem. E é caminho ADICIONAL: o Esc
        // continua sendo o principal, que é a convenção de desktop — por isso
        // a dica não muda de texto (decisão do owner: um texto só, não um
        // catatau por plataforma).
        else if (e.key === 'ArrowDown') { e.preventDefault(); recuarNaFoto(); }
        // + e − dão zoom, como no mapa ampliado: aqui eles não faziam nada
        // (auditoria de 2026-09-29, L33). Nunca com o campo do nome focado —
        // ali "+" e "-" são LETRAS do nome ("Posto 24-horas").
        else if ((e.key === '+' || e.key === '=') && !focoEmCampoDeTexto()) { e.preventDefault(); Lightbox.zoomPeloTeclado(1); }
        else if ((e.key === '-' || e.key === '_') && !focoEmCampoDeTexto()) { e.preventDefault(); Lightbox.zoomPeloTeclado(-1); }
        // z desfaz a exclusão, a aprovação ou a renomeação que acabou de sair
        // daqui — o banner delas mora FORA do lightbox, e a tecla não chegava a
        // ele (auditoria de 2026-09-26). Nunca com o campo do nome focado: ali
        // o z é uma LETRA do nome.
        else if ((e.key === 'z' || e.key === 'Z') && !focoEmCampoDeTexto()) {
            if (desfazerPeloTeclado()) e.preventDefault();
        }
        // O Desfazer entra na volta do Tab: ele aparece POR CIMA do lightbox
        // (o `#notifyStack` é z-70), e o Tab preso na camada o deixava visível
        // e inalcançável pra quem opera pelo teclado ou leitor de tela.
        else if (e.key === 'Tab') trapTabInModal(e, document.getElementById('imageLightbox'), document.getElementById('undoContainer'));
        return;
    }

    // Com modal aberto: Esc fecha, e as setas NÃO disparam swipe no card
    // atrás do diálogo (antes disparavam — ação destrutiva invisível). O Esc é
    // TECLADO, e a limpeza do modal sabe disso (o fim do treino leva o foco ao
    // card que volta, R8-7-07).
    const openedModal = topOpenModal();
    if (openedModal) {
        if (e.key === 'Escape') {
            e.preventDefault();
            closeModal(openedModal.id, { peloTeclado: true });
        } else if (e.key === 'Tab') {
            trapTabInModal(e, openedModal);
        }
        return;
    }

    if (document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName)) return;

    // Foco numa área do card que rola: as teclas de cursor são DELA (ver
    // `focoEmAreaQueRola`). Sem `preventDefault` — ↑ ↓ PageUp PageDown Home
    // End rolam a lista pelo navegador —, e ← → ali não decidem nada. Antes da
    // trava do Desfazer de propósito: ler a lista durante a janela é legítimo,
    // e a trava daria `preventDefault` no ↑ e travaria a rolagem.
    if (focoEmAreaQueRola() && TECLAS_DE_CURSOR.includes(e.key)) return;

    // Desfazer via teclado (power-user opera por teclas): z (ou Ctrl/Cmd+Z) —
    // o do card E o das ações de foto, que seguem com a janela aberta depois
    // de o lightbox fechar (ver `desfazerPeloTeclado`).
    if ((e.key === 'z' || e.key === 'Z') && desfazerPeloTeclado()) {
        e.preventDefault();
        return;
    }

    if (!AppState.currentPlace) return;
    // As setas também respeitam a trava — senão o teclado seria um atalho pra
    // furar a janela do Desfazer que o dedo respeita. E respondem com o porquê
    // quando a trava não tem banner na tela (ver `avisarTravaAoTocar`).
    if (acoesTravadas() && ['ArrowLeft', 'ArrowRight', 'ArrowUp'].includes(e.key)) {
        e.preventDefault();
        avisarTravaAoTocar();
        return;
    }

    // A ação vale pro pedido do card que SAIU, não pro da frente 350 ms depois
    // (ver `agirNoPedidoDoGesto`).
    if (e.key === 'ArrowLeft') {
        e.preventDefault();
        if (window.triggerSwipe) window.triggerSwipe('left', (card) => agirNoPedidoDoGesto(pedidoDoCard(card), handleReject));
        else handleReject();
    } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        if (window.triggerSwipe) window.triggerSwipe('right', (card) => agirNoPedidoDoGesto(pedidoDoCard(card), handleMarkAsRead));
        else handleMarkAsRead();
    } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (window.triggerSwipe) window.triggerSwipe('up', (card) => agirNoPedidoDoGesto(pedidoDoCard(card), handleSkip));
        else handleSkip();
    }
}

// Confina o Tab dentro do modal aberto — sem isso, Tab saía do diálogo e Enter
// podia disparar uma ação destrutiva no card invisível atrás (M3/HIG).
//
// `emprestadas`: o que mora FORA da camada mas é desenhado POR CIMA dela e faz
// parte da volta — hoje, o Desfazer das ações de foto, que fica no
// `#notifyStack` (z-70) sobre o lightbox (z-65). Sem entrar na volta ele era
// visível e inalcançável pelo Tab (auditoria de 2026-09-26).
function trapTabInModal(e, modal, ...emprestadas) {
    if (!modal) return;
    const sel = 'a[href], button:not([disabled]), textarea:not([disabled]), input:not([type=hidden]):not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';
    const zonas = [modal, ...emprestadas].filter(Boolean);
    const porZona = zonas.map((z) => Array.from(z.querySelectorAll(sel)).filter(el => el.offsetParent !== null));
    const list = porZona.flat();
    if (list.length === 0) return;
    const first = list[0];
    const last = list[list.length - 1];
    // Foco FORA da camada (a camada abriu sem puxá-lo, ou ele ficou no corpo):
    // o Tab seguinte ia pro próximo da página — o card de trás. Entra pela
    // ponta certa, em vez de só dar a volta quando já está dentro.
    if (!zonas.some((z) => z.contains(document.activeElement))) {
        e.preventDefault();
        (e.shiftKey ? last : first).focus();
        return;
    }
    // Na DIVISA entre duas zonas o próximo é o da outra zona, e quem diz é a
    // lista — o próximo do DOM pode ser qualquer coisa entre elas (o botão do
    // modo dev, um banner do topo). No meio de uma zona o Tab segue do
    // navegador, como sempre foi.
    const i = list.indexOf(document.activeElement);
    const pontas = porZona.filter((l) => l.length).map((l) => [l[0], l[l.length - 1]]);
    if (i > 0 && e.shiftKey && pontas.some(([a]) => a === list[i])) {
        e.preventDefault();
        list[i - 1].focus();
        return;
    }
    if (i >= 0 && i < list.length - 1 && !e.shiftKey && pontas.some(([, b]) => b === list[i])) {
        e.preventDefault();
        list[i + 1].focus();
        return;
    }
    if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
    }
}

function showAuthScreen() {
    // A aposta do script inline do <head> era otimista (havia token no
    // aparelho). Se chegamos aqui, ela estava errada — token vencido, logout,
    // pareamento. Tirar a marca devolve o comando às classes `hidden`, que a
    // partir do JS são a única fonte de verdade.
    document.documentElement.classList.remove('tem-sessao');
    mostrarControlesDeSessao(false);
    document.getElementById('authScreen').classList.remove('hidden');
    document.getElementById('appScreen').classList.add('hidden');
    document.getElementById('filtersBtn').classList.add('hidden');
    document.getElementById('refreshBtn').classList.add('hidden');
    document.getElementById('userProfileBadge').classList.add('hidden');
    // Escondido não é apagado: a foto, o nome e o nível de quem estava aqui
    // seguiam no cabeçalho — e a próxima conta aparecia com a FOTO da anterior
    // até a dela chegar (ver a função).
    limparCabecalhoDoPerfil();
    // E o anúncio do último card ao leitor de tela: "Novo pedido: <nome do
    // local>, <tipo>" ficava na região viva depois do "Sair" — dado de terceiro
    // no DOM da tela de entrada, que nenhum código limpava (auditoria de
    // 2026-10-01, R5-5-X).
    const anuncio = document.getElementById('cardLiveRegion');
    if (anuncio) anuncio.textContent = '';
    // E a lista de autores rejeitados (ver a função): a folha do autor pode tê-la
    // redesenhado no painel fechado (R6-1-05) — e, com ela, o painel inteiro do
    // Histórico, com a patente e os totais de quem estava (R8-7-06). E as áreas
    // gerenciadas no seletor dos Filtros (R11-1-05).
    esvaziarPainelDoHistorico();
    esvaziarSeletorDeAreas();
    const brandTitle = document.getElementById('brandTitle');
    if (brandTitle) brandTitle.classList.remove('sr-only'); // volta visível ao deslogar
    AppState.authenticated = false;
    AppState.profile = null;
    // Deslogado não tem crachá, então não tem sala. Fecha o socket na hora em
    // vez de deixar a conexão viva com uma sessão que já não vale.
    window.Presenca?.desligar?.();
}

// Controles da Ajuda que só existem com sessão (Praticar, Conectar outro
// aparelho, Sair). A Ajuda abre também na tela de entrada, e ali eles eram
// becos sem saída — o "Praticar" chegava a ligar um treino invisível.
function mostrarControlesDeSessao(com) {
    document.querySelectorAll('[data-so-com-sessao]').forEach((el) => el.classList.toggle('hidden', !com));
}

function showMainScreen() {
    mostrarControlesDeSessao(true);
    document.getElementById('authScreen').classList.add('hidden');
    document.getElementById('appScreen').classList.remove('hidden');
    document.getElementById('filtersBtn').classList.remove('hidden');
    document.getElementById('refreshBtn').classList.remove('hidden');
    AppState.authenticated = true;   // o selo lê isto; o resto da função repete abaixo
    atualizarSeloDeConquista();
    AppState.authenticated = true;
    quedaAnunciada = false;   // a sessão voltou: a queda dita já passou (ver `avisarTravaAoTocar`)
    // Com a sessão de volta (a renovação pela extensão, com o card na tela), o
    // card destrava: sem sessão ele fica travado (ver `acoesTravadas`).
    aplicarTravaDeAcao();
    updateDevBadge();
    // A sala só faz sentido logado: é o crachá do WME que abre a porta.
    window.Presenca?.sincronizar?.();
}

// O "Fazer upload do cookies.txt" foi tocado pelo TECLADO? O login que der certo
// leva o foco ao ✕ do primeiro card, como o colar e o código (R7-1-04): pelo
// arquivo, o foco ficava no botão que o `setAuthLoading` desabilita e a tela de
// entrada esconde, e caía no <body> — o Tab seguinte ia à seta do carrossel
// (MEDIDO nos dois motores; auditoria de 2026-10-03, R8-1-01). Lido no toque que
// abre o seletor (o `change` vem do sistema, sem o gesto) e gasto no `change`.
let arquivoPeloTeclado = false;

async function handleFileUpload(e) {
    const peloTeclado = arquivoPeloTeclado;
    arquivoPeloTeclado = false;
    const file = e.target.files[0];
    if (!file) { e.target.value = ''; return; }
    try {
        const content = await file.text();
        await authenticateWithCookies(content, { peloTeclado });
    } catch (error) {
        showToast(t('toast.fileReadError'), 'error');
    } finally {
        e.target.value = ''; // permite re-selecionar o mesmo arquivo (dispara change)
    }
}

async function handlePasteConfirm(ev) {
    const content = document.getElementById('cookiesTextarea').value.trim();
    if (!content) {
        showToast(t('toast.pasteEmpty'), 'error');
        return;
    }
    // Pelo TECLADO (o Enter no "Confirmar"): o login que der certo leva o foco
    // ao ✕ do primeiro card (ver `authenticateWithCookies`). Lido ANTES de
    // fechar: o fechamento leva o foco pro "Colar cookies".
    const peloTeclado = veioDoTeclado(ev);
    closeModal('pasteModal');   // limpa o campo (ver `LIMPEZA_AO_FECHAR`); o conteúdo já foi lido
    await authenticateWithCookies(content, { peloTeclado });
}

let authInFlight = false;
// `peloTeclado`: quem entrou pelo teclado (o "Confirmar" do colar). A tela de
// entrada some com o foco nela, e o foco caía no <body>: o Tab seguinte ia à
// seta do carrossel do card (MEDIDO nos dois motores, auditoria de 2026-10-02,
// R7-1-04). É a regra do C10 pra todo controle que some com o foco: ele fica
// PROMETIDO ao ✕ do primeiro card e pousa quando o card chegar
// (`aplicarFocoDoTeclado`, com as regras dele). O mouse e o dedo não movem nada.
async function authenticateWithCookies(cookies, { peloTeclado = false } = {}) {
    if (authInFlight) return;            // evita duplo-envio (criaria 2 sessões)
    authInFlight = true;
    setAuthLoading(true);
    // O aviso de PROGRESSO sai com o resultado: com o servidor respondendo
    // rápido, "Validando cookies…" seguia na tela por até ~3,7 s depois dele —
    // ao lado do "Autenticado com sucesso!", do erro e por cima do "Acesso
    // restrito" (auditoria de 2026-10-02, R7-1-08). É a regra do aviso da trava:
    // aviso de espera que já acabou é o app mentindo.
    const validando = showToast(t('toast.validatingCookies'), 'info');
    try {
        // UM login por vez nesta aba. Com o resgate de um código no ar (o link
        // `/#pair=`, que mostra a tela de entrada enquanto resgata, ou o "Entrar
        // com um código" fechado no meio), os cookies colados e CONFIRMADOS
        // faziam um segundo login: os dois davam certo, o segundo trocava o
        // primeiro, e o "Sair" apagava só o último — o outro ficava vivo no
        // servidor, sem dono, por até 21 dias (auditoria da rodada 12, R12-1-01,
        // MEDIDO). Este espera o desfecho daquele: entrou, a pessoa já está no
        // app, e o que ela colou não vai a lugar nenhum — o que a regra do
        // R11-1-04 já faz com o "Colar" ainda aberto; não entrou, segue. O
        // caminho inverso não existe: o "Entrar com um código" trava durante a
        // conferência dos cookies (`setAuthLoading`), e o link só é resgatado na
        // abertura.
        if (resgateNoAr) {
            const outroEntrou = await resgateNoAr;
            if (outroEntrou || API.temSessaoNaMemoria() || AppState.authenticated) {
                // Pelo teclado, o foco segue a regra de todo login (R7-1-04): o
                // botão que ele tinha travou, e a tela de entrada já saiu.
                if (peloTeclado) focoDoTeclado = BOTAO_DA_ACAO.left;
                return;
            }
        }
        const result = await API.testCookies(cookies);
        if (result.success) {
            guardarPrazoDaSessao(result);
            aoEntrarNestaPagina();
            // O que a tela de entrada tinha aberto sai COM a limpeza, e o foco que
            // estava nela vai ao ✕ do primeiro card — como no resgate do código e
            // na entrada pela extensão (R10-1-05). O "Entrar com um código" aberto
            // durante a espera, com o código digitado, ficava POR CIMA do app, e o
            // "Entrar" ali fazia um segundo login, com a primeira sessão órfã no
            // servidor (auditoria da rodada 11, R11-1-04, MEDIDO). Lido ANTES de
            // fechar.
            const focoNaEntrada = focoNaTelaDeEntrada();
            fecharModaisDaEntrada({ focoComDestino: peloTeclado || focoNaEntrada });
            showMainScreen();
            resetQueue();
            // DE QUEM é a sessão, NA HORA — o portão já leu o perfil (ver o
            // `testar-cookies`). Antes, a conta só se sabia com o `/perfil`: o
            // que a pessoa fazia antes dele chegar (placar, Histórico, autores)
            // era apagado junto com os dados da conta anterior quando a troca
            // era detectada (auditoria da costura, 2026-09-26, K8). DEPOIS do
            // `resetQueue`: a fila já é desta sessão, e a troca não a refaz.
            conhecerContaDoLogin(result.conta);
            AppState._profilePromise = loadProfileAndAuxData();
            // O foco de quem entrou pelo teclado (ver acima, R7-1-04), ou que
            // estava na tela de entrada quando ela sumiu (R11-1-04).
            if (peloTeclado || focoNaEntrada) focoDoTeclado = BOTAO_DA_ACAO.left;
            startFetching();
            esvaziarFilaDeSaida();   // o que ficou esperando a sessão sai agora
            showToast(t('toast.authSuccess'), 'success');
        } else if (result.errorCategory === 'access_denied') {
            showAccessDenied(result);
        } else {
            showToast(msgDoServidor(result, t('toast.invalidCookies')), 'error');
        }
    } catch (error) {
        showToast(t('toast.authError'), 'error');
    } finally {
        authInFlight = false;
        setAuthLoading(false);
        try { validando.dispensar(); } catch (e) { /* o aviso já saiu */ }
    }
}

// Desabilita os botões de login enquanto valida (feedback + trava duplo-envio).
//
// O botão com o FOCO que vira `disabled` o perde (MEDIDO nos dois motores), e o
// fechamento do "Colar" põe o foco justamente no "Colar cookies": com os
// cookies recusados a tela de entrada fica, e o foco ficava no <body> — quem usa
// teclado ou leitor de tela recomeçava do topo (auditoria de 2026-10-02,
// R7-1-04). O foco é GUARDADO ao desabilitar e volta ao mesmo botão quando ele
// volta a valer, se ainda estiver perdido: não é foco pulando pela tela, ele
// volta pra onde estava (como o `guardarFocoDaTrava` do card). Com o login que
// deu certo a tela de entrada some, e o botão escondido não recebe nada.
//
// O "Entrar com um código" trava junto: era o único caminho da tela de entrada
// que seguia aberto, e o diálogo dele aberto durante a validação ficava POR CIMA
// do app quando o login dava certo — o "Entrar" ali fazia um segundo login
// (auditoria da rodada 11, R11-1-04, MEDIDO).
let focoNoBotaoDeEntrada = null;
function setAuthLoading(loading) {
    const ativo = document.activeElement;
    ['uploadBtn', 'pasteBtn', 'pairEnterBtn'].forEach(id => {
        const b = document.getElementById(id);
        if (b) {
            if (loading && b === ativo) focoNoBotaoDeEntrada = b;
            b.disabled = loading;
            b.classList.toggle('opacity-60', loading);
            b.classList.toggle('cursor-wait', loading);
        }
    });
    if (loading) return;
    const b = focoNoBotaoDeEntrada;
    focoNoBotaoDeEntrada = null;
    if (b && focoPerdido() && focavelNaTela(b)) b.focus();
}

function showAccessDenied(result) {
    const modal = document.getElementById('accessDeniedModal');
    const msg = document.getElementById('accessDeniedMessage');
    const profileBox = document.getElementById('accessDeniedProfile');
    msg.textContent = msgDoServidor(result, t('accessDenied.defaultMsg'));
    if (result.profile && result.profile.userName) {
        const p = result.profile;
        const displayRank = (p.rank !== null && p.rank !== undefined) ? ('L' + (p.rank + 1)) : '';
        const tags = [];
        if (displayRank) tags.push(displayRank);
        tags.push(p.isStaff ? t('profile.tag.staff') : (p.isAreaManager ? t('profile.tag.am') : t('profile.tag.notAm')));
        profileBox.innerHTML = `<strong>${escapeHtml(p.userName)}</strong> <span class="text-slate-500 dark:text-slate-400">· ${escapeHtml(tags.join(' · '))}</span>`;
        profileBox.classList.remove('hidden');
    } else {
        profileBox.classList.add('hidden');
    }
    openModal('accessDeniedModal');
}

async function loadProfileAndAuxData() {
    const epoca = epocaDaSessao;
    const pedidoAntes = perfilPedidoEm;
    const carga = ++cargasDoPerfil;
    perfilPedidoEm = Date.now();
    perfilFalhouPorRede = false;
    // O lugar em que o perfil e os países são PEDIDOS (ver `lugarDoPedidoDoPerfil`).
    const regiaoPedida = API.getRegion();
    lugarDoPedidoDoPerfil = { regiao: regiaoPedida, pais: API.getCountry() };
    // A lista de países é a MESMA ida que os Filtros abertos nesse meio
    // aproveitam (o atalho do ícone os abre já): ver `pedirListaDePaises`.
    const [profileRes, countriesRes] = await Promise.all([
        API.getProfile(),
        pedirListaDePaises(regiaoPedida)
    ]);
    // Saiu enquanto o perfil vinha: sem isto ele voltava ao AppState, ao
    // cabeçalho e ao portão gravado — de quem já tinha saído.
    if (epoca !== epocaDaSessao) return;
    // O perfil que não veio por REDE ou pelo SERVIDOR: a busca de "Minha área"
    // que o espera falhou por rede (ver `ultimaBuscaFalhouPorRede`, R12-4-02).
    perfilFalhouPorRede = !profileRes.success && profileRes.errorCategory === 'transient';
    // E SEM resposta nenhuma (o `_motivo` do `_post`): com "Minha área" a busca
    // espera este perfil e nem sai — é ela ficando sem resposta, o "lie-fi" que o
    // card de foto lê (`buscaSemResposta`, R5-4-4). Sem a marca, o card de foto da
    // fila guardada que entra assim ficava com "Sem Imagem" e ✕/✓ vivos. Apaga com
    // a primeira resposta que chegar, como sempre.
    if (perfilFalhouPorRede && typeof profileRes._motivo === 'string' && AppState.filters.myArea) buscaSemResposta = true;
    // O pedido que nem teve RESPOSTA (o `_motivo` do `_post`: a rede, o prazo)
    // não chegou ao servidor, e não conta no teto de um por minuto do
    // `refazerPerfilSeFaltar` — a regra do token e da lista da presença. Contava:
    // o app reaberto sem resposta da API, com a rede voltando em menos de um
    // minuto, não pedia o perfil nas provas de rede que vinham (as respostas do
    // esvaziamento da fila de saída), e sem ele faltavam o nome, os portões de
    // L6, a recusa automática, a presença — e o "invisível" que esperava o perfil
    // não saía, contra o "assim que o sinal volta" (auditoria da rodada 12,
    // R12-5-04, MEDIDO). Só se nenhuma carga começou depois desta.
    if ((!profileRes || typeof profileRes._motivo === 'string') && carga === cargasDoPerfil) perfilPedidoEm = pedidoAntes;
    // O portão reconferido pelo servidor: o nível ou a área mudou no Waze
    // depois do login (ver `handlePerfil`). A sessão já foi apagada lá. Não
    // passa pelo `handleUnauthorized`, porque não há o que confirmar (não é o
    // 401 ambíguo), nem pela extensão, que entraria pelo mesmo portão: a pessoa
    // vê o MESMO diálogo de quem é recusado no login, com o perfil dela.
    if (profileRes.errorCategory === 'access_denied') {
        if (AppState.authenticated) recusaDoPortao(profileRes);
        return;
    }
    // Os países ANTES do resto: o país de quem entra e o subtítulo da lista da
    // presença usam o nome deles (ver `completarPerfilChegado`). E antes do 401
    // logo abaixo: com o perfil barrado por um 401 passageiro (o blip do KV),
    // os países que chegaram BEM eram jogados fora, e a chegada do perfil pelo
    // alarme falso dizia o país sem o nome — e a lista da presença saía sem
    // subtítulo (auditoria da costura, 2026-09-26, K11).
    //
    // E só se a região ainda for a do pedido: pelo atalho do PWA, a pessoa
    // aplicava outra região nos Filtros antes de a lista chegar, e a da ROW
    // virava a lista de países da NA — o próximo "Aplicar" podia gravar o
    // Brasil na NA (auditoria de 2026-09-29, achado 10; é o V3 na abertura).
    if (countriesRes.success && API.getRegion() === regiaoPedida) {
        AppState.countries = countriesRes.countries;
    }
    // Se qualquer um dos dois detectar sessão expirada/revogada no Waze (401/403),
    // deslogar e mandar pra tela de auth. Sem isso o user fica preso vendo
    // "Erro ao buscar X (HTTP 403)" sem entender por quê.
    if (profileRes.errorCategory === 'unauthorized' || countriesRes.errorCategory === 'unauthorized') {
        handleUnauthorized();
        return;
    }
    // Os editáveis do perfil são do servidor em que ele foi PEDIDO (ver
    // `editaveisLidos`, R7-6-02).
    // E a caixa das áreas do mesmo `/Session`, que também é dele (R9-6-04), e as
    // áreas gerenciadas (R10-6-03).
    if (profileRes.success && profileRes.profile) {
        anotarEditaveis(profileRes.profile, regiaoPedida, profileRes.profile.editableCountryIDs, profileRes.profile.areas,
            profileRes.profile.managedAreas);
    }
    if (definirPerfil(profileRes)) await completarPerfilChegado(profileRes.profile, epoca);
}

// ── O PORTÃO FECHOU na reconferência ──────────────────────────────────────
// O `perfil` reconfere o nível e a área a cada abertura (e na sonda de um 401 —
// ver `handlePerfil` e `handleUnauthorized`): quem caiu abaixo do portão perde a
// sessão, que o servidor já apagou. Não passa pela extensão (ela entraria pelo
// mesmo portão), e a pessoa vê o MESMO "Acesso restrito" de quem é recusado no
// login, com o perfil dela.
//
// E a recusa é TERMINAL: a pessoa não entra de novo até mudar de nível ou de
// área — e o "Sair" só existe com sessão. A queda comum deixa o aparelho como
// está, pra a mesma pessoa voltar; aqui não há volta, e o Histórico, a lista de
// autores e a fila de saída (nome e id de quem mandou o pedido, dado de
// TERCEIRO) ficavam no aparelho sem caminho pra apagar, a não ser outra conta
// entrando (auditoria de 2026-10-02, R6-1-11). Então o que é da conta sai como
// o "Sair" tira — pela MESMA função, a mesma lista (`handleLogout`, com
// `recusado`). Só se a sessão desta aba era a do aparelho: senão o aparelho é
// de outra sessão (outra aba, talvez outra conta), e aqui cai só a memória,
// como na queda.
//
// A ordem: a limpeza, o diálogo, a tela de entrada. O diálogo ANTES da tela de
// entrada: o `showAuthScreen` fecha a conversa e a lista da presença
// (`Presenca.desligar`), e fechar um modal e abrir outro no mesmo quadro
// dessincroniza o voltar (gotcha #65). A limpeza antes dos dois: ela não abre
// nem fecha camada nenhuma (as camadas já fecharam no `fecharCamadasAbertas`).
function recusaDoPortao(res) {
    const doAparelho = sessaoDestaAbaEhAGuardada();
    derrubarSessao(res.errorKey, { depois: () => {
        if (doAparelho) handleLogout({ recusado: true });
        showAccessDenied(res);
        showAuthScreen();
    } });
}

// ── O PERFIL CHEGOU: fonte única ──────────────────────────────────────────
// O perfil chega por DOIS caminhos: a carga da abertura (acima) e a sonda do
// 401 que se revela alarme falso (`handleUnauthorized`). O segundo gravava o
// `AppState.profile` por conta própria, SEM o `aoConhecerConta` (auditoria de
// 2026-09-26): quem entrava num aparelho cuja sessão anterior tinha caído sem o
// "Sair", com o 1º perfil levando um 401 passageiro (o blip do KV), nunca tinha
// a troca de conta detectada — e a recusa automática da conta ANTERIOR agia no
// nome de quem entrou, sobre a fila dele. E com o perfil presente o
// `refazerPerfilSeFaltar` não rodava mais: nada corrigia depois.
//
// Por isso é UMA função, e ela é a ÚNICA que grava um perfil no `AppState`
// (`test/conta.test.mjs` reprova quem gravar por fora): a conta é conferida
// ANTES de tudo que depende dela. Resposta sem perfil não apaga o que se sabia.
function definirPerfil(res) {
    const perfil = res && res.success ? res.profile : null;
    if (!perfil || typeof perfil !== 'object') return false;
    // O perfil de uma aba cuja sessão NÃO é a do aparelho, de uma conta que não é
    // a dona dele: outra conta entrou noutra aba enquanto esta ainda não sabia a
    // sua (ver `aoEntrarOutraContaEmOutraAba`). Esta sai; pelo caminho de
    // sempre, ela tomaria o aparelho de volta — apagando o que é da outra — e a
    // outra aba é que sairia.
    if (!contaSegueNoAparelho(perfil.id)) {
        handleLogout({ porOutraAba: true, outraConta: true });
        return false;
    }
    AppState.profile = perfil;
    // ANTES do que depende do perfil: se a conta é outra, o que era da
    // anterior sai antes de a recusa automática e a presença rodarem.
    aoConhecerConta(perfil);
    guardarReferencias(res);
    guardarPerfilDoPortao(perfil);
    guardarPrazoDaSessao(res);
    renderProfileHeader();
    presencaWmeAoCarregarPerfil(res.visivelNoWme);
    // O "invisível" que a pessoa pediu antes de o perfil chegar (ver
    // `presencaWmeDesligar`): agora ele tem pra quem ir.
    presencaWmeRefazerDesligar();
    // Os Filtros abertos ANTES dele (o atalho do PWA, a rede lenta) mostravam
    // a área e a ordem sem o que só o perfil sabe (F2).
    redesenharFiltrosComOPerfil();
    // E a foto ampliada aberta antes dele: o "Aprovar", a lixeira e a pílula do
    // nome dependem do portão, que lê o perfil (R6-3-07).
    reavaliarFotoAbertaPeloPerfil();
    // A conta DESTA aba estava em dúvida (R6-1-04) e o perfil a resolveu: é a
    // mesma conta (sendo outra, a aba já saiu, acima). O card destrava AGORA, e
    // não no fim da carga do perfil: a trava lê a dúvida na hora
    // (`acoesTravadas`), então a seta e o arraste já decidiam, e só os botões
    // seguiam `disabled` — mudos ao toque — enquanto o `completarPerfilChegado`
    // terminava (o país de quem entra pode perguntar a outros servidores,
    // segundos). Botão morto com o gesto vivo é o gotcha #63 (MEDIDO no
    // navegador: 3 s depois de o perfil chegar, a seta mandava o ✕ com os três
    // botões travados; auditoria de 2026-10-07, R13-2-06). O fim da conferência
    // (`conferirContaDestaAba`) reaplica a trava de novo, sem mudar nada.
    if (AppState.contaEmDuvida === true && !contaDestaAbaEmDuvida()) {
        AppState.contaEmDuvida = false;
        aplicarTravaDeAcao();
    }
    // E o ponto do botão de Filtros, que também lê o portão: a conquista de L6
    // ganha e não vista só passa a contar quando a vitrine pode mostrá-la — e o
    // perfil de quem não pode a tira da conta (R13-7-02).
    atualizarSeloDeConquista();
    return true;
}

// O PERFIL chegou com a foto ampliada ABERTA — o `/Session` é a chamada mais
// lenta da abertura, e a renovação da sessão o zera até o novo chegar. O portão
// das três ações da foto (`podeAgirComoL6Aqui`) só era reavaliado ao abrir,
// trocar de foto ou a imagem carregar: o "Aprovar", a lixeira e a pílula do nome
// seguiam escondidos pra um L6+AM até fechar e abrir a foto de novo (R6-3-07,
// auditoria de 2026-10-01, MEDIDO). Fecha também o caminho oposto: o perfil de
// quem não pode tira a pílula e fecha a edição.
function reavaliarFotoAbertaPeloPerfil() {
    if (!Lightbox.isOpen()) return;
    mostrarNomeNoLightbox();
    atualizarAcoesDeFoto();
}

// O que DEPENDIA do perfil e pode ter rodado antes dele. Roda na carga da
// abertura e no alarme falso que traz o PRIMEIRO perfil da sessão: sem este
// segundo caminho, quem teve o 1º perfil barrado por um 401 passageiro ficava
// sem o país, sem a presença e sem a recusa automática até recarregar.
async function completarPerfilChegado(perfil, epoca) {
    // A recusa automática (é de L6+AM, e a fila costuma chegar primeiro) e a
    // ordem por casa/trabalho (as referências vêm com o perfil). Sem isto, os
    // dois só valiam na próxima busca.
    aplicarRecusaAutomatica();
    // A decisão do lugar DESTA conta, nesta sessão, começou (ver
    // `areaNoutroServidorSemDecisao`, R11-6-02). Logo no começo: nada antes dela
    // pode lançar e deixá-la sem marca (a recusa automática é assíncrona).
    const estaDecisao = { epoca, conta: String(perfil.id) };
    decisaoDoLugarDe = estaDecisao;
    // Com o TREINO aberto a fila na tela é a de EXEMPLOS, e a real está guardada
    // nele: a ordem e a recusa (que no treino sai na primeira linha) ficam
    // ANOTADAS, e o `Treino.sair()` as aplica na fila real quando ela voltar.
    // Ordenar aqui desfazia a ordem por variedade do treino, e a real voltava na
    // ordem de data, com os pedidos do autor marcado na tela (R7-2-04, MEDIDO no
    // navegador; auditoria de 2026-10-02).
    if (typeof Treino !== 'undefined' && Treino.ativo === true) Treino.anotarPerfil();
    else {
        // Com um card na tela, só o RESTO entra na ordem, e o card de fundo passa a
        // anunciar o próximo de verdade (ver o `sortQueue`, R6-2-06).
        sortQueue({ semTrocarOCardDaTela: true });
        if (AppState.currentPlace) aoMudarAFilaPorBaixo();
    }
    // "Minha área": a busca que esperava por este perfil é refeita (ver
    // `fetchNextPage`) — pela caixa da área ou, num perfil sem caixa, com o
    // filtro desligado e dito. ANTES do país: desligado, o "Minha área" deixa
    // de segurar a escolha do país de quem entra.
    //
    // Menos com a lista de editáveis DAQUI vazia (e quem não é staff): aí a área
    // está noutro servidor, e as `areas` do `/Session` são POR SERVIDOR (MEDIDO no
    // Waze real: 8 e 1 áreas na ROW, 0 na NA e na IL) — o perfil daqui não tem
    // caixa nenhuma, e desligar aqui dizia "Seu perfil do Waze não tem área de
    // edição" a quem tem, com "Mostrando a fila de United States" logo depois
    // (auditoria da rodada 9, R9-6-04). A decisão espera o perfil do servidor de
    // destino: a ida pra lá confere a caixa de lá (`irProPaisDoPerfil`), e sem
    // destino quem decide é a busca, pela caixa do servidor dela.
    const refazerFila = filaEsperaPerfil;
    const editaveisAqui = (Array.isArray(perfil.editableCountryIDs) ? perfil.editableCountryIDs : [])
        .map(Number).filter((n) => Number.isInteger(n) && n > 0);
    const areaNoutroServidor = !perfil.isStaff && editaveisAqui.length === 0;
    if (AppState.filters.myArea && !areaNoutroServidor && !caixaDaMinhaArea(perfil)) desligarMinhaAreaSemCaixa();
    // A área gerenciada salva que este perfil não tem sai do filtro, e a fila que
    // saiu com ela é refeita (ver a função).
    const refazerPelaArea = esquecerAreaForaDoPerfil(perfil);
    // A DECISÃO do lugar (e, com ela, da caixa de "Minha área") fica no ar daqui
    // até a fila ser refeita: pra quem só edita noutro servidor, é a pergunta ao
    // `/Session` de lá. Um ↻ ou um "Aplicar" nesse meio (também pelo atalho
    // "Filtros" do ícone) buscava JÁ, com o perfil daqui sem caixa: "Minha área"
    // era desligada com a frase que o R9-6-04 tirou, a tela dizia "Tudo limpo!" e
    // a fila virava a do país, sem o aviso (MEDIDO no navegador, auditoria da
    // rodada 10, R10-6-01). A busca de "Minha área" espera por ela
    // (`startFetching`), como espera o perfil; nenhuma busca nova sai por isso.
    // Promessa no `AppState`, como a do perfil (`_profilePromise`).
    let decidiu = null;
    const decisao = new Promise((ok) => { decidiu = ok; });
    AppState._caixaDaMinhaAreaNoAr = decisao;
    try {
        // O país de quem entra: só depois do perfil, e só quando o atual é um onde
        // a pessoa NÃO edita (ver `paisDoPerfil`).
        const semResposta = [];
        const destino = await paisDoPerfil(perfil, epoca, { semResposta });
        // Sem destino e SEM a resposta de um servidor onde a pessoa pode editar: a
        // decisão fica PENDENTE sobre este lugar (ver `decisaoSemResposta`).
        if (semResposta.length) estaDecisao.semResposta = { regioes: semResposta, regiao: API.getRegion(), pais: String(API.getCountry()) };
        if (destino && epoca === epocaDaSessao) await irProPaisDoPerfil(destino);
        // E a busca que ESPEROU por esta decisão enquanto ela corria (ver
        // `areaNoutroServidorSemDecisao`, R11-6-02): a que saiu antes de ela
        // começar (a troca de conta, dentro do `definirPerfil`) ou no meio (o
        // `maybePrefetch`, qualquer chamada direta) também é refeita aqui.
        //
        // Com "Minha área" de pé (a área do perfil vale), pelo `retomarBusca`: com
        // a fila VAZIA ele é o atualizar de sempre (`refazerFilaReal`), e com CARD
        // na fila só RETOMA, como sem "Minha área". Com card é a fila guardada do
        // "Disponível offline" aberta sem rede (o lie-fi do R12-4-02, ou o modo
        // avião), cuja reposição esperou o perfil (`fetchNextPage`) e armou a
        // espera: refeita, o `resetQueue` arrancava o card da mão, trazia de volta
        // os que a pessoa pulou e mandava na hora a decisão da janela do Desfazer
        // (MEDIDO no navegador, nos dois motores: o ✕ saía ~0,4 s depois do toque,
        // com o pulado de volta como o card da frente; auditoria da rodada 13,
        // R13-6-01 = R13-4-02). A área salva que o perfil não tem
        // (`refazerPelaArea`) e "Minha área" desligada pela falta de caixa mudam o
        // FILTRO, e a fila da tela é de outro filtro: é refeita.
        //
        // Com o TREINO aberto, a mesma régua, pela fila REAL que ele guarda (o
        // `retomarBusca` pergunta à `filaReal`): VAZIA, o refazer fica anotado pro
        // `sair()` (R9-7-04); com CARD, só retoma — o `startFetching` sai na
        // primeira linha no treino, e o `sair()` devolve a fila e repõe pelo
        // `maybePrefetch`. Anotado, o "Sair" do treino refazia a fila guardada: os
        // pulados voltavam como o card da frente (MEDIDO no navegador; o irmão do
        // R13-6-01, gotcha #63).
        else if ((refazerFila || refazerPelaArea || filaEsperaPerfil) && epoca === epocaDaSessao) {
            if (!refazerPelaArea && AppState.filters.myArea) {
                filaEsperaPerfil = false;
                retomarBusca();
            } else refazerFilaReal();
        }
    } finally {
        if (AppState._caixaDaMinhaAreaNoAr === decisao) AppState._caixaDaMinhaAreaNoAr = null;
        decidiu();
    }
    // A presença (fase 3) precisa do id do PERFIL — a lista exclui a própria
    // pessoa e o chat é dela. O `showMainScreen` chama a presença antes de o
    // perfil chegar, e ela desiste calada; sem esta linha, quem abria o app com
    // a sessão salva ficava sem lista e sem conversa até mexer nos filtros.
    // Depois dos países, porque o subtítulo da lista usa o nome do país.
    // (Achado na validação ao vivo: o smoke injetava o perfil ANTES e não via.)
    if (epoca === epocaDaSessao) window.Presenca?.sincronizar?.();
}

// O perfil que falhou na abertura (rede, 5xx) não era pedido de novo: o L6
// perdia a lixeira, o aprovar, o renomear e a recusa automática, e a presença
// não subia (ela precisa do id), até recarregar. Refaz na próxima PROVA de rede
// (`API.aoProvarRede`) — nunca por relógio — e no máximo uma vez por minuto.
// O pedido que nem teve resposta não conta no teto (ver o fim da carga).
let perfilPedidoEm = 0;
// Quantas cargas do perfil começaram nesta página: a carga que acaba sem
// resposta só devolve o carimbo do teto se nenhuma outra começou depois dela.
let cargasDoPerfil = 0;
// O LUGAR (região e país) de quando o perfil foi PEDIDO pela última vez — na
// carga da abertura ou na que refaz o perfil que faltou. Os países editáveis do
// perfil são do servidor DAQUELE pedido (`editableCountryIDs` é POR servidor), e
// levar a pessoa pro país dela só vale sobre o lugar que existia quando ele foi
// pedido. Pelo atalho do PWA (`/?action=filters`), a pessoa aplicava outra
// região (NA, os EUA) antes de o perfil chegar, e o perfil da ROW a levava pro
// Brasil DENTRO da NA: `na/30`, uma fila que não existe (auditoria de
// 2026-09-29, achado 10). Ver `paisDoPerfil`.
let lugarDoPedidoDoPerfil = null;
const PERFIL_REFAZER_MS = 60 * 1000;
function refazerPerfilSeFaltar() {
    if (!AppState.authenticated || AppState.profile) return;
    if (Date.now() - perfilPedidoEm < PERFIL_REFAZER_MS) return;
    // Com a conta desta aba em dúvida (R6-1-04), pela conferência: ela destrava
    // o card quando o perfil chega.
    if (AppState.contaEmDuvida === true) { conferirContaDestaAba(); return; }
    AppState._profilePromise = loadProfileAndAuxData();
}

// ── O país de quem entra ────────────────────────────────────────────────
// O app nascia no Brasil (30), região ROW, pra TODO mundo — o que servia à
// fila de quem o criou e a mais ninguém. Um champion da França abria a fila do
// Brasil, o servidor descartava tudo (ele não edita lá: o filtro de permissão
// tira local sem `permissions` do cabeçalho) e a tela dizia "Tudo limpo!" sem
// ele ter tratado nada. Da América do Norte era pior: o servidor dela nem
// respondia (ver `WAZE_REGIONS` no core).
//
// O perfil diz onde a pessoa EDITA: `editableCountryIDs`, POR SERVIDOR —
// MEDIDO nas duas contas do owner: [30] no ROW, [] no NA e no IL. Fila de país
// fora dessa lista vem sempre vazia, então trocar é sempre melhor que ficar.
// Lista vazia quer dizer que a pessoa edita em OUTRO servidor: pergunta o
// perfil lá (uma chamada por servidor, só neste caso — nunca pra quem já está
// no lugar certo). Staff edita em toda parte e escolhe sozinho.
//
// "Minha área" busca pela CAIXA das áreas, não pelo país: o país dela fica como
// está. Mas a caixa é buscada no servidor da REGIÃO, e com a lista daqui VAZIA
// a área está noutro servidor — a busca dela ia ao servidor errado, numa fila
// que não tem os locais da área. Era o que acontecia com OUTRA conta entrando
// no mesmo aparelho (a renovação pela extensão, outra pessoa no navegador): o
// "Minha área" da anterior fica (é um filtro, e os filtros são do aparelho), e
// quem só edita na NA seguia na ROW — MEDIDO no navegador, a busca dela saía
// `row bbox` e o perfil só era perguntado na ROW; sem "Minha área", a mesma
// pessoa ia pra `na/235` (auditoria da rodada 8, R8-6-06). Decisão do owner:
// com "Minha área", o perfil corrige a REGIÃO quando a lista daqui é vazia
// (pergunta os outros servidores, como sem ela), e "Minha área" fica ligado. O
// país vai junto só porque o de antes não existe no servidor novo: o par
// região/país fica coerente (o achado 10), e nenhum aviso de país sai — a fila
// continua a da área (ver `irProPaisDoPerfil`). Com a lista daqui CHEIA, nada
// muda: a área é deste servidor, e o país do filtro é o da pessoa.
//
// E só decide sobre o lugar do PEDIDO (`lugarDoPedidoDoPerfil`): mudou a região
// ou o país desde que o perfil foi pedido — a pessoa aplicou outro lugar nos
// Filtros enquanto ele vinha —, a escolha DELA vale, e a lista de editáveis
// (que é de outro servidor, se a região mudou) nem é lida. É o que mantém
// região e país coerentes: o país sai sempre da lista do servidor da região em
// que ele vai valer (achado 10).
//
// A pergunta que FALHOU — o Waze fora (o 500 `transient`), a página de erro da
// borda, a que nem chegou (`_motivo`) — não diz que a pessoa não edita lá: só a
// que LEU vale (a régua do `lerServidorDaMinhaArea`, R11-6-01). Contava como "não
// edita lá", e com "Minha área" a busca desligava o filtro e o GRAVAVA, com a
// frase falsa "Seu perfil do Waze não tem área de edição" e "Tudo limpo! …
// Confira o país e a região"; religar, o ↻, nada perguntava de novo até reabrir
// o app — também na troca de conta pela renovação (MEDIDO no navegador, nos dois
// motores; auditoria da rodada 12). Sem destino, as regiões SEM resposta vão
// em `semResposta`, e a decisão fica pendente (`decisaoSemResposta`): a busca
// de "Minha área" espera, com "Falha ao carregar", e a busca seguinte pergunta
// de novo só a elas (`refazerDecisaoSemResposta`). O 401 vai à conferência da
// sessão e a recusa do portão é terminal, como na carga do perfil.
//
// `so`: as regiões a perguntar (a pergunta repetida); `lugar`: o lugar sobre o
// qual se decide (por padrão, o do pedido do perfil).
async function paisDoPerfil(perfil, epoca, { so = null, semResposta = null, lugar = null } = {}) {
    const lugarMudou = () => {
        const pedido = lugar || lugarDoPedidoDoPerfil;
        return !!pedido && (API.getRegion() !== pedido.regiao || String(API.getCountry()) !== String(pedido.pais));
    };
    if (!perfil || perfil.isStaff || lugarMudou()) return null;
    const minhaArea = !!AppState.filters.myArea;
    const editaveis = (l) => (Array.isArray(l) ? l : []).map(Number).filter((n) => Number.isInteger(n) && n > 0);
    const aqui = editaveis(perfil.editableCountryIDs);
    if (aqui.length) {
        // A área é deste servidor: com "Minha área", o país do filtro fica.
        if (minhaArea) return null;
        return aqui.includes(Number(API.getCountry())) ? null : { regiao: API.getRegion(), pais: aqui[0] };
    }
    const falharam = [];
    for (const regiao of (so || REGIOES_DO_WAZE).filter((r) => r !== API.getRegion())) {
        const r = await API.getProfile(regiao);
        if (epoca !== epocaDaSessao) return null;
        if (!(r && r.success && r.profile)) {
            if (r && r.errorCategory === 'access_denied') { if (AppState.authenticated) recusaDoPortao(r); return null; }
            if (r && r.errorCategory === 'unauthorized') handleUnauthorized();
            falharam.push(regiao);
            if (lugarMudou()) return null;
            continue;
        }
        const la = editaveis(r.profile.editableCountryIDs);
        // A lista que esta pergunta trouxe fica, pra peneira dos Filtros naquela
        // região (ver `editaveisLidos`, R7-6-02). Só a que VEIO: a pergunta que
        // falhou não diz que a pessoa não edita lá.
        // E a caixa das áreas de lá: com "Minha área", é ela que decide (R9-6-04).
        // E as áreas gerenciadas de lá, pro seletor dos Filtros (R10-6-03).
        //
        // Fica mesmo com o lugar mudado no meio (a pessoa aplicou outro nos
        // Filtros): o que o servidor respondeu é dele, e a decisão abaixo é que
        // não vale mais. Jogada fora, a busca de "Minha área" no servidor que a
        // pessoa aplicou perguntava a ele de novo (`lerServidorDaMinhaArea`): duas
        // idas ao mesmo `/Session` (R10-6-02).
        anotarEditaveis(perfil, regiao, la, r.profile.areas, r.profile.managedAreas);
        if (lugarMudou()) return null;
        if (la.length) return minhaArea ? { regiao, pais: la[0], minhaArea: true } : { regiao, pais: la[0] };
    }
    if (falharam.length) {
        dfato('pais.semResposta', { regioes: falharam });
        if (semResposta) semResposta.push(...falharam);
    }
    return null;
}

// `minhaArea`: a ida é pela REGIÃO da área (ver `paisDoPerfil`, R8-6-06). Quem
// decide se a fila é a da área é o filtro na hora da ida (ver abaixo, R10-6-01).
async function irProPaisDoPerfil({ regiao, pais, minhaArea = false }) {
    const epoca = epocaDaSessao;
    // O lugar de ANTES: pra saber se a pessoa aplicou outro durante a espera
    // abaixo, e se os Filtros abertos mostram este (ver `redesenharLugarNosFiltros`).
    const antes = { regiao: API.getRegion(), pais: API.getCountry() };
    if (regiao !== API.getRegion()) {
        // A lista da região NOVA é pedida ANTES de a região valer (o
        // `listCountries` aceita a região), e nada muda se a sessão acabou
        // durante a espera: o "Sair" repõe região e país, e a região daqui
        // gravada antes do `await` deixava o par trocado (a região de quem
        // entrou com o país que o "Sair" repôs) — e o país de quem saiu voltava
        // ao aparelho, com o aviso na tela de entrada (auditoria da costura,
        // 2026-09-26, K12). Pela fonte única da lista: a que já chegou daquela
        // região não sai de novo (R9-6-01).
        const r = await pedirListaDePaises(regiao);
        if (epoca !== epocaDaSessao) return;
        // Nem se a pessoa aplicou outro lugar nos Filtros enquanto a lista vinha:
        // a escolha dela vale (achado 10).
        if (API.getRegion() !== antes.regiao || String(API.getCountry()) !== String(antes.pais)) return;
        API.setRegion(regiao);
        AppState.statesByCountry = {};
        AppState.countries = r && r.success ? r.countries : [];
    }
    // O "Minha área" que vale é o do filtro AGORA, não o de quando o
    // `paisDoPerfil` começou a perguntar: a pessoa pode tê-lo desligado (ou
    // ligado) num "Aplicar" no meio da pergunta ao outro servidor. Com o de
    // antes, a fila ia pros EUA pelo país sem o aviso "Mostrando a fila de…"
    // (auditoria da rodada 10, R10-6-01), ou o aviso saía sobre a fila da área.
    // O destino é o mesmo nos dois casos (a região e o país onde ela edita).
    minhaArea = !!AppState.filters.myArea;
    // "Minha área" vai pela região DA ÁREA se o perfil de LÁ tiver a caixa: as
    // `areas` do `/Session` são por servidor (R9-6-04), e o perfil de lá sem
    // área nenhuma é o "sem caixa" de verdade. Aí o filtro desliga e diz por
    // quê, e a ida é a do país, com o aviso dele.
    if (minhaArea && !caixaDaMinhaAreaEm(regiao)) {
        desligarMinhaAreaSemCaixa();
        minhaArea = false;
    }
    API.setCountry(pais);
    // Estado e área eram do país de antes.
    AppState.filters.stateId = '';
    AppState.filters.managedAreaId = '';
    saveFilters();
    dfato('pais.doPerfil', minhaArea ? { pais, regiao, minhaArea: true } : { pais, regiao });
    // Com "Minha área" a fila segue sendo a da ÁREA: "Mostrando a fila de
    // {país}" diria o que ela não é. A região é a da área, e não há o que avisar.
    let aviso = null;
    if (!minhaArea) {
        const nome = ((AppState.countries || []).find((c) => Number(c.id) === Number(pais)) || {}).name;
        // O LUGAR do aviso vai junto: o treino que termina pelo ↻ ou pelo
        // "Aplicar" só o mostra se a busca ainda é desse lugar (R10-7-02).
        aviso = { chave: nome ? 'toast.paisDoPerfil' : 'toast.paisDoPerfilSemNome', pais: nome || '',
            regiao: API.getRegion(), id: Number(pais) };
    }
    // Os Filtros ABERTOS mostravam o país de antes, e o "Aplicar" o devolvia.
    redesenharLugarNosFiltros(antes);
    window.Presenca?.sincronizar?.();
    // A fila, e o aviso que fala dela: com o treino aberto, no `sair()` dele.
    refazerFilaReal(aviso);
}

// A fila REAL refeita SEM gesto da pessoa: porque o PERFIL chegou — o país de
// quem entra (`irProPaisDoPerfil`), a busca que esperava por ele ("Minha área",
// com a fila vazia: com card ela só retoma, R13-6-01) ou a área salva que ele
// não tem (`completarPerfilChegado`) — ou porque a rede voltou com a fila vazia
// (`retomarBusca`). Com o TREINO aberto, a fila real
// está guardada nele e a da tela são os EXEMPLOS: o `resetQueue` daqui o
// encerrava CALADO — a faixa "nada é enviado ao Waze" sumia, o card da frente
// virava um pedido real e o ✕ seguinte ia pro Waze no nome da pessoa (R9-7-04,
// MEDIDO no navegador nos três caminhos do perfil; auditoria de 2026-10-06). O
// treino ANOTA, como já anota o perfil e a ordem, e o `sair()` refaz a fila,
// com o aviso do país. O LUGAR (região, país, a área do filtro) muda já, como
// sem o treino: é por ele que o ↻ e os Filtros buscam, se a pessoa sair do
// treino por eles. Nada que refaça a fila sem gesto da pessoa encerra o treino
// por baixo dela.
function refazerFilaReal(aviso = null) {
    if (typeof Treino !== 'undefined' && Treino.ativo === true) { Treino.anotarFilaRefeita(aviso); return; }
    if (aviso) showToast(t(aviso.chave, { pais: aviso.pais }), 'info', 7000);
    resetQueue();
    startFetching();
}

// O treino que termina por um GESTO de busca nova — o ↻, o "Aplicar" com outro
// filtro — não passa pelo `sair()`: o `resetQueue` o encerra, e o aviso do país
// que o perfil anotou nele (`Treino.anotarFilaRefeita`) ia embora com o `_salvo`
// — a fila de outro país entrava sem explicação nenhuma (R10-7-02, MEDIDO no
// navegador; auditoria da rodada 10). Quem encerra lê o aviso ANTES
// (`Treino.avisoDoPaisAnotado`) e o passa aqui DEPOIS de aplicar o lugar. A fila
// que vem é a do lugar de AGORA: o aviso (o mesmo do `refazerFilaReal`) sai só
// se ela ainda é a do país dele — no "Aplicar" a pessoa pode ter escolhido outro
// país, outra região ou "Minha área", e aí ele seria falso.
function avisarPaisDoTreinoEncerrado(aviso) {
    if (!aviso || AppState.filters.myArea) return;
    if (aviso.regiao !== API.getRegion() || String(aviso.id) !== String(API.getCountry())) return;
    showToast(t(aviso.chave, { pais: aviso.pais }), 'info', 7000);
}

// O lugar APLICADO mudou por baixo dos Filtros abertos (o país do perfil chegou
// depois de eles abrirem — pelo atalho do PWA é sempre assim): o seletor seguia
// mostrando o país de antes, e o "Aplicar", tocado só pra desmarcar um tipo,
// punha o de antes de volta — MEDIDO: buscas `row/30 → row/73 → row/30`
// (auditoria de 2026-09-29, achado 11). A tela acompanha, a menos que a pessoa
// tenha escolhido OUTRO lugar no modal: aí a escolha dela vale, e o "Aplicar" a
// grava. "Não mexeu" é o modal ainda mostrar o lugar de antes (`antes`) — quem
// trocou e voltou pro mesmo também não escolheu nada.
//
// Com os países da ABERTURA ainda chegando, o seletor diz "Carregando…" e
// ninguém escolheu país. Na MESMA região nada se redesenha: quem os puser no
// seletor já escolhe o país aplicado de agora. Com a REGIÃO trocada, não: a
// lista que vem é da região de antes, e a abertura a punha debaixo do seletor
// de região de antes com o país da nova — MEDIDO no navegador: quem só edita
// na NA, pelo atalho, ficava com `row` e os países da NA, e o "Aplicar" gravava
// `row/235`, os EUA no servidor da ROW (uma fila vazia). Aí a tela acompanha
// já: a carga nova toma o seletor (`cargaDePaises`) e a da região de antes,
// chegando depois, não escreve mais. A troca de região que a PESSOA deixou no
// ar (`esperaDosFiltros.regiao`) é dona do seletor e fica com ele.
function redesenharLugarNosFiltros(antes) {
    const modal = document.getElementById('filtersModal');
    if (!modal || modal.classList.contains('hidden')) return;
    const regiaoSel = document.getElementById('filterRegion');
    const paisSel = document.getElementById('filterCountry');
    if (!regiaoSel || !paisSel) return;
    if (regiaoSel.value !== antes.regiao) return;
    const abrindo = !!paisSel.dataset.carregando && !esperaDosFiltros.regiao;
    if (String(paisSel.value) !== String(antes.pais) && !(abrindo && API.getRegion() !== antes.regiao)) return;
    regiaoSel.value = API.getRegion();
    // As áreas gerenciadas da região que a tela passa a mostrar (R10-6-03).
    populateManagedAreaSelect();
    // Estado e área eram do país de antes (o `irProPaisDoPerfil` os zerou).
    aoMudarPaisNaTela();
    popularPaisEstado();
}

// UM 401 não é prova de que a sessão morreu — e tratar como se fosse era o
// caminho mais curto pro editor cair na tela de login sem ter pedido pra sair.
//
// Três coisas chegam aqui como 401 e só UMA delas exige entrar de novo:
//   · o Waze recusou os cookies de verdade (expiraram)           → é pra sair
//   · o Waze devolveu 403 por rajada/WAF                          → passageiro
//   · o KV devolveu vazio num blip de propagação                  → passageiro
// O core já manda chaves diferentes (`srv.err.cookiesExpired` × `sessionExpired`),
// mas nenhuma delas distingue passageiro de definitivo — só uma segunda
// chamada distingue.
//
// Então confirma antes de derrubar: espera um pouco e pergunta o perfil. Se
// responder, a sessão está viva e nada é apagado. Custa ~1s no caso em que os
// cookies morreram MESMO, e evita o logout falso no caso em que não morreram.
let verificandoSessao = false;
// A conferência EM CURSO, pra quem precisa do DESFECHO dela e não só de
// dispará-la: a escrita do lightbox que levou 401 enquanto outra chamada já
// conferia (ver `refazerDepoisDo401`, V5). Promessa compartilhada, como as da
// busca e do perfil — sem espera em laço.
let conferenciaDaSessao = null;

// Recompõe a fila depois de uma falha que NÃO era sessão morta.
//
// Existe porque `startFetching()` sozinho NÃO recompõe nada, e é isso que
// produziu a tela do owner ("Tudo limpo!" sobre 217 pedidos pendentes): a busca
// que falhou deixa `hasMore: false`, e o laço do `startFetching` é GUARDADO por
// `hasMore` — ou seja a "retentativa" não busca coisa nenhuma, só zera o
// `loadError` e desenha o painel de fila vazia. Os dois caminhos de
// recomposição (alarme falso do 401, e renovação pela extensão) chamavam
// `startFetching()` cru. O botão "Tentar de novo" nunca caiu nisto porque ele
// passa antes pelo `resetQueue`, que repõe `hasMore` — foi o que escondeu o
// defeito: testar pelo botão dava certo.
//
// `loadError` é o que distingue "a fila esvaziou por FALHA" de "a fila acabou
// de verdade". Sem essa distinção, forçar `hasMore` gastaria uma requisição a
// mais toda vez que o backlog tivesse realmente zerado — e o app roda no free
// tier, onde requisição é recurso contado.
const MAX_REBUSCAS_AUTO = 2;
let rebuscasAuto = 0;

function rebuscarDepoisDeFalha() {
    if (AppState.fetching) return;
    // "Minha área" com a busca RECUSADA porque o perfil não tinha chegado
    // (`filaEsperaPerfil`), e o perfil CHEGOU — pelo alarme falso de um 401, que
    // chama esta função logo depois de começar o `completarPerfilChegado`. Quem
    // refaz essa fila é ele, depois de decidir a caixa e o lugar (no servidor da
    // área, R8-6-06): buscar aqui também saía em DOBRO, e a primeira era jogada
    // fora — pra quem só edita noutro servidor, ela ia ao servidor errado, e a
    // tela dizia "Tudo limpo! … Confira o país e a região" até o perfil de lá
    // responder (MEDIDO no navegador, auditoria da rodada 9, R9-6-03). Sem o
    // perfil ainda, segue abaixo: o `startFetching` o pede e espera.
    //
    // E só com a decisão NO AR (`_caixaDaMinhaAreaNoAr`): é ela que refaz a
    // fila. Sem ela, ninguém refazia. Um 401 passageiro na pergunta ao servidor
    // que a pessoa aplicou à mão (`lerServidorDaMinhaArea`) vai à conferência;
    // a sonda responde ("sua sessão continua válida") e já LÊ esse servidor —
    // e a busca que esperava a caixa dele ficava em "Falha ao carregar …
    // Verifique sua conexão" até o "Tentar de novo", com o que faltava na mão
    // (MEDIDO no navegador, nos dois motores: 0,4 a 15 s; auditoria da rodada
    // 12, R12-6-01). No 1º perfil pela sonda (o R9-6-03), o
    // `completarPerfilChegado` já pôs a decisão no ar antes de chegar aqui.
    if (filaEsperaPerfil && AppState.profile && AppState._caixaDaMinhaAreaNoAr) return;
    // E a fila VAZIA que só espera a decisão do lugar que ficou SEM resposta
    // (`decisaoSemResposta`): o "Tudo limpo!" sem "Minha área", ou a busca de
    // "Minha área" esperando por ela (`filaEsperaPerfil`). Nenhuma busca falhou:
    // recompor era só perguntar de novo, 1,2 s depois, ao servidor que acabou de
    // recusar com um 401 — o `/Session` de OUTRO servidor, num pedido que a pessoa
    // nem fez, e o ritmo que faz um WAF marcar a conta. A sessão está viva (é o
    // alarme falso que chama aqui), e quem pergunta de novo é a próxima busca da
    // pessoa — o "Tentar de novo", o ↻, o "Verificar novamente": uma ida por
    // busca, nenhuma por relógio, a régua da pendência (auditoria da rodada 13,
    // R13-6-02). A busca que FALHOU (`loadError` sem a espera) segue abaixo.
    if (AppState.queue.length === 0 && (!AppState.loadError || filaEsperaPerfil) && decisaoSemResposta()) return;
    if (AppState.queue.length > 0) {
        // COM card na fila: foi a REPOSIÇÃO que levou o 401. A busca que falhou
        // deixou `hasMore = false` e `loadError = true`, e com a sessão viva a
        // fila parava de se repor: o `maybePrefetch` (que roda a cada card que
        // sai) nunca mais buscava, e ao fim dos cards a pessoa via "Falha ao
        // carregar" com a rede e a sessão boas (auditoria de 2026-09-26, O6).
        // Repõe as duas, com o MESMO teto de sempre — o `maybePrefetch` busca
        // agora se a fila já está no limite, ou quando chegar lá.
        if (!AppState.loadError || rebuscasAuto >= MAX_REBUSCAS_AUTO) return;
        rebuscasAuto++;
        AppState.loadError = false;
        AppState.hasMore = true;
        maybePrefetch();
        return;
    }
    // Fila vazia SEM falha: não há o que repor, e o `startFetching` vai só
    // pintar o "Tudo limpo!" — que aí é verdade. Com o MESMO teto de baixo: o
    // `startFetching` pergunta de novo a decisão do lugar que ficou pendente
    // (`refazerDecisaoSemResposta`), e o 401 dela vem pra cá de novo — com o
    // `/Session` de OUTRO servidor recusando (o 403 em rajada do WAF do Waze
    // num servidor só) e a sonda daqui respondendo, eram duas idas ao Waze, um
    // "Conexão instável…" e um "Tudo limpo!" anunciado a cada 1,2 s, SEM FIM
    // (MEDIDO no navegador, nos dois motores: 13 + 13 pedidos em 15 s;
    // auditoria da rodada 13, R13-6-02).
    if (!AppState.loadError) {
        if (rebuscasAuto >= MAX_REBUSCAS_AUTO) return;
        rebuscasAuto++;
        startFetching();
        return;
    }
    // TETO, e ele não é preciosismo: sem isto o desenho é um laço de requisição
    // (falha → confere → alarme falso → rebusca → falha…). Estourado o teto, o
    // erro FICA na tela com o botão de tentar de novo — honesto, e quem decide
    // gastar a próxima requisição é a pessoa.
    if (rebuscasAuto >= MAX_REBUSCAS_AUTO) return;
    rebuscasAuto++;
    AppState.hasMore = true;
    startFetching();
}

// ── Diário técnico do modo dev ────────────────────────────────────────────
//
// Modelo trazido do botequei (projeto do owner), onde ele já tinha resolvido o
// problema que eu ia apresentar como novidade. Duas ideias vieram de lá e são o
// que fazem isto funcionar:
//
//  1. COBERTURA POR FUNIS, não remendo em 200 lugares. Instrumentar cada call
//     site envelhece: o próximo recurso nasce sem log e ninguém percebe. Em vez
//     disso a instrumentação mora nos ESTRANGULAMENTOS por onde tudo passa —
//     `showToast`, `openModal`, a barra de ações, o `fetchNextPage`, o
//     `handleUnauthorized`. Recurso novo já nasce coberto.
//
//  2. O DIÁRIO DE TELA É O "PRINT TEXTUAL". Página web não tira foto dos
//     próprios pixels no Android (o `getDisplayMedia` não existe lá, e o resto
//     exige biblioteca e quebra na CSP). A jornada de telas + os toasts contam
//     o que a pessoa viu, e valem mais que uma imagem quase certa.
//
// O QUE ISTO CONSERTA, com evidência do dia em que nasceu: o botão de baixar
// ficava dentro de Filtros → Preferências. Pra apertá-lo era preciso abrir dois
// modais POR CIMA da tela com defeito — e o toast, que dura 4s, já tinha
// sumido. O diagnóstico do owner chegou com `loadErrorState` visível e ZERO
// toast no DOM, justamente perdendo a evidência ("Conexão instável") que
// derrubou a hipótese errada. Instrumento que não alcança o momento do defeito
// não é instrumento.
//
// CUSTO ZERO DESLIGADO: `dlog` sai na primeira linha. Nada de closure, nada de
// objeto criado, nada de `JSON.stringify` — o app tem 200 swipes por sessão e o
// valor dele é o ritmo.
const DLOG_TETO = 800;
// 3: entraram `resumo.alertas` (sentinelas) e a seção `computado` — a camada
// que o navegador decidiu, que o `dom` não mostra. Aditivo: leitor de formato 2
// só ignora as chaves novas.
const DIAG_FORMATO = 3;
let dlogAnel = [];

function dlogLigado() {
    return typeof AppState !== 'undefined' && !!(AppState.devMode && AppState.devMode.active);
}

// `k` é a CHAVE do evento (curta, estável, greppável). `d` é o que importa
// daquele evento — nunca o objeto inteiro de onde ele saiu.
function dlog(k, d) {
    if (!dlogLigado()) return;
    try {
        dlogAnel.push({ t: Date.now(), k, ...(d || {}) });
        if (dlogAnel.length > DLOG_TETO) dlogAnel.shift();
    } catch (e) {}
}

// ── O anel que NÃO tem portão ─────────────────────────────────────────────
//
// MEDIDO nos 7 diagnósticos reais recebidos até 2026-09-10: **4 chegaram com o
// diário VAZIO**, e o pior é justamente o dos modais achatados no iOS — anel de
// chamadas CHEIO (60, ou seja muita atividade) e `diario: []`. O motivo é
// estrutural, não descuido: o `dlog` sai na primeira linha com o modo dev
// desligado, e a pessoa só liga o modo dev DEPOIS de o problema acontecer. O
// instrumento apagava exatamente o trecho que interessa.
//
// Tem uma ironia que fecha o argumento: o `diagCapturarErros()` roda
// incondicionalmente no `initApp`, e lá dentro registra um observador de long
// task que chama `dlog('lenta', …)`. Ou seja, a captura sempre-ligada alimentava
// um anel com portão — o dado de travada era jogado fora exatamente quando
// ninguém estava gravando.
//
// **O portão do `dlog` continua valendo, e por CUSTO**: o app tem ~200 swipes
// por sessão e o valor dele é o ritmo. Por isso este anel é só o subconjunto que
// sai de graça, e o critério de entrada é duplo:
//   1. **RARO** — nada que aconteça uma vez por swipe. Modal abre, tela gira,
//      teclado sobe, busca falha: acontecem unidades de vezes por sessão.
//   2. **SEM DADO DE TERCEIRO** — nome de local, nome de autor e texto livre não
//      entram aqui nem com o modo dev ligado. Só id de elemento nosso, número e
//      chave de erro. O `dlog` segue sendo o lugar do que identifica pedido.
// Teto de 120 × ~40 bytes ≈ 5 KB. `API.chamadas` é o precedente: nunca teve
// portão, e é por isso que é a única coisa que sobrevive num relato de 1ª hora.
const DFATO_TETO = 120;
let dfatoAnel = [];

function dfato(k, d) {
    try {
        dfatoAnel.push({ t: Date.now(), k, ...(d || {}) });
        if (dfatoAnel.length > DFATO_TETO) dfatoAnel.shift();
    } catch (e) {}
}

// ── DIÁRIO DE SESSÕES: o que sobrevive ao tombo ──────────────────────────
//
// O `dfato` já é o anel sem portão, mas ele vive em MEMÓRIA — e a sessão cair
// é justamente o evento depois do qual o editor fecha o app. Quando ele volta
// pra gerar o diagnóstico, o anel está vazio: o mesmo buraco que fez o `dfato`
// nascer ("4 dos 7 diagnósticos chegaram com `diario: []`"), agora no evento
// mais caro que o app tem.
//
// Daí este anel em localStorage. Ele existe pra responder UMA pergunta que
// hoje depende da memória de quem relata — *"quanto tempo a sessão durou?"* —
// trocando "acho que uns dois dias" por dois carimbos de data.
//
// Regras de entrada, as mesmas do `dfato` e por isso mesmo: (a) RARO — entrar,
// cair e o prazo MUDAR, nunca por swipe, senão volta o custo de escrita que o
// gotcha do localStorage mede em quadros perdidos; (b) SEM DADO DE TERCEIRO e
// sem token: só instante, evento, caminho de entrada e a chave do motivo.
//
// Sai no "Sair", com o resto (contrato de privacidade). Isso não cega a
// investigação: quem deu Sair SABE que deu, e o caso que se investiga é o de
// quem NÃO saiu e perdeu a sessão assim mesmo.
const SESSOES_KEY = 'waze_places_sessoes';
const NASCIMENTO_KEY = 'waze_places_nascimento';
const SESSOES_TETO = 40;

function lerDiarioDeSessoes() {
    try {
        const v = JSON.parse(safeLS.get(SESSOES_KEY) || '[]');
        return Array.isArray(v) ? v : [];
    } catch (e) { return []; }
}

function registrarEventoDeSessao(e, d) {
    try {
        const anel = lerDiarioDeSessoes();
        anel.push({ t: Date.now(), e, ...(d || {}) });
        while (anel.length > SESSOES_TETO) anel.shift();
        safeLS.set(SESSOES_KEY, JSON.stringify(anel));
    } catch (err) { /* armazenamento cheio/bloqueado: o diário é instrumento, nunca requisito */ }
}

// A sessão pode já estar ativa quando este registro começou a existir — e esse
// é o caso de TODO aparelho no dia do deploy, inclusive o dos testadores que
// vão relatar. `API.getSession()` lê o token do armazenamento SEM passar pelo
// `setSession`, que é onde o gancho mora, então a abertura não carimba nada: o
// `caiu` chega sozinho, sem início, e a duração — que é o produto inteiro desta
// seção — sai vazia justamente no primeiro relato.
//
// Marco PRÓPRIO, e não `token+`: "já estava ativa" NÃO é "entrou agora". A
// duração contada daí é um PISO ("pelo menos tanto"), nunca a medida — chamar
// os dois de entrada seria inventar um número, que é pior que não ter nenhum.
//
// Só registra quando NÃO há início em aberto, senão viraria uma linha por
// abertura do app e quebraria a regra de entrada do diário (raro, nunca por
// gesto repetido).
function marcarSessaoJaAtiva() {
    try {
        if (!safeLS.get('waze_session_token')) return;
        const anel = lerDiarioDeSessoes();
        for (let i = anel.length - 1; i >= 0; i--) {
            const e = anel[i].e;
            if (e === 'token+' || e === 'jaAtiva') return;          // já há início em aberto
            if (e === 'token-' || e === 'caiu' || e === 'saiu') break;  // o último ciclo fechou
        }
        registrarEventoDeSessao('jaAtiva');
    } catch (e) { /* instrumento nunca atrapalha a abertura */ }
}

// Quando este app rodou pela PRIMEIRA vez NESTE armazenamento. É o detector de
// apagamento pelo navegador, e ele funciona por CONTRADIÇÃO: o Safari apaga
// todo o storage script-writable após 7 dias sem interação (webkit.org, e web
// app na tela inicial é ISENTA — tem contador próprio). Quando isso acontece o
// diário some junto, então a evidência não pode ser só o diário: um carimbo de
// ontem num aparelho onde a pessoa diz usar o app há um mês É o apagamento.
function nascimentoDoArmazenamento() {
    try {
        const v = Number(safeLS.get(NASCIMENTO_KEY));
        if (Number.isFinite(v) && v > 0) return v;
        const agora = Date.now();
        safeLS.set(NASCIMENTO_KEY, String(agora));
        return agora;
    } catch (e) { return null; }
}

// O `API.setSession` é o ponto ÚNICO por onde o token entra e sai do
// armazenamento, e o gancho mora LÁ de propósito: perseguir os call sites um a
// um é como se perde o próximo caminho de entrada que alguém adicionar (a
// mesma lição do gotcha #39 — persiga o CONCEITO, não o lugar). Aqui fica o
// fato BRUTO; quem sabe o motivo (caiu? saiu?) registra à parte, logo depois.
if (typeof window !== 'undefined') window.__sessaoEvento = registrarEventoDeSessao;

// Identidade de pedido no diário: `creatorId` (número) e NUNCA `createdBy`.
// O nome é dado de terceiro e o id resolve a mesma pergunta — é a mesma regra
// que a reincidência já segue (o nome muda, o id não).
function dlogPlace(p) {
    if (!p) return null;
    return { v: p.venueID, ur: p.updateRequestID, tipo: p.purType, autor: p.creatorId ?? null };
}

// ── Watchdog: o que NÃO volta no prazo ────────────────────────────────────
// Ideia do botequei, onde flagrou o `getCurrentPosition` preso no prompt. Aqui
// o alvo é a fila congelada: `fetching` que fica true, ação pendente que nunca
// executa, promessa de busca que não resolve. Nenhum desses grita — a tela só
// para, e "parece que acabou o trabalho" ninguém reporta.
const dlogPendencias = new Map();
function dlogVigiar(o, ms = 20000) {
    if (!dlogLigado()) return;
    if (dlogPendencias.has(o)) clearTimeout(dlogPendencias.get(o));
    dlogPendencias.set(o, setTimeout(() => {
        dlogPendencias.delete(o);
        dlog('pendurada', { o, ms });
    }, ms));
}
function dlogVoltou(o) {
    const h = dlogPendencias.get(o);
    if (h) { clearTimeout(h); dlogPendencias.delete(o); }
}

// ── Momentos: o que a pessoa via ──────────────────────────────────────────
// Cada toque no FAB congela UM momento. O código, os caches e o ambiente NÃO
// entram aqui — eles são iguais em todos e vão uma vez só no relatório. Sem
// isso, cada captura repetiria ~600 KB e o arquivo viraria intransportável.
let dlogMomentos = [];
const DLOG_MAX_MOMENTOS = 12;

// Teto POR MOTIVO, só pro que acontece por uso normal. Motivo que só dispara
// quando algo deu errado (erro de JS, alarme falso de sessão) não entra aqui:
// ali o anel inteiro é pouco. O arraste é o oposto — é o gesto central do app,
// e sem cota ele toma as 12 vagas sozinho.
// DOIS e não um: o primeiro arraste da sessão raramente é o que interessa, e
// com dois sobra o mais recente, que é o que a pessoa acabou de ver.
const DLOG_COTA_POR_MOTIVO = { 'auto:arraste': 2 };

function dlogTelaAtual() {
    // `offsetParent` NÃO serve aqui: ele é `null` para elemento `position:
    // fixed`, e TODO modal deste app é fixed. Com ele, `modais` vinha sempre
    // vazio — ou seja a capacidade central do FAB (registrar EM CONTEXTO, com o
    // modal por cima) não capturava o contexto, em silêncio. Pego pelo teste
    // ponta a ponta, que abria a Ajuda antes de tocar e cobrava o modal na
    // lista. Aqui vale o que decide o pixel: a classe, o `display` computado e
    // uma caixa com tamanho.
    const visivel = (id) => {
        const e = document.getElementById(id);
        if (!e || e.classList.contains('hidden')) return false;
        if (getComputedStyle(e).display === 'none') return false;
        const r = e.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
    };
    const modais = (typeof MODAL_IDS !== 'undefined' ? MODAL_IDS : []).filter(visivel);
    const painel = visivel('loadErrorState') ? 'falhaAoCarregar'
                 : visivel('noMoreCards') ? 'tudoLimpo'
                 : visivel('loadingCard') ? 'carregando'
                 : cardDaFrente() ? 'card' : 'nada';
    return {
        tela: visivel('authScreen') ? 'entrar' : (visivel('appScreen') ? 'app' : '?'),
        painel,
        // O MESMO painel diz coisas diferentes, e o `painel` sozinho chamava
        // tudo de "tudoLimpo" — inclusive o "Fim da fila" (pulados pendentes) e
        // o "nada nesta fila" de quem não tratou nada (auditoria de 2026-09-26);
        // e a falha, "sem conexão" ou "falha ao carregar". A variante sai da
        // CHAVE do texto na tela (`trocarTextoI18n`), que não depende do idioma.
        ...(painel === 'tudoLimpo' || painel === 'falhaAoCarregar' ? { variante: dlogVarianteDoPainel(painel) } : {}),
        // O `painel` diz só a camada de CIMA. No relato de 2026-09-22 ele
        // disse "carregando" com um card montado por baixo, e a captura não
        // tinha como contar o resto — este campo conta.
        cardMontado: !!cardDaFrente(),
        modais,
        // Era `visivel('lightbox')`, e esse id NÃO EXISTE (os dois são
        // `imageLightbox` e `mapaLightbox`): o campo saiu `false` em TODO
        // momento de todo relatório, com o lightbox aberto ou não. É a mesma
        // falha que o comentário do FAB já registra ("escrevi `lightbox` e o
        // elemento se chama `imageLightbox`") — id errado num seletor some com
        // o dado SEM DIZER NADA. `test/diagnostico.test.mjs` cobra que todo id
        // consultado aqui exista no HTML.
        lightbox: visivel('imageLightbox') ? 'foto' : (visivel('mapaLightbox') ? 'mapa' : false),
        // O TREINO aberto (R8-4-06): a fila na tela é a de EXEMPLOS, e a captura e
        // o relatório não diziam isso — a palavra "treino" só aparecia no id inerte
        // do pedido da frente. Ver `diagTreinoAgora`.
        treino: diagTreinoAgora(),
    };
}

// O treino, em NÚMEROS: aberto ou não, quantas ações já houve nele (`passo`) e
// quantos EXEMPLOS (os clones inertes e os sintéticos) estão na fila agora — com
// ele aberto, é ela que o `appState` e o `estado.fila` das capturas contam. A
// fila REAL que ele guarda vai inteira só no relatório (`diagTreinoGuardado`).
// Nunca lança: a captura não pode cair por causa dele.
function diagTreinoAgora() {
    try {
        if (!Treino.ativo) return { ativo: false };
        return { ativo: true, passo: Treino.passo, exemplos: (AppState.queue || []).length };
    } catch (e) { return { ativo: null }; }
}

// A fila REAL que o treino GUARDA enquanto está aberto (`Treino._salvo`), lida
// direto (R8-4-06): a fila, o pedido que estava na frente, o foco no autor, as
// épocas (a da fila real e a que o treino pôs), o que o Waze recusou com ele
// aberto e volta como card (`devolver`), e se o perfil e a ordem chegaram nele
// (`perfilChegou`, `ordemMudou`). Sem isto, o relato "ao sair do treino a fila
// voltou errada" chegava sem a fila que voltou: o `appState` tem os exemplos. O
// pedido da frente sai como ÍNDICE, como no `appState`. Fechado, só `ativo`.
//
// E o que ESPERA o "Sair" dele: a fila guardada do offline que a abertura sem
// rede leu com ele aberto (`abrirGuardada`) e a recusa automática pedida nele
// (`recusaPedida`). As duas entraram no `_salvo` em paralelo com esta função, e
// ficaram de fora: o relatório feito no treino dizia "fila real: 0 pedidos" com a
// fila guardada esperando o "Sair" — quem lia concluía que a fila tinha sumido
// (auditoria da rodada 9, R9-4-07).
function diagTreinoGuardado() {
    try {
        const s = Treino.ativo ? Treino._salvo : null;
        if (!s) return { ativo: false };
        const fila = Array.isArray(s.queue) ? s.queue : [];
        return {
            ...diagTreinoAgora(),
            fila: diagSeguro(fila),
            currentPlaceIdx: s.currentPlace ? fila.indexOf(s.currentPlace) : -1,
            autorEmFoco: s.autorEmFoco ?? null,
            epoca: s.epoca, epocaDoTreino: s.epocaDoTreino, epocaAgora: AppState.fetchEpoch,
            devolver: diagSeguro(Array.isArray(s.devolver) ? s.devolver : []),
            perfilChegou: !!s.perfilChegou, ordemMudou: !!s.ordemMudou,
            abrirGuardada: !!s.abrirGuardada, recusaPedida: !!s.recusaPedida,
            // A fila guardada do offline que a abertura leu nele (quantos e de
            // quando) e a fila que o PERFIL mandou refazer nele (R9-7-04): os
            // dois também esperam o "Sair".
            filaGuardadaLida: s.filaGuardadaLida && typeof s.filaGuardadaLida === 'object'
                ? { n: s.filaGuardadaLida.n ?? null, t: s.filaGuardadaLida.t ?? null } : null,
            refazerFila: !!s.refazerFila,
            avisoDoPais: s.avisoDoPais && typeof s.avisoDoPais === 'object' ? (s.avisoDoPais.chave || null) : null,
        };
    } catch (e) { return { erro: String((e && e.message) || e).slice(0, 120) }; }
}

// Qual das frases o painel de fila vazia (ou de falha) está mostrando, pela
// chave que o `showNoPlaces` pôs no texto.
function dlogVarianteDoPainel(painel) {
    try {
        if (painel === 'falhaAoCarregar') {
            const h = document.querySelector('#loadErrorState h3');
            return h && h.getAttribute('data-i18n') === 'states.error.titleOffline' ? 'semConexao' : 'falha';
        }
        const nm = document.getElementById('noMoreCards');
        const h = nm && nm.querySelector('h3[data-i18n^="states.empty.title"]');
        const p = nm && nm.querySelector('p[data-i18n^="states.empty.body"]');
        if (h && h.getAttribute('data-i18n') === 'states.empty.titlePulados') return 'fimDaFila';
        if (p && p.getAttribute('data-i18n') === 'states.empty.bodyNada') return 'nadaNestaFila';
        return 'limpo';
    } catch (e) { return null; }
}

// ── REDE e OFFLINE no instante da captura ─────────────────────────────────
// O relato de 2026-09-22 foi TODO sobre a falta de rede, e nenhuma captura
// dizia se havia rede: a janela sem sinal foi reconstruída de 16 "Failed to
// fetch" e da fila de saída abrindo e fechando. E o estado do offline (a janela
// que monta a URL da foto, o resultado da varredura) morava em variáveis que
// não iam pro arquivo — a janela foi deduzida do sufixo das URLs. Duas funções
// baratas e síncronas, sem dado de ninguém.
function diagRedeAgora() {
    const c = navigator.connection || {};
    return { online: navigator.onLine, tipo: c.effectiveType || null };
}

function diagOfflineAgora() {
    try {
        return { ligado: offlineLigado(), janelaServida: offlineJanelaServida,
                 janelaAtual: Math.floor(Date.now() / OFFLINE_CICLO_MS),
                 resultado: offlineUltimoResultado, varrendo: offlineVarrendo };
    } catch (e) { return { erro: String((e && e.message) || e).slice(0, 120) }; }
}

// ── A camada COMPUTADA: o que o NAVEGADOR decidiu ─────────────────────────
// O diagnóstico já trazia o que a página É (`dom`) e o que o app ACHA
// (`AppState`). Faltava a terceira: o que o navegador decidiu. Bug de layout
// mora inteiro aí, e ela não se lê do `outerHTML`.
//
// Custou uma investigação inteira: o `--kb-inset` cravado em 388px no PWA do
// iOS (v2026.09.09-02). O valor que decidia era `visualViewport.height`, que
// NÃO era capturado — cheguei nele por sorte, porque o `--kb-inset` estava num
// `style=` inline do `<html>` e veio de carona no `dom`. E o segundo fato
// decisivo, que NADA estava focado, não estava no arquivo de jeito nenhum.
// A geometria do modal eu tive que reconstruir extraindo quadros do vídeo do
// editor com ffmpeg e medindo pixel a pixel — sendo que é um
// `getBoundingClientRect()`, 40 bytes de JSON.
//
// Nada aqui é dado de terceiro: são números da janela e do layout.
function diagComputado() {
    const fora = {};
    try {
        const vv = window.visualViewport;
        fora.janela = { innerW: window.innerWidth, innerH: window.innerHeight,
                        outerW: window.outerWidth, outerH: window.outerHeight };
        fora.visualViewport = vv ? {
            w: Math.round(vv.width), h: Math.round(vv.height),
            offsetTop: Math.round(vv.offsetTop) || 0, offsetLeft: Math.round(vv.offsetLeft) || 0,
            escala: Number(vv.scale.toFixed(3)),
            // A subtração JÁ FEITA — é ela que vira `--kb-inset`, e é ela que
            // mentiu. Deixar pra quem lê refazer a conta é deixar o erro passar.
            coberto: Math.round(window.innerHeight - vv.height - vv.offsetTop),
        } : null;

        const a = document.activeElement;
        fora.foco = a ? {
            tag: a.tagName, id: a.id || null, tipo: a.getAttribute && a.getAttribute('type'),
            emModal: !!(a.closest && a.closest('.modal-root')),
            abreTeclado: (typeof campoDeTextoFocado === 'function') ? campoDeTextoFocado() : null,
        } : null;

        // Lidas do COMPUTADO, nunca do atributo inline: o atributo é o que
        // alguém escreveu, o computado é o que vale.
        const cs = getComputedStyle(document.documentElement);
        fora.varsCss = {};
        for (const v of ['--kb-inset', '--header-h', '--linha-comentario', '--lb-tira']) {
            const t = cs.getPropertyValue(v).trim();
            if (t) fora.varsCss[v] = t;
        }
        // As safe-areas do iPhone RESOLVIDAS. `env()` não se lê direto — só
        // medindo um elemento que as use. Sem isto, a altura do header no iOS
        // só se adivinha.
        fora.safeArea = medirSafeArea();

        fora.media = {};
        for (const q of ['(pointer: coarse)', '(prefers-reduced-motion: reduce)',
                         '(orientation: portrait)', '(display-mode: standalone)',
                         '(prefers-color-scheme: dark)']) {
            fora.media[q] = matchMedia(q).matches;
        }

        fora.tema = {
            htmlClasse: document.documentElement.className,
            guardado: safeLS.get(THEME_KEY),
            // A cor da barra do sistema: a meta `theme-color` que VALE, que é a
            // primeira cuja media casa (não a primeira do documento). É o que
            // a sentinela `temaContraditorio` compara com o tema do app.
            barra: (() => {
                const m = [...document.querySelectorAll('meta[name="theme-color"]')]
                    .find((x) => !x.media || matchMedia(x.media).matches);
                return m ? m.getAttribute('content') : null;
            })(),
        };

        fora.camadasAbertas = diagCamadasAbertas().map((e) => e.id || e.className.slice(0, 40));
        fora.geometria = diagGeometria();
        // A foto do card da FRENTE: o aviso de "precisa de sinal" está lá, e a
        // foto carregou? Os dois juntos são o defeito do relato de 2026-09-22
        // (ver a sentinela `fotoEscondidaComAviso`). Só o da frente: o de fundo
        // é clone e não tem ouvinte nenhum.
        const frente = cardDaFrente();
        const foto = frente && frente.querySelector('.card-image');
        fora.fotoDaFrente = frente ? {
            aviso: !!frente.querySelector('.card-sem-foto'),
            carregada: !!(foto && foto.complete && foto.naturalWidth > 0),
            src: foto ? String(foto.currentSrc || foto.src || '').slice(0, 160) : null,
        } : null;
        // Só as falhas desde a leitura ANTERIOR (ver `diagTilesLidosAte`).
        fora.tilesGuardadosQueFalharam = diagTilesParaAlerta();
        // O esqueleto de "carregando" e o card da frente, cada um por si: o
        // `painel` do `dlogTelaAtual` diz só o de CIMA ("carregando"), e foi
        // assim que o relato de 2026-09-22 chegou sem dizer que havia um card
        // montado por baixo (ver a sentinela `esqueletoSobreCard`). Classe E
        // caixa, a mesma régua do `visivel` de lá.
        const esq = document.getElementById('loadingCard');
        const rEsq = esq && esq.getBoundingClientRect();
        fora.telaDoCard = {
            esqueleto: !!(esq && !esq.classList.contains('hidden') && rEsq.width > 0 && rEsq.height > 0),
            card: !!frente,
        };
        // Pedido que já está esperando envio e voltou pra fila de pedidos: o
        // defeito do relato de 2026-09-22 (ver `semOsJaDecididos` e a sentinela
        // `pedidoDecididoNaFila`). Vai só a CONTAGEM — a chave é id de pedido
        // de terceiro, e o conteúdo da fila de saída já está no localStorage.
        fora.decididos = diagDecididosAgora();
    } catch (e) {
        fora._erro = String((e && e.message) || e).slice(0, 160);
    }
    return fora;
}

// PURA. A fila de saída × a fila de pedidos DESTA aba, pela MESMA chave do
// filtro de entrada (`chaveDoPedido`), e só em números. O pedido que a OUTRA
// aba decidiu com o card já aqui (`daOutraAba`, ver `anotarDecididosPorOutraAba`)
// não é o que a sentinela procura — nenhum caminho de entrada falhou — e vai à
// parte (`porOutraAba`), sem contar em `naFila` (R7-4-05).
function diagDecididos(saida, fila, daOutraAba) {
    const naSaida = new Set((Array.isArray(saida) ? saida : []).map(chaveDoPedido).filter(Boolean));
    const voltaram = (Array.isArray(fila) ? fila : []).filter((p) => naSaida.has(chaveDoPedido(p)));
    const porOutraAba = daOutraAba ? voltaram.filter((p) => p && typeof p === 'object' && daOutraAba.has(p)).length : 0;
    return { naSaida: naSaida.size, naFila: voltaram.length - porOutraAba, ...(porOutraAba ? { porOutraAba } : {}) };
}

// O que a sentinela compara AGORA: a fila de saída × a fila REAL (`filaReal()`).
// Com o treino aberto, a da tela são os EXEMPLOS, e o pedido decidido que voltou
// à fila guardada pelo treino passava calado — justamente no relatório que o
// R8-4-06 passou a gerar "dentro do treino" (junção do lote 12; o R8-4-02 já
// anota a decisão da outra aba na fila real).
function diagDecididosAgora() {
    return diagDecididos(carregarFilaDeSaida(), filaReal(), decididosPorOutraAbaComCardAqui);
}

// O pedido que a OUTRA ABA decidiu com o card JÁ na fila desta. A fila de saída
// é do APARELHO e a de pedidos é de cada aba: a decisão de lá (sem sinal,
// esperando envio) não tira o card daqui, que entrou ANTES — e nenhum caminho de
// entrada falhou. A sentinela `pedidoDecididoNaFila` e o `saida.repetida` do
// diário diziam "voltou como card" nesse caso, mandando quem lê atrás de um
// filtro furado que não existe (R7-4-05, MEDIDO: as duas abas com a mesma fila,
// a A decide sem sinal e a captura da B acusa). O navegador avisa esta aba
// quando a outra grava a fila de saída (evento `storage`, com o valor de antes e
// o de depois): o pedido que APARECEU nela com o card ainda aqui é da outra aba.
// Pelo OBJETO do pedido na fila (`WeakSet`), não pela chave: o pedido que sai e
// ENTRA de novo — pela busca, pela fila guardada — é outro objeto e volta a
// contar, porque é nessa entrada que mora a falha que a sentinela procura. E o
// que já estava na fila de saída quando o pedido entrou aqui não é marcado
// nunca. Só em memória, e o que sai da fila some daqui junto.
//
// `chavesDoPouso`: as chaves que o aviso de POUSO da outra aba trouxe (o canal
// entre abas, ver `aoPousarEmOutraAba`, R11-2-01). Ali não há fila de saída a
// comparar — o que pousou lá é decisão, por definição —, e o resto é o MESMO.
// `em`: quando esta aba soube, se não foi agora (o aviso que esperou a conta
// desta aba, R12-2-05).
const decididosPorOutraAbaComCardAqui = new WeakSet();
function anotarDecididosPorOutraAba(ev, chavesDoPouso, em) {
    let novas;
    if (Array.isArray(chavesDoPouso)) {
        novas = new Set(chavesDoPouso.filter((k) => typeof k === 'string' && k));
    } else {
        let antes, depois;
        try {
            antes = JSON.parse((ev && ev.oldValue) || '[]');
            depois = JSON.parse((ev && ev.newValue) || '[]');
        } catch (e) { return; }
        const tinha = new Set((Array.isArray(antes) ? antes : []).map(chaveDoPedido).filter(Boolean));
        novas = new Set((Array.isArray(depois) ? depois : []).map(chaveDoPedido).filter((k) => k && !tinha.has(k)));
    }
    if (!novas.size) return;
    // As CHAVES também, com a hora: o que está FORA da fila agora — a recusa
    // automática no ar, a busca no ar — também não decide de novo (R12-2-01,
    // R12-2-02, ver `lembrarDecididasPorOutraAba`).
    if (typeof lembrarDecididasPorOutraAba === 'function') lembrarDecididasPorOutraAba(novas, em);
    // A fila REAL (`filaReal`), e não a da tela: com o treino aberto, a da tela
    // são os EXEMPLOS (o `updateRequestID` inerte nunca casa) e a real fica
    // guardada nele — junto do que o Waze recusou de vez nesse meio, que volta
    // como card no `sair()` (`devolver`). A decisão da outra aba não era anotada,
    // e de volta à fila a sentinela acusava "voltou como card" e o ✕ aqui anotava
    // um `saida.repetida` sem `outraAba` (auditoria de 2026-10-03, R8-4-02). A
    // régua é a das outras perguntas de identidade (`filaRealComDevolvidos`).
    //
    // E o que está na JANELA DO DESFAZER desta aba (R10-2-02): o gesto daqui
    // ainda não saiu, e a decisão da outra chegou antes à fila de saída — vale a
    // primeira. No fim da janela a decisão daqui é descartada (`enfileirarSaida`
    // a dá por repetida, mesmo depois de a de lá pousar e sair da fila de saída),
    // e desfeita ela volta como card já anotado.
    const pendente = AppState.pendingAction ? AppState.pendingAction.place : null;
    const naJanela = Array.isArray(pendente) ? pendente : pendente ? [pendente] : [];
    for (const p of [...filaRealComDevolvidos(), ...naJanela]) {
        if (p && typeof p === 'object' && novas.has(chaveDoPedido(p))) decididosPorOutraAbaComCardAqui.add(p);
    }
}

// ── O que a OUTRA aba decidiu, pela CHAVE (auditoria da rodada 12) ──────────
// A anotação de cima é por OBJETO, e só alcança o pedido que está na fila (ou
// na janela do Desfazer) quando o aviso chega. Dois caminhos pegavam o pedido
// FORA dela nessa hora, e o decidiam de novo:
//   · a recusa automática NO AR tira os alvos da fila antes de mandar: o pedido
//     que a pessoa acabou de marcar como lido na outra aba saía daqui rejeitado,
//     segundos depois — lido e rejeitado no Waze, e o placar com 8 pra 7 pedidos
//     (R12-2-01, MEDIDO no navegador, nos dois motores);
//   · a BUSCA no ar — a da abertura da segunda aba, a do ↻, a da troca de
//     filtro — começou antes da decisão de lá e voltava depois com o pedido
//     como card, e o ✕ aqui ia ao Waze (R12-2-02, MEDIDO).
// Por isso as chaves ficam aqui, com a hora em que ESTA aba soube (a mais nova,
// quando soube duas vezes: a anotação na fila de saída, e depois o pouso). A
// régua é a do `semOsJaDecididos`: o que foi decidido DEPOIS de a lista ser
// tirada (os alvos da recusa, a página da busca) fica de fora; o de antes, quem
// manda é o Waze, porque a lista que saiu depois da decisão já a reflete — com
// "lidos também", o lido volta como card legítimo, como volta numa aba só. Pra
// busca, a chave vai também pros pousos da página (`pousosDaPagina`), que é o
// que o filtro dela lê. Só em memória, com teto; sai no "Sair" e na troca de
// conta (`esquecerDecididasPorOutraAba`). Os pousos da página seguem a regra
// deles (saem no "Sair"): a troca de conta mantém a fila desta sessão, e o que
// ela decidiu tem que continuar fora da busca que está no ar.
const decididasPorOutraAba = new Map();
const DECIDIDAS_POR_OUTRA_ABA_MAX = 2000;

function lembrarDecididasPorOutraAba(chaves, em) {
    const quando = Number.isFinite(em) ? em : Date.now();
    for (const k of chaves) {
        if (typeof k !== 'string' || !k) continue;
        const antes = decididasPorOutraAba.get(k);
        // Reinserida no FIM: o teto tira do começo, a que não muda há mais tempo.
        decididasPorOutraAba.delete(k);
        decididasPorOutraAba.set(k, antes >= quando ? antes : quando);
        if (!(pousosDaPagina.get(k) >= quando)) pousosDaPagina.set(k, quando);
    }
    while (decididasPorOutraAba.size > DECIDIDAS_POR_OUTRA_ABA_MAX) {
        decididasPorOutraAba.delete(decididasPorOutraAba.keys().next().value);
    }
    // A mesma poda do `registrarPouso`: esta aba pode só RECEBER, sem pousar nada.
    if (pousosDaPagina.size > 500) {
        const agora = Date.now();
        for (const [k, t] of pousosDaPagina) if (agora - t > POUSO_NA_MEMORIA_MS) pousosDaPagina.delete(k);
    }
}

// A OUTRA aba decidiu este pedido em `desde` ou depois?
function decididoNaOutraAbaDepoisDe(p, desde) {
    const k = chaveDoPedido(p);
    const t = k ? decididasPorOutraAba.get(k) : undefined;
    return t !== undefined && t >= desde;
}

// O "Sair" leva também os avisos que esperavam a conta (`comOsAvisos`, R12-2-05);
// a troca de conta não: quem os consome é o `aoConhecerConta` que a revelou.
function esquecerDecididasPorOutraAba({ comOsAvisos = false } = {}) {
    decididasPorOutraAba.clear();
    if (comOsAvisos) avisosDePousoSemConta.length = 0;
}

// O que a OUTRA aba decidiu sai da fila DESTA (auditoria de 2026-10-07,
// R10-2-02). Cada aba tem a sua fila de pedidos, e a decisão de lá não tirava o
// card daqui: decidido de novo, ele contava outra vez no placar, no Histórico e
// na "Mão firme", e dizia "Já tratado por outro editor" sobre a decisão da
// própria pessoa — e, se lá tinha sido ✓, o ✕ daqui era EXECUTADO, porque ler
// não resolve o pedido: o Waze recebia as duas decisões (MEDIDO no navegador,
// q07 da rodada 10). Vale a PRIMEIRA decisão, a regra do `saida.repetida`.
//
// Roda logo depois de `anotarDecididosPorOutraAba`, no MESMO aviso (o evento
// `storage` da fila de saída), e tira da fila REAL (`filaReal`: com o treino
// aberto, a guardada nele, e o que volta no `sair()` dele) os pedidos anotados
// que NÃO estão na tela, com o "Restam" e o card de fundo acompanhando. O da
// tela FICA — trocar o card debaixo do dedo é pior que um gesto a mais —, e o
// gesto nele é descontado e não sai (`gestoNoDecididoPorOutraAba`). O que está
// EM ANDAMENTO aqui (o lote de lidos no ar) é de quem o está mandando, que o
// tira da fila quando a resposta chega. O que a outra aba devolver depois
// (recusado de vez) é dela: volta como card LÁ. Nada aqui grava no aparelho: o
// aviso só chega à outra aba, e responder gravando mandaria outro de volta.
function tirarDaFilaOQueAOutraAbaDecidiu() {
    const salvo = typeof Treino !== 'undefined' && Treino.ativo === true && Treino._salvo ? Treino._salvo : null;
    const naTela = salvo ? salvo.currentPlace : AppState.currentPlace;
    const sai = (p) => !!p && typeof p === 'object' && p !== naTela && decididosPorOutraAbaComCardAqui.has(p)
        && !pedidosEmAndamento.has(chaveDoPedido(p));
    const fila = filaReal();
    const fora = new Set(fila.filter(sai));
    const devolver = salvo && Array.isArray(salvo.devolver) ? salvo.devolver : [];
    const foraDosDevolvidos = new Set(devolver.filter(sai));
    if (!fora.size && !foraDosDevolvidos.size) return;
    if (fora.size) {
        const ficam = fila.filter((p) => !fora.has(p));
        if (salvo) salvo.queue = ficam;
        else AppState.queue = ficam;
        AppState.serverTotal = Math.max(0, AppState.serverTotal - fora.size);
    }
    // O devolvido ainda não voltou a contar no "Restam" (ver `Treino.guardarDevolucao`).
    if (foraDosDevolvidos.size) salvo.devolver = devolver.filter((p) => !foraDosDevolvidos.has(p));
    updatePendingCount();
    // O card de fundo e o "Ver +N" do da frente passam a dizer a fila de agora.
    // Com o treino aberto o card da tela é um exemplo: o `sair()` desenha a fila real.
    if (!salvo) aoMudarAFilaPorBaixo();
}

// O gesto (✕ ↑ ✓, por qualquer caminho) no card NA TELA que a OUTRA aba já
// decidiu (R10-2-02, ver acima): o pedido sai da tela como saiu da fila de lá, o
// "Restam" desce, e nada mais — nem o placar, nem o Histórico, nem a "Mão
// firme", nem o Waze. A pessoa fica sabendo por quê, numa frase. Conta como
// trabalho feito NESTA fila (`tratouNestaFila`): a decisão foi dela, noutra aba,
// e a fila que termina assim é "Tudo limpo!", não "Confira o país e a região".
// Devolve se o gesto era num pedido assim.
function gestoNoDecididoPorOutraAba(tipo) {
    const place = AppState.currentPlace;
    if (!place || typeof place !== 'object' || !decididosPorOutraAbaComCardAqui.has(place)) return false;
    tratouNestaFila = true;
    AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
    // O mesmo fato do diário que a decisão repetida já anota (`enfileirarSaida`):
    // a segunda decisão de um pedido que a outra aba decidiu, descontada. Uma
    // linha por card assim — é raro, e não por swipe.
    dfato('saida.repetida', { tipo, outraAba: true, naTela: true });
    advanceQueue();
    showToast(t('toast.decididoNaOutraAba'), 'info');
    return true;
}

// A decisão da janela do Desfazer que a outra aba tomou ANTES (ver
// `anotarDecididosPorOutraAba`) não saiu nem contou — o executor a descartou,
// três segundos depois do gesto. Diz por quê.
function avisarDecididoNaOutraAba(place) {
    if (place && typeof place === 'object' && decididosPorOutraAbaComCardAqui.has(place)) {
        showToast(t('toast.decididoNaOutraAba'), 'info');
    }
}

// ── O POUSO de uma aba chega às OUTRAS (auditoria de 2026-10-07, R11-2-01) ──
// O aviso de cima é o `storage` da FILA DE SAÍDA, e por ela só passa o que o
// card decide (o ✕/✓, o "Rejeitar os N", a descarga ao fechar). O "Marcar
// todos", a recusa automática e a APROVAÇÃO de foto não escrevem nela, e a outra
// aba seguia com esses pedidos como card: decididos de novo lá, contavam duas
// vezes no placar, no Histórico e na "Mão firme", diziam "Já tratado por outro
// editor" sobre a decisão da própria pessoa e, depois de um "Marcar todos", o ✕
// de lá era EXECUTADO — ler não resolve o pedido (MEDIDO no navegador, n01 a n03
// da rodada 11, nos dois motores).
//
// Toda decisão que pousa passa pelo `registrarPouso`, e é ele que avisa as
// outras abas, por um `BroadcastChannel`: NADA vai pro aparelho (um `setItem` por
// pouso seria um por swipe, e a gravação é síncrona), e por isso não há chave a
// apagar no "Sair". A outra aba roda o MESMO anotar + tirar da fila do aviso da
// fila de saída, com as mesmas regras: o card da TELA fica (o gesto nele é
// descontado e diz por quê; a decisão dela que está na janela do Desfazer não
// sai), o que está EM ANDAMENTO lá é de quem o manda, e com o treino aberto vale
// a fila REAL. Só entre abas da MESMA conta: a mesma sessão, ou a mesma conta
// (a régua do esvaziamento da fila de saída). A aba sem sessão na memória (a
// renovação da queda no meio) decide pela conta que ela confirmou, ou espera a
// conta (R13-2-03, ver `aoPousarSemSessaoNaMemoria`) — e não pergunta ao
// `getSession`, que leria o aparelho (R9-1-03). Sem
// `BroadcastChannel` (iOS < 15.4), segue como antes. A mensagem leva só as
// chaves dos pedidos e a marca da sessão (nunca o token), e não sai do navegador.
const CANAL_DOS_POUSOS = 'waze-places-pousos';
let canalDosPousos = null;

function abrirCanalDosPousos() {
    if (canalDosPousos || typeof BroadcastChannel !== 'function') return;
    try { canalDosPousos = new BroadcastChannel(CANAL_DOS_POUSOS); } catch (e) { canalDosPousos = null; return; }
    canalDosPousos.onmessage = (ev) => aoPousarEmOutraAba(ev && ev.data);
}

// QUEM decide, tirado no GESTO: a marca da sessão (nunca o token) e a conta. A
// decisão que pousa com a sessão já caída — a queda chegou com o "Marcar todos"
// ou a aprovação de foto no ar, e a renovação ainda não respondeu — não tem
// sessão na memória pra dizer de quem é, e o aviso não saía: a outra aba, com a
// mesma sessão antiga, seguia com os pedidos como card, e o ✕ de lá ia ao Waze
// (R12-2-04, MEDIDO no navegador com a queda forçada). Quem pousa assim passa
// esta marca, tirada quando a decisão saiu (`registrarPouso(…, quem)`). Sem
// sessão na memória no gesto, `null`.
function quemDecideAgora() {
    // A sessão DESTA aba, pela régua única (`marcaDestaAba`, R12-1-03).
    const s = marcaDestaAba();
    if (!s) return null;
    return { s, conta: contaAgora() };
}

// O que acabou de pousar NESTA aba, com a marca de quem decidiu: a do GESTO,
// quando quem pousa a trouxe (`quem`, ver `quemDecideAgora`), senão a de agora.
// O canal não entrega a mensagem ao objeto que a mandou: esta aba não recebe o
// próprio aviso.
function avisarOutrasAbasDoPouso(chaves, quem) {
    if (!canalDosPousos || !Array.isArray(chaves) || !chaves.length) return;
    let de = quem && typeof quem.s === 'string' && quem.s ? quem : null;
    if (!de) {
        // A de agora — e sem sessão na memória, nada: não pergunta ao
        // `getSession`, que leria o aparelho (R9-1-03).
        if (!API.temSessaoNaMemoria()) return;
        de = { s: marcaDaSessao(API.getSession()), conta: contaAgora() };
    }
    try {
        canalDosPousos.postMessage({ v: 1, chaves, conta: de.conta ?? null, s: de.s });
    } catch (e) { /* canal fechado: segue como antes */ }
}

// O pouso de OUTRA aba. Nada aqui grava no aparelho nem avisa de volta.
function aoPousarEmOutraAba(aviso) {
    if (!aviso || aviso.v !== 1 || !Array.isArray(aviso.chaves) || !aviso.chaves.length) return;
    // SEM sessão na memória (a renovação da queda no meio) não é "ignore" (R13-2-03,
    // ver a função).
    if (!API.temSessaoNaMemoria()) { aoPousarSemSessaoNaMemoria(aviso); return; }
    if (!(aviso.s && aviso.s === marcaDaSessao(API.getSession()))) {
        if (!aviso.conta) return;
        const agora = contaAgora();
        // A conta DESTA aba ainda não se sabe (o perfil não chegou; a conta em
        // dúvida, R6-1-04): o aviso ESPERA por ela (R12-2-05, ver a função).
        if (!agora) { guardarAvisoSemConta(aviso); return; }
        if (String(aviso.conta) !== agora) return;
    }
    aplicarPousoDeOutraAba(aviso.chaves);
}

// O MESMO anotar + tirar da fila do aviso da fila de saída. `em`: quando esta aba
// soube, se não foi agora (o aviso que esperou a conta).
function aplicarPousoDeOutraAba(chaves, em) {
    anotarDecididosPorOutraAba(null, chaves, em);
    tirarDaFilaOQueAOutraAbaDecidiu();
}

// O aviso que chega com esta aba SEM sessão na memória. Era jogado fora — e a
// renovação da queda deixa a memória vazia com a FILA na tela (`manterFila`): o
// que a outra aba decidiu por um caminho que só passa pelo canal (o "Marcar
// todos", a recusa automática, a aprovação de foto) seguia aqui como card, e,
// renovada a sessão com a MESMA conta, o ✕ ia ao Waze como segunda decisão —
// lido e rejeitado (auditoria da rodada 13, R13-2-03 = R13-1-01, MEDIDO no
// navegador, nos dois motores). Era o espelho do R12-2-04: lá quem estava sem
// sessão era a aba que manda.
//
// A régua é a conta de QUEM deixou a fila aqui: a que esta aba confirmou
// (`contaConfirmadaNestaAba`), que fica na queda e sai no "Sair" e na troca de
// conta. A mesma conta do aviso: vale agora, como valeria com a sessão (a
// renovação com OUTRA conta refaz a fila de qualquer jeito, em
// `esquecerOutraConta`). Outra conta: nada. Sem conta confirmada (a sessão caiu
// antes de o perfil chegar), o aviso ESPERA a conta desta aba, como o da conta em
// dúvida (R12-2-05, `guardarAvisoSemConta`): o `aoConhecerConta` da renovação o
// aplica — mas só com o que a sessão que caiu deixou aqui (`guardaASessaoQueCaiu`,
// a régua que faz o "Sair" da outra aba alcançar esta e levar os avisos): a aba
// que nunca entrou, ou que saiu, não tem fila a proteger e não guarda id de pedido
// de terceiro na memória. Nunca pelo `getSession`, que com a memória vazia ADOTA a
// sessão guardada no aparelho (R9-1-03).
function aoPousarSemSessaoNaMemoria(aviso) {
    if (!aviso.conta) return;
    const aqui = contaConfirmadaNestaAba;
    if (aqui) {
        if (String(aviso.conta) === aqui.id) aplicarPousoDeOutraAba(aviso.chaves);
        return;
    }
    if (guardaASessaoQueCaiu()) guardarAvisoSemConta(aviso);
}

// Os avisos de pouso que chegaram com a conta DESTA aba desconhecida — o perfil
// falhou, ou não chegou ainda, e a outra aba tem outra sessão (a conta em dúvida
// da outra aba que entrou de novo, R6-1-04). Não dava pra saber se eram da mesma
// conta, e eles eram jogados fora: quando o perfil chegava e dizia que era a
// mesma, os pedidos decididos lá seguiam como card aqui, e o ✕ ia ao Waze
// (R12-2-05, MEDIDO no navegador). Esperam aqui, só em memória e com teto (os
// mais antigos saem primeiro), até o `aoConhecerConta`: a mesma conta, valem como
// se tivessem chegado agora (com a hora em que chegaram); outra, saem sem efeito.
// O "Sair" os leva (`esquecerDecididasPorOutraAba`).
const avisosDePousoSemConta = [];
const AVISOS_DE_POUSO_SEM_CONTA_MAX = 50;

function guardarAvisoSemConta(aviso) {
    const chaves = aviso.chaves.filter((k) => typeof k === 'string' && k);
    if (!chaves.length) return;
    avisosDePousoSemConta.push({ chaves, conta: String(aviso.conta), em: Date.now() });
    while (avisosDePousoSemConta.length > AVISOS_DE_POUSO_SEM_CONTA_MAX) avisosDePousoSemConta.shift();
}

// A conta desta aba ficou conhecida (`aoConhecerConta`): todos os avisos que
// esperavam saem daqui — os desta conta valem, os de outra não.
function aplicarAvisosQueEsperavamAConta(id) {
    if (!avisosDePousoSemConta.length) return;
    const esperando = avisosDePousoSemConta.splice(0);
    for (const a of esperando) if (a.conta === String(id)) aplicarPousoDeOutraAba(a.chaves, a.em);
}

// `env(safe-area-inset-*)` não é legível por API. O jeito é pedir ao próprio
// navegador: um elemento fora da tela cujo padding SÃO os env(), e então
// `getComputedStyle` devolve os px resolvidos.
function medirSafeArea() {
    let d = null;
    try {
        d = document.createElement('div');
        d.style.cssText = 'position:fixed;left:-9999px;top:0;width:0;height:0;'
            + 'padding-top:env(safe-area-inset-top);padding-right:env(safe-area-inset-right);'
            + 'padding-bottom:env(safe-area-inset-bottom);padding-left:env(safe-area-inset-left);';
        document.body.appendChild(d);
        const c = getComputedStyle(d);
        return { top: parseFloat(c.paddingTop) || 0, right: parseFloat(c.paddingRight) || 0,
                 bottom: parseFloat(c.paddingBottom) || 0, left: parseFloat(c.paddingLeft) || 0 };
    } catch (e) {
        return null;
    } finally {
        if (d && d.parentNode) d.parentNode.removeChild(d);
    }
}

// A tabela que eu meço À MÃO em toda investigação de layout. `rect` diz onde a
// coisa FICOU (o que a tela deu), e `scrollHeight/clientHeight` + o `overflow-y`
// COMPUTADO dizem se ela rola ou se está cortada — que são coisas diferentes e
// `scrollHeight > clientHeight` é verdadeiro nas DUAS (gotcha #29).
const DIAG_ALVOS = ['.place-card:not(.card-fundo)', '.card-fundo', '.card-content', '.card-changes', '.card-flag-comment',
                    // O mapa entrou em v2026.09.21-05, e a razão é uma falha do
                    // próprio instrumento: o owner relatou o mapa do card de
                    // fundo mudando de tamanho ao virar frente, e o diagnóstico
                    // dele NÃO tinha como mostrar isso. A geometria já media os
                    // dois cards lado a lado, mas nenhuma coluna distinguia o
                    // caso — as CAIXAS sempre bateram; o que divergia era o
                    // ENQUADRAMENTO (`data-mapa-w/h`), que só existia no `dom`
                    // cru de 140 KB. Dado que só está no HTML é dado que
                    // ninguém procura sem já saber a resposta.
                    '.card-map:not(.hidden)',
                    // O "N esperando envio" entrou na rodada 11 (R11-4-04), e pelo
                    // mesmo motivo do mapa: os quatro defeitos que o esconderam (o
                    // FAB em cima, R9-4-05; o cabeçalho do iPhone instalado,
                    // R10-4-02; o FAB atravessando a tela, R10-4-05; a outra aba,
                    // R11-4-03) foram achados por auditoria, nenhum por relato — o
                    // único sinal de decisão esperando sinal só existia no `dom`.
                    '#cardStack', '#placar', '#inFlightIndicator', 'header', '.modal-root:not(.hidden) > div',
                    '#imageLightbox:not(.hidden)', '#devFab:not(.hidden)',
                    '.card-btn-reject', '.card-btn-skip', '.card-btn-read'];
// Modal e lightbox ABERTOS. Camada aberta cobre o que está atrás — é a função
// dela —, e sem saber disso o hit-test acusa o normal como defeito.
function diagCamadasAbertas() {
    const ids = [...(typeof MODAL_IDS !== 'undefined' ? MODAL_IDS : []), 'imageLightbox', 'mapaLightbox'];
    return ids.map((id) => document.getElementById(id))
        .filter((e) => e && !e.classList.contains('hidden') && getComputedStyle(e).display !== 'none');
}

// As duas comparações de TAMANHO das sentinelas usam a caixa de LAYOUT, nunca o
// `getBoundingClientRect`: esse inclui a transformação, e no arraste o card anda,
// GIRA (caixa maior) e, saindo, encolhe. MEDIDO pela auditoria de 2026-09-25: toda
// captura `auto:arraste` com o mapa na frente trazia "mapa fora da caixa", e a
// saída pra cima, "alvo pequeno" no ↑ de 48px. Relatório antigo não tem `cw`/`ow`
// e cai no `rect`, como antes.
function diagMapaForaDaCaixa(g) {
    if (!g || !g.mapaPara) return false;
    const [mw, mh] = String(g.mapaPara).split('x').map(Number);
    const w = Number.isFinite(g.cw) ? g.cw : g.w;
    const h = Number.isFinite(g.ch) ? g.ch : g.h;
    // Tolerância de 1px: `clientWidth` é inteiro arredondado (gotcha #34).
    return Math.abs(mw - w) > 1 || Math.abs(mh - h) > 1;
}
function diagAlvoPequeno(g) {
    const w = Number.isFinite(g.ow) ? g.ow : g.w;
    const h = Number.isFinite(g.oh) ? g.oh : g.h;
    return w < 44 || h < 44;
}

function diagGeometria() {
    const fora = [];
    const camadas = diagCamadasAbertas();
    for (const sel of DIAG_ALVOS) {
        let els = [];
        try { els = [...document.querySelectorAll(sel)]; } catch (e) { continue; }
        for (const e of els.slice(0, 3)) {
            const r = e.getBoundingClientRect();
            if (r.width === 0 && r.height === 0) continue;
            const cs = getComputedStyle(e);
            fora.push({
                sel,
                x: Math.round(r.left), y: Math.round(r.top),
                w: Math.round(r.width), h: Math.round(r.height),
                scrollH: e.scrollHeight, clientH: e.clientHeight,
                overflowY: cs.overflowY,
                display: cs.display,
                // Quem RECEBE o dedo no centro. É o gotcha #26 — os dois
                // retângulos existem e só o hit-test diz quem intercepta —, e
                // ele já reincidiu três vezes neste projeto.
                noCentro: diagQuemEstaNoCentro(e, r),
                // Quem recebe é o AVISO passageiro (o toast e o Desfazer, no
                // `#notifyStack`)? Ver a sentinela do toque.
                ...(diagCentroEmAvisoPassageiro(e, r) ? { sobAviso: true } : {}),
                // O ENQUADRAMENTO do mapa: pra que tamanho ele foi desenhado.
                // Sem isto, frente e fundo saem idênticos no relatório mesmo
                // quando um deles está desenhado pra outra caixa.
                ...(e.dataset && e.dataset.mapaW
                    ? { mapaPara: e.dataset.mapaW + 'x' + e.dataset.mapaH,
                        // A caixa SEM transformação, que é a que o `renderMapa`
                        // mediu: no arraste o card anda e GIRA, e o `rect` acima
                        // é a caixa girada (maior). Ver `diagMapaForaDaCaixa`.
                        cw: e.clientWidth, ch: e.clientHeight } : {}),
                // O tamanho de LAYOUT (border-box, sem transformação) — é ele o
                // alvo de toque. O `rect` encolhe na animação de saída do card e
                // acusava "alvo pequeno" num botão de 48px.
                ...(typeof e.offsetWidth === 'number' ? { ow: e.offsetWidth, oh: e.offsetHeight } : {}),
                // Quantos tiles o desenho pediu e quantos FALHARAM. O tile que
                // falha sai da tela (ícone quebrado não informa nada), então
                // sem esta contagem "mapa com buraco" não aparece no arquivo.
                ...(e.dataset && e.dataset.tilesPedidos
                    ? { tiles: { pedidos: +e.dataset.tilesPedidos, falharam: +(e.dataset.tilesFalharam || 0) } } : {}),
                // Do card de FUNDO? Ele é coberto pelo da frente POR
                // CONSTRUÇÃO (`inert` + `pointer-events:none`), então o
                // hit-test nele acusa o normal como defeito — ver a sentinela
                // do toque.
                noFundo: !!(e.closest && e.closest('.card-fundo')),
                // DESABILITADO de propósito (a janela do Desfazer, o card sem
                // foto): o toque não é pra chegar, e o banner do Desfazer por
                // cima dele é o desenho — ver a sentinela do toque.
                ...(e.disabled ? { desab: true } : {}),
                // DENTRO de uma camada aberta, ou atrás dela? Quem está atrás é
                // coberto por construção, e alertar nisso é ruído.
                naCamada: camadas.some((c) => c.contains(e)),
                camadaAberta: camadas.length > 0,
                // NÚMERO a não cobrir (`.nao-cobrir`: o placar, e o "N esperando
                // envio" com decisão esperando): o que está por cima dele — ver a
                // sentinela `indicadorEscondido`.
                ...(e.classList && e.classList.contains('nao-cobrir') ? diagNumeroACobrir(e, r) : {}),
            });
        }
    }
    return fora;
}

// O que está por cima de um número a não cobrir (`.nao-cobrir`), no centro dele:
// um aviso PASSAGEIRO do topo (`#bannerStack`, que some sozinho — o do rodapé já é
// o `sobAviso`) ou o FAB do modo dev — e, se o FAB, se foi o EDITOR que o arrastou
// pra lá (`devFabFixado`: aí o canto é escolha dele, não do app), ou se o app
// ADIOU a troca de canto até o fim de um gesto no card (`fabEsperaOGesto`, a
// decisão do R10-4-05: o card deslocado mostra um canto que, parado, ele cobre).
// O "N esperando envio" que nasce NO MEIO do arraste — a decisão anterior que
// falha por rede, a marca da outra aba que vence — fica debaixo do FAB até o
// dedo soltar, por desenho; a captura automática do mesmo arraste o acusava
// como escondido (auditoria da rodada 12, R12-4-04, MEDIDO nos dois motores: o
// alerta na captura, e o FAB fora de cima dele logo depois do gesto).
function diagNumeroACobrir(el, r) {
    const fora = { naoCobrir: true };
    try {
        const alvo = document.elementFromPoint(Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2));
        if (alvo && alvo !== el && !el.contains(alvo) && alvo.closest) {
            if (alvo.closest('#bannerStack')) fora.sobBanner = true;
            if (alvo.closest('#devFab')) fora.sobFab = devFabFixado ? 'fixado' : fabEsperaOGesto ? 'gesto' : true;
        }
    } catch (e) { /* sonda nunca derruba o diagnóstico */ }
    return fora;
}

// O toast (snackbar do M3) e o Desfazer moram no `#notifyStack`, no rodapé, em
// z-70: nas telas baixas eles passam por cima dos botões do card — é o lugar
// deles, e somem sozinhos em segundos. Toda captura até 4 s depois de um toast
// acusava "toqueInterceptado" nos três botões (auditoria de 2026-09-26, D3).
function diagCentroEmAvisoPassageiro(el, r) {
    try {
        const alvo = document.elementFromPoint(Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2));
        return !!(alvo && alvo !== el && !el.contains(alvo) && alvo.closest && alvo.closest('#notifyStack'));
    } catch (e) { return false; }
}

function diagQuemEstaNoCentro(el, r) {
    try {
        const alvo = document.elementFromPoint(Math.round(r.left + r.width / 2),
                                               Math.round(r.top + r.height / 2));
        if (!alvo) return 'nada';
        if (alvo === el || el.contains(alvo)) return 'ele mesmo';
        // `className` de elemento SVG é um SVGAnimatedString, não uma string:
        // `String(...)` devolvia `[object SVGAnimatedString]` e o rótulo saía
        // como `path.[object` — inútil justamente no alerta cujo produto é
        // dizer QUEM interceptou. Os ícones do card são SVG, então isso valia
        // pra todo alerta de toque que já saiu.
        const cls = alvo.getAttribute ? (alvo.getAttribute('class') || '') : '';
        return (alvo.id ? '#' + alvo.id : alvo.tagName + (cls ? '.' + cls.split(' ')[0] : '')).slice(0, 60);
    } catch (e) { return null; }
}

// ── SENTINELAS: o arquivo não me dá material, ele DIZ o que está errado ────
// Cada uma nasce de um defeito que já chegou na tela de um editor. Elas rodam
// no APARELHO dele, onde eu não chego — e uma linha no topo do relatório vale
// mais que 1 MB pra vasculhar.
//
// Regra pra entrar aqui: só invariante que o app garante e que, quebrada,
// significa defeito — nunca "achei estranho". Falso positivo aqui treina a
// ignorar a seção inteira, que é como ela deixa de servir.
// ── O RETRATO DA SESSÃO, com a conta JÁ FEITA ────────────────────────────
//
// Esta seção existe porque a pergunta do relato — *"a sessão dura 2 dias ou 7?"*
// — hoje depende da memória de quem relata, e memória de duração é justamente
// o que ninguém tem. Ela devolve os INTERVALOS medidos entre entrar e cair.
//
// E entrega CONCLUÍDO em vez de dados crus de propósito: cruzar carimbos à mão
// num arquivo de 500 KB é o trabalho que faz a seção não ser lida.
function diagSessao() {
    const fora = { nascimento: null, idadeDoArmazenamentoH: null, diario: [], ciclos: [], erro: null };
    try {
        const nasc = Number(safeLS.get(NASCIMENTO_KEY)) || null;
        fora.nascimento = nasc ? new Date(nasc).toISOString() : null;
        fora.idadeDoArmazenamentoH = nasc ? Math.round((Date.now() - nasc) / 360000) / 10 : null;
        const anel = lerDiarioDeSessoes();
        fora.diario = anel.map((l) => ({ ...l, quando: new Date(l.t).toISOString() }));
        // Um CICLO é entrar e sair/cair. É ele que responde a pergunta, e a
        // duração vai em horas porque "2 dias" e "7 dias" se distinguem lá.
        let abriu = null;
        for (const l of anel) {
            if (l.e === 'token+' || l.e === 'jaAtiva') { abriu = l; continue; }
            if ((l.e === 'token-' || l.e === 'caiu' || l.e === 'saiu') && abriu) {
                fora.ciclos.push({
                    de: new Date(abriu.t).toISOString(),
                    ate: new Date(l.t).toISOString(),
                    durouH: Math.round((l.t - abriu.t) / 360000) / 10,
                    // `jaAtiva` significa que a sessão já existia quando o
                    // registro começou: a duração é um PISO, não a medida.
                    inicioConhecido: abriu.e !== 'jaAtiva',
                    fim: l.e, motivo: l.motivo || null,
                });
                abriu = null;
            }
        }
        if (abriu) {
            fora.ciclos.push({ de: new Date(abriu.t).toISOString(), ate: null,
                               durouH: Math.round((Date.now() - abriu.t) / 360000) / 10,
                               inicioConhecido: abriu.e !== 'jaAtiva', fim: 'em curso' });
        }
        // Só entra na estatística o ciclo com as DUAS pontas medidas. Um piso
        // misturado com medidas puxaria a mediana pra baixo e ela passaria a
        // afirmar menos tempo do que houve — erro na direção que confirma o
        // relato, que é a pior direção possível pra um instrumento.
        const fechados = fora.ciclos.filter((c) => (c.fim === 'caiu' || c.fim === 'token-') && c.inicioConhecido);
        fora.pisos = fora.ciclos.filter((c) => c.inicioConhecido === false).length;
        if (fechados.length) {
            const d = fechados.map((c) => c.durouH).sort((a, b) => a - b);
            fora.duracaoH = { menor: d[0], mediana: d[Math.floor(d.length / 2)], maior: d[d.length - 1], n: d.length };
        }
    } catch (e) { fora.erro = String((e && e.message) || e); }
    return fora;
}

// ── O AMBIENTE QUE DECIDE SE O ARMAZENAMENTO SOBREVIVE ───────────────────
//
// O relato ("preciso puxar os cookies toda semana") tem um candidato de
// PLATAFORMA que não é defeito nosso: o WebKit apaga TODO o storage
// script-writable depois de "seven days of Safari use without user interaction
// on the site" (webkit.org). E a isenção é exatamente o que o app pede:
// "web applications added to the home screen ... have their own counter".
//
// Ou seja: quem usa no Safari SEM instalar perde tudo em 7 dias, e o sintoma é
// idêntico a "a sessão expirou". Isto responde, no arquivo, de que lado está.
function diagArmazenamentoDuravel() {
    const f = { modoExibicao: null, iosStandalone: null, engine: null, navegador: null,
                riscoDeApagamento: null, pedimosPersistencia: false };
    try {
        for (const m of ['fullscreen', 'standalone', 'minimal-ui', 'browser']) {
            if (matchMedia('(display-mode: ' + m + ')').matches) { f.modoExibicao = m; break; }
        }
        f.iosStandalone = navigator.standalone === true;
        const ua = navigator.userAgent || '';
        // Heurística DECLARADA como tal: UA mente, e o que importa aqui é o
        // motor, não a marca. No iOS todo navegador é WebKit — Chrome incluso —,
        // então "é Chrome" não exclui a regra dos 7 dias.
        const iOS = /iPhone|iPad|iPod/.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
        f.engine = iOS || (/Safari/.test(ua) && !/Chrome|Chromium|Edg/.test(ua)) ? 'WebKit'
                 : /Firefox|Gecko\//.test(ua) ? 'Gecko' : 'Blink';
        const mb = ua.match(/(Firefox|Edg|OPR|Chrome|CriOS|FxiOS|Version)\/([\d.]+)/);
        f.navegador = mb ? mb[1] + ' ' + mb[2] : null;
        f.iOS = iOS;
        const instalada = f.modoExibicao === 'standalone' || f.modoExibicao === 'fullscreen' || f.iosStandalone;
        f.instalada = instalada;
        // A conclusão, escrita: é isto que eu leio primeiro.
        f.riscoDeApagamento = f.engine === 'WebKit' && !instalada
            ? 'ALTO — WebKit fora da tela inicial: o navegador apaga todo o armazenamento após 7 dias sem abrir o site'
            : f.engine === 'WebKit' ? 'baixo — instalada na tela inicial, que o WebKit isenta do apagamento de 7 dias'
            : 'baixo — motor sem apagamento por inatividade (pode haver limpeza por pressão de espaço)';
    } catch (e) { f.erro = String((e && e.message) || e); }
    return f;
}

function diagSentinelas(comp) {
    const alertas = [];
    const diga = (chave, msg, dado) => alertas.push({ chave, msg, ...(dado || {}) });
    try {
        // 1. O bug de v2026.09.09-02, em uma linha.
        // UMA condição, e o `!== true` é deliberado: cobre nada focado, focado
        // em algo que não abre teclado, e DESCONHECIDO. A primeira versão pedia
        // `=== false` e ficava MUDA num build onde `campoDeTextoFocado` não
        // existe — que é exatamente o build antigo em que o defeito vive. A
        // sentinela não pode depender de o conserto já estar presente.
        const kb = parseFloat((comp.varsCss || {})['--kb-inset']) || 0;
        if (kb > 0 && !(comp.foco && comp.foco.abreTeclado === true)) {
            diga('kbInsetSemFoco',
                'há inset de teclado sem campo de texto focado — os modais achatam',
                { kbInset: kb, foco: (comp.foco && comp.foco.tag) || 'nada' });
        }
        // 2. O TEMA do app contra o que o NAVEGADOR pinta em volta dele: o fundo
        //    sob o app e a barra do sistema. O `applyTheme` (e o script do tema,
        //    na carga) põe `dark` OU `tema-claro` e todas as metas `theme-color`
        //    na cor do tema. Duas contradições QUEBRAM a tela:
        //    · sistema escuro, app claro SEM `tema-claro`: a regra
        //      `html:not(.tema-claro)` do styles.css, que vive dentro de
        //      `@media (prefers-color-scheme: dark)`, pinta o fundo escuro por
        //      baixo do app claro (num sistema claro ela nem se aplica — daí o
        //      escopo, senão a sentinela dispararia à toa);
        //    · a barra do sistema (a meta que VALE) escura com o app claro, ou o
        //      contrário.
        //    Era o que o botão do tema deixava até recarregar (auditoria de
        //    2026-09-29, A8, medido). A versão anterior alertava `tema-claro` +
        //    `dark` juntos, e esse estado é INERTE (o `dark` do body cobre o
        //    fundo): alertava o que não quebra e calava o que quebra.
        const cl = (comp.tema && comp.tema.htmlClasse) || '';
        const classes = cl.split(/\s+/);
        const appEscuro = classes.includes('dark');
        const sistemaEscuro = !!(comp.media && comp.media['(prefers-color-scheme: dark)']);
        const barra = (comp.tema && comp.tema.barra) || null;
        const hex = /^#([0-9a-f]{6})$/i.exec(String(barra || '').trim());
        // Relatório antigo (sem a barra) ou cor noutro formato: não julga.
        const barraEscura = hex
            ? (parseInt(hex[1].slice(0, 2), 16) * 299 + parseInt(hex[1].slice(2, 4), 16) * 587
               + parseInt(hex[1].slice(4, 6), 16) * 114) / 1000 < 128
            : null;
        const fundoErrado = sistemaEscuro && !appEscuro && !classes.includes('tema-claro');
        const barraErrada = barraEscura !== null && barraEscura !== appEscuro;
        if (fundoErrado || barraErrada) {
            diga('temaContraditorio',
                [fundoErrado ? 'app claro sem `tema-claro` num sistema escuro — o fundo sob o app fica escuro' : '',
                 barraErrada ? `a barra do sistema (${barra}) não acompanha o tema do app` : '']
                    .filter(Boolean).join('; '),
                { classe: cl, barra });
        }
        // 4. O armazenamento não está guardando NADA — e o app parece boa.
        //    Invariante dura: depois de entrar, o token ESTÁ no localStorage.
        //    Se há sessão ativa e ele não está lá, a sessão morre ao fechar a
        //    aba, toda vez, e nenhum outro campo deste arquivo diz isso.
        try {
            if (AppState.authenticated && !safeLS.get('waze_session_token')) {
                diga('tokenNaoPersiste',
                    'há sessão ativa mas o token NÃO está no armazenamento — ele morre ao fechar a aba '
                    + '(navegação privada, cookies bloqueados ou armazenamento cheio)');
            }
        } catch (e) { /* sonda nunca derruba o diagnóstico */ }
        // 5. O ambiente apaga o armazenamento antes do prazo que o app promete.
        //    NÃO é "achei estranho": é contradição entre o que o app garante
        //    (sessão de semanas, com janela deslizante) e o que ESTE ambiente
        //    faz — o WebKit apaga todo o storage após 7 dias sem interação, e
        //    isenta quem está na tela inicial. Escopo apertado de propósito:
        //    só com sessão ativa e fora da tela inicial, senão vira aviso
        //    genérico de plataforma em todo diagnóstico de iPhone.
        try {
            const dur = diagArmazenamentoDuravel();
            if (AppState.authenticated && dur.engine === 'WebKit' && !dur.instalada) {
                diga('apagamentoPorInatividade',
                    'WebKit fora da tela inicial: o navegador apaga TODO o armazenamento após 7 dias '
                    + 'sem abrir o site — a sessão vai sumir sozinha, e instalar na tela inicial isenta',
                    { modoExibicao: dur.modoExibicao, navegador: dur.navegador });
            }
        } catch (e) { /* idem */ }
        // 6. A sessão está caindo sozinha, e isso tem NÚMERO agora.
        //    Dois ciclos ou mais, cada um abaixo de 72 h, sem ter sido o editor
        //    que saiu. Um só poderia ser troca de aparelho ou logout no WME;
        //    dois é padrão. É o relato virando evidência sem depender da
        //    memória de quem relata.
        try {
            // `inicioConhecido`: o ciclo que começou num `jaAtiva` é um PISO (a
            // sessão já existia antes do diário), e a estatística já o deixa de
            // fora. Contá-lo aqui acusava "caiu cedo" em todo testador que
            // estava logado no dia do deploy — o erro na direção que CONFIRMA
            // o relato, a pior que um instrumento pode ter.
            const curtos = (diagSessao().ciclos || [])
                .filter((c) => c.fim === 'caiu' && c.inicioConhecido !== false && c.durouH != null && c.durouH < 72);
            if (curtos.length >= 2) {
                diga('sessaoCaiCedo',
                    `a sessão caiu ${curtos.length}× em menos de 72 h — o prazo do Waze é de ~28 dias`,
                    { duracoesH: curtos.map((c) => c.durouH), motivos: [...new Set(curtos.map((c) => c.motivo))] });
            }
        } catch (e) { /* idem */ }
        // 3. Gotcha #26, três reincidências: quem recebe o dedo não é o alvo.
        //    **Só vale pro controle que NÃO está atrás de camada aberta.** Modal
        //    cobrir o card é a função do modal, e sem esta condição a sentinela
        //    acusa os três botões toda vez que alguém abre os Filtros — foi o
        //    que ela fez no PRIMEIRO diagnóstico real que chegou (3 alertas, os
        //    3 falsos). O `#devFab` NÃO precisa de exceção: ele é `z-[68]`,
        //    acima dos modais, e o mesmo diagnóstico mostra `noCentro: "ele
        //    mesmo"` com o modal aberto — se um dia ele for coberto, é defeito
        //    de verdade e o smoke do FAB mede isso em 5 camadas por hit-test.
        for (const g of comp.geometria || []) {
            if (g.noCentro && g.noCentro !== 'ele mesmo' && g.noCentro !== 'nada'
                && /card-btn|devFab/.test(g.sel)
                && !(g.camadaAberta && !g.naCamada)
                // REINCIDIU pela PILHA (v2026.09.21-05): o card de fundo tem os
                // mesmos três botões, e eles são cobertos pelo da frente — que
                // é a função da pilha. MEDIDO com controle: 3 alertas com dois
                // pedidos na fila, ZERO com um. Ou seja, desde v2026.09.19-01
                // TODO diagnóstico com fila cheia trazia três alertas falsos,
                // na seção que se lê primeiro. Mesma sentinela, mesma
                // quantidade, causa nova — e a regra é a mesma do modal aberto.
                && !g.noFundo
                // E o controle DESABILITADO: na janela do Desfazer os três
                // botões ficam travados de propósito, e o banner do Desfazer os
                // cobre em boa parte dos aparelhos — toda captura feita nessa
                // janela acusava "o dedo não chega nele" num botão que não é pra
                // receber o dedo (auditoria de 2026-09-25).
                && !g.desab
                // E o AVISO PASSAGEIRO por cima (o toast e o Desfazer, no
                // `#notifyStack`): é o lugar deles nas telas baixas, e somem em
                // segundos — cada captura logo depois de um toast trazia três
                // alertas falsos (auditoria de 2026-09-26). Elemento de VERDADE
                // por cima continua acusando.
                && !g.sobAviso) {
                diga('toqueInterceptado',
                    'algo está por cima de um controle: o dedo não chega nele',
                    { alvo: g.sel, recebe: g.noCentro });
            }
            // 4. Alvo de toque abaixo da régua M3/HIG.
            if (/card-btn|devFab/.test(g.sel) && diagAlvoPequeno(g)) {
                diga('alvoPequeno', 'alvo de toque abaixo de 44px',
                    { alvo: g.sel, w: g.ow ?? g.w, h: g.oh ?? g.h });
            }
        }
        // 5. O mapa desenhado pra uma caixa que não é a dele.
        //
        // INVARIANTE que o app garante: `renderMapa` enumera os tiles pra
        // cobrir exatamente `larguraPx × alturaPx`, então o enquadramento tem
        // que ser o tamanho da caixa. Quando não é, sobra faixa sem tile (caixa
        // maior que o enquadramento) ou o zoom foi escolhido pra outra
        // proporção (caixa menor) — os dois visíveis, nenhum detectável pelo
        // resto deste arquivo.
        //
        // Nasceu de uma falha do INSTRUMENTO: o owner relatou o mapa do card de
        // fundo mudando de tamanho ao virar frente, e o diagnóstico dele não
        // tinha como mostrar. A geometria já media os dois cards, mas as CAIXAS
        // sempre batem — o que diverge é o enquadramento.
        //
        // Tolerância de 1px porque `clientWidth` é inteiro arredondado
        // (gotcha #34) e o enquadramento guarda o valor lido na hora.
        for (const g of comp.geometria || []) {
            if (!g.mapaPara || !/card-map/.test(g.sel)) continue;
            if (diagMapaForaDaCaixa(g)) {
                diga('mapaForaDaCaixa',
                    'o mini-mapa foi desenhado pra um tamanho que não é o da caixa dele — '
                    + 'sobra faixa sem tile, ou o zoom é de outra proporção',
                    { onde: g.noFundo ? 'card de fundo' : 'card da frente',
                      caixa: (g.cw ?? g.w) + 'x' + (g.ch ?? g.h), desenhadoPara: g.mapaPara });
            }
        }
        // 7. "A foto precisa de sinal" por cima de uma foto CARREGADA.
        //
        // INVARIANTE desde v2026.09.22-02: o aviso nasce do `onerror` da foto
        // em decisão, ou seja só existe DEPOIS de ela falhar — e foto que
        // falhou tem `naturalWidth` zero. Aviso com a foto carregada embaixo é
        // o defeito do relato de 2026-09-22 (o aviso posto por suposição
        // escondia a foto guardada), e aconteceu em 4 das 6 capturas dele sem
        // nenhuma sentinela dizer nada. Só o card da FRENTE: o de fundo é
        // clone e não tem ouvinte nenhum.
        const fd = comp.fotoDaFrente;
        if (fd && fd.aviso && fd.carregada) {
            diga('fotoEscondidaComAviso',
                'o card diz "a foto precisa de sinal" mas a foto em decisão CARREGOU — o aviso '
                + 'está escondendo uma foto que o aparelho tem', { foto: fd.src });
        }
        // 8. Pedaço de mapa GUARDADO que falhou na tela.
        //
        // INVARIANTE: com o service worker no comando, tile que está no cache
        // de tiles é servido do cache — com ou sem rede. O anel só recebe a
        // falha nas condições em que isso vale (ver `registrarFalhaDeTile`), e
        // é o defeito do mapa do relato de 2026-09-22 (o worker acordava sem
        // saber dos tiles), que o arquivo dele não tinha como mostrar: o app
        // tira da tela o tile que falha, e a prova ia junto.
        // Só as falhas desde a captura (ou o relatório) ANTERIOR, e com a HORA:
        // sem ela, a falha de minutos atrás lia como se estivesse na tela agora.
        const tf = comp.tilesGuardadosQueFalharam || [];
        if (tf.length) {
            diga('tileGuardadoFalhou',
                'pedaço de mapa GUARDADO no aparelho falhou na tela — o service worker não o serviu',
                { n: tf.length, exemplos: tf.slice(-3).map((x) => x.url),
                  quando: tf.slice(-3).map((x) => new Date(x.t).toISOString()) });
        }
        // 9. O esqueleto de "carregando" POR CIMA de um card montado.
        //
        // INVARIANTE desde v2026.09.22-04: o `renderCurrentCard` esconde o
        // esqueleto ao pendurar o card, e todo card da frente passa por ele.
        // Os dois visíveis juntos é o defeito do relato de 2026-09-22 — o app
        // reaberto sem rede "não carregava nada" com o pedido montado por
        // baixo do esqueleto (z-50) —, e o resumo daquele arquivo dizia só
        // "carregando", sem alerta nenhum.
        const tc = comp.telaDoCard;
        if (tc && tc.esqueleto && tc.card) {
            diga('esqueletoSobreCard',
                'o esqueleto de "carregando" está POR CIMA de um card já montado — a tela parece '
                + 'parada e o pedido está ali embaixo');
        }
        // 10. Pedido que já está esperando envio DE VOLTA na fila de pedidos.
        //
        // INVARIANTE desde v2026.09.22-06: o que está na fila de saída não entra
        // na fila de pedidos — o filtro (`semOsJaDecididos`) está nos DOIS
        // caminhos por onde pedido entra, a busca e a reabertura sem rede. Os
        // dois juntos é o relato de 2026-09-22: reaberta no modo avião, o app
        // devolvia como card o que o owner já tinha tratado, e dava pra decidir
        // de novo — contando duas vezes e mandando duas decisões pro Waze.
        const dc = comp.decididos;
        if (dc && dc.naFila > 0) {
            diga('pedidoDecididoNaFila',
                'pedido que já está esperando envio voltou como card — dá pra decidir de novo, '
                + 'e o segundo gesto conta outra vez',
                { n: dc.naFila });
        }
        // 11. O "N esperando envio" ESCONDIDO (R11-4-04).
        //
        // INVARIANTE desde o R9-4-05 e o R10-4-02: com decisão ESPERANDO envio
        // (o indicador é `.nao-cobrir`), o número está à vista — o FAB não pousa
        // nele e ele se ancora abaixo do cabeçalho medido. É o único sinal de que
        // há decisão esperando sinal, e os quatro defeitos que o esconderam foram
        // achados por auditoria, nenhum por relato: a geometria nem o media. Fora,
        // como no toque: atrás de camada aberta (ela cobre tudo, de propósito),
        // debaixo de aviso passageiro (some sozinho), debaixo do FAB que o EDITOR
        // arrastou pra lá e debaixo do FAB que espera o fim de um gesto no card
        // pra trocar de canto (`'gesto'`, R12-4-04: o app adia a troca de
        // propósito, e o número sai de baixo dele quando o dedo solta). O
        // "enviando" não é número a não cobrir (R10-4-05) e não entra.
        for (const g of comp.geometria || []) {
            if (g.sel !== '#inFlightIndicator' || !g.naoCobrir) continue;
            if (!g.noCentro || g.noCentro === 'ele mesmo' || g.noCentro === 'nada') continue;
            if ((g.camadaAberta && !g.naCamada) || g.sobAviso || g.sobBanner || g.sobFab === 'fixado'
                || g.sobFab === 'gesto') continue;
            diga('indicadorEscondido',
                'o "N esperando envio" está escondido: o dedo no meio dele cai em outra coisa',
                { recebe: g.noCentro, ...(g.sobFab ? { fab: true } : {}) });
        }
        // NÃO existe sentinela de "modal achatado" por ALTURA, e a ausência é
        // deliberada. Eu escrevi uma (< 25% da janela) e ela não disparou no
        // caso real que a motivou: o modal de Filtros achatado tinha 302px de
        // 812 (37%), enquanto o `pairEnterModal` LEGÍTIMO tem 236px (29%) — ou
        // seja o normal é mais BAIXO que o defeito, e nenhum limiar separa os
        // dois. Afrouxar pra pegar 37% faria o modal certo alertar toda vez que
        // abrisse. Quem pega o achatamento é `kbInsetSemFoco`, que olha a CAUSA.
        // (Mesmo desfecho do gotcha #67: asserção que não distingue as duas
        // versões sai, com o motivo no lugar, em vez de ser remendada.)
    } catch (e) {
        alertas.push({ chave: '_erro', msg: String((e && e.message) || e).slice(0, 160) });
    }
    return alertas;
}

// As sentinelas NO INSTANTE da captura. Até v2026.09.22-04 só o relatório as
// rodava — e ele costuma ser gerado com o modal de Filtros ABERTO (o botão de
// baixar mora lá), quando as sentinelas de toque calam de propósito pela
// exceção de camada aberta. No relato de 2026-09-22 o toque no botão foi às
// 20:27:24, com o defeito na tela e NENHUM modal: rodadas ali, elas diriam
// "esqueleto por cima do card" (e três toques interceptados); rodadas no
// relatório, disseram nada. O `computado` vai junto porque é dele que as
// sentinelas leem — sentinela que nascer depois ainda pode ser conferida contra
// a captura velha. Custa ~1,5 KB por captura, contra os ~147 KB do `dom`, e
// nunca derruba a captura: o que falhar vira alerta, como no relatório.
function diagNoInstante() {
    try {
        const computado = diagComputado();
        const alertas = diagSentinelas(computado);
        // O que esta captura leu não volta a acusar na próxima (ver `diagTilesLidosAte`).
        diagTilesLidosAte = Date.now();
        return { computado, alertas };
    } catch (e) {
        return { alertas: [{ chave: '_erro', msg: String((e && e.message) || e).slice(0, 160) }] };
    }
}

function dlogCapturar(motivo) {
    try {
        const m = {
            t: new Date().toISOString(),
            motivo,
            rede: diagRedeAgora(),
            offline: diagOfflineAgora(),
            ...dlogTelaAtual(),
            // O que o navegador decidiu e o que as SENTINELAS acham, no INSTANTE
            // da captura (ver `diagNoInstante`).
            ...diagNoInstante(),
            // Os toasts NA TELA agora. O anel do diário guarda os que já
            // sumiram; este campo diz quais estavam visíveis no instante.
            // Pelo MESMO filtro do `dom`: o toast copiável do pareamento traz o
            // link com o segredo (D1).
            toastsNaTela: [...document.querySelectorAll('#toastContainer > *, #bannerContainer > *')]
                .map((e) => diagSemSegredoDePareamento((e.textContent || '').trim()).slice(0, 120)),
            estado: {
                fila: (AppState.queue || []).length,
                serverTotal: AppState.serverTotal,
                hasMore: AppState.hasMore,
                loadError: AppState.loadError,
                fetching: AppState.fetching,
                ultimaBusca: AppState.ultimaBusca,
                pendingAction: AppState.pendingAction ? AppState.pendingAction.type : null,
                // CÓPIA, não a referência: o Aplicar dos Filtros muda o objeto NO
                // LUGAR, e a captura de antes passava a mostrar os filtros de DEPOIS
                // (auditoria de 2026-09-25).
                filtros: diagSeguro(AppState.filters),
                autorEmFoco: AppState.autorEmFoco,
                atual: dlogPlace(AppState.currentPlace),
            },
            // Imagem quebrada é indistinguível de "meu sandbox não baixou" quando
            // eu reconstruo a tela — então quem sabe é o aparelho, e ele diz.
            imagens: [...document.images].map((i) => ({
                src: (i.currentSrc || i.src || '').slice(0, 160),
                quebrada: !!(i.complete && i.naturalWidth === 0),
            })).filter((x) => x.src),
            // Pixel de canvas não vai no outerHTML. `toDataURL` LANÇA quando o
            // canvas tem tile de outra origem (fica "tainted") — falhar dizendo
            // por quê é melhor que a imagem sair branca sem explicação.
            canvas: [...document.querySelectorAll('canvas')].map((c) => {
                // O QR do pareamento É o segredo desenhado (ver `domParaDiagnostico`).
                if (c.id === 'pairQr') return { classe: c.className, omitido: 'QR do pareamento' };
                try { return { classe: c.className, url: c.toDataURL('image/webp', 0.5).slice(0, 400000) }; }
                catch (e) { return { classe: c.className, erro: 'origem cruzada (tainted)' }; }
            }),
            rolagem: [...document.querySelectorAll('.card-changes-list, .card-flag-comment-text, #noMoreCards')]
                .map((e) => ({ classe: [...e.classList][0], top: e.scrollTop, altura: e.scrollHeight })),
            dom: domParaDiagnostico(),
        };
        dlogMomentos.push(m);
        // COTA POR MOTIVO pro que é FREQUENTE, e o arraste é o caso: ele é o
        // gesto central do app, então a uma captura por 30s ele enche as 12
        // vagas do anel em ~6 minutos de triagem — e empurra pra fora o momento
        // do erro de JS e o da queda de sessão, que são os que se quer ler.
        // É o mesmo risco que o comentário do `dlogCapturarAuto` já descrevia
        // ("um erro em laço enche o anel e empurra pra fora justamente o
        // começo"), só que disparado pelo uso NORMAL em vez de por defeito.
        //
        // MEDIDO: um momento pesa 147 KB e o anel cheio leva o diagnóstico de
        // 760 KB pra 2,5 MB — com TODAS as vagas em `auto:arraste`. Com a cota,
        // o arraste descarta o próprio mais antigo e nunca toca nos outros.
        const cota = DLOG_COTA_POR_MOTIVO[motivo];
        if (cota) {
            let sobrando = dlogMomentos.filter((x) => x.motivo === motivo).length - cota;
            for (let i = 0; i < dlogMomentos.length && sobrando > 0; ) {
                if (dlogMomentos[i].motivo === motivo) { dlogMomentos.splice(i, 1); sobrando--; }
                else i++;
            }
        }
        // O ANEL CHEIO tira primeiro a captura AUTOMÁTICA mais velha, NUNCA uma
        // que a PESSOA fez (o toque no FAB, motivo 'manual') enquanto houver
        // automática pra tirar. Tirava a mais velha, fosse qual fosse: com o
        // servidor fora — justamente quando se registra a tela pra relatar —,
        // cada busca que falha deixa duas automáticas (`buscaFalhou` e
        // `falhaAoCarregar`), e o sexto "Tentar de novo" levava as telas da
        // pessoa do anel, da cópia guardada e do relatório, sem download e sem
        // aviso, com o número do botão ainda contando-as (R7-4-02, MEDIDO: 2 →
        // 0 em ~2,5 min). Com o anel só de telas da pessoa, a automática que
        // chega é a que sai; e a tela nova da pessoa tira a mais velha dela.
        //
        // E ANTES de tudo sai a mais velha JÁ BAIXADA, de qualquer motivo: ela
        // já foi entregue, e segue no anel só pro número desta abertura
        // (`dlogJaBaixados`). A regra existe pra proteger o que NÃO foi
        // entregue: com o anel cheio de telas da pessoa já baixadas, a
        // automática que chegava (o erro de JS, a busca que falhou) era a que
        // saía, e não ia nem pra cópia guardada nem pro próximo relatório
        // (R8-4-01, MEDIDO: 12 toques, o download e um erro de JS de verdade —
        // a captura do erro sumiu; com 11 toques, entrou).
        if (dlogMomentos.length > DLOG_MAX_MOMENTOS) {
            const baixada = dlogMomentos.findIndex((x) => dlogJaBaixados.has(x));
            const automatica = dlogMomentos.findIndex((x) => x.motivo !== 'manual');
            dlogMomentos.splice(baixada >= 0 ? baixada : automatica >= 0 ? automatica : 0, 1);
        }
        // O número do botão segue o anel a CADA captura, não só a do toque: é
        // o que o anel tem agora que vai no próximo relatório. Sem reposicionar
        // o botão — a captura do arraste acontece com o card no meio do gesto.
        atualizarFabDev({ reposicionar: false });
        // `foraDoAnel`: a captura que nem coube (a automática, com o anel cheio
        // de telas da pessoa ainda não entregues) — sem a marca, o diário
        // anotava uma captura que o relatório não traz.
        dlog('momento', { motivo, painel: m.painel, cardMontado: m.cardMontado,
                          alertas: (m.alertas || []).map((a) => a.chave),
                          ...(dlogMomentos.includes(m) ? {} : { foraDoAnel: true }) });
        // A captura vai pro aparelho NA HORA: é ela que prova o defeito, e o
        // app pode morrer antes de ir pro fundo (ver `diagGuardarAbertura`).
        diagGuardarAbertura('captura');
        return m;
    } catch (e) {
        dlog('momento.falhou', { erro: String((e && e.message) || e).slice(0, 120) });
        return null;
    }
}

// Captura AUTOMÁTICA. Vale mais que o botão: o defeito não espera a pessoa ser
// rápida. Um por motivo a cada 30s, senão um erro em laço enche o anel e empurra
// pra fora justamente o começo, que é onde a causa costuma estar.
const dlogUltimaAuto = {};
function dlogCapturarAuto(motivo) {
    if (!dlogLigado()) return;
    const agora = Date.now();
    if (dlogUltimaAuto[motivo] && agora - dlogUltimaAuto[motivo] < 30000) return;
    dlogUltimaAuto[motivo] = agora;
    dlogCapturar('auto:' + motivo);
}

// Desligar o dev APAGA o que ele gravou — senão "desligado" é mentira: o dado
// continua no aparelho. Some o diário, os momentos (o DOM deles carrega nome e
// endereço de terceiros) e os corpos de resposta guardados no anel da API.
// Fica o anel de METADADOS das chamadas: ele não tem dado pessoal e é a espinha
// de qualquer diagnóstico posterior.
//
// `soMemoria`: a OUTRA aba já apagou o que estava no aparelho — ou ele agora é
// de outra conta (ver `handleLogout`). A base fica; a época sobe do mesmo jeito,
// e uma gravação desta aba ainda em voo não grava mais nela.
function dlogApagar({ soMemoria = false } = {}) {
    dlogAnel = [];
    dlogMomentos = [];
    // E o que ficou GUARDADO de aberturas anteriores, no aparelho e na memória:
    // desligado é desligado, e ali há o DOM das capturas, com dado de terceiro.
    diagAberturasAnteriores = [];
    diagBaixadoEm = 0;
    // Na saída por OUTRA aba (`soMemoria`) o aparelho não é desta aba: só a
    // memória sai. Senão saem a base, o retrato que o fechar deixou no
    // localStorage (`diagRetratoAoSair`) e o aviso do que um download entregou
    // (`diagAvisarEntregues`), que também são do aparelho.
    if (soMemoria) diagEpoca++;
    else {
        diagEsquecerGuardado();
        diagEsquecerRetratos();
        diagEsquecerEntregas();
    }
    for (const h of dlogPendencias.values()) clearTimeout(h);
    dlogPendencias.clear();
    // O corpo ENVIADO também: com o modo dev ligado ele leva o texto da conversa
    // e o cartão do pedido (sem o dev, só o tamanho). Ficava aqui depois de
    // desligar — e o comentário da época dizia que eram só metadados.
    try { for (const c of (API.chamadas || [])) { delete c.corpoResposta; delete c._bytes; delete c.corpoReq; } } catch (e) {}
    // A posição em que o editor fixou o FAB é dado do modo dev como qualquer
    // outro: desligar apaga, e ligar de novo devolve a escolha automática do
    // canto. É também o único caminho de volta pra quem arrastou pra um lugar
    // ruim e quer o automático de novo.
    devFabFixado = false;
    try { sessionStorage.removeItem('__devFabPos'); } catch (e) {}
    // E o "pego" que tenha sobrado (D7): desligar o modo dev é a saída que a
    // pessoa tem, e ele sobrevivia a ela.
    devFabDedo = null;
    document.getElementById('devFab')?.classList.remove('fab-pego');
    atualizarFabDev();
}

// O selo do FAB e o aviso do desligar contam SÓ o que a PESSOA registrou (o
// motivo 'manual', o toque no FAB). Pedido do owner depois de ver o selo ir a
// 2, 4 e 5 em três toques: o número somava as capturas AUTOMÁTICAS — o arraste
// do card passando do limiar, com cota de 2 — às dele, então o primeiro toque
// já mostrava 2 e ele leu "capturou duas vezes". As automáticas continuam no
// anel e no relatório, iguais; só não entram num número que a pessoa lê como
// "quantas vezes eu apertei". Os dois pontos contam a MESMA coisa: aviso de
// "3 não baixados" com o selo mostrando 1 seria o app discordando de si mesmo.
function dlogCapturasDoEditor() { return dlogMomentos.filter((m) => m.motivo === 'manual'); }

// Quais já foram BAIXADOS, marcados no próprio momento. Era uma CONTAGEM (o
// tamanho do anel na hora do download), que mentia assim que o anel cheio
// girava: com 12 baixados, uma captura nova empurrava a mais velha pra fora e
// a conta seguia dizendo "0 não baixados". `WeakSet` e não um campo no objeto
// porque o momento vai inteiro pro JSON do relatório.
const dlogJaBaixados = new WeakSet();
// As guardadas de aberturas ANTERIORES entram nas duas contas (ver
// `diagAberturasAnteriores`): o número do botão é "o que vai no próximo
// relatório", e é isso que precisa sobreviver a fechar o app.
//
// `entregues` é a lista do RETRATO do relatório (ver `diagCorpo`): marca só o
// que FOI no arquivo. Marcar o anel de depois do download levava junto a
// captura feita enquanto o arquivo era montado e empacotado — ela não ia no
// arquivo, e sumia do número do botão e da cópia guardada (auditoria de
// 2026-09-26). Sem a lista, marca tudo o que existe agora.
function dlogMarcarBaixados(entregues) {
    const lista = Array.isArray(entregues) ? entregues : [...dlogMomentos, ...diagMomentosAnteriores()];
    for (const m of lista) dlogJaBaixados.add(m);
}
function dlogNaoBaixados() {
    return [...dlogCapturasDoEditor(), ...diagCapturasAnterioresDoEditor()]
        .filter((m) => !dlogJaBaixados.has(m)).length;
}

// ── O DIAGNÓSTICO QUE SOBREVIVE A FECHAR O APP ────────────────────────────
//
// Relato de 2026-09-22 (owner, no modo avião): capturou o defeito com o botão
// duas vezes, fechou o app, reabriu — e o número sumiu do botão. As capturas,
// o diário, as chamadas e os erros viviam só em MEMÓRIA e morriam ao fechar. E
// o defeito daquele dia (o pedido tratado voltando como card) só existia
// ATRAVESSANDO um fechar e reabrir: o relatório, gerado numa abertura
// posterior, não tinha como mostrá-lo, e a prova de antes de fechar era
// exatamente o que sumia.
//
// Com o modo dev LIGADO, cada abertura guarda no aparelho o que o relatório
// levaria dela — as capturas ainda não baixadas, o diário, as chamadas (só os
// metadados) e os erros —, e as aberturas seguintes os devolvem: o número do
// botão sobrevive, e o relatório conta o que houve em cada uma. Decisão do
// owner, com o custo na mesa: até ~1,8 MB (12 capturas de ~150 KB) e, o que
// pesou, dado de terceiro no aparelho — a captura leva o DOM, com nome e
// endereço dos pedidos na tela. Por isso tudo tem saída: o que foi guardado
// some ao BAIXAR o diagnóstico (já foi entregue), ao DESLIGAR o modo dev, no
// "Sair", ou depois de 24 h.
//
// IndexedDB e não localStorage: 1,8 MB num `setItem` SÍNCRONO trava a thread do
// swipe. E base PRÓPRIA, não a do offline: aquela é apagada inteira quando o
// toggle dele desliga, e as duas coisas não têm nada a ver uma com a outra.
//
// Grava a cada CAPTURA e quando o app vai pro fundo (`visibilitychange`
// oculto, o último momento confiável no celular) ou sai (`pagehide`). NUNCA
// por swipe: o diário do modo dev anota cada ação, e gravar a cada anotação
// seria justamente o custo que o anel existe pra não ter.
const DIAG_DB = 'waze_places_diag';
const DIAG_STORE = 'aberturas';
const DIAG_GUARDA_MS = 24 * 60 * 60 * 1000;
const DIAG_ABERTURAS_MAX = 5;
// O mesmo teto do anel desta abertura (`DLOG_MAX_MOMENTOS`), somado entre TODAS
// as aberturas guardadas — é ele que segura o armazenamento em ~1,8 MB. As da
// pessoa ganham das automáticas, e entre iguais as mais NOVAS ganham (pela hora
// da captura, ver `diagPodarAberturas`).
const DIAG_CAPTURAS_GUARDADAS_MAX = DLOG_MAX_MOMENTOS;
// Esta abertura: o id nasce com a página e morre com ela.
const DIAG_ABERTURA = { id: Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
                        inicio: Date.now() };
// O que as OUTRAS aberturas deixaram no aparelho — as anteriores, e a de outra
// aba aberta —, lido na abertura (só com o modo dev ligado) e relido na hora de
// baixar e de desligar (`diagAtualizarAnteriores`). Fica em memória até a página
// morrer: mesmo baixado, segue indo nos relatórios desta abertura — é o que já
// acontece com as capturas dela.
let diagAberturasAnteriores = [];
// O último download do diagnóstico NESTA abertura. O que veio antes já foi
// entregue: não volta a ser guardado.
let diagBaixadoEm = 0;

function diagMomentosAnteriores(lista = diagAberturasAnteriores) {
    return lista.flatMap((a) => (Array.isArray(a.momentos) ? a.momentos : []));
}
function diagCapturasAnterioresDoEditor() {
    return diagMomentosAnteriores().filter((m) => m && m.motivo === 'manual');
}

// Abrir a base tem TETO, como a do offline (`OFFLINE_DB_TETO_MS`): o IndexedDB
// do WebKit às vezes não responde, e uma gravação com a abertura pendurada
// prendia a fila `diagGuardando` — o apagar do "Sair" e do desligar do modo dev
// entra na MESMA fila e nunca rodava (auditoria de 2026-09-26, O10).
const DIAG_DB_TETO_MS = 5000;
// Sobe a cada apagar: a gravação que acordar DEPOIS dele não grava nada (ver
// `diagEsquecerGuardado`).
let diagEpoca = 0;
function diagDB() {
    return new Promise((ok, erro) => {
        let req;
        try { req = indexedDB.open(DIAG_DB, 1); } catch (e) { return erro(e); }
        let estourou = false;
        const teto = setTimeout(() => { estourou = true; erro(new Error('timeout')); }, DIAG_DB_TETO_MS);
        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(DIAG_STORE)) db.createObjectStore(DIAG_STORE, { keyPath: 'id' });
        };
        req.onsuccess = () => {
            clearTimeout(teto);
            // Abriu DEPOIS do teto: ninguém mais espera por ela — fecha, senão a
            // conexão esquecida seguraria o apagar da base.
            if (estourou) { try { req.result.close(); } catch (e) {} return; }
            ok(req.result);
        };
        req.onerror = () => { clearTimeout(teto); erro(req.error); };
    });
}

function diagLerGuardado(db) {
    return new Promise((ok, erro) => {
        const r = db.transaction(DIAG_STORE, 'readonly').objectStore(DIAG_STORE).getAll();
        r.onsuccess = () => ok(Array.isArray(r.result) ? r.result : []);
        r.onerror = () => erro(r.error);
    });
}

// A chamada vai só com os METADADOS. O corpo da resposta é a fila inteira —
// dado de terceiro em massa, e pesado — e o do pedido não responde nada do que
// se investiga entre uma abertura e outra.
function diagChamadaSemCorpo(c) {
    const { corpoReq, corpoResposta, _bytes, ...resto } = c || {};
    return resto;
}

// O que ESTA abertura guarda: só o que ainda não foi entregue — as capturas não
// baixadas e, do diário, das chamadas e dos erros, o que veio depois do último
// download (sem download, tudo). O download de OUTRA aba também conta (R9-4-10):
// o que ela entregou desta é conferido aqui, antes de cada registro, e não volta
// à base (ver `diagAplicarEntregues`).
function diagRegistroDaAbertura(motivo) {
    diagAplicarEntregues();
    const depois = (x) => {
        if (!diagBaixadoEm) return true;
        const t = typeof x.t === 'number' ? x.t : Date.parse(x.t);
        return !(t <= diagBaixadoEm);
    };
    return {
        id: DIAG_ABERTURA.id,
        inicio: DIAG_ABERTURA.inicio,
        salvoEm: Date.now(),
        salvoPor: motivo,
        versao: typeof APP_VERSION !== 'undefined' ? APP_VERSION : null,
        diario: [...dfatoAnel, ...dlogAnel].filter(depois).sort((a, b) => a.t - b.t),
        chamadas: (API.chamadas || []).filter(depois).map(diagChamadaSemCorpo),
        erros: diagErros.filter(depois),
        momentos: dlogMomentos.filter((m) => !dlogJaBaixados.has(m)),
    };
}

// A PODA, pura. O que passou de 24 h sai inteiro; das que ficam SEM tela da
// pessoa (ver abaixo), só as DIAG_ABERTURAS_MAX de atividade mais RECENTE (a
// última gravação, `salvoEm`); e as capturas, somadas, não passam do teto — as
// da PESSOA antes das automáticas (a mesma regra do anel, ver `dlogCapturar`),
// e entre iguais as mais NOVAS pela hora da CAPTURA (`m.t`). A ordem era a da
// ABERTURA (`inicio`), que com duas abas não diz nada da hora das capturas: a aba aberta
// por último ficava com as dela e cortava as da outra, mesmo sendo as da outra
// as mais novas, e a aba mais velha gravava a própria abertura já sem as
// capturas dela (R7-4-03, MEDIDO: na base A 0 · B 12, com o botão de A
// mostrando "2"; A recarregada, as 2 tinham sumido sem ir em arquivo nenhum).
// Pela última gravação, a abertura que está gravando agora nunca é a que sai.
//
// O teto de ABERTURAS não leva tela da PESSOA (R8-4-09): ele cortava antes da
// prioridade delas, e a 6ª abertura que gravava tirava a mais velha INTEIRA, com
// as telas que a pessoa registrou, mesmo com as outras 5 sem captura nenhuma —
// no Android, que encerra o app no fundo, cada volta a ele é uma abertura nova
// (MEDIDO, r9 da auditoria: 2 telas registradas, 5 reaberturas, e a base ficou
// com [0,0,0,0,0], o botão ainda dizendo "2"). A abertura com tela da pessoa
// que cabe no teto de CAPTURAS fica; o teto de aberturas vale entre as outras.
// O custo segue limitado: as capturas, somadas, não passam do teto de sempre, e
// abertura com tela é no máximo uma por captura (5 + 12 no pior caso, 24 h).
// Devolve o que manter (com as capturas já cortadas), os ids que saem e os ids
// cortados (que precisam ser regravados).
function diagPodarAberturas(lista, agora) {
    const todas = (Array.isArray(lista) ? lista : []).filter((a) => a && typeof a.id === 'string');
    const noPrazo = todas
        .filter((a) => Number.isFinite(a.salvoEm) && agora - a.salvoEm <= DIAG_GUARDA_MS)
        .sort((a, b) => b.salvoEm - a.salvoEm);
    // Cada captura com a hora dela (o `toISOString` da captura); sem hora
    // legível, a da gravação da abertura (a captura é de antes dela), e o empate
    // fica com a de depois no anel. Só a forma ISO: o `Date.parse` do V8 aceita
    // quase qualquer texto ("x:11" vira uma data de 2001).
    const capturasDe = (aberturas) => aberturas.flatMap((a) => (Array.isArray(a.momentos) ? a.momentos : []).map((m, i) => {
        const t = !m ? NaN : typeof m.t === 'number' ? m.t
            : (typeof m.t === 'string' && /^\d{4}-\d\d-\d\dT/.test(m.t) ? Date.parse(m.t) : NaN);
        return { m, i, daPessoa: !!(m && m.motivo === 'manual'), t: Number.isFinite(t) ? t : a.salvoEm };
    }));
    const ordem = (x, y) => (y.daPessoa - x.daPessoa) || (y.t - x.t) || (y.i - x.i);
    // As telas da pessoa que cabem no teto de capturas, entre TODAS as aberturas
    // no prazo: são elas que tiram a abertura do teto de aberturas.
    const telas = new Set(capturasDe(noPrazo).filter((c) => c.daPessoa).sort(ordem)
        .slice(0, DIAG_CAPTURAS_GUARDADAS_MAX).map((c) => c.m));
    const temTela = (a) => (Array.isArray(a.momentos) ? a.momentos : []).some((m) => telas.has(m));
    const semTela = new Set(noPrazo.filter((a) => !temTela(a)).slice(0, DIAG_ABERTURAS_MAX));
    const vivas = noPrazo.filter((a) => semTela.has(a) || temTela(a));
    const capturas = capturasDe(vivas);
    capturas.sort(ordem);
    const ficam = new Set(capturas.slice(0, DIAG_CAPTURAS_GUARDADAS_MAX).map((c) => c.m));
    const cortadas = [];
    const manter = vivas.map((a) => {
        const ms = Array.isArray(a.momentos) ? a.momentos : [];
        const daqui = ms.filter((m) => ficam.has(m));
        if (daqui.length === ms.length) return a;
        cortadas.push(a.id);
        return { ...a, momentos: daqui };
    });
    const mantidas = new Set(manter.map((a) => a.id));
    return { manter, sair: todas.filter((a) => !mantidas.has(a.id)).map((a) => a.id), cortadas };
}

async function diagAplicarPoda(db, poda, novos) {
    await new Promise((ok, erro) => {
        const tx = db.transaction(DIAG_STORE, 'readwrite');
        const st = tx.objectStore(DIAG_STORE);
        for (const id of poda.sair) st.delete(id);
        for (const a of poda.manter) if (novos.has(a.id) || poda.cortadas.includes(a.id)) st.put(a);
        tx.oncomplete = ok;
        tx.onerror = () => erro(tx.error);
        tx.onabort = () => erro(tx.error);
    });
}

// Uma gravação de cada vez, em ORDEM: a de uma captura e a de ir pro fundo
// podem sair no mesmo instante, e a mais velha não pode pousar por cima da
// mais nova. O retrato é tirado DEPOIS do `await`, pelo mesmo motivo.
let diagGuardando = Promise.resolve();
function diagGuardarAbertura(motivo) {
    if (!dlogLigado()) return Promise.resolve(false);
    diagSegurarAbertura();
    // A época do PEDIDO, e não a do começo da gravação: um apagar pedido DEPOIS
    // desta gravação a vence, mesmo que ela ainda nem tenha começado (a fila) ou
    // esteja pendurada no meio (ver `diagEpoca`).
    const epoca = diagEpoca;
    const esta = diagGuardando.then(async () => {
        // O modo dev pela FONTE, além da memória: desligado (ou o "Sair") numa
        // OUTRA aba, esta ainda o tem ligado até o aviso do navegador chegar — e
        // gravava de novo a base que a outra acabou de apagar (auditoria de
        // 2026-09-26, D2). Aqui, na vez da gravação, antes de abrir a base.
        if (!dlogLigado() || epoca !== diagEpoca || modoDevDesligadoNoArmazenamento()) return false;
        let db = null;
        try {
            db = await diagDB();
            const guardadas = (await diagLerGuardado(db)).filter((a) => a.id !== DIAG_ABERTURA.id);
            if (epoca !== diagEpoca) return false;
            const atual = diagRegistroDaAbertura(motivo);
            const poda = diagPodarAberturas([atual, ...guardadas], Date.now());
            await diagAplicarPoda(db, poda, new Set([atual.id]));
            return true;
        } catch (e) {
            dfato('diag.guardarFalhou', { motivo, erro: String((e && e.name) || e).slice(0, 60) });
            return false;
        } finally {
            try { if (db) db.close(); } catch (e) {}
        }
    });
    diagGuardando = esta.catch(() => false);
    return esta;
}

// ── A OUTRA ABA não é uma abertura ANTERIOR ───────────────────────────────
//
// Desde que o relatório leva o que a outra aba aberta gravou (R6-4-5), ela
// chegava em `aberturasAnteriores` sem nada que a distinguisse de uma abertura
// que FECHOU — e essa seção existe pro defeito que atravessa fechar e reabrir:
// quem lê ia atrás de um fechar que não houve. No relatório do auditor, a
// "abertura anterior" tinha COMEÇADO depois da do relatório (R7-4-04).
//
// A abertura que gravou na base segura, enquanto a página viver, uma trava do
// navegador com o id dela (só com o modo dev, a partir da primeira gravação);
// quem a solta é o navegador, quando a página morre. Trava não grava nada.
const DIAG_ABERTURA_TRAVA = '__diagAbertura:';
let diagAberturaSegura = false;
function diagSegurarAbertura() {
    if (diagAberturaSegura) return;
    diagAberturaSegura = true;
    try {
        const locks = navigator.locks && typeof navigator.locks.request === 'function' ? navigator.locks : null;
        if (!locks) return;
        locks.request(DIAG_ABERTURA_TRAVA + DIAG_ABERTURA.id, { ifAvailable: true },
            (lock) => (lock ? new Promise(() => {}) : undefined)).catch(() => {});
    } catch (e) { /* sem a trava, fica a prova pela hora (ver abaixo) */ }
}

// As aberturas VIVAS agora, pelas travas que o navegador diz estarem seguras.
// `null` = não deu pra saber (navegador sem `navigator.locks`, ou sem resposta
// a tempo — o relatório tem orçamento).
async function diagAberturasVivas(prazo) {
    try {
        const locks = navigator.locks && typeof navigator.locks.query === 'function' ? navigator.locks : null;
        if (!locks) return null;
        const espera = Math.max(0, Math.min(1500, prazo - Date.now()));
        const r = await Promise.race([locks.query(), new Promise((ok) => setTimeout(() => ok(null), espera))]);
        if (!r || !Array.isArray(r.held)) return null;
        return new Set(r.held.map((l) => String((l && l.name) || ''))
            .filter((n) => n.startsWith(DIAG_ABERTURA_TRAVA)).map((n) => n.slice(DIAG_ABERTURA_TRAVA.length)));
    } catch (e) { return null; }
}

// PURA. A abertura guardada que viveu JUNTO com esta ganha `simultanea: true`:
// ela gravou DEPOIS de esta abrir (a vida das duas se cruzou — uma página de
// antes, na mesma aba, morreu antes de esta nascer), ou a trava dela segue
// segura agora, ou estava segura quando ESTA abriu (`vivasAoAbrir`, ver
// `diagCarregarAberturas`). `abertaAgora` diz se ela segue aberta (`null`: não
// deu pra saber). As que não viveram junto voltam as MESMAS.
function diagMarcarSimultaneas(lista, inicioDesta, vivas, vivasAoAbrir) {
    return (Array.isArray(lista) ? lista : []).map((a) => {
        if (!a || typeof a !== 'object') return a;
        const viva = vivas ? vivas.has(a.id) : null;
        const gravouDepois = Number.isFinite(a.salvoEm) && a.salvoEm > inicioDesta;
        const vivaAoAbrir = !!(vivasAoAbrir && vivasAoAbrir.has(a.id));
        if (!gravouDepois && viva !== true && !vivaAoAbrir) return a;
        return { ...a, simultanea: true, abertaAgora: viva };
    });
}

// As OUTRAS aberturas VIVAS quando esta abriu, pelas travas (só com o modo dev
// ligado na abertura; `null` = não se sabe). A aba MAIS VELHA, aberta junto com
// esta e fechada antes do relatório, saía como "abertura anterior": a última
// gravação dela na base é de antes de esta abrir (ir pro fundo grava; o fechar
// aborta a gravação), e a trava já tinha sido solta na hora do relatório — as
// duas provas acima falhavam, embora a trava dela estivesse SEGURA quando esta
// abriu (R8-4-07, MEDIDO: 3 de 4 rodadas do r2 `bAntes` da auditoria). A página
// de antes, na MESMA aba (recarregar), não entra: ela solta a trava a tempo de
// a seguinte nascer (a mesma medição do `segurarMarcaDaAba`).
let diagOutrasVivasAoAbrir = null;

// Na abertura, com o modo dev ligado: traz o que as aberturas anteriores
// deixaram, já podado (o que venceu sai do aparelho aqui mesmo). Os RETRATOS
// que o fechar deixou no localStorage (ver `diagRetratoAoSair`) entram antes da
// poda, juntos ao que a base tinha da mesma abertura, e saem do localStorage.
async function diagCarregarAberturas() {
    if (!dlogLigado()) return;
    // O aviso do que os downloads entregaram vive o prazo do resto (24 h).
    diagPodarEntregas();
    // Quem está VIVO agora, na abertura (ver `diagOutrasVivasAoAbrir`): a
    // pergunta sai antes da base, que pode levar até o teto dela pra abrir.
    // Trava não grava nada, e a pergunta não lança (`null` = não se sabe).
    const vivasAoAbrir = diagAberturasVivas(Date.now() + 1500).then((vivas) => {
        if (!vivas) return;
        vivas.delete(DIAG_ABERTURA.id);
        diagOutrasVivasAoAbrir = vivas;
    });
    // A época de AGORA: desligado o modo dev (ou o "Sair") enquanto a base
    // abre, nada do que foi lido volta pro aparelho.
    const epoca = diagEpoca;
    const retratos = diagLerRetratos();
    let db = null;
    try {
        db = await diagDB();
        const guardadas = (await diagLerGuardado(db)).filter((a) => a.id !== DIAG_ABERTURA.id);
        const juntadas = new Set();
        for (const { r } of retratos) {
            if (!r || r.id === DIAG_ABERTURA.id) continue;
            const i = guardadas.findIndex((a) => a.id === r.id);
            const junto = diagJuntarRetrato(i >= 0 ? guardadas[i] : null, r);
            if (i >= 0 && junto === guardadas[i]) continue;
            if (i >= 0) guardadas[i] = junto; else guardadas.push(junto);
            juntadas.add(junto.id);
        }
        const poda = diagPodarAberturas(guardadas, Date.now());
        if (epoca !== diagEpoca || !dlogLigado()) return;
        if (poda.sair.length || poda.cortadas.length || juntadas.size) await diagAplicarPoda(db, poda, juntadas);
        diagEsquecerRetratos(retratos);
        diagAberturasAnteriores = poda.manter;
        dfato('diag.aberturas', { n: poda.manter.length, capturas: diagMomentosAnteriores().length,
                                  ...(retratos.length ? { retratos: juntadas.size } : {}) });
        atualizarFabDev();
    } catch (e) {
        dfato('diag.carregarFalhou', { erro: String((e && e.name) || e).slice(0, 60) });
    } finally {
        try { if (db) db.close(); } catch (e) {}
        await vivasAoAbrir;
    }
}

// O que o APARELHO tem agora das outras aberturas, juntado ao que esta aba leu ao
// abrir. A OUTRA aba aberta grava as capturas dela na base na hora em que são
// feitas (`diagGuardarAbertura`), e esta só as conhecia se fossem de antes de ela
// abrir: o aviso do desligar contava só a memória desta aba — e desligar aqui
// apaga as da outra (R6-4-4) —, e o relatório baixado aqui não as levava, com o
// download apagando a base inteira (R6-4-5). Por abertura vale a versão mais NOVA
// (`salvoEm`), e a que só esta aba ainda tem na memória fica. A versão nova de uma
// abertura já baixada aqui traz de novo as capturas que foram: elas seguem
// marcadas (pela hora e o motivo, que a base não guarda objeto), senão contariam
// como "não baixadas" no botão e no aviso. Sem a base (o IndexedDB não
// respondeu), fica o que havia.
async function diagAtualizarAnteriores() {
    if (!dlogLigado()) return false;
    const epoca = diagEpoca;
    let db = null, guardadas = null;
    try {
        db = await diagDB();
        guardadas = await diagLerGuardado(db);
    } catch (e) {
        return false;
    } finally {
        try { if (db) db.close(); } catch (e) {}
    }
    // Apagado (o "Sair", o desligar) ou desligado enquanto a base era lida: nada
    // do que foi lido volta pra memória.
    if (epoca !== diagEpoca || !dlogLigado()) return false;
    const porId = new Map(diagAberturasAnteriores.map((a) => [a.id, a]));
    let mudou = false;
    for (const a of guardadas) {
        if (!a || typeof a.id !== 'string' || a.id === DIAG_ABERTURA.id) continue;
        // O que passou do prazo (24 h) não volta: é da poda, não do relatório.
        if (!(Date.now() - a.salvoEm <= DIAG_GUARDA_MS)) continue;
        const ja = porId.get(a.id);
        if (ja && !(a.salvoEm > ja.salvoEm)) continue;
        if (ja) {
            const baixadas = new Set((ja.momentos || []).filter((m) => dlogJaBaixados.has(m)).map(diagMarcaDoMomento));
            for (const m of (a.momentos || [])) if (baixadas.has(diagMarcaDoMomento(m))) dlogJaBaixados.add(m);
        }
        porId.set(a.id, a);
        mudou = true;
    }
    if (mudou) {
        diagAberturasAnteriores = [...porId.values()];
        atualizarFabDev();
    }
    // E o que OUTRA aba já entregou (R9-4-10): o aviso dela pode não ter chegado
    // — esta releitura é a do relatório e a do aviso do desligar, que contam as
    // não baixadas (ver `diagAplicarEntregues`).
    diagAplicarEntregues();
    return true;
}

// O que SOBROU no aparelho com o modo dev DESLIGADO. A poda de 24 h mora no
// `diagCarregarAberturas`, que só roda com o modo dev ligado — então o que
// ficasse pra trás (a base recriada por outra aba, antes do conserto do D2; um
// apagar que não chegou a rodar) ficava indefinidamente, contra "desligar
// apaga", "Sair é limpar de tudo" e a Ajuda ("no máximo 24 h") — auditoria de
// 2026-09-26. Com o modo dev desligado não existe registro legítimo: apaga
// inteiro, não só o vencido.
//
// SEM CRIAR a base: `indexedDB.databases()` lista as que existem sem abrir
// nenhuma (o `open` criaria uma vazia, em todo aparelho de quem nunca ligou o
// modo dev), e o `deleteDatabase` de uma base inexistente também não cria nada
// — por isso ele é o caminho onde não há `databases()` (Firefox antigo).
function diagFaxinaSemModoDev() {
    if (dlogLigado()) return Promise.resolve(false);
    // O retrato do fechar também (síncrono, e sem custo quando não há chave), e
    // o aviso do que um download entregou (R9-4-10).
    diagEsquecerRetratos();
    diagEsquecerEntregas();
    try {
        if (typeof indexedDB === 'undefined') return Promise.resolve(false);
        const sabe = typeof indexedDB.databases === 'function';
        const existe = sabe
            ? indexedDB.databases().then((l) => (l || []).some((b) => b && b.name === DIAG_DB))
            : Promise.resolve(true);
        return existe.then((sim) => {
            if (!sim || dlogLigado()) return false;
            // Só anota quando SABE que havia sobra (sem `databases()` o apagar é às cegas).
            if (sabe) dfato('diag.sobraApagada');
            return diagEsquecerGuardado().then(() => sabe);
        }).catch(() => false);
    } catch (e) { return Promise.resolve(false); }
}

// Apaga TUDO o que foi guardado: no desligar do modo dev e no "Sair" (o download
// apaga só o que entregou: `diagEsquecerEntregue`). Entra na MESMA fila das
// gravações: a que estava em voo termina antes (senão recriaria a base logo
// depois de apagada), e a que for pedida depois acontece depois.
function diagEsquecerGuardado() {
    // A gravação em voo termina ANTES — mas com TETO: pendurada, ela prendia o
    // apagar pra sempre (O10). Se ela acordar depois, a época a impede de gravar.
    diagEpoca++;
    const antes = Promise.race([diagGuardando, new Promise((ok) => setTimeout(ok, DIAG_DB_TETO_MS))]);
    const esta = antes.then(() => new Promise((ok) => {
        try {
            const r = indexedDB.deleteDatabase(DIAG_DB);
            r.onsuccess = r.onerror = r.onblocked = () => ok(true);
        } catch (e) { ok(false); }
    }));
    diagGuardando = esta.catch(() => false);
    return esta;
}

// Depois do DOWNLOAD, sai do aparelho só o que FOI no arquivo (R6-4-5). Apagava
// a base inteira, e com ela o que a OUTRA aba gravou depois do relatório ler a
// base — capturas que não foram no arquivo e sumiam (medido, t3b). Sai cada
// abertura entregue, na versão em que foi (`{ id, salvoEm }`): a que a outra aba
// regravou depois de lida fica, e vai no próximo relatório (repetir o entregue é
// melhor que perder o que não foi). E a desta aba é REGRAVADA com o que veio
// depois do retrato (`diagBaixadoEm`) e as capturas não entregues — sem o que já
// foi. Na MESMA fila das gravações, e com a época do PEDIDO: um apagar inteiro
// pedido depois (o "Sair", o desligar) decide.
function diagEsquecerEntregue(entregues) {
    const epoca = diagEpoca;
    const foi = new Map((Array.isArray(entregues) ? entregues : []).map((a) => [a.id, a.salvoEm]));
    const esta = diagGuardando.then(async () => {
        if (epoca !== diagEpoca) return false;
        let db = null;
        try {
            db = await diagDB();
            const guardadas = await diagLerGuardado(db);
            if (epoca !== diagEpoca) return false;
            const sair = guardadas.filter((a) => a && (a.id === DIAG_ABERTURA.id
                || (foi.has(a.id) && foi.get(a.id) === a.salvoEm))).map((a) => a.id);
            // A desta aba volta com o que NÃO foi entregue — pelo modo dev da FONTE,
            // como na gravação (desligado noutra aba, não regrava nada).
            const atual = dlogLigado() && !modoDevDesligadoNoArmazenamento() ? diagRegistroDaAbertura('baixou') : null;
            await diagAplicarPoda(db, { sair, manter: atual ? [atual] : [], cortadas: [] }, new Set(atual ? [atual.id] : []));
            return true;
        } catch (e) {
            dfato('diag.guardarFalhou', { motivo: 'baixou', erro: String((e && e.name) || e).slice(0, 60) });
            return false;
        } finally {
            try { if (db) db.close(); } catch (e) {}
        }
    });
    diagGuardando = esta.catch(() => false);
    return esta;
}

// ── O que OUTRA ABA entregou ──────────────────────────────────────────────
//
// O download numa aba leva o que a OUTRA aba aberta gravou na base (R6-4-5) e
// apaga do aparelho a versão que foi. A outra aba não ficava sabendo: as telas
// dela seguiam "não baixadas" na memória, VOLTAVAM pra base quando ela ia pro
// fundo de novo e saíam de novo no próximo relatório — e o aviso do desligar
// pedia o 2º toque por "2 não baixados" que já tinham ido no arquivo (auditoria
// da rodada 9, R9-4-10, MEDIDO no navegador). Agora o download DIZ o que entregou:
// uma chave no localStorage com as aberturas (o id e a versão, `salvoEm`) e a
// marca de cada captura (`diagMarcaDoMomento`). O aviso `storage` a leva às
// outras abas na hora, e cada registro desta abertura a confere de novo antes de
// gravar (`diagRegistroDaAbertura`): o aviso que se perder, com a aba congelada
// no fundo, não devolve nada à base. Só ids, horas e o motivo — nenhum DOM,
// nenhum dado de terceiro —, e sai com o resto do modo dev: no "Sair", ao
// desligar, e em 24 h.
const DIAG_ENTREGUE_KEY = 'waze_places_diag_entregue';
// As últimas entregas, e não só a última: dois downloads com a outra aba
// congelada nos dois, e a conferência na hora de gravar ainda acha o primeiro.
const DIAG_ENTREGAS_MAX = 5;

// A marca de uma captura ENTRE abas: a base guarda CÓPIAS, não o objeto, então o
// que a identifica é a hora e o motivo.
function diagMarcaDoMomento(m) { return (m && m.t) + '|' + (m && m.motivo); }

// As entregas no aparelho, as de até 24 h e com a forma certa. Nunca lança.
function diagLerEntregas() {
    let lista = [];
    try { lista = JSON.parse(localStorage.getItem(DIAG_ENTREGUE_KEY) || '[]'); } catch (e) { return []; }
    const agora = Date.now();
    return (Array.isArray(lista) ? lista : []).filter((it) => it && Number.isFinite(it.em)
        && agora - it.em <= DIAG_GUARDA_MS && Array.isArray(it.aberturas) && Array.isArray(it.marcas));
}

// O DOWNLOAD avisa o que entregou (o `corpo.entregue` do relatório): as outras
// aberturas, cada uma na versão que foi, e as marcas de TODAS as capturas que
// foram no arquivo — as desta aba também, que a outra pode ter lido da base.
function diagAvisarEntregues(entregue) {
    if (!entregue) return false;
    try {
        const item = {
            em: Date.now(),
            aberturas: (Array.isArray(entregue.aberturas) ? entregue.aberturas : [])
                .filter((a) => a && typeof a.id === 'string').map((a) => ({ id: a.id, salvoEm: a.salvoEm })),
            marcas: [...new Set((Array.isArray(entregue.momentos) ? entregue.momentos : []).filter(Boolean).map(diagMarcaDoMomento))],
        };
        localStorage.setItem(DIAG_ENTREGUE_KEY, JSON.stringify([...diagLerEntregas(), item].slice(-DIAG_ENTREGAS_MAX)));
        return true;
    } catch (e) { return false; }   // cota cheia, armazenamento bloqueado: a outra aba repete, não perde
}

// O que OUTRA aba entregou DESTA conta como entregue aqui: as capturas com a marca
// de uma entregue (as desta abertura e as das outras que esta tem na memória)
// ficam "baixadas" — o aviso do desligar não as conta, e o registro não as grava
// de novo —, e a versão desta abertura que foi no arquivo dela adianta o
// `diagBaixadoEm`: o diário, as chamadas e os erros até ela já foram entregues.
// Devolve se mudou algo.
function diagAplicarEntregues() {
    const entregas = diagLerEntregas();
    if (!entregas.length) return false;
    const marcas = new Set(entregas.flatMap((it) => it.marcas));
    let ate = 0;
    for (const it of entregas) {
        for (const a of it.aberturas) {
            if (a && a.id === DIAG_ABERTURA.id && Number.isFinite(a.salvoEm) && a.salvoEm > ate) ate = a.salvoEm;
        }
    }
    let mudou = false;
    for (const m of [...dlogMomentos, ...diagMomentosAnteriores()]) {
        if (m && !dlogJaBaixados.has(m) && marcas.has(diagMarcaDoMomento(m))) { dlogJaBaixados.add(m); mudou = true; }
    }
    if (ate > diagBaixadoEm) { diagBaixadoEm = ate; mudou = true; }
    return mudou;
}

// As entregas de mais de 24 h saem do aparelho (na abertura com o modo dev, como
// a poda da base): a chave vive o mesmo prazo do resto.
function diagPodarEntregas() {
    try {
        const cru = localStorage.getItem(DIAG_ENTREGUE_KEY);
        if (cru === null) return;
        const vivas = diagLerEntregas();
        if (!vivas.length) localStorage.removeItem(DIAG_ENTREGUE_KEY);
        else if (JSON.stringify(vivas) !== cru) localStorage.setItem(DIAG_ENTREGUE_KEY, JSON.stringify(vivas));
    } catch (e) {}
}
function diagEsquecerEntregas() {
    try { localStorage.removeItem(DIAG_ENTREGUE_KEY); } catch (e) {}
}

// ── A abertura que FECHA sem ir pro fundo ─────────────────────────────────
//
// A gravação na base é ASSÍNCRONA, e recarregar a página ou fechar a aba a
// ABORTA: o `visibilitychange` e o `pagehide` saem, a gravação começa, e a
// página morre antes de ela terminar. MEDIDO (auditoria de 2026-09-29, D2):
// recarregar perdeu a abertura em 5 de 5 e fechar em 2 de 5; ir pro fundo (o
// celular trocando de app) gravou sempre, porque ali a página segue viva. O
// caso é o do computador, e o do "recarregue e veja se volta" — justamente
// quando o que se quer ler é o diário de ANTES.
//
// Aqui, no `pagehide`, um RETRATO COMPACTO vai pro localStorage de forma
// SÍNCRONA, que é a escrita que o navegador termina com a página indo embora.
// Leva o diário, as chamadas (sem corpo) e os erros do que ainda não foi
// entregue — as capturas NÃO: ~150 KB cada, elas vão pra base na hora em que
// são feitas, com a página viva. Tem TETO: passando dele, sai o mais VELHO do
// diário primeiro (o que interessa é o fim, logo antes de fechar), e o retrato
// diz quanto cortou. A abertura seguinte, com o modo dev ligado, o junta ao que
// a base tinha da mesma abertura e apaga a chave (`diagCarregarAberturas`).
//
// Uma chave POR ABERTURA (o id no nome): numa chave só, duas abas fechando
// juntas escreveriam uma por cima da outra, e ler-e-regravar no `pagehide` é o
// pior lugar pra uma corrida.
//
// Só com o modo dev LIGADO: desligado, sai na primeira linha e nada é escrito.
// Sai no "Sair" e ao desligar o modo dev (`dlogApagar`) e na abertura com ele
// desligado (`diagFaxinaSemModoDev`); entregue, vale o prazo da base (24 h).
const DIAG_RETRATO_KEY = 'waze_places_diag_retrato';
// Em caracteres. É uma escrita SÍNCRONA no `pagehide` e divide o localStorage
// com o resto do app (histórico, fila de saída…). MEDIDO (2026-09-30): 12 ações
// de uso real dão um retrato de 6 K; com os anéis CHEIOS (as 920 entradas dos
// dois diários, 60 chamadas e 50 erros: 119 K) o corte leva as 498 mais velhas
// do diário e grava 64 K em 2,6 ms — 12,7 ms com a CPU 6× mais lenta. Com o
// modo dev desligado, nada: sai na primeira linha.
const DIAG_RETRATO_TETO = 64 * 1024;

// O retrato pronto pra gravar: o registro da abertura SEM as capturas, cortado
// ao teto. `null` quando não há nada a guardar, ou quando nem cortado cabe.
function diagRetratoCompacto(reg, teto) {
    const { momentos, ...resto } = reg || {};
    const r = { ...resto, retrato: true };
    const listas = ['diario', 'chamadas', 'erros'];
    for (const nome of listas) r[nome] = Array.isArray(r[nome]) ? r[nome] : [];
    if (!listas.some((nome) => r[nome].length)) return null;
    let texto = JSON.stringify(r);
    if (texto.length <= teto) return texto;
    // Corta do mais VELHO (as listas estão em ordem de tempo), e o diário
    // primeiro: é ele que cresce; chamadas e erros têm anel curto. A folga de
    // 300 é a dos campos `cortados` e `cortadosDesde`, que entram depois da conta.
    let sobra = texto.length - (teto - 300);
    const cortados = {}, cortadosDesde = {};
    for (const nome of listas) {
        const l = r[nome];
        let i = 0;
        while (sobra > 0 && i < l.length) { sobra -= JSON.stringify(l[i]).length + 1; i++; }
        if (i) { r[nome] = l.slice(i); cortados[nome] = i; cortadosDesde[nome] = l[0].t; }
        if (sobra <= 0) break;
    }
    // Cortado até esvaziar, não sobra o que guardar.
    if (!listas.some((nome) => r[nome].length)) return null;
    // `cortadosDesde`: a hora do PRIMEIRO cortado. É com ela que a junção com a
    // base conta quantos dos cortados a base já tinha (`diagJuntarRetrato`).
    r.cortados = cortados;
    r.cortadosDesde = cortadosDesde;
    texto = JSON.stringify(r);
    return texto.length <= teto ? texto : null;
}

// No `pagehide`, SÍNCRONO (ver acima). Nunca lança: a página está indo embora.
function diagRetratoAoSair() {
    if (!dlogLigado()) return false;
    try {
        // O modo dev pela FONTE, como na gravação da base: desligado noutra
        // aba (o aviso ainda não chegou aqui), nada vai pro aparelho.
        if (modoDevDesligadoNoArmazenamento()) return false;
        const texto = diagRetratoCompacto(diagRegistroDaAbertura('saida'), DIAG_RETRATO_TETO);
        if (!texto) return false;
        localStorage.setItem(DIAG_RETRATO_KEY + ':' + DIAG_ABERTURA.id, texto);
        return true;
    } catch (e) { return false; }   // cota cheia, armazenamento bloqueado: fica a gravação da base
}

// Os retratos no aparelho, com a chave e o TEXTO lidos: quem os apaga depois
// confere o texto, e a chave reescrita depois da leitura não se perde.
function diagLerRetratos() {
    const achados = [];
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k || !k.startsWith(DIAG_RETRATO_KEY + ':')) continue;
            const texto = localStorage.getItem(k);
            let r = null;
            try { r = JSON.parse(texto); } catch (e) { /* ilegível: sai sem entrar */ }
            const valido = !!r && typeof r.id === 'string' && Number.isFinite(r.salvoEm);
            achados.push({ k, texto, r: valido ? r : null });
        }
    } catch (e) { /* armazenamento bloqueado: não há retrato */ }
    return achados;
}

// Apaga os retratos LIDOS (só se o texto é o mesmo da leitura) ou, sem lista,
// todos. As chaves são juntadas antes: apagar no meio da volta muda os índices.
function diagEsquecerRetratos(lidos) {
    try {
        if (Array.isArray(lidos)) {
            for (const { k, texto } of lidos) if (localStorage.getItem(k) === texto) localStorage.removeItem(k);
            return;
        }
        const chaves = [];
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (k && k.startsWith(DIAG_RETRATO_KEY + ':')) chaves.push(k);
        }
        for (const k of chaves) localStorage.removeItem(k);
    } catch (e) { /* armazenamento bloqueado */ }
}

// Junta o retrato ao registro que a base tinha da MESMA abertura (a última
// captura ou ida pro fundo). Só a base tem as capturas; o retrato é o mais
// NOVO. Das listas fica, da base, o que é ANTERIOR ao começo do retrato (o que
// o teto cortou), e o retrato dali em diante. Base mais nova que o retrato (a
// gravação do `pagehide` chegou a terminar) já tem tudo: fica como está.
//
// O que o teto cortou (os mais VELHOS do retrato) só falta no COMEÇO quando a
// base não tinha nada antes dele. Com a base, o começo vem dela, e a falta
// fica no MEIO — entre o último dela e o primeiro do retrato —, e a triagem
// dizia "faltam no começo" com o começo ali (auditoria de 2026-10-01, R5-4-5).
// Por isso a junção troca `cortados` por `lacunas`, por lista: onde falta
// (`de` = a hora do último que ficou antes, `null` no começo; `ate` = a do
// primeiro depois) e quantos — os cortados menos os que a base tinha no mesmo
// trecho, contados desde o primeiro cortado (`cortadosDesde`; o retrato da
// versão anterior não o tem, e aí conta tudo o que a base tinha antes dele).
function diagJuntarRetrato(guardado, retrato) {
    if (guardado && !(retrato.salvoEm > guardado.salvoEm)) return guardado;
    const base = guardado || {};
    const quando = (x) => (typeof x.t === 'number' ? x.t : Date.parse(x.t));
    const primeiro = (l) => (Array.isArray(l) && l.length ? Math.min(...l.map(quando)) : null);
    const juntar = (velha, nova) => {
        const v = Array.isArray(velha) ? velha : [];
        const desde = primeiro(nova);
        if (desde === null) return v;
        return [...v.filter((x) => quando(x) < desde), ...nova];
    };
    const { cortados, cortadosDesde, ...resto } = retrato;
    const j = { ...base, ...resto,
                momentos: Array.isArray(base.momentos) ? base.momentos : [],
                diario: juntar(base.diario, retrato.diario),
                chamadas: juntar(base.chamadas, retrato.chamadas),
                erros: juntar(base.erros, retrato.erros) };
    // As lacunas da base que seguem de pé (inteiras antes do retrato); as novas
    // vêm por cima.
    const lacunas = {};
    for (const [nome, lac] of Object.entries(base.lacunas || {})) {
        const desde = primeiro(retrato[nome]);
        if (lac && desde !== null && lac.ate <= desde) lacunas[nome] = lac;
    }
    for (const [nome, n] of Object.entries(cortados || {})) {
        if (!(n > 0)) continue;
        const ate = primeiro(retrato[nome]) ?? retrato.salvoEm;
        const inicio = cortadosDesde && cortadosDesde[nome] !== undefined ? quando({ t: cortadosDesde[nome] }) : -Infinity;
        const antes = (Array.isArray(base[nome]) ? base[nome] : []).filter((x) => quando(x) < ate);
        const faltam = n - antes.filter((x) => quando(x) >= inicio).length;
        if (faltam > 0) lacunas[nome] = { n: faltam, de: antes.length ? Math.max(...antes.map(quando)) : null, ate };
    }
    delete j.lacunas;
    if (Object.keys(lacunas).length) j.lacunas = lacunas;
    return j;
}

function setupGuardaDoDiagnostico() {
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') diagGuardarAbertura('oculta');
    });
    // O retrato SÍNCRONO primeiro: é o que chega ao fim quando a página morre.
    window.addEventListener('pagehide', () => { diagRetratoAoSair(); diagGuardarAbertura('saida'); });
    // A decisão que a OUTRA aba põe na fila de saída com o card ainda nesta:
    // ANOTA, pra sentinela `pedidoDecididoNaFila` não chamá-la de falha de
    // entrada (ver `anotarDecididosPorOutraAba`), e tira da fila desta o que não
    // está na tela — vale a primeira decisão (R10-2-02, ver
    // `tirarDaFilaOQueAOutraAbaDecidiu`). Na MESMA ordem: quem sai é o anotado.
    // Roda com ou sem o modo dev, e nenhum dos dois grava nada.
    window.addEventListener('storage', (ev) => { if (ev.key === SAIDA_KEY) { anotarDecididosPorOutraAba(ev); tirarDaFilaOQueAOutraAbaDecidiu(); } });
    // O DOWNLOAD feito na outra aba levou telas e diário DESTA: contam como
    // entregues aqui, na hora (R9-4-10, ver `diagAplicarEntregues`). Só marca a
    // memória — não grava nada.
    window.addEventListener('storage', (ev) => { if (ev.key === DIAG_ENTREGUE_KEY) diagAplicarEntregues(); });
}

// ── O FAB ─────────────────────────────────────────────────────────────────
// UM gesto de toque e UM de arrasto, e nada mais. Toque = registra um momento;
// arrastar = move o botão. **Segurar NÃO faz mais nada**, e a remoção foi
// pedida pelo defeito: pressionar-e-segurar É como se pega um botão flutuante,
// então "segurar = baixar tudo" disputava com arrastar o mesmo começo de
// gesto. O owner descreveu exatamente isso — "seguro nele e parece que tem
// algo segurando" — e o diagnóstico que ele mandou tinha `momentos: 0`: ele
// nunca chegou a TOCAR, só segurava, e o que saía era o download.
// O baixar tudo continua inteiro no botão de Filtros → Avançado (`#diagBtn`),
// que é onde ele já morava antes de eu duplicá-lo aqui.
//
// Registrar VÁRIOS momentos importa porque defeito raramente é um instante: o
// que explica costuma ser "antes → ação → depois". Cada momento é leve (DOM +
// estado); o código, os caches e o ambiente entram UMA vez no relatório.

// ── ONDE O FAB NASCE ──────────────────────────────────────────────────────
//
// O owner pediu "que ele nasça no melhor lugar possível, em todos os casos".
// MEDIDO: esse lugar não existe como escolha fixa. O canto que está livre no
// card é exatamente o que tapa o ✕ do modal — em 3 de 3 celulares o FAB em
// cima à direita cobria `closeFilters` e `closeHelp` (no tablet, nenhum dos
// dois). Trocar de canto só muda de vítima.
//
// Então o canto não se escolhe: ele se MEDE, com a régua que este projeto já
// usa pra sobreposição (gotcha #26 — `elementFromPoint`, nunca retângulo, que
// os dois retângulos existem e só o hit-test diz quem recebe o dedo). A cada
// troca de camada o FAB testa os cantos na ordem de preferência e fica no
// primeiro em que nada acionável passa por baixo dele.
//
// A ordem de preferência também foi medida, não escolhida: pelo desvio-padrão
// dos pixels em 20 telas (4 aparelhos × 5 tipos de card, pedidos reais), os
// dois cantos de cima são ~3x mais vazios que qualquer outro (12,3 e 13,2
// contra 30,9 a 46,0) E são os únicos sem controle por baixo em tela nenhuma.
//
// Duas escolhas que não são gosto:
//  · **A posição do editor SEMPRE ganha.** Arrastou, fixou: a partir daí o app
//    não mexe mais. Instrumento que foge da mão é pior que instrumento no
//    lugar errado.
//  · **Nada de canto embaixo no centro.** Ali moram os toasts, em z-70 — ACIMA
//    do FAB. Não é o FAB que taparia o toast: é o toast que engoliria o toque
//    no FAB, que é justamente o defeito que já custou o "dois toques
//    registravam um momento só".
// Quanto tempo de dedo parado até o botão se dar por PEGO. 200ms é o toque
// longo curto: rápido o bastante pra não parecer travado, longo o bastante pra
// não pegar num toque comum. Toque devagar NÃO vira arrasto — quem decide é
// ter andado ou não, não o relógio.
const DEV_FAB_PEGAR_MS = 200;
const DEV_FAB_MARGEM = 12;
// Faixa de baixo reservada aos toasts/Desfazer. Não é chute: o `#notifyStack`
// se ancora em `bottom: 1rem + safe-area` e empilha caixas de ~56px.
const DEV_FAB_RESERVA_TOAST = 96;
// ORDEM = PREFERÊNCIA, e o meio caiu pro fim depois de medido. A faixa central
// é a FOTO e é a pista do polegar: MEDIDO em 4 aparelhos × 6 cards reais, o
// `meio-dir` encosta em controle de verdade (`card-image-next`, o ↗ do WME) em
// **5 de 6** cards — até 43px de um alvo de 44 —, e o `meio-esq` come a seta
// anterior em 3 a 4. O `baixo-*` fica livre em 6/6 no aparelho do owner e no
// Pixel 7, e nos dois estreitos só raspa 14px da BORDA de uma área rolável em
// 2 de 6. Trocar de lugar não tem custo: o `DEV_FAB_RESERVA_TOAST` já mantém
// essa faixa acima dos toasts.
const DEV_FAB_CANTOS = ['cima-dir', 'cima-esq', 'baixo-dir', 'baixo-esq', 'meio-dir', 'meio-esq'];
// Quem, por baixo, desqualifica um canto. Primeiro o que se TOCA: cobrir um
// controle ROUBA o dedo, e nem o esmaecido avisa.
const DEV_FAB_ACIONAVEL = 'button, a[href], input, select, textarea, label[for], [role="button"], [tabindex]:not([tabindex="-1"])';
// E o que se LÊ COMO VALOR, mesmo sem ser clicável. A regra antiga era "texto e
// foto o FAB pode cobrir, e o editor arrasta se incomodar" — ela vale pra prosa
// (nome, endereço, categoria): cortar ali ESCONDE, e a falta se percebe. Não
// vale pro placar, e a diferença não é gosto: "311" com a última coluna comida
// lê como "31" — um número inteiro, plausível e ERRADO. Cobrir prosa esconde;
// cobrir número MENTE, e ninguém arrasta o que não sabe que está errado.
// MEDIDO com a tinta (`Range.getBoundingClientRect`, não a caixa do elemento):
// no canto de cima o FAB comia 14% do "Restam" no aparelho do owner, 30% no
// iPhone SE, 13% no Pixel 7 — e 0% no Fold, onde o placar vira 2×2 e o número
// muda de lugar. Ou seja: o defeito aparecia e sumia com o aparelho.
// O marcador mora no HTML, e não como lista de ids AQUI, por um motivo: assim
// contador novo dentro do `#placar` já nasce protegido, em vez de depender de
// alguém lembrar de somá-lo a uma lista deste arquivo. E é marcador PURO — sem
// regra em CSS nenhuma —, senão reusar a classe arrastaria aparência junto
// (gotcha #56) e mexer nela deixaria de ser barato.
// Escopo de propósito ESTREITO: o placar e o "N esperando envio" (o
// `#inFlightIndicator`, que mora fora do placar — R9-4-05). As leituras curtas
// sobre a FOTO (escala do mapa, "3/5") ficam de fora porque a foto é justamente
// o que o FAB pode cobrir, e alargar o marcador até elas desqualificaria os
// cantos do meio — com a chance de não sobrar canto nenhum, que é pior que o
// defeito.
const DEV_FAB_LEITURA = '.nao-cobrir';
const DEV_FAB_EVITAR = DEV_FAB_ACIONAVEL + ', ' + DEV_FAB_LEITURA;

let devFabFixado = false;   // o editor arrastou → o app não escolhe mais
// O canto foi pedido com um GESTO no card da frente (ver `posicionarFabDev`): o
// fim do gesto o escolhe (`aoFimDoGesto`).
let fabEsperaOGesto = false;
// O ponteiro que está no botão agora (null = nenhum dedo). Módulo, e não só do
// gesto, porque o `posicionarFabDev` precisa saber se o "pego" tem dedo (D7).
let devFabDedo = null;

function devFabCoords(canto, w, h) {
    const cab = document.querySelector('header');
    const topo = (cab ? cab.getBoundingClientRect().bottom : 0) + 8;
    const x = canto.endsWith('dir') ? innerWidth - w - DEV_FAB_MARGEM : DEV_FAB_MARGEM;
    const y = canto.startsWith('cima') ? topo
            : canto.startsWith('meio') ? Math.round((innerHeight - h) / 2)
            : innerHeight - h - DEV_FAB_RESERVA_TOAST;
    return { x, y: Math.max(topo, Math.min(innerHeight - h - DEV_FAB_MARGEM, y)) };
}

// Quantas vítimas passariam por baixo do FAB neste canto — controle acionável
// ou leitura, os dois pesam igual (roubar o dedo e mentir o número são ruins do
// mesmo jeito).
//
// A GRADE VAI ATÉ A BORDA (0,02 / 0,5 / 0,98), e o recuo que havia antes era o
// defeito. A versão anterior amostrava 5 pontos com os cantos RECUADOS a 0,15 —
// e o comentário dizia, com todas as letras, que isso existia pra pegar "o alvo
// que encosta pela beirada". Não pegava: num quadro de 44px, 0,15 deixa **6,6px
// cegos** de cada lado, e é justamente aí que um vizinho encosta. MEDIDO quando
// o FAB desceu pro meio: ele invadia 6px do "›" (próxima foto), que ficava com
// 39px úteis de 44 e entregava o toque do topo AO FAB — e o amostrador de 5
// pontos via **NADA**, enquanto esta grade vê `card-image-next`. Ou seja: o
// guard tinha um ponto cego do tamanho do problema que ele existia pra achar.
// 0,02 e 0,98 são ~1px pra dentro: no limite exato o `elementFromPoint` fica
// ambíguo entre as duas caixas.
const DEV_FAB_AMOSTRAS = [0.02, 0.5, 0.98];

// Os AVISOS PASSAGEIROS — o banner do topo (o aviso da consequência, o da recusa
// automática, a dica do Desfazer) e o rodapé do toast e do Desfazer — não
// decidem o canto: o FAB mede o que fica POR BAIXO deles. O banner é uma caixa
// sem nada acionável e sem `.nao-cobrir`, e lido como o que está no ponto ele
// fazia o `cima-dir` passar por LIVRE com o placar ali embaixo: tocado com o
// banner na tela, o FAB ia pra cima do "Restam" e FICAVA lá depois de o banner
// sair, porque nada reavalia o canto quando um aviso some (R7-4-01, MEDIDO: 21%
// da tinta de "310" coberta a 390×844, 30% no iPhone SE, o mesmo no WebKit). O
// rodapé é o espelho: o "Desfazer" é um botão, e espantava o FAB pra um canto
// pior, onde ele ficava depois de a janela fechar. O aviso some sozinho; o que
// está por baixo dele é o que o FAB vai cobrir depois.
const DEV_FAB_PASSAGEIROS = '#bannerStack, #notifyStack';

// O que recebe o dedo no ponto sem o próprio FAB e sem os avisos passageiros.
// Pela PILHA do ponto (`elementsFromPoint`, de cima pra baixo), e não tirando
// os avisos do hit-test pelo `pointer-events`: o filho de um aviso que traga o
// próprio `pointer-events-auto` escaparia do ajuste no contêiner (é o que o
// botão do FAB faz com o dele, ver abaixo).
function devFabSob(px, py, fab) {
    const pilha = typeof document.elementsFromPoint === 'function'
        ? document.elementsFromPoint(px, py) : [document.elementFromPoint(px, py)];
    for (const el of pilha) {
        if (!el || fab.contains(el)) continue;
        if (el.closest && el.closest(DEV_FAB_PASSAGEIROS)) continue;
        return el;
    }
    return null;
}

function devFabVitimas(canto, w, h, fab) {
    const { x, y } = devFabCoords(canto, w, h);
    const vitimas = new Set();
    const pontos = [];
    for (const fx of DEV_FAB_AMOSTRAS) for (const fy of DEV_FAB_AMOSTRAS) pontos.push([fx, fy]);
    for (const [fx, fy] of pontos) {
        const sob = devFabSob(x + w * fx, y + h * fy, fab);
        const alvo = sob && sob.closest(DEV_FAB_EVITAR);
        // O próprio FAB nunca conta como vítima. A segunda condição não é
        // paranoia: `pointer-events: none` no contêiner NÃO tira o botão do
        // hit-test, porque ele traz `pointer-events-auto` — e sem esta linha o
        // FAB media a si mesmo, achava o canto onde já estava sempre ocupado e
        // fugia dele a cada troca de camada.
        if (alvo && !fab.contains(alvo)) vitimas.add(alvo);
    }
    // O NÚMERO menor que a grade (R9-4-05). A grade amostra 3 linhas a 0,02, 0,5 e
    // 0,98 da altura — num FAB de 44 px, a 1, 22 e 43 px —, e o "N esperando
    // envio" tem 17 px de altura: no computador e no tablet ele cabia INTEIRO
    // entre a 1ª e a 2ª linha, nenhum ponto o tocava, e o FAB o cobria 100% com
    // o canto lido como livre (MEDIDO a 1280×800 e 768×1024, já com o
    // `.nao-cobrir` nele). Pra o que se LÊ (`DEV_FAB_LEITURA`), o que vale é a
    // INTERSEÇÃO com o canto — cobrir parte de um número já mente —, e quem
    // decide se ele está mesmo À VISTA ali é o hit-test no meio da sobreposição,
    // pelo mesmo `devFabSob` da grade: atrás de um modal ele não é vítima, como
    // o placar não é (o teste da camada que segue decidindo o canto).
    for (const el of document.querySelectorAll(DEV_FAB_LEITURA)) {
        if (vitimas.has(el)) continue;
        const r = el.getBoundingClientRect();
        const x0 = Math.max(x, r.left), x1 = Math.min(x + w, r.right);
        const y0 = Math.max(y, r.top), y1 = Math.min(y + h, r.bottom);
        if (x1 <= x0 || y1 <= y0) continue;
        const sob = devFabSob((x0 + x1) / 2, (y0 + y1) / 2, fab);
        if (sob && el.contains(sob)) vitimas.add(el);
    }
    return vitimas.size;
}

function posicionarFabDev() {
    const fab = document.getElementById('devFab');
    if (!fab || devFabFixado || fab.classList.contains('hidden')) return;
    // Com um GESTO no card da frente — o dedo nele, a volta pro lugar, a saída —
    // a tela é a do MEIO do gesto: o card deslocado deixa à mostra o canto que,
    // parado, ele cobre. Medido assim, o FAB ia pro canto que o card deslocado
    // liberava e FICAVA lá (o indicador sumindo com o card seguinte arrastado:
    // `baixo-dir` → `baixo-esq`, auditoria da rodada 10, R10-4-05). A escolha
    // espera o card parar (`aoFimDoGesto`) — a mesma regra da captura do
    // arraste, que só acerta o número (`reposicionar: false`).
    if (cardSobGesto(cardDaFrente())) { fabEsperaOGesto = true; return; }
    fabEsperaOGesto = false;
    // Pego (segurado, sem ter andado ainda): não se mexe debaixo do dedo. Mas só
    // com um DEDO de verdade no botão: o "pego" que sobrou sem dedo (o relógio
    // órfão de dois dedos) travava o botão ali pra sempre — crescido, parado,
    // por cima do "Aplicar" dos Filtros (auditoria de 2026-09-26, D7). Sai aqui.
    if (fab.classList.contains('fab-pego')) {
        if (devFabDedo !== null) return;
        fab.classList.remove('fab-pego');
    }
    const r = fab.getBoundingClientRect();
    const w = r.width || 44, h = r.height || 44;
    // O FAB inteiro sai do hit-test durante a medição — contêiner E botão —
    // senão ele não enxerga o que está POR BAIXO de si mesmo.
    const btn = document.getElementById('devFabBtn');
    const antes = fab.style.pointerEvents, antesBtn = btn ? btn.style.pointerEvents : '';
    fab.style.pointerEvents = 'none';
    if (btn) btn.style.pointerEvents = 'none';
    let melhor = DEV_FAB_CANTOS[0], menos = Infinity;
    try {
        for (const canto of DEV_FAB_CANTOS) {
            const n = devFabVitimas(canto, w, h, fab);
            if (n < menos) { melhor = canto; menos = n; }
            if (n === 0) break;   // ordem = preferência: o primeiro livre ganha
        }
    } finally {
        fab.style.pointerEvents = antes;
        if (btn) btn.style.pointerEvents = antesBtn;
    }
    const { x, y } = devFabCoords(melhor, w, h);
    fab.style.left = x + 'px'; fab.style.top = y + 'px';
    fab.style.right = 'auto'; fab.style.bottom = 'auto';
    fab.dataset.canto = melhor;
}

// `reposicionar: false` só acerta o número (a captura no meio de um arraste não
// pode mudar o botão de canto debaixo do gesto).
function atualizarFabDev({ reposicionar = true } = {}) {
    const fab = document.getElementById('devFab');
    if (!fab) return;
    const ligado = typeof AppState !== 'undefined' && !!(AppState.devMode && AppState.devMode.active);
    fab.classList.toggle('hidden', !ligado);
    const selo = document.getElementById('devFabBadge');
    if (selo) {
        // Só as que a pessoa fez — ver `dlogCapturasDoEditor` —, desta abertura
        // e das anteriores que ficaram guardadas: o número é "o que vai no
        // próximo relatório", e ele tem que sobreviver a fechar o app.
        const n = dlogCapturasDoEditor().length + diagCapturasAnterioresDoEditor().length;
        selo.textContent = String(n);
        selo.classList.toggle('hidden', n === 0);
    }
    if (ligado && reposicionar) posicionarFabDev();
}

function ligarFabDev() {
    const btn = document.getElementById('devFabBtn');
    if (!btn) return;
    const fab = document.getElementById('devFab');

    // ── PEGAR E ARRASTAR ──────────────────────────────────────────────────
    //
    // Como o arrastar em mobile TEM que ser, e eu tinha errado o modelo antes
    // de errar o código: **segurar É o jeito de pegar**. Ícone da tela
    // inicial, bolha do Android, AssistiveTouch do iOS — em todos você
    // pressiona, o elemento AVISA que foi pego, e a partir dali ele acompanha
    // o dedo. O que existia aqui era o contrário: segurar disparava OUTRA
    // coisa (baixar tudo) e arrastar só valia se o dedo saísse na hora. O
    // owner descreveu o resultado exato — "seguro nele e parece que tem algo
    // segurando" — e o diagnóstico dele veio com `momentos: 0`: ele nunca
    // chegou a tocar, só segurava.
    //
    // Agora:
    //   · segurou `DEV_FAB_PEGAR_MS` → PEGOU (o botão cresce e vibra), e daí
    //     acompanha o dedo;
    //   · saiu andando antes disso → pega na hora, sem esperar;
    //   · soltou sem ter andado → é toque, registra um momento (não importa
    //     quanto tempo segurou — toque devagar continua sendo toque).
    //
    // E o gesto precisa de QUATRO defesas, nenhuma opcional. A prova de que é
    // assim está no próprio projeto: o swipe do card, que comprovadamente
    // funciona no aparelho dele, tem `touch-action: none` **e**
    // `user-select: none` juntos em `.place-card`. Eu tinha dado só o primeiro.
    //   1. `touch-none` (index.html) — sem ele o navegador reivindica o gesto
    //      como rolagem ao passar do próprio limiar e CANCELA o ponteiro.
    //      MEDIDO: dos 20 movimentos de dedo despachados chegava UM.
    //   2. `select-none` (index.html) — o selo do botão é TEXTO, e segurar em
    //      texto no Android começa uma seleção, que também cancela o ponteiro.
    //   3. `-webkit-touch-callout: none` (styles.css) — mata o balão de
    //      "abrir/copiar" do toque longo, que não tem utility no Tailwind.
    //   4. `contextmenu` barrado aqui — o toque longo do Android dispara esse
    //      evento, e o menu que ele abre leva o gesto embora.
    //
    // Ouvir na `window` e não capturar o ponteiro é a regra do gotcha #56.
    // Desenhar por QUADRO também: `pointermove` chega a 120Hz e escrever
    // `left/top` a cada um é layout jogado fora.
    // `dedo`: o ponteiro que PEGOU. Sem ele, qualquer outro dedo na tela movia o
    // FAB e o soltar de qualquer um encerrava o gesto — a mesma armadilha do
    // `dragTouchId` do swipe (auditoria de 2026-09-25).
    let pego = false, arrastou = false, dx = 0, dy = 0, quadro = 0, alvo = null, relogio = null;
    const desenhar = () => {
        quadro = 0;
        if (!alvo) return;
        fab.style.left = alvo.x + 'px'; fab.style.top = alvo.y + 'px';
        fab.style.right = 'auto'; fab.style.bottom = 'auto';
    };
    // O AVISO de que pegou é o que faltava por inteiro: sem ele não há como
    // saber se o app agarrou o botão ou se o toque se perdeu — e "parece que
    // tem algo segurando" é exatamente a descrição de um gesto sem retorno.
    // São dois canais de propósito (WCAG 1.4.1 — sinal não pode viver só num):
    // o botão CRESCE e o aparelho VIBRA.
    // Pegar NÃO fixa: só ARRASTAR fixa (ver `mover`). Um toque devagar — segurou
    // e soltou sem andar — é toque, e fixar ali deixava o botão parado pra
    // sempre, sem nunca mais sair de cima do que viesse a cobrir.
    const pegar = () => {
        if (pego) return;
        pego = true;
        fab.classList.add('fab-pego');
        try { navigator.vibrate && navigator.vibrate(12); } catch (e) {}
    };
    const soltarPega = () => {
        pego = false;
        fab.classList.remove('fab-pego');
    };
    btn.addEventListener('contextmenu', (e) => e.preventDefault());
    btn.addEventListener('pointerdown', (e) => {
        // O gesto é DESTE ponteiro: `mover` e `fim` só atendem a ele. (Travar um
        // segundo `pointerdown` foi descartado: um `pointerup` perdido — soltar
        // fora da janela — deixaria o botão surdo pra sempre.)
        // UM relógio por gesto: o segundo dedo sobrescrevia o relógio do
        // primeiro SEM cancelá-lo, e o órfão "pegava" o botão depois que os dois
        // dedos já tinham saído (auditoria de 2026-09-26, D7).
        if (relogio) { clearTimeout(relogio); relogio = null; }
        const meu = e.pointerId;
        devFabDedo = meu;
        arrastou = false;
        const r = fab.getBoundingClientRect();
        dx = e.clientX - r.left; dy = e.clientY - r.top;
        fab.style.transition = 'none';   // dedo e transição brigando = botão escorregando
        relogio = setTimeout(pegar, DEV_FAB_PEGAR_MS);
        const mover = (ev) => {
            if (ev.pointerId !== meu) return;
            if (!pego && Math.hypot(ev.clientX - e.clientX, ev.clientY - e.clientY) < 8) return;
            if (relogio) { clearTimeout(relogio); relogio = null; }
            pegar();
            arrastou = true;
            devFabFixado = true;
            if (ev.cancelable) ev.preventDefault();
            alvo = {
                x: Math.min(innerWidth - r.width - 4, Math.max(4, ev.clientX - dx)),
                y: Math.min(innerHeight - r.height - 4, Math.max(4, ev.clientY - dy)),
            };
            if (!quadro) quadro = requestAnimationFrame(desenhar);
        };
        // `pointercancel` tem que desmontar igual ao `pointerup`. Sem isto o
        // gesto cancelado deixava `mover` e `fim` pendurados na window PRA
        // SEMPRE — a cada toque sobrava mais um par, todos escrevendo a mesma
        // posição a partir de coordenadas velhas.
        const fim = (ev) => {
            if (ev && ev.pointerId !== meu) return;
            if (devFabDedo === meu) devFabDedo = null;
            removeEventListener('pointermove', mover);
            removeEventListener('pointerup', fim);
            removeEventListener('pointercancel', fim);
            if (relogio) { clearTimeout(relogio); relogio = null; }
            if (quadro) { cancelAnimationFrame(quadro); quadro = 0; desenhar(); }
            fab.style.transition = '';
            soltarPega();
            if (arrastou) {
                try { sessionStorage.setItem('__devFabPos', fab.style.left + '|' + fab.style.top); } catch (er) {}
            }
            alvo = null;
        };
        addEventListener('pointermove', mover, { passive: false });
        addEventListener('pointerup', fim);
        addEventListener('pointercancel', fim);
    });

    // ── TOCAR: registra um momento ────────────────────────────────────────
    // A distinção é ANDOU ou não andou, nunca o tempo: toque devagar continua
    // sendo toque, e é o que impede que segurar sem querer vire um beco.
    // `pointerup` e não `click` porque, com captura implícita, o clique nem
    // sempre chega quando o dedo saiu do botão.
    const soltar = (ev) => {
        if (arrastou) return;   // arrastar não é tocar
        if (ev && devFabDedo !== null && ev.pointerId !== devFabDedo) return;
        capturar();
    };
    btn.addEventListener('pointerup', soltar);
    // TECLADO: Enter e Espaço num <button> disparam `click` (com `detail` 0) e
    // nunca `pointerup` — o botão existia pro Tab e não fazia nada (auditoria de
    // 2026-09-25). O clique do dedo tem `detail` ≥ 1 e já passou pelo `soltar`.
    btn.addEventListener('click', (e) => { if (e.detail === 0) capturar(); });
    function capturar() {
        const m = dlogCapturar('manual');
        atualizarFabDev();
        // SEM toast, e o motivo é o próprio instrumento: o toast vive em z-70,
        // acima do FAB, e MEDIDO ele engolia o toque seguinte — dois toques
        // registravam um momento só. Pior: ele entrava na captura seguinte, ou
        // seja o instrumento passava a medir a si mesmo. O selo do botão já diz
        // quantos há, e o pulso dá o retorno sem cobrir nada.
        if (m) {
            btn.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.25)' }, { transform: 'scale(1)' }],
                        { duration: 220, easing: 'ease-out' });
        }
    }

    // ── Quando reavaliar o canto ──────────────────────────────────────────
    //
    // Observador nos ELEMENTOS de camada, e não chamada espalhada em cada
    // abrir/fechar: modal fecha por três caminhos (botão, Esc, scrim) e o
    // lightbox por mais alguns — amarrar a um deles deixa os outros vazando, o
    // gotcha dos modais deste projeto. Aqui o gatilho é o próprio `hidden`
    // mudando, então nenhum caminho novo precisa lembrar de avisar.
    //
    // `filter(Boolean)` some com id errado SEM DIZER NADA, e foi o que
    // aconteceu: escrevi `lightbox` e o elemento se chama `imageLightbox`, então
    // o lightbox de foto simplesmente não era vigiado. `test/diagnostico.test.mjs`
    // cobra que todo id desta lista exista no index.html.
    // E os PAINÉIS da fila vazia: a falha de carga e o "Tudo limpo!" (com o
    // convite de instalar dentro) aparecem SEM mexer em modal, lightbox ou tela
    // — o FAB ficava onde estava, na borda do "Tentar de novo", do "Instalar"
    // e do "Agora não" (auditoria de 2026-09-26, D8).
    const DEV_FAB_CAMADAS = [...MODAL_IDS, 'imageLightbox', 'mapaLightbox', 'appScreen', 'authScreen',
                             'loadErrorState', 'noMoreCards', 'installInvite'];
    const camadas = DEV_FAB_CAMADAS.map((id) => document.getElementById(id)).filter(Boolean);
    let pendente = 0;
    const reavaliar = () => {
        if (pendente) return;
        pendente = requestAnimationFrame(() => { pendente = 0; posicionarFabDev(); });
    };
    if (camadas.length) {
        const obs = new MutationObserver(reavaliar);
        for (const el of camadas) obs.observe(el, { attributes: true, attributeFilter: ['class'] });
    }
    addEventListener('resize', () => {
        // Fixado, o FAB não se remove do lugar — mas precisa continuar DENTRO
        // da tela quando ela gira ou encolhe, senão some pra fora sem volta.
        if (!devFabFixado) return reavaliar();
        const r = fab.getBoundingClientRect();
        fab.style.left = Math.min(innerWidth - r.width - 4, Math.max(4, r.left)) + 'px';
        fab.style.top = Math.min(innerHeight - r.height - 4, Math.max(4, r.top)) + 'px';
    });

    try {
        const pos = sessionStorage.getItem('__devFabPos');
        if (pos) {
            // DENTRO da tela: a posição foi gravada noutra orientação (retrato →
            // paisagem) e voltava fora dela, sem `resize` pra corrigir. 56px é o
            // maior tamanho do botão (pego); o `resize` acerta o resto.
            const [x, y] = pos.split('|').map((v) => parseFloat(v));
            if (Number.isFinite(x) && Number.isFinite(y)) {
                fab.style.left = Math.max(4, Math.min(innerWidth - 60, x)) + 'px';
                fab.style.top = Math.max(4, Math.min(innerHeight - 60, y)) + 'px';
                fab.style.right = 'auto'; fab.style.bottom = 'auto';
                devFabFixado = true;
            }
        }
    } catch (e) {}
}

// ── Diagnóstico: baixa TUDO que existe do lado do cliente ──────────────────
//
// Pedido do owner, depois de horas em que eu adivinhei o defeito do aparelho
// dele em vez de olhar. O botão vive atrás do modo dev e gera UM arquivo.
//
// DUAS COISAS QUE ELE **NÃO** CONSEGUE TRAZER, e é honesto dizer no próprio
// arquivo em vez de deixar a pessoa procurar:
//
//  1. Os cookies do WAZE. Eles são de `waze.com`, outra origem — o JavaScript
//     desta página não os enxerga, por regra do navegador, e nem existem aqui:
//     depois do login eles vivem CIFRADOS no servidor e nunca mais voltam ao
//     aparelho. O que dá pra trazer é `document.cookie` desta origem.
//  2. O corpo do que o Service Worker guardou de OUTRA origem (tiles do Waze):
//     a resposta é opaca. As URLs vêm; o conteúdo, não.
//
// O QUE ELE TRAZ, e o peso disso: o `waze_session_token` vai INTEIRO. Ele é
// credencial viva — quem tiver o arquivo pode agir na conta do Waze do dono até
// a sessão vencer, e é METADE da chave que decifra os cookies no servidor (ver
// `derivarChave`). Foi pedido assim de propósito, porque é ele que permite
// REPRODUZIR a falha em vez de teorizar. O arquivo diz isso na primeira linha,
// e o caminho de anular é sair do app, que destrói a sessão no servidor.
// 3 (v2026.09.22-03): entraram a seção `offline`, `serviceWorker.proprio` (o
// worker respondendo sobre si), `recursosInfo`, `rede`/`offline` em cada
// momento e `tiles` na geometria do mapa. Aditivo: leitor antigo só ignora.
// 4 (v2026.09.22-05): cada momento leva `computado` + `alertas` do instante e
// `cardMontado`; o resumo ganha `alertasNasCapturas`. Aditivo também.
// 5 (v2026.09.22-06): o resumo ganha `saida` (a fila de saída em números), o
// `computado` ganha `decididos` (e a sentinela `pedidoDecididoNaFila`), e a
// seção `offline` ganha `pousosGravados` e o `desdeMin` da fila guardada. E o
// arquivo passa a levar as ABERTURAS ANTERIORES guardadas no aparelho
// (`aberturasAnteriores`, `aberturaAtual`, e no resumo a contagem e os alertas
// das capturas delas, com a `abertura` de cada uma). Aditivo.
// 6 (v2026.09.23-03): o resumo ganha `presencaWme` (a presença no mapa do WME,
// de carona nas ações): ligada, já vista ligada, escritas, falhas e se a marca
// de quem está no app voltou diferente. Aditivo.
// 7 (v2026.09.24-01): o resumo ganha `presencaApp` (a lista e o chat do app,
// fase 3: quantos no app, conversas, não lidas, o token e o tempo real — só
// CONTAGENS), e o `dom` (do relatório e de cada captura) sai SEM a conversa e
// sem a prévia da lista (`domParaDiagnostico`), com a contagem do que saiu.
// 8 (v2026.09.24-02), pra entender os relatos da fase 3 — e sem filtro de
// privacidade, que não é critério no modo dev (decisão do owner):
//   · o `dom` volta INTEIRO (a conversa e a lista entram);
//   · o anel de chamadas guarda a resposta de `chat` e `presenca-app` (o token e
//     a chave do tempo real saem como marcador), e o texto que se manda;
//   · o diário ganha a linha do tempo da presença e do chat (`presenca.lista`,
//     `presenca.token`, `presenca.fluxo`, `chat.abrir`, `chat.envio`,
//     `chat.chegou`, `presencaWme.visivel`, `presencaWme.falhou`);
//   · o `presencaApp` ganha `contagem` (o PORQUÊ da lista, contado no servidor)
//     e o `fluxoDiag`, as mensagens ignoradas e as quedas seguidas; o
//     `presencaWme` ganha o que o perfil disse da visibilidade;
//   · o `codigo` perde o corpo (menos do CSS): fica tamanho, hash e versão.
// 9 (v2026.09.25-05): o `cacheVsRede` compara SEM o script que a borda injeta no
// HTML (`borda: true` quando o descontou; ver `diagSemInjecaoDaBorda`), e a
// geometria leva a caixa de layout (`cw/ch/ow/oh`), que o arraste não gira nem
// encolhe. Aditivo.
// 10: `resumo.falhas` e `rotasQueFalharam` não contam mais o "já tratado"
// (`already_processed`/`not_found`, que pro app é sucesso); ele vai em
// `resumo.jaTratadas`. Relatório anterior ao v10 soma os dois em `falhas`.
// 11 (auditoria de 2026-09-26): a `coleta` (quanto o relatório levou, o
// orçamento e o que ficou `semResposta`); a `variante` do painel na captura e
// no resumo, e `pulados`/`tratou` no `tela.vazia`; o `sobAviso` na geometria (o
// aviso passageiro por cima de um botão não é toque interceptado); o toast
// SENSÍVEL no diário sem o texto; e a hora (`quando`) no alerta do tile
// guardado que falhou. Aditivo.
const DIAG_VERSAO = 11;

// O Cloudflare INJETA no HTML, a cada resposta, o script do Bot Fight Mode com
// token e hora próprios (`window.__CF$cv$params={r:…,t:…,u:…,ut:…}`, antes do
// `</body>`). MEDIDO em produção em 2026-09-25: duas respostas seguidas do `/`,
// mesmo tamanho, 180 posições diferentes, TODAS dentro dele. Comparado com ele, o
// `/` saía "DIFERENTE" em todo relatório de produção e o leitor concluía "versão
// velha no cache" — alarme falso na seção que responde justamente isso. O script
// não é nosso; a pergunta é se o NOSSO código é o mesmo. Casa só a forma
// injetada (`<script>` sem atributo que começa pelo `__CF$cv$params`); o bootstrap
// continua bloqueado pela CSP de qualquer jeito (gotcha #14).
const DIAG_INJECAO_DA_BORDA = /<script>window\.__CF\$cv\$params=[\s\S]*?<\/script>/g;
function diagSemInjecaoDaBorda(txt) {
    return String(txt).replace(DIAG_INJECAO_DA_BORDA, '');
}

// O `codigo` do relatório, ENXUTO: o CORPO fica só no CSS, que é de onde o
// `tools/diag-tela.mjs` tira o estilo exato do aparelho pra remontar a tela. Do
// resto bastam o tamanho, o hash (a MESMA função do `cacheVsRede`, pra os dois
// se compararem) e a versão quando o arquivo a declara — é o que responde "este
// aparelho roda versão velha, ou misturada?". MEDIDO no relatório real de
// v2026.09.24-02: o JS e o HTML inteiros eram 580 KB de 1,9 MB, e ~166 KB dos
// 382 KB do .zip — quase metade do que a pessoa manda. Roda DEPOIS do
// `cacheVsRede`, que precisa do corpo pra comparar com a rede.
//
// O hash é do corpo SEM o que a BORDA injeta (`diagSemInjecaoDaBorda`): é a mesma
// régua do `cacheVsRede`, e o `/` precisa dela pra não diferir sempre.
async function diagCodigoEnxuto(codigo, hash) {
    for (const u of Object.keys(codigo)) {
        const c = codigo[u];
        if (!c || typeof c.corpo !== 'string') continue;
        c.bytes = c.corpo.length;
        c.hash = await hash(diagSemInjecaoDaBorda(c.corpo));
        const v = /APP_VERSION\s*=\s*['"]?(\d{10})/.exec(c.corpo) || /waze-places-(\d{10})/.exec(c.corpo);
        if (v) c.versao = v[1];
        if (!/\.css(\?|$)/.test(u)) delete c.corpo;
    }
    return codigo;
}

// O HTML da página pro diagnóstico, INTEIRO: a conversa aberta e a lista de
// presença entram. O relatório e as capturas só existem com o modo dev ligado, e
// ali privacidade não é critério (decisão do owner, 2026-09-24). Até v2026.09.24-02
// as duas saíam vazias, e um relato de "a mensagem ficou como não enviada"
// chegaria sem a mensagem na tela. Fica como FONTE ÚNICA da cópia — o relatório
// e cada captura passam por aqui —, pra que o dia em que algo precisar sair seja
// um lugar só.
//
// A ÚNICA coisa que sai é o SEGREDO do pareamento: ele vale uma sessão nova por
// 5 minutos e não depura nada (auditoria de 2026-09-25) — ver
// `diagSemSegredoDePareamento`.
function domParaDiagnostico() {
    return diagSemSegredoDePareamento(document.documentElement.outerHTML);
}

// Tira do texto TODO segredo de pareamento que ESTE aparelho emitiu nesta página
// (`pareamentosEmitidos`: o do QR e o digitável, este também na forma que a tela
// mostra). Era pelo `data-raw` do modal, e isso só valia com o modal ABERTO: o
// link `/#pair=<segredo>` que vira o toast copiável (quando a área de
// transferência falha) segue na tela depois de o modal fechar — e fechar APAGA o
// `data-raw` —, então a captura seguinte levava o segredo no `dom` e na lista de
// toasts, pro relatório e pra cópia guardada (auditoria de 2026-09-26, D1). O
// `data-raw`/`data-curto` ficam como defesa a mais.
function diagSemSegredoDePareamento(texto) {
    let saida = String(texto);
    try {
        const formas = new Set();
        const junta = (c) => {
            if (!c) return;
            formas.add(String(c));
            const fmt = formatarCodigoPareamento(c);
            if (fmt && fmt !== String(c) && fmt.length > 4) formas.add(fmt);
        };
        for (const c of pareamentosEmitidos) junta(c);
        const el = document.getElementById('pairCode');
        if (el) { junta(el.dataset.raw); junta(el.dataset.curto); }
        // As mais LONGAS primeiro: o curto (6) não pode comer o pedaço de um maior.
        for (const forma of [...formas].sort((a, b) => b.length - a.length)) {
            saida = saida.split(forma).join('[código de pareamento]');
        }
    } catch (e) { /* sem o modal (ou numa página de teste): nada a tirar */ }
    return saida;
}

// JSON de coisa viva: `AppState` tem Promise, função e referência circular
// (`currentPlace` é o mesmo objeto de `queue[0]`). Sem isto o `stringify` lança
// e o arquivo sai vazio — falha silenciosa no instrumento de socorro.
//
// `[circular]` é só o que está no CAMINHO até aqui (os ancestrais), não tudo o
// que já foi visto: o mesmo objeto em dois lugares da árvore não é ciclo, e marcá-lo
// escondia a segunda ocorrência. E o fundo é 12: com 8 a coordenada de uma
// entrada proposta (`queue[i].changes[j].delta.add[k].point.coordinates`, nível 9)
// saía `[fundo]` — justamente o dado de um pedido de entrada (auditoria de
// 2026-09-25).
const DIAG_FUNDO = 12;
function diagSeguro(v, prof = 0, vistos = new WeakSet()) {
    if (v === null || typeof v !== 'object') {
        return typeof v === 'function' ? '[função]' : v;
    }
    if (vistos.has(v)) return '[circular]';
    if (prof > DIAG_FUNDO) return '[fundo]';
    if (v instanceof Promise) return '[promise]';
    if (typeof Element !== 'undefined' && v instanceof Element) return '[elemento ' + v.tagName + ']';
    if (v instanceof Map) return { '[Map]': [...v.keys()].map(String) };
    if (v instanceof Set) return { '[Set]': [...v].map(String) };
    vistos.add(v);
    try {
        if (Array.isArray(v)) return v.map((x) => diagSeguro(x, prof + 1, vistos));
        const o = {};
        for (const k of Object.keys(v)) {
            try { o[k] = diagSeguro(v[k], prof + 1, vistos); } catch (e) { o[k] = '[erro: ' + e.message + ']'; }
        }
        return o;
    } finally {
        vistos.delete(v);
    }
}

// Erros de JS acumulados desde a carga. Armado cedo, no `initApp`.
const diagErros = [];
// ── O teto da lista de RECURSOS ───────────────────────────────────────────
// O navegador guarda só 250 entradas de Resource Timing e DESCARTA o que vem
// depois. No relato de 2026-09-22 tiles e fotos da varredura ocuparam 230 das
// 250 vagas, e o que aconteceu depois — o card sem sinal, a parte que
// interessava — não entrou. Com o modo dev ligado o teto sobe; desligado fica
// o padrão, que é de graça. Cada entrada é pequena (URL, duração, bytes).
const DIAG_RECURSOS_TETO = 1000;
let diagRecursosCheio = false;
function diagAjustarRecursos() {
    try {
        if (dlogLigado() && performance.setResourceTimingBufferSize) {
            performance.setResourceTimingBufferSize(DIAG_RECURSOS_TETO);
        }
    } catch (e) { /* navegador sem a API: fica o padrão */ }
}

// ── De QUEM é o que a página REGISTROU: a lista de recursos e o anel de chamadas
// O relatório leva as duas. A lista de recursos do navegador guarda a URL da
// foto de perfil (com o id de quem estava aqui) e as fotos dos pedidos de
// terceiros (o id do pedido vai no nome); o anel de chamadas (`API.chamadas`)
// guarda o corpo de cada pedido ao servidor. O "Sair" e a troca de conta as
// LIMPAM — e só limpar não bastava: o que ainda estava no ar termina DEPOIS da
// limpeza e entra de novo. MEDIDO com a foto do card chegando em 4 s e o "Sair"
// no meio: a lista sai vazia e, 6 s depois, tem a foto de novo — que ia no
// relatório da próxima conta que entrasse na mesma página (auditoria de
// 2026-10-03, R8-1-04; a troca de conta nem limpava, R8-1-05). E o ✕ no ar no
// "Sair" registrava DEPOIS, com o id do pedido de terceiro e a posição e o id de
// quem saiu na carona da presença (pista do lote 12, L12-1).
//
// CORTAR o download não resolve: tirar o `src` do <img> (ou trocá-lo por '') não
// cancela a ida do navegador, e a entrada volta igual — MEDIDO no Chromium 153 e
// no WebKit 26, com a <img> no DOM, fora dele e solta (`new Image()`). O que
// separa o que era de quem saiu é QUANDO a ida COMEÇOU: o `startTime` da entrada
// tardia é anterior à limpeza (medido nos dois motores; a que começa depois tem o
// `startTime` depois), e o início de cada chamada o `_post` já mede. Daí UMA
// marca (`API.registrosDesde`) pras duas listas: o relatório só leva o recurso
// que começou depois dela (`diagRecursosDaSessao`), e o anel não registra a
// chamada que começou antes (`API._registrar`), termine quando terminar.
//
// `ficaASessao` (a marca da sessão, ver `marcaDaSessao`) é a da TROCA DE CONTA:
// o login ou o perfil que a revela já é de quem ENTROU, e o que essa sessão fez
// fica — no anel (`deixarSoAsChamadasDaSessao`) e na regra do instante, pra
// chamada dela que ainda estava no ar (R10-1-02). O "Sair" não deixa nenhuma.
// A lista de recursos do navegador não diz de que sessão cada entrada é, e
// segue cortada pelo instante.
function esquecerRegistrosDaPagina(ficaASessao = null) {
    try {
        API.registrosDesde = performance.now();
        API.registrosDaSessao = ficaASessao || null;
    } catch (e) { /* sem a API: só a limpeza */ }
    try { performance.clearResourceTimings(); } catch (e) {}
}

// O anel de chamadas fica só com o que a sessão `fica` fez (a marca que cada
// registro leva, `API._marcaDaChamada`); sem sessão que fique, esvazia.
function deixarSoAsChamadasDaSessao(fica) {
    try {
        for (let i = API.chamadas.length - 1; i >= 0; i--) {
            if (!fica || API.chamadas[i].s !== fica) API.chamadas.splice(i, 1);
        }
    } catch (e) { /* sem a API: nada a tirar */ }
}
function diagRecursosDaSessao() {
    let lista = [];
    try { lista = performance.getEntriesByType('resource'); } catch (e) { return []; }
    return lista.filter((r) => r.startTime >= API.registrosDesde);
}

function diagCapturarErros() {
    // A lista bateu no teto: o relatório tem que DIZER isso, senão a ausência
    // do que veio depois lê como "não aconteceu".
    try {
        performance.addEventListener('resourcetimingbufferfull', () => { diagRecursosCheio = true; });
    } catch (e) {}
    addEventListener('error', (e) => {
        // O aviso de ResizeObserver não é erro do app (ver `RUIDO_RESIZE_OBSERVER`):
        // aqui ele virava "erro de JS" no relatório e uma CAPTURA automática de
        // ~150 KB, sem cota, empurrando pra fora do anel os momentos que importam
        // (auditoria de 2026-09-25). O console segue contando (`console.warn`).
        if (RUIDO_RESIZE_OBSERVER.test(e.message || '')) return;
        // Com CONTEXTO DE TELA: erro sem saber ONDE aconteceu manda procurar no
        // arquivo inteiro. É a diferença entre pista e ruído.
        diagErros.push({ t: new Date().toISOString(), tipo: 'error',
            msg: String(e.message || ''), fonte: String(e.filename || ''), linha: e.lineno,
            ...(typeof dlogTelaAtual === 'function' ? { onde: dlogTelaAtual() } : {}) });
        if (diagErros.length > 50) diagErros.shift();
        dlogCapturarAuto('erroDeJs');
    });

    // O `console.error/warn` some com a aba fechada, e é onde o navegador conta
    // coisa que o app não vê: falha de WebRTC, storage recusando, recurso
    // bloqueado. Embrulhar aqui é um funil só, em vez de trocar 200 chamadas.
    for (const nivel of ['error', 'warn']) {
        const orig = console[nivel].bind(console);
        console[nivel] = (...a) => {
            dlog('console.' + nivel, { msg: a.map((x) => {
                try { return typeof x === 'string' ? x : (x && x.message) || JSON.stringify(x); }
                catch (e) { return String(x); }
            }).join(' ').slice(0, 200) });
            orig(...a);
        };
    }

    // Travada de quadro é defeito de PRODUTO aqui: o valor do app é o ritmo do
    // swipe, e 200ms de thread presa são ~24 quadros perdidos.
    try {
        new PerformanceObserver((l) => {
            for (const e of l.getEntries()) if (e.duration > 200) dfato('lenta', { ms: Math.round(e.duration) });
        }).observe({ type: 'longtask', buffered: true });
    } catch (e) {}
    addEventListener('unhandledrejection', (e) => {
        diagErros.push({ t: new Date().toISOString(), tipo: 'rejeicao',
            msg: String((e.reason && e.reason.message) || e.reason || '').slice(0, 300) });
        if (diagErros.length > 50) diagErros.shift();
    });

    // A REDE CAIU / VOLTOU. O relato de 2026-09-22 foi todo sobre a falta de
    // rede, e o arquivo não dizia QUANDO ela faltou: a janela sem sinal foi
    // reconstruída de 16 "Failed to fetch" e da fila de saída abrindo e
    // fechando. Evento RARO e sem dado de ninguém — a regra de entrada do
    // `dfato`. `onLine === false` é a metade confiável (a da regra de uma mão
    // só): o que se registra é a TRANSIÇÃO que o navegador anuncia.
    addEventListener('offline', () => dfato('rede.caiu'));
    addEventListener('online', () => dfato('rede.voltou'));
    if (navigator.onLine === false) dfato('rede.caiu', { naAbertura: true });
    // O esqueleto nasce VISÍVEL no HTML, então a primeira transição dele é o
    // SUMIR — sem esta linha, o diário não diria desde quando ele estava lá.
    if (document.getElementById('loadingCard')?.classList.contains('hidden') === false) {
        dfato('tela.carregando', { visivel: true, naAbertura: true });
    }

    // A TELA MUDOU DE TAMANHO. Girar o aparelho, a barra do navegador sumir, a
    // janela do PWA reabrir — tudo isso remonta o layout, e num relato de "ficou
    // torto" a primeira pergunta é se aconteceu antes ou depois. Só quando o
    // tamanho MUDA de verdade: `resize` dispara em rajada durante o giro, e um
    // anel de 120 não sobrevive a isso.
    let ultimaJanela = '';
    const anotarJanela = () => {
        const j = innerWidth + 'x' + innerHeight;
        if (j === ultimaJanela) return;
        ultimaJanela = j;
        dfato('janela', { j, dpr: Math.round((devicePixelRatio || 1) * 100) / 100,
                          orient: innerWidth > innerHeight ? 'deitado' : 'em pé' });
    };
    addEventListener('resize', anotarJanela);
    anotarJanela();

    // O SW ASSUMIU. É o momento exato em que o código servido pode trocar
    // debaixo da página, e é a causa mais chata de "funcionava e parou": o
    // aparelho fica dias com asset velho porque o SW é cache-first. Sem esta
    // linha o arquivo diz QUAL código está rodando, mas não QUANDO ele entrou.
    try {
        if (navigator.serviceWorker) {
            navigator.serviceWorker.addEventListener('controllerchange',
                () => dfato('sw.assumiu', { v: typeof APP_VERSION !== 'undefined' ? APP_VERSION : null }));
        }
    } catch (e) {}
}

// ── A FILA DE SAÍDA no resumo ─────────────────────────────────────────────
// Em NÚMEROS: quantos itens, quantos pedidos distintos, quantos repetidos, de
// que tipo e há quanto tempo o mais velho espera. `repetidas` > 0 é a mesma
// decisão mandada duas vezes — o que o relato de 2026-09-22 deixava acontecer.
// Os ids e o autor de cada pedido ficam de fora: são dado de terceiro, e o
// resumo é o que se lê primeiro e se cola numa conversa.
function diagResumoDaSaida() {
    try {
        const f = carregarFilaDeSaida();
        const chaves = f.map(chaveDoPedido).filter(Boolean);
        const distintas = new Set(chaves).size;
        const tipos = {};
        for (const it of f) tipos[it.tipo] = (tipos[it.tipo] || 0) + 1;
        const ts = f.map((it) => it.t).filter(Number.isFinite);
        return { n: f.length, distintas, repetidas: chaves.length - distintas, tipos,
                 maisAntigaMin: ts.length ? Math.round((Date.now() - Math.min(...ts)) / 60000) : null };
    } catch (e) { return { erro: String((e && e.message) || e).slice(0, 120) }; }
}

// ── O OFFLINE no relatório ────────────────────────────────────────────────
// O estado que decide se a foto e o mapa abrem sem sinal mora em variáveis de
// módulo e numa base IndexedDB, e nada disso ia pro arquivo: no relato de
// 2026-09-22 a janela servida foi deduzida do sufixo das URLs, e a idade da
// fila guardada não aparecia em lugar nenhum. A fila vai só como NÚMERO e
// IDADE — o conteúdo é pedido de terceiro e já está inteiro no `appState`.
// Quem nunca ligou o offline sai sem abrir a base: abrir CRIA a base.
async function diagOffline() {
    const o = { ...diagOfflineAgora(), tilesGuardadosQueFalharam: diagTilesGuardadosQueFalharam.length };
    if (!o.ligado) return o;
    try {
        const f = await offlineLerFila();
        // `desdeMin`: de quando é a LISTA (o começo da busca que a trouxe). É
        // contra ele que os pousos filtram a reabertura sem rede.
        o.filaGuardada = f ? { n: f.places.length, idadeMin: Math.round((Date.now() - f.t) / 60000),
                               desdeMin: Number.isFinite(f.desde) ? Math.round((Date.now() - f.desde) / 60000) : null } : null;
    } catch (e) { o.filaGuardada = { erro: String((e && e.message) || e).slice(0, 120) }; }
    // Quantos pedidos pousaram no Waze depois da foto — os que a reabertura sem
    // rede tira da fila guardada. Só o número.
    try { o.pousosGravados = offlineLerPousos().length; } catch (e) {}
    try { o.janelaGuardada = await offlineLerJanela(); } catch (e) {}
    try {
        if (window.caches && await caches.has(OFFLINE_TILES_CACHE)) {
            o.tilesNoCache = (await (await caches.open(OFFLINE_TILES_CACHE)).keys()).length;
        } else o.tilesNoCache = 0;
    } catch (e) { o.tilesNoCache = { erro: String((e && e.message) || e).slice(0, 120) }; }
    return o;
}

// ── O service worker, pela boca DELE ──────────────────────────────────────
// Até aqui o relatório só sabia que ele estava "ativo e controlando", e o
// defeito do mapa de 2026-09-22 — o worker ACORDANDO sem lembrar dos tiles —
// não aparecia em nada. Agora ele diz quando nasceu, se a lista está lida,
// quantos tiles conhece e o que fez com os que passaram por ele (ver o `DIAG`
// no `service-worker.js`). Com TETO: worker de versão antiga não conhece a
// pergunta e não responde, e o diagnóstico não pode esperar pra sempre.
function diagServiceWorker() {
    return new Promise((ok) => {
        try {
            const ctl = navigator.serviceWorker && navigator.serviceWorker.controller;
            if (!ctl || typeof MessageChannel === 'undefined') return ok(null);
            const canal = new MessageChannel();
            const teto = setTimeout(() => ok({ semResposta: true }), 1500);
            canal.port1.onmessage = (e) => { clearTimeout(teto); ok(e.data); };
            ctl.postMessage({ type: 'DIAG' }, [canal.port2]);
        } catch (e) { ok({ erro: String((e && e.message) || e).slice(0, 120) }); }
    });
}

// Toda leitura do diagnóstico tem TETO: rede pendurada (portal cativo, sinal
// indo e voltando) deixava o "Baixar diagnóstico" sem resposta nenhuma —
// justamente na hora em que ele é pedido (auditoria de 2026-09-25). O sinal vale
// pro corpo também.
//
// E o relatório inteiro tem um ORÇAMENTO: as leituras eram em SÉRIE, cada uma
// com o seu teto, e com a rede pendurada o arquivo levava ~48 s pra sair (12
// leituras × 4 s), com o botão em "Gerando…" sem sinal nenhum (auditoria de
// 2026-09-26, D15). Agora as leituras andam em PARALELO e nenhuma passa do
// `prazo` do relatório; o que não chegou até ali sai marcado `semResposta`.
const DIAG_FETCH_TETO_MS = 4000;
const DIAG_ORCAMENTO_MS = 10000;
function diagFetch(url, opts = {}, prazo = Infinity) {
    const resta = Math.min(DIAG_FETCH_TETO_MS, prazo - Date.now());
    if (!(resta > 0)) {
        const e = new Error('sem resposta no orçamento do diagnóstico');
        e.name = 'TimeoutError';
        return Promise.reject(e);
    }
    let sinal;
    try { sinal = AbortSignal.timeout(resta); }
    catch (e) { const c = new AbortController(); setTimeout(() => c.abort(), resta); sinal = c.signal; }
    return fetch(url, { ...opts, signal: sinal });
}
// A leitura que NÃO CHEGOU (teto ou orçamento), distinta da que falhou: é ela
// que diz "a rede estava pendurada", e não "o arquivo não existe".
function diagFalhaDaLeitura(e) {
    const nome = e && e.name;
    return nome === 'TimeoutError' || nome === 'AbortError'
        ? { erro: 'sem resposta', semResposta: true }
        : { erro: String((e && e.message) || e) };
}

// "Já tratado por outro editor" chega com `success: false`, mas pro app é o
// pedido resolvido (ver `handleActionResult`): contar como falha punha um
// "falhas 1" em todo relatório com um ✕ que outro editor tinha feito antes, e
// quem lê procura um defeito que não existe (auditoria em produção de
// 2026-09-26: a única "falha" das 10 chamadas era essa).
function chamadaJaTratada(c) {
    return !!c && !c.ok && (c.errorCategory === 'already_processed' || c.errorCategory === 'not_found');
}
function chamadaFalhou(c) {
    return !!c && !c.ok && !chamadaJaTratada(c);
}

// Os arquivos NOSSOS que entram no `codigo` do relatório — o que responde "qual
// código este aparelho está rodando": o HTML, o SW, o CSS, os `js/min/*` e o
// manifest.
//
// O `service-worker.js` NÃO aparece em `performance.getEntriesByType` — ele
// não é recurso DESTA página, é o processo que a serve. Sem pedir por nome,
// o arquivo traz o conteúdo dos caches e a URL do SW, mas não o script que
// está no comando: dava pra concluir "está atualizado" pelo `version.js` com
// um SW de três versões atrás decidindo o que servir.
//
// Nem tudo que vem da nossa origem é CÓDIGO, e três coisas entravam aqui sem
// servir pra nada. **A fonte**: `.woff2` é binário lido com `r.text()`, então
// chega corrompido (byte inválido vira U+FFFD) — e ainda que chegasse inteiro,
// fonte não causa defeito que este arquivo investiga. MEDIDO no diagnóstico do
// owner: 111 KB crus, **42 KB comprimidos, 8% do arquivo inteiro**. **A
// `/api/*`**: o coletor faz GET e a API só aceita POST, então eram 6 entradas
// de `405 Método não permitido` — um erro que o app nunca vê. **E a leitura do
// relatório ANTERIOR** (`?diag-rede=1`, o lado "servidor" do `cacheVsRede`),
// que fica na lista de recursos da página: o 2º relatório na mesma página
// comparava 23 arquivos em vez de 11, dobrava as requisições e levava o CSS
// duas vezes (auditoria de 2026-09-26).
//
// **E o endereço RESERVADO da borda (`/cdn-cgi/`)**, que é da Cloudflare e nunca
// é código nosso. O Web Analytics que a borda injeta manda o relatório dele por
// `sendBeacon` pra MESMA origem (`/cdn-cgi/rum?`, que só aceita POST), e o pedido
// entra na lista de recursos (tipo "beacon"): virava "código", o GET de
// comparação levava 405, e TODO relatório de produção dizia "sem conferir: o
// servidor respondeu 405 em 1 arquivo" — sobre algo que não diz nada do código
// nem do servidor, e com 2 GETs à borda a cada relatório (auditoria da rodada
// 12, R12-4-06, reproduzido emulando a borda). O mesmo vale pro script do Bot
// Fight Mode (`/cdn-cgi/challenge-platform/…`), se um dia ele carregar.
function diagUrlsDoCodigo(urlsDosRecursos, meu, aqui) {
    return [...new Set([aqui, meu + '/service-worker.js',
        ...urlsDosRecursos.filter((u) => typeof u === 'string' && u.startsWith(meu))])]
        .filter((u) => !/\.(woff2?|ttf|otf|eot|png|jpe?g|gif|webp|avif|ico|mp4|webm)(\?|$)/i.test(u))
        .filter((u) => !u.startsWith(meu + '/api/'))
        .filter((u) => !u.startsWith(meu + '/cdn-cgi/'))
        .filter((u) => !/[?&]diag-rede=/.test(u));
}

// O código que a PÁGINA carregou, lido do PRÓPRIO DOCUMENTO: os `<script src>` (o
// `js/min/qr.js` também, que o `carregarQr` põe no `<head>` quando o pareamento
// o pede) e as folhas de estilo. A lista do `codigo` saía SÓ da lista de recursos
// da sessão (`diagRecursosDaSessao`), e o "Sair" e a troca de conta a limpam
// (`esquecerRegistrosDaPagina`): o código, carregado na abertura, ANTES da marca,
// saía junto. O relatório de quem entrava na mesma página levava `/` e o
// `/service-worker.js` e mais nada — a conferência de "versão velha?" cobria 2
// dos 11 arquivos, e o `diag-tela` remontava a tela SEM ESTILO (auditoria da
// rodada 9, R9-1-01 = R9-4-04, MEDIDO). O DOM não muda com a limpeza e não
// carrega dado de ninguém: é o código NOSSO, o mesmo pra toda conta. Nunca lança.
function diagUrlsDoDocumento() {
    try {
        return [...document.querySelectorAll('script[src], link[rel~="stylesheet"][href]')]
            .map((el) => (el.tagName === 'LINK' ? el.href : el.src))
            .filter((u) => typeof u === 'string' && u);
    } catch (e) { return []; }
}

async function diagCorpo() {
    const meu = location.origin;
    // O ORÇAMENTO do relatório inteiro (ver `DIAG_ORCAMENTO_MS`).
    const inicioDaColeta = Date.now();
    const prazo = inicioDaColeta + DIAG_ORCAMENTO_MS;
    // O que as OUTRAS abertas deixaram no aparelho até agora — a outra aba aberta
    // inclusive (ver `diagAtualizarAnteriores`) —, relido em paralelo com as
    // leituras de rede: o relatório leva o que o aparelho tem, e o download apaga
    // só o que levou (R6-4-5). A base tem teto próprio (`DIAG_DB_TETO_MS`).
    const anterioresDoAparelho = diagAtualizarAnteriores().catch(() => false);
    // Quais delas seguem ABERTAS agora (outra aba), pelas travas (ver
    // `diagMarcarSimultaneas`).
    const vivasPromessa = diagAberturasVivas(prazo);
    // Só recurso da NOSSA origem: de terceiro a resposta é opaca e a leitura
    // ainda gastaria rede. `cache: 'force-cache'` pra pegar o que o aparelho
    // REALMENTE tem — que é a pergunta quando se suspeita de PWA com código
    // velho; buscar da rede mediria o servidor, não o aparelho.
    const texto = async (url) => {
        try {
            const r = await diagFetch(url, { cache: 'force-cache' }, prazo);
            return { http: r.status, tipo: r.headers.get('content-type'),
                     etag: r.headers.get('etag'), corpo: await r.text() };
        } catch (e) { return diagFalhaDaLeitura(e); }
    };

    const ls = {}, ss = {};
    try { for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); ls[k] = localStorage.getItem(k); } }
    catch (e) { ls._erro = String(e); }
    try { for (let i = 0; i < sessionStorage.length; i++) { const k = sessionStorage.key(i); ss[k] = sessionStorage.getItem(k); } }
    catch (e) { ss._erro = String(e); }

    const sw = { suportado: 'serviceWorker' in navigator,
                 controlando: !!(navigator.serviceWorker && navigator.serviceWorker.controller),
                 registros: [] };
    try {
        for (const r of await navigator.serviceWorker.getRegistrations()) {
            sw.registros.push({ escopo: r.scope,
                ativo: r.active && r.active.scriptURL, estadoAtivo: r.active && r.active.state,
                esperando: r.waiting && r.waiting.scriptURL,
                instalando: r.installing && r.installing.scriptURL });
        }
    } catch (e) { sw.erro = String(e); }
    sw.proprio = await diagServiceWorker();

    const cachesDoAparelho = {};
    try {
        for (const nome of await caches.keys()) {
            const c = await caches.open(nome);
            cachesDoAparelho[nome] = (await c.keys()).map((r) => r.url);
        }
    } catch (e) { cachesDoAparelho._erro = String(e); }

    // O CÓDIGO que está rodando: tamanho, hash e versão de cada arquivo (o corpo,
    // só do CSS — ver abaixo). É isto que responde "o PWA está com a versão
    // velha?" — pergunta que o serial sozinho não responde, porque ele só diz o
    // que o `version.js` carregado afirma, não o que o resto é. Os `recursos` são
    // só os que começaram DEPOIS do último "Sair" ou troca de conta (ver
    // `diagRecursosDaSessao`); o CÓDIGO da página vem também do documento, que a
    // limpeza não toca (ver `diagUrlsDoDocumento`, R9-1-01).
    const recursos = diagRecursosDaSessao()
        .map((r) => ({ url: r.name, tipo: r.initiatorType, ms: Math.round(r.duration),
                       bytes: r.transferSize,
                       doCache: r.transferSize === 0 && r.decodedBodySize > 0 }));
    // EM PARALELO (ver `DIAG_ORCAMENTO_MS`), e na ordem da lista.
    const codigo = {};
    const urlsDoCodigo = diagUrlsDoCodigo([...diagUrlsDoDocumento(), ...recursos.map((r) => r.url)], meu, location.href);
    const lidos = await Promise.all(urlsDoCodigo.map((u) => texto(u)));
    urlsDoCodigo.forEach((u, i) => { codigo[u] = lidos[i]; });

    // ── O que o aparelho tem × o que o servidor tem AGORA ──────────────────
    // Responde de vez a pergunta que sozinha custou horas: "o PWA está rodando
    // código velho?". O `codigo` acima é o lado do APARELHO (`force-cache`);
    // aqui o mesmo arquivo vem da REDE (`reload`) e os dois são comparados por
    // hash. Deduzir isso do serial não serve — o serial só diz o que o
    // `version.js` carregado afirma, não o que o resto dos arquivos é.
    //
    // Custa uma requisição por arquivo, e SÓ quando alguém aperta o botão.
    const hash = async (txt) => {
        try {
            const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(txt));
            return [...new Uint8Array(b)].slice(0, 8).map((x) => x.toString(16).padStart(2, '0')).join('');
        } catch (e) { return 'sem-hash:' + txt.length; }
    };
    // Só o que entrou no `codigo`: a fonte e a `/api/*` ficam fora dele de
    // propósito (ver acima), e compará-las dava "sem corpo local" — 7 das 19
    // linhas no relatório real de 2026-09-24, que o leitor contava como arquivo
    // que não deu pra conferir. Assim, "sem corpo local" só sai quando a
    // leitura do arquivo NO APARELHO falhou, que é o caso que importa.
    // O RELÓGIO do servidor sai JUNTO com as releituras (em paralelo): é mais
    // uma leitura de rede, e em série ele somava o teto dele ao fim de tudo.
    const relogioPromessa = (async () => {
        const relogio = { aparelho: new Date().toISOString(), servidor: null, desvioSeg: null };
        try {
            const r = await diagFetch(meu + '/manifest.json?diag-rede=1', { cache: 'no-store', method: 'HEAD' }, prazo);
            const d = r.headers.get('date');
            if (d) {
                relogio.servidor = new Date(d).toISOString();
                relogio.desvioSeg = Math.round((Date.now() - new Date(d).getTime()) / 1000);
            }
        } catch (e) { Object.assign(relogio, diagFalhaDaLeitura(e)); }
        return relogio;
    })();
    const cacheVsRede = {};
    const comparar = async (u) => {
        const local = codigo[u] && codigo[u].corpo;
        if (typeof local !== 'string') return { erro: 'sem corpo local' };
        try {
            // `diag-rede` passa POR FORA do service worker (ver lá): sem isso o
            // "servidor" era o cache do próprio aparelho, e dava "igual" sempre.
            const r = await diagFetch(u + (u.indexOf('?') === -1 ? '?' : '&') + 'diag-rede=1', { cache: 'reload' }, prazo);
            // Resposta que não é OK não é "o servidor": com a origem fora do ar,
            // quem responde é a BORDA, com a página de erro dela (502, ~50 bytes),
            // e comparar com ela acusava "código diferente do servidor" em TODO
            // arquivo — justo no caso em que o app instalado abre da cópia
            // guardada (auditoria de 2026-10-01, R5-4-3). Fica "sem conferir",
            // com o status; o corpo de erro nem é lido.
            if (!r.ok) return { erro: 'http ' + r.status, http: r.status };
            const remoto = await r.text();
            // Sem o script da borda nos DOIS lados (ver `diagSemInjecaoDaBorda`);
            // `borda` diz que ele estava lá e foi descontado.
            const [la, lb] = [diagSemInjecaoDaBorda(local), diagSemInjecaoDaBorda(remoto)];
            const [ha, hb] = [await hash(la), await hash(lb)];
            const c = { aparelho: ha, servidor: hb, igual: ha === hb,
                        bytesAparelho: local.length, bytesServidor: remoto.length, http: r.status };
            if (la.length !== local.length || lb.length !== remoto.length) c.borda = true;
            return c;
        } catch (e) { return diagFalhaDaLeitura(e); }
    };
    const urlsComparadas = Object.keys(codigo);
    const comparados = await Promise.all(urlsComparadas.map(comparar));
    urlsComparadas.forEach((u, i) => { cacheVsRede[u] = comparados[i]; });
    await diagCodigoEnxuto(codigo, hash);

    // ── O armazenamento local funciona mesmo? ──────────────────────────────
    // O `safeLS` engole exceção DE PROPÓSITO, então armazenamento cheio ou
    // navegação privada falham em SILÊNCIO: filtro não persiste, sessão não
    // grava, e o app parece boa. É uma classe inteira de defeito que nenhum
    // outro campo deste arquivo revelaria — só a sonda escreve-lê-apaga.
    const armazenamento = { quota: null, uso: null, escreve: null, erroEscrita: null };
    try {
        const e = await navigator.storage.estimate();
        armazenamento.quota = e.quota; armazenamento.uso = e.usage;
        armazenamento.sobraPct = e.quota ? +(100 - (e.usage / e.quota) * 100).toFixed(2) : null;
    } catch (e) { armazenamento.erroQuota = String(e); }
    try {
        const k = '__diag_probe__', v = String(Date.now());
        localStorage.setItem(k, v);
        armazenamento.escreve = localStorage.getItem(k) === v;
        localStorage.removeItem(k);
    } catch (e) { armazenamento.escreve = false; armazenamento.erroEscrita = String((e && e.message) || e); }
    try { armazenamento.persistente = await navigator.storage.persisted(); } catch (e) {}

    // ── Relógio do aparelho × do servidor ──────────────────────────────────
    // Data errada no celular faz o aviso de sessão vencendo mentir e toda
    // comparação de prazo sair torta — e o sintoma nunca aponta pro relógio.
    const relogio = await relogioPromessa;
    await anterioresDoAparelho;
    const vivas = await vivasPromessa;

    const idb = {};
    try { for (const d of await indexedDB.databases()) idb[d.name] = d.version; }
    catch (e) { idb._erro = String(e); }

    const c = navigator.connection || {};
    // Computado UMA vez: as sentinelas leem dele, e medir duas vezes daria duas
    // fotos de instantes diferentes — que é como um alerta some do relatório
    // onde ele acabou de aparecer.
    const computado = diagComputado();
    const alertas = diagSentinelas(computado);
    diagTilesLidosAte = Date.now();   // o relatório também LÊ (ver `diagTilesLidosAte`)
    // O RETRATO: o instante em que o diário, as capturas, as chamadas e os erros
    // entram no arquivo. Tudo daqui pra frente é síncrono até a leitura do
    // offline, e é ESTE instante — não o fim do download — que separa o que foi
    // entregue do que fica guardado pra depois. Com o carimbo no fim, o que
    // entrava no anel enquanto o arquivo era serializado e empacotado não ia no
    // arquivo e saía da cópia guardada (auditoria de 2026-09-26).
    const retratoEm = Date.now();
    const momentosNoArquivo = [...dlogMomentos];
    // As outras aberturas, como vão no arquivo (a lista é trocada INTEIRA quando
    // muda, nunca editada no lugar): é delas que o download diz o que entregou.
    const aberturasNoArquivo = diagAberturasAnteriores;
    // As mesmas, com a OUTRA ABA marcada (`simultanea`): é assim que elas vão no
    // arquivo e no resumo. Cópias só das marcadas — as capturas são as mesmas.
    // As vivas AGORA e as vivas quando esta abriu (a que fechou antes, R8-4-07).
    const aberturasMarcadas = diagMarcarSimultaneas(aberturasNoArquivo, DIAG_ABERTURA.inicio, vivas, diagOutrasVivasAoAbrir);
    const chamadasNoArquivo = (typeof API !== 'undefined' && API.chamadas) ? [...API.chamadas] : [];
    const errosNoArquivo = [...diagErros];
    const corpo = {
        _leia_isto: 'Este arquivo contém o waze_session_token, que é CREDENCIAL VIVA da conta do Waze '
            + 'de quem gerou. Trate como senha. Pra anular: sair do app, o que destrói a sessão no '
            + 'servidor; se o app avisar que a limpeza no servidor não completou, o token ainda vale até '
            + 'ficar ' + SESSAO_DIAS_EXIBIDO + ' dias sem uso. '
            + 'NÃO contém os cookies do Waze — eles são de outra origem e não ficam neste aparelho.',
        _versaoDoDiag: DIAG_VERSAO,
        _formato: DIAG_FORMATO,
        // RESUMO NO TOPO: o arquivo tem 1,7 MB e ninguém lê 1,7 MB procurando o
        // que está errado. Isto é o que eu olho primeiro.
        resumo: {
            momentos: dlogMomentos.length,
            chamadas: (API.chamadas || []).length,
            falhas: (API.chamadas || []).filter(chamadaFalhou).length,
            jaTratadas: (API.chamadas || []).filter(chamadaJaTratada).length,
            naoAutorizado: (API.chamadas || []).filter((c) => c.errorCategory === 'unauthorized').length,
            rotasQueFalharam: [...new Set((API.chamadas || []).filter(chamadaFalhou).map((c) => c.rota))],
            errosDeJs: diagErros.length,
            penduradas: dlogAnel.filter((l) => l.k === 'pendurada').map((l) => l.o),
            lentas: dlogAnel.filter((l) => l.k === 'lenta').length,
            telaAgora: dlogTelaAtual(),
            // O resumo é o que se lê primeiro; estas duas respondem o relato da
            // sessão sem abrir o resto do arquivo.
            sessaoDuracaoH: (() => { try { return diagSessao().duracaoH || null; } catch (e) { return null; } })(),
            riscoDeApagamento: (() => { try { return diagArmazenamentoDuravel().riscoDeApagamento; } catch (e) { return null; } })(),
            // O relato de 2026-09-22 foi todo sobre a falta de rede, e o resumo
            // não dizia nem se havia rede. A linha do tempo está no diário
            // (`rede.caiu`/`rede.voltou`); aqui vai o AGORA.
            rede: navigator.onLine,
            offline: (() => { const o = diagOfflineAgora(); return o.ligado ? o.resultado || 'ligado' : 'desligado'; })(),
            // A fila de saída em NÚMEROS. O relato de 2026-09-22 dependia dela
            // (pedido esperando envio que voltou como card) e o resumo não a
            // mencionava: estava no localStorage, cru, junto do token.
            saida: diagResumoDaSaida(),
            // A presença no mapa do WME (fase 2). Responde "não apareço no WME"
            // sem abrir o resto: ligada? o app já a viu ligada? as escritas de
            // carona estão saindo, falhando, voltando sem a marca?
            presencaWme: (() => { try { return presencaWmeDiag(); } catch (e) { return { erro: String(e && e.message) }; } })(),
            // A lista e o chat do app (fase 3): quantos estão no app, quantas
            // conversas e não lidas, o token e o tempo real, e o PORQUÊ da lista
            // contado no servidor (`contagem`). É o RESUMO: a conversa em si vai
            // pelo registro de chamadas e pelo DOM.
            presencaApp: (() => { try { return window.Presenca?.diag?.() || null; } catch (e) { return { erro: String(e && e.message) }; } })(),
            // PRIMEIRA coisa a olhar. Vazio = nenhuma invariante conhecida
            // quebrada; não significa "está tudo bem", significa "não é nenhum
            // dos defeitos que já vimos".
            alertas,
            // As sentinelas de cada CAPTURA, no instante dela (`diagNoInstante`),
            // só as que acusaram algo. É aqui que aparece o defeito que estava na
            // tela quando a pessoa tocou no botão — e que o relatório, gerado
            // depois e com o modal de Filtros por cima, não enxerga.
            alertasNasCapturas: dlogMomentos
                .filter((m) => Array.isArray(m.alertas) && m.alertas.length)
                .map((m) => ({ t: m.t, motivo: m.motivo, painel: m.painel,
                               alertas: m.alertas.map((a) => a.chave) }))
                // E as das aberturas ANTERIORES que ficaram guardadas, com a
                // abertura de cada uma: o defeito que só aparece depois de
                // fechar e reabrir foi capturado ANTES, noutra abertura. A da
                // OUTRA ABA aberta junto vem marcada (`outraAba`): ali não houve
                // fechar e reabrir (R7-4-04).
                .concat(aberturasMarcadas.flatMap((a) => (a.momentos || [])
                    .filter((m) => Array.isArray(m.alertas) && m.alertas.length)
                    .map((m) => ({ t: m.t, motivo: m.motivo, painel: m.painel, abertura: a.id,
                                   ...(a.simultanea ? { outraAba: true } : {}),
                                   alertas: m.alertas.map((x) => x.chave) }))))
                .sort((x, y) => Date.parse(x.t) - Date.parse(y.t)),
            // Quantas aberturas anteriores ficaram guardadas, e com quantas
            // capturas — a primeira pergunta de um relato que atravessa fechar
            // e reabrir o app. E quantas delas são, na verdade, OUTRA ABA que
            // viveu junto com esta (`simultaneas`).
            aberturasAnteriores: { n: diagAberturasAnteriores.length,
                                   capturas: diagMomentosAnteriores().length,
                                   simultaneas: aberturasMarcadas.filter((a) => a && a.simultanea).length },
        },
        computado,
        // Os DOIS anéis numa linha do tempo só: o sempre-ligado (`dfato`) e o do
        // modo dev (`dlog`). Cada call site escolhe UM dos dois, então não há
        // duplicata — e o `diario` deixa de nascer vazio, que era o buraco que
        // custou a investigação dos modais achatados.
        diario: [...dfatoAnel, ...dlogAnel].sort((a, b) => a.t - b.t),
        momentos: momentosNoArquivo,
        // O que as aberturas ANTERIORES deixaram guardado no aparelho (só com o
        // modo dev ligado nelas): diário, chamadas sem corpo, erros e as
        // capturas não baixadas, cada abertura com o seu id, início e versão.
        // Ver `diagAberturasAnteriores`.
        // A da OUTRA ABA aberta junto com esta vem com `simultanea: true` (e
        // `abertaAgora`), ver `diagMarcarSimultaneas`.
        aberturaAtual: { id: DIAG_ABERTURA.id, inicio: new Date(DIAG_ABERTURA.inicio).toISOString() },
        aberturasAnteriores: aberturasMarcadas,
        _gerado: new Date().toISOString(),
        // A seção que responde o relato "a sessão não dura": ciclos medidos em
        // horas, e o ambiente que decide se o armazenamento sobrevive.
        sessao: diagSessao(),
        armazenamentoDuravel: diagArmazenamentoDuravel(),
        app: { versao: typeof APP_VERSION !== 'undefined' ? APP_VERSION : null,
               rotulo: typeof verLabel === 'function' ? verLabel(APP_VERSION) : null,
               url: location.href,
               idioma: typeof getLang === 'function' ? getLang() : null },
        ambiente: {
            ua: navigator.userAgent, plataforma: navigator.platform, idiomas: navigator.languages,
            online: navigator.onLine,
            conexao: { tipo: c.effectiveType, downlink: c.downlink, rtt: c.rtt, economia: c.saveData },
            standalone: matchMedia('(display-mode: standalone)').matches || navigator.standalone === true,
            tela: { w: screen.width, h: screen.height, dpr: devicePixelRatio,
                    janela: innerWidth + 'x' + innerHeight },
            fuso: Intl.DateTimeFormat().resolvedOptions().timeZone,
            escuro: matchMedia('(prefers-color-scheme: dark)').matches,
            memoria: navigator.deviceMemory, nucleos: navigator.hardwareConcurrency,
        },
        // Cookies DESTA origem. Os do Waze não estão aqui — ver o cabeçalho.
        cookiesDestaOrigem: document.cookie || '(vazio)',
        localStorage: ls,
        sessionStorage: ss,
        indexedDB: idb,
        serviceWorker: sw,
        offline: await diagOffline(),
        caches: cachesDoAparelho,
        // CÓPIA no retrato, como o diário: a chamada que chegar depois dele fica
        // pra cópia guardada (ver `retratoEm`), em vez de ir nos dois lugares.
        chamadas: chamadasNoArquivo,
        recursos,
        // Se a lista de recursos bateu no teto do navegador, o que veio DEPOIS
        // não está nela — e sem este aviso a ausência lê como "não aconteceu".
        recursosInfo: { n: recursos.length, encheu: diagRecursosCheio,
                        teto: dlogLigado() ? DIAG_RECURSOS_TETO : 'padrão do navegador (250)' },
        erros: errosNoArquivo,
        // `currentPlace` É `queue[0]` — o MESMO objeto —, então o `diagSeguro`
        // marcava um dos dois como `[circular]`, e quem perdia era sempre o card
        // que a pessoa estava VENDO. Já custou um remendo do meu lado ao ler um
        // arquivo real ("[circular]" no item 0 de 395). Aqui o `currentPlace` sai
        // como ÍNDICE, e a fila fica inteira e legível.
        appState: (() => {
            const st = typeof AppState !== 'undefined' ? AppState : null;
            if (!st) return null;
            const idx = st.currentPlace && Array.isArray(st.queue)
                ? st.queue.indexOf(st.currentPlace) : -1;
            const copia = { ...st };
            if (idx >= 0) delete copia.currentPlace;
            const fora = diagSeguro(copia);
            if (fora) fora.currentPlaceIdx = idx;
            return fora;
        })(),
        // Com o TREINO aberto, o `appState` acima tem os EXEMPLOS; a fila REAL é
        // a que o treino guarda, e vai aqui (R8-4-06, ver `diagTreinoGuardado`).
        treino: diagTreinoGuardado(),
        // O HTML como está AGORA, com as classes que decidem o que aparece na
        // tela. É o que mostra qual painel estava visível no momento da queixa.
        dom: domParaDiagnostico(),
        codigo,
        cacheVsRede,
        armazenamento,
        relogio,
        // A COLETA em si: quanto levou, o orçamento, e o que NÃO chegou nele —
        // "a rede estava pendurada" dito no arquivo, não deduzido (D15).
        coleta: {
            ms: Date.now() - inicioDaColeta, orcamentoMs: DIAG_ORCAMENTO_MS,
            semResposta: [...Object.entries(codigo).filter(([, v]) => v && v.semResposta).map(([u]) => u),
                          ...Object.entries(cacheVsRede).filter(([, v]) => v && v.semResposta).map(([u]) => u + ' (servidor)'),
                          ...(relogio.semResposta ? ['relógio do servidor'] : [])],
        },
    };
    // Fora do JSON (não enumerável): o que o `baixarDiagnostico` marca como
    // entregue — o instante do retrato, as capturas que foram no arquivo e as
    // outras aberturas, cada uma na VERSÃO que foi (o que sai do aparelho, R6-4-5).
    // Da lista do retrato, e não da de agora: a releitura pode trocá-la durante os
    // `await` de cima, e marcaria como entregue o que não foi no arquivo.
    Object.defineProperty(corpo, 'entregue', {
        value: { em: retratoEm, momentos: [...momentosNoArquivo, ...diagMomentosAnteriores(aberturasNoArquivo)],
                 aberturas: aberturasNoArquivo.map((a) => ({ id: a.id, salvoEm: a.salvoEm })) },
    });
    return corpo;
}

// ── Empacotar o diagnóstico ───────────────────────────────────────────────
//
// O arquivo é grande por natureza — ele carrega o código servido, a fila e o
// DOM — e MEDIDO no diagnóstico real do owner: 2,61 MB que viram **532 KB**,
// 4,9×. A compressão é do próprio navegador (`CompressionStream`), então isto
// não traz dependência nenhuma: custa ~65 linhas de container e **529 ms com
// CPU 6× mais lenta**, ao lado do segundo que a coleta já leva.
//
// ZIP e não `.gz` por duas razões práticas, nessa ordem:
//  1. O ZIP abre no PRÓPRIO celular, sem instalar nada. `.gz` é opaco no
//     Android e no iOS, e arquivo que o dono não consegue abrir é arquivo que
//     ele manda sem poder conferir o que está mandando.
//  2. O ZIP aceita MAIS DE UMA entrada — e isso resolve um problema que a
//     compressão criaria: hoje a primeira coisa dentro do JSON é o aviso de que
//     ele contém CREDENCIAL VIVA. Comprimido, esse aviso sumiria de vista. O
//     `LEIA-ME.txt` aparece na listagem de qualquer visualizador de ZIP, sem
//     extrair nada.
//
// `deflate-raw` é exatamente o que o ZIP quer no método 8 — a mesma compressão
// do gzip, sem o envelope dele.
const CRC_TAB = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
        let c = n;
        for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
        t[n] = c >>> 0;
    }
    return t;
})();

function crc32(u8) {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < u8.length; i++) c = CRC_TAB[(c ^ u8[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
}

// ZIP "store or deflate", sem data/hora (campos zerados: o nome do arquivo já
// carrega o instante, e hora local dentro do pacote é um dado a mais sobre quem
// gerou). Um `DataView` little-endian, que é o que a especificação manda.
async function zipar(entradas) {
    const enc = new TextEncoder();
    const partes = [];
    for (const [nome, texto] of entradas) {
        const cru = enc.encode(texto);
        let corpo = cru, metodo = 0;
        try {
            corpo = new Uint8Array(await new Response(new Blob([cru]).stream()
                .pipeThrough(new CompressionStream('deflate-raw'))).arrayBuffer());
            metodo = 8;
        } catch (e) { /* sem CompressionStream: guarda cru, o ZIP segue válido */ }
        partes.push({ nome: enc.encode(nome), cru, corpo, metodo, crc: crc32(cru) });
    }
    let tam = 22;
    for (const e of partes) tam += 30 + e.nome.length + e.corpo.length + 46 + e.nome.length;
    const out = new Uint8Array(tam), dv = new DataView(out.buffer);
    const põe = (o, vals) => {
        let q = o;
        for (const [n, v] of vals) { if (n === 2) dv.setUint16(q, v, true); else dv.setUint32(q, v, true); q += n; }
        return q;
    };
    let o = 0;
    for (const e of partes) {
        e.off = o;
        o = põe(o, [[4, 0x04034b50], [2, 20], [2, 0], [2, e.metodo], [2, 0], [2, 0],
                    [4, e.crc], [4, e.corpo.length], [4, e.cru.length], [2, e.nome.length], [2, 0]]);
        out.set(e.nome, o); o += e.nome.length;
        out.set(e.corpo, o); o += e.corpo.length;
    }
    const inicioCd = o;
    for (const e of partes) {
        o = põe(o, [[4, 0x02014b50], [2, 20], [2, 20], [2, 0], [2, e.metodo], [2, 0], [2, 0],
                    [4, e.crc], [4, e.corpo.length], [4, e.cru.length],
                    [2, e.nome.length], [2, 0], [2, 0], [2, 0], [2, 0], [4, 0], [4, e.off]]);
        out.set(e.nome, o); o += e.nome.length;
    }
    põe(o, [[4, 0x06054b50], [2, 0], [2, 0], [2, partes.length], [2, partes.length],
            [4, o - inicioCd], [4, inicioCd], [2, 0]]);
    return out;
}

async function baixarDiagnostico() {
    const btn = document.getElementById('diagBtn');
    if (btn) { btn.disabled = true; btn.textContent = t('filters.diag.gerando'); }
    try {
        const corpo = await diagCorpo();
        // Sem indentação quando vai comprimido: o `null, 1` existia pra o
        // arquivo ser legível a olho, e dentro do ZIP quem abre já usa um
        // visualizador. Cru continua indentado, que é o caso em que alguém vai
        // mesmo abrir no bloco de notas.
        const podeZipar = typeof CompressionStream === 'function';
        const json = JSON.stringify(corpo, null, podeZipar ? 0 : 1);
        // Começa com `diag-` e NÃO com `waze`: o guard do logout varre os
        // literais `waze*` do js/ procurando chave nova de armazenamento, e um
        // nome de arquivo com esse prefixo é indistinguível de uma chave pra
        // ele. Afrouxar o guard pra caber um nome bonito é o caminho errado.
        const base = 'diag-wazeplaces-' + new Date().toISOString().replace(/[:.]/g, '-');
        let blob, nome;
        if (podeZipar) {
            const zip = await zipar([
                ['diagnostico.json', json],
                // Visível na listagem do ZIP sem extrair nada — que é o motivo de
                // o aviso não poder ficar só dentro do JSON comprimido.
                ['LEIA-ME.txt', t('diag.leiame', { v: typeof APP_VERSION !== 'undefined' ? APP_VERSION : '?' })],
            ]);
            blob = new Blob([zip], { type: 'application/zip' });
            nome = base + '.zip';
        } else {
            // Navegador sem `CompressionStream` (iOS < 16.4). Cai pro JSON de
            // sempre em vez de falhar: o instrumento de socorro não pode ter
            // pré-requisito, senão ele falta justamente no aparelho estranho.
            blob = new Blob([json], { type: 'application/json' });
            nome = base + '.json';
        }
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = nome;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 30000);
        dlogMarcarBaixados(corpo.entregue.momentos);
        // Entregue: o que foi no arquivo sai do aparelho — e SÓ isso (R6-4-5: a
        // base inteira saía, com o que a outra aba gravou depois da leitura; ver
        // `diagEsquecerEntregue`) —, e desta abertura só volta a ser guardado o que
        // veio DEPOIS DO RETRATO — não do fim do download (ver `retratoEm`).
        diagBaixadoEm = corpo.entregue.em;
        // E as OUTRAS abas ficam sabendo do que foi delas (R9-4-10): sem isto a
        // que gravou as telas as devolvia à base, e elas saíam de novo.
        diagAvisarEntregues(corpo.entregue);
        diagEsquecerEntregue(corpo.entregue.aberturas);
        atualizarFabDev();
        showToast(t('toast.diagPronto'), 'success');
    } catch (e) {
        // O instrumento de socorro NÃO pode falhar calado: se ele quebrar,
        // ninguém descobre por que o socorro não veio.
        showToast(t('toast.diagFalhou', { erro: String((e && e.message) || e).slice(0, 80) }), 'error', 9000);
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = t('filters.diag.btn'); }
    }
}

async function handleUnauthorized() {
    // Concorrência é o normal aqui, não a exceção: ao abrir o app saem TRÊS
    // chamadas ao Waze quase juntas (perfil, países, busca). Sem esta trava,
    // cada uma que voltasse 401 fazia sua própria verificação e seu próprio
    // toast — foi assim que o owner recebeu DOIS "Sessão expirou" empilhados.
    // A decisão mais cara do app: derrubar ou não a sessão. Registrar as duas
    // pontas (o que motivou e o que a sonda respondeu) é o que transforma
    // "conexão instável pra sempre" em evidência.
    // O log vem ANTES da trava, e não dentro dela: assim a linha da trava fica
    // intacta pro guard que a protege (ele cobra o retorno COLADO na condição),
    // e o registro fica melhor — diz a tentativa E se ela seguiu adiante.
    dlog('sessao.confere', { seguiu: !verificandoSessao && !!AppState.authenticated });
    if (verificandoSessao || !AppState.authenticated) return;
    verificandoSessao = true;
    let terminou = null;
    const estaConferencia = new Promise((ok) => { terminou = ok; });
    conferenciaDaSessao = estaConferencia;
    try {
        await new Promise((r) => setTimeout(r, VERIFICA_SESSAO_MS));
        // A pessoa pode ter saído (ou o portão ter derrubado a sessão) durante a
        // espera. Seguir daria uma sonda SEM token, um "morta" e uma tentativa
        // de login silencioso pela extensão — depois de um "Sair".
        if (!AppState.authenticated) return;
        // O servidor em que a sonda PERGUNTA: os editáveis do perfil que ela
        // trouxer são dele (ver abaixo, R8-6-03), e a pessoa pode aplicar outra
        // região enquanto a resposta vem.
        const regiaoDaSonda = API.getRegion();
        const r = await API.getProfile();
        if (!AppState.authenticated) return;
        // A sonda achou o portão fechado (ver `handlePerfil`): não é alarme
        // falso nem sessão que expirou — é o mesmo desfecho do login negado.
        if (r && r.errorCategory === 'access_denied') {
            // A recusa TERMINAL, com o que é da conta saindo do aparelho e o
            // diálogo antes da tela de entrada (ver a função).
            recusaDoPortao(r);
            return;
        }
        // Teste POSITIVO de vida, não ausência de marcador.
        //
        // Antes era `r.errorCategory !== 'unauthorized'`, o que infere "viva" de
        // NÃO encontrar um carimbo — e um 401 sem carimbo (o do nosso próprio
        // store, que não passa pelo `categorizeWazeError`) caía aqui como alarme
        // falso. A sessão morta era MANTIDA, o toast de "conexão instável"
        // aparecia a cada tentativa, e o único jeito de sair era o logout manual.
        // Foi o que aconteceu com todos os testadores no deploy da derivação de
        // chave, que invalidou as sessões existentes de uma vez.
        //
        // As três saídas agora são explícitas: respondeu → viva; disse que não
        // autoriza → morta; qualquer outra coisa (rede, 5xx, timeout) → não dá
        // pra saber, e aí NÃO se derruba ninguém, que é o que o gotcha #42 pede.
        const morta = r && (r.errorCategory === 'unauthorized'
            || r.errorKey === 'srv.err.sessionExpired'
            || r.errorKey === 'srv.err.sessionMissing'
            || r.errorKey === 'srv.err.cookiesExpired');
        if (r && !morta) {
            // Alarme falso. O pedido que falhou já foi revertido por quem o
            // chamou; aqui só recompomos o que o 401 tinha interrompido.
            // O perfil da sonda passa pela FONTE ÚNICA (`definirPerfil`), que
            // confere a conta antes de tudo: era aqui que ele entrava sem o
            // `aoConhecerConta`. Se era o PRIMEIRO da sessão (o 401 barrou o da
            // abertura), completa o que a abertura não chegou a fazer.
            //
            // E os editáveis dele ficam anotados, como a carga faz (ver
            // `editaveisLidos`, R7-6-02): o perfil da abertura que leva o 401
            // passageiro nunca chega a anotá-los, e o desta sonda também não
            // anotava — com "Minha área", o país da área (`paisDaMinhaArea`)
            // ficava desconhecido até recarregar: o Histórico gravava as
            // decisões sem lugar e a carona marcava o país do filtro (auditoria
            // da rodada 8, R8-6-03, MEDIDO no navegador). Antes do
            // `definirPerfil`, na ordem da carga: a anotação é da conta do
            // perfil, e outra conta recomeça a lista.
            // A caixa das áreas também (R9-6-04), e as áreas gerenciadas (R10-6-03).
            if (r.success && r.profile) {
                anotarEditaveis(r.profile, regiaoDaSonda, r.profile.editableCountryIDs, r.profile.areas, r.profile.managedAreas);
            }
            const primeiroPerfil = !AppState.profile;
            if (definirPerfil(r) && primeiroPerfil) completarPerfilChegado(r.profile, epocaDaSessao);
            // O perfil revelou que OUTRA conta tomou o aparelho noutra aba, e
            // esta saiu (ver `definirPerfil`): "sua sessão continua válida" e a
            // busca de novo seriam o contrário do que acabou de acontecer.
            if (!AppState.authenticated) return;
            // A sonda RESPONDEU com o perfil: a sessão está viva AGORA. É isto
            // que deixa a fila de saída distinguir sessão morta de escrita
            // recusada (ver `sessaoVivaDepoisDe`). "Não deu pra saber" (rede,
            // 5xx) não confirma nada.
            if (r.success && r.profile) marcarSessaoViva();
            dfato('sessao.alarmeFalso', { sondaOk: !!(r && r.success) });
            dlogCapturarAuto('alarmeFalso');
            // "Continua válida" só quando a sonda RESPONDEU (é a prova de vida).
            // Sonda que falhou por rede ou 5xx não prova nada — a sessão segue
            // aberta porque não dá pra saber, e o aviso diz isso (auditoria de
            // 2026-09-26: "sua sessão continua válida" saía sem prova nenhuma).
            showToast(t(r.success ? 'toast.sessionKeptAlive' : 'toast.sessionUnconfirmed'), 'info');
            rebuscarDepoisDeFalha();
            // A ação que levou o 401 foi pra fila de saída (ver o
            // `handleActionResult`): com a sessão confirmada viva, ela sai já.
            // A conferência ACABOU aqui (o `finally` só confirma): o
            // esvaziamento espera enquanto ela corre (ver lá, K14).
            verificandoSessao = false;
            esvaziarFilaDeSaida();
            return;
        }
        // A confirmação também diz de QUAL lado falhou, e isso vira a mensagem:
        // o core já mandava chaves diferentes (`srv.err.cookiesExpired` quando o
        // Waze recusou; `srv.err.sessionExpired` quando a nossa sessão sumiu) e
        // o frontend juntava as duas numa frase só. Separar transforma a próxima
        // ocorrência em EVIDÊNCIA — dá pra saber de onde veio sem HAR nem
        // exportar cookie de novo — e ainda diz ao editor algo que ele pode
        // usar: "o Waze recusou" e "você ficou fora tempo demais" pedem cuidados
        // diferentes, mesmo que a ação seja a mesma.
        derrubarSessao(r && r.errorKey);
    } finally {
        verificandoSessao = false;
        // O desfecho (viva, morta ou "não deu pra saber") chega a quem esperava.
        if (conferenciaDaSessao === estaConferencia) conferenciaDaSessao = null;
        terminou();
    }
}

// Chave do core → frase que o editor lê. Chave desconhecida cai na frase
// genérica de sempre: mensagem vaga é ruim, mensagem errada é pior.
// O `srv.err.sessionExpired` é "sessão expirada OU INVÁLIDA" no core: vale pra
// inatividade, mas também pra chave do servidor trocada, sessão apagada e token
// estranho — a frase dizia "venceu por inatividade" pra todos (auditoria de
// 2026-09-26), e hoje diz só o que se sabe: a sessão não vale mais.
const MOTIVO_DA_QUEDA = {
    'srv.err.cookiesExpired': 'toast.sessionExpired.waze',
    'srv.err.sessionExpired': 'toast.sessionExpired.local',
};

// A sessão desta aba ainda é a GUARDADA no aparelho? Com o app aberto em duas
// abas, as duas carregam a mesma sessão na memória. Quando ela cai, a primeira
// que percebe a derruba — tira o token do aparelho e anota a queda no diário de
// sessões — e pode entrar de novo (a extensão renova), guardando um token NOVO.
// A outra só descobre no gesto seguinte, com o token VELHO na memória: a queda
// dela é só dela. Tirar o token do aparelho ali apagava o NOVO da primeira, que
// seguia viva com ele na memória e caía na tela de entrada ao recarregar; e o
// diário ganhava uma segunda queda, que fechava o ciclo da sessão nova — viva —
// como se ela tivesse durado minutos (auditoria de 2026-09-29, R4-5). Lê a
// memória direto: o `getSession`, com ela vazia, iria buscar o do aparelho.
function sessaoDestaAbaEhAGuardada() {
    const naMemoria = API.sessionToken;
    return !!naMemoria && safeLS.get('waze_session_token') === naMemoria;
}

function derrubarSessao(errorKey, { depois } = {}) {
    epocaDaSessao++;   // o que estava em voo pertencia à sessão que morreu
    quedaAnunciada = false;   // esta queda ainda não foi dita (ver o fim da renovação)
    // O que é do APARELHO — o token guardado, o diário de sessões e o prazo —
    // só sai se a sessão que caiu é a guardada nele. Senão ele é o da sessão
    // da outra aba, viva, e aqui cai só a cópia da memória (ver a função).
    const doAparelho = sessaoDestaAbaEhAGuardada();
    // A queda é a decisão mais cara do app e era a ÚNICA que não chegava ao
    // anel sem portão: havia `dlog('sessao.confere')`, que o dev mode desligado
    // engole, e `dfato` só no ALARME FALSO — ou seja o caso em que ela NÃO cai.
    // O testador liga o dev mode DEPOIS do problema, então sem isto o evento
    // some exatamente para quem precisa relatá-lo.
    //
    // O prazo entra aqui porque o `esquecerPrazoDaSessao()` logo abaixo o apaga
    // — com razão, senão a próxima entrada nasce com a contagem da sessão morta
    // na tela. Ele sai da TELA e fica no REGISTRO.
    const prazoQueMorreu = AppState.sessaoExpiraEm || Number(safeLS.get(SESSAO_KEY)) || null;
    // O anel da memória é DESTA aba e anota as duas; o diário de sessões é do
    // aparelho, e a queda só desta aba ele já anotou quando ela aconteceu lá.
    dfato('sessao.caiu', { motivo: errorKey || null, ...(doAparelho ? {} : { soNestaAba: true }) });
    if (doAparelho) registrarEventoDeSessao('caiu', {
        motivo: errorKey || null,
        prazo: prazoQueMorreu || null,
        // Faltava muito, ou já tinha vencido? É o que separa "caiu antes da
        // hora" de "venceu como esperado", sem eu ter que cruzar datas à mão.
        faltavamH: prazoQueMorreu ? Math.round((prazoQueMorreu - Date.now() / 1000) / 360) / 10 : null,
    });
    // Cancela ação pendente: a sessão já morreu no Waze, o executor falharia e
    // mostraria "erro ao marcar" na tela de login. Cancelar reverte o stat otimista
    // — e a reversão é GRAVADA: o gesto já tinha gravado o +1, e quem fecha o app
    // depois da queda (o caso comum) ficava com um pedido a mais no placar pra
    // sempre (auditoria de 2026-09-25). O logout não precisa: ele zera o placar.
    //
    // E o pedido VOLTA pra fila (`cancel(true)`, o mesmo do Desfazer): ele segue
    // pendente no Waze, e a renovação pela extensão mantém a fila na tela. Sem
    // isto ele não ia pro Waze nem voltava como card — já tinha passado pela
    // fila, e nenhuma busca o trazia (auditoria de 2026-09-29, V1). Se entrar
    // OUTRA conta, a fila inteira sai com ela (`esquecerOutraConta`); na tela de
    // entrada, o próximo login começa uma fila nova.
    if (AppState.pendingAction) {
        AppState.pendingAction.cancel(true);
        AppState.pendingAction = null;
        saveStats();
    }
    // O lote de lidos que estava no ar era da sessão que morreu: ele não trava
    // a sessão que vem (ver `loteDeLidosEmVoo`). A aprovação no ar sai da
    // sessão também, mas segue travando o card dela na fila que atravessa a
    // queda, até a resposta chegar (ver `aprovacoesDaQueda`).
    loteDeLidosEmVoo = false;
    aprovacoesAtravessamAQueda();
    // E as do lightbox, que têm janela própria (ver a função).
    cancelarPendenciasDoLightbox();
    removeUndoBanner();
    // O token só sai do aparelho se é o desta aba. Senão só a memória solta —
    // pelo `setSession`, o de lá (o da outra aba) sairia, e o diário ganharia
    // um "token-" de uma sessão que ele já tinha dado por encerrada.
    if (doAparelho) API.setSession(null);
    else API.soltarSessao();
    AppState.profile = null;
    AppState.authenticated = false;
    // Sem sessão o card não decide (ver `acoesTravadas`): durante a renovação
    // pela extensão ele segue na tela, e os botões ficam com cara de travados.
    aplicarTravaDeAcao();
    // O cabeçalho é de QUEM ESTAVA: o nome e a foto seguiam lá durante a
    // renovação — e depois dela, se o perfil de quem entrou não chegasse
    // (MEDIDO: "contaA" com a sessão de B). O perfil que chegar o redesenha.
    limparCabecalhoDoPerfil();
    // Casa e trabalho são da CONTA da sessão que caiu, pelo mesmo motivo: quem
    // entrasse depois, no mesmo aparelho, teria a fila ordenada pela casa de quem
    // estava (auditoria de 2026-09-29, R4-5 A4). A mesma pessoa voltando os tem
    // de volta com o perfil.
    //
    // A posição do GPS NÃO sai aqui: ela é do APARELHO, não da conta, e o perfil
    // que volta não a traz. Tirada na queda, a renovação pela extensão (a MESMA
    // conta, que segue triando) deixava o "📍 Perto de mim" sem referência, e o
    // card seguinte saía pela ordem de data, sem aviso, sob o "sua fila continua
    // aqui" (auditoria de 2026-10-01, R56-1). Ela sai quando o perfil revela
    // OUTRA conta (`esquecerOutraConta`) e no "Sair".
    referenciasDoPerfil = null;
    // O prazo era desta sessão, que acabou de morrer. Deixá-lo guardado faria a
    // próxima entrada nascer com a contagem da sessão ANTERIOR na tela, até a
    // primeira resposta do Waze corrigir. O guardado no aparelho, na queda só
    // desta aba, é o da sessão da outra: fica.
    esquecerPrazoDaSessao({ soMemoria: !doAparelho });

    // Antes de mandar pra tela de login, PERGUNTA à extensão — em silêncio.
    //
    // A sessão do app venceu, mas o login do editor no WME quase sempre não:
    // são prazos diferentes. Quem tem a extensão renova sem sair do lugar, e a
    // fila continua na tela. Só quem não tem (ou está deslogado do WME) vê o
    // toast e cai no login — por isso o aviso é ADIADO até a extensão falhar:
    // avisar antes seria assustar quem nem ia ser interrompido.
    //
    // `depois` é pra quem já sabe o desfecho e não quer a extensão no meio: o
    // portão negado no perfil (a extensão entraria pelo MESMO portão e seria
    // recusada, com um toast de "sessão expirada" que não é o motivo).
    //
    // Nos dois casos a tela de entrada vem pelo `fecharCamadasAbertas`, que fecha
    // o que estava aberto por cima ANTES de ela (e do diálogo) aparecer.
    if (typeof depois === 'function') { fecharCamadasAbertas(depois); return; }
    const epoca = epocaDaSessao;
    // A fila REAL, que a renovação mantém — pela ÉPOCA dela. Com o TREINO aberto,
    // a `fetchEpoch` é a dos EXEMPLOS, e guardada ela a renovação errava nos dois
    // sentidos: com a fila refeita no "Sair" (o perfil levou a outro país), "sua
    // fila continua aqui" saía junto do "Mostrando a fila do país…"; sem o
    // refazer, a fila continuava e o aviso não saía (R11-7-03, MEDIDO no
    // navegador; auditoria da rodada 11). No treino, vale a que ele guarda, e null
    // quando ela não volta no "Sair" (`Treino.epocaDaFilaGuardada`).
    const epocaDaFilaReal = () => (Treino.ativo === true ? Treino.epocaDaFilaGuardada() : AppState.fetchEpoch);
    const filaDaQueda = epocaDaFilaReal();
    entrarPelaExtensao({ silencioso: true, manterFila: true }).then(async (renovou) => {
        // O "Sair" no meio da renovação: a tela e o aviso já são os dele, e um
        // "sua sessão expirou" depois dele diria o que não aconteceu (K3).
        if (epoca !== epocaDaSessao) return;
        if (renovou) {
            rebuscarDepoisDeFalha();
            // "Sua fila continua aqui" só se ela continua. Com OUTRA conta — dita
            // pela ponte que repassa a conta, ou pelo perfil que a renovação
            // pediu —, a fila sai (`esquecerOutraConta`), e os dois avisos
            // juntos se contradiziam: o da troca é o que vale (auditoria da
            // costura, 2026-09-26, K2). Por isso o perfil é esperado, com teto.
            await Promise.race([
                Promise.resolve(AppState._profilePromise).catch(() => {}),
                new Promise((ok) => setTimeout(ok, AVISO_RENOVADA_ESPERA_PERFIL_MS)),
            ]);
            if (epoca !== epocaDaSessao) return;
            if (filaDaQueda !== null && epocaDaFilaReal() === filaDaQueda) showToast(t('toast.sessionRenewed'), 'info');
            return;
        }
        // A extensão pode ter respondido que o PORTÃO recusou a conta (o nível
        // ou a área mudou no Waze): aí o motivo é esse, não "a sessão venceu",
        // e a pessoa vê o "Acesso restrito" em vez do aviso de queda.
        const negado = tirarNegadoDaExtensao();
        // O "espere a conferência" que o toque no card travado mostrou durante a
        // renovação já não é verdade — ela acabou, e não deu: sai antes do aviso
        // de queda, que diz o contrário (R6-1-03).
        dispensarAvisoDaTrava();
        // E daqui até a tela de entrada o card segue na tela, travado: o toque
        // nele empilhava "Sessão expirada" sob o aviso de queda — dois avisos do
        // mesmo fato, um com o termo que o app deixou de usar pra queda de causa
        // desconhecida (auditoria de 2026-10-02, R7-1-09). O desfecho já está
        // dito (ou o "Acesso restrito" vem já): o toque não avisa mais nada (ver
        // `avisarTravaAoTocar`).
        quedaAnunciada = true;
        if (!negado) showToast(t(MOTIVO_DA_QUEDA[errorKey] || 'toast.sessionExpired'), 'error', 9000);
        setTimeout(() => {
            if (epoca !== epocaDaSessao) return;
            fecharCamadasAbertas(() => {
                if (negado) showAccessDenied(negado);
                showAuthScreen();
            });
        }, UNAUTHORIZED_REDIRECT_MS);
    });
}

// Fecha TUDO que está por cima — mapa ampliado, foto ampliada, modais —, com a
// limpeza de cada um, e devolve as entradas do voltar do aparelho de UMA vez.
//
// A queda da sessão chega no meio do que a pessoa estava fazendo, e o que
// estava aberto ficava por cima do "Bem-vindo!": os Filtros, a foto ampliada
// (com os botões de aprovar e excluir de uma sessão que já não existe) e o mapa
// ampliado (auditoria de 2026-09-26). O `abrirPorCima` é o que mostra a tela de
// entrada — e, antes dela, o "Acesso restrito" quando a própria queda o abre (o
// portão fechou): roda com tudo JÁ fechado, e o diálogo fica. Com tudo fechado,
// o `Presenca.desligar` do `showAuthScreen` (que fecha a conversa e a lista pelo
// `closeModal`) também não acha nada aberto e não mexe no histórico.
//
// Fechar camada por camada pelo caminho normal não serve, e é o gotcha #65:
// cada fechamento AGENDA um `history.back()`, e o diálogo que abre em seguida
// EMPILHA uma entrada que o back pendente come — sobra profundidade sem entrada
// de verdade, e o próximo fechamento tira a pessoa do app. MEDIDO no Chromium e
// no WebKit: `back()` + `pushState()` no mesmo tique termina na BASE; o destino
// do `go()` é calculado na hora da chamada. Daí a ordem daqui: (1) fecha tudo
// SEM mexer no histórico (`viaHistorico`); (2) o que abre por cima empilha a
// entrada DELE; (3) só então as entradas das camadas fechadas saem, num `go`
// só, contado a partir da entrada nova — que é onde o diálogo fica. Medido nos
// dois motores: o diálogo fechado depois volta à base, dentro do app.
function fecharCamadasAbertas(abrirPorCima) {
    if (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()) MapaLightbox.close(true);
    if (Lightbox.isOpen()) Lightbox.close({ viaHistorico: true });
    // Só os abertos: o `closeModal` anota no diário antes de conferir.
    for (const id of MODAL_IDS) {
        const m = document.getElementById(id);
        if (m && !m.classList.contains('hidden')) closeModal(id, { viaHistorico: true });
    }
    const sobrando = CamadaVoltar.profundidade;
    CamadaVoltar.profundidade = 0;
    if (typeof abrirPorCima === 'function') abrirPorCima();
    // Cada camada fechada devolveu o foco a quem a abriu (o botão de Filtros, o
    // mapa do card) — e a tela de entrada acabou de esconder isso tudo. O foco
    // caía no <body>, e quem usa teclado ou leitor de tela recomeçava do topo
    // (medido: Filtros e mapa ampliado abertos na queda; auditoria da costura,
    // 2026-09-26, K13). O diálogo que a queda abre (o portão) fica com o dele.
    const ativo = document.activeElement;
    if (!ativo || ativo === document.body || !focavelNaTela(ativo)) devolverFoco(null);
    if (sobrando > 0) {
        CamadaVoltar.consumindo = true;
        try { history.go(-sobrando); } catch (e) { CamadaVoltar.consumindo = false; }
    }
}

// ── A foto de perfil espera o primeiro card ──────────────────────────────
// Ela é a imagem MAIS PESADA do app e a MENOS importante: 214 KB vindos do
// Waze para aparecer com 32px no cabeçalho, e não existe variante menor
// (sondadas 5 formas de URL, todas devolvem os mesmos 218 KB). O
// `fetchpriority="low"` já a tirou da frente na fila de prioridades, mas os
// bytes continuavam disputando a banda — em 1,6 Mbps são mais de um segundo de
// cano, no exato momento em que o editor espera VER o pedido. Medido no
// relatório de produção: 213 dos 249 KB de economia de imagem eram só ela.
//
// Então ela nem começa a ser buscada antes do primeiro card estar na tela.
// Depois disso ainda espera a thread ficar ociosa — com `timeout`, porque
// página ocupada pode nunca ficar ociosa e aí o avatar nunca chegaria.
//
// A CAIXA fica reservada desde o começo (o `w-8 h-8` com fundo cinza do
// index.html), então quando a foto chega nada se move: trocar peso por
// deslocamento de layout seria péssimo negócio.
let avatarPendente = null;
let telaPronta = false;
// A URL que FALHOU, pra não tentar de novo e — principalmente — pra o ícone de
// imagem quebrada não voltar: `renderProfileHeader` roda a cada troca de idioma
// e reexibiria o <img> morto.
//
// Isto existe por causa de um caso REAL (v2026.09.14-01): o Waze mudou o
// endereço da foto de perfil de `social-row.waze.com/SocialMediaServer/images/
// profile/<id>` pra `sms-profile-image.waze.com/<id>`, que a CSP não conhecia.
// A imagem foi BLOQUEADA antes da rede (medido no HAR do owner: status 0 em
// 0,06 ms, sem IP de servidor) e o cabeçalho passou a mostrar o ícone de
// quebrado. O host novo entrou na CSP, mas isso conserta ESTE endereço, não a
// próxima mudança — e o Waze não avisa quando muda. Foto de terceiro que some
// tem que degradar pro estado que o app já tem pra "perfil sem foto".
let avatarFalhou = null;

function liberarAvatar() {
    if (!avatarPendente || !telaPronta) return;
    const url = avatarPendente;
    avatarPendente = null;
    // A foto é da sessão que a PEDIU. Entre o agendamento (até 2 s de ociosidade)
    // e o disparo cabem um "Sair" e outra conta entrando — e aí o `authenticated`
    // já é verdadeiro de novo, com a foto da conta anterior a caminho do <img>.
    const epoca = epocaDaSessao;
    const carregar = () => {
        const el = document.getElementById('userAvatar');
        // `authenticated` de novo aqui: entre o agendamento e o disparo cabe um
        // logout, e aí a busca sairia já na tela de entrada.
        if (!el || !AppState.authenticated || epoca !== epocaDaSessao) return;
        // `error` cobre TODOS os modos de falha desta imagem com um caminho só:
        // CSP bloqueando, host fora do ar, 404 e rede caída.
        el.onerror = () => {
            avatarFalhou = url;
            el.style.display = 'none';
            // SÓ o host — é o que muda quando o Waze move a foto de lugar, e é
            // a pergunta que custou um print de celular e um HAR pra responder.
            // Nome e id do editor ficam de fora (dado de terceiro no `dfato`).
            let host = '?';
            try { host = new URL(url).host; } catch (e) {}
            dfato('avatar.falhou', { host });
        };
        el.onload = () => { avatarFalhou = null; };
        el.src = url;
    };
    if (typeof requestIdleCallback === 'function') requestIdleCallback(carregar, { timeout: 2000 });
    else setTimeout(carregar, 800);
}

// Chamado de onde a tela DEIXA de depender da rede. Fila vazia e erro de carga
// contam: sem eles, quem abre com tudo tratado ficaria no cinza para sempre.
// Idempotente de propósito — roda a cada swipe.
function marcarTelaPronta() {
    if (telaPronta) return;
    telaPronta = true;
    liberarAvatar();
}

function renderProfileHeader() {
    const p = AppState.profile;
    if (!p) return;
    const badge = document.getElementById('userProfileBadge');
    let avatar = document.getElementById('userAvatar');
    const nameEl = document.getElementById('userName');
    const rankEl = document.getElementById('userRank');
    // A falha degrada pro MESMO estado de "perfil sem foto" (o `else` abaixo),
    // que o app já tinha — em vez do ícone de quebrado do navegador.
    if (p.profileImageUrl && p.profileImageUrl !== avatarFalhou) {
        // Já é esta a foto? Não mexe. Esta função roda de novo a cada troca de
        // idioma, e reatribuir o `src` faz o navegador re-decodificar à toa.
        if (avatar.getAttribute('src') !== p.profileImageUrl) {
            // A foto que está no <img> é de OUTRA pessoa (a conta de antes, na
            // mesma página). Sai já, e a caixa fica no cinza reservado até a
            // nova CARREGAR — nunca a foto de uma conta sob o nome da outra.
            avatar = avatarSemFoto(avatar);
            avatarPendente = p.profileImageUrl;
            liberarAvatar();
        }
        avatar.style.display = '';
    } else {
        avatar.style.display = 'none';
        // Escondida não basta: o `src` antigo seguiria no DOM (e no diagnóstico,
        // que leva o DOM inteiro), com o id de quem estava aqui antes.
        avatarSemFoto(avatar);
    }
    nameEl.textContent = p.userName || '';
    const tags = [];
    if (p.rank !== null && p.rank !== undefined) tags.push('L' + (p.rank + 1));
    if (p.isStaff) tags.push(t('profile.tag.staff'));
    else if (p.isAreaManager) tags.push(t('profile.tag.am'));
    rankEl.textContent = tags.join(' · ');
    // Pontos/edições no tooltip do badge (feature barata; já vem do /Session).
    const pstats = [];
    if (p.totalPoints) pstats.push(t('profile.points', { n: Number(p.totalPoints) }));
    if (p.totalEdits) pstats.push(t('profile.edits', { n: Number(p.totalEdits) }));
    badge.title = pstats.length ? ((p.userName || '') + ' — ' + pstats.join(' · ')) : (p.userName || '');
    badge.classList.remove('hidden');
    const brandTitle = document.getElementById('brandTitle');
    // sr-only (não 'hidden'): some visualmente mas fica na árvore de a11y como h1
    // — mantém a hierarquia de headings contínua (h1 → h2 fila → h3 card).
    if (brandTitle) brandTitle.classList.add('sr-only');
}

// O cabeçalho do perfil é de QUEM ESTAVA aqui. Ele era só ESCONDIDO na tela de
// entrada: a foto, o nome, o nível e o título (com pontos e edições) ficavam no
// DOM — que o diagnóstico leva inteiro —, e a próxima conta que entrasse na
// mesma página aparecia com a FOTO da anterior durante toda a espera da
// primeira busca, porque a dela só é pedida depois do primeiro card (auditoria
// de 2026-09-26). Chamado pelo `showAuthScreen`, por onde passam o "Sair" e a
// queda da sessão.
//
// A foto não sai com `removeAttribute('src')` só: um <img> que JÁ TEVE `src` e
// o perdeu fica "quebrado", e o Chrome desenha o ícone de imagem quebrada no
// círculo do cabeçalho — MEDIDO com a próxima conta entrando, exatamente o
// ícone que o `onerror` do avatar existe pra evitar. O que nunca teve `src` é o
// círculo cinza reservado da primeira entrada. Daí a troca pelo elemento NOVO
// (e sem os ouvintes da foto que estava a caminho: um `onerror` velho marcaria
// a foto da PRÓXIMA conta como falha).
function avatarSemFoto(el) {
    if (!el || !el.hasAttribute('src')) return el;
    el.onerror = null;
    el.onload = null;
    // Tirado ANTES de clonar: o clone com `src` já começaria a baixar a foto.
    el.removeAttribute('src');
    const novo = el.cloneNode(false);
    el.replaceWith(novo);
    return novo;
}

function limparCabecalhoDoPerfil() {
    const avatar = avatarSemFoto(document.getElementById('userAvatar'));
    if (avatar) avatar.style.display = 'none';
    for (const id of ['userName', 'userRank']) {
        const el = document.getElementById(id);
        if (el) el.textContent = '';
    }
    const badge = document.getElementById('userProfileBadge');
    if (badge) {
        badge.removeAttribute('title');
        badge.classList.add('hidden');
    }
}

// Sair = esquecer o user completamente. Apaga sessão, stats, filters,
// preferences, region e country deste dispositivo. Equivale a "reinstalar
// o app". Único item mantido: tema (light/dark) por ser preferência de
// dispositivo, não identidade do usuário. handleUnauthorized (cookies
// expiram pelo Waze) NÃO chama isso — preserva tudo pra próximo login.
// "Sair" deliberado nesta página (ver o `visibilitychange` da extensão).
let saiuNestaPagina = false;

// Quantas decisões o "Sair" descarta: a fila de saída sai com ele (ver abaixo),
// e o que estava nela NÃO chega ao Waze. O diálogo falava dos dados do app e
// não disto — duas decisões esperando a rede sumiam sem aviso nenhum
// (auditoria de 2026-09-29, R4-5 A11). Desenhado ao abrir o diálogo e sempre
// que a fila muda com ele aberto (`updateInFlightIndicator`): a rede que volta
// com o diálogo na tela esvazia a fila, e a frase não pode seguir dizendo que
// algo vai se perder.
function desenharAvisoDoSair() {
    const el = document.getElementById('logoutSaidaAviso');
    if (!el) return;
    // Só o que ESPERA: a decisão que está no ar — nesta aba
    // (`pedidosEmAndamento`) ou na outra (a marca dela) — também mora na fila de
    // saída desde o O2, e já saiu: ela chega ao Waze com o "Sair" no meio. A
    // frase a contava e dizia que ela "não chega" (auditoria de 2026-10-01, R5-1
    // F7).
    const n = carregarFilaDeSaida().filter((x) => x && !pedidosEmAndamento.has(chaveDoPedido(x))
        && !reivindicadoPorOutraAba(x)).length;
    el.textContent = n ? t(n === 1 ? 'modal.logout.saida' : 'modal.logout.saidaPlural', { n }) : '';
    el.classList.toggle('hidden', !n);
}

// `porOutraAba`: o "Sair" foi dado numa OUTRA aba deste aparelho (ver
// `aoSairEmOutraAba`). Aquela já apagou o aparelho e o servidor; esta SOLTA o
// que tem na memória e na tela, e não grava nada no aparelho nem apaga o que é
// dele. Gravar daqui voltaria como aviso pra ela; e apagar podia levar o que
// uma entrada NOVA, feita lá depois do "Sair", já gravou — a aba em segundo
// plano recebe os avisos com atraso (auditoria de 2026-09-29, R4-5 A1). Por
// isso as linhas que mexem no APARELHO levam o `porOutraAba`, e o resto vale
// igual: é a mesma lista, e o que for esquecido numa aba fica esquecido nas
// duas. O modo dev também: o que ele guardou no aparelho, a aba que saiu apagou
// (o "Sair" o desliga), e aqui sai só o da memória.
//
// `outraConta`: não foi "Sair", foi OUTRA conta que entrou noutra aba (ver
// `aoEntrarOutraContaEmOutraAba`). O aparelho agora é dela, e esta aba sai do
// mesmo jeito — sem tocar nele —, com uma diferença: a sessão desta no
// SERVIDOR é outra, que ninguém mais vai apagar. Ela sai daqui, pelo token da
// memória, senão o registro fica órfão até vencer.
//
// `recusado`: não foi "Sair", foi o PORTÃO recusando a conta na reconferência
// (ver `recusaDoPortao`). A recusa é terminal e o "Sair" só existe com sessão,
// então o que é da conta sai do aparelho aqui, pela mesma lista. A sessão já
// caiu (`derrubarSessao`) e o servidor já a apagou: não há diálogo do "Sair" a
// fechar nem sessão a destruir, e o token da memória já saiu.
//
// `naEntrada` (com o `porOutraAba`): esta aba estava na TELA DE ENTRADA, com a
// memória da sessão que CAIU nela (ver `aoSairEmOutraAba`, R12-1-04). Sai a
// mesma lista, menos o que é da tela de entrada: as camadas da sessão já
// fecharam na queda, e o que está aberto agora — o "Colar cookies", o código —
// é de quem está entrando, com o que ela digita (R9-1-03). E sem o aviso: a tela
// não muda, e a sessão desta aba já tinha saído.
async function handleLogout({ porOutraAba = false, outraConta = false, recusado = false, naEntrada = false } = {}) {
    epocaDaSessao++;   // antes de tudo: nenhuma resposta em voo grava daqui pra frente
    saiuNestaPagina = true;
    // Aqui o diálogo do "Sair" é o que está aberto. Na outra aba pode ser
    // qualquer coisa (a foto ampliada, os Filtros, a conversa, o QR do
    // pareamento): tudo fecha, com a limpeza de cada um — mais abaixo, depois de
    // o que estava pendente ser cancelado (ver lá).
    if (!porOutraAba && !recusado) closeModal('logoutModal');
    // Cancela ação pendente ANTES de destruir a sessão: logout = esquecer tudo,
    // então descartamos (não enviamos) o swipe em buffer e evitamos o executor
    // rodando com sessão nula (que mostrava "erro ao marcar" na tela de login).
    if (AppState.pendingAction) {
        AppState.pendingAction.cancel();
        AppState.pendingAction = null;
    }
    // As do lightbox também: a janela delas correria invisível e sairia com o
    // token de quem entrasse depois (ver a função).
    cancelarPendenciasDoLightbox();
    // O "Marcar todos" que ficou no ar é de quem saiu: ele não trava quem
    // entrar (ver `loteDeLidosEmVoo`). Nem a aprovação no ar, desta sessão ou
    // de uma que caiu antes (ver `aprovacoesDaQueda`).
    loteDeLidosEmVoo = false;
    aprovacoesNoAr.clear();
    aprovacoesDaQueda.clear();
    // O token sai do armazenamento AGORA e a limpeza local acontece inteira sem
    // esperar rede nenhuma — pedir pra sair tem que ser instantâneo. As cópias
    // servem pra exclusão no servidor, que vai depois, com retentativa. Na outra
    // aba o token já saiu do armazenamento: só a cópia da memória solta — pelo
    // `setSession`, o diário de sessões ganharia um "token-" por cima do "Sair"
    // que acabou de apagá-lo.
    //
    // QUAIS sessões saem do servidor. Com o app aberto em mais de uma aba, a
    // MESMA conta pode ter sessões DIFERENTES nelas (uma entrou de novo, pelo
    // ACESSAR do WME ou pelos cookies), e o "Sair" apagava só uma — a outra
    // ficava viva no servidor, órfã, por até 21 dias, nos dois sentidos (MEDIDO;
    // auditoria de 2026-10-03, R8-1-03):
    //  · aqui, a desta aba E a GUARDADA no aparelho, quando são outras: este
    //    "Sair" a tira do aparelho e a aba dela sai junto, sem saber que é a dela
    //    que saiu;
    //  · na outra aba, a dela, se não for a que a aba do "Sair" tirou do aparelho
    //    (`tokenTiradoPorOutraAba`), que já saiu do servidor por lá. Sem saber
    //    qual saiu, apaga a dela: o servidor lê antes de apagar, e o pedido a
    //    mais é barato;
    //  · na saída por outra conta, a desta aba — nunca a guardada, que é da
    //    outra;
    //  · na recusa do portão, nenhuma: o servidor já apagou a recusada.
    const tirada = tokenTiradoPorOutraAba;
    tokenTiradoPorOutraAba = null;
    const tokenParaApagar = recusado ? null : !porOutraAba ? API.getSession()
        : outraConta ? (!sessaoDestaAbaEhAGuardada() ? API.sessionToken : null)
        : (API.sessionToken && API.sessionToken !== tirada ? API.sessionToken : null);
    const guardada = porOutraAba || recusado ? null : safeLS.get('waze_session_token');
    const guardadaParaApagar = guardada && guardada !== tokenParaApagar ? guardada : null;
    if (porOutraAba || recusado) API.soltarSessao();
    else API.setSession(null);
    // Na OUTRA aba as camadas abertas fecham SÓ AGORA, como na queda (o
    // `derrubarSessao`): com o que estava pendente cancelado e a sessão, o
    // perfil e o `authenticated` soltos. O fechamento de cada uma roda a limpeza
    // dela, e com eles ainda de pé a da foto ampliada MANDAVA a aprovação que
    // estava na janela do Desfazer, e a da conversa pagava o "lida" que esperava
    // a rajada — os dois com a sessão de quem saiu, e a resposta da aprovação
    // gravava as conquistas no aparelho depois do "Sair", ou no da conta que
    // entrou (auditoria de 2026-10-01: R5-1 F2, R5-3-01, R5-5-6). Sem o perfil,
    // o "lida" fica devendo, e o `Presenca.esquecer` lá embaixo o descarta. A
    // presença não é desligada ANTES: o desligar fecha a conversa pelo caminho
    // que mexe no voltar, e o fechamento daqui devolve as entradas de uma vez
    // (gotcha #65).
    if (porOutraAba) {
        AppState.profile = null;
        AppState.authenticated = false;
        // Na tela de entrada, o que está aberto é de quem está entrando (ver o
        // `naEntrada`, acima): fica.
        if (!naEntrada) fecharCamadasAbertas();
    }
    // Os códigos de pareamento emitidos aqui param de valer (sem esperar rede:
    // sem ela, eles vencem sozinhos em 5 min). Cada aba cancela os que ELA
    // emitiu: o QR que a outra mostrava entraria, por 5 min, numa conta que
    // acabou de sair.
    for (const code of pareamentosEmitidos) API.cancelarPareamento(code).catch(() => {});
    pareamentosEmitidos.clear();
    // As preferências ANTES do `resetQueue`: com o offline ligado, ele abre a
    // base do offline pra conferir de onde é a fila guardada — e, com a base
    // já apagada pelo "Sair", a abriria de novo, vazia.
    AppState.preferences = preferenciasDeFabrica();
    resetQueue();
    AppState.stats = { read: 0, rejected: 0, skipped: 0 };
    AppState.filters = filtrosDeFabrica();
    AppState.devMode = { unlocked: false, active: false };
    // O que o modo dev gravou sai junto — as capturas desta abertura (em
    // memória) e as das anteriores (guardadas no aparelho). Elas levam o DOM,
    // com nome e endereço dos pedidos na tela: "sair é sair de tudo". Antes
    // disto as da memória ficavam até a página fechar, e iriam no relatório de
    // quem entrasse depois e ligasse o modo dev. Na outra aba, as da memória: as
    // do aparelho, a aba que saiu já apagou — e, se foi OUTRA conta que entrou,
    // o aparelho agora é dela.
    if (porOutraAba) dlogApagar({ soMemoria: true });
    else dlogApagar();
    // O anel de chamadas é da sessão que saiu (rotas, ids de pedidos de
    // terceiros, o destino das mensagens): quem entrar depois começa do zero.
    try { API.chamadas.length = 0; } catch (e) {}
    // A lista de recursos do navegador também, pelo mesmo motivo: o diagnóstico
    // a leva inteira, e ela guardava a URL da foto de perfil (com o id de quem
    // saiu) e as fotos dos pedidos de terceiros — MEDIDO depois do "Sair", as
    // duas seguiam lá (auditoria de 2026-09-26). E o que ainda estava no ar — a
    // foto chegando, o ✕ esperando a resposta — não volta pra nenhuma das duas
    // depois da limpeza (ver a função; R8-1-04, L12-1).
    esquecerRegistrosDaPagina();
    AppState.profile = null;
    // A conta que esta aba confirmou (`contaConfirmada`) sai junto: o que era
    // dela já saiu da memória aqui, e quem entrar depois não é uma troca de conta
    // NESTA aba (ver `aoConhecerConta`, R11-1-01).
    contaConfirmadaNestaAba = null;
    presencaWmeZerar();              // o freio e os contadores eram de quem saiu
    AppState.authenticated = false;
    AppState.pendingAction = null;
    AppState.inFlightActions = 0;
    // `null`, e não `{}`: o `loadHistory` só relê o armazenamento com `null`, e
    // um `{}` sem `_total` fazia TODA ação confirmada seguinte (sem recarregar a
    // página) lançar no `recordHistory` — histórico, reincidência, conquistas e
    // o toast "já tratado" sumiam calados, e o lote parava no primeiro sucesso.
    AppState.history = null;
    AppState.conquistas = null;
    atualizarSeloDeConquista();      // o selo é estado de quem entrou: sai junto
    if (!porOutraAba) {
        safeLS.remove(HISTORY_KEY); // logout = esquecer tudo (inclui histórico)
        safeLS.remove(CONQUISTAS_KEY);   // patente, conquistas e contadores somem junto
        // "Sair limpa tudo" não tem exceção que ninguém decidiu: este marcador (o
        // "Agora não" do convite de instalar) ficava pra trás só por descuido.
        safeLS.remove(CHAVE_INSTALL_DISPENSADO);
        safeLS.remove(PERFIL_GATE_KEY);   // rank do último perfil: some com o resto
        safeLS.remove(CONTA_KEY);         // de quem eram os dados: não há mais dados
    }
    // Contagem por autor: é dado de TERCEIRO, sai primeiro (na outra aba, a
    // cópia da memória; o aparelho a que saiu já limpou).
    if (porOutraAba) AppState.autores = null;
    else esquecerAutores();
    esquecerFocoAutor();   // o autor em foco também (reordenava a fila da próxima conta)
    // Fecha o tempo real e apaga o que o chat guardou no aparelho (a
    // instalação, as conversas conhecidas, até onde cada um leu): é de quem
    // entrou, não preferência do aparelho. Na outra aba, só a memória: a
    // conexão com o Google fecha e o que ficou digitado sai.
    if (porOutraAba) window.Presenca?.esquecer?.({ soMemoria: true });
    else window.Presenca?.esquecer?.();
    // Prazo da sessão do Waze: some com o resto.
    if (porOutraAba) AppState.sessaoExpiraEm = null;
    else esquecerPrazoDaSessao();
    if (!porOutraAba) {
        // O diário de sessões e o carimbo de nascimento são do APARELHO, mas saem
        // aqui assim mesmo: o contrato do "Sair" é "limpar de tudo", sem exceção
        // que ninguém decidiu — foi por descuido assim que o marcador do convite de
        // instalar ficou pra trás. E não cega a investigação: quem deu Sair SABE
        // que deu, e o caso investigado é o de quem NÃO saiu e perdeu a sessão.
        registrarEventoDeSessao('saiu');   // fica no anel até a linha seguinte apagá-lo
        safeLS.remove(SESSOES_KEY);
        safeLS.remove(NASCIMENTO_KEY);
        // A fila de saída guarda venueID, updateRequestID e o creatorId de QUEM
        // MANDOU o pedido — dado de terceiro. Sai com o resto, e o efeito assumido
        // é que sair com a fila cheia descarta o que ainda não foi enviado: é
        // exatamente o que "sair é sair de tudo" promete (e o diálogo diz quantos).
        safeLS.remove(SAIDA_KEY);
        // Os pedidos que o app estrelou (`ESTRELADOS_KEY`, R10-2-05): ids de
        // pedidos de terceiros, e a estrela é de quem saiu.
        safeLS.remove(ESTRELADOS_KEY);
    }
    // O que foi decidido nesta página (ids de pedidos de terceiros, em memória).
    // Quem entrar depois começa do zero: a fila dele vem da busca dele. As idas
    // sem resposta das escritas da foto também (R6-3-04): eram de quem saiu. E o
    // que a outra aba decidiu, com os avisos que esperavam a conta (R12-2-01/05),
    // e as fotos que as exclusões de quem saiu tiraram do mapa (R12-3-02).
    pousosDaPagina.clear();
    pedidosEmAndamento.clear();
    idasSemRespostaGuardadas.clear();
    fotosQueSairamDoMapa.clear();
    if (typeof esquecerDecididasPorOutraAba === 'function') esquecerDecididasPorOutraAba({ comOsAvisos: true });
    // A fila guardada tem nome de quem enviou e foto de terceiro. "Sair e sair
    // de tudo" nao abre excecao que ninguem decidiu. Leva junto os pousos
    // gravados (`OFFLINE_POUSOS_KEY`). Na outra aba, a varredura em voo PARA
    // (senão ela gravaria de novo na base que a outra acabou de apagar).
    if (porOutraAba) offlineEsquecer({ soMemoria: true });
    else offlineEsquecer();
    avatarPendente = null;   // a próxima entrada volta a esperar o primeiro card
    avatarFalhou = null;     // outro editor pode ter foto onde este não tinha
    // Casa, trabalho e posição são dado de LOCALIZAÇÃO do editor: sair é sair.
    referenciasDoPerfil = null;
    posicaoGps = null;
    posicaoDoModal = null;
    telaPronta = false;
    if (!porOutraAba) {
        saveStats();
        saveFilters();
        savePreferences();
        saveDevMode();
        API.setRegion('row');
        API.setCountry(30);
    } else {
        // O lugar é da aba (ver `API.lerLugar`), e o "Sair" de lá gravou o de
        // fábrica no aparelho: esta o relê, em vez de seguir no lugar de quem saiu.
        API.esquecerLugar();
    }
    // A lista de países (e os estados) em memória é da região de ANTES, e o lugar
    // acabou de voltar ao de fábrica: entrando de novo nesta aba, os Filtros
    // mostravam os países da NA debaixo da ROW (a lista só é pedida com o cache
    // vazio), e o "Aplicar" tocado sem mexer em nada gravava `row/235`, uma fila
    // vazia (auditoria da rodada 7, R7-6-03). Vale nos três caminhos — este
    // "Sair", o da outra aba e a recusa do portão —, como o lugar. E as listas
    // guardadas por região, que são desta sessão (R9-6-01).
    AppState.countries = [];
    AppState.statesByCountry = {};
    esquecerListasDePaises();
    removeUndoBanner();
    updateInFlightIndicator();
    updateStats();
    updateDevBadge();
    removeCurrentCardEl();
    showAuthScreen();
    if (!naEntrada) showToast(t(outraConta ? 'toast.outraContaNoutraAba' : porOutraAba ? 'toast.saiuNoutraAba' : 'toast.loggedOut'), 'info');

    // A exclusão no servidor é METADE da promessa do "Sair", e falhava calada
    // com a rede fora: o `_post` devolve erro em vez de lançar, então ninguém
    // ficava sabendo. Agora tenta de novo (mesma política de transiente do resto
    // do app) e, se ainda assim não for, diz o que aconteceu e o que acontece
    // depois — o blob fica órfão (a chave é o hash do token, que já foi embora)
    // e expira sozinho em até 21 dias. As duas sessões (ver acima) saem juntas.
    const apagar = [tokenParaApagar, guardadaParaApagar].filter(Boolean);
    if (apagar.length) {
        // `null`: o token vai EXPLÍCITO, e a época já mudou (ver `callWithRetry`).
        const saidas = await Promise.all(apagar.map((tok) => callWithRetry(() => API.destroySession(tok), null)));
        if (saidas.some((saida) => !saida || !saida.success)) {
            showToast(t('toast.logoutServerFailed'), 'error', 9000);
        }
    }
}

function resetQueue() {
    // Fila nova é fila REAL: o treino aberto sai sem devolver a fila salva (ver
    // `Treino.encerrar`). Cobre sair, entrar, atualizar e trocar de filtro.
    if (Treino.ativo) Treino.encerrar();
    tratouNestaFila = false;
    recusaAutomaticaNestaFila = false;
    filaAtravessouSessao = false;   // fila nova: é desta sessão
    puladosNoInicioDaFila = AppState.stats.skipped || 0;
    // Descarrega ação no buffer de undo ANTES de zerar a fila: sem isso, a ação
    // pendente (nunca enviada ao Waze) era re-buscada e o "Desfazer" duplicava o
    // place + dobrava stats. Refresh/filtros honram o swipe (execute); logout e
    // sessão expirada cancelam a ação antes de chamar resetQueue.
    if (AppState.pendingAction) {
        AppState.pendingAction.execute();
        AppState.pendingAction = null;
    }
    // E as do lightbox, que têm janela própria: o `removeUndoBanner` logo
    // abaixo deixava a janela delas correndo sem o botão (L25). Com a fila do
    // gesto ainda de pé — a aprovação sabe dela (`epocaFila`).
    enviarPendenciasDoLightbox();
    removeUndoBanner();
    AppState.fetchEpoch++;              // invalida fetch em voo (descarta obsoleto)
    AppState.queue = [];
    AppState.hasMore = true;
    // Fila nova: o que passou pela anterior pode voltar — é o "atualizar".
    pedidosQueEntraramNaFila.clear();
    filaEsperaPerfil = false;
    bloqueadosPorPagina.clear();
    AppState.ultimaBusca = null;
    // Gesto explícito (atualizar, filtro, tentar de novo) recomeça a conta.
    rebuscasAuto = 0;
    AppState.currentPlace = null;
    AppState.serverTotal = 0;
    AppState.serverBlocked = 0;
    AppState.blockedPartial = false;
    AppState.loadError = false;
    // Fila nova, lugar novo (ver `filaDeOnde`): a busca que vem diz de onde é. A
    // fila guardada do offline NÃO sai daqui: se o lugar mudou, a reabertura a
    // RECUSA (`mesmoLugar`), e a busca com rede do lugar novo a regrava. Apagá-la
    // na troca, como era, levava a preparação inteira no meio da estrada: trocar
    // o filtro SEM REDE e voltar ao de antes não a trazia mais (auditoria de
    // 2026-09-30, R5-4-2).
    filaDeOnde = null;
    updatePendingCount();
}

function showLoading(visible) {
    const el = document.getElementById('loadingCard');
    if (!el) return;
    // O DIÁRIO anota a TRANSIÇÃO, nunca a chamada: o `renderCurrentCard` chama
    // isto a cada card montado — ou seja a cada swipe —, e o `dfato` é anel de
    // 120 sem portão; anotado por chamada, ele engoliria o resto do diário.
    // Com a transição, a linha do tempo do relato de 2026-09-22 teria saído
    // pronta: "carregando" desde a abertura, primeiro card 89 ms depois, e o
    // "carregando" NUNCA saindo.
    const estava = !el.classList.contains('hidden');
    el.classList.toggle('hidden', !visible);
    if (estava !== !!visible) dfato('tela.carregando', { visivel: !!visible });
}

// ═══════════════════════════════════════════════════════════════════════════
//  Perto de mim — ordenar a fila por DISTÂNCIA
// ═══════════════════════════════════════════════════════════════════════════
//
// Três ordens novas no mesmo select de "Ordenar por": casa, trabalho e GPS. O
// celular sabe onde você está e o WME de mesa não, e um pedido a 900 m é um
// pedido que talvez você conheça de verdade.
//
// MEDIDO na fila real do owner (374 pedidos, Brasil inteiro): ordenando por
// casa, só 2 dos 20 primeiros coincidem com a ordem atual — ou seja, isto
// mostra pedidos que hoje ficam enterrados. São 1 a menos de 1 km, 9 dentro de
// 20 km e 19 dentro de 100 km, invisíveis numa fila por data.
//
// A REFERÊNCIA NÃO MORA NO AppState, e isso não é estilo: o `AppState` inteiro
// entra no diagnóstico que o editor manda por WhatsApp, e a coordenada da casa
// dele não pode viajar junto com um relato de bug. Por isso ela vive aqui, em
// escopo de módulo, e some no logout junto com o resto.
let referenciasDoPerfil = null;   // { casa: [lat, lon]|null, trabalho: [lat, lon]|null }
let posicaoGps = null;            // { ll: [lat, lon], precisaoM } — NUNCA persistida
// A posição pedida NO MODAL de Filtros. Só vira a da fila (`posicaoGps`) no
// "Aplicar" (ver `applyFiltersFromModal`): o "Cancelar" depois de um pedido que
// falhou APAGAVA a posição da ordem já aplicada, e a fila seguia dizendo "Perto
// de mim" ordenada por data — e lendo todas as páginas à toa (auditoria de
// 2026-09-29, F5). Também NUNCA persistida, e sai no "Sair" com a outra.
let posicaoDoModal = null;
// Cada pedido de posição tem um número: a resposta de um pedido que a pessoa
// abandonou (trocou de ordem, fechou ou reabriu os Filtros) não escreve nada.
let pedidoDePosicao = 0;

// Abandona o pedido de posição que estiver no ar e esquece a do modal. A
// abertura dos Filtros passa por aqui: a posição de uma abertura não vale na
// outra, e o "Aplicar" deixa de esperar por ela.
function esquecerPosicaoDoModal() {
    pedidoDePosicao++;
    posicaoDoModal = null;
    esperaDosFiltros.gps = false;
}

// As ordens que medem distância em vez de data.
const ORDENS_POR_DISTANCIA = ['casa', 'trabalho', 'gps'];
// O ícone de cada ordem. Ele vivia DENTRO do texto no dicionário, e isso
// custava duas coisas:
//
// (a) **vazava pra prosa** — `filters.sort.hint.negado` interpola o rótulo da
//     ordem padrão numa frase ("a ordem voltou pra «…»"), e com o emoji no
//     texto a frase ganhava um 🆕 no meio, entre aspas;
// (b) o dicionário passava a carregar DECORAÇÃO, então a régua "o mesmo
//     conceito usa o mesmo ícone em todo o app" ficava espalhada por 4 línguas
//     em vez de num lugar só — e conferível por ninguém.
//
// Aqui o ícone é do CONCEITO (a ordem), não da tradução: um mapa só, e o
// dicionário volta a ser texto. Ordem nova entra aqui e no dicionário.
const ORDEM_ICONE = Object.freeze({
    newest: '🆕', oldest: '⏳', casa: '🏠', trabalho: '💼', gps: '📍',
});
const rotuloDaOrdem = (ordem) =>
    (ORDEM_ICONE[ordem] ? ORDEM_ICONE[ordem] + ' ' : '') + t('filters.sort.' + ordem);
// (`ORDEM_PADRAO` mora lá em cima, com os filtros de fábrica: `filtrosDeFabrica`.)

function referenciaDaOrdem(ordem) {
    if (ordem === 'gps') return posicaoGps && posicaoGps.ll;
    if (ordem === 'casa') return referenciasDoPerfil && referenciasDoPerfil.casa;
    if (ordem === 'trabalho') return referenciasDoPerfil && referenciasDoPerfil.trabalho;
    return null;
}

// Haversine, em km, entre dois pares [lat, lon].
//
// O core tem `distanciaEntrePontos`, e ele NÃO serve aqui por dois motivos:
// é módulo de servidor (o app.js é script clássico, não importa de lá) e é
// equiretangular, calibrado pra menos de 1 km. Aqui a fila cobre o país
// inteiro — medido, de 0,9 km a 2.830 km — e nessa escala a aproximação
// reordena. A ordem É o produto deste recurso.
function distanciaKm(a, b) {
    const R = 6371, rad = Math.PI / 180;
    const dLat = (b[0] - a[0]) * rad, dLon = (b[1] - a[1]) * rad;
    const h = Math.sin(dLat / 2) ** 2
        + Math.cos(a[0] * rad) * Math.cos(b[0] * rad) * Math.sin(dLon / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(h));
}

// A coordenada do pedido, SEMPRE [lat, lon].
//
// CUIDADO COM A ORDEM — as duas pontas do app usam ordens diferentes e isso já
// me pegou: `place.mapa.centro` vem do `pontoDeGeometria` do core, que INVERTE
// o GeoJSON de propósito e devolve [lat, lon]; o `homeLocation` do Waze é
// GeoJSON CRU, [lon, lat], e o core já o converte antes de mandar. Ler o centro
// como [lon, lat] não dá erro: dá uma ordenação plausível e ERRADA (medido:
// 500 pedidos "a ~4.000 km", todos praticamente iguais).
function pontoDoPlace(p) {
    const c = p && p.mapa && p.mapa.centro;
    if (Array.isArray(c) && Number.isFinite(c[0]) && Number.isFinite(c[1])) return c;
    if (Number.isFinite(p && p.lat) && Number.isFinite(p && p.lon)) return [p.lat, p.lon];
    return null;
}

// Ordena a fila conforme AppState.filters.sortOrder, no aparelho — sobre a fila
// que ESTÁ nele. Até 500 pedidos o Waze a devolve numa página só; acima disso
// ela vem em páginas, e uma ordem que não é a do Waze só vale depois de a busca
// trazer todas (ver `ordemPrecisaDaFilaInteira`). Este comentário dizia que "o
// Waze devolve tudo de uma vez" — e com 554 pedidos o mais antigo aparecia no
// card 499 (auditoria da fila, 2026-09-26).
//
// `semTrocarOCardDaTela`: a ordem vale JÁ pro RESTO da fila, e o card NA TELA
// fica na frente — é a ordem que chega por baixo dele (uma página nova, o perfil
// que trouxe a casa). A fila INTEIRA não pode ser reordenada com um card na
// tela: ele é o `queue[0]` e a ação vai pra ele (ver o `fetchNextPage`). Isso
// adiava a ordem pro próximo card (`ordemPendente`), e nesse meio o card de
// FUNDO e o aquecimento anunciavam o `queue[1]` da ordem velha: o próximo card
// era outro — MEDIDO, s48 (chega um pedido mais recente) e s49 ("Perto de casa"
// com o perfil chegando depois do 1º card); auditoria de 2026-10-02, R6-2-06.
function sortQueue({ semTrocarOCardDaTela = false } = {}) {
    if (semTrocarOCardDaTela && AppState.currentPlace && AppState.queue[0] === AppState.currentPlace) {
        const naTela = AppState.queue.shift();
        sortQueue();
        AppState.queue.unshift(naTela);
        return;
    }
    const ref = referenciaDaOrdem(AppState.filters.sortOrder);
    if (ref) {
        AppState.queue.sort((a, b) => {
            // Pedido SEM coordenada vai pro FIM — a MESMA regra que o sort por
            // data já usa pra pedido sem data. "Não dá pra ordenar" não é
            // "primeiro da fila". Medido: 0 de 374 na fila do owner, mas o
            // core devolve `mapa: null` quando não há coordenada nenhuma.
            const da = pontoDoPlace(a), db = pontoDoPlace(b);
            if (!da) return db ? 1 : 0;
            if (!db) return -1;
            return distanciaKm(ref, da) - distanciaKm(ref, db);
        });
        manterFocoNaFrente();
        return;
    }
    const asc = AppState.filters.sortOrder === 'oldest';
    AppState.queue.sort((a, b) => {
        // Pedido SEM data vai pro FIM, nos dois sentidos — e o `|| 0` que
        // estava aqui fazia o contrário. Um `dateAdded` nulo virava 0, que em
        // "mais antigos" é o mais antigo possível: o pedido cravava a posição
        // 0 da fila e ficava lá, em toda abertura do app, para sempre.
        //
        // É EXATAMENTE o sintoma que o owner relatou em 2026-09-10 (por outra
        // causa: o rótulo de idade ambíguo). Não estava ativo na fila dele —
        // medido, 370 de 370 com data —, mas o core devolve `ur.dateAdded ??
        // null` (core.mjs:1836), então basta o Waze omitir o campo em UM
        // pedido pra reproduzir o mesmo "isto não sai da minha frente" sem
        // nada na tela explicando.
        //
        // Sem data não é "mais antigo", é DESCONHECIDO — e o fim da fila é o
        // lugar honesto pra isso nas duas ordenações.
        const da = Number.isFinite(a && a.dateAdded) ? a.dateAdded : null;
        const db = Number.isFinite(b && b.dateAdded) ? b.dateAdded : null;
        if (da === null) return db === null ? 0 : 1;
        if (db === null) return -1;
        return asc ? da - db : db - da;
    });
    manterFocoNaFrente();
}

// O FOCO num autor (o "Ver +N") é uma ordem que a PESSOA pediu: a ordenação
// reordena dentro dos dois grupos e nunca espalha a série dele. Sem isto, uma
// página que chegasse durante o foco reordenava a fila no próximo card, a série
// se espalhava e a barra do foco sumia depois de um pedido só (auditoria de
// 2026-09-25). No LUGAR: quem segura a referência da fila segue vendo a mesma.
function manterFocoNaFrente() {
    const foco = AppState.autorEmFoco;
    if (foco === null || foco === undefined) return;
    const q = AppState.queue;
    // A série pela régua ÚNICA (`serieDoAutor`), a mesma do toque que a pôs na
    // frente (`focarAutor`) e da barra que a conta (R6-2-02).
    const dele = serieDoAutor(foco, { naTela: AppState.currentPlace });
    if (!dele.length) return;
    const naSerie = new Set(dele);
    const atual = AppState.currentPlace;
    const fica = atual && q[0] === atual && !naSerie.has(atual) ? atual : null;
    const resto = q.filter((x) => !naSerie.has(x));
    q.length = 0;
    q.push(...dele, ...resto);
    // O card da TELA fica na frente mesmo FORA da série — o que a outra aba já
    // decidiu (R11-2-06, ver `serieDoAutor`). Com a série passando por cima dele,
    // `currentPlace` e `queue[0]` ficavam diferentes, e o gesto seguinte (o
    // `advanceQueue` tira o PRIMEIRO da fila) levava junto um pedido da série,
    // sem decisão nenhuma.
    if (fica) q.unshift(...q.splice(q.indexOf(fica), 1));
}

// Pede a posição ao aparelho. APROXIMADA de propósito (`enableHighAccuracy:
// false`): pra ORDENAR uma fila, errar 1 km não muda a ordem que importa, e
// ligar o GPS fino acende o rádio e demora — a pessoa pediu uma ordem, não uma
// rota. Quem decide a precisão de verdade é o sistema: no Android 12+ a pessoa
// escolhe "precisa" ou "aproximada" ao conceder, e o app não força nada.
//
// NUNCA é chamada na abertura: só quando o editor ESCOLHE "Perto de mim" no
// filtro. Permissão pedida sem gesto é a interrupção que a régua da casa proíbe.
// Só aceita par numérico: o servidor pode mudar e um `null`/string aqui viraria
// NaN na distância, que ordena de forma imprevisível em vez de falhar.
const parDeCoordenadas = (v) =>
    (Array.isArray(v) && Number.isFinite(v[0]) && Number.isFinite(v[1]) ? [v[0], v[1]] : null);

// Guarda casa/trabalho da resposta do perfil. Fora do AppState, de propósito.
function guardarReferencias(res) {
    const r = res && res.referencias;
    referenciasDoPerfil = r
        ? { casa: parDeCoordenadas(r.casa), trabalho: parDeCoordenadas(r.trabalho) }
        : null;
    // A referência pode chegar DEPOIS da primeira página (perfil e fila são
    // buscados em paralelo). Sem isto, quem salvou "perto de casa" veria a
    // primeira fila da sessão em ordem de data com o filtro dizendo outra
    // coisa. Só reordena antes de haver card na tela: re-ordenar por baixo de
    // um card já exibido trocaria o topo da fila sem trocar o que se vê.
    if (!AppState.currentPlace
        && ORDENS_POR_DISTANCIA.includes(AppState.filters.sortOrder)
        && referenciaDaOrdem(AppState.filters.sortOrder)) {
        sortQueue();
    }
}

const GPS_TIMEOUT_MS = 10000;
// Devolve a posição (`{ ll, precisaoM }`) ou o MOTIVO de ela não ter vindo
// (`{ falha }`). Os três erros da API juntavam-se num "não deu" só, com a dica
// do NEGADO ("libere nas configurações e reabra o app") — e dois deles
// acontecem com a permissão CONCEDIDA: posição indisponível e tempo esgotado
// (a localização do aparelho desligada, sem sinal de GPS). Mandar liberar o que
// já está liberado deixava a pessoa sem saída (auditoria de 2026-09-29, F4).
// MEDIDO no Chromium: sem permissão, o código 1 na hora; permissão concedida e
// nenhuma posição, o código 3 aos 10 s.
function pedirPosicao() {
    return new Promise((resolve) => {
        if (!navigator.geolocation) { resolve({ falha: 'semApi' }); return; }
        navigator.geolocation.getCurrentPosition(
            (pos) => resolve({ ll: [pos.coords.latitude, pos.coords.longitude],
                               precisaoM: Math.round(pos.coords.accuracy || 0) }),
            (err) => resolve({ falha: motivoDaFalhaDoGps(err) }),
            { enableHighAccuracy: false, timeout: GPS_TIMEOUT_MS, maximumAge: 300000 }
        );
    });
}

// O código do `GeolocationPositionError` em palavra: 1 = PERMISSION_DENIED,
// 2 = POSITION_UNAVAILABLE, 3 = TIMEOUT. Só o 1 é permissão.
function motivoDaFalhaDoGps(err) {
    const codigo = err && err.code;
    if (codigo === 1) return 'negado';
    if (codigo === 3) return 'tempo';
    return 'indisponivel';
}

// O estado que a dica mostra agora. A troca de idioma a redesenha por ele
// (ver `aplicarIdioma`): a dica é texto do JS, com valor interpolado, e o
// `applyI18n` não a alcança — ficava em português na aba Filtros depois de
// trocar o idioma nas Preferências do mesmo modal (auditoria de 2026-09-29, F6).
let estadoDaDicaDeOrdem = null;

// A linha sob o select: de onde sai a referência, e o que houve com a permissão.
function atualizarDicaDeOrdem(estado) {
    estadoDaDicaDeOrdem = estado || null;
    const el = document.getElementById('filterSortHint');
    if (!el) return;
    const cores = {
        neutro: 'text-slate-500 dark:text-slate-400',
        ok: 'text-emerald-700 dark:text-emerald-400',
        alerta: 'text-amber-700 dark:text-amber-300',
    };
    // A precisão é a da posição que a ordem vai USAR: a pedida neste modal,
    // senão a da ordem já aplicada. E ela é uma DISTÂNCIA como as outras da
    // tela, no formato delas (`formatarMetros`, com a unidade): o metro cru da
    // frase dava "±12346 m" nas 4 línguas onde o card diz "12,3 km" — e a posição
    // aproximada que se pede (`enableHighAccuracy: false`) costuma vir em
    // quilômetros no computador (auditoria da rodada 9, R9-6-05).
    const posicao = posicaoDoModal || posicaoGps;
    const mapa = {
        perfil: ['filters.sort.hint.perfil', 'neutro', {}],
        pedindo: ['filters.sort.hint.pedindo', 'neutro', {}],
        ok: ['filters.sort.hint.ok', 'ok', { d: formatarMetros((posicao && posicao.precisaoM) || 0) }],
        negado: ['filters.sort.hint.negado', 'alerta', { padrao: t('filters.sort.' + ORDEM_PADRAO) }],
        semPosicao: ['filters.sort.hint.semPosicao', 'alerta', { padrao: t('filters.sort.' + ORDEM_PADRAO) }],
    };
    const item = mapa[estado];
    el.classList.toggle('hidden', !item);
    if (!item) return;
    el.className = 'text-[0.6875rem] mt-1 ' + cores[item[1]];
    el.textContent = t(item[0], item[2]);
}

// Monta as opções do "Ordenar por". As de DISTÂNCIA só entram quando há de onde
// medir: casa/trabalho dependem do perfil no WME (nem todo editor cadastrou) e o
// GPS depende de o aparelho ter a API. Oferecer o que não dá pra cumprir é beco
// sem saída — a mesma régua que tirou a extensão de Chrome da frente no celular.
// Uma ordem só vale se houver de onde medir AGORA: perfil sem casa, aparelho
// sem GPS ou permissão negada caem no padrão. Sem esta peneira, `sortOrder`
// ficaria num valor que o `sortQueue` ignora — a fila sairia por data com o
// filtro afirmando distância, calado.
function ordemValida(v) {
    if (v === 'oldest' || v === 'newest') return v;
    if (ORDENS_POR_DISTANCIA.includes(v) && referenciaDaOrdem(v)) return v;
    if (ordemSalvaEsperaOPerfil(v)) return v;
    return ORDEM_PADRAO;
}

// Sem o perfil ainda — o atalho do PWA (`/?action=filters`) abre os Filtros
// ANTES dele, a rede lenta, o perfil que falhou —, não há como saber se casa e
// trabalho existem: a ordem SALVA fica valendo, em vez de virar "Mais
// recentes" no primeiro "Aplicar" (auditoria de 2026-09-29, F2). É o que a
// abertura do app já faz: a carga dos filtros guarda a ordem salva, e o perfil
// que chega a confere (`completarPerfilChegado`; nos Filtros abertos,
// `redesenharFiltrosComOPerfil`). Só a SALVA: oferecer "Perto do trabalho" a
// quem salvou "Perto de casa" seria oferecer o que talvez não exista.
function ordemSalvaEsperaOPerfil(ordem) {
    return !AppState.profile && (ordem === 'casa' || ordem === 'trabalho')
        && AppState.filters.sortOrder === ordem;
}

function popularOrdenacoes() {
    const sel = document.getElementById('filterSort');
    if (!sel) return;
    const disponivel = {
        casa: !!(referenciasDoPerfil && referenciasDoPerfil.casa) || ordemSalvaEsperaOPerfil('casa'),
        trabalho: !!(referenciasDoPerfil && referenciasDoPerfil.trabalho) || ordemSalvaEsperaOPerfil('trabalho'),
        gps: !!(typeof navigator !== 'undefined' && navigator.geolocation),
    };
    for (const ordem of ORDENS_POR_DISTANCIA) {
        const existente = sel.querySelector('option[value="' + ordem + '"]');
        if (!disponivel[ordem]) { if (existente) existente.remove(); continue; }
        const opt = existente || document.createElement('option');
        opt.value = ordem;
        opt.textContent = rotuloDaOrdem(ordem);
        if (!existente) sel.appendChild(opt);
    }
    // As duas de DATA vivem no HTML com `data-i18n`, então o `applyI18n` reescreve
    // o textContent delas e levaria o ícone junto. Decorar aqui é o que mantém as
    // cinco opções com a mesma régua — e é por isso que a troca de idioma chama
    // esta função DEPOIS do `applyI18n` (ver `aplicarIdioma`).
    for (const ordem of ['newest', 'oldest']) {
        const opt = sel.querySelector('option[value="' + ordem + '"]');
        if (opt) opt.textContent = rotuloDaOrdem(ordem);
    }
    // Ordem salva que não existe mais neste perfil/aparelho volta ao padrão em
    // vez de deixar o select num valor fantasma (que o browser mostra VAZIO).
    if (!sel.querySelector('option[value="' + sel.value + '"]')) sel.value = ORDEM_PADRAO;
}

// Trocar pra "Perto de mim" PEDE a posição na hora, e não no Aplicar: o
// resultado da permissão precisa caber na mesma tela em que a escolha foi feita.
// Negado, a ordem volta sozinha pro padrão — deixar "Perto de mim" selecionado
// sem posição seria um filtro que mente sobre o que vai fazer.
async function aoTrocarOrdenacao() {
    const sel = document.getElementById('filterSort');
    if (!sel) return;
    // Toda troca abandona o pedido de posição que estivesse no ar: a resposta
    // dele chegaria depois e escreveria sobre uma escolha que já é outra.
    const meu = ++pedidoDePosicao;
    if (sel.value !== 'gps') {
        esperaDosFiltros.gps = false;
        aplicarEsperaDosFiltros();
        atualizarDicaDeOrdem(sel.value === 'casa' || sel.value === 'trabalho' ? 'perfil' : null);
        return;
    }
    // A posição é pedida A CADA escolha, nunca reaproveitada: a de horas atrás
    // ordenava a fila de quem já tinha mudado de cidade — MEDIDO, a escolha em
    // São Paulo ordenada pelo Rio (auditoria da fila, 2026-09-26). Não liga o
    // GPS à toa: o `maximumAge` da consulta devolve a recente que o navegador
    // guardou. E segue só no GESTO — é este `change`.
    //
    // E o "Aplicar" ESPERA por ela, como espera os países de uma região nova
    // (ver `aplicarEsperaDosFiltros`): tocado com o GPS ainda respondendo, ele
    // gravava "Mais recentes" sem aviso, ou ordenava pela posição de ANTES
    // (auditoria de 2026-09-29, F1). Volta quando ela chega ou falha.
    posicaoDoModal = null;
    esperaDosFiltros.gps = true;
    aplicarEsperaDosFiltros();
    atualizarDicaDeOrdem('pedindo');
    const r = await pedirPosicao();
    // Abandonado no meio (outra ordem, os Filtros fechados ou reabertos): quem
    // abandonou já cuidou do "Aplicar", e a resposta não escreve nada.
    if (meu !== pedidoDePosicao) return;
    esperaDosFiltros.gps = false;
    aplicarEsperaDosFiltros();
    // A pessoa pode ter mudado o select enquanto o prompt estava aberto.
    if (sel.value !== 'gps') return;
    if (!r || !r.ll) {
        // Nem a posição da ordem JÁ aplicada é apagada aqui: ela só muda no
        // "Aplicar" (F5). O que a pessoa vê é a ordem voltando pro padrão, e o
        // porquê — que depende do motivo (F4).
        sel.value = ORDEM_PADRAO;
        const motivo = (r && r.falha) || 'indisponivel';
        atualizarDicaDeOrdem(motivo === 'negado' ? 'negado' : 'semPosicao');
        if (motivo === 'negado') dfato('gps.negado');
        else dfato('gps.semPosicao', { motivo });
        return;
    }
    posicaoDoModal = r;
    atualizarDicaDeOrdem('ok');
    dfato('gps.ok', { precisaoM: r.precisaoM });
}

// O PERFIL chegou com os Filtros ABERTOS: o atalho do PWA (`/?action=filters`)
// os abre antes dele, e a rede lenta e o perfil refeito depois de uma falha
// também. As duas coisas que só ele sabe são redesenhadas — as áreas
// gerenciadas (com o nome) e se casa/trabalho existem —, e o que cada seletor
// mostra FICA: a pessoa pode ter mexido enquanto ele não vinha. Só muda o que
// deixou de existir: a casa que o perfil não tem vira "Mais recentes", como
// numa abertura com ele (auditoria de 2026-09-29, F2). Chamada pelo
// `definirPerfil`, a porta única do perfil.
//
// E as outras duas abas do MESMO modal, que também leem o perfil: a cota do
// Desfazer (Preferências) e o portão de L6 da vitrine e do "Rejeitar sozinho"
// (Histórico). Só a aba Filtros era redesenhada, e as outras ficavam velhas até
// fechar e abrir: o Desfazer travado com "Disponível depois de você logar…", a
// vitrine "1 de 14" sem o "Curador" já ganho, a lista de autores sem o
// interruptor (R12-7-02, MEDIDO nos dois motores, também pelo atalho do ícone;
// auditoria de 2026-10-07). O Histórico só é redesenhado NA TELA
// (`agendarRedesenhoDoHistorico`): fora dela, entrar na aba já o desenha.
function redesenharFiltrosComOPerfil() {
    const modal = document.getElementById('filtersModal');
    if (!modal || modal.classList.contains('hidden')) return;
    populateManagedAreaSelect({ manterEscolha: true });
    const sel = document.getElementById('filterSort');
    const antes = sel && sel.value;
    popularOrdenacoes();
    if (sel && sel.value !== antes) atualizarDicaDeOrdem(null);
    peneirarPaisesComOPerfil();
    renderUndoGateUI();
    agendarRedesenhoDoHistorico();
}

// A lista de países que já estava no seletor quando o perfil chegou entrou SEM a
// peneira dos editáveis: todos os países, sem a dica. Pelo atalho do PWA (os
// Filtros abrem antes do perfil) ou com a rede lenta, dava pra escolher e
// aplicar um país que a pessoa não edita DEPOIS de o perfil chegar — a fila
// vinha vazia ("Confira o país e a região"), e a reabertura seguinte a devolvia
// ao país do perfil, com aviso (auditoria da rodada 7, R7-6-01; é o R66-4 por um
// terceiro caminho). A lista passa pela MESMA peneira da abertura
// (`populateCountrySelect`), com a régua do redesenho: o país que o seletor
// mostra FICA — escolhido antes de haver peneira, ele é da pessoa (achado 11) —,
// e os outros que ela não edita saem. Como o país na tela não muda, o estado e a
// área também não. E aqui não se pede nada.
//
// Só quando a tela mostra a lista da região APLICADA (`AppState.countries`), que
// é a que o app tem pra peneirar — e a prova é o país da tela estar NELA (os ids
// de país são de um servidor só). Com outra região na tela (a troca da pessoa,
// com os editáveis de outro servidor), com o "Carregando…" de uma lista no ar ou
// o "Lista não carregou" (R7-6-04), ou com a lista da volta à região que o app
// não guardou, o país da tela não está nela, e nada muda: quem puser a próxima
// lista no seletor já peneira com o perfil de agora.
function peneirarPaisesComOPerfil() {
    const pais = document.getElementById('filterCountry');
    if (!pais || !Array.isArray(AppState.countries)) return;
    const mostrado = pais.value;
    if (!AppState.countries.some((c) => String(c.id) === String(mostrado))) return;
    populateCountrySelect(AppState.countries, API.getRegion(), mostrado);
}

// Acumula as categorias vistas nos places carregados — fonte do filtro de categoria (B5).
function trackSeenCategories(places) {
    const set = new Set(AppState.seenCategories);
    for (const p of places) {
        if (Array.isArray(p.categories)) for (const c of p.categories) if (c) set.add(c);
    }
    AppState.seenCategories = [...set].sort((a, b) => String(a).localeCompare(String(b), i18nLocale()));
}

// D13 por página (ver `fetchNextPage`): a busca relê as mesmas páginas.
const bloqueadosPorPagina = new Map();

// "MINHA ÁREA" busca pela CAIXA das áreas do perfil: a de gerência (drive)
// primeiro, senão qualquer área com caixa. `null` = o perfil não tem caixa que
// sirva — e aí o filtro não tem como valer.
function caixaDaMinhaArea(perfil) {
    const areas = perfil && Array.isArray(perfil.areas) ? perfil.areas : [];
    const area = areas.find((a) => a && a.type === 'drive' && a.bbox) || areas.find((a) => a && a.bbox);
    return area ? area.bbox : null;
}

// A caixa de "Minha área" NO SERVIDOR da região (por padrão, a de agora). As
// `areas` do `/Session` são POR SERVIDOR, como os editáveis (MEDIDO no Waze
// real: 8 e 1 áreas na ROW, 0 na NA e na IL), e o perfil do `AppState` é o do
// servidor em que ele foi pedido: quem só edita na NA chega na ROW com zero
// áreas, e o `paisDoPerfil` o leva pra NA com a caixa do perfil de LÁ — a que
// ele leu (`anotarEditaveis`).
//
// Servidor NUNCA lido pra esta conta (`servidorNuncaLido`): `undefined` — NÃO SE
// SABE. A caixa do perfil guardado é de OUTRO servidor e não cruza com este: a
// busca ia ao servidor aplicado à mão com a área de outro (o "Tudo limpo! …
// Confira o país e a região" com "Minha área" ligada; auditoria da rodada 11,
// R11-6-01). Quem decide o que fazer sem saber é a busca (`fetchNextPage`: ela
// espera). `null` é saber que lá não há área.
function caixaDaMinhaAreaEm(regiao = API.getRegion()) {
    const perfil = AppState.profile;
    const lidas = editaveisPorServidor.caixas;
    if (perfil && perfil.id !== null && perfil.id !== undefined && editaveisPorServidor.conta === String(perfil.id)
        && lidas && Object.prototype.hasOwnProperty.call(lidas, regiao)) return lidas[regiao];
    if (servidorNuncaLido(regiao)) return undefined;
    return caixaDaMinhaArea(perfil);
}

// "MINHA ÁREA" num servidor que o app NUNCA LEU pra esta conta: a região que a
// pessoa APLICOU à mão nos Filtros. A busca ia ao servidor novo com a caixa do
// perfil de OUTRO servidor (o da abertura) — MEDIDO no navegador: aplicada a NA
// com "Minha área", a busca saía `na bbox` com a caixa do Brasil, nenhum
// `/Session` da NA era pedido, e a tela dizia "Tudo limpo! … Confira o país e a
// região" com "Minha área" ligada (auditoria da rodada 10, R10-6-02). Agora o
// `/Session` de lá é perguntado ANTES de a busca decidir a caixa (como o
// `paisDoPerfil` faz: `API.getProfile(regiao)` + `anotarEditaveis`), e a busca
// espera a resposta (`startFetching`).
//
// A ida que está no ar é dividida, e só a que LEU vale: a resposta boa fica
// anotada (`anotarEditaveis`), e aquele servidor não é perguntado de novo. A
// que FALHOU — o Waze fora (o 500 `transient` do core), a página de erro da
// borda (o 502 que não é JSON), a que NEM CHEGOU (`_motivo`: a rede, o teto de
// 45 s) — não vale pela ida: a busca ESPERA, com "Falha ao carregar" e "Tentar
// de novo" (ver `fetchNextPage`), e o próximo gesto pergunta de novo — uma ida
// por gesto, nenhuma por relógio. Até o lote 14 a falha valia pela SESSÃO
// inteira, e a busca ia com a caixa do perfil de OUTRO servidor: "Tudo limpo! …
// Confira o país e a região" com "Minha área" ligada, e nem o ↻ perguntava de
// novo (MEDIDO no navegador, nos dois motores; auditoria da rodada 11,
// R11-6-01). É a régua da lista de países: a que falha não fica
// (`pedirListaDePaises`). O 401 vai pra conferência da sessão, e a recusa do
// portão é terminal, como na carga do perfil: com a busca esperando, ninguém
// mais os veria. Sem rede nem se pergunta: a busca também não sai (ela mostra o
// "sem sinal"). Na MESMA busca a pergunta não se repete (ver o `startFetching`).
// E só depois de um GESTO: o servidor da busca só fica sem leitura quando a
// pessoa aplica uma região à mão — o da abertura é lido com o perfil, e o da
// ida pro país do perfil, pelo `paisDoPerfil`. Devolve a promessa da ida (no ar
// ou nova), ou `null` quando não há o que perguntar.
let leiturasDaMinhaArea = { epoca: null, noAr: new Map() };
function lerServidorDaMinhaArea(regiao = API.getRegion()) {
    const perfil = AppState.profile;
    if (!AppState.authenticated || !AppState.filters.myArea || !regiao) return null;
    if (!perfil || typeof perfil !== 'object' || perfil.id === null || perfil.id === undefined) return null;
    if (editaveisLidos(regiao) !== null) return null;
    if (leiturasDaMinhaArea.epoca !== epocaDaSessao) leiturasDaMinhaArea = { epoca: epocaDaSessao, noAr: new Map() };
    const estas = leiturasDaMinhaArea;
    if (estas.noAr.has(regiao)) return estas.noAr.get(regiao);
    if (navigator.onLine === false) return null;
    const epoca = epocaDaSessao;
    const ida = Promise.resolve(API.getProfile(regiao)).then((r) => {
        if (epoca !== epocaDaSessao) return;
        // A falha por REDE ou pelo SERVIDOR é a da busca que espera por esta ida
        // (ver `ultimaBuscaFalhouPorRede`, R12-4-02).
        if (minhaAreaFalhouPorRede.epoca !== epoca) minhaAreaFalhouPorRede = { epoca, regioes: new Set() };
        if (r && !r.success && r.errorCategory === 'transient') {
            minhaAreaFalhouPorRede.regioes.add(regiao);
            // Sem resposta nenhuma: o lie-fi da busca que espera por ela (ver
            // `loadProfileAndAuxData`).
            if (typeof r._motivo === 'string') buscaSemResposta = true;
        } else minhaAreaFalhouPorRede.regioes.delete(regiao);
        if (!(r && r.success && r.profile)) {
            if (r && r.errorCategory === 'access_denied') { if (AppState.authenticated) recusaDoPortao(r); }
            else if (r && r.errorCategory === 'unauthorized') handleUnauthorized();
            return;
        }
        // A conta que perguntou: a resposta de outra conta não entra na dela.
        if (!AppState.profile || String(AppState.profile.id) !== String(perfil.id)) return;
        anotarEditaveis(perfil, regiao, r.profile.editableCountryIDs, r.profile.areas, r.profile.managedAreas);
        // Os Filtros reabertos nesse meio mostram o que ele trouxe (a peneira dos
        // países e as áreas gerenciadas de lá).
        redesenharFiltrosComOPerfil();
    }).catch(() => {}).finally(() => {
        estas.noAr.delete(regiao);
    });
    estas.noAr.set(regiao, ida);
    return ida;
}

// A busca recusou "Minha área" porque o perfil não tinha chegado (sinal ruim na
// abertura): o perfil que chegar refaz a fila (`completarPerfilChegado`). Zera
// no `resetQueue` — fila nova é outra busca.
let filaEsperaPerfil = false;

// A DECISÃO do lugar da conta de agora, nesta sessão, já COMEÇOU? `{ epoca,
// conta }` da última que começou (`completarPerfilChegado`).
let decisaoDoLugarDe = null;

// "Minha área" de quem NÃO edita no servidor desta busca — a lista de editáveis
// que o app LEU aqui é vazia, e a pessoa não é staff: a área está noutro
// servidor (a regra do `completarPerfilChegado`, `areaNoutroServidor`,
// R9-6-04) — com a decisão do lugar ainda POR TERMINAR: no ar
// (`_caixaDaMinhaAreaNoAr`) ou nem começada nesta sessão pra esta conta. A troca
// de conta pela renovação refaz a fila DENTRO do `definirPerfil` (o
// `esquecerOutraConta`), antes de a decisão começar: a busca saía na ROW com o
// perfil de quem só edita na NA, "Minha área" era desligada e gravada com "Seu
// perfil do Waze não tem área de edição…" (a frase falsa), a tela dizia "Tudo
// limpo!", e só depois a fila ia pros EUA, pelo país e com o aviso dele (MEDIDO
// no navegador, nos dois motores; auditoria da rodada 11, R11-6-02). Aí a busca
// ESPERA, e quem refaz a fila é a decisão. Vale pra qualquer chamada da busca
// (o `maybePrefetch`, a troca de conta). Decidido o lugar, nada espera: sem área
// em servidor nenhum, ou numa região que a pessoa aplicou à mão, o filtro
// desliga e diz — esperar ali seria esperar pra sempre.
//
// E a decisão que terminou SEM a resposta de um servidor onde a área pode
// estar (`decisaoSemResposta`, auditoria da rodada 12) também espera: não se
// sabe se há área lá. A busca fica em "Falha ao carregar", e a seguinte (o
// "Tentar de novo", o ↻) pergunta de novo — a régua do servidor aplicado à mão
// (R11-6-01).
function areaNoutroServidorSemDecisao() {
    const perfil = AppState.profile;
    if (!perfil || perfil.isStaff || perfil.id === null || perfil.id === undefined) return false;
    const aqui = editaveisLidos(API.getRegion());
    if (!Array.isArray(aqui) || aqui.length > 0) return false;
    if (AppState._caixaDaMinhaAreaNoAr) return true;
    const d = decisaoDoLugarDe;
    if (!(d && d.epoca === epocaDaSessao && d.conta === String(perfil.id))) return true;
    return !!decisaoSemResposta();
}

// A decisão do lugar DESTA conta, nesta sessão, terminou sem destino e SEM a
// resposta de um servidor (ver `paisDoPerfil`) — e o lugar ainda é o daquela
// decisão (o que a pessoa aplica à mão vale por si: a escolha é dela). Devolve
// as regiões que não responderam, ou `null`. E o "Aplicar" que MUDA o lugar
// tira a pendência (`applyFiltersFromModal`): voltando a ele à mão, a escolha
// também é dela, e a pergunta repetida a levava de volta ao país do perfil
// logo depois de ela trocar em Filtros (auditoria da rodada 13, R13-6-05).
function decisaoSemResposta() {
    const d = decisaoDoLugarDe;
    const pendente = d && d.semResposta;
    const perfil = AppState.profile;
    if (!pendente || !perfil || perfil.id === null || perfil.id === undefined) return null;
    if (d.epoca !== epocaDaSessao || d.conta !== String(perfil.id)) return null;
    if (API.getRegion() !== pendente.regiao || String(API.getCountry()) !== pendente.pais) return null;
    return pendente.regioes;
}

// A pergunta que ficou SEM resposta na decisão do lugar (`decisaoSemResposta`)
// sai de novo, SÓ a esses servidores, no COMEÇO de cada busca — o "Tentar de
// novo", o ↻, o "Aplicar", a rede que volta: uma ida por busca, nenhuma por
// relógio, e sem rede nem sai. A busca que a própria decisão refaz, ou que
// esperou por ela, começou com ela no AR, e não repete: ali ela acabou de
// perguntar. A ida fica no ar como a decisão (`_caixaDaMinhaAreaNoAr`): quem
// busca espera por ela. Achou onde a pessoa edita, vai pra lá
// (`irProPaisDoPerfil`, que refaz a fila); de novo sem resposta, segue
// pendente; respondida sem destino, a decisão termina (sem área em servidor
// nenhum, "Minha área" desliga e diz). Devolve a promessa da ida, ou `null`.
//
// Os editáveis "daqui" são os do servidor do LUGAR PENDENTE que o app leu
// (`editaveisLidos`), nunca os do perfil de agora: a sonda de um 401 pergunta o
// perfil na região em que a pessoa ESTÁ, e o `definirPerfil` o guarda — passando
// pela NA à mão, o perfil de agora era o de lá, e a pergunta repetida lia os EUA
// como se fossem da ROW: `row/235`, uma fila que não existe, com "Mostrando a
// fila do país onde você edita" e "Tudo limpo!" (MEDIDO no navegador, nos dois
// motores; auditoria da rodada 13, R13-6-05). Sem leitura de lá, `[]`: a
// pendência só nasce com a lista daqui vazia (ver `paisDoPerfil`).
function refazerDecisaoSemResposta() {
    const regioes = decisaoSemResposta();
    if (!regioes || !AppState.authenticated || AppState._caixaDaMinhaAreaNoAr || navigator.onLine === false) return null;
    const perfil = { ...AppState.profile, editableCountryIDs: editaveisLidos(API.getRegion()) || [] };
    const epoca = epocaDaSessao;
    const estaDecisao = decisaoDoLugarDe;
    const lugar = { regiao: API.getRegion(), pais: API.getCountry() };
    let decidiu = null;
    const decisao = new Promise((ok) => { decidiu = ok; });
    AppState._caixaDaMinhaAreaNoAr = decisao;
    (async () => {
        try {
            const semResposta = [];
            const destino = await paisDoPerfil(perfil, epoca, { so: regioes, semResposta, lugar });
            // A sessão acabou, ou a pessoa aplicou outro lugar no meio (a escolha é
            // dela, e o "Aplicar" que muda o lugar já tirou a pendência): nada
            // aqui decide mais.
            if (epoca !== epocaDaSessao || API.getRegion() !== lugar.regiao || String(API.getCountry()) !== String(lugar.pais)) return;
            estaDecisao.semResposta = semResposta.length ? { regioes: semResposta, regiao: lugar.regiao, pais: String(lugar.pais) } : null;
            if (destino) await irProPaisDoPerfil(destino);
        } finally {
            if (AppState._caixaDaMinhaAreaNoAr === decisao) AppState._caixaDaMinhaAreaNoAr = null;
            decidiu();
        }
    })().catch(() => {});
    return decisao;
}

// A última busca FALHOU POR REDE ou pelo SERVIDOR (`transient`: nada respondeu,
// o teto de 45 s estourou, ou a origem devolveu 5xx). É o que deixa a fila
// guardada do offline entrar com `onLine` dizendo que há rede (ver
// `startFetching` e o "Tentar de novo"). Zera a cada busca que começa.
//
// Com "Minha área", a busca que ESPERA o perfil (ou a caixa do servidor dela)
// nem sai — e a ida que ela espera é a que falhou por rede: o perfil
// (`perfilFalhouPorRede`) ou o `/Session` do servidor da busca
// (`minhaAreaFalhouPorRedeEm`). Pra fila guardada, é a mesma falha. Sem isto, a
// abertura com a rede que não anda (ou a origem fora do ar) terminava em "Falha
// ao carregar" com a fila preparada no aparelho, deste lugar e desta conta, sem
// uso — e o "Tentar de novo" repetia o mesmo: o O1 valia só pra quem não usa
// "Minha área" (auditoria da rodada 12, R12-4-02, MEDIDO no navegador, com a API
// sem resposta e com a borda em 502).
let ultimaBuscaFalhouPorRede = false;
// A última ida do PERFIL (`loadProfileAndAuxData`) falhou por rede ou pelo
// servidor (`transient`). Zera quando a ida seguinte sai.
let perfilFalhouPorRede = false;
// A pergunta ao `/Session` do servidor da busca de "Minha área"
// (`lerServidorDaMinhaArea`) que falhou por rede ou pelo servidor, por região e
// por sessão. A que leu tira a região.
let minhaAreaFalhouPorRede = { epoca: null, regioes: new Set() };
function minhaAreaFalhouPorRedeEm(regiao) {
    return minhaAreaFalhouPorRede.epoca === epocaDaSessao && minhaAreaFalhouPorRede.regioes.has(regiao);
}
// A última busca ficou SEM RESPOSTA nenhuma (a rede fora, o teto de 45 s — não o
// erro do servidor, que respondeu, nem a página de erro da borda: a marca é o
// `_motivo` do `_post`) e nada respondeu DEPOIS: o "lie-fi", em que o
// `onLine` diz que há rede e ela não anda. Pra foto que não abre, é o mesmo que
// sem rede (`marcarCardSemFoto`). Zera com a primeira resposta que chegar
// (`API.aoProvarRede`) ou com a busca que der certo — e NÃO a cada busca que
// começa, como a de cima: a busca no ar não prova rede nenhuma.
let buscaSemResposta = false;

// A ÁREA GERENCIADA salva que o PERFIL não tem — a da conta anterior (a área
// vem do perfil, é de uma conta), ou a tirada no WME — seguia indo em toda
// busca, enquanto os Filtros mostravam "Nenhuma" pra ela
// (`populateManagedAreaSelect`): o que o app mostrava e o que ele usava
// divergiam, até a pessoa abrir os Filtros e tocar "Aplicar" (auditoria de
// 2026-10-01, R5-1 F4 e R56-2). Sai do filtro e é gravado. Devolve se a fila
// tinha saído com ela — com "Minha área" a busca vai pela caixa, não por ela.
// Perfil sem a lista (não se sabe) não decide nada.
//
// A lista que confere é a do SERVIDOR da fila (a região aplicada), quando o app
// a leu: as áreas gerenciadas são por servidor (R10-6-03), e a área do filtro é
// buscada lá. Sem leitura de lá, a do perfil que chegou, como antes.
function esquecerAreaForaDoPerfil(perfil) {
    const salva = AppState.filters.managedAreaId;
    if (!salva || !perfil) return false;
    const lidas = areasGerenciadasLidas(API.getRegion(), perfil);
    const areas = Array.isArray(lidas) ? lidas : perfil.managedAreas;
    if (!Array.isArray(areas)) return false;
    if (areas.some((a) => a && String(a.id) === String(salva))) return false;
    AppState.filters.managedAreaId = '';
    saveFilters();
    return !AppState.filters.myArea;
}

// "Minha área" num perfil SEM caixa: buscar o país com o filtro marcado é filtro
// que mente (a pessoa acha que vê a área dela). Desliga, grava e DIZ — o mesmo
// do "Perto de mim" negado: volta pro padrão e diz por quê.
function desligarMinhaAreaSemCaixa() {
    AppState.filters.myArea = false;
    saveFilters();
    dfato('minhaArea.semCaixa', {});
    showToast(t('toast.minhaAreaSemCaixa'), 'info', 7000);
}

function fetchNextPage() {
    // Reentrância: se já há um fetch em voo, devolve a MESMA promise (não gira
    // busy-loop de microtasks — era o P0 que congelava a aba no startFetching).
    // Só devolve a promessa que EXISTE: `fetching` verdadeiro sem promessa é
    // estado inconsistente (foi o que o treino produzia), e devolver um
    // `Promise.resolve()` ali fazia o laço do `startFetching` girar pra sempre.
    // Sem a promessa, uma busca nova sai — no pior caso, uma busca a mais.
    if (AppState.fetching && AppState._fetchPromise) return AppState._fetchPromise;
    // No treino a fila é de EXEMPLOS: uma busca aqui pousaria pedidos reais nela.
    if (Treino.ativo) return Promise.resolve();
    if (!AppState.hasMore) return Promise.resolve();
    if (!AppState.authenticated) return Promise.resolve();
    // SEM REDE a busca nem tenta: o pedido falharia na hora, e a falha DESISTIA
    // da fila (`hasMore = false`) com um toast vermelho pra quem está num túnel
    // tratando o que já tem. Com card na fila, só espera: a próxima ação busca
    // de novo, e com a rede de volta a busca relê do topo sem perder nem
    // repetir nada. Com a fila VAZIA, a tela certa é a de "sem sinal", nunca o
    // "Tudo limpo!": o `loadError` a pede ao `showNoPlaces`, e é ele que a volta
    // da rede usa pra buscar de novo. O `hasMore = false` ali encerra o laço do
    // `startFetching` — sem ele a espera viraria o laço do gotcha #19.
    // `onLine === false` é a mão confiável da API (o `true` não prova rede).
    if (navigator.onLine === false) {
        if (AppState.queue.length === 0) {
            AppState.loadError = true;
            AppState.hasMore = false;
            dfato('busca.semRede', {});
            // O "Restam" diz "—" (não sei) em vez do número velho com "+": o
            // contador só se redesenha quando alguém o chama (auditoria de
            // 2026-09-25).
            updatePendingCount();
        }
        return Promise.resolve();
    }

    // "MINHA ÁREA" sem a caixa das áreas: a busca saía pelo PAÍS inteiro com o
    // filtro marcado na tela — MEDIDO, `bbox: null, countryId: 30` com o perfil
    // falhando na abertura, e o perfil que chegava depois não refazia nada
    // (auditoria da fila, 2026-09-26). Sem o perfil a busca ESPERA por ele: a
    // tela é a de falha (com "Tentar de novo"), o perfil que faltou é pedido
    // de novo (no máximo 1×/min), e o que chegar refaz a fila. O `hasMore =
    // false` encerra o laço do `startFetching` (gotcha #19). Com o perfil na mão
    // e SEM caixa NO SERVIDOR desta busca (`caixaDaMinhaAreaEm`, R9-6-04), o
    // filtro desliga e diz por quê.
    //
    // E sem SABER a caixa do servidor desta busca — o servidor aplicado à mão que
    // o app nunca leu, porque a pergunta a ele falhou ou nem chegou
    // (`lerServidorDaMinhaArea`) —, a busca também ESPERA, como sem o perfil: a
    // caixa do perfil guardado é de OUTRO servidor, e com ela a tela dizia "Tudo
    // limpo! … Confira o país e a região" com "Minha área" ligada (auditoria da
    // rodada 11, R11-6-01). O "Tentar de novo" pergunta de novo: uma ida por
    // gesto, sem relógio. E sem caixa AQUI, com a área noutro servidor e o lugar
    // ainda por decidir, também espera: quem refaz a fila é a decisão (ver
    // `areaNoutroServidorSemDecisao`, R11-6-02).
    //
    // A espera pelo perfil (ou pela caixa) que FALHOU por rede ou pelo servidor é
    // a busca falhando por rede (ver `ultimaBuscaFalhouPorRede`, R12-4-02): a fila
    // guardada entra como sem "Minha área".
    //
    // E com card na fila a espera é CALADA, e a fila não acaba: o `hasMore` só cai
    // com ela VAZIA, que é o que encerra o laço do `startFetching`. Caindo com card
    // (o `maybePrefetch` dos últimos cards chega aqui), o fim da fila dizia "Tudo
    // limpo!" — com a fila guardada aberta no lie-fi, decididos os cards, "Tudo
    // limpo!" com as decisões esperando envio e o Waze sem resposta (MEDIDO no
    // navegador; sem "Minha área", a mesma fila termina em "Falha ao carregar").
    // É o que a busca que falha por rede com card na tela já faz (`busca.esperaRede`).
    if (AppState.filters.myArea) {
        if (!AppState.profile) {
            filaEsperaPerfil = true;
            ultimaBuscaFalhouPorRede = perfilFalhouPorRede;
            if (AppState.queue.length === 0) { AppState.loadError = true; AppState.hasMore = false; }
            dfato('busca.esperaPerfil', {});
            refazerPerfilSeFaltar();
            updatePendingCount();
            return Promise.resolve();
        }
        const caixa = caixaDaMinhaAreaEm();
        if (caixa === undefined || (!caixa && areaNoutroServidorSemDecisao())) {
            filaEsperaPerfil = true;
            ultimaBuscaFalhouPorRede = caixa === undefined && minhaAreaFalhouPorRedeEm(API.getRegion());
            if (AppState.queue.length === 0) { AppState.loadError = true; AppState.hasMore = false; }
            dfato('busca.esperaCaixa', { regiao: API.getRegion(), por: caixa === undefined ? 'naoLido' : 'decisao' });
            updatePendingCount();
            return Promise.resolve();
        }
        if (!caixa) desligarMinhaAreaSemCaixa();
    }

    AppState.fetching = true;
    // O "Restam" diz "…" (carregando) JÁ: quem o escreveu por último foi o
    // `startFetching` (ou o `resetQueue` do ↻), ANTES de a busca ligar, e com a
    // fila vazia isso dava "0+" — o zero que é o OPOSTO de "não sei" — sob o
    // esqueleto, até a busca voltar (MEDIDO, s47: abertura e ↻ com a busca
    // levando 3 s; auditoria de 2026-10-02, R6-2-04). Com card na fila, nada
    // muda (o ramo do "…" é só com o total zerado).
    updatePendingCount();
    // Época capturada aqui: se resetQueue() rodar durante o await (refresh, troca
    // de filtro, logout), a época muda e descartamos o resultado obsoleto pra não
    // injetar places de filtros/região antigos na fila nova.
    const epoch = AppState.fetchEpoch;
    // E o TREINO: o `entrar()` descarta a busca no ar (sobe a época), mas o
    // `sair()` DEVOLVE a época da fila real (R7-7-04) — e a busca de antes do
    // treino, ainda no ar, voltaria a valer. Ela segue descartada pelo número de
    // vezes que o treino abriu: quem busca de novo é o `sair()`.
    const treinoAntes = Treino.entradas;
    const filters = {
        unreadOnly: AppState.filters.unreadOnly !== false
    };
    if (AppState.filters.types.length > 0 && AppState.filters.types.length < TYPES_ALL.length) {
        filters.types = AppState.filters.types;
    }
    if (AppState.filters.residential === 'true') filters.residential = true;
    if (AppState.filters.residential === 'false') filters.residential = false;
    if (AppState.filters.myArea) {
        // Prefere a área de gerência (drive); cai pra qualquer área com bbox
        // (managed areas não-drive) se não houver drive — amplia o "minha área".
        // Aqui ela EXISTE: sem perfil a busca nem sai, e sem caixa o filtro
        // desligou logo acima. É a do servidor da busca (R9-6-04).
        filters.bbox = caixaDaMinhaAreaEm();
    } else {
        if (AppState.filters.stateId) filters.stateId = AppState.filters.stateId;
        if (AppState.filters.managedAreaId) filters.managedAreaId = AppState.filters.managedAreaId;
    }
    if (Array.isArray(AppState.filters.categories) && AppState.filters.categories.length > 0) {
        filters.categories = AppState.filters.categories; // backend filtra server-side (core.mjs já aceita)
    }
    // Só quando não é a de sempre: o corpo da busca padrão segue igual.
    const orderBy = ordemDoWaze();
    if (orderBy !== 'SORTING_UPDATE_TIME_DESC') filters.orderBy = orderBy;

    // A BUSCA RELÊ A PARTIR DA PÁGINA 1 — sempre, e nunca "a próxima página".
    // MEDIDO em 2026-09-25, na fila real do Brasil e só lendo: o Waze conta a
    // página sobre a lista do MOMENTO do pedido, já sem os lidos. A mesma conta,
    // no mesmo instante, deu 500 + 307 com "lidos também" e 500 + 54 com "só
    // não lidos", e os 4 lidos da página 1 fizeram a página 1 do segundo filtro
    // chegar exatamente 4 pedidos mais fundo. Ou seja: cada pedido que a pessoa
    // trata (ou que outro editor resolve) SOBE os de baixo, e cada pedido novo
    // os DESCE. A próxima página só era pedida quando sobravam 3 cards — depois
    // de a pessoa tratar a página 1 —, e a essa altura a "página 2" já tinha
    // andado: vinha vazia, e o app mostrava "Tudo limpo!" com dezenas de pedidos
    // pendentes (54 na fila do owner naquele dia), que só apareciam ao atualizar.
    //
    // Relendo do topo, o que já passou pela fila sai no filtro
    // (`semOsQueJaPassaramPelaFila`), e o que sobra é o que falta: o que subiu,
    // o que chegou durante a triagem e o que estava depois. A leitura anda pelas
    // páginas enquanto não achar pedido novo — no filtro "lidos também" as
    // primeiras são as já lidas, que continuam pendentes lá — e para quando a
    // fila tem com o que seguir (algo novo, e mais que `PREFETCH_THRESHOLD`),
    // quando o Waze diz que acabou, ou num dos tetos. Na abertura, com a fila
    // vazia, é a página 1 e pronto, como sempre foi. O custo é o mesmo: uma
    // leitura por busca, e mais só onde as primeiras páginas já são conhecidas.
    AppState._fetchPromise = (async () => {
        const busca = { paginas: 0, novos: 0, jaVistos: 0, jaDecididos: 0 };
        // Reposição = a fila já teve pedido antes desta busca (não é a abertura).
        const reposicao = pedidosQueEntraramNaFila.size > 0;
        let semNadaSeguidas = 0;
        try {
            for (let pagina = 1; ; pagina++) {
                // VIGIA a busca: fila congelada não grita, a tela só para — e
                // "parece que acabou o trabalho" ninguém reporta. Ideia do
                // botequei, onde o watchdog flagrou o GPS preso no prompt
                // comendo check-ins.
                dlogVigiar('buscar');
                // O instante em que a LISTA é pedida. Decisão que pousar depois
                // disto pode ou não estar refletida no que o Waze devolver — e
                // por isso sai no filtro (`semOsJaDecididos`). O que pousou
                // antes, a lista já reflete.
                const inicioDaBusca = Date.now();
                // O LUGAR desta busca (ver `filaDeOnde`): o que ela trouxer é de lá.
                const lugarDaBusca = lugarAgora();
                const result = await API.fetchPlaces(pagina, filters);
                // reset (ou o treino) durante o fetch → descarta
                if (epoch !== AppState.fetchEpoch || treinoAntes !== Treino.entradas) return;
                if (!result.success) {
                    dlogVoltou('buscar');
                    dfato('busca.falhou', { key: result.errorKey || null,
                                            cat: result.errorCategory || null });
                    dlogCapturarAuto('buscaFalhou');
                    ultimaBuscaFalhouPorRede = result.errorCategory === 'transient';
                    // Sem resposta NENHUMA (ver `buscaSemResposta`): é o `_motivo`, que
                    // o `_post` só põe quando a resposta NEM CHEGOU. Era o `httpCode`, e
                    // ele não prova nada: a resposta que chega e não é JSON (o 502 da
                    // borda com a origem fora, o 429 da cota, o desafio do WAF) vem SEM
                    // ele, e o core manda `httpCode: 0` quando o WAZE é que está fora
                    // do alcance do servidor — que respondeu. Com rede, o card da foto
                    // que o Waze tirou do ar travava ✕/✓ dizendo "a foto precisa de
                    // sinal" (auditoria de 2026-10-01, R6-4-3).
                    buscaSemResposta = result.errorCategory === 'transient' && typeof result._motivo === 'string';
                    if (result.errorCategory === 'unauthorized') {
                        AppState.hasMore = false;
                        // `loadError` TAMBÉM aqui, e a falta dele foi o defeito que o
                        // owner viu: "Tudo limpo!" sobre 217 pedidos pendentes.
                        //
                        // Este ramo confia no `handleUnauthorized` pra recompor — ou
                        // ele derruba pra tela de entrar (sessão morta), ou ele
                        // rebusca (alarme falso). Só que ele tem uma TRAVA de
                        // concorrência (`verificandoSessao`): ao abrir o app saem
                        // três chamadas quase juntas, e a segunda que chega encontra
                        // a trava fechada e volta NA HORA, sem derrubar e sem
                        // rebuscar. A rebusca do alarme falso também reentra aqui e
                        // encontra a própria trava. Em qualquer desses caminhos
                        // sobrava fila vazia + `hasMore: false` + `loadError: false`,
                        // que o `showNoPlaces` desenha como "Tudo limpo!".
                        //
                        // Marcar aqui é seguro porque quem REBUSCA limpa: o
                        // `startFetching` zera `loadError` antes de tentar. Ou seja,
                        // a flag só sobrevive quando de fato ninguém recompôs — que é
                        // exatamente quando a tela precisa dizer "Falha ao carregar"
                        // com o botão de tentar de novo.
                        //
                        // O comentário do `showNoPlaces` já dizia a intenção desde
                        // sempre ("o editor acharia que zerou o backlog"); faltava
                        // este ramo. E é o pior defeito possível pela régua do
                        // próprio projeto: "parece que acabou o trabalho" ninguém
                        // reporta — o editor fecha o app achando que terminou.
                        AppState.loadError = true;
                        handleUnauthorized();
                    } else if (result.errorCategory === 'transient' && (AppState.currentPlace || AppState.queue.length > 0)) {
                        // A rede caiu NO MEIO da busca, com card na tela: é o
                        // "sem rede com card" do topo da função, só que o `onLine`
                        // ainda não tinha virado (é o caso comum ao entrar num
                        // túnel). Espera calado, como lá: a próxima ação busca de
                        // novo. Antes era toast vermelho, `hasMore = false`,
                        // "Restam —" com cards na fila, e o `online` seguinte
                        // fazia `resetQueue` com o card na tela.
                        dfato('busca.esperaRede', {});
                    } else {
                        // UM anúncio só. Com a fila vazia o `showNoPlaces` desenha
                        // o painel de erro inteiro, e o toast repete o mesmo fato no
                        // RODAPÉ — onde ficam os botões do card. Com card na tela o
                        // painel não aparece, e aí o toast é o único sinal: fica.
                        //
                        // Este é o ramo que de fato pinta o toast vermelho que o
                        // owner viu: o `api.js` RETORNA a falha em vez de lançar,
                        // então o `catch` lá embaixo nem roda. Silenciar só o catch
                        // era mirar no lugar errado — medido na tela, com 2 toasts.
                        if (!!AppState.currentPlace || AppState.queue.length > 0) {
                            showToast(msgDoServidor(result, t('toast.loadPlacesError')), 'error');
                        }
                        AppState.loadError = true;
                        AppState.hasMore = false;
                    }
                    return;
                }

                dlogVoltou('buscar');
                ultimaBuscaFalhouPorRede = false;
                buscaSemResposta = false;
                busca.paginas++;
                dlog('busca.ok', { n: (result.places || []).length, hasMore: !!result.hasMore,
                                   page: pagina, total: result.total });
                AppState.hasMore = !!result.hasMore;
                // Busca que deu certo encerra a cadeia: o teto é de tentativas
                // SEGUIDAS sem sucesso, não da vida da sessão.
                rebuscasAuto = 0;
                // Esta é a chamada que se repete, então é ela que mantém o prazo
                // em dia: se o editor relogar no WME, o Waze passa a mandar um
                // `Expires` novo e o aviso some sozinho, sem o app perguntar nada.
                guardarPrazoDaSessao(result);

                // D13, POR PÁGINA: a busca relê as mesmas páginas, e somar a cada
                // leitura contaria o mesmo bloqueado de novo a cada volta. Backend
                // antigo não manda o campo → 0, e a dica simplesmente não aparece.
                bloqueadosPorPagina.set(pagina, Number(result.blocked) || 0);
                AppState.serverBlocked = [...bloqueadosPorPagina.values()].reduce((a, b) => a + b, 0);

                // O que este aparelho já decidiu não entra de novo — ver
                // `semOsJaDecididos` —, e o que já passou pela fila também não:
                // relendo do topo, o Waze devolve o que continua pendente lá. A
                // contagem abaixo (`serverTotal`) é a da lista FILTRADA: "Restam"
                // é o que falta fazer, e o que está saindo já foi feito.
                const filtrada = semOsJaDecididos(result.places || [], inicioDaBusca);
                const novos = semOsQueJaPassaramPelaFila(filtrada.places);
                busca.jaDecididos += filtrada.excluidos;
                busca.jaVistos += novos.repetidos;
                const newPlaces = novos.places;
                if (newPlaces.length > 0) {
                    AppState.queue.push(...newPlaces);
                    registrarEntradaNaFila(newPlaces);
                    filaDeOnde = lugarDaBusca;
                    // Guardar o texto NAO custa requisicao: ele acabou de chegar.
                    // Sai calado quando o toggle esta desligado. O `desde` é o
                    // começo da BUSCA, não a hora de gravar: é dali que a lista é.
                    offlineGravarFila(inicioDaBusca);
                    AppState.serverTotal += newPlaces.length;
                    busca.novos += newPlaces.length;
                    trackSeenCategories(newPlaces);
                    // Reordenar a fila INTEIRA aqui, com um card já na tela, quebra a
                    // invariante de que o card exibido é o `queue[0]` — e o resto do
                    // app inteiro conta com ela. `advanceQueue` remove o TOPO
                    // (`shift`), mas a ação é enviada pro `currentPlace`: divergindo
                    // os dois, o app rejeita o que você vê e apaga OUTRO da fila, que
                    // some sem ser tratado — e o seu volta na sua frente depois.
                    // MEDIDO no navegador nas três ordens (recentes, antigos e perto
                    // de casa). Então o card da tela fica na frente e só o RESTO entra
                    // na ordem — já, e não no próximo card: adiada, o card de fundo e
                    // o aquecimento anunciavam o `queue[1]` da ordem velha, e o
                    // próximo card era outro (R6-2-06). O `aoMudarAFilaPorBaixo` logo
                    // abaixo refaz o card de fundo com o próximo de verdade.
                    sortQueue({ semTrocarOCardDaTela: true });
                    aplicarRecusaAutomatica();
                    aoMudarAFilaPorBaixo();
                }
                semNadaSeguidas = (result.places || []).length > 0 ? 0 : semNadaSeguidas + 1;

                if (!result.hasMore) break;
                // Com uma ordem que não é a do Waze, a busca segue pelas páginas
                // até o fim (ou o teto): ordenar só a primeira era a ordem valendo
                // pra 500 de 554 (ver `ordemPrecisaDaFilaInteira`).
                if (busca.novos > 0 && AppState.queue.length > PREFETCH_THRESHOLD && !ordemPrecisaDaFilaInteira()) break;
                if (semNadaSeguidas >= MAX_EMPTY_PAGES || busca.paginas >= MAX_PAGINAS_POR_BUSCA) {
                    // Desistimos com o Waze ainda dizendo hasMore → o que contamos
                    // até aqui (inclusive `blocked`) é um PISO, não o total. Sem
                    // esta flag a dica do D13 mostraria número parcial com cara de
                    // exato. Acontece de verdade: região onde o editor não pode
                    // editar nada devolve páginas cheias de bloqueados e zero cards.
                    AppState.blockedPartial = true;
                    AppState.hasMore = false;
                    break;
                }
            }
            if (busca.jaDecididos) dfato('busca.jaDecididos', { n: busca.jaDecididos });
            // Uma linha por busca que releu (reposição, ou mais de uma página),
            // e só contagens: o `dfato` roda pra todo editor.
            if (reposicao || busca.paginas > 1) {
                dfato('busca.reposicao', { paginas: busca.paginas, novos: busca.novos,
                                           jaVistos: busca.jaVistos, hasMore: AppState.hasMore });
            }
            AppState.ultimaBusca = { ...busca, t: Date.now() };
            // Com o offline marcado, o que ENTROU numa reposição vai pra
            // varredura na hora: ela só roda quando vira a janela de 20 min, e
            // sem isto a foto e o mapa desses pedidos esperariam até lá — quem
            // entrasse num túnel antes abriria o card sem foto. A varredura sai
            // calada com o toggle desligado, sem rede ou com a pessoa ociosa, e
            // o que já está guardado volta do cache sem custar rede. Na abertura
            // quem cuida são os gatilhos de sempre.
            // O que chegou vai pra preparação do offline na hora — em TODA busca,
            // não só na reposição. A abertura dependia de "outra resposta chegar
            // depois da fila", e a primeira prova de rede (a própria busca) roda
            // ANTES de a fila existir: quem abria o app em casa e não triava
            // saía sem nada preparado, com as Preferências dizendo "Pronto".
            // Sai calado com o toggle desligado, e só baixa o que falta.
            if (busca.novos > 0) offlineVarrer();
        } catch (error) {
            dlogVoltou('buscar');
            dlog('busca.erro', { erro: String((error && error.message) || error).slice(0, 120) });
            console.error('fetchNextPage error', error);
            if (epoch === AppState.fetchEpoch && treinoAntes === Treino.entradas) {
                // O toast só fala quando o PAINEL não vai falar. Com a fila
                // vazia o `showNoPlaces` desenha o estado de erro inteiro, e
                // somar um toast vermelho é anunciar o mesmo fato duas vezes —
                // com o agravante de que ele pousa no rodapé, onde ficam os
                // botões do card. Com card na tela o painel NÃO aparece, e aí
                // o toast é o único sinal: ele continua.
                const temCard = !!AppState.currentPlace || AppState.queue.length > 0;
                if (temCard) showToast(t('toast.loadPlacesError'), 'error');
                AppState.loadError = true;
                AppState.hasMore = false;
            }
        } finally {
            // Sempre limpa: esta invocação é a dona da flag fetching. Sem o guard
            // de época aqui (senão fetching ficaria preso true e voltaria o freeze).
            AppState.fetching = false;
            AppState._fetchPromise = null;
            updatePendingCount();
        }
    })();
    return AppState._fetchPromise;
}

// O `startFetching` ESPERANDO o perfil pra buscar ("Minha área" sem as áreas
// ainda): a fila está carregando, como com a busca no ar, e o "Restam" diz "…"
// (ver `updatePendingCount`).
let buscaEsperaOPerfil = false;

// A fila que voltou VAZIA com o lugar por decidir espera (ver o fim do
// `startFetching`, R12-6-02) — a DECISÃO no ar inteira, e o PERFIL ainda vindo
// só até um TETO. A espera pelo perfil valia pra toda fila vazia, não só pra de
// quem vai ser levado a outro país: quem edita no Brasil e limpou a fila ficava
// no esqueleto, com "Restam …", até o perfil chegar ou falhar — com o `/Session`
// pendurado, até o teto de 45 s do `_post` (MEDIDO no navegador: 45 165 ms,
// contra 297 ms antes do R12-6-02; auditoria da rodada 13, R13-6-04) —, pra ver o
// mesmo "Tudo limpo!" que a tela já sabia.
//
// Por que 4 s: o perfil normal chega em menos de 1 s, e a busca que volta antes
// dele (a fila vazia de verdade: a do país que a pessoa edita, sem nada) é a que
// espera; a decisão que o perfil traz (a pergunta aos outros servidores, ~1,3 s
// MEDIDOS no R12-6-02) fica FORA do teto. É o mesmo teto que a renovação já usa
// pra esperar o perfil antes de seguir sem ele (`AVISO_RENOVADA_ESPERA_PERFIL_MS`).
// Passado ele, o painel aparece, e o perfil que chegar depois ainda leva a
// pessoa à fila dela, com o aviso de sempre (como antes do R12-6-02): o "Tudo
// limpo!" só volta a piscar pra quem só edita noutro servidor com o perfil
// levando mais de 4 s além da busca.
const FILA_VAZIA_ESPERA_PERFIL_MS = 4000;
async function esperarOLugarDaFilaVazia(promessa) {
    if (promessa === AppState._caixaDaMinhaAreaNoAr) { await promessa; return; }
    let relogio = null;
    const teto = new Promise((ok) => { relogio = setTimeout(ok, FILA_VAZIA_ESPERA_PERFIL_MS); });
    try { await Promise.race([promessa, teto]); } finally { clearTimeout(relogio); }
    // O perfil chegou dentro do teto, e a decisão que ele começou está no ar (a
    // carga só termina depois dela): ela vem inteira, como sempre.
    if (AppState.profile && AppState._caixaDaMinhaAreaNoAr) await AppState._caixaDaMinhaAreaNoAr;
}

async function startFetching() {
    // O `sair()` do treino busca; aqui, o laço abaixo esperaria uma busca que o
    // `fetchNextPage` recusa no treino — seria o laço do gotcha #19.
    //
    // E a pergunta se repete DEPOIS DE CADA `await` (o perfil, a caixa de "Minha
    // área", a busca, a fila guardada): o treino pode ABRIR no meio de uma
    // espera — a abertura com rede lenta ("Carregando…"), ⓘ → "Praticar" —, e
    // esta busca voltava DENTRO dele. Com os exemplos acabados (o "Treino
    // concluído" aberto), o laço chamava o `fetchNextPage`, que no treino volta
    // sem mudar nada, pra sempre: a aba CONGELAVA inteira, sem nem o "Ir para a
    // fila" responder (R11-7-01, MEDIDO no Chromium e no WebKit; auditoria da
    // rodada 11). Com exemplos na fila, ela redesenhava o card de treino e o
    // foco do teclado caía no <body>. Só a guarda daqui não basta: o laço já
    // podia estar no `await`. Quem busca de novo é o `sair()` do treino.
    if (Treino.ativo) return;
    AppState.loadError = false;
    ultimaBuscaFalhouPorRede = false;
    // A fila desta busca: um `resetQueue` no meio (↻, filtro) é outra fila.
    const epoca = AppState.fetchEpoch;
    showLoading(true);
    document.getElementById('noMoreCards').classList.add('hidden');
    document.getElementById('loadErrorState')?.classList.add('hidden');
    removeCurrentCardEl();
    updatePendingCount();

    // A decisão do lugar que ficou SEM a resposta de um servidor pergunta de
    // novo, só a ele, antes da busca (ver `refazerDecisaoSemResposta`): achando
    // onde a pessoa edita, a fila é refeita lá, e esta não vale mais. Antes de
    // qualquer `await`: a busca que começa com a decisão no ar não repete.
    const refazendoADecisao = refazerDecisaoSemResposta();
    if (refazendoADecisao) {
        buscaEsperaOPerfil = true;
        updatePendingCount();
        try { await refazendoADecisao; } catch (e) {} finally { buscaEsperaOPerfil = false; }
        if (epoca !== AppState.fetchEpoch || Treino.ativo) return;
    }

    // "Minha área" precisa do perfil (áreas/bbox). Se ainda não chegou, espera —
    // a busca sem ele não sai (ver `fetchNextPage`). E o perfil que FALHOU é
    // pedido de novo aqui, no máximo 1×/min: é o "Tentar de novo" de quem usa
    // "Minha área", que sem isto só repetia a mesma recusa.
    if (AppState.filters.myArea && !(AppState.profile && AppState.profile.areas)) {
        refazerPerfilSeFaltar();
        if (AppState._profilePromise) {
            // Esperando o perfil a fila está CARREGANDO, e o "Restam" diz "…" —
            // não o "0+" escrito logo acima, que ficava até o perfil chegar
            // (R6-2-04; ver o `updatePendingCount`).
            buscaEsperaOPerfil = true;
            updatePendingCount();
            try { await AppState._profilePromise; } catch (e) {} finally { buscaEsperaOPerfil = false; }
        }
    }
    // E a CAIXA de "Minha área" que ainda está sendo decidida: o perfil que
    // chegou e pergunta aos outros servidores (`completarPerfilChegado`,
    // R10-6-01), ou o `/Session` do servidor que a pessoa aplicou à mão
    // (`lerServidorDaMinhaArea`, R10-6-02). Com o perfil daqui na mão (sem caixa,
    // ou com a de outro servidor), a busca decidia antes: "Minha área" desligava
    // com a frase falsa, ou ia ao servidor novo com a área de outro. A busca
    // espera, e sai UMA vez, no lugar e com a caixa que a decisão deixar. Cada
    // volta espera uma promessa NO AR (as duas se apagam ao terminar), com teto:
    // nunca gira em falso (gotcha #19). E a pergunta ao servidor é UMA por busca:
    // a que não teve resposta não se repete aqui (fica pra próxima busca).
    let perguntou = false;
    for (let volta = 0; volta < 4 && !Treino.ativo && AppState.filters.myArea && AppState.authenticated; volta++) {
        let decidindo = AppState._caixaDaMinhaAreaNoAr;
        if (!decidindo && !perguntou) {
            decidindo = lerServidorDaMinhaArea();
            perguntou = !!decidindo;
        }
        if (!decidindo) break;
        buscaEsperaOPerfil = true;
        updatePendingCount();
        try { await decidindo; } catch (e) {} finally { buscaEsperaOPerfil = false; }
    }

    while (!Treino.ativo && AppState.queue.length === 0 && AppState.hasMore && AppState.authenticated) {
        await fetchNextPage();
    }
    // O treino abriu numa das esperas acima (ver o topo): a tela é dele.
    if (Treino.ativo) return;

    // A busca ESPEROU a decisão do lugar, que está no ar (ver `fetchNextPage` e
    // `areaNoutroServidorSemDecisao`, R11-6-02 — a troca de conta pela renovação
    // a dispara antes de a decisão começar): quem refaz a fila é a decisão, e
    // esta busca espera junto, na tela de carregar, sem o "Falha ao carregar" no
    // meio. Refeita a fila (outra época), quem a desenha é a busca dela. Só sem
    // card pra mostrar: com a fila cheia, ela mostra o que tem.
    //
    // E SEM "Minha área" também: a fila que volta VAZIA com o lugar ainda por
    // decidir. Na primeira abertura (e depois de todo "Sair") o aparelho está no
    // Brasil, e pra quem só edita na NA ou em Israel a busca de lá volta vazia
    // enquanto o perfil pergunta aos outros servidores: a tela dizia "Tudo limpo!
    // … Confira o país e a região" — e o leitor de tela o anunciava — até a
    // decisão levar a pessoa pra fila dela (MEDIDO no navegador, nos dois
    // motores: 1,3 s; auditoria da rodada 12, R12-6-02). Com a decisão no ar, ou
    // com o PERFIL ainda vindo (a busca que volta antes dele: a carga da
    // abertura só termina depois da decisão), a busca espera. Sem refazer a
    // fila, o painel vem depois, e diz a verdade.
    //
    // Só a busca que RESPONDEU vazia: a que FALHOU tem a tela dela — a de falha,
    // ou a fila guardada do "Disponível offline" logo abaixo —, e no "lie-fi" o
    // perfil pendura junto, até o teto de 45 s: esperando por ele, a fila
    // guardada não entrava (MEDIDO no smoke do offline, 9j). E o perfil ainda
    // vindo tem teto próprio (ver `esperarOLugarDaFilaVazia`, R13-6-04).
    const decidindoOLugar = (filaEsperaPerfil && AppState._caixaDaMinhaAreaNoAr)
        || (!AppState.loadError && (AppState._caixaDaMinhaAreaNoAr || (!AppState.profile && AppState._profilePromise)));
    if (decidindoOLugar && !AppState.queue.length && epoca === AppState.fetchEpoch) {
        buscaEsperaOPerfil = true;
        updatePendingCount();
        try { await esperarOLugarDaFilaVazia(decidindoOLugar); } catch (e) {} finally { buscaEsperaOPerfil = false; }
        if (epoca !== AppState.fetchEpoch) return;
    }

    // A busca falhou por REDE ou pelo SERVIDOR com a fila NOVA vazia (a
    // abertura, o ↻, o filtro trocado) — "lie-fi", em que o `onLine` diz que há
    // rede e nada passa (a API pendura até o teto de 45 s), ou a origem fora do
    // ar respondendo 5xx. É pra isso que o "Disponível offline" existe: a fila
    // guardada entra, se for desta conta, deste lugar e deste filtro. Ela só
    // entrava com `onLine === false`, e a espera terminava em "Falha ao
    // carregar" com a fila preparada no aparelho (auditoria de 2026-09-29, O1).
    // Só na fila NOVA: numa fila que a pessoa já trabalhou, os que ela pulou
    // voltariam sozinhos — ali é o "Tentar de novo" que a traz, como sem rede.
    if (!AppState.queue.length && ultimaBuscaFalhouPorRede && pedidosQueEntraramNaFila.size === 0
        && epoca === AppState.fetchEpoch) {
        await abrirGuardadaDepoisDaFalha(epoca);
        // Abriu — por esta chamada ou por outra que esperava a MESMA busca: o
        // card já está na tela, e a busca seguinte sai com o próximo gesto. Ou o
        // treino abriu durante a leitura (a fila guardada ficou anotada nele).
        if (AppState.queue.length > 0 || Treino.ativo) return;
    }

    showLoading(false);
    // O "Restam" das esperas acima ("…", `buscaEsperaOPerfil`) volta a dizer o
    // número: o `showNoPlaces` não o redesenha, e quem desenhou por último foi a
    // espera — o painel dizia "Tudo limpo!" com o contador em "carregando" ao
    // lado, pra sempre (MEDIDO no navegador, nos dois motores; auditoria da
    // rodada 13, R13-6-03). Aqui, e não no fim de cada espera: com a fila
    // refeita no meio (outra época), quem desenha é a busca dela.
    updatePendingCount();

    if (AppState.queue.length > 0) {
        showCurrentPlace();
        maybePrefetch();
    } else {
        showNoPlaces();
    }
}

// Uma tentativa por vez: dois `startFetching` esperando a MESMA busca (a
// promessa dela é compartilhada) abririam a fila guardada duas vezes.
let abrindoGuardadaDepoisDaFalha = null;
function abrirGuardadaDepoisDaFalha(epoca) {
    if (!abrindoGuardadaDepoisDaFalha) {
        abrindoGuardadaDepoisDaFalha = offlineTentarAbrirSemRede(true, epoca)
            .catch(() => false)
            .finally(() => { abrindoGuardadaDepoisDaFalha = null; });
    }
    return abrindoGuardadaDepoisDaFalha;
}

function maybePrefetch() {
    if (Treino.ativo) return;
    if (AppState.queue.length <= PREFETCH_THRESHOLD && AppState.hasMore && !AppState.fetching) {
        fetchNextPage().then(() => {
            if (!AppState.currentPlace && AppState.queue.length > 0) {
                showCurrentPlace();
            }
        });
    }
}

function removeCurrentCardEl() {
    const cardStack = document.getElementById('cardStack');
    // querySelectorAll, e não querySelector: desde a pilha existem DOIS
    // `.place-card` na tela (o da frente e o de fundo). Com `querySelector`
    // esta função tirava só um deles — e qual seria dependia da ordem do DOM,
    // o que é a pior forma de decidir: some o card errado e sobra um pedido
    // fantasma na tela, sem erro nenhum. Todos os 10 chamadores querem dizer
    // "limpa a área do card", então limpar tudo é o que eles já pediam.
    cardStack.querySelectorAll('.place-card').forEach((e) => e.remove());
}

// O card que o editor está TRATANDO — nunca o de fundo, que é só o próximo
// pedido espiando por baixo. FONTE ÚNICA de propósito: `document.querySelector
// ('.place-card')` estava em 9 lugares e passou a ser ambíguo no dia em que a
// pilha nasceu. Dois deles eram graves — o `triggerSwipe` (botão e teclado)
// mandaria SAIR o card errado, e o `aplicarTravaDeAcao` travaria o de fundo
// deixando os botões do da frente vivos durante o Desfazer. Nenhum dos dois dá
// erro no console: a tela simplesmente faz outra coisa.
function cardDaFrente() {
    return document.querySelector('#cardStack .place-card:not(.card-fundo)');
}

// Há um GESTO neste card agora — o dedo nele, a volta pro lugar depois de um
// arraste solto sem decidir, ou a saída? Quem responde é o swipe.js
// (`gestoNoCard`), por SINAL POSITIVO: o `style.transform` não serve, a volta
// pro lugar deixa `translate(0, 0) rotate(0deg)` escrito (R10-4-01). Quem
// esperar o gesto acabar é chamado no fim dele (`aoFimDoGesto`).
function cardSobGesto(card) {
    return !!(card && window.gestoNoCard && window.gestoNoCard(card));
}

// O FIM de um gesto no card — o swipe.js avisa quando a volta pro lugar termina
// e quando a saída termina: o que esperava o card parar roda agora.
function aoFimDoGesto() {
    redesenharCardAdiado();
    if (fabEsperaOGesto) posicionarFabDev();
}

// O PEDIDO QUE O GESTO VIU — e a ação só vale pra ele.
//
// ✕ ↑ ✓, a seta do teclado e o arraste decidem 350 ms DEPOIS do gesto (a
// animação de saída), e os handlers leem `AppState.currentPlace` nessa hora.
// Se a fila andou por baixo nesse meio — a aprovação de uma foto pousando, o
// fim do "marcar todos" —, a ação caía num pedido que ninguém viu. MEDIDO
// (auditoria de 2026-09-26): aprovar a foto de B no lightbox, fechar e dar ✓
// em B com a resposta pousando durante a saída → `marcar-lido` saiu pra C, o
// card seguinte; o mesmo pela seta →, e segurando B no arraste de mouse
// enquanto a aprovação pousava → C REJEITADO.
//
// A regra é uma só e vale pros três caminhos: o card conhece o pedido que
// mostra (registrado no `renderCurrentCard`), o gesto leva o card até o fim,
// e se o pedido da frente já é outro a ação é DESCARTADA — o pedido do gesto
// saiu da fila por outro caminho, e é esse caminho que já decidiu por ele.
// Descartar não deixa buraco na tela: quem trocou o pedido já montou o card
// novo (o `showCurrentPlace` tira o que estava saindo).
//
// Pedido de card é identidade de OBJETO, não de chave: um card redesenhado
// com o MESMO pedido (a exclusão de uma foto dele, por exemplo) segue valendo.
const pedidoDoElemento = new WeakMap();

function pedidoDoCard(card) {
    return (card && pedidoDoElemento.get(card)) || null;
}

function agirNoPedidoDoGesto(alvo, handler) {
    // Sem pedido conhecido (card que não passou pelo render, chamada sem card)
    // o comportamento é o de sempre: descartar aí seria perder o gesto calado.
    if (alvo && AppState.currentPlace !== alvo) return;
    // A trava chegou DURANTE a saída do card (a sessão caiu nesses 350 ms): o
    // handler recusa o gesto, e o card que a animação levou pra fora da tela
    // VOLTA — senão o pedido seguia na frente da fila, invisível e sem botão.
    //
    // A MESMA volta vale pro ✕ e o ✓ num card de foto cuja foto em decisão
    // falhou sem rede nesses 350 ms (`direcaoTravada`): o `onerror` põe o aviso
    // no card que está SAINDO, o `handleReject`/`handleMarkAsRead` recusam, e o
    // card ficava fora da tela (x=-709, opacidade 0) como pedido atual, com só
    // o card de fundo — inerte — na tela e o ↑ inalcançável (auditoria do card,
    // 2026-09-29, C4). Remontado, ele volta com o aviso da foto que precisa de
    // sinal (o `onerror` de novo) e o ↑ vivo. A direção sai do HANDLER, e não
    // de um parâmetro, pra nenhum caminho novo de gesto esquecer de passá-la; o
    // ↑ nunca trava por foto (pular é o que o aviso manda fazer).
    const direcao = handler === handleReject ? 'left' : handler === handleMarkAsRead ? 'right' : null;
    if (acoesTravadas() || (direcao && direcaoTravada(direcao))) {
        if (AppState.currentPlace) showCurrentPlace();
        return;
    }
    handler();
}

// ── "Como funciona": uma vez, no primeiro card ────────────────────────────
// Os três botões do card só têm `aria-label` e `title` — e `title` NÃO existe no
// toque. No celular, quem nunca usou vê três círculos coloridos e adivinha. Não
// havia nada explicando em lugar nenhum do app.
//
// A alternativa era rótulo fixo sob cada botão, e ela foi medida e recusada:
// custa 20px de FOTO em todo card, pra sempre (329 → 309px no iPhone; 181 → 160
// no Fold), pra ensinar o que se aprende uma vez. Este aviso custa zero pixel
// permanente.
//
// Mora no `preferences` (que já é persistido e já é apagado no logout) de
// propósito: chave nova no localStorage exigiria decisão de logout própria e
// entraria na varredura do test/layout — e não há nada aqui que justifique uma.
//
// Ele só abre com a TELA DO CARD LIVRE, e quem pede passa por
// `pedirComoFuncionaAdiado`, que decide DEPOIS da tarefa que pediu (numa
// microtarefa, o mesmo padrão do foco prometido no `renderCurrentCard`). O
// pedido mais comum é o card que monta (`showCurrentPlace`), e no GESTO ele
// vem antes de o `scheduleAction` abrir a janela do Desfazer: decidido na
// hora, o diálogo adiado (R6-7-2) abria no 1º ✕ e o banner do Desfazer (z-70)
// ficava por cima do "Entendi" e do "Quero treinar antes" — no iPhone SE e
// com o celular deitado, o toque caía no "Desfazer" e desfazia o ✕, com o
// diálogo ainda aberto; e pelo teclado o foco ia pro ⓘ, perdendo o ✕ do card
// seguinte (R7-7-01, auditoria de 2026-10-02). Os outros pedidos são os
// momentos em que a tela fica livre: o card que destrava (`aplicarTravaDeAcao`,
// o fim da janela) e a camada que fecha (`aoFecharCamada`) — antes de
// qualquer gesto, como no 1º card.
let comoFuncionaPedido = false;
function pedirComoFuncionaAdiado() {
    if (comoFuncionaPedido || AppState.preferences.comoFuncionaVisto) return;
    comoFuncionaPedido = true;
    queueMicrotask(() => {
        comoFuncionaPedido = false;
        // Acessório: uma falha aqui nunca derruba quem pediu (o card, a trava).
        try { mostrarComoFuncionaSePrimeiraVez(); } catch (e) { console.error(e); }
    });
}

// Um voltar NOSSO no ar (`CamadaVoltar.consumindo`): a camada fechou por um
// caminho do app e o `history.back()` dela ainda não chegou. A tentativa espera
// o `popstate` que o consome (o ouvinte logo abaixo).
let comoFuncionaEsperaVoltar = false;
// O VOLTAR DO APARELHO fechou uma camada: até um gesto novo da pessoa, o
// diálogo não abre. Empilhar uma entrada depois de um voltar do navegador SEM
// gesto novo faz o Chrome marcar as entradas do app como "puláveis" (History
// Manipulation Intervention: o voltar iniciado pelo navegador tira o valor da
// ativação de antes, e só um gesto novo devolve), e o voltar seguinte SAI do
// app em vez de fechar o diálogo. MEDIDO pelo aviso que o próprio Chromium dá
// (`NavigationEntryMarkedSkippable`, no Audits do DevTools): a foto ampliada
// fechada pelo voltar depois de uma aprovação abria o adiado e dava o aviso.
// O voltar NOSSO (`history.back()` do app) não tira o valor da ativação: depois
// dele, empilhar é seguro.
let comoFuncionaEsperaGesto = false;

function mostrarComoFuncionaSePrimeiraVez() {
    if (AppState.preferences.comoFuncionaVisto) return;
    if (Treino.ativo) return;   // o treino É o "como funciona"; ver `Treino.entrar`
    // Só quando existe card na tela: o aviso fala dos botões DELE, e aparecer
    // sobre "Tudo limpo!" ou sobre o esqueleto de carregamento explicaria algo
    // que a pessoa não está vendo.
    if (!AppState.currentPlace || !cardDaFrente()) return;
    // Nem por cima de uma camada que a PESSOA abriu enquanto a fila carregava
    // (modal, foto ou mapa ampliados): o `openModal` a esconde e roda a limpeza
    // dela — apagava o QR do "Conectar outro aparelho" no meio do pareamento e
    // jogava fora a escolha ainda não aplicada dos Filtros (R6-7-2, auditoria de
    // 2026-10-01). É interromper sem ser chamado, desfazendo o que ela fazia.
    // Sem marcar como visto: ele espera a camada fechar (`aoFecharCamada`).
    if (!semCamadaAberta()) return;
    // Nem com o card TRAVADO, e a trava que mais aparece é a janela do
    // Desfazer: o banner dela fica por cima dos modais e cobre os botões do
    // diálogo (R7-7-01). Ele espera o card destravar (`aplicarTravaDeAcao`).
    // Explicar os botões de um card travado também não faria sentido.
    if (acoesTravadas()) return;
    // Nem com um voltar NOSSO no ar: o `openModal` empilharia a entrada do
    // diálogo no mesmo tique do `history.back()` pendente, que a come (gotcha
    // #65) — e o "Entendi", o Esc ou o voltar do aparelho tiravam a pessoa do
    // app. Era o fechar da foto ampliada que ANDA a fila depois de uma
    // aprovação (R7-3-01, auditoria de 2026-10-02).
    if (CamadaVoltar.consumindo) { comoFuncionaEsperaVoltar = true; return; }
    if (comoFuncionaEsperaGesto) return;
    abrirComoFunciona();
}

// O `popstate` do voltar NOSSO chegou: a tentativa que esperava por ele vai de
// novo. Registrado DEPOIS do ouvinte do `CamadaVoltar` (a ordem do arquivo é a
// ordem dos ouvintes), então o `consumindo` aqui já é o depois.
window.addEventListener('popstate', () => {
    if (!comoFuncionaEsperaVoltar || CamadaVoltar.consumindo) return;
    comoFuncionaEsperaVoltar = false;
    pedirComoFuncionaAdiado();
});

// Um gesto novo da pessoa: as mesmas regras da ativação do navegador (HTML,
// "activation triggering input event") — a tecla que não é o Esc, o botão do
// mouse que desce e o dedo ou a caneta que SOBEM. Em captura, pra valer mesmo
// quando alguém para a propagação.
function gestoDaPessoaParaOComoFunciona(ev) {
    if (!comoFuncionaEsperaGesto) return;
    if (ev.type === 'keydown' && ev.key === 'Escape') return;
    if (ev.type === 'pointerdown' && ev.pointerType !== 'mouse') return;
    if (ev.type === 'pointerup' && ev.pointerType === 'mouse') return;
    comoFuncionaEsperaGesto = false;
}
for (const tipo of ['keydown', 'pointerdown', 'pointerup']) {
    window.addEventListener(tipo, gestoDaPessoaParaOComoFunciona, true);
}

// Uma camada FECHOU (modal, foto ou mapa ampliados). Por um caminho do app (✕,
// Esc, fundo, "Entendi"): o diálogo que esperava tenta de novo — antes de
// qualquer gesto, como no 1º card —, e a tentativa espera o voltar nosso ser
// consumido. Pelo VOLTAR do aparelho (`viaHistorico`): espera um gesto novo
// (ver `comoFuncionaEsperaGesto`). A queda da sessão fecha tudo pelo mesmo
// caminho (`fecharCamadasAbertas`) e também espera: é só o adiado esperando o
// próximo toque. Chamado no FIM de cada fechamento; o que o próprio fechamento
// pediu no meio (a foto que anda a fila ao fechar) é decidido depois, na
// microtarefa, já com a marca.
//
// E os avisos de UMA vez que esperavam a camada fechar (R13-7-01) — DEPOIS do
// "Como funciona": as duas microtarefas rodam na ordem, ele decide primeiro e,
// aberto, o aviso espera por ele em vez de ficar por baixo. São banners, sem
// entrada no voltar: nem o voltar do aparelho nem o nosso no ar os seguram.
function aoFecharCamada(viaHistorico) {
    if (!AppState.preferences.comoFuncionaVisto) {
        if (viaHistorico) comoFuncionaEsperaGesto = true;
        else pedirComoFuncionaAdiado();
    }
    pedirAvisosAdiados();
}

// Direto no `openModal`, mesmo vindo da Ajuda: ele JÁ esconde o modal anterior
// sem passar pelo `closeModal`, e só empilha histórico quando não havia nenhum
// aberto. Minha primeira versão fechava a Ajuda antes "para não empilhar" — e
// era exatamente isso que quebrava: `closeModal` CONSOME a entrada do histórico
// e o `openModal` seguinte, vendo nenhum modal aberto, empilhava outra. Medido,
// o Esc depois disso levava a `about:blank` — a pessoa saía do app inteiro.
//
// Quem abre, à mão ou sozinho, dá o diálogo por VISTO. O "Ver de novo" da Ajuda
// aberto enquanto a fila carregava não marcava: o card montava com ele aberto,
// o adiado ficava esperando, e o diálogo reabria no 1º gesto — com o banner do
// Desfazer por cima (R7-7-02, auditoria de 2026-10-02).
function abrirComoFunciona() {
    if (!AppState.preferences.comoFuncionaVisto) {
        AppState.preferences.comoFuncionaVisto = true;
        savePreferences();
    }
    openModal('comoFuncionaModal');
}

// O "Ver de novo" da Ajuda é um GESTO, e ele chega também logo depois de um ✕
// ou ✓, com a janela do Desfazer correndo. O automático espera a janela
// (`acoesTravadas`, R7-7-01); o aberto à mão não esperava, e o banner (z-70)
// ficava por cima do "Entendi" e do "Quero treinar antes": no iPhone SE e com o
// celular deitado, o toque no "Entendi" caía no "Desfazer" e desfazia a decisão
// por trás do diálogo, sem nada ir ao Waze (R12-7-03, MEDIDO nos dois motores;
// auditoria de 2026-10-07). Ele DESPACHA a janela antes de abrir, como o
// "Praticar" (`Treino.entrar`) e a folha da presença: a decisão sai agora, e o
// banner sai com ela. Sem janela, nada muda.
function verDeNovoComoFunciona() {
    despacharJanelaDoDesfazer();
    abrirComoFunciona();
}

// O tipo do pedido, em UMA função: o rótulo visível e o que o leitor de tela
// ANUNCIA têm que dizer a mesma coisa, no mesmo idioma. Eram duas cópias, e a
// da região viva nunca foi traduzida (ver o comentário no call site).
//
// "Reporte (Sinalização)" não diz o que foi reportado; quando é foto, o WME
// chama de "Foto sinalizada", e o card marca QUAL das fotos é.
// `updateTypeKey` é a chave crua (VENUE, IMAGE, FLAG…); o `updateType` em
// português segue vindo do core e serve de último recurso, pra chave nova
// nunca deixar o campo vazio — feio, nunca invisível.
function rotuloDoTipo(place) {
    if (!place) return '';
    if (Array.isArray(place.changes) && place.changes.length > 0) return t('card.type.update');
    if (place.flagSubjectType === 'IMAGE') return t('card.type.flagImage');
    return rotuloDeEnum('card.updateType.', place.updateTypeKey) || place.updateType || '';
}

function showCurrentPlace() {
    marcarTelaPronta();   // libera a foto de perfil (ver `liberarAvatar`)
    try {
        renderCurrentCard();
    } catch (err) {
        console.error('Erro ao montar card, pulando place:', err, AppState.queue[0]);
        if (window.showToast) {
            window.showToast(t('toast.renderCardError'), 'error');
        }
        AppState.queue.shift();
        // Place quebrado descartado conta como tratado: decrementa o total e
        // atualiza o contador (invariante do serverTotal — antes superconta).
        AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
        AppState.currentPlace = null;
        updatePendingCount();
        if (AppState.queue.length > 0) {
            setTimeout(showCurrentPlace, 0);
        } else if (AppState.hasMore) {
            startFetching();
        } else {
            showNoPlaces();
        }
        return;
    }
    // FORA do try de propósito: uma falha aqui não pode fazer o card ser tratado
    // como quebrado e o pedido ser DESCARTADO (o catch acima faz `queue.shift()`
    // e decrementa o total). O aviso é acessório; o pedido é o produto. E é
    // PEDIDO, não aberto: no gesto, a janela do Desfazer abre logo depois desta
    // linha (ver `pedirComoFuncionaAdiado`, R7-7-01).
    try { pedirComoFuncionaAdiado(); } catch (e) { console.error(e); }
}

let primeiroCardAnotado = false;   // `tela.primeiroCard`: uma vez por página
// O pedido que a região viva do card anunciou por último. O card é REDESENHADO
// por muita coisa que não troca o pedido da frente — a foto excluída sem o
// Desfazer, a foto que volta, o idioma —, e cada redesenho dizia "Novo pedido:
// <o mesmo local>" a quem usa leitor de tela (achado da auditoria de
// 2026-10-01). O anúncio sai quando o pedido da frente MUDA: outro pedido, ou
// um que volta depois de a frente ficar vazia (ela zera isto).
let pedidoAnunciado = null;
function renderCurrentCard() {
    const place = AppState.queue[0];
    if (!place) {
        AppState.currentPlace = null;
        pedidoAnunciado = null;
        if (AppState.hasMore) {
            showLoading(true);
            startFetching();
        } else {
            showNoPlaces();
        }
        return;
    }

    AppState.currentPlace = place;

    // Anuncia o novo card a leitor de tela (a fila avança sem foco mudar) — só
    // quando o pedido da frente é OUTRO (ver `pedidoAnunciado`).
    const liveRegion = document.getElementById('cardLiveRegion');
    if (liveRegion && place !== pedidoAnunciado) {
        pedidoAnunciado = place;
        liveRegion.textContent = t('card.live.newRequest', {
            name: identidadeDoPlace(place).titulo,
            // A MESMA função do rótulo visível. Aqui estava `place.updateType`
            // cru — o português que o core manda como último recurso —, então
            // quem usa leitor de tela em en/es/fr ouvia português em TODO card.
            // Não dava pra ver: região viva não aparece na tela, e por isso
            // passou por auditoria visual nenhuma.
            type: rotuloDoTipo(place) ? ', ' + rotuloDoTipo(place) : ''
        });
    }

    const card = montarCard(place);
    // O pedido que ESTE card mostra: é por ele que o gesto confere, na hora de
    // agir, se a fila não andou por baixo (ver `agirNoPedidoDoGesto`).
    pedidoDoElemento.set(card, place);
    renderFocoAutor();

    // Botões de ação explícitos — gesto é atalho, nunca o único caminho
    // (M3/HIG). Também é o único caminho acessível a leitor de tela.
    //
    // Ficam FORA do `montarCard` porque o card de fundo não pode tê-los: ele
    // já é `inert` e `pointer-events:none`, mas ouvinte pendurado num botão
    // que só não dispara por causa de OUTRA camada é o tipo de coisa que
    // volta a disparar no dia em que alguém mexe na camada. Aqui não há o que
    // desfazer: o botão do fundo nunca chega a ser ligado.
    let actionFired = false;
    const fireAction = (direction, handler, ev) => {
        if (actionFired) return;
        actionFired = true;
        // Enter/Espaço no botão FOCADO: o foco vai ao botão equivalente do card
        // que ficar na tela (ver `pedirFocoDoTeclado`).
        pedirFocoDoTeclado(ev && ev.currentTarget, !!ev && ev.detail === 0, direction);
        if (window.triggerSwipe) window.triggerSwipe(direction, () => agirNoPedidoDoGesto(place, handler));
        else handler();
    };
    card.querySelector('.card-btn-reject').addEventListener('click', (ev) => fireAction('left', handleReject, ev));
    card.querySelector('.card-btn-skip').addEventListener('click', (ev) => fireAction('up', handleSkip, ev));
    card.querySelector('.card-btn-read').addEventListener('click', (ev) => fireAction('right', handleMarkAsRead, ev));
    // O toque no ✕ ↑ ✓ TRAVADO responde com o porquê (ver `avisarTravaAoTocar`).
    // Botão `disabled` não recebe `click` — o navegador o suprime —, mas o
    // `pointerdown`/`pointerup` chegam, e sobem até a barra: MEDIDO no Chromium
    // 153 e no WebKit 26, com mouse e com toque. É por eles, e não trocando o
    // `disabled` por `aria-disabled`, porque o `disabled` é o que tira do Tab e
    // faz o leitor de tela anunciar o travado (gotcha #63). O par na MESMA
    // barra é o "clique": o fim de um arraste que só termina ali não conta.
    const barraDeAcoes = card.querySelector('.card-actions');
    let tocouTravado = null;
    const botaoTravado = (ev) => {
        const b = ev.target && ev.target.closest && ev.target.closest('.card-btn-reject, .card-btn-skip, .card-btn-read');
        return b && b.disabled ? b : null;
    };
    barraDeAcoes.addEventListener('pointerdown', (ev) => { tocouTravado = botaoTravado(ev); });
    barraDeAcoes.addEventListener('pointerup', (ev) => {
        const b = botaoTravado(ev);
        if (b && b === tocouTravado) avisarTravaAoTocar();
        tocouTravado = null;
    });

    // Ampliar o mapa é interação, então segue a MESMA regra dos três botões
    // acima: mora no card da frente, nunca no `montarCard`. Antes ficava
    // dentro do `renderMapa`, que roda mais de uma vez por card — e aí cada
    // passada pendurava outro ouvinte no mesmo elemento (`stopPropagation`
    // não impede o irmão; isso seria `stopImmediatePropagation`).
    // O box existe sempre no template, mesmo quando o mapa não é o primeiro
    // slide: pendurar aqui é uma vez por card, e o clique só chega quando ele
    // está visível.
    const mapaBoxF = card.querySelector('.card-map');
    if (mapaBoxF) {
        mapaBoxF.addEventListener('click', (ev) => {
            if (ev.target.closest('button')) return;   // as setas do carrossel não
            ev.stopPropagation(); ev.preventDefault();
            MapaLightbox.open(place);
        });
    }


    // O card novo nasce travado se a janela do Desfazer ainda estiver correndo
    // (o `undo` devolve o place anterior à fila e re-renderiza).
    card.classList.toggle('acoes-travadas', acoesTravadas());
    for (const cls of ['.card-btn-reject', '.card-btn-skip', '.card-btn-read']) {
        card.querySelector(cls).disabled = acoesTravadas();
    }

    // As duas ÚNICAS áreas que podem rolar (nunca as duas no mesmo card: reporte
    // é FLAG, mudanças é UPDATE). O swipe.js já não pega o gesto dentro delas.
    marcarBordaRolagem(card.querySelector('.card-changes-list'));
    marcarBordaRolagem(card.querySelector('.card-flag-comment-text'));

    // Rede de segurança: o layout acima é dimensionado pra caber sempre, mas
    // fonte gigante do sistema, zoom só-de-texto ou uma tela deitada muito baixa
    // podem estourar mesmo assim — e conteúdo cortado sem jeito de alcançar é
    // pior que perder o gesto. Quando dispara, o arraste vertical rola em vez de
    // pular (o botão ↑ nunca some) — e o esmaecido avisa que ainda tem coisa.
    marcarBordaRolagem(card.querySelector('.card-content'));
    vigiarEstouroDoConteudo(card.querySelector('.card-content'));

    // O card novo nasce SEM EFEITO NENHUM — decisão do owner, e o porquê de
    // cada coisa que já esteve aqui (mola, escala, fade) está medido no
    // styles.css, junto com o que o fade arrastava atrás de si.
    removeCurrentCardEl();
    document.getElementById('cardStack').appendChild(card);
    // Agora que a caixa existe. Sem isto o card da frente também guarda o
    // enquadramento do fallback — o observer só o corrige quando a caixa
    // CRESCE, e num card com diff ela encolhe. Ver `desenharMapaComCaixa`.
    desenharMapaComCaixa(card, place);
    // O aviso de "a foto precisa de sinal" NÃO nasce aqui: ele vem do `onerror`
    // da foto em decisão (ver `renderCardImages`). Posto no render, ele se
    // antecipava à imagem e escondia a foto que estava guardada.
    // Quem está deslizando está usando o app: a varredura não dorme.
    offlineMarcarGesto();
    // Tira o .celebrate junto: sem isso o confete não reinicia quando a fila
    // zerar de novo (a classe ficaria pendurada do "Tudo limpo!" anterior).
    document.getElementById('noMoreCards').classList.remove('celebrate');
    document.getElementById('noMoreCards').classList.add('hidden');
    // CARD NA TELA ⇒ NENHUM PAINEL POR CIMA DELE, e a regra mora AQUI porque
    // todo caminho que monta um card passa por esta função. O esqueleto
    // (`#loadingCard`, z-50) nasce VISÍVEL no HTML, e só o `startFetching` o
    // escondia — a abertura sem rede, que de propósito não chama o
    // `startFetching`, montava o card POR BAIXO dele: relato de 2026-09-22, app
    // reaberta no modo avião com 236 pedidos guardados, o card montado e o mapa
    // carregado do cache, e a tela parada no esqueleto. Nenhum smoke via porque
    // o helper que monta cards chamava `showLoading(false)` por conta própria.
    showLoading(false);
    document.getElementById('loadErrorState')?.classList.add('hidden');
    // UMA vez por página: o instante em que o primeiro pedido ficou pronto.
    // Junto do `tela.carregando`, é o par que separa "o card nunca montou" de
    // "montou e ficou coberto" — os dois pareciam a mesma tela parada.
    if (!primeiroCardAnotado) {
        primeiroCardAnotado = true;
        dfato('tela.primeiroCard', { fila: AppState.queue.length });
    }
    agendarAquecimento(card);
    // O card que chega DEPOIS do gesto do teclado (a próxima página, quando a
    // fila acabou) também recebe o foco prometido. Depois da tarefa, e não
    // aqui: o `scheduleAction` do mesmo gesto trava o card logo em seguida, e o
    // foco num botão que vira `disabled` se perde (ver `aplicarFocoDoTeclado`).
    if (focoDoTeclado) queueMicrotask(aplicarFocoDoTeclado);
}

// Monta UM card a partir de UM pedido e devolve o elemento — sem pendurar na
// tela, sem ouvinte, sem observador. Nasceu de dentro do `renderCurrentCard`
// quando a pilha passou a precisar montar DOIS: o da frente e o de fundo.
// O que ficou de fora daqui ficou de propósito — é tudo que só o card da
// frente pode ter (ouvintes de botão, a trava do Desfazer, os
// ResizeObserver de rolagem, a mola de entrada e o aquecimento).
function montarCard(place) {
    const template = document.getElementById('cardTemplate');
    const clone = template.content.cloneNode(true);
    const card = clone.querySelector('.place-card');

    const ident = identidadeDoPlace(place);
    const elNome = card.querySelector('.card-name');
    elNome.textContent = ident.titulo;
    elNome.classList.toggle('valor-ausente', ident.ausente);
    elNome.classList.toggle('titulo-endereco', ident.tituloEhEndereco);
    // `semNome` segue verdadeiro (o local É sem nome, e outros pontos podem
    // querer saber); o que muda é MOSTRAR — ver ausenciaDeNomeEsperada.
    card.querySelector('.card-no-name-badge')
        .classList.toggle('hidden', !ident.semNome || ausenciaDeNomeEsperada(place));
    // Categoria vai CRUA, de propósito. Traduzi as mais comuns uma vez e o owner
    // reverteu com um motivo que eu não tinha: o Waze REGIONALIZA categoria por
    // país, então uma tabela fixa pt/en/es/fr está errada fora do recorte onde
    // foi medida — e "errado com cara de certo" é pior que o enum. O identificador
    // cru também é o que casa com o WME quando o editor vai conferir lá.
    // Quando aparecer a fonte de regionalização do Waze, dá pra tentar de novo.
    escreverValor(card.querySelector('.card-category'),
        place.categories && place.categories.length > 0 ? place.categories.join(', ') : '',
        'card.categories.empty');
    // Endereço que virou título não se repete embaixo: seria a mesma informação
    // duas vezes, gastando uma linha que a caixa de mudanças usa melhor.
    card.querySelector('.card-address-row').classList.toggle('hidden', ident.tituloEhEndereco);
    escreverValor(card.querySelector('.card-address'), place.address, 'card.address.empty');
    // Num UPDATE o backend monta o tipo como "Atualização: Id, Nome, Telefone…" —
    // exatamente os rótulos que a caixa "Mudanças propostas" repete logo abaixo,
    // COM os valores. Mostrar os dois era a mesma informação duas vezes, e a de
    // cima truncada. Com a lista na tela, o tipo diz só o que ela não diz.
    card.querySelector('.card-type').textContent = rotuloDoTipo(place);
    const elTipo = card.querySelector('.card-type');
    escreverValor(elTipo, elTipo.textContent, 'card.type.empty');
    escreverValor(card.querySelector('.card-creator'), place.createdBy, 'card.creator.empty');
    renderSelosDeProcedencia(card, place);

    if (place.isDelete) {
        card.querySelector('.card-delete-banner').classList.remove('hidden');
        // O banner âmbar já diz "⚠ Pedido de remoção", e a linha "TIPO:" dizia a
        // MESMA frase logo abaixo — era ela que truncava: em francês, a 320px,
        // "Demande de suppression" pede 171px numa caixa de 162 e vira
        // "Demande de suppressio…". Mesma lição do UPDATE, que já não repete a
        // enumeração de campos: espaço não se acha apertando, se acha tirando
        // repetição.
        //
        // Some o RÓTULO e o TEXTO, não a linha: a idade ("há 3d") mora nela e é
        // informação de decisão num pedido de remoção. Tentei antes mover a
        // idade pra dentro do banner e não funciona — `applyI18n(card)` roda
        // depois e o banner tem `data-i18n`, que escreve textContent e apaga
        // qualquer filho anexado (gotcha #24).
        const linha = card.querySelector('.card-type-row');
        if (linha) {
            const rotulo = linha.querySelector('[data-i18n="card.type"]');
            if (rotulo) rotulo.classList.add('hidden');
            const tipo = linha.querySelector('.card-type');
            if (tipo) tipo.classList.add('hidden');
        }
    }

    if (place.isStarred) {
        card.querySelector('.card-starred').classList.remove('hidden');
    }

    const ageStr = formatRelativeTime(place.dateAdded);
    if (ageStr) {
        const ageEl = card.querySelector('.card-age');
        ageEl.textContent = ageStr;
        ageEl.title = new Date(place.dateAdded).toLocaleString(i18nLocale());
        ageEl.classList.remove('hidden');
    }

    // A faixa "já lido". Só aparece quando o Waze diz que ESTE pedido já foi
    // lido — o que, com o filtro no padrão ("Apenas pedidos não lidos"), nunca
    // acontece, porque o pedido lido nem é devolvido. Ou seja: custo zero de
    // foto no fluxo em que a fila é triada, e a resposta pronta pra quem
    // desmarcou o filtro e estranha o pedido voltar depois de marcá-lo. Foi um
    // relato real, com a MESMA marcação feita duas vezes no mesmo pedido antes
    // de o editor desconfiar.
    card.querySelector('.card-read-banner')?.classList.toggle('hidden', place.isRead !== true);

    // Reporte: o motivo (`flagType`) é a informação principal e quase sempre a
    // ÚNICA — o comentário livre vem vazio na maioria dos casos. O app só olhava
    // o comentário, então o card de reporte saía sem dizer por que o local foi
    // denunciado, enquanto o WME mostrava "Motivo da marcação: Inapropriado".
    if (place.flagType) {
        // Enum não mapeado aparece CRU, pela mesma razão do diff de mudanças:
        // esconder o motivo de uma denúncia é pior que mostrá-lo em inglês.
        let motivo = rotuloDeEnum('card.flagType.', place.flagType);
        // "Duplicado" sozinho não é um motivo: é meia frase. O WME escreve
        // "Duplicado DE <local>", e o alvo é justamente a informação que decide
        // — sem ela o editor tem que abrir o WME só pra saber de quem. O core
        // resolve o nome quando consegue (ver `resolverDuplicados`); quando não
        // consegue, fica a forma isolada, que é o que o app já mostrava.
        // Só com NOME. Alvo achado e sem nome existe, e aí a frase completa
        // sairia `Duplicado de “(local sem nome)”` — aspas em volta de
        // parênteses, que é a marca de placeholder do app: duas convenções
        // empilhadas dizendo a mesma ausência. Nesse caso o texto volta a ser o
        // de hoje e quem responde "onde" é o marcador no mapa, que continua lá.
        if (place.flagType === 'DUPLICATE' && place.duplicado && place.duplicado.nome) {
            motivo = t('card.flagDuplicateOf', { alvo: place.duplicado.nome });
        }
        // A distância vai no TEXTO e não só no mapa porque o mapa nem sempre é
        // o primeiro slide (`mapaVemPrimeiro()`): num pedido com foto o editor
        // pode decidir sem nunca deslizar até ele, e aí "onde" ficaria sem
        // resposta. É também o que separa na hora o duplicado plausível do
        // vizinho parecido — medido na fila real: 94 · 96 · 101 · 110 · 146 m.
        if (place.duplicado && Number.isFinite(place.duplicado.distM)) {
            motivo += ' · ' + formatarMetros(place.duplicado.distM);
        }
        const valorDoMotivo = card.querySelector('.card-flag-reason-value');
        valorDoMotivo.textContent = motivo;
        // O valor tem teto de duas linhas (C16, ver o index.src.html): o que o
        // corte esconder de um nome longo fica inteiro no `title`.
        valorDoMotivo.title = motivo;
        card.querySelector('.card-flag-reason').classList.remove('hidden');
    }
    // A caixa aparece só quando HÁ texto livre — ela existe pra segurá-lo. Antes
    // ela vinha junto com o motivo e, sem texto, sobrava um retângulo rosa
    // gastando ~40px de moldura numa linha vazia. (O número que estava aqui —
    // "15 de 17 reportes" — vinha de uma amostra pequena e brasileira; medido
    // em 438 reportes de 13 países, 60% TÊM texto, e nos dois tipos mais comuns
    // passa de 86%. A caixa aparecer só com conteúdo continua certo; o que
    // estava errado era chamar o conteúdo de raro.) O malabarismo de flex que existia aqui pra ela não
    // reivindicar a sobra saiu junto: sem conteúdo, ela simplesmente não existe.
    if (place.flagComment) {
        const cx = card.querySelector('.card-flag-comment');
        const txt = card.querySelector('.card-flag-comment-text');
        txt.textContent = place.flagComment;
        cx.classList.remove('hidden');
        // O que sobra da janela se alcança ROLANDO dentro da própria caixa —
        // não há botão. O aviso de que sobra texto é a borda esmaecida, e ela
        // é armada logo abaixo por `marcarBordaRolagem`, junto com as outras
        // áreas roláveis do card.
    }

    // O ↗ do card e o ↗ da folha de leitura saem da MESMA função
    // (`linkWmeDoPedido`): eram duas montagens iguais em lugares diferentes, e
    // é assim que uma ganha um parâmetro e a outra não.
    //
    // O parâmetro venueUpdateRequest do WME espera o venueID (formato dotted
    // tipo "205522459.2055159053.3242788"), NÃO o id do venueUpdateRequest
    // (que é um UUID). Confirmado via HAR comparando URL do WME nativo.
    //
    // A URL é CANÔNICA, sem segmento de idioma (decisão do owner). Estava
    // `/pt-BR/editor`: um editor que usa o app em francês clicava no ↗ e caía
    // num WME em português. O `/editor` cru responde 200 direto (medido, sem
    // redirect HTTP) e o Waze resolve o idioma pela conta de quem abriu — que é
    // exatamente o certo, porque quem decide não somos nós.
    prepararLinkDoWme(card.querySelector('.card-wme-link'), place);

    renderCardImages(card, place);

    const brandRow = card.querySelector('.card-brand-row');
    const brandStr = (place.brand !== null && place.brand !== undefined) ? String(place.brand).trim() : '';
    if (brandStr !== '') {
        card.querySelector('.card-brand').textContent = brandStr;
        if (place.brandKnown === true) {
            card.querySelector('.card-brand-known').classList.remove('hidden');
        } else if (place.brandKnown === false) {
            card.querySelector('.card-brand-unknown').classList.remove('hidden');
        }
        brandRow.classList.remove('hidden');
    }

    renderCardChanges(card, place);

    // BUG CORRIGIDO: o card é clonado de um <template>, e conteúdo de template
    // NÃO é alcançado por document.querySelectorAll — então o applyI18n() global
    // nunca via estas 25 chaves. Resultado: em inglês/espanhol o card voltava pro
    // português A CADA SWIPE (o clone traz o texto pt hardcoded do HTML).
    // Traduzir aqui, no clone, é o único ponto que pega todo card novo.
    atualizarSeloDePular(card, place);
    if (typeof applyI18n === 'function') applyI18n(card);

    return card;
}

// O ↗ do card. O de um EXEMPLO sintético do treino (`_exemplo`) não levava a
// lugar nenhum: o `venueID` dele ("treino1") não existe, e o ↗ abria o WME sem
// nada selecionado — o treino ensinando errado (R10-7-01, MEDIDO no navegador;
// auditoria de 2026-10-07). Ação impossível sai da frente: o card do exemplo
// fica sem ele. O clone de um pedido real (`Treino.neutralizar`) mantém o
// `venueID` real, e o ↗ abre o lugar certo.
function prepararLinkDoWme(link, place) {
    if (!link) return;
    const semLugar = !!(place && place._exemplo);
    link.classList.toggle('hidden', semLugar);
    if (semLugar) link.removeAttribute('href');
    else link.href = linkWmeDoPedido(place, API.getRegion());
}

// ── A PILHA: o próximo pedido aparece POR BAIXO do atual ────────────────────
//
// Ideia de um colega do owner, pelo paralelo com o Tinder: ao puxar o cartão
// pro lado já se vê o de baixo, sem concluir o gesto.
//
// O que ela NÃO faz, e isto foi MEDIDO antes de virar código: não acelera nada.
// Eu tinha previsto que sim — que ver o próximo adiantaria a decisão — e a
// medição derrubou. Ela entra pelo efeito visual, com o owner sabendo disso.
//
// Três decisões que não são gosto:
//
// 1. O VÉU É 35%, e o número tem escopo (gotcha #40). Mockups no app real, dois
//    aparelhos × dois temas: sem véu os dois cards ficam com o MESMO peso — dois
//    ✓ verdes igualmente acesos, e quem diz qual é o ativo é a posição, que
//    durante o arraste é justamente o que está mudando. A 55% funciona no tema
//    claro e QUEBRA no escuro: o card de fundo quase funde com o fundo da tela,
//    e aí some o que o recurso existe pra mostrar. O mesmo véu pesa mais sobre
//    um card que já é escuro. A 35% lê nos dois, e é por isso que o valor é UM
//    só e não um por tema.
//
// 2. ELE NASCE COM O AQUECIMENTO, não junto com o card da frente. A foto do
//    card é o LCP do app, e montar o de fundo na mesma hora põe a foto do
//    PRÓXIMO pedido disputando banda com a que o editor precisa ver AGORA — o
//    defeito exato que o `agendarAquecimento` já tinha medido e consertado
//    (189 KB atropelando 12 KB). Pendurar na mesma espera é uma política só; uma
//    espera própria seria uma segunda, pra envelhecer sozinha.
//
// 3. O QUE ELE CARREGA JÁ ESTÁ NA MÃO. O aquecimento aquece o primeiro slide E
//    o resto do card de `queue[1]` — inclusive o tile do mapa quando é ele que
//    vem primeiro (gotcha #54). O card de fundo desenha exatamente esse pedido,
//    logo depois: sai do cache. Custo de rede da pilha: ZERO.
// O mapa só sabe se enquadrar quando a caixa EXISTE, e ela só existe no DOM.
//
// `renderMapa` mede com `box.clientWidth || 400`: fora do DOM isso é 0 e ele
// enquadra pra 400×240 — um tamanho que não é o de card nenhum. O observer de
// `vigiarCaixaDoMapa` conserta só metade dos casos, porque ele refaz quando a
// caixa CRESCE (encolher não abre buraco, e refazer à toa é custo por quadro).
// Quando a caixa real é MENOR que o fallback — card com diff, que deixa pouca
// altura pro mapa — ele não refaz, e o enquadramento fica calculado pra outra
// proporção: 400×240 é 1,67 e 359×144 é 2,49, então o zoom escolhido é outro.
//
// MEDIDO nos dois sentidos: o card de fundo guardava 400×240 numa caixa de
// 359×337 (faixa sem mapa embaixo, o que o owner fotografou), e o da frente
// guardava 400×240 numa caixa de 359×144 (enquadramento de outra proporção).
// Chamar isto depois do `appendChild` conserta os dois pela raiz, em vez de
// repor o observer perdido no clone.
function desenharMapaComCaixa(card, place) {
    const box = card && card.querySelector('.card-map');
    // Escondido a caixa mede 0 e cairíamos no mesmo fallback. O mapa que não é
    // o primeiro slide se desenha quando o editor navega até ele — e aí o card
    // já está no DOM, que é justamente a condição que falta aqui.
    if (!box || box.classList.contains('hidden')) return;
    try { renderMapa(card, place, true); } catch (e) { /* mapa nunca derruba o card */ }
}

function montarCardDeFundo() {
    const stack = document.getElementById('cardStack');
    if (!stack) return;
    // IDEMPOTENTE de propósito. Ele é agendado junto com o aquecimento e pode
    // disparar com a fila já tendo andado (o editor é mais rápido que a foto).
    // Em vez de tentar cancelar o agendamento — que é como se perde o caso que
    // ninguém imaginou —, ele relê o estado AGORA e refaz. Disparo atrasado
    // vira trabalho repetido, nunca card errado na tela.
    stack.querySelectorAll('.card-fundo').forEach((e) => e.remove());
    if (!cardDaFrente()) return;
    const proximo = AppState.queue[1];
    // Último da fila: não há próximo a revelar, e a pilha simplesmente não
    // existe — por baixo fica o fundo da tela. Desenhar ali o "Tudo limpo!"
    // seria anunciar o fim antes de a ação ter sido confirmada, e a janela do
    // Desfazer pode devolver o pedido.
    if (!proximo) return;
    let fundo;
    try {
        fundo = montarCard(proximo);
    } catch (err) {
        // Um pedido quebrado NUNCA pode derrubar o card que o editor está
        // tratando. Sem este catch a exceção subiria pelo callback do
        // aquecimento até o `window.onerror`, que tem recuperação automática:
        // ele chamaria `advanceQueue()` e o pedido da frente sumiria da fila
        // sem ninguém ter decidido nada.
        console.error('Erro ao montar o card de fundo, seguindo sem pilha:', err);
        return;
    }
    // CLONE PROFUNDO: `cloneNode` copia atributos e NÃO copia ouvinte nenhum.
    // Os dos botões já ficavam de fora (eles moram no `renderCurrentCard`), mas
    // o `renderCardImages` pendura ouvinte na foto e nas setas do carrossel —
    // e o lightbox ABRIA com um `.click()` programático no card de fundo, ou
    // seja o ouvinte estava vivo e só não era alcançado por causa do `inert` e
    // do `pointer-events`. É o mesmo argumento que tirou os botões dali: o que
    // só não dispara por causa de OUTRA camada volta a disparar no dia em que
    // alguém mexe na camada. Depois desta linha o card de fundo é uma FIGURA.
    //
    // O que o clone perde são propriedades JS, e só uma importa: o `onerror`
    // da foto, que troca a imagem quebrada pelo "Sem Imagem". Ele é reposto
    // logo abaixo — sem isso, foto 404 no card de fundo viraria caixa vazia.
    fundo = fundo.cloneNode(true);
    const imgF = fundo.querySelector('.card-image');
    const semF = fundo.querySelector('.card-no-image');
    if (imgF && semF) imgF.onerror = () => { imgF.classList.add('hidden'); semF.classList.remove('hidden'); };

    fundo.classList.add('card-fundo');
    // Qual pedido ele anuncia — é por aqui que `aoMudarAFilaPorBaixo` sabe se mudou.
    fundo.dataset.pedido = chaveDoPedido(proximo) || '';
    // As TRÊS, e cada uma cobre o que as outras não cobrem: `inert` tira do Tab
    // e da árvore de acessibilidade E bloqueia o ponteiro, mas é recente demais
    // pra ser a única linha de defesa; `aria-hidden` garante que nenhum leitor
    // de tela anuncie um segundo pedido que não está sendo tratado; e o
    // `pointer-events:none` do CSS vale mesmo onde o `inert` não existe. O modo
    // de falha que elas evitam é caro: um segundo ✕/↑/✓ alcançável pelo teclado,
    // idêntico ao real, agindo sobre o pedido errado.
    fundo.setAttribute('aria-hidden', 'true');
    fundo.inert = true;
    const veu = document.createElement('div');
    veu.className = 'card-fundo-veu';
    veu.setAttribute('aria-hidden', 'true');
    fundo.appendChild(veu);
    // No FIM do #cardStack de propósito, e não no começo: quem pinta em cima é
    // o z-index (explícito no CSS), então a ordem do DOM fica livre pra servir
    // ao outro leitor — `document.querySelector('.place-card')` segue achando o
    // card da FRENTE. É a diferença entre uma linha que todo mundo precisa
    // lembrar e uma que já nasce certa.
    stack.appendChild(fundo);

    // E SÓ AGORA o mapa, porque só agora a caixa tem tamanho.
    //
    // `renderMapa` mede com `box.clientWidth || 400` — fora do DOM isso é 0, e
    // ele enquadra pra 400×240, um tamanho que não é o do card. No card da
    // FRENTE o erro se conserta sozinho: o `ResizeObserver` de
    // `vigiarCaixaDoMapa` refaz quando a caixa assenta. No de fundo, não —
    // `cloneNode` copia atributo e **não copia propriedade JS**, então o
    // observer fica no original e o clone guarda o enquadramento errado PRA
    // SEMPRE.
    //
    // RELATADO pelo owner, com duas capturas do mesmo pedido: puxando o card
    // da frente, o mapa do de baixo tem um tamanho; quando ele chega à frente,
    // tem outro. REPRODUZIDO aqui — caixa 359×337 nos dois, desenhada pra
    // 359×337 na frente e pra 400×240 no fundo, com o tile 48px fora do lugar
    // e uma faixa sem mapa embaixo. O card de fundo é a PROMESSA do que vem;
    // promessa que muda ao virar realidade lê como o app tropeçando.
    //
    // Um redesenho basta, e ele reinstala o observer de quebra. Só quando o
    // mapa está VISÍVEL: escondido a caixa é 0 e cairíamos no mesmo fallback
    // que este conserto existe pra evitar.
    desenharMapaComCaixa(fundo, proximo);
}

// A fila MUDOU por baixo do card na tela (uma página que chegou, a recusa
// automática tirando pedidos): o que o card calcula a partir dela — o "Ver +N"
// do mesmo autor e o card de FUNDO — foi desenhado com a fila de antes, e o card
// que entrava não era o que a pilha anunciava (auditoria de 2026-09-25).
// O de fundo só é refeito se o aquecimento deste card JÁ o montou — antes
// disso, ele é montado na hora dele, lendo a fila de agora — e só se mudou.
let aquecimentoDaFrenteFeito = false;

// Os selos são refeitos a cada página que chega, recusa automática, devolução
// ou fim de lote, e o foco que estava no "Ver +N" ou no "✕ N" caía no <body>
// (R5-2-06, MEDIDO nos dois motores; o CONTROLE, sem a fila mudar, mantém o
// foco no selo). Vai ao selo EQUIVALENTE refeito; se ele não existe mais (os
// outros pedidos do autor saíram da fila), o ✕ do card fica prometido, como no
// C10 — e pousa quando o card destravar.
function seloComFoco(box) {
    const ativo = document.activeElement;
    if (!box || !ativo || !box.contains(ativo)) return null;
    return ['selo-lote', 'selo-reinc'].find((c) => ativo.classList.contains(c)) || null;
}

function devolverFocoAoSelo(card, cls) {
    const novo = card.querySelector('.selos-proc .' + cls);
    if (focavelNaTela(novo)) { novo.focus({ preventScroll: true }); return; }
    focoDoTeclado = BOTAO_DA_ACAO.left;
    aplicarFocoDoTeclado();
}

function aoMudarAFilaPorBaixo() {
    const card = cardDaFrente();
    const place = AppState.currentPlace;
    if (!card || !place) return;
    const linha = card.querySelector('.card-creator-row');
    const velho = linha && linha.querySelector('.selos-proc');
    // O selo FOCADO sai junto com os velhos (R5-2-06): ver `devolverFocoAoSelo`.
    const seloFocado = seloComFoco(velho);
    if (velho) velho.remove();
    renderSelosDeProcedencia(card, place);
    // E a barra "Primeiro os de X · N de M": com o foco no autor, a página que
    // chega com mais pedidos dele passava o selo a "Ver +3" e a barra seguia
    // dizendo "2 de 4" (e o `aria-label`, "os 2 pedidos") até o próximo card
    // (R5-2-08). Os dois na tela contando a mesma fila de jeitos diferentes.
    renderFocoAutor();
    if (seloFocado) devolverFocoAoSelo(card, seloFocado);
    if (!aquecimentoDaFrenteFeito) return;
    const fundo = document.querySelector('#cardStack .card-fundo');
    const quer = chaveDoPedido(AppState.queue[1]);
    const tem = (fundo && fundo.dataset.pedido) || null;
    if (quer !== tem) montarCardDeFundo();
}

// Tempo máximo que o aquecimento espera a foto do card. Rede de segurança: foto
// que trava não pode cancelar o aquecimento do próximo pedido, senão o recurso
// desaparece exatamente na rede ruim, que é onde ele mais serve.
const AQUECIMENTO_ESPERA_MAX_MS = 2500;

// O aquecimento do PRÓXIMO pedido esperava zero: `prefetchNextImage()` era
// chamado na linha seguinte ao card entrar no DOM, então as fotos do próximo
// começavam no mesmo instante que a do atual.
//
// MEDIDO no relatório de produção, num pedido com 4 fotos:
//
//   2715ms   12KB  ← a foto do card (é ela o LCP)
//   2715ms   54KB  ┐
//   2715ms   79KB  ├ fotos do PRÓXIMO pedido, aquecendo junto
//   2716ms   44KB  ┘
//
// 189 KB do que ainda não é preciso disputando banda com os 12 KB que o editor
// precisa ver AGORA. Elas já iam com `fetchPriority: low`, mas prioridade
// ordena a fila, não cria banda: num link estrangulado o LCP paga na mesma.
//
// Agora o aquecimento começa quando a foto atual termina. Card sem foto (20% da
// fila medida) ou com o mapa no primeiro slide não tem o que esperar — dispara
// na hora.
function agendarAquecimento(card) {
    let disparado = false;
    aquecimentoDaFrenteFeito = false;
    const disparar = () => {
        if (disparado) return;
        disparado = true;
        aquecimentoDaFrenteFeito = true;
        prefetchNextImage();
        // A pilha vem DEPOIS do aquecimento, na mesma espera e por dois motivos:
        // a foto do card de fundo é exatamente a que o aquecimento acabou de
        // pedir (sai do cache, custo zero), e montar antes seria pô-la pra
        // competir com o LCP — o defeito que esta espera existe pra evitar.
        montarCardDeFundo();
    };
    setTimeout(disparar, AQUECIMENTO_ESPERA_MAX_MS);
    const img = card.querySelector('.card-image');
    // `complete` é true também pra <img> sem src — a checagem do src vem antes.
    if (!img || img.classList.contains('hidden') || !img.getAttribute('src') || img.complete) return disparar();
    img.addEventListener('load', disparar, { once: true });
    img.addEventListener('error', disparar, { once: true });
}

// Desenha o mini-mapa de evidência dentro do slide.
//
// Preguiçoso de propósito: só monta quando o slide aparece. Medido na fila
// real, são 2,13 tiles por card a 29–147 KB cada; baixar isso pra card que o
// editor nem chega a ver seria cobrar dele por evidência que não pediu.
//
// As cores são as MESMAS do diff — verde entra, vermelho sai. O card já ensina
// essa gramática na caixa de mudanças; inventar outra aqui obrigaria o editor a
// aprender duas.
// A caixa do mapa mudou de tamanho depois do enquadramento? Refaz.
//
// Não é caso raro: o card é flex e assenta depois do primeiro render, então a
// medida do momento do render quase sempre subestima. Girar o aparelho e mudar
// a fonte do sistema fazem o mesmo.
//
// E vale nos DOIS sentidos. Crescer deixa faixa sem tile; ENCOLHER deixa
// marcador FORA da caixa, porque o enquadramento foi feito pra caixa maior.
// Até a auditoria de 2026-09-26 só o crescer refazia ("encolher não abre
// buraco" — não abre, mas corta o que o mapa existe pra mostrar): MEDIDO
// girando o celular de retrato (378×305) pra deitado (267×212) e abrindo no
// Fold (246×135), o marcador saía da caixa, e só voltava girando de novo.
//
// A regra do gotcha #35 continua, e é o que impede o laço: o callback do
// ResizeObserver só AGENDA (a escrita vai no quadro seguinte, fora do ciclo de
// entrega), e só refaz quando o tamanho é OUTRO que o do desenho — redesenhar
// não muda a caixa (os tiles são `absolute` num contêiner `overflow-hidden`),
// então depois de refazer o tamanho bate e o observer sossega.
function vigiarCaixaDoMapa(box, card, place) {
    if (box._roMapa) return;
    let agendado = 0;
    box._roMapa = new ResizeObserver(() => {
        if (agendado) return;
        agendado = requestAnimationFrame(() => {
            agendado = 0;
            const w = box.clientWidth, h = box.clientHeight;
            if (!w || !h) return;
            if (Math.abs(w - (+box.dataset.mapaW || 0)) <= 0.5 && Math.abs(h - (+box.dataset.mapaH || 0)) <= 0.5) return;
            try { renderMapa(card, place, true); } catch (e) { /* mapa nunca derruba o card */ }
        });
    });
    box._roMapa.observe(box);
}

// Os marcadores do mapa deste pedido, em ordem ESTÁVEL — é ela que casa cada
// pixel devolvido pelo `mapaMontar` com o seu marcador.
//
// FONTE ÚNICA de propósito: a mesma lista decide o enquadramento do mapinha do
// card, o do mapa ampliado e os tiles que o prefetch aquece. Ela morava
// copiada nos três, e ponto a mais num só deles não é "um marcador faltando":
// é ZOOM diferente, ou seja, o ampliado abrindo noutro enquadramento e o
// prefetch aquecendo tile que ninguém vai pedir. Mesma lição do gotcha #63.
function pontosDoMapa(place) {
    const m = place && place.mapa;
    if (!m) return [];
    const pontos = [];
    // `fora` e `distM` são do aviso de "fora deste mapa" (ver `avisoForaDoMapa`):
    // QUAL ponto ficou fora, na frase dele, e a que distância do local — a
    // mesma que o core já mede pra cada tipo (o movimento, a entrada, o alvo do
    // duplicado), todas a partir do local.
    if (m.centro) pontos.push({ ll: m.centro, cls: 'mapa-atual', rot: m.proposto ? 'card.map.antes' : 'card.map.aqui' });
    if (m.proposto) pontos.push({ ll: m.proposto, cls: 'mapa-proposto', rot: 'card.map.depois',
        fora: 'card.map.foraDoMapa', distM: m.movidoM });
    for (const e of m.entradas || []) {
        pontos.push({
            ll: e.ll, nome: e.nome,
            cls: 'mapa-entrada mapa-e-' + e.estado,
            rot: 'card.map.entrada.' + e.estado,
            fora: 'card.map.foraDoMapa.entrada', distM: e.distM,
        });
    }
    // O "onde" do duplicado. O nome responde DE QUEM; o marcador responde ONDE
    // — e ONDE é o que decide se são de fato o mesmo lugar. Medido na fila
    // real: 94 · 96 · 101 · 110 · 146 m. Nessa faixa o `mapaMontar` já escolhe
    // sozinho o zoom que cabe, sem caso especial aqui.
    if (place.duplicado && place.duplicado.ll) {
        pontos.push({
            ll: place.duplicado.ll,
            nome: place.duplicado.nome,
            cls: 'mapa-duplicado',
            rot: 'card.map.duplicado',
            fora: 'card.map.foraDoMapa.duplicado', distM: place.duplicado.distM,
        });
    }
    return pontos;
}

// O que ficou FORA do mapa, dito em palavra: QUAL ponto e a que distância do
// local. Até a auditoria de 2026-09-26 a frase era escolhida pelo `movidoM`,
// não pelo ponto que saiu: com a posição proposta a 5 m e uma ENTRADA a 30 km,
// o card dizia "a posição proposta está a 5 m — fora deste mapa".
//
// Fala do PRIMEIRO que ficou de fora, na ordem do `pontosDoMapa` (a proposta
// antes das entradas, e elas antes do duplicado): é o que mais pesa na decisão,
// e uma linha é o que cabe sobre o mapa. A distância é a que o core mediu pra
// aquele ponto; sem ela, a do ponto até o primeiro desenhado.
function avisoForaDoMapa(pontos, foraDoMapa, ancora) {
    const p = foraDoMapa && foraDoMapa.length ? pontos[foraDoMapa[0]] : null;
    if (!p || !p.fora) return t('card.map.foraDoMapa.semDist');
    let d = Number.isFinite(p.distM) ? p.distM : NaN;
    const base = pontos[ancora];
    if (!Number.isFinite(d) && base && Array.isArray(base.ll) && Array.isArray(p.ll)) d = distanciaKm(base.ll, p.ll) * 1000;
    return Number.isFinite(d) ? t(p.fora, { d: formatarMetros(d) }) : t('card.map.foraDoMapa.semDist');
}

// A barra de escala do card e a do mapa ampliado, pela MESMA conta
// (`mapaEscala`, em js/mapa.js). O alvo é o comprimento do TRAÇO inteiro: com o
// `border-box` do `.mapa-escala` a caixa É o traço, e os 16 px de padding que
// antes sobravam por fora (e o faziam medir 36% a mais no card) passaram a
// morar dentro dele. Os alvos são os de antes somados a esses 16 px, então a
// barra na tela tem o mesmo tamanho de sempre — só passou a medir o que diz.
const ESCALA_ALVO_CARD_PX = 80;
const ESCALA_ALVO_AMPLIADO_PX = 112;

function escreverEscala(el, metrosPorPixel, alvoPx) {
    const e = window.mapaEscala ? mapaEscala(metrosPorPixel, alvoPx) : null;
    if (!el || !e) return;
    el.style.width = e.px + 'px';
    el.textContent = e.metros >= 1000
        ? t('card.map.km', { n: (e.metros / 1000).toLocaleString(i18nLocale()) })
        : t('card.map.m', { n: e.metros });
}

function renderMapa(card, place, refazendo) {
    const box = card.querySelector('.card-map');
    if (!box || !place.mapa || (box.dataset.pronto === '1' && !refazendo)) return !!(box && place.mapa);
    const m = place.mapa;

    const pontos = pontosDoMapa(place);
    // A caixa é medida AGORA, e o enquadramento vale só pra este tamanho: os
    // tiles são enumerados pra cobrir exatamente `larguraPx × alturaPx`. Se a
    // caixa crescer depois — e ela cresce, porque o card é flex e assenta
    // depois do primeiro render —, a faixa nova fica SEM tile. Medido: caixa
    // de 359×329 recebendo o enquadramento de uma caixa mais baixa, um tile só
    // em `top:-248px` cobrindo até y=264, e 65px de nada embaixo. Guardar as
    // dimensões usadas é o que deixa o observer lá embaixo decidir se refaz.
    const larguraCaixa = box.clientWidth || 400;
    const alturaCaixa = box.clientHeight || 240;
    const r = window.mapaMontar
        ? mapaMontar(pontos.map((p) => p.ll), larguraCaixa, alturaCaixa, API.getRegion())
        : null;
    if (!r) return false;
    box.dataset.mapaW = String(larguraCaixa);
    box.dataset.mapaH = String(alturaCaixa);
    // Quantos tiles este desenho PEDIU, e quantos falharam — contados ANTES de
    // o tile quebrado sair da tela (ver `registrarFalhaDeTile`). A geometria do
    // diagnóstico lê os dois.
    box.dataset.tilesPedidos = String(r.tiles.length);
    box.dataset.tilesFalharam = '0';
    vigiarCaixaDoMapa(box, card, place);

    const tiles = box.querySelector('.card-map-tiles');
    const marks = box.querySelector('.card-map-marks');
    tiles.textContent = '';
    marks.textContent = '';
    for (const t of r.tiles) {
        const im = new Image();
        im.src = t.url;
        im.alt = '';
        im.decoding = 'async';
        // O tile é <img>, e <img> é arrastável: com o MOUSE, arrastar o card
        // pelo mapa começava o arrastar nativo e o card ficava preso ao cursor
        // (a mesma armadilha da foto — ver `enableSwipeOnCard` no swipe.js).
        im.draggable = false;
        im.className = 'absolute mapa-tile';
        im.style.cssText = `left:${t.left}px;top:${t.top}px;width:${r.tamanho}px;height:${r.tamanho}px`;
        // Tile que não vem não pode deixar um alt quebrado no meio do mapa —
        // mas a falha é CONTADA antes, senão some a prova junto com o ícone.
        im.onerror = () => { registrarFalhaDeTile(box, t.url); im.remove(); };
        tiles.appendChild(im);
    }
    // Qual ponto de `pontos` é cada pixel: o `mapaMontar` diz (`idx`), e
    // desde que ele passou a manter os pontos que cabem mesmo quando algum
    // fica de fora, casar por posição erraria a partir do primeiro que saiu.
    // (O `|| …` é o casamento de antes, pro caso de um mapa.js velho no cache.)
    const idx = r.idx || r.pixels.map((_, k) => k);
    const pixelDe = (i) => { const k = idx.indexOf(i); return k >= 0 ? r.pixels[k] : null; };
    // Linha do movimento: sem ela, dois pontos próximos parecem dois locais
    // diferentes em vez de um que andou. Só com as DUAS pontas desenhadas: com
    // a proposta fora do mapa, uma linha até outro ponto contaria outra história.
    // (Com os dois, o `pontosDoMapa` põe o local em 0 e a proposta em 1.)
    const a = pixelDe(0), b = pixelDe(1);
    if (m.proposto && m.centro && a && b) {
        const linha = document.createElement('div');
        linha.className = 'mapa-linha';
        const dx = b.left - a.left, dy = b.top - a.top;
        linha.style.cssText = `left:${a.left}px;top:${a.top}px;width:${Math.hypot(dx, dy)}px;`
            + `transform:rotate(${Math.atan2(dy, dx)}rad)`;
        marks.appendChild(linha);
    }
    r.pixels.forEach((px, k) => {
        const p = pontos[idx[k]];
        const el = document.createElement('span');
        el.className = 'mapa-marca ' + p.cls;
        el.style.cssText = `left:${px.left}px;top:${px.top}px`;
        el.title = p.nome ? `${t(p.rot)} — ${p.nome}` : t(p.rot);
        marks.appendChild(el);
    });
    // O que não coube em zoom NENHUM vira frase, não marcador escondido.
    // Acontece de verdade: há pedidos propondo mover um local dezenas de
    // quilômetros, e é justamente o card em que a evidência decide sozinha.
    // Sem isto o mapa mostrava um ponto só e calava sobre o outro — o editor
    // concluiria que nada mudou de lugar.
    if (r.foraDoMapa && r.foraDoMapa.length) {
        const aviso = document.createElement('span');
        aviso.className = 'mapa-fora';
        aviso.textContent = avisoForaDoMapa(pontos, r.foraDoMapa, idx[0]);
        marks.appendChild(aviso);
    }

    // Escala: sem ela o mapa mente sobre distância, porque o zoom muda de card
    // pra card conforme o que precisa caber.
    escreverEscala(box.querySelector('.card-map-scale'), r.metrosPorPixel, ESCALA_ALVO_CARD_PX);

    // Legenda: o marcador sozinho não diz qual é qual, e cor não pode ser o
    // único canal de informação (WCAG 1.4.1).
    const leg = box.querySelector('.card-map-legend');
    leg.textContent = '';
    const jaPos = new Set();
    // Só o que foi DESENHADO entra na legenda: prometer um marcador que não
    // está na tela faz o editor procurar o que não existe.
    const desenhados = new Set(idx);
    for (const [i, p] of pontos.entries()) {
        if (!desenhados.has(i)) continue;
        if (jaPos.has(p.rot)) continue;
        jaPos.add(p.rot);
        const s = document.createElement('span');
        s.className = 'mapa-leg';
        const pt = document.createElement('span');
        pt.className = 'mapa-marca ' + p.cls;
        s.appendChild(pt);
        s.appendChild(document.createTextNode(t(p.rot)));
        leg.appendChild(s);
    }
    // Clicar amplia, mas o OUVINTE não mora aqui — ver `renderCurrentCard`.
    // O comentário que estava nesta linha dizia "`once` porque `renderMapa` só
    // monta uma vez por card", e as duas metades eram falsas: o código passava
    // `{ once: false }`, e o observer de caixa logo acima refaz o mapa sempre
    // que o layout assenta. MEDIDO: o mapa já NASCIA com dois ouvintes (um
    // clique abria o lightbox 2×) e ia a três depois do primeiro refazer.
    // Desenho puro aqui também é o que deixa o card de FUNDO redesenhar sem
    // ganhar interação — ele é uma figura, e precisa ser igual ao que vem.
    box.style.cursor = 'zoom-in';
    box.dataset.pronto = '1';
    return true;
}

// ── Mapa AMPLIADO: arrastar, zoom, e tiles buscados conforme navega ──────
//
// O mapinha do card responde "onde é isto"; este responde "e o que tem em
// volta?" — pedido dos testadores. A diferença não é de tamanho: ampliar foto
// estica uma imagem que já está em mãos, enquanto aqui arrastar e dar zoom
// BUSCA tiles novos. Fazer o barato (esticar o que o card já baixou) daria
// zoom borrado e arrasto que não revela nada: entregaria o gesto e frustraria
// a expectativa, que é pior que não ter.
//
// Sem biblioteca, como o resto. A matemática mora em `js/mapa.js` (`mapaGrade`,
// com `projetar`/`desprojetar`), e aqui fica só gesto e DOM.
// O Street View abre ONDE A PESSOA ESTÁ OLHANDO — e enquanto ela não mexeu no
// mapa, isso é o PEDIDO, não o enquadramento (ver `pontoDoStreetView`).
//
// Depois que ela arrasta ou dá zoom, o centro é escolha dela: no lightbox ela
// mexe pra entender qual é a entrada, e abrir no centróide jogaria fora a
// investigação que ela acabou de fazer. E isto só existe AQUI: o mini-mapa do
// card usa `mapaMontar`, que é enquadramento FIXO ("escolhido pra caber,
// minimiza tiles"), então lá a pergunta "onde você está olhando" não tem
// resposta. Foi o que fez o botão morar no lightbox e não no card — ver a
// regra do card decide / lightbox analisa, no CLAUDE.md.
//
// Não mandamos `heading`: MEDIDO contra a doc da Google — sem ele, "a default
// heading is chosen based on the viewpoint and the actual location of the
// image", ou seja o Google JÁ aponta a câmera do panorama pro viewpoint, e com
// a informação que nós não temos (onde a imagem está). Mandar um rumo
// calculado por nós trocaria o cálculo exato dele por uma estimativa.
//
// `centro` é [lat, lon]: o core INVERTE o GeoJSON antes de mandar. Ler ao
// contrário NÃO quebra nada visível — dá um lugar plausível e errado. Medido
// no Terminal 2 de Guarulhos: [lat,lon] cai no aeroporto, [lon,lat] cai no
// Atlântico Sul, e os dois passam num teste de |lat| <= 90. `test/streetview
// .test.mjs` carrega contraprova por isso.
//
// Não mandamos zoom nem `fov`: o zoom do MAPA não tem tradução pro campo de
// visão do panorama, e inventar uma seria número sem medida atrás.
function linkStreetView(centro) {
    if (!Array.isArray(centro) || centro.length < 2) return null;
    const lat = Number(centro[0]);
    const lon = Number(centro[1]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    const p = new URLSearchParams({ api: '1', map_action: 'pano', viewpoint: lat + ',' + lon });
    return STREET_VIEW_URL + '?' + p;
}

const MapaLightbox = {
    centro: null, z: 16, pontos: [], _tiles: new Map(), _falhos: new Set(), _fora: [], _inicial: null, _local: null,
    isOpen() { return !document.getElementById('mapaLightbox').classList.contains('hidden'); },

    open(place) {
        if (!place || !place.mapa || !window.mapaGrade) return;
        this.pontos = pontosDoMapa(place);
        if (!this.pontos.length) return;

        const el = document.getElementById('mapaLightbox');
        // Abre no MESMO enquadramento do card (a pessoa clicou no que estava
        // vendo) — e, quando algum ponto não cabia no card, no zoom da
        // navegação em que TODOS cabem. Ver `mapaEnquadrarAmpliado`: o zoom da
        // conta do card com o centro no meio de tudo abria o pedido de 82 km
        // no vazio entre os dois pontos, sem marcador na tela.
        const enq = mapaEnquadrarAmpliado(this.pontos.map((p) => p.ll), innerWidth, innerHeight, API.getRegion());
        if (!enq) return;   // nenhuma coordenada válida: o card nem desenha o mapa
        this.z = enq.z;
        this.centro = enq.centro.slice();
        // Os pontos que não cabem em zoom NENHUM da navegação (ex.: um movimento
        // de 2.500 km): o `desenharMarcas` os diz em palavra enquanto não estão
        // na tela, como o card faz.
        this._fora = (enq.foraDoMapa || []).slice();
        // O ponto do PEDIDO, guardado à parte do enquadramento: o `centro` acima
        // é a média dos marcadores (local + entradas + posição proposta +
        // duplicado), que em 31% dos pedidos NÃO é o local.
        this._local = place.mapa.centro ? place.mapa.centro.slice() : null;
        this._inicial = { centro: this.centro.slice(), z: this.z };
        this._tiles.clear();
        this._falhos.clear();   // cada abertura tenta de novo o que falhou antes
        document.getElementById('mapaLbTiles').textContent = '';
        // Quem abriu (o mapa do card, que é focável): o foco volta pra ele.
        this._quemAbriu = document.activeElement;
        CamadaVoltar.empilhar();
        el.classList.remove('hidden');
        document.body.style.overflow = 'hidden';
        const fechar = document.getElementById('mapaLbClose');
        if (fechar) fechar.focus();
        this.desenhar();
    },

    close(viaHistorico) {
        const el = document.getElementById('mapaLightbox');
        if (el.classList.contains('hidden')) return;
        el.classList.add('hidden');
        document.body.style.overflow = '';
        // Consome a entrada de histórico quando NÃO foi o voltar que fechou —
        // sem isso sobra entrada morta e o próximo voltar não faz nada, a
        // pessoa aperta de novo e sai do app (a mesma regra do lightbox).
        if (!viaHistorico) CamadaVoltar.consumir();
        // E o que era DO PEDIDO sai do DOM e da memória: o nome do local
        // duplicado e o das entradas (o `title` dos marcadores), o link do
        // Street View com a coordenada do pedido, os tiles da área e os pontos.
        // Ficavam no mapa fechado — até na tela de entrada depois do "Sair", e o
        // relatório do modo dev da próxima conta os levava com o DOM inteiro
        // (auditoria de 2026-10-02, R7-1-02, MEDIDO nos dois motores; a foto
        // ampliada já limpava, R6-1-05). O `open` refaz tudo. Sem o `centro`, o
        // que chegar depois de fechar (o quadro de um arraste ainda no ar, o
        // toque que solta o dedo) não desenha a camada escondida.
        for (const id of ['mapaLbTiles', 'mapaLbMarks', 'mapaLbLegenda']) {
            const n = document.getElementById(id);
            if (n) n.textContent = '';
        }
        const sv = document.getElementById('mapaLbStreetView');
        if (sv) sv.removeAttribute('href');
        this._tiles.clear();
        this._falhos.clear();
        this.pontos = [];
        this._fora = [];
        this._local = null;
        this._inicial = null;
        this.centro = null;
        // O foco não cai no <body>: volta pro mapa do card (ver
        // `devolverFocoDaAmpliacao`).
        const quem = this._quemAbriu;
        this._quemAbriu = null;
        devolverFocoDaAmpliacao(quem, ['.card-map', '.card-image']);
        // O "Como funciona" que esperava a camada fechar (R7-7-01).
        aoFecharCamada(!!viaHistorico);
    },

    // Redesenha a grade. Tiles já baixados são REAPROVEITADOS (mapa por chave
    // z/x/y): sem isso, arrastar 10px refazia o DOM e piscava a tela inteira.
    // FONTE ÚNICA do link do Street View: chamada de dentro do `desenhar()`,
    // por onde passam abrir, arrastar, zoom e recentrar. Amarrar isto a um dos
    // quatro deixaria os outros três com o link velho, e o sintoma seria o
    // panorama abrir no lugar anterior — sem erro nenhum na tela.
    // FONTE ÚNICA do ponto que vai pro Street View, e a distinção que ela faz
    // não é firula: o `centro` do lightbox é o meio da CAIXA que enquadra todos
    // os marcadores, e enquanto a pessoa não mexeu no mapa esse ponto não foi
    // escolhido por ninguém — é subproduto do enquadramento. MEDIDO em 9.997
    // pedidos de 12 países: em 3.085 (31%) ele não é o local, com mediana de
    // 22 m e máximo de 3,6 km, quase sempre porque um ponto de entrada puxou a
    // caixa. Medindo onde o Google põe a câmera nos dois casos (849 pares):
    // a distância dela até o local cai de 79 m para 30 m na mediana, e o pior
    // caso despenca de 10.885 m para 393 m — melhor em 321, empate em 279 e
    // pior em 1, que é um parque onde nenhuma das duas mostra coisa alguma.
    //
    // Depois que ela arrasta, manda o centro DELA: aí o ponto é escolha, e é o
    // que faz o pedido de movimento funcionar de graça (quer ver a posição
    // proposta? arrasta até lá e abre de lá).
    //
    // "Mexeu" é o centro ter ANDADO, com tolerância: o zoom pelos botões + e −
    // mantém o centro, mas a ida e volta pela projeção deixa resíduo de ponto
    // flutuante (MEDIDO: 3,6e-15° depois de um +), e a igualdade estrita lia isso
    // como "a pessoa escolheu o centro" — o Street View trocava o pedido pelo meio
    // da caixa só por ela ter dado zoom (auditoria de 2026-09-25). 1e-9° é ~0,1 mm;
    // o menor arrasto possível (1 px no zoom 19) anda ~2,7e-6°.
    pontoDoStreetView() {
        const TOL = 1e-9;
        if (this._local && this._inicial && Array.isArray(this.centro)
            && Math.abs(this.centro[0] - this._inicial.centro[0]) < TOL
            && Math.abs(this.centro[1] - this._inicial.centro[1]) < TOL) return this._local;
        return this.centro;
    },

    atualizarStreetView() {
        const a = document.getElementById('mapaLbStreetView');
        if (!a) return;
        const url = linkStreetView(this.pontoDoStreetView());
        // Opção que não dá pra cumprir não aparece: sem coordenada, sem botão.
        if (url) { a.href = url; a.classList.remove('hidden'); }
        else { a.removeAttribute('href'); a.classList.add('hidden'); }
    },

    // O "+" no zoom MÁXIMO e o "−" no MÍNIMO não fazem nada (o `zoom` sai calado
    // no limite) e seguiam com cara de vivos — botão morto com cara de vivo lê
    // como app quebrado (auditoria de 2026-10-02, R7-3-09, MEDIDO nos dois
    // motores). `aria-disabled`, e não `disabled`: este tiraria o foco de quem
    // chegou ao botão pelo teclado (R5-2-05), e o Tab seguinte recomeçaria fora
    // da camada; o esmaecido vem do CSS, o mesmo dos outros botões travados.
    // Chamada do `desenhar()`, por onde passa todo caminho que muda o zoom.
    atualizarLimitesDoZoom() {
        for (const [id, noLimite] of [['mapaLbMais', this.z >= MAPA_Z_NAV_MAX], ['mapaLbMenos', this.z <= MAPA_Z_NAV_MIN]]) {
            const b = document.getElementById(id);
            if (!b) continue;
            if (noLimite) b.setAttribute('aria-disabled', 'true');
            else b.removeAttribute('aria-disabled');
        }
    },

    desenhar() {
        // Fechado, não há o que desenhar (ver o `close`).
        if (!this.centro) return;
        const el = document.getElementById('mapaLightbox');
        const w = el.clientWidth || innerWidth;
        const h = el.clientHeight || innerHeight;
        const g = mapaGrade(this.centro, this.z, w, h, API.getRegion());
        this.z = g.z;
        this.atualizarLimitesDoZoom();
        const caixa = document.getElementById('mapaLbTiles');
        const vivos = new Set();
        for (const t of g.tiles) {
            vivos.add(t.chave);
            let im = this._tiles.get(t.chave);
            if (!im) {
                // Tile que JÁ FALHOU nesta abertura não é pedido de novo. O
                // `onerror` tira a <img> quebrada do DOM (gotcha #55) e apagava a
                // chave, e o `desenhar()` seguinte — um por QUADRO de arraste — a
                // recriava: MEDIDO com os tiles dando 404, 432 pedidos num arraste
                // de 40 px, o mesmo tile até 30× (com tiles bons: 0). Reabrir o
                // mapa tenta de novo.
                if (this._falhos.has(t.chave)) continue;
                im = new Image();
                im.src = t.url; im.alt = ''; im.decoding = 'async';
                im.className = 'absolute mapa-tile';
                im.style.width = im.style.height = g.tamanho + 'px';
                im.onerror = () => {
                    registrarFalhaDeTile(null, t.url);
                    im.remove();
                    this._tiles.delete(t.chave);
                    this._falhos.add(t.chave);
                };
                this._tiles.set(t.chave, im);
                caixa.appendChild(im);
            }
            im.style.left = t.left + 'px';
            im.style.top = t.top + 'px';
        }
        // Tile que saiu de vista sai do DOM: navegar bastante encheria a página
        // de <img> invisível, e aí o custo vira memória em vez de rede.
        for (const [k, im] of this._tiles) {
            if (!vivos.has(k)) { im.remove(); this._tiles.delete(k); }
        }
        this.desenharMarcas(g);
        this.atualizarStreetView();
    },

    desenharMarcas(g) {
        const marks = document.getElementById('mapaLbMarks');
        marks.textContent = '';
        const px = this.pontos.map((p) => g.projetar(p.ll));
        // Linha do movimento: mesma gramática do card (verde entra, tracejada
        // porque é trajeto proposto e não feição do mapa).
        if (this.pontos.length >= 2 && this.pontos[1].cls === 'mapa-proposto') {
            const [a, b] = px;
            const linha = document.createElement('div');
            linha.className = 'mapa-linha';
            const dx = b.left - a.left, dy = b.top - a.top;
            linha.style.cssText = `left:${a.left}px;top:${a.top}px;width:${Math.hypot(dx, dy)}px;`
                + `transform:rotate(${Math.atan2(dy, dx)}rad)`;
            marks.appendChild(linha);
        }
        this.pontos.forEach((p, i) => {
            const e = document.createElement('span');
            e.className = 'mapa-marca ' + p.cls;
            e.style.cssText = `left:${px[i].left}px;top:${px[i].top}px`;
            e.title = p.nome ? `${t(p.rot)} — ${p.nome}` : t(p.rot);
            marks.appendChild(e);
        });
        escreverEscala(document.getElementById('mapaLbEscala'), g.metrosPorPixel, ESCALA_ALVO_AMPLIADO_PX);
        // O que está NA TELA agora (o centro do marcador dentro da caixa). A
        // legenda, como a do card, fala só do que se vê — prometer um marcador
        // que não está na tela faz o editor procurar o que não existe. E o ponto
        // que não cabe em zoom nenhum (`_fora`), enquanto não está na tela, é
        // dito em palavra pelo MESMO aviso do card: o ampliado de um movimento
        // de 2.500 km mostrava só o local, calado, com "depois" na legenda
        // (auditoria de 2026-09-26). Arrastando até ele, o aviso sai e a legenda
        // o ganha.
        const caixa = document.getElementById('mapaLightbox');
        const w = caixa.clientWidth || innerWidth, h = caixa.clientHeight || innerHeight;
        const naTela = (i) => px[i].left >= 0 && px[i].left <= w && px[i].top >= 0 && px[i].top <= h;
        const foraAgora = (this._fora || []).filter((i) => this.pontos[i] && !naTela(i));
        if (foraAgora.length) {
            const aviso = document.createElement('span');
            aviso.className = 'mapa-fora';
            aviso.textContent = avisoForaDoMapa(this.pontos, foraAgora, 0);
            marks.appendChild(aviso);
        }
        const leg = document.getElementById('mapaLbLegenda');
        leg.textContent = '';
        const ja = new Set();
        for (const [i, p] of this.pontos.entries()) {
            if (!naTela(i)) continue;
            if (ja.has(p.rot)) continue;
            ja.add(p.rot);
            const sp = document.createElement('span');
            sp.className = 'mapa-leg';
            const pt = document.createElement('span');
            pt.className = 'mapa-marca ' + p.cls;
            sp.appendChild(pt);
            sp.appendChild(document.createTextNode(t(p.rot)));
            leg.appendChild(sp);
        }
    },

    // Arrastar: converte o deslocamento em pixels para uma coordenada nova, via
    // `desprojetar`. Ir pelo pixel e não por "graus por pixel" mantém a conta
    // correta em qualquer latitude e qualquer zoom.
    arrastar(dxPx, dyPx) {
        if (!this.centro) return;   // fechado (ver o `close`)
        const el = document.getElementById('mapaLightbox');
        const w = el.clientWidth || innerWidth, h = el.clientHeight || innerHeight;
        const g = mapaGrade(this.centro, this.z, w, h, API.getRegion());
        this.centro = g.desprojetar(w / 2 - dxPx, h / 2 - dyPx);
        this.desenhar();
    },

    // Zoom mantendo FIXO o ponto sob o dedo (ou o centro, se não houver foco).
    // Sem isso, dar zoom no que interessa manda o alvo pra fora da tela.
    zoom(delta, focoX, focoY) {
        if (!this.centro) return;   // fechado (ver o `close`)
        const el = document.getElementById('mapaLightbox');
        const w = el.clientWidth || innerWidth, h = el.clientHeight || innerHeight;
        const fx = focoX === undefined ? w / 2 : focoX;
        const fy = focoY === undefined ? h / 2 : focoY;
        const g0 = mapaGrade(this.centro, this.z, w, h, API.getRegion());
        const alvoLL = g0.desprojetar(fx, fy);
        const zNovo = Math.max(MAPA_Z_NAV_MIN, Math.min(MAPA_Z_NAV_MAX, Math.round(this.z + delta)));
        if (zNovo === this.z) return;
        this.z = zNovo;
        const g1 = mapaGrade(alvoLL, this.z, w, h, API.getRegion());
        // Onde o alvo caiu com o centro provisório? Corrige o centro pela sobra.
        const p = g1.projetar(alvoLL);
        this.centro = g1.desprojetar(p.left + (w / 2 - fx), p.top + (h / 2 - fy));
        this.desenhar();
    },

    recentrar() {
        if (!this._inicial) return;
        this.centro = this._inicial.centro.slice();
        this.z = this._inicial.z;
        this.desenhar();
    },
};

// Renderiza a imagem/carrossel do card (extraído de renderCurrentCard — A1).
function renderCardImages(card, place) {
    const img = card.querySelector('.card-image');
    const noImg = card.querySelector('.card-no-image');
    const imgNav = card.querySelector('.card-image-nav');
    const imgCount = card.querySelector('.card-image-count');
    const imgPrev = card.querySelector('.card-image-prev');
    const imgNext = card.querySelector('.card-image-next');
    const newBadge = card.querySelector('.card-image-new-badge');
    const newBorder = card.querySelector('.card-image-new-border');
    const fotos = fotosDoCard(place);
    const urls = fotos.urls;

    // O mapa é mais um SLIDE do carrossel — nunca uma linha nova no card, que
    // acabou de ser espremido até caber. Ele vem PRIMEIRO quando é a evidência
    // principal (o pedido mexe em posição, ou não há foto nenhuma pra olhar) e
    // por último quando a foto é que responde a pergunta.
    const temMapa = !!place.mapa;
    const mapaPrimeiro = mapaVemPrimeiro(place);
    const slides = urls.map((u) => ({ foto: u }));
    if (temMapa) slides.splice(mapaPrimeiro ? 0 : slides.length, 0, { mapa: true });
    const idxMapa = temMapa ? (mapaPrimeiro ? 0 : slides.length - 1) : -1;

    if (slides.length === 0) {
        img.classList.add('hidden');
        noImg.classList.remove('hidden');
        return;
    }

    // Um card é UM updateRequest: ou PROPÕE foto nova (✨ âmbar) ou DENUNCIA uma
    // existente (🚩 rosa) — nunca os dois. Daí um marcador só, com dois estados.
    //
    // NUM LOCAL NOVO O SELO NÃO APARECE, e isso é deliberado. O owner reparou e
    // perguntou: se o local é novo, a foto também é — não deveria vir marcada?
    // Tecnicamente sim, e a ausência do selo chega a ser uma meia-mentira. Mas
    // medido na fila real: dos 86 fotos em locais novos, 86 estão NÃO aprovadas
    // e ZERO aprovadas — é impossível um local novo ter foto que já esteja no
    // mapa. O selo apareceria em 100% desses cards, e selo que nunca varia não
    // é selo: é decoração. Pior, local novo é o tipo mais comum da fila (140 de
    // 295), então o editor veria ✨ o tempo todo e ele pararia de significar
    // algo justamente onde discrimina — no pedido de FOTO, em que uma entre
    // quatro é a nova. E o contexto já desambigua: a linha `Tipo: Novo local`
    // diz que tudo ali é novo. Decisão do owner depois da medição.
    // QUAL das N fotos é o pedido sai do `fotosDoCard` — a MESMA regra que o
    // aquecimento e a varredura do offline usam pra saber qual foto guardar.
    const eDenuncia = fotos.eDenuncia;
    const newImageIdx = fotos.emDecisao;
    newBadge.textContent = eDenuncia ? '🚩' : '✨';
    // Via atributo, não via .title: o applyI18n() roda DEPOIS deste render e
    // sobrescreveria um title escrito na mão.
    newBadge.setAttribute('data-i18n-title', eDenuncia ? 'card.flaggedPhoto.title' : 'card.newPhoto.title');
    newBorder.classList.toggle('ring-amber-400', !eDenuncia);
    newBorder.classList.toggle('ring-rose-500', eDenuncia);
    let currentImgIdx = fotos.inicial;

    // O índice do carrossel agora anda pelos SLIDES; a foto tem o seu próprio,
    // porque `newImageIdx` e o lightbox falam em posição na lista de FOTOS.
    let slideIdx = 0;
    const mapaBox = card.querySelector('.card-map');
    const updateImage = () => {
        const s = slides[slideIdx];
        imgCount.textContent = `${slideIdx + 1} / ${slides.length}`;
        if (s.mapa) {
            img.classList.add('hidden');
            noImg.classList.add('hidden');
            newBadge.classList.add('hidden');
            newBorder.classList.add('hidden');
            mapaBox.classList.remove('hidden');
            // Só aqui o tile é pedido: slide que ninguém abriu não custa rede.
            if (!renderMapa(card, place)) mapaBox.classList.add('hidden');
            return;
        }
        if (mapaBox) mapaBox.classList.add('hidden');
        currentImgIdx = urls.indexOf(s.foto);
        // A foto do card é o LCP do app, e o Lighthouse aponta que ela chega sem
        // dica de prioridade (`priorityHinted: false`). Pré-carregar não dá — a
        // URL só existe depois da resposta da API —, mas dizer que ela é a mais
        // importante da página, dá. Faz par com o `fetchpriority="low"` do
        // avatar: os dois juntos é que tiram os 214 KB da foto de perfil da
        // frente dos ~50 KB que o editor precisa VER pra decidir.
        img.fetchPriority = 'high';
        // urlDaFoto: MESMA URL que o aquecimento usou. Se divergir, o card pede
        // um endereco que ninguem aqueceu e a foto some offline, sem erro.
        img.src = urlDaFoto(s.foto);
        // Num LOCAL NOVO toda foto está sendo proposta junto com o local — e o
        // card não põe o ✨ nelas de propósito (ver a nota longa acima: o selo
        // ficaria sempre ligado e perderia sentido onde ele decide algo). Mas a
        // informação não pode simplesmente sumir: quem usa leitor de tela ou
        // passa o mouse ouve/lê aqui, sem custar um pixel na tela nem competir
        // com o selo real. Foi a saída que o owner escolheu depois de a medição
        // mostrar que o selo visível não pagava.
        const propostaComOLocal = place.purType === 'NEW_PLACE' || place.reqType === 'VENUE';
        img.alt = altDaFoto(place, currentImgIdx + 1, urls.length);
        img.title = propostaComOLocal ? t('card.img.novoLocal.title') : '';
        img.classList.remove('hidden');
        noImg.classList.add('hidden');
        const isNew = currentImgIdx === newImageIdx;
        newBadge.classList.toggle('hidden', !isNew);
        newBorder.classList.toggle('hidden', !isNew);
    };
    slideIdx = idxMapa === 0 ? 0 : slides.findIndex((s) => s.foto === urls[currentImgIdx]);
    if (slideIdx < 0) slideIdx = 0;
    img.classList.add('cursor-zoom-in');
    img.decoding = 'async';
    // Foto quebrada (404 do Waze) → cai pro placeholder "Sem Imagem".
    // E SEM REDE, se a que falhou é a foto EM DECISÃO, o card diz "precisa de
    // sinal" e trava ✕/✓ — mas só DEPOIS de a imagem falhar de verdade. Até
    // v2026.09.22-01 o aviso era posto por SUPOSIÇÃO (`offline` + tipo de foto)
    // antes de a imagem tentar, e escondia a foto que a varredura acabara de
    // guardar justamente pra este momento. RELATADO pelo owner com o toggle
    // ligado e a varredura em "Pronto" 1 minuto antes: os três cards de foto
    // vieram vazios. Reproduzido com controle: a mesma URL, numa <img> solta e
    // sem rede, carregava do cache.
    img.onerror = () => {
        img.classList.add('hidden');
        noImg.classList.remove('hidden');
        if (newImageIdx < 0 || currentImgIdx === newImageIdx) marcarCardSemFoto(card, place);
    };
    updateImage();

    img.addEventListener('click', (e) => {
        e.stopPropagation();
        e.preventDefault();
        openLightbox(urls, currentImgIdx, newImageIdx, place.name, eDenuncia, place);
    });

    if (slides.length > 1) {
        imgNav.classList.remove('hidden');
        const anda = (d) => (e) => {
            e.stopPropagation();
            e.preventDefault();
            slideIdx = (slideIdx + d + slides.length) % slides.length;
            updateImage();
        };
        imgPrev.addEventListener('click', anda(-1));
        imgNext.addEventListener('click', anda(1));
    }
}

// Renderiza o diff de mudanças propostas (extraído de renderCurrentCard — A1).
// Distância que o ponto andou, no formato de quem está lendo. Abaixo de 1m o
// número inteiro esconde a informação ("0 m" não diz nada), então vai com uma
// casa; acima de 1km metro não importa mais.
//
// A unidade se escolhe pelo número ARREDONDADO, que é o que a tela mostra:
// decidindo por `m < 1000` antes de arredondar, de 999,5 a 999,9 m saía "1.000 m"
// (en "1,000 m", fr "1 000 m") onde todo o resto diz "1 km" — MEDIDO nos 4
// idiomas (auditoria da rodada 9, R9-6-06). A mesma régua em `formatarMetros`.
function formatarDistancia(m) {
    if (!Number.isFinite(m)) return '';
    const loc = i18nLocale();
    if (m < 1) return t('card.change.movedM', { d: m.toLocaleString(loc, { maximumFractionDigits: 1 }) });
    const metros = Math.round(m);
    if (metros < 1000) return t('card.change.movedM', { d: metros.toLocaleString(loc) });
    return t('card.change.movedKm', { d: (m / 1000).toLocaleString(loc, { maximumFractionDigits: 1 }) });
}

// A mesma distância SEM o verbo. `formatarDistancia` diz "moveu 36 m", que é a
// frase certa pra geometria e errada pra qualquer outra coisa — reusá-la no
// ponto de entrada produziu "a MOVEU 16,3 km do local". Número e frase são
// coisas separadas; quem monta a frase escolhe o verbo. É a FONTE ÚNICA de uma
// distância sem verbo na tela: o mapa, a entrada, o duplicado e a precisão do
// "📍 Perto de mim" (R9-6-05) passam por aqui.
function formatarMetros(m) {
    if (!Number.isFinite(m)) return '';
    const loc = i18nLocale();
    if (m < 1) return t('card.map.m', { n: m.toLocaleString(loc, { maximumFractionDigits: 1 }) });
    // A unidade pelo número ARREDONDADO (R9-6-06, ver `formatarDistancia`).
    const metros = Math.round(m);
    if (metros < 1000) return t('card.map.m', { n: metros.toLocaleString(loc) });
    return t('card.map.km', { n: (m / 1000).toLocaleString(loc, { maximumFractionDigits: 1 }) });
}

// Valor de lista: enum do Waze quando conhecemos, cru quando não. Objeto (um
// entryExitPoint, por exemplo) vira resumo curto em vez de JSON na cara.
// Nomes de dia SEM dicionário: o Intl já sabe em toda língua, e uma tabela de
// 7 dias × 4 idiomas seria 28 strings pra manter em paridade sem ganho nenhum.
// 2024-01-07 é um domingo, que é o dia 0 do Waze.
function nomeDoDia(d) {
    try {
        return new Date(Date.UTC(2024, 0, 7 + Number(d)))
            .toLocaleDateString(i18nLocale(), { weekday: 'short', timeZone: 'UTC' });
    } catch (e) { return String(d); }
}

// Item de lista sem conteúdo. O Waze manda isso de verdade: medido na fila
// real, um pedido do "Posto Equador" propunha `services: [""]` — um array com
// uma string vazia. O card mostrava `Serviços: +` e mais nada, que lê como app
// quebrada, não como "estão adicionando um item vazio".
function itemDeListaAusente(v) {
    return v === null || v === undefined || v === '';
}

// UM renderizador de item de lista, usado pelo campo de lista de topo E pela
// folha de objeto que é lista. Eram dois trechos idênticos copiados, que é
// exatamente como duas telas do mesmo conceito divergem sem ninguém notar.
// Valor ausente leva `.valor-ausente` como qualquer placeholder do card — e o
// smoke mede o contraste dele nos dois temas a cada PR.
function itemDeLista(v, cls, sinal, campo, centro) {
    const txt = escapeHtml(valorDeLista(v, campo, centro));
    const corpo = itemDeListaAusente(v) ? `<span class="valor-ausente">${txt}</span>` : txt;
    return `<span class="${cls}"><span aria-hidden="true">${sinal}</span> ${corpo}</span>`;
}

// `centro` é o do local DESTE card ([lat, lon], `place.mapa.centro`). Era lido
// do `AppState.currentPlace`, e o card de FUNDO da pilha media a entrada dele a
// partir do local do card da FRENTE (auditoria de 2026-09-25).
function valorDeLista(v, campo, centro) {
    // MESMO placeholder do resto do card (`valorDoDiff` já fazia isto). Os
    // parênteses não são enfeite: resolvem a ambiguidade de um valor que
    // poderia se chamar "vazio", e são TEXTO, então leitor de tela lê.
    if (itemDeListaAusente(v)) return t('card.value.empty');
    if (v && typeof v === 'object') {
        // Ponto de entrada/saída: DISTÂNCIA até o local, não coordenada.
        //
        // `+ entrada -23.50382, -46.84458` é exato e injulgável — o editor não
        // tem como saber se aquilo fica na calçada ou na cidade vizinha. Medido
        // na fila de 12 países: a mediana é 29 m (plausível), mas há pedidos
        // propondo entrada a 16 e a 82 QUILÔMETROS do próprio local, e em
        // coordenada isso passava batido. Mesma lição do `geometry`, que já
        // virou "moveu 36 m". O nome fica quando existe: é por ele que o editor
        // reconhece o ponto ao abrir o WME.
        const p = v.point && v.point.coordinates;
        if (Array.isArray(p) && p.length >= 2) {
            const tipo = v.entry === false ? t('card.eep.exit') : t('card.eep.entry');
            const nome = String(v.name || '').trim();
            if (Array.isArray(centro) && centro.length >= 2) {
                const dLat = (p[1] - centro[0]) * 111320;
                const dLon = (p[0] - centro[1]) * 111320 * Math.cos(centro[0] * Math.PI / 180);
                const d = Math.sqrt(dLat * dLat + dLon * dLon);
                return `${nome ? nome + ' · ' : ''}${tipo} ${t('card.eep.aDistancia', { d: formatarMetros(d) })}`;
            }
            // Sem posição do local não há distância a calcular — aí a
            // coordenada volta, porque sumir com o dado é pior que ser cru.
            return `${nome ? nome + ' · ' : ''}${tipo} ${Number(p[1]).toFixed(5)}, ${Number(p[0]).toFixed(5)}`;
        }
        // Horário de funcionamento: vinha como JSON cru na tela (medido na fila
        // real). 7 dias vira "todos os dias" em vez de enfileirar a semana.
        if (Array.isArray(v.days) && v.fromHour !== undefined) {
            const dias = v.days.length >= 7 ? t('card.oh.everyday') : v.days.map(nomeDoDia).join(', ');
            return `${dias} · ${v.fromHour}–${v.toHour}`;
        }
        // Objeto que o app não conhece: em vez de JSON cru, `chave valor` com
        // separador. Nenhuma chave e nenhum valor somem — a regra continua
        // sendo "feio, nunca invisível" — mas sem chaves, aspas e vírgulas, que
        // é o que fazia o editor pular a linha inteira. Medido no
        // `chargingPorts` de um eletroposto: 152 caracteres de JSON viravam
        // uma linha que ninguém lia.
        return objetoLegivel(v);
    }
    // Item de lista sai CRU. Aqui passava por `rotuloDeEnum('card.enum.', …)`,
    // que nunca teve UMA chave no dicionário — era um mecanismo de tradução
    // vazio, então TUDO caía no `humanizarEnum`, que faz lowercase. Três danos,
    // medidos na fila real:
    //
    //   · CATEGORIA humanizada, contra a decisão do owner de mostrá-la crua
    //     (o Waze regionaliza categoria por país). O MESMO card mostrava
    //     `NATURAL_FEATURES` no topo e `Natural features` no diff — o mesmo
    //     conceito com dois nomes na mesma tela.
    //   · `aliases` é NOME PRÓPRIO, não enum: "Escola Estadual Leovegildo de
    //     Melo" virava "Escola estadual leovegildo de melo".
    //   · `externalProviderIDs` é ID opaco do Google: `ChIJfYn3umKwnZMRWQEl…`
    //     virava `Chijfyn3umkwnzmrwqel…` — deixa de ser o ID. Quem copiasse da
    //     tela colaria um valor que não existe.
    //
    // O `rotuloDeEnum` continua onde ele tem dicionário de verdade (updateType,
    // flagType, source) — lá humanizar é fallback de enum não mapeado, não a
    // regra. Se um dia houver fonte de regionalização do Waze, o lugar de
    // traduzir categoria é essa fonte, não uma humanização mecânica.
    //
    // ÚNICA exceção: `services`, e ela é por CAMPO, nunca genérica. O
    // dicionário veio do Transifex do Waze e serviço é comodidade genérica —
    // "ar-condicionado" é ar-condicionado em qualquer país. Categoria não entra
    // aqui porque o Waze a regionaliza POR PAÍS; apelido e ID do Google também
    // não, porque não são enum coisa nenhuma. Chave que faltar cai no valor
    // cru, como todo o resto: feio, nunca invisível.
    if (campo === 'services') {
        const chave = 'card.service.' + String(v);
        const traduzido = t(chave);
        if (traduzido !== chave) return traduzido;
    }
    return String(v);
}

// `{portId: "TYPE2.11", connectorTypes: ["TYPE2"], count: 2}` →
// `portId TYPE2.11 · connectorTypes TYPE2 · count 2`.
//
// Sem tabela de campos de propósito: isto atende o objeto DESCONHECIDO, e o
// Waze adiciona campo sem avisar. Quem tem tratamento próprio (ponto de
// entrada, horário) é resolvido antes de chegar aqui.
function objetoLegivel(v, prof = 0) {
    if (v === null || v === undefined) return t('card.value.empty');
    if (Array.isArray(v)) return v.map((x) => objetoLegivel(x, prof + 1)).join(', ');
    if (typeof v !== 'object') return String(v);
    // Teto de profundidade: aninhamento fundo vira sopa de palavras, e aí o
    // JSON é mais honesto sobre a estrutura do que uma lista achatada.
    if (prof >= 2) {
        try { return JSON.stringify(v); } catch { return String(v); }
    }
    const partes = Object.keys(v).map((k) => `${k} ${objetoLegivel(v[k], prof + 1)}`);
    return partes.length ? partes.join(' · ') : '{}';
}

// Quem pediu, de onde, e se veio sozinho. Três sinais que o Waze manda e o app
// descartava — todos cabem na linha do criador, sem custar altura de card.
//
// Por que cada um decide algo:
//   · rank    L1 anônimo pedindo mudança num local travado é outra coisa que L5
//   · source  MOBILE_CLIENT é alguém dirigindo; WEB é alguém sentado conferindo
//   · lote    42% da fila vem de quem enviou 3+ — se os primeiros do autor forem
//             lixo, os outros provavelmente são, e isso muda o ritmo da triagem
// ── Foco num autor: os pedidos dele vêm PRIMEIRO ─────────────────────────
// 42% da fila vem de quem enviou 3+ pedidos. Se os primeiros de um autor são
// lixo, os outros costumam ser — decidir uma vez e tratar 14 seguidos é o maior
// ganho de tempo que apareceu medindo a fila real.
//
// É PRIORIZAÇÃO, não filtragem, e a diferença importa: esconder os outros 126
// faria a fila "esvaziar" depois dos 14 e o app mostraria "Tudo limpo!" com 126
// pendentes — mentira. Aqui os do autor sobem pra frente e o resto continua
// depois, na mesma ordem relativa. Nada some, nada mente, e o editor recebe
// exatamente o que queria: a série do autor em sequência.
// Chaveado pelo ID, exibido pelo NOME.
//
// O módulo de reincidência já era por `creatorId`; o foco era por `createdBy`,
// e o mesmo card podia mostrar `Ver +2` (por nome) ao lado de um `✕ 6` que não
// virava botão (por id) — dois sistemas de identidade na mesma linha.
//
// Eu quase justifiquei isto com a medição ERRADA, e vale registrar: medi
// COLISÕES (dois ids com o mesmo nome) em 2.035 autores e deu zero — mas nome
// de usuário do Waze é único por construção, então zero era resultado
// garantido, não evidência. O modo de falha real é o MESMO id trocar de nome
// ENTRE sessões, e um instantâneo único nunca consegue ver isso.
//
// E a troca não é hipótese: 69% dos autores da fila real têm nome GERADO
// (`world_xxxxx`), que muda no dia em que a pessoa escolhe um. É o ciclo de
// vida normal da maioria, não um caso de borda.
//
// `id` pode ser 0 em teoria, então as comparações são contra `null`/`undefined`
// explicitamente. `!id` mandaria o foco embora num id 0 sem ninguém ver.
function focarAutor(id) {
    if (id === null || id === undefined || id === '') return;
    // A série pela régua ÚNICA (`serieDoAutor`): o que o "Ver +N" e a folha
    // contaram, com o card da tela na frente. O pedido em andamento (a aprovação
    // de foto no ar) vai pro RESTO — na série ele chegava à frente travado, e a
    // barra o contava sem o selo contar (R6-2-02).
    const daPessoa = serieDoAutor(id, { naTela: AppState.currentPlace });
    if (daPessoa.length === 0) return;
    const naSerie = new Set(daPessoa);
    const atual = AppState.currentPlace;
    const fica = atual && AppState.queue[0] === atual && !naSerie.has(atual) ? atual : null;
    AppState.queue = [...daPessoa, ...AppState.queue.filter((x) => !naSerie.has(x))];
    // O card da TELA que ficou FORA da série — o que a outra aba já decidiu
    // (R11-2-06, ver `serieDoAutor`) — segue na frente, com a série logo depois:
    // o "Ver +N" tocado nele conta os OUTROS, e trocá-lo seria trocar o card
    // debaixo do dedo (a mesma regra do `manterFocoNaFrente`).
    if (fica) AppState.queue.unshift(...AppState.queue.splice(AppState.queue.indexOf(fica), 1));
    AppState.autorEmFoco = id;
    AppState.currentPlace = AppState.queue[0];
    renderFocoAutor();
    removeCurrentCardEl();
    showCurrentPlace();
    updatePendingCount();
}

function limparFocoAutor() {
    if (AppState.autorEmFoco === null || AppState.autorEmFoco === undefined) return;
    AppState.autorEmFoco = null;
    // Aqui a ordem não mexe: QUEM REORDENA é quem chama. A ordem nova escolhida
    // no filtro (`reordenarFilaNaTela`) reordena a fila inteira; o toque na
    // barra (`voltarAOrdemNormal`) reordena o RESTO e deixa o card da tela na
    // frente.
    renderFocoAutor();
}

// A barra do foco promete "Tocar para voltar à ordem normal" (é o nome dela
// pro leitor de tela, nas quatro línguas), e o toque só escondia a barra: a
// série do autor seguia na frente, fora da ordem que o filtro diz — MEDIDO,
// X1,X2,X3,Y1,Y2 depois do toque, com a ordem normal X1,Y1,X2,Y2,X3 (auditoria
// do card, 2026-09-29, C11). Agora o toque cumpre o texto: sai do foco e
// devolve o RESTO da fila à ordem normal (`sortQueue`). O card NA TELA fica na
// frente: trocá-lo seria trocar o pedido debaixo do dedo de quem só pediu a
// ordem de volta. O card de fundo e o "Ver +N" acompanham a fila nova
// (`aoMudarAFilaPorBaixo`).
//
// `ev` é o clique na barra: pelo teclado, o foco não fica pra trás com ela
// (ver `focarDepoisDoFocoNoAutor`).
function voltarAOrdemNormal(ev) {
    if (AppState.autorEmFoco === null || AppState.autorEmFoco === undefined) return;
    const peloTeclado = veioDoTeclado(ev);
    limparFocoAutor();
    const fila = AppState.queue;
    const naTela = AppState.currentPlace && fila[0] === AppState.currentPlace ? fila.shift() : null;
    sortQueue();
    if (naTela) fila.unshift(naTela);
    updatePendingCount();
    aoMudarAFilaPorBaixo();
    if (peloTeclado) focarDepoisDoFocoNoAutor(false);
}

// O FOCO do teclado no par "Ver +N" ⇄ barra do foco — a família do C10
// (auditoria do card, 2026-09-29). Os dois somem com o foco neles: o "Ver +N"
// porque o `focarAutor` remonta o card, a barra porque ela se esconde. MEDIDO
// nos dois motores: Enter em qualquer um largava o foco no <body>. Pelo teclado
// (`veioDoTeclado`), o foco vai ao controle do CAMINHO DE VOLTA: de quem entrou
// no foco (o "Ver +N") pra barra — que ainda anuncia o modo novo ao leitor de
// tela —, e de quem saiu (a barra) pro "Ver +N" do card da tela, o equivalente
// dela no card; sem ele (a série acabou neste card), pro primeiro botão vivo do
// card, ✕ ↑ ✓. Com o card travado, o ✕ fica prometido ao teclado e pousa quando
// destravar (`aplicarFocoDoTeclado`). Quem usa o dedo não tem o foco movido.
function veioDoTeclado(ev) {
    return !!(ev && ev.detail === 0 && ev.currentTarget && document.activeElement === ev.currentTarget);
}

function focarDepoisDoFocoNoAutor(entrou) {
    if (entrou) {
        const barra = document.getElementById('focoAutorBar');
        if (focavelNaTela(barra)) barra.focus({ preventScroll: true });
        return;
    }
    const card = cardDaFrente();
    if (!card) {
        // Sem card — o último pedido do autor era o FIM da fila (R13-2-05): o
        // caminho de volta é o do teclado sem card, o botão do painel que tomou
        // o lugar dele ("Verificar novamente", "Tentar de novo") ou o ✕ do card
        // que chegar (o Desfazer, a próxima página), pela régua do
        // `aplicarFocoDoTeclado` (R7-2-06). Antes nada acontecia, e o foco
        // ficava na barra escondida — o navegador o largava no <body>.
        focoDoTeclado = BOTAO_DA_ACAO.left;
        aplicarFocoDoTeclado();
        return;
    }
    const alvo = ['.selo-lote', '.card-btn-reject', '.card-btn-skip', '.card-btn-read']
        .map((s) => card.querySelector(s)).find(focavelNaTela);
    if (alvo) alvo.focus({ preventScroll: true });
    else focoDoTeclado = BOTAO_DA_ACAO.left;
}

// O foco é uma ordem que a PESSOA pediu, sobre um autor da fila DELA — dado de
// terceiro. Sobrevivia ao "Sair": a próxima conta entrava com a fila reordenada
// pelo autor que a anterior tinha focado, e com a barra "Primeiro os de…" na
// tela sem nunca ter tocado em "Ver +N" (auditoria de 2026-09-26). Sai no
// "Sair" e quando o perfil revela OUTRA conta (`esquecerOutraConta`); a queda
// da sessão sozinha não mexe, porque ali a mesma pessoa volta e segue a série.
//
// E o foco que o TREINO aberto guardou com a fila real (ver `Treino.entrar`)
// também sai: o `encerrar` o devolve, e a troca de conta com o treino aberto
// esquecia o de agora (nulo no treino) e o `resetQueue` logo depois o trazia de
// volta — a fila da conta B nascia com a série do autor que a conta A tinha
// escolhido na frente, e a barra "Primeiro os de X" (R7-7-03, MEDIDO no
// navegador; auditoria de 2026-10-02).
function esquecerFocoAutor() {
    AppState.autorEmFoco = null;
    if (typeof Treino !== 'undefined' && Treino._salvo) Treino._salvo.autorEmFoco = null;
    const bar = document.getElementById('focoAutorBar');
    if (!bar) return;
    bar.classList.add('hidden');
    // O NOME do autor também: escondida, a barra seguia com "Primeiro os de
    // fulano" no DOM, que o diagnóstico leva inteiro.
    bar.removeAttribute('aria-label');
    for (const id of ['focoAutorTexto', 'focoAutorContagem']) {
        const el = document.getElementById(id);
        if (el) el.textContent = '';
    }
}

// A barra some sozinha quando a série acaba — sem isso ela ficaria mentindo
// sobre um foco que não existe mais assim que o card muda de autor.
function renderFocoAutor() {
    const bar = document.getElementById('focoAutorBar');
    if (!bar) return;
    const id = AppState.autorEmFoco;
    const atual = AppState.queue[0];
    // Sem foco no autor a barra não tem o que dizer. Quem DESLIGOU o foco
    // (`limparFocoAutor`: o toque na barra, a ordem nova dos Filtros) cuida do
    // foco do teclado — o Enter na barra o leva ao "Ver +N" do card
    // (`voltarAOrdemNormal`), e o clique do mouse não move foco nenhum.
    if (id === null || id === undefined) {
        bar.classList.add('hidden');
        return;
    }
    // A série que o toque pôs na frente, pela régua ÚNICA (`serieDoAutor`): o
    // pedido em andamento foi pro resto, e a barra contá-lo dizia "3 de 4" com
    // o selo em "Ver +1" (R6-2-02).
    const restam = !atual || atual.creatorId !== id ? 0 : serieDoAutor(id, { naTela: atual }).length;
    // A série ACABOU, por um de três caminhos, e a regra é UMA: a barra sai e,
    // com card na tela, o foco no autor também.
    //   · O card da frente é de OUTRO autor: a seta, o gesto ou o ✕ decidiram o
    //     último pedido dele.
    //   · Não há card: o último pedido dele era o FIM da fila, e o painel tomou
    //     o lugar do card (`showNoPlaces`). O foco no autor FICA: o Desfazer que
    //     devolve esse pedido devolve a barra junto.
    //   · O card do autor segue na tela FORA da série: é o que a OUTRA aba já
    //     decidiu (R11-2-06). A barra dizia "Primeiro os de X · 0 de 3", e o
    //     leitor de tela "Mostrando primeiro os 0 pedidos de X" (MEDIDO no
    //     navegador; auditoria de 2026-10-07, R12-2-06).
    // O foco do TECLADO que estava na barra vai ao caminho de volta no card (o
    // "Ver +N" ou o ✕; travado, o ✕ fica prometido; sem card, o botão do painel
    // — ver `focarDepoisDoFocoNoAutor`), e não ao <body>. Só o terceiro caminho
    // fazia isso: pela seta, com o foco do teclado na barra, o último pedido do
    // autor saía e o foco caía no <body> — e quem usa teclado ou leitor de tela
    // recomeçava do topo da página (MEDIDO nos dois motores; auditoria de
    // 2026-10-07, R13-2-05). Numa microtarefa, porque o `renderCurrentCard`
    // desenha a barra ANTES de pôr o card novo na tela. Quem pôs o foco em outro
    // lugar nesse meio ganha.
    if (restam === 0) {
        if (atual) AppState.autorEmFoco = null;
        const comOFoco = bar.contains(document.activeElement);
        bar.classList.add('hidden');
        if (comOFoco) {
            queueMicrotask(() => {
                const ativo = document.activeElement;
                if (!ativo || ativo === document.body || bar.contains(ativo)) focarDepoisDoFocoNoAutor(false);
            });
        }
        return;
    }
    // O nome é só rótulo. Sem ele o id vira o texto — feio, nunca invisível,
    // como o resto do card faz com valor que o Waze não nomeia.
    const nome = atual.createdBy || String(id);
    document.getElementById('focoAutorTexto').textContent = t('card.focoAutor', { autor: nome });
    document.getElementById('focoAutorContagem').textContent =
        t('card.focoAutor.contagem', { n: restam, total: AppState.queue.length });
    // Com UM pedido dele na fila, a forma plural dizia "os 1 pedidos": o
    // singular é chave própria, escolhida por `=== 1` (sem ICU no projeto).
    bar.setAttribute('aria-label', t(restam === 1 ? 'card.focoAutor.ariaUm' : 'card.focoAutor.aria', { n: restam, autor: nome }));
    bar.classList.remove('hidden');
}

function renderSelosDeProcedencia(card, place) {
    const linha = card.querySelector('.card-creator-row');
    if (!linha) return;
    const selos = [];
    if (Number.isInteger(place.creatorRank)) {
        // +1 porque o Waze é 0-indexed e humano conta de 1 (gotcha #15).
        selos.push({ cls: 'selo-rank', txt: 'L' + (place.creatorRank + 1),
                     title: t('card.creatorRank.title') });
    }
    if (place.source) {
        const rot = rotuloDeEnum('card.source.', place.source);
        // Cada origem tem a redação oficial do WME no title; o genérico atende
        // valor que o Waze inventar depois — o selo cru já diz QUAL é, e a dica
        // ao menos diz o que aquilo significa.
        const dica = t('card.source.' + place.source + '.title');
        if (rot) selos.push({ cls: 'selo-src', txt: rot,
                              title: dica.startsWith('card.source.') ? t('card.source.title') : dica });
    }
    // PELO `pedidosDoAutorNaFila`: eram dois sistemas de identidade na mesma
    // linha, e um card podia mostrar `Ver +2` ao lado de um `✕ 6` que não virava
    // botão. E é a mesma régua da folha e do lote — sem o pedido em andamento
    // (R5-2-02): o "Ver +N" não conta o que o "Rejeitar os N" não leva.
    const mesmos = pedidosDoAutorNaFila(place).filter((x) => x !== place).length;
    if (mesmos > 0) {
        selos.push({ cls: 'selo-lote', txt: t('card.sameAuthor', { n: mesmos }),
                     title: t('card.sameAuthor.acao'), acao: place.creatorId });
    }
    // Reincidência: quantos pedidos DESTE autor você já rejeitou. Rosa é a cor
    // do ✕ em todo o app — reincidência é rejeição acumulada, então herda dele.
    // Abaixo do limiar sai em cinza: o app CONTA, não acusa.
    const reincidente = contagemDoAutor(place);
    if (reincidente >= 2) {
        selos.push({
            cls: reincidente >= AUTOR_LIMIAR_DESTAQUE ? 'selo-reinc' : 'selo-src',
            txt: '✕ ' + reincidente,
            title: t('card.reincidencia.title', { n: reincidente }),
            // Vira BOTÃO sempre que o selo está VERMELHO — a cor é a promessa,
            // e selo vermelho sem toque é promessa quebrada. Vermelho quer dizer
            // "o app está acusando esta pessoa"; se acusa, tem que haver pra onde
            // ir. Abaixo do limiar o selo é cinza (o app CONTA sem acusar) e
            // segue sendo span: não há decisão a tomar sobre quem ele não acusa.
            //
            // Já esteve amarrado TAMBÉM a `pedidosDoAutorNaFila(place).length > 1`,
            // e essa segunda condição estava errada — mas não pelo motivo óbvio.
            // O raciocínio original ("com um só na fila a folha oferece 'Ver o 1'
            // e 'Rejeitar o 1', que é o card na tela com os três botões abaixo")
            // continua verdadeiro; o que estava errado foi a metade que eu cortei.
            // Diante de uma folha redundante eu tirei o BOTÃO, quando o certo era
            // tirar as duas linhas redundantes e pôr no lugar o que o card não
            // consegue mostrar: o que "✕ N" significa (o `title` não existe no
            // toque), o interruptor da recusa automática e o esquecer. Ver
            // `abrirFolhaDoAutor`, que agora se adapta ao tamanho da fila.
            //
            // Reportado pelo owner com um `✕ 8` vermelho e morto na tela — o caso
            // MAIS comum, porque só 27,3% dos cards têm outro pedido do mesmo
            // autor na fila (medido nos 6 países obrigatórios, 2.785 cards). Ou
            // seja: em ~3 de cada 4 vezes o selo vermelho não fazia nada.
            //
            // Contar por `creatorId` e não pelo nome é a razão de sempre neste
            // módulo: 69% dos autores têm nome GERADO, que muda no dia em que a
            // pessoa escolhe um.
            folha: reincidente >= AUTOR_LIMIAR_DESTAQUE ? place : null,
        });
    }
    if (!selos.length) return;
    const box = document.createElement('span');
    box.className = 'selos-proc';
    for (const s of selos) {
        // O selo do lote é o único que AGE: vira botão de verdade (não span com
        // onclick), pra receber foco no Tab e ser anunciado como acionável.
        // `s.acao != null` e não `s.acao`: a ação virou o `creatorId`, e um id 0
        // seria falsy — o selo perderia o botão sem nada avisar.
        const el = document.createElement(s.acao != null || s.folha ? 'button' : 'span');
        el.className = 'selo-proc ' + s.cls;
        el.textContent = s.txt;
        el.title = s.title;
        if (s.acao != null) {
            el.type = 'button';
            el.classList.add('selo-acionavel');
            // Pelo teclado, o foco vai pra barra do foco: o `focarAutor` remonta
            // o card e leva este botão junto (ver `focarDepoisDoFocoNoAutor`).
            el.addEventListener('click', (ev) => {
                ev.stopPropagation();
                const peloTeclado = veioDoTeclado(ev);
                focarAutor(s.acao);
                if (peloTeclado) focarDepoisDoFocoNoAutor(true);
            });
        } else if (s.folha) {
            el.type = 'button';
            el.classList.add('selo-acionavel');
            el.addEventListener('click', (ev) => { ev.stopPropagation(); abrirFolhaDoAutor(s.folha); });
        }
        box.appendChild(el);
    }
    linha.appendChild(box);
}

function renderCardChanges(card, place) {
    if (!place.changes || place.changes.length === 0) {
        // Nenhuma linha, mas por dois motivos MUITO diferentes, e só um deles
        // pode virar afirmação: ou o core comparou campo a campo e todos vieram
        // iguais ao valor atual (`camposSemMudanca > 0`), ou não veio nada pra
        // comparar. Dizer "nada a alterar" no segundo caso seria inventar.
        if (place.camposSemMudanca > 0) {
            const aviso = card.querySelector('.card-sem-diferenca');
            if (aviso) { aviso.classList.remove('hidden'); aviso.classList.add('flex'); }
        }
        return;
    }
    const changesBox = card.querySelector('.card-changes');
    const changesList = card.querySelector('.card-changes-list');
    // A distância das entradas é até o local DESTE card (ver `valorDeLista`).
    const centroDoLocal = place.mapa && place.mapa.centro;
    changesList.innerHTML = place.changes.map((c) => {
        const rotulo = `<span class="text-xs font-semibold text-slate-600 dark:text-slate-300">${escapeHtml(rotuloDoCampo(c))}:</span>`;

        // Campo de LISTA: o que entrou e o que saiu. Mostrar as duas listas
        // inteiras obrigava o editor a comparar de olho — no dado real
        // `services` troca 1 item entre 5 e `categories` ganha 1 entre 2.
        if (c.delta && ((c.delta.add || []).length || (c.delta.del || []).length)) {
            const add = (c.delta.add || []).map((v) => itemDeLista(v, 'diff-add', '+', c.field, centroDoLocal)).join('');
            const del = (c.delta.del || []).map((v) => itemDeLista(v, 'diff-del', '−', c.field, centroDoLocal)).join('');
            return `<div class="diff-row diff-row-lista">${rotulo}<span class="diff-delta">${add}${del}</span></div>`;
        }

        // Objeto simples: só as folhas que mudaram. Antes o card mostrava o
        // objeto inteiro em JSON pra dizer que um campo virou outro — medido na
        // fila real com `categoryAttributes` de um eletroposto. O caminho da
        // folha vai cru (`CHARGING_STATION.network`) porque é o identificador
        // que casa com o WME, mesma razão da categoria.
        // `geometry` NUNCA entra aqui: o core já a exclui, e a guarda dupla é
        // porque ela também é objeto simples e o sequestro desta linha desfaz
        // silenciosamente o "moveu 84 m" (aconteceu ao introduzir isto).
        if (c.field !== 'geometry' && c.objDelta && c.objDelta.length) {
            // Só `categoryAttributes` traduz. Diff de objeto é genérico e serve
            // qualquer campo — aplicar a tabela fora dali seria traduzir o que
            // não é enum de atributo.
            const attr = c.field === 'categoryAttributes';
            // Valor de item de lista: traduzido em atributo, intocado no resto.
            const vItem = (l, v) => (attr ? (valorDeAtributo(l.caminho, v) ?? v) : v);
            const linhas = c.objDelta.map((l) => {
                // Traduzido é PROSA ("Elevação do estacionamento"); cru é
                // IDENTIFICADOR (`PARKING_LOT.lotType`). O identificador precisa
                // de monoespaçado e `break-all` — sem isso um nome longo sem
                // espaço não quebra em lugar nenhum. A prosa com a mesma régua
                // parte no meio da palavra: apareceu "Número de vaga / s" na
                // primeira captura desta mudança.
                const rot = attr ? rotuloDeAtributo(l.caminho) : null;
                const caminho = `<span class="diff-obj-caminho${rot ? ' diff-obj-rotulo' : ''}">`
                    + `${escapeHtml(rot ?? l.caminho)}</span>`;
                const val = (v) => (attr ? (valorDeAtributo(l.caminho, v) ?? valorDoDiff(v)) : valorDoDiff(v));
                // Folha que é LISTA usa o mesmo vocabulário do campo de lista de
                // topo (+ verde entra, − vermelho sai). Dois blocos de JSON lado
                // a lado era o que estava aqui — medido no `chargingPorts` de um
                // eletroposto, e ninguém lia.
                if (l.delta && ((l.delta.add || []).length || (l.delta.del || []).length)) {
                    // `lotType`, `paymentType` e `paymentMethods` são LISTAS de enum,
                    // e é onde o código mais aparecia — o caso do owner tinha
                    // `− UNDERGROUND + MULTI_LEVEL`.
                    //
                    // Traduz o VALOR e entrega ao renderizador ÚNICO. Envolver o
                    // `itemDeLista` num segundo renderizador é o que o guard de
                    // layout proíbe, e com razão: eram dois trechos idênticos
                    // copiados, que é como duas telas do mesmo conceito divergem.
                    const add = (l.delta.add || []).map((v) => itemDeLista(vItem(l, v), 'diff-add', '+')).join('');
                    const del = (l.delta.del || []).map((v) => itemDeLista(vItem(l, v), 'diff-del', '−')).join('');
                    return `<span class="diff-obj-linha diff-obj-linha-lista">${caminho}`
                        + `<span class="diff-delta">${add}${del}</span></span>`;
                }
                return `<span class="diff-obj-linha">${caminho}`
                    + `<span class="diff-from">${escapeHtml(val(l.de))}</span>`
                    + `<span class="diff-to">${escapeHtml(val(l.para))}</span></span>`;
            }).join('');
            return `<div class="diff-row diff-row-obj">${rotulo}<span class="diff-obj">${linhas}</span></div>`;
        }

        // GEOMETRIA tem linha própria. Duas coordenadas de 6 casas quase iguais,
        // uma riscada em vermelho e outra em verde, ocupavam meio card e não
        // respondiam a pergunta do editor, que é "mudou muito?". Aqui a resposta
        // vem primeiro; a coordenada nova fica de referência, pequena.
        if (c.field === 'geometry') {
            const mudouForma = Number.isFinite(c.vertsFrom) && Number.isFinite(c.vertsTo)
                && c.vertsFrom !== c.vertsTo;
            // Abaixo de 5cm é a mesma posição. Dizer "moveu 0 m" numa forma que
            // ganhou vértice é afirmar que nada aconteceu — pior que ser vago.
            const parado = !Number.isFinite(c.movedM) || c.movedM < 0.05;
            let resumo;
            if (parado && mudouForma) resumo = t('card.change.reshaped');
            else if (parado) resumo = t('card.change.samePlace');
            else resumo = formatarDistancia(c.movedM);
            const verts = mudouForma
                ? `<span class="diff-hint">${escapeHtml(t('card.change.verts', { de: c.vertsFrom, para: c.vertsTo }))}</span>`
                : '';
            return `<div class="diff-row diff-row-geo">${rotulo}`
                + `<span class="diff-geo-resumo">${escapeHtml(resumo)}</span>`
                + `${verts}`
                + `<span class="diff-geo-coord">${escapeHtml(valorDoDiff(c.to))}</span></div>`;
        }

        // Realce só quando a diferença é agulha em palheiro (ver `realceDoMiolo`).
        // Nos outros casos a linha sai exatamente como sempre saiu.
        const realce = realceDoMiolo(c.from, c.to);
        if (realce) {
            // O valor inteiro fica no `title`: a janela mostra o que decide, e
            // quem quiser o resto tem onde ver sem abrir o WME.
            const tDe = escapeHtml(String(c.from)), tPara = escapeHtml(String(c.to));
            return `<div class="diff-row">${rotulo}`
                + `<span class="diff-from" title="${tDe}">${ladoRealcado(realce, 'de', 'diff-mark diff-mark-del')}</span>`
                + `<span class="diff-to" title="${tPara}">${ladoRealcado(realce, 'para', 'diff-mark diff-mark-add')}</span></div>`;
        }
        return `<div class="diff-row">${rotulo}`
            + `<span class="diff-from">${escapeHtml(valorDoDiffDoCampo(c.field, c.from))}</span>`
            + `<span class="diff-to">${escapeHtml(valorDoDiffDoCampo(c.field, c.to))}</span></div>`;
    }).join('');
    changesBox.classList.remove('hidden');
}

// Enquanto a janela do "Desfazer" corre, o pedido AINDA NÃO foi pro Waze e dá
// pra voltar atrás. Tratar o próximo nesse meio-tempo despachava o anterior sem
// aviso — e, por acidente de layout, em 6 de 8 aparelhos o banner cobria os
// botões, então o comportamento ainda mudava conforme a tela. Agora é decisão
// explícita: durante os UNDO_WINDOW_MS ninguém prossegue, em nenhum aparelho e
// por nenhum caminho (botão, gesto ou tecla).
//
// Só vale com o "Desfazer" LIGADO. Desligado (Preferências, depois da cota), a
// ação vai na hora e não há janela nenhuma — nem espera.
//
// E SEM SESSÃO nada decide. Entre a queda e a tela de entrada (1,2 s), e durante
// a renovação pela extensão (até 8 s, com o card na tela), o ✕ era aceito: a
// decisão ficava na janela e saía depois com o token que tivesse entrado —
// inclusive o de OUTRA conta do WME —, e o Desfazer aparecia por cima da tela de
// entrada (auditoria da costura, 2026-09-26, K1/K9). É a MESMA trava, numa
// função só (gotcha #63): botão, gesto, tecla e os botões do lightbox, com a
// cara de travado que o botão morto precisa ter. Quem muda o `authenticated`
// reaplica a trava (`derrubarSessao` e `showMainScreen`).
function acoesTravadas() {
    // Inclui as ações de FOTO (aprovar/excluir), não só o swipe. Elas abrem a
    // mesma janela de Desfazer e escrevem no mesmo local — deixar os botões do
    // lightbox vivos durante ela era o defeito que o owner viu: "não estão
    // sendo desativados que nem é feito nos cards".
    // E o LOTE de lidos no ar (`loteDeLidosEmVoo`): os pedidos dele seguem na
    // fila até a resposta, e o ✕ no card da frente mandava uma SEGUNDA decisão
    // pro mesmo pedido (auditoria da fila, 2026-09-26). Sem sessão nada decide
    // (K1/K9): durante a queda e a renovação o gesto sairia com a sessão errada.
    // E a conferência de um 401 numa escrita do lightbox (`refazerDepoisDo401`):
    // a escrita ainda pode sair de novo, e nada pode cruzar com ela (L1).
    // E a APROVAÇÃO no ar do pedido que está na tela (`aprovacaoDaTelaNoAr`).
    // E a conta DESTA aba sendo conferida, com o aparelho tomado por outra
    // sessão (`contaDestaAbaEmDuvida`, R6-1-04) — só depois de o aviso de outra
    // aba a acender (`AppState.contaEmDuvida`); a dúvida mesma é lida na hora.
    return !!(!AppState.authenticated || AppState.pendingAction || aprovacaoPendente || exclusaoPendente
        || renomeacaoPendente || loteDeLidosEmVoo || escritasConferindo > 0 || aprovacaoDaTelaNoAr()
        || (AppState.contaEmDuvida === true && contaDestaAbaEmDuvida()));
}

// A trava do card MENOS as janelas do Desfazer (a do card e as do lightbox),
// que o "Marcar todos" despacha antes de sair, e menos a aprovação no ar, cujo
// pedido o lote já deixa de fora (V7). É o que segura o "Marcar todos": ele
// conferia só a sessão, e com a conta desta aba em DÚVIDA (R6-1-04) o card
// travava mas o lote abria, marcava a fila inteira com a sessão desta aba e
// gravava o placar e o Histórico no aparelho — já de OUTRA conta (MEDIDO,
// auditoria de 2026-10-02, R7-2-02). O aviso é o da trava (`avisoDaTrava`).
function acoesTravadasForaDaJanela() {
    return !!(!AppState.authenticated || loteDeLidosEmVoo || escritasConferindo > 0
        || (AppState.contaEmDuvida === true && contaDestaAbaEmDuvida()));
}

// A aprovação da foto do pedido NA TELA saiu e espera a resposta. O card fica
// na fila até ela voltar (ele só sai quando ela vale), e com ela no ar o ✕ e o
// ✓ do card seguiam vivos: sem o Desfazer, uma rejeição saía JUNTO com a
// aprovação — duas decisões do mesmo pedido no Waze —; com ele, ao fim da
// janela do ✕, e o placar contava um rejeitado de um pedido que a pessoa aprovou
// (achado do lightbox, 2026-09-29; também na main c6d9f91). Botão, gesto e tecla
// passam todos por `acoesTravadas`, então os três travam.
//
// É um conjunto PRÓPRIO, e não o `pedidosEmAndamento`: lá também moram os
// pedidos do "Marcar todos" de uma sessão que caiu, e travar por ele devolvia a
// trava que o V6 tirou da sessão que volta (medido no teste do V6). A aprovação
// de uma sessão que CAIU trava também, mas só na fila em que estava (ver
// `aprovacoesDaQueda`).
function aprovacaoDaTelaNoAr() {
    const p = AppState.currentPlace;
    if (!p) return false;
    const chave = chaveDoPedido(p);
    return aprovacoesNoAr.has(chave) || (aprovacoesDaQueda.has(chave) && aprovacoesDaQueda.get(chave) === AppState.fetchEpoch);
}

// O que dizer a quem tocou com as ações travadas: cada trava pede uma espera, e
// "espere o Desfazer" com nenhum Desfazer na tela manda a pessoa procurar um
// botão que não existe. Sem sessão, a espera é a da sessão (a renovação pela
// extensão, ou entrar de novo).
function avisoDaTrava() {
    // Sem sessão, com a extensão RENOVANDO em silêncio (`extRenovando`): o app
    // de propósito não avisa a queda nessa hora ("avisar antes seria assustar
    // quem nem ia ser interrompido", ver `derrubarSessao`), e o toque no card
    // travado dizia "Sessão expirada" — segundos antes do "Acesso renovado pelo
    // WME — sua fila continua aqui", as duas se contradizendo (R5-2-07). A espera
    // é a da sessão, com o texto que já existe. Só DEPOIS do `aguarde` da ponte:
    // a pergunta sozinha ("tem extensão aí?", 350 ms em todo aparelho) mandava
    // esperar também onde não há extensão nenhuma, logo antes do "a sessão não
    // vale mais" (R6-1-03).
    if (!AppState.authenticated) return extRenovando ? 'toast.esperaSessao' : 'api.error.noSession';
    if (loteDeLidosEmVoo) return 'toast.esperaLote';
    if (escritasConferindo > 0) return 'toast.esperaSessao';
    // A conta desta aba sendo conferida (R6-1-04): também é esperar a sessão.
    if (AppState.contaEmDuvida === true && contaDestaAbaEmDuvida()) return 'toast.esperaSessao';
    if (aprovacaoDaTelaNoAr()) return 'toast.esperaAprovacao';
    return 'toast.esperaDesfazer';
}

// Tocar no card TRAVADO por um motivo SEM banner na tela — o "Marcar todos" no
// ar depois que o toast dele some (4 s), a conferência de um 401, a renovação
// silenciosa da sessão — não respondia NADA: os botões estão `disabled`, o
// arraste não começa e as setas voltam caladas. Botão morto sem motivo à vista
// lê como app quebrado (auditoria do card, 2026-09-29, C14). Os três caminhos
// (o toque no ✕ ↑ ✓, o arraste e as setas) passam por aqui e respondem com o
// aviso que JÁ existe, o mesmo do "Rejeitar os N" (`avisoDaTrava`). Na janela
// do Desfazer, não: o banner com a contagem está na tela e já diz o que é e por
// quanto tempo. E no máximo um a cada `AVISO_DA_TRAVA_INTERVALO_MS`, que é
// também quanto ele DURA: quem insiste no ✕ travado nunca vê dois avisos iguais
// empilhados (com os 4 s de sempre, o segundo chegava com o primeiro na tela).
// Devolve se avisou.
//
// O aviso SAI quando a trava acaba (`dispensarAvisoDaTrava`, chamada pela
// `aplicarTravaDeAcao`): "espere o lote terminar" com o lote terminado é o app
// mentindo. E, MEDIDO, no rodapé do Galaxy Fold e do iPhone SE ele cobre os
// três botões do card (o hit-test no centro de ✕ ↑ ✓ dá o toast): enquanto
// cobre, o botão que voltou a valer está morto (gotcha #26).
const AVISO_DA_TRAVA_INTERVALO_MS = 3000;
let avisoDaTravaEm = 0;
let avisoDaTravaNaTela = null;   // o toast do aviso, pra sair quando a trava acabar
// A renovação da queda ACABOU sem dar, e o aviso de queda já está na tela (ou o
// "Acesso restrito" vem já): até a tela de entrada, o toque no card travado não
// diz mais nada — antes ele empilhava "Sessão expirada" sob "Sua sessão no app
// não vale mais" (R7-1-09). Aceso no fim da renovação (`derrubarSessao`), apagado
// a cada queda nova e quando a sessão volta (`showMainScreen`).
let quedaAnunciada = false;
function avisarTravaAoTocar() {
    if (!acoesTravadas()) return false;
    if (!AppState.authenticated && quedaAnunciada) return false;
    const chave = avisoDaTrava();
    if (chave === 'toast.esperaDesfazer') return false;
    const agora = Date.now();
    if (agora - avisoDaTravaEm < AVISO_DA_TRAVA_INTERVALO_MS) return false;
    avisoDaTravaEm = agora;
    avisoDaTravaNaTela = showToast(t(chave), 'info', AVISO_DA_TRAVA_INTERVALO_MS);
    return true;
}

function dispensarAvisoDaTrava() {
    if (!avisoDaTravaNaTela) return;
    try { avisoDaTravaNaTela.dispensar(); } catch (e) { /* o toast já saiu */ }
    avisoDaTravaNaTela = null;
}

// Card de FOTO cuja foto não veio sem rede (`marcarCardSemFoto`): ✕ e ✓ não
// decidem. O botão a `aplicarTravaDeAcao` já desabilita, mas o GESTO e a SETA
// do teclado passavam direto — dava pra rejeitar uma foto que ninguém viu (o
// gotcha #63 outra vez: o botão trava, o gesto não). O ↑ segue valendo: pular
// é justamente o que o aviso manda fazer.
function direcaoTravada(direcao) {
    if (direcao !== 'left' && direcao !== 'right') return false;
    const card = cardDaFrente();
    return !!(card && card.querySelector('.card-sem-foto'));
}

// Botão travado precisa PARECER travado: botão que não responde e parece normal
// lê como app quebrado (M3/HIG). O `disabled` também tira da ordem do Tab e faz
// o leitor de tela anunciar. A contagem regressiva do banner diz por quanto.
function aplicarTravaDeAcao() {
    const travado = acoesTravadas();
    const card = cardDaFrente();
    if (card) card.classList.toggle('acoes-travadas', travado);
    // Card de FOTO cuja foto não veio (`marcarCardSemFoto`): ✕ e ✓ ficam
    // travados MESMO fora da janela do Desfazer, com o ↑ vivo. Esta função roda
    // a cada ação que começa, termina ou é desfeita, e antes escrevia
    // `disabled = travado` nos três botões sem saber do aviso — então a ação
    // ANTERIOR terminar reabria ✕ e ✓ num card sem foto, e dava pra rejeitar
    // uma foto que ninguém viu. Visto no smoke da estrada rodando contra a main
    // de antes: aviso na tela e ✕ vivo. Duas escritas no mesmo atributo, sem
    // uma saber da outra, é o gotcha #63; a trava mora AQUI, numa função só.
    const semFoto = !!(card && card.querySelector('.card-sem-foto'));
    // Antes de escrever o `disabled`: o botão focado que vira `disabled` perde
    // o foco (R5-2-05).
    if (travado) guardarFocoDaTrava(card);
    for (const cls of ['.card-btn-reject', '.card-btn-skip', '.card-btn-read']) {
        const b = card && card.querySelector(cls);
        if (b) b.disabled = travado || (semFoto && cls !== '.card-btn-skip');
    }
    // Os do lightbox seguem a MESMA regra e a mesma função. Regra duplicada é
    // como as duas telas divergem sem ninguém notar; o esmaecido vem do
    // `:disabled` no CSS, então basta o atributo. E eles têm um motivo a mais,
    // que mora AQUI e não num segundo escritor: uma escrita de foto sem janela
    // no ar (`aprovandoAgora`/`excluindoAgora`, L24).
    const fotoNoAr = aprovandoAgora || excluindoAgora;
    for (const id of ['lightboxApprove', 'lightboxDelete']) {
        const b = document.getElementById(id);
        if (b) b.disabled = travado || fotoNoAr;
    }
    // A pílula do nome também: ela abre a edição, e na janela o
    // `abrirEdicaoNome` saía calado — a pílula parecia viva e não fazia nada
    // (auditoria de 2026-09-26, o gotcha #63 de novo). E ela tem um SEGUNDO
    // motivo pra estar desabilitada, que é ser RÓTULO durante a edição; os dois
    // moram aqui, num escritor só, senão um desfaz o outro (a mesma reincidência
    // do #63 com o card sem foto). O esmaecido de travada vem do CSS, só fora da
    // edição — editando ela é rótulo, e rótulo não se apaga.
    // E um TERCEIRO motivo: uma renomeação deste local no ar (L23). Corrigir de
    // novo com a primeira ainda voando fazia as duas cruzarem no Waze.
    // E um QUARTO: uma EXCLUSÃO de foto deste local no ar (R11-3-06): a que tira
    // a última foto da camada a fecha quando pousa, e jogava fora o nome que se
    // corrigia (`exclusaoDoLocalNoAr`).
    const pilula = document.getElementById('lightboxNomeBtn');
    if (pilula) pilula.disabled = travado || editandoNome() || renomeacaoNoAr(Lightbox.place) || exclusaoDoLocalNoAr(Lightbox.place);
    // O ✓ da edição também (o Enter vai pelo `confirmarRenomear`, que confere a
    // trava): quem escreve o `disabled` dele é o `atualizarBotaoSalvarNome`.
    if (editandoNome()) atualizarBotaoSalvarNome();
    // O controle da foto ampliada que TINHA o foco e acabou de travar (o
    // "Aprovar", a lixeira, a pílula do nome) o perdeu, e o foco caía no <body>
    // com a camada `aria-modal` aberta — a queda da sessão com a extensão
    // renovando, a conferência de um 401, o lote no ar; e a trava, ao acabar,
    // não o devolvia (auditoria de 2026-10-02, R7-3-06, MEDIDO nos dois
    // motores). É o par do `guardarFocoDaTrava` do card: o foco fica na camada,
    // na pílula ou, travada ela também, no ✕ (ver `manterFocoNoLightbox`).
    if (travado) manterFocoNoLightbox();
    // A trava mudou: acabou, o aviso dela sai de cima dos botões (C14); o
    // "Como funciona" que esperava o card destravar (o fim da janela do
    // Desfazer, sobretudo) pode abrir — decidido na microtarefa, DEPOIS do foco
    // da última linha: fechado, ele o devolve ao ✕ que o teclado acabou de
    // ganhar (R7-7-01); e o foco prometido ao teclado pode pousar agora (C10).
    if (!travado) dispensarAvisoDaTrava();
    if (!travado) pedirComoFuncionaAdiado();
    aplicarFocoDoTeclado();
}

// O FOCO de quem opera pelo TECLADO (auditoria do card, 2026-09-29, C10).
// Enter no ✕ ↑ ✓ focado tira o botão da tela — o card sai e o próximo nasce —
// e o foco caía no <body>: o Tab seguinte ia parar na seta do carrossel do card
// novo. Enter no "Desfazer" (o banner some) mandava o Tab pro botão de tema, no
// alto da página. MEDIDO nos dois motores. O foco vai ao botão EQUIVALENTE do
// card que ficou na tela: o do próximo pedido, ou o do pedido que o Desfazer
// devolveu.
//
// Só quando o gesto veio do TECLADO: o botão acionado ESTAVA focado e a
// ativação foi por tecla (`detail` 0 no clique, que é também o do leitor de
// tela) — um `.click()` programático não conta, e o mouse e o dedo têm
// `detail` 1. Quem usa o dedo não pode ter o foco pulando pela tela, e qualquer
// `pointerdown` desliga o pedido (`setupAppListeners`).
//
// O foco ESPERA o botão destravar: na janela do Desfazer o card novo nasce
// `disabled`, botão desabilitado não recebe foco e o focado que vira `disabled`
// o perde (MEDIDO no Chromium e no WebKit). Quem aplica é a
// `aplicarTravaDeAcao`, que roda sempre que a trava muda, e o card que nasce
// (`renderCurrentCard`, depois da tarefa: a trava da ação vem logo em seguida,
// no mesmo gesto). Se nesse meio a pessoa pôs o foco em outro lugar — Tab,
// clique, uma camada aberta —, o pedido cai: o lugar que ela escolheu ganha.
const BOTAO_DA_ACAO = { left: '.card-btn-reject', up: '.card-btn-skip', right: '.card-btn-read',
    reject: '.card-btn-reject', skip: '.card-btn-skip', read: '.card-btn-read' };
let focoDoTeclado = null;   // o seletor do botão que recebe o foco (ou a lista, R9-3-02), ou null

function pedirFocoDoTeclado(botao, peloTeclado, acao) {
    if (!peloTeclado || !botao || document.activeElement !== botao) return;
    focoDoTeclado = BOTAO_DA_ACAO[acao] || null;
}

// A trava que LIGA com o foco num ✕ ↑ ✓ do card da frente (R5-2-05): o botão
// vira `disabled`, perde o foco, e ninguém o devolvia — o foco ficava no <body>
// depois de a trava acabar. MEDIDO nos dois motores com o "Pular guarda": o C10
// pousa o foco no ↑ do card novo quando a janela do Desfazer acaba, o
// `guardar-pedido` leva 401, e a conferência trava os três botões. Vale pra
// toda trava que liga com o foco já ali (a queda da sessão, a escrita do
// lightbox conferindo um 401). O foco fica PROMETIDO ao mesmo botão e pousa
// pelo `aplicarFocoDoTeclado` quando a trava acabar, com as regras dele: quem
// pôs o foco em outro lugar, ou pegou o mouse ou o dedo, ganha. Não é foco
// pulando pela tela: ele volta pra onde estava.
function guardarFocoDaTrava(card) {
    const ativo = document.activeElement;
    if (!card || !ativo || ativo === document.body) return;
    const sel = ['.card-btn-reject', '.card-btn-skip', '.card-btn-read'].find((s) => card.querySelector(s) === ativo);
    if (sel) focoDoTeclado = sel;
}

function aplicarFocoDoTeclado() {
    if (!focoDoTeclado || acoesTravadas()) return;
    const ativo = document.activeElement;
    const camada = !!(topOpenModal()
        || (typeof Lightbox !== 'undefined' && Lightbox.isOpen())
        || (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()));
    // Quem pôs o foco num controle VIVO (o Tab, o clique) ganha. O foco num
    // controle que SUMIU (escondido com o painel, fora da página) é foco
    // perdido, mesmo antes de o navegador o devolver ao <body> — ele só faz isso
    // no próximo desenho, e o card que chega antes perdia o foco prometido
    // (R6-2-13: o "Verificar novamente" some com o painel quando o card volta).
    if ((ativo && ativo !== document.body && focavelNaTela(ativo)) || camada) { focoDoTeclado = null; return; }
    const card = cardDaFrente();
    if (!card) {
        // A fila ACABOU com o foco prometido: o ✕ ↑ ✓ do ÚLTIMO card saiu com
        // ele, o "Verificar novamente" voltou sem nada, o "Rejeitar os N" levou o
        // resto da fila — e não vem card nenhum. O foco caía no <body>, e quem
        // usa teclado ou leitor de tela recomeçava do topo da página (MEDIDO nos
        // dois motores; auditoria de 2026-10-02, R7-2-06). Vai ao botão do painel
        // que tomou o lugar do card, o caminho de volta: "Tentar de novo" na
        // falha, "Verificar novamente" no "Tudo limpo!"/"Fim da fila". Sem painel
        // na tela (a busca ainda corre), a promessa espera quem chegar: o card
        // (`renderCurrentCard`) ou o painel (`showNoPlaces`).
        const painelNaTela = (id) => {
            const p = document.getElementById(id);
            return !!p && !p.classList.contains('hidden');
        };
        const botao = painelNaTela('loadErrorState') ? document.getElementById('retryLoadBtn')
            : painelNaTela('noMoreCards') ? document.getElementById('reloadBtn') : null;
        if (!focavelNaTela(botao)) return;
        focoDoTeclado = null;
        botao.focus();
        return;
    }
    // Card de foto sem a foto: ✕ e ✓ seguem travados, e o ↑ é o vivo. A
    // promessa é UM seletor (o botão equivalente, C10) ou uma LISTA em ordem: o
    // fechar de uma ampliação sem card na tela promete o mesmo lugar no card que
    // chegar, a foto ou o mapa dele (`devolverFocoDaAmpliacao`, R9-3-02).
    const sels = Array.isArray(focoDoTeclado) ? focoDoTeclado : [focoDoTeclado];
    const alvo = [...sels, '.card-btn-skip'].map((s) => card.querySelector(s)).find(focavelNaTela);
    if (!alvo) return;
    focoDoTeclado = null;
    alvo.focus({ preventScroll: true });
}

// "Verificar novamente" (o "Fim da fila"/"Tudo limpo!") e "Tentar de novo" (a
// falha ao carregar) somem com o painel quando o card volta — com o foco neles.
// Pelo teclado ele caía no <body>, e quem usa teclado ou leitor de tela
// recomeçava do topo da página (MEDIDO, s45; auditoria de 2026-10-02, R6-2-13).
// A regra do C10 pra todo controle que some com o foco: pelo teclado
// (`veioDoTeclado`), o foco é prometido ao ✕ do card que chegar — ou ao ↑, num
// card de foto sem a foto — e pousa quando ele chegar (`renderCurrentCard`). O
// mouse e o dedo não movem nada.
function prometerFocoAoCardQueVem(ev) {
    if (veioDoTeclado(ev)) focoDoTeclado = BOTAO_DA_ACAO.left;
}

// A rolagem do conteúdo é CONSEQUÊNCIA de estourar, não estado padrão — e a
// medição precisa ser VIVA, não uma foto do primeiro quadro.
//
// Antes, o `overflow-y: auto` estava cravado no HTML e valia sempre. Uma sobra
// de UM PIXEL — arredondamento de fração do flex, não conteúdo que não cabe —
// já desenhava barra de rolagem no desktop. Relatado pelo owner e reproduzido
// com o card dele (conteúdo 284,x px numa caixa de 283,y px).
//
// Tirar o auto do HTML sozinho seria pior: se o conteúdo estourar DEPOIS (girar
// o aparelho, aumentar a fonte do sistema, zoom só-de-texto), o texto ficaria
// cortado sem saída — que é exatamente o que o guard de layout protege. Por isso
// aqui tem ResizeObserver: quem garante a saída é a medição continuar rodando,
// não um overflow ligado pra sempre.
//
// Tolerância de 2px: scrollHeight e clientHeight são INTEIROS arredondados de
// alturas fracionárias, e cada borda pode errar ~1px. Ela cobre SÓ isso — a
// falta de espaço de verdade cresce contínua com a janela (medido no card do
// segundo relato: 0,17 → 1,34 → 2,55 → 3,28px) e quem a resolve é o piso do
// texto no CSS, não uma tolerância maior aqui.
const TOLERANCIA_ARREDONDAMENTO_PX = 2;

function vigiarEstouroDoConteudo(el) {
    if (!el) return;

    // O callback do observer NÃO pode mexer no DOM: ligar a classe muda o
    // `overflow-y`, e onde a barra de rolagem é CLÁSSICA (desktop) ela ocupa
    // largura — encolhendo justamente o content box que este observer observa.
    // O browser detecta a re-entrada e emite "ResizeObserver loop completed
    // with undelivered notifications", que o window.onerror mostrava como toast
    // vermelho pro editor. Reproduzido no card do owner: só acontece na faixa
    // marginal (sobra de 3-4px), porque é onde a classe TROCA de estado; com
    // estouro claro ela já nasce ligada e nada re-dispara.
    //
    // Por isso o observer só AGENDA: a escrita acontece no quadro seguinte,
    // fora do ciclo de entrega. E só escreve se a decisão mudou, então em
    // regime permanente o custo é zero.
    //
    // Converge sempre, e isso é propriedade da geometria, não sorte: barra
    // VERTICAL não muda a altura da caixa, só estreita o conteúdo. Estreitar
    // só faz o texto ficar mais alto — então o que estourava sem barra segue
    // estourando com ela, e o que cabe COM a barra também cabe sem. Os dois
    // sentidos são estáveis; não há como piscar.
    let ligado = el.classList.contains('card-content-rola');
    let agendado = false;

    const escrever = () => {
        agendado = false;
        const estoura = el.scrollHeight > el.clientHeight + TOLERANCIA_ARREDONDAMENTO_PX;
        if (estoura === ligado) return;
        ligado = estoura;
        el.classList.toggle('card-content-rola', estoura);
    };
    // O primeiro quadro mente: antes do layout assentar, scrollHeight não vale.
    const agendar = () => {
        if (agendado) return;
        agendado = true;
        requestAnimationFrame(escrever);
    };

    agendar();
    if (typeof ResizeObserver === 'function') {
        const obs = new ResizeObserver(agendar);
        // A caixa é `flex-1` dentro de um card de altura fixa: quando o texto
        // cresce sem a caixa mudar de tamanho — fonte do sistema maior, zoom
        // só-de-texto — observar SÓ a caixa não dispara nada e a rede nunca
        // liga. Quem denuncia esse caso são os filhos.
        obs.observe(el);
        for (const filho of el.children) obs.observe(filho);
    }
}

// Scroll edge effect (M3): esmaece a borda de baixo enquanto sobra conteúdo.
// Área que rola sem dizer que rola é área que ninguém rola — e aqui isso custa
// caro, porque arrastar o card pra cima PULA: quem não souber que a caixa rola
// nunca vai ver o resto da lista. Some ao chegar no fim, pra não parecer corte.
// O ResizeObserver existe porque a caixa é `flex-1`: ela muda de tamanho quando
// o card entra, quando a foto carrega e quando o aparelho gira.
function marcarBordaRolagem(el) {
    if (!el) return;
    const atualizar = () => {
        el.classList.toggle('rola-mais', el.scrollHeight - el.scrollTop - el.clientHeight > 1);
    };
    el.addEventListener('scroll', atualizar, { passive: true });
    if (typeof ResizeObserver === 'function') new ResizeObserver(atualizar).observe(el);
    requestAnimationFrame(atualizar);
}

// Sem nome, o ENDEREÇO é a identidade — é o que o Google Maps faz com ponto sem
// nome, e o que faltava aqui: "sem nome" ocupava o slot de 1.35rem enquanto a
// única coisa que identificava o local ficava em cinza pequeno logo abaixo.
// Invertido. A ausência não some: vira selo (ver .card-no-name-badge), porque
// num pedido de place ela PODE ser informação de decisão — mas só onde ela é
// INESPERADA, e é isso que `ausenciaEsperada` decide.
//
// Cadeia: nome → endereço → "(local sem nome)". Só o último é placeholder — o
// endereço promovido é DADO, e por isso não leva o esmaecido de ausente.
function identidadeDoPlace(place) {
    const nome = String(place.name || '').trim();
    if (nome) return { titulo: nome, semNome: false, tituloEhEndereco: false, ausente: false };
    const endereco = String(place.address || '').trim();
    if (endereco) return { titulo: endereco, semNome: true, tituloEhEndereco: true, ausente: false };
    return { titulo: t('card.noName'), semNome: true, tituloEhEndereco: false, ausente: true };
}

// O texto alternativo da foto `i` de `n` do pedido: o do card E o da foto
// ampliada, por esta função só — é o MESMO pixel, e o leitor de tela não pode
// ouvir um local no card e outro na ampliação. A ampliada usava só o NOME e,
// sem ele (todo local residencial, 100% sem nome), caía em "Foto do place" —
// no português e no espanhol, com a palavra em inglês —, enquanto o card dizia
// "Foto de Rua das Flores, 250 (1 de 2)" (auditoria de 2026-09-29, L32).
function altDaFoto(place, i, n) {
    // Num LOCAL NOVO toda foto está sendo proposta junto com o local (ver o
    // `renderCardImages`): quem não vê o card ouve isso aqui.
    const propostaComOLocal = place.purType === 'NEW_PLACE' || place.reqType === 'VENUE';
    return t(propostaComOLocal ? 'card.img.altNovoLocal' : 'card.img.alt',
        { name: identidadeDoPlace(place).titulo, i, n });
}

// ── MANDAR O PEDIDO ABERTO PELA CONVERSA ────────────────────────────────────
//
// Vai um RESUMO, não o place inteiro: o `changes[]`, o `mapa` e a escrituração
// do venue não cabem numa pergunta ("isso é fachada ou é a sala?") e só
// engordariam o que trafega. O que vai é o que a folha de leitura mostra.
//
// E vai CHAVE, nunca texto renderizado (`updateTypeKey`, categorias cruas):
// quem manda pode estar em português e quem recebe em francês. É a mesma regra
// que o servidor já segue com o card — o remetente não escolhe a palavra que
// aparece na tela do outro.
//
// Devolve `null` quando não há pedido aberto (fila vazia, "Tudo limpo!", modo
// treino), e é isso que faz o botão sumir em vez de virar botão morto.
function cardParaConversa() {
    const place = AppState.currentPlace;
    if (!place || !place.venueID) return null;
    // Pedido de treino — o clone inerte e o exemplo sintético, os dois com a
    // marca (R10-7-01) — não existe pra mais ninguém.
    if (place._treino) return null;
    // A foto que o CARD mostra, pela mesma regra do carrossel (`fotosDoCard`):
    // num pedido de foto, a que está EM DECISÃO. Mandava `place.imageUrl`, que é
    // a PRIMEIRA do local — num pedido de "Nova foto" o colega recebia uma foto
    // que o local já tinha, e não a que se estava perguntando sobre. Vai CRUA,
    // sem o sufixo do offline: o cache de quem recebe não é o de quem manda.
    const fotos = fotosDoCard(place);
    return {
        venueID: place.venueID,
        updateRequestID: place.updateRequestID || null,
        name: place.name || '',
        address: place.address || '',
        categories: Array.isArray(place.categories) ? place.categories.slice(0, 4) : [],
        updateTypeKey: place.updateTypeKey || null,
        imageUrl: fotos.urls[fotos.inicial] || null,
        lat: place.lat ?? null,
        lon: place.lon ?? null,
        // A região vai junto porque o link do WME depende dela e quem recebe
        // pode estar filtrando outra. Sem isto o ↗ levaria pro ambiente errado.
        region: API.getRegion(),
    };
}

// Monta a URL do WME pro pedido — a MESMA regra do ↗ do card (env por região,
// lat/lon com zoom 22, venueUpdateRequest com o venueID). Fonte única: o card e
// a folha de leitura chamam daqui, senão os dois links divergem sem ninguém ver.
// Casas decimais da coordenada no permalink. O número é do PRÓPRIO WME, lido no
// bundle dele (v2.367): `units: { lonLatPrecision: 5 }`, e é esse valor que o
// construtor de permalink aplica (`n.lat.toFixed(Config.units.lonLatPrecision)`).
// As duas URLs que o owner colou vêm com 5 casas porque saíram de lá.
//
// Cinco casas são ~1,1 m. No zoom 22 isso são ~30 px de deslocamento no CENTRO
// do mapa — e é aceitável porque quem marca o local é o `venues=`, não a
// coordenada: ela só enquadra. Precisão maior alongaria a URL sem mudar o que a
// pessoa vê selecionado.
const COORD_CASAS = 5;

// `Number(...)` por fora do `toFixed` corta zero à direita (`-23.40000` vira
// `-23.4`), que é o objetivo aqui: encurtar. O próprio WME usa esta MESMA forma
// no "copiar coordenadas" (`Number(e.toFixed(s))`); o permalink dele usa o
// `toFixed` cru, e os dois valem o mesmo NÚMERO — a diferença é só o texto.
//
// Não vira notação exponencial: depois do `toFixed(5)` o menor valor não-nulo é
// 0.00001, e o JS só troca pra exponencial abaixo de 1e-6.
const coordDoLink = (n) => Number(n.toFixed(COORD_CASAS));

// A URL do ↗ é um PERMALINK do WME, e a gramática dele é `tipoDeFeature=ids`.
// MEDIDO no bundle do WME (v2.367, `app-f7541f99…js`): o construtor de permalink
// espalha o `getMapSelection()` — um mapa `{tipo: ids}` — direto na query, e
// `venues`/`venueUpdateRequest` são dois desses tipos. `feature_editor` é um
// nome de aba (ao lado de `issue_tracker`, `areas`, `prefs`…). Ou seja: não é
// truque, é o link que o próprio WME gera quando você seleciona os dois e copia.
//
// `venues=` e `tab=feature_editor` entraram a pedido do owner (2026-09-03): sem
// eles o WME abria a SOLICITAÇÃO mas não selecionava o local, então quem clicava
// pra corrigir ainda tinha que achar o lugar no mapa. Com eles, cai no editor do
// local com a solicitação aberta — que é exatamente o que o ↗ promete, já que o
// app não edita dado de local por princípio.
//
// Os DOIS levam o `venueID`, e é contraintuitivo: `venueUpdateRequest` NÃO leva
// o id do pedido. Já estava assim (confirmado por HAR do WME nativo) e foi
// reconfirmado agora com dado real — nas duas URLs que o owner colou, uma é
// `NEW_PHOTO` cujo `updateRequestID` é um UUID (`ab3f9d27-…`) e mesmo assim o
// permalink que FUNCIONA traz o venueID. Medido na fila do Brasil (503 pedidos):
// `venueID === updateRequestID` só em `NEW_PLACE` (213); nos outros 290 o pedido
// é UUID. Se algum dia alguém "consertar" isto passando o UUID, quebra em 58%
// dos cards — travado em `test/layout.test.mjs`.
function linkWmeDoPedido(dados, region) {
    const envParam = region === 'na' ? 'usa' : region;
    const params = [`env=${envParam}`];
    // `Number.isFinite` e não a checagem por verdade: latitude 0 corta o Brasil
    // (Macapá) e longitude 0 corta o Reino Unido (Greenwich) — dois dos seis
    // países de validação. Com `dados.lat && dados.lon` o zero cai fora e o
    // editor abre no último lugar que a pessoa estava, sem sintoma nenhum.
    if (Number.isFinite(dados.lat) && Number.isFinite(dados.lon)) {
        params.push(`lat=${coordDoLink(dados.lat)}`, `lon=${coordDoLink(dados.lon)}`, 'zoomLevel=22');
    }
    if (dados.venueID) {
        const id = encodeURIComponent(dados.venueID);
        params.push(`venues=${id}`, `venueUpdateRequest=${id}`);
        // A aba só entra COM seleção: `feature_editor` sem nada selecionado abre
        // um painel vazio, que é pior que deixar o WME escolher a aba dele.
        params.push('tab=feature_editor');
    }
    return `${WME_EDITOR_URL}?${params.join('&')}`;
}

// Abre o pedido que CHEGOU pela conversa. Só leitura: sem ✕ ↑ ✓, porque ele não
// está na fila de quem recebe.
function abrirPedidoRecebido(dados, deQuem) {
    if (!dados) return;
    // O `$` deste arquivo é LOCAL de cada função que o declara, não global —
    // três funções já fazem exatamente isto. Assumi que era global porque o vi
    // sendo usado no setup, e o smoke devolveu `$ is not defined` na cara.
    const $ = (id) => document.getElementById(id);
    const ident = identidadeDoPlace(dados);
    $('pedidoNome').textContent = ident.titulo;
    $('pedidoDe').textContent = t('presenca.pedido.de', { nome: deQuem || t('presenca.anon') });

    const foto = $('pedidoFoto');
    if (dados.imageUrl) {
        const img = $('pedidoFotoImg');
        // Foto que não vem (o Waze a tirou do ar, sem sinal) SAI da folha, como a
        // do card: o ícone de imagem quebrada no topo não informa nada
        // (auditoria de 2026-09-25). Pendurado ANTES do `src`: o erro pode
        // chegar no mesmo tique, com a foto já no cache como falha.
        img.onerror = () => { foto.classList.add('hidden'); };
        img.src = dados.imageUrl;
        foto.classList.remove('hidden');
    } else {
        $('pedidoFotoImg').removeAttribute('src');
        foto.classList.add('hidden');
    }

    const linha = (idRow, idVal, valor) => {
        $(idRow).classList.toggle('hidden', !valor);
        if (valor) $(idVal).textContent = valor;
    };
    // `rotuloDeEnum`, como no card: o cartão vem de OUTRO aparelho, que pode
    // mandar um tipo que este dicionário não tem — a chave crua ia pra tela.
    linha('pedidoTipoRow', 'pedidoTipo', rotuloDeEnum('card.updateType.', dados.updateTypeKey));
    // Categoria sai CRUA de propósito: o Waze regionaliza por PAÍS, não por
    // idioma, então traduzir erraria em metade dos países (ver gotcha #39).
    linha('pedidoCatRow', 'pedidoCat', (dados.categories || []).join(', '));
    // Sem nome o endereço já virou o TÍTULO — repeti-lo aqui seria dizer a
    // mesma coisa duas vezes, que é o que o card também evita.
    linha('pedidoEndRow', 'pedidoEnd', ident.tituloEhEndereco ? '' : (dados.address || ''));

    $('pedidoWme').href = linkWmeDoPedido(dados, dados.region || API.getRegion());
    openModal('pedidoModal');
}

// Categorias em que NÃO ter nome é o normal — o selo não aparece nelas.
//
// MEDIDO em 4692 pedidos dos 13 países de validação (o dado CRU do Waze, não a
// fila filtrada por permissão, que fora do Brasil devolve zero): a ausência de
// nome é 100% em RESIDENCE_HOME (325 de 325) e exceção em todo o resto —
// PARKING_LOT 8,1%, PARK 8,3%, CHARGING_STATION 4,0%, e ZERO em GAS_STATION
// (427), RESTAURANT (149) e SUPERMARKET_GROCERY (125).
//
// Sinal que dispara em 100% de uma classe não distingue nada dentro dela: ele
// não diz "olhe isto", diz "isto é RESIDENCE_HOME" — que a linha de categoria
// logo abaixo já diz. Pior: selo em destaque no topo lê como alerta, e para
// casa a ausência é normal, então ele convidava a rejeitar o que está certo.
// São 8% da fila global e 15% da do owner — não é caso de canto.
//
// A regra que fica: o selo marca ausência INESPERADA, não ausência. Categoria
// nova entra aqui só com a taxa medida perto de 100%; abaixo disso, o selo
// informa e deve aparecer.
//
// Isto substitui a justificativa antiga ("RESIDENCE_HOME sem nome é forte
// candidato a rejeitar"), que era raciocínio de escrivaninha sobre uma amostra
// brasileira pequena — e que o dado nega.
const CATEGORIAS_SEM_NOME_ESPERADO = Object.freeze(['RESIDENCE_HOME']);

function ausenciaDeNomeEsperada(place) {
    const cats = Array.isArray(place && place.categories) ? place.categories : [];
    return cats.some((c) => CATEGORIAS_SEM_NOME_ESPERADO.includes(c));
}

// Escreve valor OU placeholder, marcando qual dos dois é. O texto entre
// parênteses já diz sozinho (e o leitor de tela lê); o esmaecido em itálico é
// reforço visual. Cor sozinha não serviria — WCAG 1.4.1.
function escreverValor(el, valor, chaveVazio) {
    if (!el) return;
    const v = valor === null || valor === undefined ? '' : String(valor).trim();
    el.textContent = v || t(chaveVazio);
    el.classList.toggle('valor-ausente', !v);
}

// O core manda TIPO, não palavra: null = vazio, boolean = sim/não, '' = existe
// sem nome. Ver formatValue em server/core.mjs.
// Onde exatamente dois textos diferem, quando isso NÃO se vê num relance.
//
// O card já mostra o valor antigo riscado em vermelho e o novo em verde, lado a
// lado — e pra quase toda mudança isso basta: `Bom Atacarejo` → `Strapasson` se
// lê num piscar. O owner recusou (com razão) selo que explica o óbvio: editor de
// mapa não precisa de muleta pra comparar dois nomes.
//
// O que engana o olho é OUTRA coisa, e ela se descobriu medindo: a diferença
// que NÃO muda o tamanho da string. Sem mudança de tamanho não há pista de
// forma, e as duas linhas parecem a mesma linha:
//
//   Aeroport Josep Tarradellas Barcelona - El Prat T1     CDG Terminal 2F
//   Aeroport Josep Tarradellas Barcelona - El Prat T2     CDG Terminal 2C
//                                                  ^                   ^
//
// Compare com o que CRESCE, e que ninguém deixa passar:
//   Goose Street Car Park  →  Goose Street Car Parkuuuu
//   Termas Prexigueiro     →  Termas de Prexigueiro
//
// MEDIDO em 453 mudanças de texto de 13 países. Os três limiares saem daí:
//
//   `REALCE_DELTA_MAX` é O QUE DECIDE. Δ≤1 separa limpo: de um lado ficam
//   `Radmore`→`Radmoor`, `Sánchez`→`Sanchez`, `Inglesia`→`Iglesia`,
//   `Rincón del`→`Rincón de`, `Falésia`→`Falésiau`, `Sé Catedral`→`Sé QCatedral`,
//   `Gate 7`→`Gate 8`, e as 12 variantes de `CDG Terminal 2F`. Do outro, tudo
//   que ganha ou perde pedaço visível (`…Barajas T2`, `W Boulangerie`,
//   `Corporationhhdh`, `/天汇`).
//
//   `REALCE_MIOLO_MAX` = 3. Em 2 perderia `CDG Terminal 2F`→`T2d`; em 4 entraria
//   `ChaMiLukie`→`ChaMiLuLiLi`, que já se vê. O empate é DESEQUILIBRADO e por
//   isso resolvido pra cima: realçar de mais custa um destaque que ninguém
//   pediu; realçar de menos custa aprovar `T1` achando que é `T1`.
//
//   `REALCE_CONTEXTO_MIN` = 10 é piso, não fronteira — de 8 a 10 dá o mesmo
//   número. Existe pra `"71"`→`"20"` solto nunca virar realce.
//
// Resultado: 49 de 453 (10,8%). Uma primeira versão usava "contexto ≥ 18 e
// miolo ≤ 6" e estava errada nas duas pontas — deixava de fora TODOS os
// `CDG Terminal 2F` (contexto 14) e marcava os apensos visíveis.
const REALCE_DELTA_MAX = 1;      // diferença de comprimento entre os dois textos
const REALCE_MIOLO_MAX = 3;      // caracteres que de fato mudam, no maior dos dois
const REALCE_CONTEXTO_MIN = 10;  // caracteres idênticos somando início e fim
// Quanto do texto IDÊNTICO fica em volta do realce. Existe porque `.diff-from` e
// `.diff-to` são `-webkit-line-clamp: 3`, e MEDIDO no Galaxy Fold a coluna cabe
// ~15 caracteres por linha: um nome de 49 é cortado ANTES da diferença. Sem
// isto o recurso ficaria invisível justamente na tela mais apertada — e, pior,
// o card de hoje já esconde ali a informação que decide (`…El Prat T1` e
// `…El Prat T2` saem idênticos num Fold).
//
// 16 é folgado de propósito: os valores curtos, que são a maioria dos casos
// (`CDG Terminal 2F` tem 13 de contexto), passam INTEIROS e nada se perde. Só
// encurta o que seria cortado de qualquer jeito — e aí mostrar a vizinhança da
// diferença é estritamente melhor que mostrar um prefixo que termina antes
// dela. O valor completo continua no `title`.
const REALCE_JANELA = 16;

// Prefixo e sufixo comuns, por CARACTERE Unicode (`[...s]`, não `s[i]`): com
// índice de UTF-16 um emoji ou um acento composto se parte no meio e o realce
// sairia cortando o próprio caractere.
//
// Prefixo/sufixo em vez de distância de edição completa porque é isso que o
// olho faz — e nos casos reais dá a mesma resposta com uma fração do custo.
// Devolve `null` quando a regra não se aplica: quem chama não decide nada.
function realceDoMiolo(de, para) {
    if (typeof de !== 'string' || typeof para !== 'string' || de === para) return null;
    const A = [...de], B = [...para];
    if (Math.abs(A.length - B.length) > REALCE_DELTA_MAX) return null;
    let p = 0;
    while (p < A.length && p < B.length && A[p] === B[p]) p++;
    let s = 0;
    while (s < A.length - p && s < B.length - p && A[A.length - 1 - s] === B[B.length - 1 - s]) s++;
    const mA = A.length - p - s, mB = B.length - p - s;
    if (p + s < REALCE_CONTEXTO_MIN) return null;
    if (Math.max(mA, mB) > REALCE_MIOLO_MAX) return null;
    // Janela: o prefixo e o sufixo comuns entram no máximo `REALCE_JANELA`
    // caracteres. O que sobrar vira reticência — e ela é do mesmo lado nos dois
    // valores, senão as duas linhas deixariam de se alinhar na leitura.
    const cortaIni = p > REALCE_JANELA, cortaFim = s > REALCE_JANELA;
    const ini = cortaIni ? p - REALCE_JANELA : 0;
    const fimA = cortaFim ? p + mA + REALCE_JANELA : A.length;
    const fimB = cortaFim ? p + mB + REALCE_JANELA : B.length;
    return {
      de: [A.slice(ini, p), A.slice(p, p + mA), A.slice(p + mA, fimA)].map((x) => x.join('')),
      para: [B.slice(ini, p), B.slice(p, p + mB), B.slice(p + mB, fimB)].map((x) => x.join('')),
      cortaIni, cortaFim,
    };
}

function ladoRealcado(realce, lado, classe) {
    const [antes, meio, depois] = realce[lado];
    return (realce.cortaIni ? '…' : '')
        + escapeHtml(antes)
        + (meio ? `<mark class="${classe}">${escapeHtml(meio)}</mark>` : '')
        + escapeHtml(depois)
        + (realce.cortaFim ? '…' : '');
}

function valorDoDiff(v) {
    if (v === null || v === undefined) return t('card.value.empty');
    if (v === true) return t('card.value.yes');
    if (v === false) return t('card.value.no');
    if (v === '') return t('card.value.unnamed');
    // Objeto/array chegando aqui vira "[object Object]" no `String()` — o
    // defeito que já apareceu em 33 de 142 pedidos com geometria. O diff de
    // objeto pode ter folha que é lista (`chargingPorts` de um eletroposto,
    // medido), e ela precisa de saída. JSON é feio; invisível é pior.
    if (typeof v === 'object') {
        try { return JSON.stringify(v); } catch { return String(v); }
    }
    return String(v);
}

// O valor de uma linha do diff, pelo CAMPO — o `valorDoDiff` não sabe de qual
// campo o valor é, e há campo cujo número cru não é o que o WME mostra.
//
// `lockRank` é 0-indexado como o rank (gotcha #15): o WME mostra rank + 1, e o
// card dizia "Nível de trava: 0 → 4" onde o WME diz 1 → 5 (auditoria de
// 2026-09-26). Só inteiro vira nível; o resto (inclusive o vazio) segue o
// `valorDoDiff`, porque as tipagens do WME dão `lockRank` de local como número
// sempre — o vazio é campo que o Waze não mandou, e "(vazio)" diz exatamente isso.
function valorDoDiffDoCampo(campo, v) {
    if (campo === 'lockRank' && Number.isInteger(v)) return String(v + 1);
    return valorDoDiff(v);
}

// Rótulo do campo pela CHAVE (`name`, `phone`…). Campo não mapeado cai no `label`
// que o core ainda manda — feio (nome cru da API) mas nunca invisível.
function rotuloDoCampo(mudanca) {
    const chave = 'card.field.' + mudanca.field;
    const traduzido = t(chave);
    return traduzido === chave ? (mudanca.label || mudanca.field) : traduzido;
}

// ENUM_ASSIM_NAO_SE_LE → "Enum assim nao se le". Enum que ainda não mapeamos
// aparece legível em vez de gritando em caixa alta — mesmo critério do fallback
// de rótulo de campo no core. Continua em inglês, e é de propósito: esconder o
// valor seria pior, e traduzir sem confirmar seria chute.
function humanizarEnum(valor) {
    const s = String(valor).replace(/_/g, ' ').trim().toLowerCase();
    return s.charAt(0).toUpperCase() + s.slice(1);
}

// ── ATRIBUTOS DE CATEGORIA (estacionamento, eletroposto) ────────────────────
//
// O diff de `categoryAttributes` mostrava CÓDIGO: `PARKING_LOT.parkingType`
// com `PUBLIC → PRIVATE`, `R_61_TO_100 → R_1_TO_10`. Não era regressão — o
// caminho da folha nunca traduziu —, só ficou visível quando apareceu um
// pedido que altera atributo, que é raro: 22 de 4.898 pedidos (0,45%) medidos
// nos 13 países de validação.
//
// As strings são as OFICIAIS do WME, colhidas da página do editor em cada
// idioma (gotcha #47: nunca a tradução da minha língua). Só existem duas
// categorias com atributo — `PARKING_LOT` e `CHARGING_STATION` —, e isso se
// manteve nos 13 países.
//
// A chave é `categoria.campo[.VALOR]`, nunca `campo.VALOR`: `costType` existe
// nas duas com conjuntos DIFERENTES, e `PUBLIC`/`RESTRICTED` aparecem tanto em
// `parkingType` quanto em `accessType`. Achatar por campo traduziria errado.
const ATTR_PREFIXO = 'card.attr.';

// `PARKING_LOT.parkingType` → "Tipo principal". Sem string oficial, devolve o
// caminho CRU — que é o identificador que casa com o WME, como antes.
function rotuloDeAtributo(caminho) {
    const chave = ATTR_PREFIXO + caminho;
    const s = t(chave);
    return s === chave ? null : s;   // null = sem string oficial, usa o caminho cru
}

// `PARKING_LOT.parkingType` + `PUBLIC` → "Público".
//
// Valor sem string oficial cai no `humanizarEnum` — "Membership card" em vez
// de `MEMBERSHIP_CARD`. São 7 dos 46 valores observados, e eles existem no dado
// mas não na tabela do WME.
//
// **Texto livre não passa por aqui**: `network` traz nome de rede (`Belib'`,
// `ChargeGuru`) e `locationInVenue` traz frase inteira. Eles têm rótulo na
// tabela e NÃO têm valores, então o `t()` devolve a chave e o valor sai cru —
// que é o certo. Humanizar ali corromperia marca própria, exatamente como já
// corrompeu apelido e ID do Google (gotcha #39).
// Campos cujo VALOR é texto livre, e que por isso nunca passam pela tabela nem
// pelo `humanizarEnum`. A lista é por CAMPO, não pela forma do valor — e essa
// é a lição, porque a forma engana: `network` traz marca em CAIXA ALTA
// (`DRIVECO`, `ESB`, `JOINON`, `ZSE`, `ETECNIC`, medidos em 13 países), que
// passa por qualquer regex de enum e sai humanizada como "Driveco", "Esb",
// "Zse". `ESB` e `ZSE` são siglas: humanizar não é feio, é ERRADO.
//
// Terceira vez que este projeto tropeça no mesmo lugar (gotcha #39): já
// corrompeu apelido e ID do Google. A regra que sobrevive é "o campo diz se o
// valor é enumerável", nunca "o valor parece um enum".
const ATTR_TEXTO_LIVRE = new Set([
    'CHARGING_STATION.network',
    'CHARGING_STATION.locationInVenue',
    'CHARGING_STATION.chargingPorts',
]);

function valorDeAtributo(caminho, valor) {
    if (valor === null || valor === undefined || typeof valor === 'object') return null;
    if (ATTR_TEXTO_LIVRE.has(caminho)) return null;
    const bruto = String(valor);
    // SÓ CAIXA ALTA passa. Isto faz dois trabalhos: barra o texto livre e barra
    // o booleano (`"true"` é minúsculo), que já sai como Sim/Não pelo
    // `valorDoDiff`. Havia um `typeof valor === 'boolean'` explícito aqui e ele
    // era código morto — a sabotagem que o removia passava limpa, porque a
    // regex já cobria o caso.
    if (!/^[A-Z][A-Z0-9_]*$/.test(bruto)) return null;
    const chave = ATTR_PREFIXO + caminho + '.' + bruto;
    const s = t(chave);
    return s === chave ? humanizarEnum(bruto) : s;
}

// Traduz enum do Waze por prefixo de chave, humanizando o que não conhecemos.
function rotuloDeEnum(prefixo, valor) {
    if (!valor) return '';
    const chave = prefixo + valor;
    const traduzido = t(chave);
    return traduzido === chave ? humanizarEnum(valor) : traduzido;
}

// Pré-carrega a imagem do próximo place da fila — mata o flash branco no swipe.
// O que este card mostra PRIMEIRO: o mapa ou a foto?
//
// FONTE ÚNICA da decisão. Ela vale em dois lugares — o carrossel, que monta os
// slides, e o prefetch, que aquece o próximo. Duplicada, elas divergem e o
// prefetch passa a aquecer o ativo errado sem ninguém notar, que é exatamente
// o defeito que esta função veio consertar.
//
// O mapa vem primeiro quando é a evidência principal: não há foto pra olhar, ou
// o pedido mexe em POSIÇÃO (e aí a coordenada crua não se julga — foi por isso
// que o mapa existe).
function mapaVemPrimeiro(place) {
    if (!place || !place.mapa) return false;
    const nFotos = (place.imageUrls && place.imageUrls.length)
        || (place.imageUrl ? 1 : 0);
    const eEspacial = (place.changes || [])
        .some((c) => c.field === 'geometry' || c.field === 'entryExitPoints');
    return nFotos === 0 || eEspacial;
}

// QUAL FOTO o card mostra — FONTE ÚNICA, pelo mesmo motivo do `mapaVemPrimeiro`
// logo acima. Num pedido de FOTO o carrossel não abre na primeira da lista: abre
// na que está EM DECISÃO — a denunciada (`flagEntityID`, que bate exatamente com
// `venue.images[].id`, confirmado no HAR do "Ponto de Mergulho") ou a proposta
// (`updateRequestID`). Sem esse vínculo o editor via 4 fotos e nenhuma pista de
// qual era o pedido.
//
// Vale em TRÊS lugares: o carrossel, o aquecimento do próximo card e a varredura
// do offline. Até v2026.09.22-01 os dois últimos pegavam `imageUrls[0]` por
// conta própria, e MEDIDO na fila do owner a foto em decisão NÃO é a primeira em
// 13 de 76 pedidos de foto: a varredura guardava a foto errada, e sem rede o card
// abria justamente na que ninguém guardou — "a foto precisa de sinal", com ✕ e ✓
// travados, num pedido que o recurso tinha prometido resolver.
function fotosDoCard(place) {
    const urls = place.imageUrls && place.imageUrls.length > 0
        ? place.imageUrls
        : (place.imageUrl ? [place.imageUrl] : []);
    const idxPorId = (id) => (id ? urls.findIndex((u) => u.indexOf(id) !== -1) : -1);
    const denunciadaIdx = idxPorId(place.flagEntityID);
    const eDenuncia = denunciadaIdx >= 0;
    // `_urFoto`: o pedido de TREINO tem o `updateRequestID` trocado pelo inerte, e
    // é por ele que a foto em decisão é achada — sem isto o card de foto nova do
    // treino abria na foto ANTIGA, sem ✨ (ver `Treino.neutralizar`).
    const emDecisao = eDenuncia ? denunciadaIdx : idxPorId(place._urFoto || place.updateRequestID);
    return { urls, eDenuncia, emDecisao, inicial: emDecisao >= 0 ? emDecisao : 0 };
}

// Aquece o que o PRÓXIMO card vai mostrar primeiro — não "a foto dele".
//
// Antes isto era `imageUrls[0]`, sempre. Medido em 4188 cards reais de 12
// países: em 23% o primeiro slide é o MAPA, e em 20% não há foto nenhuma —
// nesses o prefetch não aquecia NADA e o editor via a caixa cinza esperando o
// tile. Nos outros ~3%, ele baixava 56 KB de uma foto que não aparece primeiro.
//
// Não é gastar mais rede: é gastar no que a pessoa vai ver. Os tiles do próximo
// card seriam baixados de qualquer forma quando ele chegasse — a fila é
// sequencial, então o "próximo" é literalmente o próximo que ela vê.

// Rede em que aquecer mais ATRAPALHA. Prefetch disputa banda com o card que
// está na tela: numa 2G ou com economia de dados ligada, encher o cano com o
// que talvez nem seja visto deixa mais lento justamente o que a pessoa está
// olhando agora. `navigator.connection` não existe no Safari — sem ele a
// resposta é "não é econômica", que é o comportamento de antes.
function redeEconomica() {
    const c = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (!c) return false;
    if (c.saveData) return true;
    return /(^|-)2g$/i.test(c.effectiveType || '');
}

// Uma imagem aquecida NUNCA compete com o card na tela: `fetchPriority: low`
// põe o pedido atrás do que está sendo pintado. Onde o navegador não suporta,
// atribuir a propriedade é inócuo — degrada pro comportamento de antes.
function aquecer(url) {
    if (!url) return;
    const im = new Image();
    im.fetchPriority = 'low';
    im.decoding = 'async';
    im.src = url;
}

// Os tiles que o mini-mapa DESTE card vai pedir. Usa a caixa do card atual: o
// próximo ainda não existe e o layout é o mesmo. Errar por alguns pixels só
// muda o zoom em casos de fronteira, e aí o tile aquecido é vizinho do certo.
function tilesDoCard(place, w, h) {
    if (!place || !place.mapa || !window.mapaMontar) return [];
    const r = mapaMontar(pontosDoMapa(place).map((p) => p.ll), w, h, API.getRegion());
    return r ? r.tiles.map((t) => t.url) : [];
}

// Aquece o que o próximo card mostra PRIMEIRO — não "a foto dele".
//
// Antes isto era `imageUrls[0]`, sempre. Medido em 4188 cards reais de 12
// países: em 23% o primeiro slide é o MAPA, e em 20% não há foto nenhuma —
// nesses o prefetch não aquecia NADA e o editor via a caixa cinza esperando o
// tile. Nos outros ~3%, baixava uma foto que não aparece primeiro.
function aquecerPrimeiroSlide(place, w, h) {
    if (!place) return;
    if (mapaVemPrimeiro(place)) { for (const u of tilesDoCard(place, w, h)) aquecer(u); return; }
    // A foto em que o carrossel ABRE — num pedido de foto, a que está em decisão.
    const f = fotosDoCard(place);
    aquecer(urlDaFoto(f.urls[f.inicial]));
}

// O RESTO do card: as outras fotos e, se o mapa não era o primeiro slide, os
// tiles dele. Serve quem PAROU e começou a explorar o carrossel — por isso vai
// só pro card seguinte, e com teto.
//
// Também passa pelo `urlDaFoto`: com o offline ligado o carrossel pede a foto
// COM o sufixo, e aquecer a URL crua era baixar uma cópia que ninguém ia pedir.
function aquecerRestoDoCard(place, w, h) {
    if (!place) return;
    const f = fotosDoCard(place);
    const mapaPrimeiro = mapaVemPrimeiro(place);
    // Com a foto no 1º slide, a INICIAL já foi aquecida — e o teto conta com ela.
    const resto = mapaPrimeiro ? f.urls : f.urls.filter((_, i) => i !== f.inicial);
    const teto = mapaPrimeiro ? PREFETCH_TETO_FOTOS : PREFETCH_TETO_FOTOS - 1;
    for (const u of resto.slice(0, teto)) aquecer(urlDaFoto(u));
    if (!mapaPrimeiro) for (const u of tilesDoCard(place, w, h)) aquecer(u);
}

function prefetchNextImage() {
    if (!AppState.queue[1]) return;
    const cx = cardDaFrente() && cardDaFrente().querySelector('.card-photo');
    const w = (cx && cx.clientWidth) || 400;
    const h = (cx && cx.clientHeight) || 240;
    const economica = redeEconomica();

    // PROFUNDIDADE: o 1º slide dos próximos N (hoje 1, ver a constante).
    const fundo = economica ? 1 : PREFETCH_PROFUNDIDADE;
    for (let i = 1; i <= fundo; i++) {
        if (!AppState.queue[i]) break;
        aquecerPrimeiroSlide(AppState.queue[i], w, h);
    }
    // LARGURA: só o card seguinte, e nunca em rede econômica.
    if (!economica) aquecerRestoDoCard(AppState.queue[1], w, h);
}

// Texto de `data-i18n` que muda com o ESTADO: troca a chave junto, senão o
// `applyI18n` da troca de idioma devolve o texto da chave antiga.
function trocarTextoI18n(el, chave) {
    if (!el) return;
    el.setAttribute('data-i18n', chave);
    el.textContent = t(chave);
}

// Houve trabalho de verdade NESTA fila (zera no `resetQueue`)? É o critério da
// festa do "Tudo limpo!" e da frase dele.
let tratouNestaFila = false;
// A recusa automática AGIU nesta fila (zera no `resetQueue`): ela rejeitou, em
// nome da pessoa, pedidos que estavam aqui. Conta como trabalho feito pra FRASE
// do "Tudo limpo!" — com a fila só de um autor marcado, a abertura terminava em
// "Nenhum pedido pendente com estes filtros. Confira o país e a região", logo
// depois de o app rejeitar 4 pedidos ali (MEDIDO, s39; auditoria de 2026-10-02,
// R6-2-11). A festa e a conquista seguem só com o `tratouNestaFila`: contar a
// recusa nelas é decisão do owner, em aberto.
let recusaAutomaticaNestaFila = false;
// Quantos pedidos foram PULADOS nesta fila, pelo placar (o Desfazer do ↑ já o
// desconta, e o treino tem placar próprio): a fila que termina com pulados não
// está "limpa" — eles seguem pendentes, e só voltam ao "Verificar novamente".
// Dizia "Tudo limpo!" e "confira o país e a região" pra quem tinha pulado tudo
// (auditoria de 2026-09-25).
let puladosNoInicioDaFila = 0;
function puladosNestaFila() {
    return Math.max(0, (AppState.stats.skipped || 0) - puladosNoInicioDaFila);
}

// A fila desta tela terminou LIMPA pelo trabalho do editor: tratou algo nela e
// não sobrou pulado. É a condição da FESTA do painel vazio — o confete e o
// convite de instalar, que mora no "Tudo limpo!" e só ali (o único momento em
// que a pessoa TERMINOU algo). O convite aparecia em todo painel vazio: no
// "Confira o país e a região" de quem não tratou nada, disputando com a
// instrução de conferir os filtros, e no "Fim da fila" com pulados (R6-7-11,
// auditoria de 2026-10-01). Uma função pros dois, pra não voltarem a divergir.
function filaTerminouLimpa() {
    return tratouNestaFila && puladosNestaFila() === 0;
}

// A fila desta tela terminou LIMPA pelo trabalho do editor, e esse trabalho
// está CONFIRMADO? É a condição da conquista "Tudo limpo", e ela é mais estreita
// que a do confete por duas razões (auditoria de 2026-09-25):
//   · com PULADO a fila não está limpa: eles seguem pendentes (a tela já dizia
//     "Fim da fila", e mesmo assim soltava confete e dava a conquista — H9);
//   · o ÚLTIMO swipe esvazia a fila e o painel aparece DENTRO da janela do
//     Desfazer: dar a conquista ali deixava ela gravada depois de o Desfazer
//     devolver o card (C13). Com a ação ainda no ar, quem confirma é a resposta
//     (`registrarAcaoConfirmada`, que pergunta de novo com `confirmando`).
// `confirmando` = quem pergunta é a confirmação de uma ação, que ainda conta
// como em voo até o executor terminar.
// `place` = o pedido cuja confirmação pergunta: ele está "em andamento" até o
// fim do envio, e não conta contra si mesmo.
function filaZeradaConfirmada({ confirmando = false, place = null } = {}) {
    // A fila na tela é a do TREINO: "zerada" seria a de exemplos. A real, que a
    // decisão confirmada com o treino aberto pode ter esvaziado, é julgada quando
    // o treino sai — o `sair()` desenha o painel dela (`showNoPlaces`), que
    // pergunta de novo (R6-7-3).
    if (typeof Treino !== 'undefined' && Treino && Treino.ativo) return false;
    if (!tratouNestaFila || AppState.loadError || AppState.currentPlace) return false;
    if ((AppState.queue || []).length > 0) return false;
    if (AppState.pendingAction) return false;
    if (!confirmando && AppState.inFlightActions > 0) return false;
    if (puladosNestaFila() > 0) return false;
    // Nada do que a pessoa decidiu pode ainda VOLTAR: o pedido cuja decisão o
    // Waze recusa volta pra fila (`devolverPedidoRecusado`). Outro pedido no ar
    // (a confirmação deste chegou primeiro) ou esperando na fila de saída pode
    // ser esse — e a conquista saía antes de ele voltar.
    const este = chaveDoPedido(place);
    for (const k of pedidosEmAndamento) if (k !== este) return false;
    if (carregarFilaDeSaida().some((it) => chaveDoPedido(it) !== este)) return false;
    const noMore = document.getElementById('noMoreCards');
    return !!noMore && !noMore.classList.contains('hidden');
}

function showNoPlaces() {
    // O painel de fila vazia tem DOIS significados e a distinção é a flag —
    // foi ela que faltou e fez o app dizer "Tudo limpo!" sobre 217 pedidos.
    // Com os PULADOS e se houve trabalho NESTA fila: são eles que decidem se a
    // tela diz "Tudo limpo!", "Fim da fila" ou "nada nesta fila" — e o diário
    // chamava as três da mesma coisa (auditoria de 2026-09-26).
    dfato('tela.vazia', { loadError: AppState.loadError, hasMore: AppState.hasMore,
                          serverTotal: AppState.serverTotal, pulados: puladosNestaFila(),
                          tratou: tratouNestaFila });
    if (AppState.loadError) dlogCapturarAuto('falhaAoCarregar');
    marcarTelaPronta();   // fila vazia ou erro: não vem card, mas a tela está pronta
    AppState.currentPlace = null;
    // A frente ficou vazia: o pedido que voltar a ela (o Desfazer do último) é
    // anunciado de novo (ver `pedidoAnunciado`).
    pedidoAnunciado = null;
    removeCurrentCardEl();
    // A barra "Primeiro os de…" é do CARD, e sai com ele: o último pedido do
    // autor em foco era o fim da fila, e ela ficava por cima do "Tudo limpo!"
    // dizendo "Primeiro os de X · 1 de 1" — com o foco do teclado nela, se ele
    // estava lá (MEDIDO pela seta nos dois motores, e pelo toque; R13-2-05).
    // Quem a tira é a regra de sempre (`renderFocoAutor`, sem card), e o foco
    // no autor fica, pro Desfazer que devolve esse pedido.
    renderFocoAutor();
    showLoading(false);
    const noMore = document.getElementById('noMoreCards');
    const errEl = document.getElementById('loadErrorState');
    if (AppState.loadError && errEl) {
        // Falha de rede/servidor: NÃO mostra "Tudo limpo!" (o editor acharia que
        // zerou o backlog). Mostra estado de erro com "Tentar de novo".
        noMore.classList.add('hidden');
        errEl.classList.remove('hidden');
        // SEM CONEXÃO é coisa que o app SABE — `onLine === false` é confiável
        // nessa direção (o inverso não é: portal cativo diz true e mente). Então
        // ali ela AFIRMA em vez de aconselhar "verifique sua conexão", e promete
        // o que o gatilho do `online` cumpre. O botão FICA, decisão do owner
        // olhando os mockups: o evento `online` às vezes não dispara, e aí ele é
        // a única saída manual — mesma razão pela qual o `callWithRetry` não
        // confia no `true`.
        const semRede = navigator.onLine === false;
        // Troca a CHAVE, não só o texto: o `applyI18n` reescreve todo
        // `data-i18n` ao trocar de idioma, e com o texto escrito por cima a tela
        // de "sem conexão" voltava a dizer "Falha ao carregar".
        trocarTextoI18n(errEl.querySelector('h3'), semRede ? 'states.error.titleOffline' : 'states.error.title');
        trocarTextoI18n(errEl.querySelector('p'), semRede ? 'states.error.bodyOffline' : 'states.error.body');
    } else {
        if (errEl) errEl.classList.add('hidden');
        // O painel APARECE agora (ou já estava na tela e só é desenhado de
        // novo)? Lido antes de mostrá-lo: é o que decide o anúncio, abaixo.
        const jaNaTela = !noMore.classList.contains('hidden');
        noMore.classList.remove('hidden');
        // O convite de instalar segue a MESMA condição do confete, logo abaixo
        // (`filaTerminouLimpa`, R6-7-11).
        atualizarConviteInstalar();
        // Com o convite embaixo, o painel pode não caber (Fold, tela deitada,
        // fonte grande do sistema). Aí ele rola — e área que rola sem dizer que
        // rola é área que ninguém rola (gotcha #29). Uma vez só por elemento:
        // o próprio marcarBordaRolagem reavalia via ResizeObserver.
        if (!noMore.dataset.bordaRolagem) {
            marcarBordaRolagem(noMore);
            noMore.dataset.bordaRolagem = '1';
        }
        // Festa só quando o editor de fato zerou algo NESTA fila. Abrir o app
        // numa fila já vazia não é conquista — confete ali seria ruído. Era o
        // placar VITALÍCIO (`AppState.stats`, gravado), então quem já tinha
        // tratado alguma coisa na vida ganhava confete e a conquista "Tudo
        // limpo" só por abrir o app com a fila vazia.
        const tratou = tratouNestaFila;
        const pulados = puladosNestaFila();
        // E a frase: "Você processou todos os pedidos" é mentira pra quem não
        // processou nada — é o que via quem abria o app num país onde não edita.
        // Com PULADOS, nem "tudo limpo" nem "confira o país": eles seguem
        // pendentes e o botão logo abaixo os traz de volta. A recusa automática
        // que agiu aqui conta como trabalho feito NA FRASE (R6-2-11): o lugar está
        // certo, e o app acabou de rejeitar os pedidos dele em nome da pessoa.
        const titulo = pulados > 0 ? 'states.empty.titlePulados' : 'states.empty.title';
        trocarTextoI18n(noMore.querySelector('h3[data-i18n^="states.empty.title"]'), titulo);
        trocarTextoI18n(noMore.querySelector('p[data-i18n^="states.empty.body"]'),
            pulados > 0 ? 'states.empty.bodyPulados'
                : tratou || recusaAutomaticaNestaFila ? 'states.empty.body' : 'states.empty.bodyNada');
        // O FIM da fila é dito a quem usa leitor de tela, como o card novo: a
        // região viva do card dizia "Novo pedido" a cada card e NADA quando a
        // decisão esvaziava a fila — o painel não é região viva (MEDIDO nos dois
        // motores; auditoria de 2026-10-02, R7-2-06). O título do painel, quando
        // ele APARECE: desenhado de novo com ele já na tela, não repete. A falha
        // ao carregar não passa por aqui: o painel dela é `role="alert"` e se
        // anuncia sozinho — dito também aqui, seria dito duas vezes.
        const anuncio = document.getElementById('cardLiveRegion');
        if (anuncio && !jaNaTela) anuncio.textContent = t(titulo);
        noMore.classList.remove('celebrate');
        // Festa só com a fila LIMPA: com pulado a tela diz "Fim da fila" (eles
        // seguem pendentes), e confete ali contradizia o próprio título.
        if (filaTerminouLimpa()) {
            // Reflow forçado: sem isso o browser junta remove+add num só estilo
            // computado e a animação não reinicia na segunda vez que a fila zera.
            void noMore.offsetWidth;
            noMore.classList.add('celebrate');
            // A conquista, só com o trabalho CONFIRMADO (`filaZeradaConfirmada`).
            // A pergunta vai pro fim da tarefa: o gesto que esvaziou a fila
            // chega aqui pelo `advanceQueue` e só DEPOIS agenda a ação (e abre a
            // janela do Desfazer) — perguntada agora, a ação ainda nem existe.
            queueMicrotask(() => {
                if (filaZeradaConfirmada()) checarConquistas({ filaZerada: true });
            });
        }
    }
    // O foco prometido ao teclado (o Enter no ✕ ↑ ✓ do último card, no
    // "Verificar novamente", no "Rejeitar os N"): o botão sumiu e não vem card —
    // ele vai ao botão do painel (`aplicarFocoDoTeclado`, R7-2-06). Depois da
    // tarefa, como no card que nasce: o gesto que esvaziou a fila chega aqui pelo
    // `advanceQueue` e só DEPOIS abre a janela do Desfazer — e, com ela correndo,
    // o foco ESPERA (a tecla z devolve o card, e o foco vai ao botão dele).
    if (focoDoTeclado) queueMicrotask(aplicarFocoDoTeclado);
}

// A abreviação OFICIAL do idioma — quando ela for inequívoca.
//
// Pedido do owner: "não prefere usar as abreviações oficiais de cada idioma?".
// Prefiro, e o CLDR as tem (`style: 'short'`). MEDIDO na fila real dele, onde
// 78% dos cards são horas e 22% dias, a média ponderada da largura do rótulo
// cai 31% em português (83 → 57px), 19% em inglês, 30% em espanhol e 37% em
// francês. Num card em que cada pixel acima da foto é pixel a menos de foto,
// isso não é enfeite.
//
// MAS o "short" oficial do ESPANHOL reproduz exatamente o defeito que este
// arquivo acabou de consertar: `hace 9 m` (meses) é prefixo de `hace 9 min`
// (minutos). O guard de `test/idade.test.mjs` pega isso sozinho, com a
// mensagem certa — foi assim que eu descobri, tentando ligar o `short` pra
// todo mundo de uma vez.
//
// Então a escolha é POR IDIOMA e por MEDIÇÃO, não por gosto: usa a abreviação
// oficial se ela passar na mesma invariante que o teste cobra (nenhuma unidade
// pode ser PREFIXO de outra), e cai pro extenso quando não passar. Duas
// consequências boas: o espanhol volta pro curto sozinho no dia em que o CLDR
// consertar, e a regra que decide aqui é a MESMA que o teste enforca — não há
// duas versões dela pra divergirem.
//
// Curiosidade que confirma a régua: em português o próprio "short" do CLDR já
// escreve "dias" e "meses" por extenso, e só abrevia `h` e `min.` — não existe
// forma curta segura pra mês em pt. O CLDR chegou à mesma conclusão sozinho.
const ESTILO_DA_IDADE = new Map();
const UNIDADES_DA_IDADE = ['minute', 'hour', 'day', 'month', 'year'];

// A TIPOGRAFIA da unidade é NORMA DE CADA IDIOMA, e elas DIVERGEM entre si —
// não é gosto, e não dá pra escolher uma e aplicar em todas. Pesquisado nas
// fontes normativas depois de o owner apontar que "há 12 h" está errado em
// português (e ele está):
//
//   pt-BR  ABNT NBR 5892: `15h`, `12h30min`, `20h45min20s` — o símbolo COLA no
//          número, sem espaço e sem ponto. E minuto é `min`, nunca `m` (que é
//          metro). O CLDR emite "há 12 h" e "há 12 min.": erra os DOIS.
//   es     RAE: "12 h" com espaço OBRIGATÓRIO, e ela diz explicitamente que
//          "12h" está errado. O CLDR acerta.
//   fr     Imprimerie nationale: "12 h", com espaço INSECÁVEL — e o CLDR emite
//          U+00A0 aqui (espaço comum nos outros), ou seja ele conhece a
//          diferença; o dado do pt-BR é que não segue a ABNT.
//   en     AP/Chicago: "12 hr". O CLDR acerta.
//
// Só o PORTUGUÊS precisa de conserto, e ele é aplicado sobre as PARTES
// (`formatToParts`), nunca por regex no texto pronto: mexer com regex em saída
// localizada é como se corrompe acento e plural de idioma que ninguém no time
// lê (o mesmo motivo do gotcha #39 — quem diz o que o valor é é a ESTRUTURA,
// não a aparência dele).
//
// E cola só o que é SÍMBOLO, nunca palavra: `12h` e `12min` sim, `12 dias` e
// `12 meses` não — ninguém escreve "12dias". A distinção não é uma lista de
// unidades cravada aqui (isso envelhece quando o CLDR mudar): símbolo é o
// token curto que é PREFIXO ESTRITO da forma por extenso — `h` ⊂ `horas`,
// `min` ⊂ `minutos`, enquanto `dias` == `dias` e `meses` == `meses` não são.
const COLA_O_SIMBOLO = new Set(['pt']);   // ABNT NBR 5892

function idadeComNormaLocal(loc, estilo, n, unidade) {
    const rtf = new Intl.RelativeTimeFormat(loc, { numeric: 'auto', style: estilo });
    const idioma = String(loc || '').slice(0, 2).toLowerCase();
    if (estilo !== 'short' || !COLA_O_SIMBOLO.has(idioma)) return rtf.format(n, unidade);
    try {
        const partes = rtf.formatToParts(n, unidade);
        const i = partes.findIndex((p) => p.type === 'integer');
        if (i < 0 || !partes[i + 1] || partes[i + 1].type !== 'literal') return rtf.format(n, unidade);
        const depois = partes[i + 1].value;
        const token = depois.trim().replace(/\.$/, '');
        // É símbolo? Compara com a forma POR EXTENSO da MESMA unidade — e o
        // token é o literal que vem DEPOIS do número, não o primeiro da lista.
        // (Primeira versão pegava o primeiro literal com conteúdo, que é o
        // prefixo "há " — comparava `min` com `há`, nunca casava, e o `min.`
        // ficava intocado. Só apareceu porque eu OLHEI a saída em vez de
        // conferir o código.)
        const pLongas = new Intl.RelativeTimeFormat(loc, { numeric: 'auto', style: 'long' })
            .formatToParts(n, unidade);
        const j = pLongas.findIndex((p) => p.type === 'integer');
        const palavra = j >= 0 && pLongas[j + 1] ? pLongas[j + 1].value.trim() : '';
        const ehSimbolo = token.length > 0 && token.length < palavra.length && palavra.startsWith(token);
        if (!ehSimbolo) return rtf.format(n, unidade);
        // Cola: tira o espaço à esquerda do token e o ponto de abreviatura
        // (símbolo do SI não leva ponto — `min`, não `min.`).
        partes[i + 1] = { ...partes[i + 1], value: depois.replace(/^\s+/, '').replace(/\.(\s|$)/, '$1') };
        return partes.map((x) => x.value).join('');
    } catch (e) {
        return rtf.format(n, unidade);
    }
}

function estiloDaIdade(loc) {
    if (ESTILO_DA_IDADE.has(loc)) return ESTILO_DA_IDADE.get(loc);
    let estilo = 'long';
    try {
        const curto = new Intl.RelativeTimeFormat(loc, { numeric: 'auto', style: 'short' });
        // n = 9: qualquer n >= 2 serve (em n = 1 vários idiomas usam palavra
        // própria — "ontem", "mês passado" — e a comparação perde o sentido).
        const saidas = UNIDADES_DA_IDADE.map((u) => curto.format(-9, u));
        const ambiguo = saidas.some((a) => saidas.some((b) => a !== b && b.startsWith(a)));
        if (!ambiguo) estilo = 'short';
    } catch (e) { /* sem Intl ou locale estranho: o extenso nunca é ambíguo */ }
    ESTILO_DA_IDADE.set(loc, estilo);
    return estilo;
}

// A IDADE DO PEDIDO, e ela já MENTIU pro owner — três vezes, com relato.
//
// Isto usava chaves abreviadas do dicionário, e em português `time.months` era
// `há {n}m` enquanto `time.minutes` é `há {n}min`. Um pedido de NOVE MESES
// renderizava **"há 9m"**, que todo falante de português lê como nove MINUTOS.
// Ao lado, na mesma linha, o rótulo de tipo diz "Novo local". A tela inteira
// afirmava "local novo, de 9 minutos atrás" sobre um pedido de 2025-11-27 — e
// foi exatamente assim que o owner relatou: a mesma solicitação "nova"
// entrando toda vez que ele abre o app. Ele leu certo o que o app escreveu.
// A mesma colisão existia em espanhol (`hace {n}m` × `hace {n}min`); inglês
// (`mo`) e francês (` mois`) escapavam — o defeito era de DUAS línguas em
// quatro, e o owner usa uma delas.
//
// E a ordenação faz dos dois um par: MEDIDO na fila real dele, o rótulo de
// meses cabe a 1 card em 370 (0,3% — 78% são horas, 22% dias). Mas com "mais
// antigos primeiro" o card mais velho é POR DEFINIÇÃO o mais provável de cair
// na faixa de meses, então o único rótulo ambíguo da fila era garantidamente o
// PRIMEIRO da tela, toda vez que ele abria o app. Cada recurso certo sozinho.
//
// Havia um segundo buraco, este aritmético e nas QUATRO línguas: entre 360 e
// 364 dias, `months` dava 12 (fora da faixa) e `years` dava `floor(360/365)` =
// 0 — a tela mostrava **"há 0a"**. Janela de 5 dias, ninguém relatou porque é
// rara, mesmo defeito de fundo: conta à mão que produz rótulo falso.
//
// O conserto NÃO é escolher abreviatura melhor: é usar o mecanismo que este
// app JÁ usa pra idade de FOTO (`idadeDaFoto`), com o motivo já escrito lá —
// `Intl.RelativeTimeFormat` resolve plural por idioma sozinho, e o projeto não
// tem ICU. Duas mecânicas para o mesmo conceito é como elas divergem: o MESMO
// card mostrava "há 9 meses" na foto e "há 9m" no pedido. Some com as 6 chaves
// `time.*` × 4 línguas, e o ano acima de 365 dias espelha o `idadeDaFoto` —
// "2025" decide melhor que "ano passado" num pedido que se vai julgar.
//
// MEDIDO antes de trocar, porque a string mais larga quase nunca está no
// idioma em que se desenvolve (gotcha #25): 3 aparelhos × 4 idiomas × 5 faixas
// = 60 combinações, ZERO estouro e ZERO quebra de linha; o pior caso (francês
// no Galaxy Fold, "il y a 28 minutes") ainda deixa 88px de folga.
function formatRelativeTime(ts) {
    if (!ts || typeof ts !== 'number' || ts <= 0) return null;
    const diff = Date.now() - ts;
    // Relógio torto ou data no futuro: "agora" é o menos errado — não se
    // inventa idade negativa nem se esconde o pedido.
    const loc = i18nLocale();
    try {
        const estilo = estiloDaIdade(loc);
        const f = (n, u) => idadeComNormaLocal(loc, estilo, n, u);
        if (diff < 0) return f(0, 'second');
        const sec = Math.floor(diff / 1000);
        if (sec < 60) return f(0, 'second');
        const min = Math.floor(sec / 60);
        if (min < 60) return f(-min, 'minute');
        const hr = Math.floor(min / 60);
        if (hr < 24) return f(-hr, 'hour');
        const days = Math.floor(hr / 24);
        if (days < 30) return f(-days, 'day');
        // `< 365` e não `meses < 12`: era daqui que saía o "há 0a".
        if (days < 365) return f(-Math.round(days / 30), 'month');
        return new Date(ts).toLocaleDateString(loc, { year: 'numeric' });
    } catch (e) {
        // Sem Intl (não deve acontecer no piso do app), a data crua ainda
        // responde a pergunta — e nunca é ambígua.
        try { return new Date(ts).toLocaleDateString(loc); } catch (e2) { return null; }
    }
}

// ── Mensagem de erro que veio do servidor ─────────────────────────────────
// O backend manda CHAVE (`errorKey`) + `errorVars`; a frase em `error` é só o
// último recurso. Antes daqui o padrão era `result.error || t('...')`, e o `||`
// fazia a string PORTUGUESA do servidor GANHAR da tradução: quem usava o app em
// inglês, espanhol ou francês lia português em todo erro de sessão, cookie,
// rede ou race — e a tradução ao lado só entrava se o servidor não dissesse
// nada. Era o buraco de i18n mais fundo do app, porque nenhuma auditoria de
// dicionário enxerga string que chega pela rede.
//
// A frase crua continua no fim da cadeia de propósito: o service worker é
// cache-first pra assets, então por alguns dias após um deploy existe cliente
// com dicionário velho que não conhece a chave nova. Português é ruim; chave
// crua na tela ("srv.err.cookieFormat") é pior.
function msgDoServidor(result, textoFallback) {
    if (result && result.errorKey) {
        const traduzido = t(result.errorKey, result.errorVars || undefined);
        if (traduzido !== result.errorKey) return traduzido;
    }
    return (result && result.error) || textoFallback;
}

// CONTAGEM SAI CRUA — decisão do owner (2026-09-15): "não vamos entrar nessa
// brincadeira de ponto e vírgula; número cru é super portável para qualquer
// idioma". Vale pro placar, pras linhas do Histórico, pro cartão da patente,
// pras estatísticas do perfil e pra imagem do Resumo do mês.
//
// O caso que originou a decisão: o cartão da patente nasceu formatado
// (`3.040`) quatro linhas acima de números que sempre foram crus (`1430`), e o
// app se contradizia na mesma tela. Havia dois consertos possíveis — formatar
// tudo ou não formatar nada — e o owner escolheu o segundo, com o argumento de
// que `1430` se lê igual em qualquer língua e `1.430` não.
//
// O QUE NÃO ENTRA NESSA REGRA, e a diferença não é detalhe:
//   • DATA (`toLocaleDateString`) — não é número.
//   • MEDIDA COM DECIMAL (`1,2 km`, `84,5 m`) — ali o separador é ARITMÉTICA:
//     `1.2` lido por um brasileiro é mil e duzentos. Segue no locale.
// `test/layout.test.mjs` cobra as duas pontas: contagem crua, decimal no locale.

function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// O envio pertence à SESSÃO do gesto, e cada tentativa lê o token de AGORA.
// Entre uma tentativa e a próxima (1,5 s e 3,5 s) a sessão pode cair e outra
// entrar — a extensão renova sozinha, com a conta que estiver no WME, que pode
// ser OUTRA —, e a retentativa de uma decisão de A saía com o token de B
// (auditoria da costura, 2026-09-26, K1). A época da sessão é conferida ANTES
// de cada tentativa, inclusive a primeira: mudou, nada sai, e quem chamou
// recebe `session_changed` (todo chamador já descarta a resposta de outra
// época). Quem chama passa a época do GESTO; sem ela vale a da chamada, que
// basta pras retentativas. `null` desliga a conferência: é o "Sair", que manda
// o token velho EXPLÍCITO e precisa apagá-lo no servidor mesmo depois.
function sessaoTrocou() {
    return { success: false, errorCategory: 'session_changed' };
}

async function callWithRetry(fn, epoca = epocaDaSessao) {
    const outraSessao = () => epoca !== null && epoca !== epocaDaSessao;
    if (outraSessao()) return sessaoTrocou();
    let result = await fn();
    let attempt = 0;
    // SEM REDE não se retenta: as duas tentativas extras são 2 requisições e
    // ~5s de espera (1,5 + 3,5) que já nascem condenadas. Com a fila de saída
    // atrás, a ação não se perde por não insistir — ela sai quando a rede
    // voltar. MEDIDO: ~509 bytes por tentativa, e offline o app fazia 3.
    //
    // O teste é de UMA MÃO só, de propósito: `onLine === false` é confiável
    // pra "não tem rede"; `true` NÃO prova que tem (portal cativo de hotel diz
    // true e mente). Então só o `false` muda o comportamento.
    const semRede = () => navigator.onLine === false;
    while (result && !result.success && result.errorCategory === 'transient'
           && !semRede() && attempt < TRANSIENT_RETRY_ATTEMPTS) {
        const delay = TRANSIENT_RETRY_DELAYS_MS[attempt] || 5000;
        await new Promise(r => setTimeout(r, delay));
        if (outraSessao()) return sessaoTrocou();
        attempt++;
        result = await fn();
    }
    return result;
}

// ── Histórico acumulado (B7): buckets diários em localStorage ────────────────
// Baldes mais velhos que isto são podados. Cobre com folga os recortes que a
// UI mostra (hoje/semana/mês) — e o "Total" continua verdadeiro porque vive
// num acumulador à parte, que sobrevive à poda.
const HISTORY_MAX_DIAS = 400;

// ── A CÓPIA EM MEMÓRIA × O APARELHO (o app aberto em duas abas) ──────────────
// O histórico, as conquistas e os autores moram em MEMÓRIA depois da primeira
// leitura, e cada gravação escreve a estrutura INTEIRA. A outra aba solta a
// cópia dela quando o navegador avisa (o evento `storage`, ver
// `aoGravarEmOutraAba`) — mas o aviso é uma TAREFA, e duas decisões pousando
// juntas, uma em cada aba (a recusa automática, o "Rejeitar os N" ou a fila de
// saída numa, a pessoa decidindo na outra), gravavam uma por cima da outra: o
// Histórico, a reincidência do autor e a "Mão firme" ficavam com UMA
// (auditoria de 2026-10-06, R9-2-03).
//
// Cada cópia lembra o TEXTO do aparelho de onde saiu (ou que acabou de gravar),
// e quem a usa confere antes: mudou, outra aba gravou — relê. Com as abas no
// MESMO processo do navegador (o armazenamento é um só, e o aviso vem depois)
// isto fecha a corrida: MEDIDO no Chromium com um processo só, a reincidência e
// a "Mão firme" perdiam uma decisão em 4 de 4 e passaram a 0 de 4. Com as abas
// em processos SEPARADOS (o padrão do computador) a gravação da outra só chega
// junto com o aviso, 0,3 a 7 ms depois, e o que pousa nesse meio ainda grava
// por cima — nenhuma conferência síncrona vê o que não chegou (MEDIDO: 4 de 5
// no Chromium, 3 de 3 no WebKit). Fechar essa janela exige coordenar a
// gravação entre as abas, e nem a trava do navegador basta: no WebKit a aba
// que pega a trava ainda lê o valor velho (20 de 40).
//
// É uma leitura do texto e uma comparação, sem JSON: o texto que o navegador
// devolve é o mesmo enquanto ninguém grava. MEDIDO no teto das estruturas (88 KB
// de autores, 29 KB de Histórico): 1 a 3 µs pelas duas conferências com a CPU
// 6× mais lenta no Chromium, 11 a 14 µs no WebKit, contra 20 ms e 3 ms do pouso.
// A regra do custo por swipe (a tabela da gravação síncrona) segue: só relê o
// JSON quem achou o aparelho mudado.
//
// Cópia sem texto lembrado (montada fora daqui) vale como está.
const textoDaCopia = new WeakMap();
function copiaEmDia(copia, chave) {
    if (!copia) return false;
    if (!textoDaCopia.has(copia)) return true;
    let agora;
    try { agora = localStorage.getItem(chave); } catch (e) { return true; }
    return agora === textoDaCopia.get(copia);
}
// `texto`: o que o aparelho tinha quando a cópia foi lida. Sem ele, relido do
// aparelho — é o caso de quem ACABOU de gravar: o texto relido, e não o
// escrito, é o que a próxima leitura devolve.
function lembrarTextoDaCopia(copia, chave, texto) {
    if (!copia || typeof copia !== 'object') return;
    if (texto === undefined) {
        try { texto = localStorage.getItem(chave); } catch (e) { return; }
    }
    textoDaCopia.set(copia, texto);
}

function loadHistory() {
    if (copiaEmDia(AppState.history, HISTORY_KEY)) return AppState.history;
    let texto = null;
    try { texto = localStorage.getItem(HISTORY_KEY); } catch (e) { texto = null; }
    let h = {};
    try { h = JSON.parse(texto || '{}') || {}; } catch (e) { h = {}; }
    // Acumulador que sobrevive à poda dos baldes diários. Só inicializa — a
    // soma retroativa do formato antigo saiu junto com os outros resíduos.
    if (!h._total) h._total = { read: 0, rejected: 0 };
    AppState.history = h;
    lembrarTextoDaCopia(h, HISTORY_KEY, texto);
    if (podarHistorico(h)) salvarHistorico(h);
    return h;
}

// Sem isto o objeto cresce um balde por dia PRA SEMPRE — e como o
// recordHistory serializa o objeto inteiro a cada ação confirmada, o custo de
// cada swipe cresceria junto, sem nada em troca.
function podarHistorico(h) {
    const limite = Date.now() - HISTORY_MAX_DIAS * 86400000;
    let podou = false;
    for (const k of Object.keys(h)) {
        if (k === '_total') continue;
        const quando = new Date(k + 'T00:00:00').getTime();
        if (!Number.isFinite(quando) || quando < limite) { delete h[k]; podou = true; }
    }
    return podou;
}

function salvarHistorico(h) {
    try {
        localStorage.setItem(HISTORY_KEY, JSON.stringify(h));
        lembrarTextoDaCopia(h, HISTORY_KEY);
    } catch (e) {}
}
function historyTodayKey() {
    const d = new Date();
    const p = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}
// Registra no histórico persistente. type: 'read' | 'reject'. delta normalmente +1.
// `dia`/`onde` explícitos existem por causa da FILA DE SAÍDA: uma ação feita
// offline pousa quando a rede volta, e sem eles ela cairia no balde do dia do
// POUSO e na região do filtro de AGORA. O trabalho foi feito no dia e no lugar
// do gesto — é isso que o editor reconhece no Histórico e no Resumo do mês.
// Omitidos (todo caminho online), valem hoje e o filtro atual, como sempre.
function recordHistory(type, delta, dia, onde) {
    if (type !== 'read' && type !== 'reject') return;
    // A linha de base das conquistas ANTES de a ação entrar no histórico (ver
    // `garantirLinhaDeBaseDasConquistas`).
    if ((delta || 0) > 0) garantirLinhaDeBaseDasConquistas();
    const h = loadHistory();
    const k = dia || historyTodayKey();
    if (!h[k]) h[k] = { read: 0, rejected: 0 };
    const field = type === 'read' ? 'read' : 'rejected';
    h[k][field] = Math.max(0, (h[k][field] || 0) + (delta || 0));
    h._total[field] = Math.max(0, (h._total[field] || 0) + (delta || 0));
    // ONDE o trabalho foi feito. É o dado que faltava pra "Andarilho"/"Viajante"
    // — e o MESMO que tirou o "onde" do Resumo do mês, que agora pode voltar.
    // É dado SEU (onde você trabalhou), não de terceiro: pode persistir, e sai
    // no logout junto com o resto do histórico.
    // Só o `onde` AUSENTE (o caminho sem gesto) lê o de agora: o `null` do gesto
    // é "o app não sabe onde" (a "Minha área" sem o país, R7-6-05), e lido de
    // novo no pouso valeria o filtro de DEPOIS do gesto (R6-7-4).
    const lugar = onde !== undefined ? onde : ondeAgora();
    if (lugar && (delta || 0) > 0) {
        if (!h[k].onde) h[k].onde = {};
        h[k].onde[lugar] = Math.max(0, (h[k].onde[lugar] || 0) + delta);
    }
    salvarHistorico(h);
    // Todo pouso passa por aqui (card, lote, fila de saída, recusa automática):
    // com o painel do Histórico aberto, ele mostra o que acabou de pousar.
    agendarRedesenhoDoHistorico();
}
// Dias de CALENDÁRIO entre chaves `YYYY-MM-DD`, sem passar por milissegundo
// local: o dia de troca do horário de verão tem 23 ou 25 h, e contar "idade"
// dividindo por 86.400.000 errava por um dia perto da meia-noite (auditoria de
// 2026-09-25). Em UTC, a conta de datas não tem horário de verão.
function diasEntreChaves(a, b) {
    const [ya, ma, da] = String(a).split('-').map(Number), [yb, mb, db] = String(b).split('-').map(Number);
    return Math.round((Date.UTC(yb, mb - 1, db) - Date.UTC(ya, ma - 1, da)) / 86400000);
}
function chaveMaisDias(k, n) {
    const [y, m, d] = String(k).split('-').map(Number);
    return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

function getHistoryStats() {
    const h = loadHistory();
    const tk = historyTodayKey();
    const acc = { today: { read: 0, rejected: 0 }, week: { read: 0, rejected: 0 }, month: { read: 0, rejected: 0 }, total: { read: 0, rejected: 0 } };
    // "Total" sai do acumulador, não da soma dos baldes: os antigos foram
    // podados, e somar só o que sobrou faria o número encolher sozinho.
    acc.total.read = (h._total && h._total.read) || 0;
    acc.total.rejected = (h._total && h._total.rejected) || 0;
    for (const [k, v] of Object.entries(h)) {
        if (k === '_total' || !v) continue;
        const r = v.read || 0, j = v.rejected || 0;
        if (k === tk) { acc.today.read += r; acc.today.rejected += j; }
        const ageDays = diasEntreChaves(k, tk);
        if (ageDays >= 0 && ageDays < 7) { acc.week.read += r; acc.week.rejected += j; }
        if (ageDays >= 0 && ageDays < 30) { acc.month.read += r; acc.month.rejected += j; }
    }
    return acc;
}

// ── o app aberto em DUAS abas ────────────────────────────────────────────────
// O histórico, as conquistas e os autores ficam em MEMÓRIA depois da primeira
// leitura, e cada ação grava a estrutura INTEIRA. Com o app aberto em duas
// abas, cada uma gravava a SUA cópia por cima da outra: MEDIDO, 5 pedidos
// numa aba e 1 na outra deixavam o `_total` em 100/1 em vez de 105/1 — o
// trabalho da primeira sumia, e as conquistas e a reincidência iam junto
// (auditoria de 2026-09-25).
//
// O navegador avisa a OUTRA aba quando esta grava (evento `storage`, que não
// dispara na aba que gravou): ela solta a cópia em memória, e a próxima
// leitura pega o que está no aparelho. Não põe JSON nenhum a mais no swipe —
// que é o que a tabela de custo da gravação por swipe protege —: só relê quem
// foi avisado, e só quando precisar. O aviso é uma TAREFA, e a gravação que
// chega antes dele é pega pela conferência do texto (`copiaEmDia`, R9-2-03).
//
// A SESSÃO que a outra aba tirou do aparelho por último (o `oldValue` do aviso
// do token), ou `null` quando não se sabe. O "Sair" de lá apaga no servidor a
// sessão dela e a guardada (ver `handleLogout`), e esta aba sai junto
// (`aoSairEmOutraAba`) — mas com o app aberto em duas abas da MESMA conta, as
// duas podem ter sessões DIFERENTES: a outra entrou de novo (o ACESSAR do WME,
// os cookies colados) e esta seguiu com a dela. A desta ficava viva no
// servidor, órfã, por até 21 dias (MEDIDO; auditoria de 2026-10-03, R8-1-03).
// É lida no aviso do TOKEN porque o "Sair" pode ser decidido no aviso seguinte,
// o da conta, que não a traz.
let tokenTiradoPorOutraAba = null;
function aoGravarEmOutraAba(ev) {
    // O mapa é montado AQUI, no evento: as chaves das conquistas e dos autores
    // são declaradas mais abaixo neste arquivo.
    const caches = { [HISTORY_KEY]: 'history', [CONQUISTAS_KEY]: 'conquistas', [AUTORES_KEY]: 'autores' };
    const chave = ev ? ev.key : undefined;
    // Um token NOVO no aparelho (outra entrada) não é uma sessão tirada; o
    // armazenamento limpo inteiro (`key` nulo) não diz qual saiu.
    if (chave === null || chave === 'waze_session_token') tokenTiradoPorOutraAba = ev.newValue ? null : (ev.oldValue || null);
    // O MODO DEV mudou noutra aba — desligado ali, ou o "Sair" de lá (que o
    // desliga) —, ou o token saiu, ou o armazenamento foi limpo inteiro.
    if (chave === null || chave === DEVMODE_KEY || chave === 'waze_session_token') aoMudarModoDevEmOutraAba();
    // O "Sair" de lá, e o placar e as preferências, que esta aba guarda na
    // MEMÓRIA (ver a função).
    sincronizarComOutraAba(chave);
    // `key` nulo é a outra aba limpando o armazenamento inteiro.
    if (chave !== null && !Object.prototype.hasOwnProperty.call(caches, chave)) return;
    for (const [k, campo] of Object.entries(caches)) {
        if (chave === null || chave === k) AppState[campo] = null;
    }
    // O ponto do botão de Filtros e o painel aberto mostram o que está no
    // aparelho agora (a outra aba pode ter visto a conquista, ou pousado ações).
    if (chave === null || chave === CONQUISTAS_KEY) atualizarSeloDeConquista();
    agendarRedesenhoDoHistorico();
}
// Desligar o modo dev, ou dar "Sair", numa aba NÃO chegava à outra: ela seguia
// com o FAB e com o modo dev na memória, e a captura seguinte RECRIAVA a base
// `waze_places_diag` com o DOM da tela (dado de terceiro) — contra "desligar
// apaga" e "Sair é limpar de tudo" (auditoria de 2026-09-26, D2). Aqui a aba
// relê o modo dev do armazenamento e, se ele desligou, apaga o que o modo dev
// gravou, como a aba que desligou apagou.
//
// O token saindo SOZINHO (a sessão caiu na outra aba, com o modo dev ligado)
// NÃO apaga nada: a queda é exatamente o que o diagnóstico existe pra mostrar,
// e a própria aba que caiu o preserva (`derrubarSessao` não chama o
// `dlogApagar`). O "Sair" desliga o modo dev no armazenamento, e é por aí que
// ele chega aqui.
function aoMudarModoDevEmOutraAba() {
    const agora = devModeDoArmazenamento();
    if (!agora) return;
    const estava = !!(AppState.devMode && AppState.devMode.active);
    AppState.devMode = agora;
    updateDevBadge();
    renderDevModeSection();
    diagAjustarRecursos();
    if (estava && !agora.active) {
        dlogApagar();          // (o `atualizarFabDev` vem junto)
        enforceDevGatedFilters();
    } else atualizarFabDev();
}

// O "Sair", o placar e as preferências, vindos da OUTRA aba (auditoria de
// 2026-09-29, R4-5 A1 e A2). As três coisas esta aba guarda na MEMÓRIA e grava
// INTEIRAS a cada gesto — e a outra muda no aparelho:
//   · o "Sair" de lá não chegava aqui: esta seguia logada, com o perfil e a
//     fila (dado de terceiro) na tela, e o ✕ seguinte regravava a fila de
//     saída, o placar e o diário — e ia pro Waze com o token de quem saiu;
//   · o placar: 3 ✕ numa aba e 1 na outra deixavam "Rejeitados 1" gravado;
//   · as preferências: um ✕ nesta regravava as de antes, desfazendo o que a
//     pessoa acabou de escolher lá — o "Pular guarda o pedido", e o "Ver quem
//     está no app" desligado, que voltava a mostrá-la no mapa do WME.
// Nada aqui GRAVA: o aviso do navegador só chega à OUTRA aba, e uma aba que
// respondesse a ele gravando mandaria outro de volta.
function sincronizarComOutraAba(chave) {
    const tudo = chave === null;   // a outra aba limpou o armazenamento inteiro
    if ((tudo || chave === 'waze_session_token' || chave === CONTA_KEY)
        && (aoSairEmOutraAba() || aoEntrarOutraContaEmOutraAba())) return;
    if (tudo || chave === STATS_KEY) relerPlacarDeOutraAba();
    if (tudo || chave === PREFERENCES_KEY) relerPreferenciasDeOutraAba();
    // A fila de saída é do aparelho, e só UMA aba a esvazia (ver `travaDaSaida`):
    // a outra seguia mostrando "1 esperando envio" depois de a decisão sair por
    // esta (auditoria de 2026-10-01, R5-1 F6). Só desenha.
    if (tudo || chave === SAIDA_KEY) updateInFlightIndicator();
}

// A conta desta aba (`id`) segue dona do aparelho? Os dados dele têm UM dono
// (`CONTA_KEY`, ver `aoConhecerConta`), e ele muda quando alguém entra com
// outra conta: a aba em que ela entrou tira o que era da anterior, e a sessão
// guardada passa a ser a dela. NÃO segue quando o dono guardado é outro E a
// sessão guardada não é a desta aba — senão é a troca de sempre, nesta aba
// mesmo (quem entrou aqui toma o aparelho da conta anterior). Conta ainda não
// sabida (sem perfil) segue: quem decide é o perfil, quando chegar.
function contaSegueNoAparelho(id) {
    if (id === undefined || id === null || id === '') return true;
    if (!safeLS.get('waze_session_token') || sessaoDestaAbaEhAGuardada()) return true;
    let dono = null;
    try { dono = JSON.parse(safeLS.get(CONTA_KEY) || 'null'); } catch (e) { dono = null; }
    return !(dono && dono.id && String(dono.id) !== String(id));
}

// Esta aba SAI quando outra conta toma o aparelho noutra aba. Seguindo, o placar
// e o Histórico que ela grava iam pra conta nova, e cada decisão dela que
// ficasse na fila de saída era tirada pela outra aba como "de outra conta", sem
// ir ao Waze — MEDIDO: o ✕ contado no placar e no Histórico da conta nova, e o
// que falhou por rede saindo da fila sem envio nenhum (auditoria de 2026-09-29).
// A decisão lê o aparelho como ele está, como a do "Sair": a outra grava o
// token ANTES da conta, e no aviso do token o `CONTA_KEY` ainda pode dizer a
// conta anterior — esta aba segue até o aviso da conta. Sem perfil na memória
// a conta desta aba não se sabe ainda; quando ele chega, o `definirPerfil`
// confere o mesmo — e ele é pedido NA HORA, com o card travado até chegar
// (`conferirContaDestaAba`, R6-1-04).
//
// A aba que CAIU na tela de entrada também não tem perfil (a tela de entrada o
// solta), e por ele a resposta era "segue" — mas ela sabe a conta: a que
// confirmou por último (ver `outraContaTomouOAparelhoDaQueCaiu`). Com OUTRA conta
// no aparelho, sai a parte de memória e de tela, como no "Sair" de lá (R12-1-04).
function aoEntrarOutraContaEmOutraAba() {
    if (contaSegueNoAparelho(AppState.profile && AppState.profile.id)) {
        if (contaDestaAbaEmDuvida()) conferirContaDestaAba();
        if (!outraContaTomouOAparelhoDaQueCaiu()) return false;
        handleLogout({ porOutraAba: true, outraConta: true, naEntrada: true });
        return true;
    }
    handleLogout({ porOutraAba: true, outraConta: true });
    return true;
}

// A aba que CAIU na tela de entrada guarda, de propósito, a memória da sessão
// que caiu — a fila, o card e a conta que confirmou (`contaConfirmadaNestaAba`)
// —, pra MESMA conta voltar (ver `guardaASessaoQueCaiu`). Quando OUTRA conta
// toma o aparelho noutra aba, isso tudo é de quem saiu: o card (dado de
// terceiro, no DOM debaixo da tela de entrada), a fila e o anel de chamadas da
// conta anterior ficavam nela até alguém entrar ali — MEDIDO no navegador:
// fila 5, o nome do local no DOM e 5 chamadas, com o aparelho já da outra conta
// (auditoria da rodada 13, R13-1-06; o irmão do R12-1-04). Sem sessão a encerrar
// aqui (nenhuma na memória, o app fora da tela) e sem pergunta à extensão no ar
// (o fim dela decide, e a adoção limpa pela memória). A conta se compara como a
// das abas logadas (`contaSegueNoAparelho`), pelo aparelho como ele está: no
// aviso do token a conta guardada ainda é a anterior, e decide o aviso da conta.
function outraContaTomouOAparelhoDaQueCaiu() {
    const appNaTela = !document.getElementById('appScreen')?.classList.contains('hidden');
    if (API.temSessaoNaMemoria() || AppState.authenticated || appNaTela || extPerguntando) return false;
    // Sem conta confirmada (a aba que nunca entrou), "segue": nada a encerrar.
    return !contaSegueNoAparelho(contaConfirmadaNestaAba && contaConfirmadaNestaAba.id);
}

// A conta DESTA aba ainda não se sabe — o perfil não chegou (falhou na
// abertura, ou está a caminho) — e o aparelho tem dono CONFIRMADO por OUTRA
// sessão: a guardada não é a desta aba, e a conta guardada foi vista com ela
// (a marca `s`). Outra conta pode ter entrado noutra aba, e "segue" (ver
// `contaSegueNoAparelho`) não queria dizer "é a mesma": esta aba seguia
// triando, o ✕ ia pro Waze com a sessão dela e o pouso gravava o Histórico, o
// placar, os autores e as conquistas no aparelho — já de quem entrou lá
// (MEDIDO no Chromium, auditoria de 2026-10-02, R6-1-04).
function contaDestaAbaEmDuvida() {
    const vivo = AppState.profile && AppState.profile.id;
    if (vivo !== undefined && vivo !== null && vivo !== '') return false;
    if (!AppState.authenticated || sessaoDestaAbaEhAGuardada()) return false;
    const guardado = safeLS.get('waze_session_token');
    if (!guardado) return false;
    let dono = null;
    try { dono = JSON.parse(safeLS.get(CONTA_KEY) || 'null'); } catch (e) { dono = null; }
    return !!(dono && dono.id && dono.s === marcaDaSessao(guardado));
}

// A dúvida apareceu: o perfil desta aba é pedido NA HORA — sem o teto de um
// minuto do `refazerPerfilSeFaltar`, porque é UM pedido por um evento raro (o
// aviso de outra aba) —, e até ele chegar nada decide aqui (`acoesTravadas`,
// com o aviso da espera da sessão). Ele decide: OUTRA conta, a aba sai
// (`definirPerfil`); a mesma, a trava sai. Falhou de novo, a trava fica, e o
// próximo pedido é o do `refazerPerfilSeFaltar`, que passa por aqui.
let conferindoContaDestaAba = false;
function conferirContaDestaAba() {
    // A dúvida ACENDEU agora: o que já tinha saído do gesto e ainda não gravou
    // nada é de uma conta que esta aba não sabe mais se é a dona do aparelho. A
    // trava segurava só as decisões NOVAS: o ✕ que estava na janela do Desfazer
    // saía no fim dela com a sessão desta aba, e o pouso gravava o Histórico, os
    // autores, as conquistas e a marca do primeiro ✕ no aparelho — já de OUTRA
    // conta (MEDIDO, auditoria de 2026-10-02, R7-2-01). Vale o que a QUEDA faz
    // (`derrubarSessao`): a janela é cancelada e a decisão volta como card (o
    // "Rejeitar os N" também: é a mesma janela), as do lightbox também, e a
    // época troca — a resposta do que estava no ar não grava nada no aparelho
    // (ela volta pela regra da queda, `decisaoDepoisDaQueda`), e o lote no ar
    // para e não trava a sessão que segue. Quando o perfil chegar: a MESMA
    // conta, o card destrava e a pessoa decide de novo; OUTRA, a aba sai.
    if (AppState.contaEmDuvida !== true) {
        AppState.contaEmDuvida = true;
        epocaDaSessao++;
        if (AppState.pendingAction) {
            AppState.pendingAction.cancel(true);
            AppState.pendingAction = null;
        }
        cancelarPendenciasDoLightbox();
        loteDeLidosEmVoo = false;
        aprovacoesAtravessamAQueda();
    }
    AppState.contaEmDuvida = true;
    aplicarTravaDeAcao();
    if (conferindoContaDestaAba) return;
    conferindoContaDestaAba = true;
    const p = loadProfileAndAuxData();
    AppState._profilePromise = p;
    Promise.resolve(p).catch(() => {}).then(() => {
        conferindoContaDestaAba = false;
        if (!contaDestaAbaEmDuvida()) AppState.contaEmDuvida = false;
        aplicarTravaDeAcao();
    });
}

// O "Sair" foi numa OUTRA aba? O que o separa da QUEDA da sessão lá é a CONTA:
// a queda tira o token e deixa a conta (a mesma pessoa volta, e os dados são
// dela); o "Sair" tira os dois. Os avisos chegam um por chave, na ordem em que
// a outra gravou — o do token antes do da conta —, e a decisão lê o aparelho
// como ele está: sem conta guardada, decide o aviso do token; com ela, o da
// conta, que chega logo depois.
function aoSairEmOutraAba() {
    if (safeLS.get('waze_session_token') || safeLS.get(CONTA_KEY)) return false;
    // Esta aba não tem SESSÃO a encerrar: nenhuma na memória, o app fora da tela
    // e nenhuma pergunta à extensão no ar — que traria uma sessão NOVA por cima
    // do "Sair" de lá.
    const appNaTela = !document.getElementById('appScreen')?.classList.contains('hidden');
    if (!API.temSessaoNaMemoria() && !AppState.authenticated && !appNaTela && !extPerguntando) {
        // Mas a aba que CAIU na tela de entrada guarda a MEMÓRIA da sessão que
        // caiu (ver a função): sem isto, a fila, o card (dado de terceiro, no DOM
        // debaixo da tela de entrada), o rascunho da conversa e o anel de
        // chamadas da conta que saiu ficavam nela — e voltavam com a mesma conta
        // entrando de novo ali (auditoria da rodada 12, R12-1-04, MEDIDO). Sai a
        // parte de memória e de tela do "Sair", sem gravar no aparelho (a outra
        // aba já o limpou) e sem fechar o que a pessoa abriu na tela de entrada:
        // o "Colar cookies", com o que ela digita, fica (R9-1-03). A aba que
        // nunca entrou não guarda nada, e segue como estava.
        if (!guardaASessaoQueCaiu()) return false;
        handleLogout({ porOutraAba: true, naEntrada: true });
        return true;
    }
    handleLogout({ porOutraAba: true });
    return true;
}

// A aba que CAIU na tela de entrada (a sessão venceu e não foi renovada) guarda,
// de propósito, a memória da sessão que caiu — pra MESMA conta voltar (ver
// `derrubarSessao`): a conta que ela confirmou, a fila e o card. A aba que nunca
// entrou não tem nenhum dos três.
function guardaASessaoQueCaiu() {
    return !!contaConfirmadaNestaAba || AppState.queue.length > 0 || !!AppState.currentPlace
        || !!document.querySelector('#cardStack .place-card');
}

// O placar que a outra aba gravou, relido NO MESMO objeto: o desconto de uma
// decisão em voo é feito no placar DO GESTO, achado pela identidade (ver
// `descontarGestoSemSessao`) — trocar o objeto o deixaria órfão.
function relerPlacarDeOutraAba() {
    const guardado = placarGuardado();
    if (!guardado) return;
    const placar = AppState.stats;
    // Os pulados DESTA fila (`puladosNestaFila`) não contam os da outra aba: a
    // base anda junto com o que ela pulou (ou devolveu com o Desfazer).
    puladosNoInicioDaFila += guardado.skipped - (placar.skipped || 0);
    Object.assign(placar, guardado);
    desenharPlacar(true);
}

// As preferências que a outra aba gravou: as de fábrica e, por cima, as do
// aparelho — pela MESMA leitura da abertura. Só se relê depois da primeira
// leitura desta aba (antes dela, a abertura vai ler o aparelho de qualquer
// jeito).
function relerPreferenciasDeOutraAba() {
    if (!preferenciasCarregadas) return;
    const antes = AppState.preferences;
    AppState.preferences = preferenciasDeFabrica();
    lerPreferenciasGuardadas();
    const agora = AppState.preferences;
    // O que MOSTRA a preferência nesta aba: as chaves da aba Preferências, o
    // selo do ↑ e a linha do offline.
    desenharChavesDePreferencia();
    atualizarSeloDePular();
    atualizarLinhaDoOffline(0, 0);
    // "Ver quem está no app" desligado lá: aqui a conexão fecha e a pílula some,
    // sem pedido nenhum (o `visivel: false` a outra mandou no gesto). Ela o
    // GRAVA antes de mandar (R7-5-03), e a leitura acima o traz pra cá: se ela
    // fechar com o pedido no ar, a prova de rede daqui o manda
    // (`presencaWmeRefazerDesligar`); a resposta boa de lá o apaga. Religado lá:
    // a próxima ação daqui liga a visibilidade de carona, como a próxima de lá —
    // a pessoa pode seguir triando nesta.
    if ((antes.presenca !== false) !== (agora.presenca !== false)) {
        if (agora.presenca === false) {
            presencaWme.ligarNaProxima = false;
            presencaWme.desligarPendente = false;
            window.Presenca?.desligar?.();
        } else presencaWme.ligarNaProxima = true;
        window.Presenca?.renderPilula?.();
    }
    // O offline desligado lá: a varredura daqui PARA, senão ela gravaria de novo
    // na base que a outra acabou de apagar.
    if (antes.offlineDisponivel === true && agora.offlineDisponivel !== true) offlineEsquecer({ soMemoria: true });
}

// As chaves da aba Preferências desenham a memória — e só desenham (quem as
// liga e desliga é o gesto, nos ouvintes de `setupModalListeners`). A do
// Desfazer, travada pela cota, fica como o `renderUndoGateUI` a deixou.
function desenharChavesDePreferencia() {
    const p = AppState.preferences;
    const marcar = (id, ligada) => {
        const el = document.getElementById(id);
        if (el && !el.disabled) el.checked = ligada;
    };
    marcar('prefUndoEnabled', p.undoEnabled !== false);
    marcar('prefPularGuarda', p.pularGuarda === true);
    marcar('prefPresenca', p.presenca !== false);
    marcar('prefOfflineDisponivel', p.offlineDisponivel === true);
}

function setupSincroniaEntreAbas() {
    window.addEventListener('storage', aoGravarEmOutraAba);
    // O que POUSA numa aba sai da fila das outras (R11-2-01, ver
    // `avisarOutrasAbasDoPouso`): o canal é aberto aqui, uma vez por página.
    abrirCanalDosPousos();
    // E a fila guardada do offline que outra aba gravou (R13-4-03, ver
    // `avisarOutrasAbasDaFilaGuardada`).
    abrirCanalDoOffline();
}
// ═══════════════════════════════════════════════════════════════════════════
//  Patentes e Conquistas — celebra, nunca cobra
// ═══════════════════════════════════════════════════════════════════════════
//
// Tudo no aparelho, zero requisição, sai no "Sair" como o resto. A régua que
// decidiu cada peça: **isto celebra o que a pessoa fez, ou cobra o que ela não
// fez?** Por isso não há sequência viva, não há "você vai perder", não há
// ranking e não há contador de progresso nas trancadas ("3 de 10" é o
// mecanismo de pressão, não a informação).
//
// TRÊS decisões de tela que saíram de MEDIÇÃO, não de gosto (mockups em
// 2026-09-14, app real nos dois aparelhos, dois temas, pt e fr):
//
//  1. GRADE LARGA — 3 colunas no normal, 2 no estreito. Em 4, MEDIDO: as
//     colunas saem 70/70/78/70, porque o nome mais longo força `min-width:auto`
//     e uma delas estica — a vitrine deixa de ser uma grade. Em 3 dá 98/98/98.
//     Custa 98px a mais de rolagem e paga. O smoke compara as larguras entre
//     si, que é o que uma tradução longa quebra primeiro (gotcha #25).
//  2. TRANCADA MOSTRA NOME E ÍCONE, em cinza. A versão "misteriosa" (🔒 + ?)
//     deixa nove células IDÊNTICAS: não lê como descoberta, lê como tela
//     quebrada — e pro editor novo, que tem 16 delas, é uma parede.
//  3. A CONDIÇÃO MORA FORA DA CÉLULA, numa linha ao toque. Dentro, na largura
//     que a grade tem, ela parte palavra pelo mesmo motivo do item 1.
//
const CONQUISTAS_KEY = 'waze_places_conquistas';

// A ESCADA, por total tratado (lidos + rejeitados). Seis degraus.
//
// O degrau 5 era "Síndico" e mudou: é conceito de prédio brasileiro que não
// existe nas outras três línguas sem virar frase ("gestionnaire d'immeuble" é
// descrição, não patente). "Inspetor" vira Inspector/Inspecteur/Inspector
// palavra por palavra. Os outros cinco atravessam — e a piada da limpeza fica,
// porque "Lixeiro" no meio da escada É a identidade do app.
const PATENTES = [
    { id: 'aprendiz', emoji: '🧤', min: 0 },
    { id: 'gari',     emoji: '🧹', min: 100 },
    { id: 'lixeiro',  emoji: '🗑️', min: 500 },
    { id: 'zelador',  emoji: '🔑', min: 1500 },
    { id: 'inspetor', emoji: '🏢', min: 4000 },
    { id: 'prefeito', emoji: '🏛️', min: 10000 },
];

// ORDEM FIXA, e ela NÃO se reordena por "ganhas primeiro". Vitrine que se
// reorganiza a cada desbloqueio destrói o reconhecimento — você aprende que a
// sua é o elefante do meio e no dia seguinte ela mudou de lugar. A ordem é
// aproximadamente a de dificuldade, então na prática preenche de cima pra
// baixo sozinha.
//
// `l6` marca as que dependem do portão destrutivo (aprovar foto, renomear).
// Elas ficam no FIM de propósito: escondidas de quem não passa no portão, não
// deixam buraco na grade. Cadeado que NUNCA abre é beco sem saída — a mesma
// régua que tirou a extensão de Chrome da frente no celular.
//
// `evento` marca as que destravam pelo que ACABOU de acontecer (o desfazer, a
// madrugada, o duplicado rejeitado...), e não por volume acumulado: essas nunca
// são retroativas, então a primeira passada do aparelho (a silenciosa) as
// anuncia — ver `checarConquistas`.
const CONQUISTAS = [
    { id: 'primeiraFaxina', emoji: '🧹' },
    { id: 'centuriao',      emoji: '💯' },
    { id: 'maoFirme',       emoji: '🎯' },
    { id: 'detetive',       emoji: '🕵️', evento: true },
    { id: 'elefante',       emoji: '🐘', evento: true },
    { id: 'tudoLimpo',      emoji: '🧼', evento: true },
    { id: 'colecionador',   emoji: '⭐' },
    { id: 'coruja',         emoji: '🌙', evento: true },
    { id: 'segundaChance',  emoji: '↩️', evento: true },
    { id: 'primeiroResumo', emoji: '🎉', evento: true },
    { id: 'andarilho',      emoji: '🗺️' },
    { id: 'viajante',       emoji: '🌍' },
    { id: 'poliglota',      emoji: '🗣️' },
    { id: 'semanaCheia',    emoji: '📅' },
    { id: 'curador',        emoji: '📸', l6: true },
    { id: 'corretor',       emoji: '✏️', l6: true },
];

// PURAS — é o que o teste exercita sem browser.
function patenteDe(tratados) {
    const n = Number.isFinite(tratados) ? tratados : 0;
    let i = 0;
    while (i + 1 < PATENTES.length && n >= PATENTES[i + 1].min) i++;
    return i;
}
// Avalia TODAS e devolve só as que viraram de trancada pra ganha agora.
// Sem DOM, sem relógio, sem armazenamento: recebe o contexto pronto.
function avaliarConquistas(ctx, jaTem) {
    const c = ctx || {}, tem = jaTem || {};
    const cond = {
        primeiraFaxina: (c.tratados || 0) >= 10,
        centuriao:      (c.hoje || 0) >= 100,
        maoFirme:       (c.seq || 0) >= 100,
        detetive:       !!c.duplicado,
        elefante:       !!c.reincidente,
        tudoLimpo:      !!c.filaZerada,
        colecionador:   (c.guardados || 0) >= 10,
        coruja:         !!c.madrugada,
        segundaChance:  !!c.desfez,
        primeiroResumo: !!c.resumo,
        andarilho:      (c.estados || 0) >= 3,
        viajante:       (c.paises || 0) >= 2,
        poliglota:      (c.idiomas || 0) >= 2,
        semanaCheia:    (c.diasSeguidos || 0) >= 7,
        curador:        (c.fotos || 0) >= 10,
        corretor:       (c.nomes || 0) >= 5,
    };
    // Na ORDEM da lista: é ela que decide qual anunciar quando duas caem juntas.
    return CONQUISTAS
        .filter((x) => (!x.l6 || c.gateL6) && cond[x.id] && !tem[x.id])
        .map((x) => x.id);
}

function carregarConquistas() {
    // A cópia em memória só vale se a outra aba não gravou (ver `copiaEmDia`).
    if (copiaEmDia(AppState.conquistas, CONQUISTAS_KEY)) return AppState.conquistas;
    let texto = null;
    try { texto = localStorage.getItem(CONQUISTAS_KEY); } catch (e) { texto = null; }
    let g = null;
    try { g = JSON.parse(texto || 'null'); } catch (e) { g = null; }
    if (!g || typeof g !== 'object') g = {};
    AppState.conquistas = {
        c: (g.c && typeof g.c === 'object') ? g.c : {},   // id → 'YYYY-MM-DD'
        // Seguidas sem desfazer. Contador PRÓPRIO, e não o `semUndoSeguidas` das
        // preferências: aquele só conta janela do Desfazer que expirou
        // NATURALMENTE, ou seja só com o Desfazer LIGADO — quem o desligou
        // (justamente o editor rápido, pra quem "Mão firme" faria sentido)
        // nunca acumularia um. Este sobe na confirmação e zera no desfazer,
        // funcionando dos dois jeitos.
        seq: Number.isFinite(g.seq) ? g.seq : 0,
        patente: Number.isFinite(g.patente) ? g.patente : null,
        n: (g.n && typeof g.n === 'object') ? g.n : {},   // contadores acumulados
        langs: Array.isArray(g.langs) ? g.langs.slice(0, 8) : [],
        base: g.base === true,
        // O que destravou e a pessoa ainda NÃO viu. É isto que acende o selo no
        // botão de Filtros e desenha o anel na vitrine — some ao abrir a aba.
        novas: Array.isArray(g.novas) ? g.novas.slice(0, 32) : [],
        patenteNova: g.patenteNova === true,
    };
    lembrarTextoDaCopia(AppState.conquistas, CONQUISTAS_KEY, texto);
    return AppState.conquistas;
}
function salvarConquistas() {
    try {
        localStorage.setItem(CONQUISTAS_KEY, JSON.stringify(AppState.conquistas));
        lembrarTextoDaCopia(AppState.conquistas, CONQUISTAS_KEY);
    } catch (e) {}
}
// Uma ação CONFIRMADA pelo Waze. Daqui saem a sequência sem desfazer, os
// gatilhos de evento e a reavaliação.
//
// ELA E A `registrarDesfazer` FORAM REMOVIDAS POR ENGANO em v2026.09.16-xx
// (#215, o PR que trocou o banner de conquista por um ponto): a que precisava
// sair era só a `anunciarConquista`, e estas duas foram junto — com os DOIS
// call sites de cada uma ficando pra trás. O resultado estava em produção e não
// era sutil: `handleActionResult` lançava `ReferenceError` em TODA ação
// confirmada, e `desfazerAcaoPendente` lançava antes de tirar o banner e
// destravar os botões — ou seja, desfazer devolvia o pedido e deixava o card
// MORTO (banner preso, ✕ ↑ ✓ desabilitados), com o gesto ainda funcionando, que
// é exatamente o que escondia o problema (a mesma assinatura do gotcha #63).
// Nenhum teste enxergava porque nenhum deles CHAMA o código — os de unidade
// fatiam a fonte e o smoke não exercitava o Desfazer até o fim.
//
// `gesto` é o MOMENTO da ação quando ela não pousa na hora — a fila de saída
// guarda a hora, o dia e o idioma do gesto (`enfileirarSaida`). Sem ele, vale
// agora, que é o caso de todo pouso com rede.
//
// SEM guarda do treino, e ela existia: uma decisão REAL que pousa com o treino
// aberto (a da janela do Desfazer, que o `Treino.entrar` despacha sem esperar;
// a fila de saída esvaziando; o "Rejeitar os N" no ar) é trabalho da pessoa, e o
// Histórico a contava enquanto as conquistas a jogavam fora — o "Detetive" do
// duplicado rejeitado sumia pra sempre, e a "Mão firme" não andava (R6-7-3,
// auditoria de 2026-10-01). Ação DE treino nunca chega aqui: o guard está no
// topo dos handlers (`handleReject` e os irmãos).
function registrarAcaoConfirmada(actionType, place, gesto) {
    const g = carregarConquistas();
    g.seq = (g.seq || 0) + 1;
    salvarConquistas();
    // O idioma entra no gesto, não na carga: o "Poliglota" é sobre TRABALHAR
    // em dois, não sobre abrir o seletor e voltar — e a condição na vitrine diz
    // isso, no verbo das vizinhas ("tratar pedidos em 2 idiomas"; dizia "usar o
    // app", R10-7-05). Item da fila de saída sem o idioma (gravado antes dele
    // existir) não registra nenhum: o de AGORA não é prova de que o trabalho
    // foi feito nele.
    registrarIdiomaUsado(gesto ? gesto.lang : (typeof getLang === 'function' ? getLang() : ''));
    const hora = new Date(gesto && Number.isFinite(gesto.t) ? gesto.t : Date.now()).getHours();
    // "Centurião" é o balde do DIA do gesto — o `recordHistory` do pouso já
    // somou a ação nele. Sem `gesto.dia`, o `checarConquistas` usa o de hoje.
    const balde = gesto && gesto.dia ? loadHistory()[gesto.dia] : null;
    checarConquistas({
        ...(balde ? { hoje: (balde.read || 0) + (balde.rejected || 0) } : {}),
        // "Rejeitar um duplicado" é pelo MOTIVO do reporte, o mesmo que faz o
        // card dizer "Duplicado". O `place.duplicado` é outra coisa — o alvo que
        // o servidor conseguiu RESOLVER, e ele nem sempre consegue: o card dizia
        // "Duplicado" e a conquista não contava (auditoria de 2026-09-29, H1).
        duplicado: actionType === 'reject' && !!place && place.flagType === 'DUPLICATE',
        // `contagemDoAutor` já inclui ESTA rejeição (o registro veio antes), então
        // > 1 significa que havia rejeição anterior — é isso que faz reincidente.
        reincidente: actionType === 'reject' && !!place && place.creatorId != null
                     && contagemDoAutor(place) > 1,
        // "Depois da meia-noite" é a MADRUGADA (0h–4h59), não a noite: às 23h a
        // pessoa ainda está acordada no mesmo dia, e a graça da coruja é a virada.
        madrugada: hora >= 0 && hora < 5,
        // O último pedido da fila CONFIRMADO: é aqui, e não no painel que
        // aparece com o gesto, que a fila fica limpa de verdade (C13).
        filaZerada: filaZeradaConfirmada({ confirmando: true, place }),
    });
    // A cota do Desfazer, pela mesma régua: na confirmação (ver `updateStats`).
    checkUndoGateUnlock();
}

// O lote de lidos confirma N de uma vez: UMA gravação e UMA avaliação, não N
// (seriam N escritas síncronas no localStorage no meio da tela).
// Sem guarda do treino, pela mesma razão da `registrarAcaoConfirmada`.
// `gesto`: o momento do toque no "Marcar todos" (`carimboDoGesto`) — a hora, o
// dia e o idioma em que a pessoa decidiu, como no ✕ e no ✓. Sem ele, vale agora.
function registrarLoteConfirmado(n, gesto) {
    const g = carregarConquistas();
    g.seq = (g.seq || 0) + n;
    salvarConquistas();
    registrarIdiomaUsado(gesto ? gesto.lang : (typeof getLang === 'function' ? getLang() : ''));
    const hora = new Date(gesto && Number.isFinite(gesto.t) ? gesto.t : Date.now()).getHours();
    // "Centurião" é o balde do DIA do gesto, a régua da `registrarAcaoConfirmada`:
    // o lote soma no `gesto.dia` (o `recordHistory` do `contarLidos` já somou), e
    // julgado pelo balde de HOJE, o "Marcar todos" tocado às 23:59 e pousado
    // depois da meia-noite não dava o "Centurião", com 120 no balde do gesto
    // (MEDIDO no navegador; o ✓ do card, no mesmo instante, dava; auditoria de
    // 2026-10-07, R11-7-06). Depois da virada, nada mais avalia aquele dia.
    const balde = gesto && gesto.dia ? loadHistory()[gesto.dia] : null;
    checarConquistas({
        ...(balde ? { hoje: (balde.read || 0) + (balde.rejected || 0) } : {}),
        madrugada: hora >= 0 && hora < 5,
    });
    checkUndoGateUnlock();   // ver `updateStats`
}

// Desfazer zera a sequência de "Mão firme" e destrava "Segunda chance" — que é
// de propósito o contrapeso da lista: a única que celebra CUIDADO, não volume.
function registrarDesfazer() {
    if (typeof Treino !== 'undefined' && Treino && Treino.ativo) return;
    const g = carregarConquistas();
    g.seq = 0;
    salvarConquistas();
    checarConquistas({ desfez: true });
}

// Contador acumulado (guardados, fotos aprovadas, nomes corrigidos).
function contarConquista(chave, delta) {
    const g = carregarConquistas();
    g.n[chave] = Math.max(0, (g.n[chave] || 0) + (delta || 1));
    salvarConquistas();
    checarConquistas();
}
// O idioma entra num conjunto pequeno — é o dado de "Poliglota", e é seu.
function registrarIdiomaUsado(lang) {
    const l = String(lang || '').slice(0, 2);
    if (!l) return;
    const g = carregarConquistas();
    if (g.langs.includes(l)) return;
    g.langs.push(l);
    salvarConquistas();
    checarConquistas();
}

// ── geografia: de onde sai "Andarilho" e "Viajante" ────────────────────────
// O `place` NÃO carrega país/estado (o core não propaga), então a fonte é o
// FILTRO — que é onde o editor escolheu trabalhar, e é a mesma fonte que já
// nomeia a sala da presença.
//
// Com "Minha área" a busca vai pela CAIXA da área, sem o estado E sem o país do
// filtro (o core manda `countryId: null` junto da caixa): nenhum dos dois é onde
// o trabalho foi feito. O estado saiu primeiro (R6-7-4, auditoria de
// 2026-10-01); o país ficava, e com a área num país e o filtro noutro o ✕ entrava
// no Histórico — e no "Viajante" — como o país do filtro (auditoria da rodada 7,
// R7-6-05). O "onde" é o país da área quando o app o SABE (`paisDaMinhaArea`), e
// nada quando não sabe: deixar de contar é melhor que contar no lugar errado.
function ondeAgora() {
    if (AppState.filters && AppState.filters.myArea) {
        const area = paisDaMinhaArea();
        return area ? String(area) : null;
    }
    const pais = (typeof API !== 'undefined' && API.getCountry) ? parseInt(API.getCountry(), 10) : NaN;
    if (!Number.isFinite(pais) || pais <= 0) return null;
    const estado = parseInt(AppState.filters && AppState.filters.stateId, 10);
    return Number.isFinite(estado) && estado > 0 ? pais + ':' + estado : String(pais);
}

// O país da FILA de quem busca por "Minha área" — sem pedido novo (R7-6-05). O
// pedido não traz o país (o core não o repassa), mas a fila só tem o que a
// pessoa pode EDITAR (o filtro de permissão do servidor descarta o resto), e os
// editáveis são POR SERVIDOR (`editaveisLidos`): quem edita UM país só neste
// servidor tem a fila inteira nele. Com mais de um, ou sem a lista deste
// servidor (o perfil foi lido noutro), não dá pra saber qual: `null`.
function paisDaMinhaArea() {
    const lidos = typeof API !== 'undefined' && API.getRegion ? editaveisLidos(API.getRegion()) : null;
    if (!lidos) return null;
    const paises = [...new Set(lidos)];
    return paises.length === 1 ? paises[0] : null;
}

// O país em que a FILA está, pra MARCA da presença (a carona leva o país do
// gesto): o do filtro — e, com "Minha área", o da área quando o app o sabe
// (`paisDaMinhaArea`): com a área num país e o filtro noutro, a pessoa aparecia
// no "Triando agora" do país do filtro (R7-6-05). Sem saber, segue o do filtro:
// a marca não existe sem país, e sem marca a pessoa sumiria do "Triando agora" de
// todo mundo enquanto usa "Minha área".
function paisDaFila() {
    if (AppState.filters && AppState.filters.myArea) {
        const area = paisDaMinhaArea();
        if (area) return area;
    }
    return API.getCountry();
}

// O MOMENTO do gesto: a hora, o dia, o lugar e o idioma em que a pessoa decidiu.
// É o que o Histórico e as conquistas registram, e eles chegavam ao pouso sendo
// lidos de NOVO — na resposta (o `recordHistory` online) ou no envio (a anotação
// na fila de saída, no fim da janela do Desfazer). "Aplicar" outro país dentro
// da janela creditava o ✕ dado no Brasil à França e destravava "Viajante" sem
// nenhum pedido francês tratado (R6-7-4). Carimbado junto da região do gesto
// (`API.getRegion()` nos handlers), e com a MESMA forma que a fila de saída já
// guardava (`t`, `dia`, `onde`, `lang`): o pouso de lá e o de cá contam igual.
function carimboDoGesto() {
    return { t: Date.now(), dia: historyTodayKey(), onde: ondeAgora(),
             lang: typeof getLang === 'function' ? getLang() : '' };
}
// Estado é chaveado por `pais:estado`, nunca pelo id do estado sozinho: o
// mesmo número existe em países diferentes e juntaria dois lugares num só.
function geografiaDoHistorico(h) {
    const paises = new Set(), estados = new Set();
    for (const [k, v] of Object.entries(h || {})) {
        if (k === '_total' || !v) continue;
        // MIGRACAO: historico-onde
        // Balde gravado antes de v2026.09.14-01 não tem `onde`, e não há como
        // saber onde aquele trabalho foi feito — ele simplesmente não conta.
        for (const chave of Object.keys(v.onde || {})) {
            const pais = String(chave).split(':')[0];
            if (pais) paises.add(pais);
            if (String(chave).includes(':')) estados.add(chave);
        }
    }
    return { paises, estados };
}

// A MAIOR sequência de dias com trabalho. Só varre a partir de um dia cujo
// anterior está ausente, então cada dia é visitado no máximo duas vezes. Anda
// por DATA (`chaveMaisDias`), nunca somando 24 h: no fim do horário de verão o
// dia tem 25 h, a soma caía no MESMO dia e a sequência de 6 contava 7.
function maiorSequenciaDeDias(h) {
    const dias = new Set(Object.keys(h || {})
        .filter((k) => /^\d{4}-\d{2}-\d{2}$/.test(k) && h[k] && ((h[k].read || 0) + (h[k].rejected || 0)) > 0));
    let melhor = 0;
    for (const d of dias) {
        if (dias.has(chaveMaisDias(d, -1))) continue;
        let n = 1, cur = d;
        while (dias.has(chaveMaisDias(cur, 1))) { cur = chaveMaisDias(cur, 1); n++; }
        if (n > melhor) melhor = n;
    }
    return melhor;
}

// ── o portão, e a checagem ─────────────────────────────────────────────────
// Função PRÓPRIA que delega à base, como manda o padrão dos outros destrutivos
// (`podeExcluirFotoAqui`, `podeRenomearAqui`): nunca chamar a base direto nem
// copiar `rank >= 5`.
function conquistasComPortaoAqui() { return podeAgirComoL6Aqui(); }
// O que a pessoa VÊ. Sem portão, as duas últimas não existem — nem na grade
// nem no "de 16", que vira "de 14".
function conquistasVisiveis() {
    return CONQUISTAS.filter((x) => !x.l6 || conquistasComPortaoAqui());
}

// Sem guarda do treino: quem chama aqui é trabalho REAL (a confirmação de uma
// decisão, o "Primeiro resumo" baixado com o treino aberto) — ver a
// `registrarAcaoConfirmada`. O que é do treino (a fila de exemplos) fica de fora
// do "Tudo limpo" pela `filaZeradaConfirmada`.
function checarConquistas(extra) {
    if (!AppState.authenticated) return;
    const g = carregarConquistas();
    const h = loadHistory();
    const s = getHistoryStats();
    const geo = geografiaDoHistorico(h);
    const tratados = s.total.read + s.total.rejected;
    const ctx = Object.assign({
        tratados,
        hoje: s.today.read + s.today.rejected,
        seq: g.seq || 0,
        guardados: g.n.guardados || 0,
        fotos: g.n.fotos || 0,
        nomes: g.n.nomes || 0,
        idiomas: g.langs.length,
        estados: geo.estados.size,
        paises: geo.paises.size,
        diasSeguidos: maiorSequenciaDeDias(h),
        gateL6: conquistasComPortaoAqui(),
    }, extra || {});

    const novas = avaliarConquistas(ctx, g.c);
    const hoje = historyTodayKey();
    for (const id of novas) g.c[id] = hoje;
    // Destravou com o painel aberto (o "Colecionador" do pedido guardado, o
    // "Corretor" do renomear que responde): a célula acende sem fechar o modal.
    if (novas.length) agendarRedesenhoDoHistorico();

    // LINHA DE BASE. Na primeira passada deste aparelho nada é anunciado: quem
    // já tem 3.000 pedidos nas costas destrava oito de uma vez, e oito banners
    // seguidos não é festa, é enxurrada. Mesmo raciocínio do `initUndoGateSeen`
    // — e, como lá, isto NÃO é migração: todo aparelho novo também passa por
    // aqui (e não destrava nada).
    //
    // O silêncio é só pro RETROATIVO (volume que já estava nas costas). A de
    // EVENTO acabou de acontecer: quando o primeiro evento do aparelho era um
    // Desfazer, a "Segunda chance" ficava gravada sem ponto nem anel, e ninguém
    // nunca sabia que ganhou (auditoria de 2026-09-25).
    const iP = patenteDe(tratados);
    if (!g.base) {
        g.base = true;
        g.patente = iP;
        const doEvento = novas.filter((id) => CONQUISTAS.some((x) => x.id === id && x.evento));
        for (const id of doEvento) if (!g.novas.includes(id)) g.novas.push(id);
        salvarConquistas();
        if (doEvento.length) atualizarSeloDeConquista();
        return;
    }

    // O AVISO NÃO INTERROMPE — decisão do owner (2026-09-16), depois de ver o
    // banner na tela: "ficou parecendo com o desbloquear o Desfazer; prefiro
    // algo mais simples, discreto e que não atrapalhe".
    //
    // Ele tinha razão de um jeito literal: conquista e desbloqueio do Desfazer
    // eram o MESMO código — `dispararConfeteNaFila()` + banner dourado de 20s.
    //
    // MEDIDO nas quatro opções, com o app rodando. A coluna que decidiu não é
    // estética: é quanto do PLACAR some, e o projeto marca o placar com
    // `.nao-cobrir` porque cobrir número MENTE ("311" lê como "31").
    //   banner dourado (o de antes) → placar coberto 13 de 13 + confete na foto
    //   banner discreto no topo     → placar coberto 13 de 13 (7/13 no Fold)
    //   snackbar no rodapé          → TAPA o ✕ no Galaxy Fold (gotcha #26)
    //   selo no botão de Filtros    → 0 de 13, e nada com prazo pra sumir
    // O banner "discreto" é a descoberta que fechou a questão: o que atrapalha
    // é a POSIÇÃO, não a cor nem o confete.
    //
    // E pelo M3 conquista nunca foi candidata a banner: "banner é proeminente,
    // TEM AÇÃO e fica mais tempo". O desbloqueio do Desfazer tem ação de
    // verdade (abre as Preferências pra desligá-lo); tocar numa conquista só
    // leva a OLHAR, que é navegação. Somando a frequência — Desfazer 1× na
    // vida, conquista 16× —, o mesmo banner nos dois gastava o momento do
    // Desfazer. Hoje o dourado com confete é exclusivo dele.
    //
    // A PATENTE entra na mesma regra, e não é descuido: se ela continuasse com
    // banner, o dourado voltaria a significar duas coisas — que é o defeito
    // que este bloco existe pra corrigir.
    const subiu = Number.isFinite(g.patente) && iP > g.patente;
    g.patente = iP;
    if (subiu) g.patenteNova = true;
    for (const id of novas) if (!g.novas.includes(id)) g.novas.push(id);
    salvarConquistas();
    if (subiu || novas.length) atualizarSeloDeConquista();
}

// A 1ª passada do aparelho é SILENCIOSA, e o silêncio é só pro RETROATIVO — o
// volume que já estava no histórico antes de o aparelho avaliar conquistas. Feita
// na confirmação da 1ª ação, ela calava a PRÓPRIA ação: o `recordHistory` já a
// tinha somado, e um "Marcar todos" de 12 como 1ª ação do aparelho destravava a
// "Primeira faxina" gravada, sem ponto nem etiqueta "nova" (R6-7-13, auditoria
// de 2026-10-01). Daí a base ser feita AQUI, pelo `recordHistory`, antes de a
// ação entrar: o histórico é a única fonte de volume que pode ser retroativa
// (os contadores próprios — sequência, guardados, fotos, nomes, idiomas —
// nascem zerados com as conquistas), e toda ação confirmada passa por ele
// antes de chegar às conquistas.
function garantirLinhaDeBaseDasConquistas() {
    if (!AppState.authenticated) return;
    const g = carregarConquistas();
    if (g && !g.base) checarConquistas();
}

// Um PONTO, nunca um número (decisão do owner). Número convida a "zerar", e o
// app já tem a regra de não mostrar contador que a pessoa não consegue zerar —
// conquista não é caixa de entrada. Mesmo desenho da pílula da presença
// ("badged icon button" do M3), que já mede 44px e não custa layout: ele mora
// SOBRE o ícone.
// Há algo destravado que a pessoa ainda não viu? FONTE ÚNICA da pergunta:
// quem ACENDE o ponto e quem decide PRA ONDE o botão leva precisam concordar
// sempre — duas cópias da condição é como elas passam a discordar, e aí o
// ponto aparece levando pra lugar nenhum (ou some levando pra algum).
//
// Lê do ARMAZENAMENTO, não do que estiver em memória: quem destravou ontem e
// fechou o app voltaria sem nada até o primeiro swipe. Deslogado não carrega
// nada — isto é estado de quem entrou.
//
// E conta só o que a vitrine MOSTRA agora (`novasNaVitrine`): o "Curador" e o
// "Corretor" são de L6, e sem o perfil — o `/Session` é a chamada mais lenta da
// abertura, e pendura no sinal ruim — o portão os esconde. O ponto acendia por
// eles, e o toque levava ao Histórico "1 de 14", sem a célula e sem alvo
// (R13-7-02, MEDIDO no navegador; auditoria de 2026-10-07). O perfil que chega
// acende o ponto (`definirPerfil`), e aí ele leva até ela.
function temConquistaNova() {
    if (!AppState.authenticated) return false;
    const g = carregarConquistas();
    return !!g && (novasNaVitrine(g).length > 0 || g.patenteNova);
}

// As novas que a vitrine MOSTRA agora: as de portão (`l6`) só com ele. A
// patente não entra — o cartão dela está sempre na tela.
function novasNaVitrine(g) {
    const mostra = new Set(conquistasVisiveis().map((x) => x.id));
    return g.novas.filter((id) => mostra.has(id));
}

function atualizarSeloDeConquista() {
    const btn = document.getElementById('filtersBtn');
    const selo = document.getElementById('conqSelo');
    if (!btn || !selo) return;
    const tem = temConquistaNova();
    selo.classList.toggle('hidden', !tem);
    // O ponto é `aria-hidden`: quem não enxerga precisa da informação no NOME
    // do botão, senão o selo não existe pra leitor de tela nenhum.
    btn.setAttribute('aria-label', t('header.filters.aria') + (tem ? ' — ' + t('conq.selo.aria') : ''));
}

// Abrir a aba É ter visto. Some o selo e, na PRÓXIMA abertura, somem os anéis —
// nesta a pessoa ainda precisa ver o que destravou, então não re-renderiza. E
// o que ela viu como novo fica em `novasDestaAbertura`: o painel é redesenhado
// com ela aberta (ação que pousa, troca de idioma, toque numa célula), e sem
// isso o anel sumia no primeiro redesenho, antes de ser visto.
//
// Visto é só o que a vitrine MOSTROU (`novasNaVitrine`): a de L6 escondida pelo
// portão sem o perfil seguia pra "vista" sem nunca ter aparecido — no toque do
// ponto, e no Histórico aberto que a OUTRA aba redesenha (R13-7-02). Ela fica
// nova, e é vista quando o perfil a puser na tela.
function marcarConquistasVistas() {
    const g = AppState.conquistas;
    if (!g) return;
    const vistasAgora = novasNaVitrine(g);
    if (!vistasAgora.length && !g.patenteNova) return;
    const vistas = novasDestaAbertura || { ids: [], patente: false };
    novasDestaAbertura = {
        ids: [...new Set([...vistas.ids, ...vistasAgora])],
        patente: vistas.patente || g.patenteNova,
    };
    g.novas = g.novas.filter((id) => !vistasAgora.includes(id));
    g.patenteNova = false;
    salvarConquistas();
    atualizarSeloDeConquista();
}

// ── a tela ─────────────────────────────────────────────────────────────────
// Estado só de VISUALIZAÇÃO (escada aberta, conquista tocada, o que esta
// abertura mostrou como novo): não persiste, não sai no diagnóstico, morre
// quando o modal fecha.
let escadaAberta = false;
let conquistaTocada = null;
let novasDestaAbertura = null;   // { ids, patente } — ver `marcarConquistasVistas`

// O painel do Histórico está NA TELA — o modal aberto E a aba dele escolhida?
function historicoNaTela() {
    const modal = document.getElementById('filtersModal');
    const painel = document.getElementById('filtersPanelHistory');
    return !!modal && !!painel && !modal.classList.contains('hidden') && !painel.classList.contains('hidden');
}

// Redesenha o painel se ele estiver na tela, UMA vez por tarefa. A confirmação
// de uma ação grava o histórico, o autor e as conquistas em sequência, e o
// painel tem que mostrar os três — daí o fim da tarefa, e não cada gravação.
// Antes a ação que pousava com o painel aberto só aparecia fechando e
// reabrindo o modal (auditoria de 2026-09-25). E o que acende nele DIANTE da
// pessoa fica visto, depois do redesenho (`verConquistasNaTela`).
let redesenhoDoHistoricoAgendado = false;
function agendarRedesenhoDoHistorico() {
    if (redesenhoDoHistoricoAgendado) return;
    redesenhoDoHistoricoAgendado = true;
    queueMicrotask(() => {
        redesenhoDoHistoricoAgendado = false;
        if (!historicoNaTela()) return;
        renderHistory();
        verConquistasNaTela();
    });
}

// A conquista (ou a patente) que destrava com o painel do Histórico NA TELA
// acende ali, com a etiqueta "nova", diante da pessoa: é ter visto, como entrar
// na aba (`switchFilterTab`) — o redesenho põe o anel, e a marca o mantém nesta
// abertura (`novasDestaAbertura`). Ela seguia em `novas`: fechado o modal,
// o ponto do botão de Filtros ficava aceso ("Filtros — conquista nova"), e o
// toque seguinte era desviado pro Histórico, com o pulso, pra mostrar o que a
// pessoa acabara de ver (R12-7-01, MEDIDO nos dois motores; auditoria de
// 2026-10-07).
//
// Só com a PÁGINA À VISTA. O painel também é redesenhado pelo aviso de OUTRA
// aba (`aoGravarEmOutraAba`): esta aba no fundo, com o Histórico aberto, dava
// por vista a conquista que a outra acabou de acender, e o ponto de lá apagava
// sem ninguém ter olhado. Escondida, quem marca é a VOLTA à página
// (`verConquistasAoVoltar`), com o painel ainda na tela.
function verConquistasNaTela() {
    if (document.visibilityState === 'hidden' || !historicoNaTela()) return;
    marcarConquistasVistas();
}

// A página VOLTOU à vista com o Histórico aberto e algo novo nele — destravado
// com ela no fundo, nesta aba ou noutra: o redesenho mostra, e dá por visto.
function verConquistasAoVoltar() {
    if (document.visibilityState !== 'visible' || !historicoNaTela() || !temConquistaNova()) return;
    agendarRedesenhoDoHistorico();
}

function htmlPatente() {
    const g = carregarConquistas();
    const s = getHistoryStats();
    const tratados = s.total.read + s.total.rejected;
    const i = patenteDe(tratados);
    const atual = PATENTES[i], prox = PATENTES[i + 1] || null;
    const pct = prox ? Math.max(0, Math.min(100,
        Math.round(((tratados - atual.min) / (prox.min - atual.min)) * 100))) : 100;
    const nome = (r) => escapeHtml(t('conq.rank.' + r.id));

    // O degrau atual leva `aria-current`: o "●" que o marca é aria-hidden, e sem
    // isto quem usa leitor de tela ouvia seis degraus iguais (auditoria de
    // 2026-09-25). Lista, pra o leitor anunciar o tamanho e a posição.
    const degraus = escadaAberta ? PATENTES.map((r, k) => `
        <div role="listitem" class="conq-deg${k === i ? ' aqui' : ''}"${k === i ? ' aria-current="step"' : ''}>
            <span class="e">${r.emoji}</span><span class="n">${nome(r)}</span>
            <span class="a tnum">${r.min}</span>
            <span class="m" aria-hidden="true">${k < i ? '✓' : k === i ? '●' : ''}</span>
        </div>`).join('') : '';

    const patenteNova = g.patenteNova || !!(novasDestaAbertura && novasDestaAbertura.patente);
    return `<div class="conq-card${patenteNova ? ' nova' : ''}">
        <div class="conq-topo">
            <span class="conq-emoji" aria-hidden="true">${atual.emoji}</span>
            <div class="conq-id">
                <div class="conq-eyebrow">${escapeHtml(t('conq.patente.titulo'))}</div>
                <div class="conq-nome">${nome(atual)}</div>
            </div>
            <div class="conq-tot tnum"><span class="conq-num">${tratados}</span><br>
                <span class="conq-sub">${escapeHtml(t('conq.patente.tratados'))}</span></div>
        </div>
        <div class="conq-barra"><i style="width:${pct}%"></i></div>
        <div class="conq-rodape conq-sub tnum">
            <span>${prox ? escapeHtml(t(prox.min - tratados === 1 ? 'conq.patente.faltamUm' : 'conq.patente.faltam',
                { n: prox.min - tratados, p: prox.emoji + ' ' + t('conq.rank.' + prox.id) }))
                : escapeHtml(t('conq.patente.topo'))}</span>
            <button type="button" id="conqEscadaBtn" class="conq-link" aria-expanded="${escadaAberta}">${
                escapeHtml(t(escadaAberta ? 'conq.patente.verMenos' : 'conq.patente.ver'))}</button>
        </div>
        ${escadaAberta ? `<div class="conq-escada" role="list">${degraus}</div>` : ''}
    </div>`;
}

function htmlConquistas() {
    const g = carregarConquistas();
    const lista = conquistasVisiveis();
    const ganhas = lista.filter((x) => g.c[x.id]).length;
    // 3 colunas; o CSS cai pra 2 abaixo de 400px. Em 4 a célula fica estreita
    // demais e uma coluna estica pra caber o nome mais longo — medido.
    const grade = lista.map((x, k) => {
        const on = !!g.c[x.id];
        const sel = conquistaTocada === x.id;
        const nova = g.novas.includes(x.id) || !!(novasDestaAbertura && novasDestaAbertura.ids.includes(x.id));
        // O ESTADO vai no nome acessível: ganha e trancada se distinguem só pela
        // COR (WCAG 1.4.1), e o leitor de tela ouvia "Coruja, botão" nas duas —
        // o `aria-pressed` é outra coisa (a condição aberta na linha abaixo da
        // grade). Texto invisível, sem mudança nenhuma na tela (auditoria de
        // 2026-09-25).
        const estado = t(on ? 'conq.estado.ganha' : 'conq.estado.trancada');
        return `<button type="button" class="conq-cel ${on ? 'on' : 'off'}${sel ? ' sel' : ''}${nova ? ' nova' : ''}"
            data-conq="${escapeHtml(x.id)}" aria-pressed="${sel}">
            <span class="e" aria-hidden="true">${x.emoji}</span>
            <span class="n">${escapeHtml(t('conq.' + x.id + '.nome'))}</span>` +
            `<span class="sr-only">, ${escapeHtml(estado)}</span>` +
            (nova ? `<span class="conq-tag">${escapeHtml(t('conq.nova'))}</span>` : '') +
            `</button>`;
    }).join('');
    const tocada = conquistaTocada && lista.find((x) => x.id === conquistaTocada);
    // A condição mora AQUI e não dentro da célula: na largura da grade ela
    // esticaria a coluna pelo mesmo motivo acima, e a frase é bem mais longa
    // que o nome.
    const dica = tocada
        ? `<p class="conq-dica" id="conqDica"><span><b>${tocada.emoji} ${escapeHtml(t('conq.' + tocada.id + '.nome'))}</b>`
          + ` — ${g.c[tocada.id] ? '✓ ' : ''}${escapeHtml(t('conq.' + tocada.id + '.como'))}</span></p>`
        : '';
    return `<div class="conq-h"><h4>${escapeHtml(t('conq.titulo'))}</h4>`
         + `<span class="tnum">${escapeHtml(t('conq.de', { a: ganhas, b: lista.length }))}</span></div>`
         + `<div class="conq-grade">${grade}</div>${dica}`;
}

// Liga os toques DEPOIS da inserção no DOM. Delegado ao container: o innerHTML
// é reescrito a cada render e listener em filho morre junto.
function ligarConquistas(el) {
    el.addEventListener('click', (ev) => {
        const b = ev.target.closest('#conqEscadaBtn');
        if (b) { escadaAberta = !escadaAberta; renderHistory(); return; }
        const c = ev.target.closest('[data-conq]');
        if (!c) return;
        const id = c.getAttribute('data-conq');
        conquistaTocada = conquistaTocada === id ? null : id;
        renderHistory();
        // A linha nasce ABAIXO da grade e, tocando uma célula de cima, ela cai
        // fora da tela — a explicação apareceria onde ninguém vê. `nearest` rola
        // o mínimo, então quando já está visível nada se mexe sob o dedo.
        if (conquistaTocada) {
            document.getElementById('conqDica')?.scrollIntoView({ block: 'nearest' });
        }
    });
}

// ═══════════════════════════════════════════════════════════════════════════
//  Resumo do mês — a imagem que a pessoa manda no grupo
// ═══════════════════════════════════════════════════════════════════════════
//
// Uma imagem 4:5 (1080×1350 — o formato que WhatsApp e Instagram não cortam)
// gerada NO APARELHO, com canvas e zero dependência, a partir do histórico por
// dia que o app já guarda. Celebra uma vez, quando a pessoa pede, e não
// pressiona ninguém: não há sequência, meta nem ranking aqui — só o mês.
//
// Escura de propósito, e só escura: é pra saltar no fundo claro do WhatsApp.
//
// O que ela NÃO mostra ainda, e por quê: "pulados" e "onde" (estados) exigem
// que o histórico passe a gravar dado que hoje não grava. É formato novo com
// migração — fica como etapa própria, decidida à parte.
//
// A fonte é a Inter auto-hospedada, que vai só até o peso 700 (ver
// css/styles.css). Pedir 800/900 aqui não dá erro: o browser SINTETIZA o
// negrito ou cai no fallback, em silêncio. `test/resumo.test.mjs` reprova
// qualquer peso acima de 700 nesta seção.
const RESUMO_LARGURA = 1080;
const RESUMO_ALTURA = 1350;

// Dados PUROS do mês-calendário, a partir do histórico por dia. Sem DOM, sem
// i18n, sem relógio — é o que o teste fatia e exercita sem browser.
//
// Note a diferença pro "Este mês" da aba Histórico, que é uma JANELA de 30
// dias: aqui é o mês do calendário, porque é assim que a pessoa fala do mês
// ("meu setembro") e é isso que o título da imagem promete.
function dadosDoResumo(h, ano, mesIdx) {
    const prefixo = `${ano}-${String(mesIdx + 1).padStart(2, '0')}-`;
    const diasNoMes = new Date(ano, mesIdx + 1, 0).getDate();
    const serie = new Array(diasNoMes).fill(0);
    let lidos = 0, rejeitados = 0, diasAtivos = 0;
    let forte = { dia: 0, n: 0 };
    for (const [k, v] of Object.entries(h || {})) {
        if (k === '_total' || !v || typeof v !== 'object' || !k.startsWith(prefixo)) continue;
        const dia = parseInt(k.slice(prefixo.length), 10);
        if (!(dia >= 1 && dia <= diasNoMes)) continue;
        const r = v.read || 0, j = v.rejected || 0, n = r + j;
        lidos += r; rejeitados += j;
        serie[dia - 1] = n;
        if (n > 0) diasAtivos++;
        // Empate: o dia mais CEDO vence — regra explícita, e não a ordem em que
        // as chaves estão no objeto, que ninguém garante.
        if (n > forte.n || (n > 0 && n === forte.n && dia < forte.dia)) forte = { dia, n };
    }
    return { ano, mesIdx, diasNoMes, lidos, rejeitados, total: lidos + rejeitados, diasAtivos, forte, serie };
}

// Desenho puro: recebe o contexto, os dados e os TEXTOS já traduzidos. Nada
// de `t()` aqui dentro — quem chama escolhe a palavra, e este código só
// posiciona. Pesos de fonte: só 400/500/600/700.
function desenharResumo(ctx, d, tx, { qr = null, logo = null, hoje = null } = {}) {
    const W = RESUMO_LARGURA, H = RESUMO_ALTURA, PAD = 80;
    const fonte = (peso, tam) => `${peso} ${tam}px Inter, system-ui, -apple-system, sans-serif`;
    const rr = (x, y, w, h, r) => {
        ctx.beginPath(); ctx.moveTo(x + r, y);
        ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
        ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
    };
    const texto = (s, x, y, peso, tam, cor, alinhar = 'left', espaco = 0) => {
        ctx.font = fonte(peso, tam); ctx.fillStyle = cor; ctx.textAlign = alinhar; ctx.textBaseline = 'alphabetic';
        if ('letterSpacing' in ctx) ctx.letterSpacing = espaco + 'px';
        ctx.fillText(s, x, y);
        if ('letterSpacing' in ctx) ctx.letterSpacing = '0px';
        return ctx.measureText(s).width;
    };
    const cartao = (x, y, w, h) => {
        rr(x, y, w, h, 22);
        ctx.fillStyle = 'rgba(255,255,255,0.06)'; ctx.fill();
        ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(255,255,255,0.10)'; ctx.stroke();
    };

    // Fundo
    const g = ctx.createRadialGradient(W * 0.8, -H * 0.1, 0, W * 0.8, -H * 0.1, 1300);
    g.addColorStop(0, '#164e63'); g.addColorStop(0.55, '#0f172a'); g.addColorStop(1, '#020617');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

    // Cabeçalho: marca à esquerda, período à direita
    if (logo) {
        ctx.save(); rr(PAD, 72, 46, 46, 12); ctx.clip(); ctx.drawImage(logo, PAD, 72, 46, 46); ctx.restore();
    } else {
        rr(PAD, 72, 46, 46, 12); ctx.fillStyle = '#0891b2'; ctx.fill();
    }
    texto(tx.marca, PAD + 60, 104, 700, 26, '#ffffff');
    texto(tx.periodo, W - PAD, 104, 600, 22, '#67e8f9', 'right', 2);

    // O número
    texto(tx.limpou, PAD, 232, 500, 28, '#a5f3fc');
    texto(tx.total, PAD, 380, 700, 168, '#ffffff', 'left', -6);
    texto(tx.pedidos, PAD, 445, 600, 34, '#e2e8f0');

    // Duas caixas grandes: rejeitados · lidos
    const gap = 18, wCol = (W - PAD * 2 - gap) / 2;
    tx.tiles.forEach(([n, rotulo, cor], i) => {
        const x = PAD + i * (wCol + gap), y = 520;
        cartao(x, y, wCol, 138);
        texto(n, x + 24, y + 70, 700, 52, cor);
        texto(rotulo, x + 24, y + 108, 400, 21, '#cbd5e1');
    });

    // Duas caixas pequenas: dia mais forte · dias ativos
    {
        const y = 676;
        cartao(PAD, y, wCol, 122);
        texto(tx.forteRotulo, PAD + 24, y + 40, 400, 18, '#94a3b8', 'left', 1.2);
        const w1 = texto(tx.forteValor + ' · ', PAD + 24, y + 88, 700, 30, '#ffffff');
        texto(tx.forteN, PAD + 24 + w1, y + 88, 700, 30, '#67e8f9');
        const x2 = PAD + wCol + gap;
        cartao(x2, y, wCol, 122);
        texto(tx.ativosRotulo, x2 + 24, y + 40, 400, 18, '#94a3b8', 'left', 1.2);
        texto(tx.ativosValor, x2 + 24, y + 88, 700, 30, '#ffffff');
    }

    // O mês dia a dia: uma barra por dia. Dia futuro sai apagado; o mais forte
    // acende. É o que dá a esta imagem a forma DAQUELE mês, e não de um modelo.
    {
        const y = 822, h = 230, x0 = PAD + 24, x1 = W - PAD - 24;
        cartao(PAD, y, W - PAD * 2, h);
        texto(tx.serieRotulo, x0, y + 40, 400, 18, '#94a3b8', 'left', 1.2);
        const n = d.serie.length, gapB = 6, wB = (x1 - x0 - gapB * (n - 1)) / n;
        const topo = y + 68, alt = 120, max = Math.max(1, ...d.serie);
        for (let i = 0; i < n; i++) {
            const v = d.serie[i];
            const futuro = hoje !== null && i + 1 > hoje;
            const hb = futuro ? 4 : (v > 0 ? Math.max(4, Math.round((v / max) * alt)) : 4);
            const bx = x0 + i * (wB + gapB), by = topo + alt - hb;
            rr(bx, by, wB, hb, Math.min(4, wB / 2));
            ctx.fillStyle = futuro ? 'rgba(255,255,255,0.08)'
                : (i + 1 === d.forte.dia && v > 0 ? '#67e8f9' : (v > 0 ? 'rgba(103,232,249,0.45)' : 'rgba(255,255,255,0.12)'));
            ctx.fill();
        }
        // Marcas de dia embaixo — só as que cabem: 1, 10, 20 e o último.
        const marcas = [1, 10, 20, n].filter((m, i, a) => a.indexOf(m) === i && m <= n);
        for (const m of marcas) {
            const cx = x0 + (m - 1) * (wB + gapB) + wB / 2;
            texto(String(m), cx, topo + alt + 26, 400, 14, '#64748b', 'center');
        }
    }

    // Rodapé: quem é, a frase, e o QR pro app
    texto(tx.editor, PAD, 1218, 400, 24, '#94a3b8');
    // A frase pode não caber ao lado do QR em idioma mais longo: encolhe até caber.
    for (let tam = 24; tam >= 18; tam -= 2) {
        ctx.font = fonte(600, tam);
        if (ctx.measureText(tx.tagline).width <= 700) { texto(tx.tagline, PAD, 1258, 600, tam, '#67e8f9'); break; }
        if (tam === 18) texto(tx.tagline, PAD, 1258, 600, 18, '#67e8f9');
    }
    if (qr && qr.modulos) {
        const QUIET = 2, lado = qr.tamanho + QUIET * 2, esc = Math.floor(150 / lado), px = lado * esc;
        const bx = W - PAD - px - 12, by = H - PAD - px - 12;
        rr(bx - 12, by - 12, px + 24, px + 24, 14); ctx.fillStyle = '#ffffff'; ctx.fill();
        ctx.fillStyle = '#0f172a';
        for (let l = 0; l < qr.tamanho; l++) {
            for (let c = 0; c < qr.tamanho; c++) {
                if (qr.modulos[l][c]) ctx.fillRect(bx + (c + QUIET) * esc, by + (l + QUIET) * esc, esc, esc);
            }
        }
    }
}

// Os TEXTOS da imagem, prontos no idioma de quem gera (é aqui que o i18n
// entra), e o `alt` dela. Separado do desenho e da espera pela fonte e pelo QR
// pra o teste conferir o que a imagem DIZ sem canvas nenhum.
function textosDoResumo(d, perfil, loc) {
    const p = perfil || {};
    // SEM PERFIL (a abertura com sinal ruim, antes de o /Session responder) não
    // há nome nem nível pra afirmar: a imagem saía " limpou" sem nome e "Editor
    // L1" — um nível FALSO, que a entrada (L2+AM) nem admite. As duas linhas
    // somem; com perfil, o desenho é o de sempre (auditoria de 2026-09-25).
    const selos = [];
    if (Number.isInteger(p.rank)) selos.push('L' + (p.rank + 1));
    if (p.isStaff) selos.push(t('profile.tag.staff'));
    else if (p.isAreaManager) selos.push(t('profile.tag.am'));
    const mesNome = new Date(d.ano, d.mesIdx, 1).toLocaleDateString(loc, { month: 'long' });
    // O dia mais forte com o MÊS, no formato do locale: só com dia e dia da
    // semana o inglês saía "21 Monday". Dia da semana e mês por extenso juntos
    // não cabem no cartão (MEDIDO, Inter 700 30px com "· 1234": até 555px pra
    // 403 úteis); dia e mês cabem nas quatro línguas, no pior mês (351px).
    const forteData = d.forte.dia
        ? new Date(d.ano, d.mesIdx, d.forte.dia).toLocaleDateString(loc, { day: 'numeric', month: 'long' })
        : '—';
    // Plural por CHAVE, e o 1 é o caso comum no começo do mês: saía "1
    // rejeitados", "1 lidos" e "1 pedidos do mapa" (auditoria de 2026-09-25).
    const pedidos = t(d.total === 1 ? 'resumo.img.pedidosUm' : 'resumo.img.pedidos');
    const rejeitados = t(d.rejeitados === 1 ? 'resumo.img.rejeitadosUm' : 'resumo.img.rejeitados');
    const lidos = t(d.lidos === 1 ? 'resumo.img.lidosUm' : 'resumo.img.lidos');
    const tx = {
        marca: 'WazePlaces',
        periodo: (mesNome + ' · ' + d.ano).toLocaleUpperCase(loc),
        limpou: p.userName ? t('resumo.img.limpou', { nome: p.userName }) : '',
        total: String(d.total),
        pedidos,
        tiles: [
            [String(d.rejeitados), rejeitados, '#fb7185'],
            [String(d.lidos), lidos, '#34d399'],
        ],
        forteRotulo: t('resumo.img.diaForte'), forteValor: forteData, forteN: String(d.forte.n),
        ativosRotulo: t('resumo.img.diasAtivos'),
        ativosValor: t('resumo.img.diasDe', { n: d.diasAtivos, de: d.diasNoMes }),
        serieRotulo: t('resumo.img.diaADia', { mes: mesNome }),
        editor: selos.length ? t('resumo.img.editor', { selos: selos.join(' · ') }) : '',
        tagline: t('resumo.img.tagline'),
    };
    // O `alt` diz o que a imagem diz, COM os números: "Resumo do mês" era tudo
    // o que o leitor de tela ouvia de uma imagem feita de números.
    const alt = t('resumo.img.altDetalhe', {
        alt: t('resumo.img.alt'), mes: mesNome, ano: d.ano,
        frase: [tx.limpou, tx.total, tx.pedidos].filter(Boolean).join(' '),
        rejeitados: d.rejeitados + ' ' + rejeitados, lidos: d.lidos + ' ' + lidos,
        forteRotulo: tx.forteRotulo, forte: forteData, forteN: d.forte.n,
        ativosRotulo: tx.ativosRotulo, ativos: tx.ativosValor,
    });
    return { tx, mesNome, alt };
}

// Espera a fonte e o QR, e desenha. Devolve null quando o mês está vazio — o
// botão nem aparece nesse caso, mas a função se defende sozinha.
async function gerarResumoDoMes() {
    const agora = new Date();
    const d = dadosDoResumo(loadHistory(), agora.getFullYear(), agora.getMonth());
    if (d.total === 0) return null;
    const { tx, mesNome, alt } = textosDoResumo(d, AppState.profile, i18nLocale());
    // A fonte precisa estar CARREGADA antes do fillText, senão o canvas desenha
    // com a fonte do sistema e o texto some do lugar. Falhar aqui não impede a
    // imagem — só a deixa na fonte do sistema.
    try {
        if (document.fonts && document.fonts.load) {
            await Promise.all([400, 500, 600, 700].map((w) => document.fonts.load(`${w} 24px Inter`)));
        }
    } catch (e) {}
    let qr = null;
    try { if (await carregarQr()) qr = gerarQR(location.origin); } catch (e) { qr = null; }
    let logo = null;
    try {
        const img = new Image();
        img.src = 'icons/icon-192.svg';
        await img.decode();
        logo = img;
    } catch (e) { logo = null; }
    const canvas = document.createElement('canvas');
    canvas.width = RESUMO_LARGURA; canvas.height = RESUMO_ALTURA;
    const hoje = (agora.getFullYear() === d.ano && agora.getMonth() === d.mesIdx) ? agora.getDate() : null;
    desenharResumo(canvas.getContext('2d'), d, tx, { qr, logo, hoje });
    return { canvas, mesNome, alt, nomeArquivo: `wazeplaces-${d.ano}-${String(d.mesIdx + 1).padStart(2, '0')}.png` };
}

// O que está na folha agora: o blob e o nome. Limpo em LIMPEZA_AO_FECHAR —
// modal fecha por três caminhos, e amarrar a limpeza a um deixa os outros vazando.
let resumoAtual = null;

async function abrirResumoDoMes() {
    // DE QUEM é o resumo. A geração espera a fonte, o QR (o `qr.js` vem pela
    // rede, sob demanda, na 1ª vez) e o logo, e nesse meio a pessoa pode ter
    // saído — o "Sair" noutra aba chega a qualquer hora —, a sessão pode ter
    // caído ou outra conta ter entrado. A folha abria DEPOIS, por cima da tela de
    // entrada, com o nome e os números de quem saiu, e o "Baixar" e o
    // "Compartilhar" vivos pra quem pegasse o aparelho (MEDIDO com o `qr.js`
    // segurado e o "Sair" na outra aba; auditoria de 2026-10-03, R8-7-04). Só
    // abre com a MESMA sessão e a MESMA conta, e com o Histórico — de onde ela
    // foi pedida — ainda na tela; senão a imagem é jogada fora, calada: quem saiu
    // não espera aviso dela, e quem fechou o Histórico desistiu.
    const epoca = epocaDaSessao;
    const conta = contaAgora();
    let r = null;
    try { r = await gerarResumoDoMes(); } catch (e) { r = null; }
    const blob = r ? await new Promise((res) => { try { r.canvas.toBlob(res, 'image/png'); } catch (e) { res(null); } }) : null;
    if (epoca !== epocaDaSessao || conta !== contaAgora() || !historicoNaTela()) return;
    if (!blob) { showToast(t('toast.resumoFalhou'), 'error'); return; }
    resumoAtual = { blob, nome: r.nomeArquivo, mesNome: r.mesNome };
    const img = document.getElementById('resumoImg');
    if (img.src) { try { URL.revokeObjectURL(img.src); } catch (e) {} }
    img.src = URL.createObjectURL(blob);
    img.alt = r.alt || t('resumo.img.alt');   // com os números (ver `textosDoResumo`)
    document.getElementById('resumoTitle').textContent = t('resumo.modal.title', { mes: r.mesNome });
    // Compartilhar só onde o aparelho compartilha ARQUIVO (Android, iOS 15+).
    // No desktop o botão some e fica o Baixar — nunca um botão que não faz nada.
    let podeCompartilhar = false;
    try {
        const arquivo = new File([blob], r.nomeArquivo, { type: 'image/png' });
        podeCompartilhar = !!(navigator.canShare && navigator.canShare({ files: [arquivo] }));
    } catch (e) { podeCompartilhar = false; }
    document.getElementById('resumoCompartilhar').classList.toggle('hidden', !podeCompartilhar);
    openModal('resumoModal');
}

async function compartilharResumo() {
    if (!resumoAtual) return;
    try {
        const arquivo = new File([resumoAtual.blob], resumoAtual.nome, { type: 'image/png' });
        await navigator.share({ files: [arquivo], title: 'WazePlaces', text: t('resumo.share.text', { mes: resumoAtual.mesNome }) });
        checarConquistas({ resumo: true });
    } catch (e) {
        // Cancelar a folha de compartilhar é escolha, não erro.
    }
}

function baixarResumo() {
    if (!resumoAtual) return;
    const a = document.createElement('a');
    a.href = URL.createObjectURL(resumoAtual.blob);
    a.download = resumoAtual.nome;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 30000);
    checarConquistas({ resumo: true });
}

// ═══════════════════════════════════════════════════════════════════════════
//  Recusa automática: os pedidos que chegam de um autor marcado
// ═══════════════════════════════════════════════════════════════════════════
//
// É o único recurso do app que decide sobre pedido que ainda não existia quando
// o editor escolheu. Duas coisas foram desenhadas contra o instinto:
//
// 1. PORTÃO. Só L6+AM ou staff — champs e staff do Waze, não qualquer editor.
//    Foi a condição do owner pra o recurso existir, e é ela que sustenta o
//    resto: quem marca alguém aqui está fazendo julgamento informado sobre um
//    spammer persistente, não um toque apressado.
//
// 2. O PLACAR ANDA COM O ENVIO, não antes dele (`contarAoLandar`). Em todo o
//    resto do app o placar é otimista, porque existe uma janela de Desfazer que
//    devolve o número. Aqui não há janela: os pedidos vão direto, um a um. Se
//    a página morresse no meio de um laço já contado, o placar ficaria com
//    números que nunca saíram — e não haveria quando reconciliar. Contando ao
//    landar, o número na tela é sempre o que de fato foi enviado.
//
// Houve uma janela de 20s aqui, com aviso no futuro ("serão rejeitados") e
// oferta de cancelar. Saiu por decisão do owner, e o motivo é o que a linha do
// tempo mostrou: a janela começa quando o APP BUSCA a fila, não quando o editor
// escolhe — ou seja, sempre no meio de outro card. Vinte segundos parados sobre
// algo que ninguém está olhando não protegem; só atrasam. O que ficou no lugar
// é honesto sobre o mesmo fato: o aviso conta enquanto acontece.

function podeRecusarAutomaticoAqui() {
    // Função própria que delega, como os outros destrutivos: são decisões de
    // produto que hoje coincidem, e se o owner separar uma o call site não muda.
    return podeAgirComoL6Aqui();
}

// O interruptor mora no MESMO registro da contagem: a poda de 30 dias vale pros
// dois, e isso é o certo — autor que parou de mandar por um mês não precisa
// seguir com recusa automática armada.
function autoLigado(chave) {
    const e = loadAutores().r[String(chave)];
    return Array.isArray(e) && e[3] === 1;
}

function alternarAutoDoAutor(chave) {
    if (!podeRecusarAutomaticoAqui()) return;
    const a = loadAutores();
    const e = a.r[String(chave)];
    if (!Array.isArray(e)) return;
    e[3] = e[3] === 1 ? 0 : 1;
    salvarAutores(a);
    renderHistory();
}

// Uma execução por vez: a fila pode crescer de novo enquanto o laço corre, e
// duas passagens simultâneas mandariam o mesmo pedido duas vezes.
let recusaAutomaticaRodando = false;
// Mas o pedido que chega COM ela rodando não pode evaporar na trava: é a página
// que acabou de pousar com mais pedidos do autor. "Mais antigos" e "Perto de…"
// leem todas as páginas numa rajada, e a 2ª chegava com a recusa da 1ª no ar —
// os pedidos dela ficavam como card (MEDIDO: 5 rejeitados de 8; auditoria de
// 2026-09-29, V4). Anota e roda de novo no fim, como a fila de saída
// (`saidaPedidaDeNovo`): não vira laço, porque a passada seguinte só existe se
// alguém pedir DURANTE esta.
let recusaAutomaticaPedidaDeNovo = false;

// Chamado depois de a fila crescer. Tira os pedidos dos autores marcados e
// rejeita na hora, um a um, com o aviso contando quantos faltam.
async function aplicarRecusaAutomatica() {
    if (!podeRecusarAutomaticoAqui()) return;
    // A lista de autores é do APARELHO: só age com ela quem se confirmou dono
    // dela nesta sessão (ver `contaConfirmada`).
    if (!contaConfirmada()) return;
    // Quem é ALVO. O card NA TELA fica de fora: o interruptor diz "os
    // PRÓXIMOS", e é ligado justamente olhando um card do autor — que sumia e era
    // rejeitado. Pior: a busca pousando durante os 350 ms da saída de um card
    // trocava o da frente, e o gesto em curso rejeitava o SEGUINTE, que ninguém
    // tinha visto. Com o da tela fora dos alvos, a recusa nunca troca o card
    // debaixo do dedo.
    // E o pedido EM ANDAMENTO também (`pedidosEmAndamento`): o lote de lidos
    // deixa os pedidos dele na fila até a resposta, e o perfil que chega no
    // meio dele (a prova de rede do próprio lote refaz o perfil que faltava)
    // rodava a recusa sobre eles — lido E rejeitado, duas decisões.
    // E o que a OUTRA aba decidiu (R10-2-02): o card anotado que saiu da tela
    // por uma troca de ordem segue na fila, e a recusa o mandaria de novo.
    const alvoFora = (naTela) => (x) => x && x !== naTela && x.creatorId !== undefined && x.creatorId !== null
        && !pedidosEmAndamento.has(chaveDoPedido(x)) && autoLigado(x.creatorId)
        && !(typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(x) === true);
    // No treino a fila da tela é de EXEMPLOS: a recusa fica ANOTADA, e o
    // `Treino.sair()` a roda na fila real quando ela voltar. Só sair perdia a 2ª
    // passada — a que a página que pousou com a 1ª no ar pediu
    // (`recusaAutomaticaPedidaDeNovo`, já zerada aqui) — quando a 1ª terminava
    // com o treino aberto: os pedidos do autor marcado voltavam como card
    // (auditoria de 2026-10-03, R8-7-03 = R8-2-03, MEDIDO no navegador).
    // Anotada só quando HÁ o que recusar na fila REAL (com o card que volta à
    // frente no "Sair" de fora, como lá): o perfil que chega no treino pede a
    // recusa a todo L6+AM, e o relatório dizia "a recusa automática pedida com o
    // treino aberto roda no Sair" sem autor nenhum marcado (R10-4-06; auditoria
    // da rodada 10).
    if (Treino.ativo) {
        if (filaReal().some(alvoFora(Treino._salvo ? Treino._salvo.currentPlace : null))) Treino.anotarRecusa();
        return;
    }
    if (recusaAutomaticaRodando) { recusaAutomaticaPedidaDeNovo = true; return; }
    const alvos = (AppState.queue || []).filter(alvoFora(AppState.currentPlace));
    if (alvos.length === 0) return;

    recusaAutomaticaRodando = true;
    // Zera ao ENTRAR, não ao sair: o que interessa é o pedido que chegar DAQUI
    // pra frente (ver `recusaAutomaticaPedidaDeNovo`).
    recusaAutomaticaPedidaDeNovo = false;
    const n = alvos.length;
    // A REGIÃO em que estes pedidos estão, fixada agora (a da fila que os
    // trouxe): trocar a região em Filtros com o laço no ar mandava o resto pro
    // servidor errado, que responde "não encontrado" — e isso conta como "já
    // tratado por outro editor", com o pedido pendente (auditoria da fila,
    // 2026-09-26). É a mesma regra do gesto (ver `API.markAsRead`). E o dia e o
    // lugar, pelo mesmo motivo, pro Histórico (`carimboDoGesto`, R6-7-4).
    const regiao = API.getRegion();
    const gesto = carimboDoGesto();
    // Saem da fila ANTES de enviar: senão o editor veria como card o pedido que
    // o app já está rejeitando, e poderia agir nele — dois envios pro mesmo.
    // E a fila que esvazia aqui é trabalho feito, não "nada com estes filtros"
    // (ver `recusaAutomaticaNestaFila`, R6-2-11): marcado ANTES, porque o painel
    // vazio sai logo (a abertura não espera o envio).
    recusaAutomaticaNestaFila = true;
    const fora = new Set(alvos);
    AppState.queue = AppState.queue.filter((x) => !fora.has(x));
    updatePendingCount();
    aoMudarAFilaPorBaixo();
    // Fora da fila, o aviso da OUTRA aba não os alcança (ele anota o que está na
    // fila): o que a pessoa decidir lá daqui pra frente fica pela CHAVE, com a
    // hora (`decididoNaOutraAbaDepoisDe`), e é conferido antes de cada ida
    // (R12-2-01). `=== true`: os harnesses devolvem objeto verdadeiro pra nome
    // que não conhecem (a régua da anotação).
    const desde = Date.now();
    const decididoNaOutraAba = (p) => typeof decididoNaOutraAbaDepoisDe === 'function'
        && decididoNaOutraAbaDepoisDe(p, desde) === true;

    // O aviso é só ACOMPANHAMENTO: conta enquanto acontece e some quando acaba.
    // Decisão do owner — "a ideia do toast é só informar". Não sobra banner
    // depois, porque depois não há nada a informar: o trabalho terminou.
    //
    // O prazo é folgado (10 min) de propósito: quem dispensa é o `finally`, não
    // o relógio. Ele existe só pra que uma falha exótica no laço não deixe o
    // aviso preso na tela pra sempre.
    //
    // Quem falhou VOLTA PRA FILA (ver `enviarLote`) e reaparece como card —
    // é esse o retorno em caso de erro. O aviso de fim que existia aqui dizia
    // "N rejeitados" com o N ORIGINAL, então mentia justamente quando algo
    // dava errado.
    //
    // E diz de QUEM é o que ainda falta. Com dois autores marcados na mesma
    // leva, o aviso nomeava só o primeiro e atribuía a ele os pedidos do outro
    // (auditoria de 2026-09-25). O lote anda EM ORDEM (`enviarLote`), então o
    // que falta é o fim da lista: com mais de um autor ali, a frase não nomeia
    // ninguém; com um só, volta a nomear — e agora é verdade.
    const andando = (q) => {
        const falta = alvos.slice(alvos.length - q);
        const autores = new Set(falta.map((x) => String(x.creatorId)));
        if (autores.size > 1) return t('auto.andandoAutores', { n: q, a: autores.size });
        const autor = falta[0].createdBy || String(falta[0].creatorId);
        return t(q === 1 ? 'auto.andando' : 'auto.andandoPlural', { n: q, autor });
    };
    const aviso = showToast(andando(n), 'hint', 600000);
    try {
        await enviarLote(alvos, {
            silencioso: true,
            contarAoLandar: true,
            regiao,
            gesto,
            // As condições da ENTRADA, lidas de novo antes de CADA ida ao Waze
            // (ver `aindaVale` no `enviarLote`): desligar o interruptor do autor
            // (ou o "Esquecer") com a recusa no ar não parava nada — os pedidos
            // que faltavam seguiam saindo como rejeitados, no nome da pessoa, e
            // com o "Esquecer" o autor voltava à lista, recriado por essas
            // rejeições (MEDIDO no navegador: 4 depois do gesto, nos dois casos;
            // auditoria de 2026-10-07, R10-2-01). O portão e a conta também. E o
            // que a OUTRA aba decidiu com a recusa no ar (R12-2-01): o pedido que a
            // pessoa marcou como lido lá saía daqui rejeitado, segundos depois.
            aindaVale: (p) => podeRecusarAutomaticoAqui() && contaConfirmada() && autoLigado(p.creatorId) && !decididoNaOutraAba(p),
            // Esse está DECIDIDO: não volta pra fila como card (seria decidido de
            // novo aqui) — sai, e o "Restam" desce, como no aviso de lá.
            decididoNaOutraAba,
            aoProgredir: (faltam) => {
                if (faltam > 0) aviso.texto(andando(faltam));
            },
        });
    } finally {
        recusaAutomaticaRodando = false;
        // Acabou: o aviso sai. Desligar o automático de alguém continua onde
        // sempre esteve — o interruptor da lista, na aba Histórico.
        aviso.dispensar();
        // Quem falhou voltou pra fila (ver `enviarLote`).
        aoMudarAFilaPorBaixo();
    }
    // A página que pousou com esta rodando é atendida AGORA (as guardas do
    // topo seguem valendo, e sem alvo nenhum ela sai na primeira linha).
    if (recusaAutomaticaPedidaDeNovo) {
        recusaAutomaticaPedidaDeNovo = false;
        return aplicarRecusaAutomatica();
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  A série de um autor: ver primeiro, ou rejeitar os que estão na fila
// ═══════════════════════════════════════════════════════════════════════════
//
// Abre pelo selo `✕ N`. NÃO há tela de confirmação depois: o número vai no
// próprio botão e o aviso diz o que o toque faz (com o Desfazer, os segundos da
// janela dele; sem, que já envia) — que é exatamente o que uma segunda pergunta
// carregaria. Confirmação que só repete o número treina todo mundo a tocar sem
// ler.
//
// O lote vai UM A UM, e isso não é preguiça: o lote atômico do WME falha
// INTEIRO quando outro editor já tratou um dos itens (o mesmo caso que o app
// já sabe tratar como `already_processed`). N requisições que sempre terminam
// valem mais que uma que às vezes morre inteira.
const ICONE_OLHO = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">'
    + '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/>'
    + '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5'
    + 'c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>';
const ICONE_X = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">'
    + '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>';
// A lixeira é a MESMA da lista do Histórico — mesmo conceito, mesmo ícone em
// todo o app. Era um `const lixo` local do `renderAutores`; virou módulo quando
// a folha do autor passou a oferecer o mesmo esquecer.
const ICONE_LIXO = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">'
    + '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"'
    + ' d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0'
    + ' 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>';
// Raio = "acontece sozinho", que é exatamente o que a recusa automática faz.
const ICONE_RAIO = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">'
    + '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>';

// A SÉRIE de um autor na fila — a régua ÚNICA do selo "Ver +N", da folha ("Ver
// os N", "Rejeitar os N"), do lote, do toque que põe a série na frente
// (`focarAutor`, `manterFocoNaFrente`) e da barra "Primeiro os de X · N de M".
// Eram duas réguas: o selo, a folha e o lote já deixavam de fora o pedido EM
// ANDAMENTO (R5-2-02), e a série do toque e a barra contavam a fila inteira — o
// selo dizia "Ver +1", o toque punha 3 na frente (o da aprovação no meio,
// travado) e a barra dizia "3 de 4" (MEDIDO, s33; auditoria de 2026-10-02,
// R6-2-02).
//
// · O pedido EM ANDAMENTO (`pedidosEmAndamento`: a aprovação de foto no ar)
//   fica FORA. Decidir sobre ele seria a SEGUNDA decisão — MEDIDO, a foto que a
//   pessoa APROVOU saía rejeitada no Waze pelo "Rejeitar os N", com "Restam 0" e
//   um card na tela (R5-2-02) —, e posto na frente ele chegava travado no meio
//   da série. Vai pro resto da fila; se a aprovação não valer, ele volta à série
//   (`refazerSelosSeOutroNaTela`).
// · O card NA TELA (`naTela`) conta sempre, mesmo em andamento: ele já está na
//   frente e é nele que a pessoa tocou — tirá-lo da série trocaria o card
//   debaixo do dedo. Com a aprovação DELE no ar, a folha dizia "Este é o único
//   dela na fila agora" e sumia com o "Ver/Rejeitar" com outro pedido do autor
//   na fila (MEDIDO, s40, R6-2-03).
// · `todos`: a FRASE da folha fala do AUTOR ("Há N na fila agora") e conta os
//   pedidos dele que ESTÃO na fila, em andamento ou não: "o único" com outro ali
//   é falso. Só a frase; o que decide não os leva.
// · O que a OUTRA aba já decidiu (`decididosPorOutraAbaComCardAqui`) fica FORA,
//   em todos os modos — mesmo o card da tela, que é onde ele fica (ver
//   `tirarDaFilaOQueAOutraAbaDecidiu`). Contado, o "Rejeitar os 3" mandava 2, e
//   o 3º era descontado calado no envio: a folha dizia "2 pedidos · ✓ 2
//   rejeitados" sem dizer do outro (MEDIDO no navegador, n08 da rodada 11;
//   R11-2-06, decisão: fora da série, sem texto novo). Fora da série, o card da
//   tela segue NA FRENTE (`manterFocoNaFrente`, `focarAutor`).
function serieDoAutor(id, { naTela = null, todos = false } = {}) {
    if (id === null || id === undefined || id === '') return [];
    return (AppState.queue || []).filter((x) => x && x.creatorId === id
        && !(typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(x) === true)
        && (todos || x === naTela || !pedidosEmAndamento.has(chaveDoPedido(x))));
}

// O que o LOTE decide ("Rejeitar os N") e o que o "Ver +N" conta além do card:
// a série SEM nada em andamento — nem o card da tela, se a aprovação dele está
// no ar (a trava recusa o lote nessa hora; esta é a segunda camada). É a régua
// do "Marcar todos" (V7) e da recusa automática.
function pedidosDoAutorNaFila(place) {
    return serieDoAutor(place && place.creatorId);
}

// O "Rejeitar os N" da folha. Pelo TECLADO (R5-2-06), fechar a folha devolve o
// foco ao "✕ N", que sai com o card que o lote tira da tela, e o resultado do
// lote, ao fechar, largava o foco no <body> (MEDIDO; o CONTROLE, abrir a folha e
// fechar com Esc, devolve ao "✕ N"). O ✕ do card que fica é prometido (C10) e
// pousa quando o card destravar — antes de o resultado abrir, que então o
// devolve a ele. Decidido ANTES de fechar: fechar move o foco.
function rejeitarPelaFolha(ev, place, contados) {
    const peloTeclado = veioDoTeclado(ev);
    closeModal('autorModal');
    if (peloTeclado) focoDoTeclado = BOTAO_DA_ACAO.left;
    rejeitarLoteDoAutor(place, contados);
}

// O "Ver os N" da folha. Pelo TECLADO, fechar a folha devolve o foco ao "✕ N", e
// o `focarAutor` remonta o card — o selo sai com ele, e o foco caía no <body>
// (MEDIDO no lote 9 da fila; o CONTROLE, a folha fechada com Esc, devolve ao
// "✕ N"). O foco vai à barra "Primeiro os de…", o caminho de volta — o mesmo
// par do Enter no selo "Ver +N" (`focarDepoisDoFocoNoAutor`). Decidido ANTES de
// fechar: fechar move o foco.
function verPelaFolha(ev, place) {
    const peloTeclado = veioDoTeclado(ev);
    closeModal('autorModal');
    focarAutor(place.creatorId);
    if (peloTeclado) focarDepoisDoFocoNoAutor(true);
}

// A folha se adapta ao TAMANHO da fila, e é essa adaptação que justifica o selo
// vermelho ser sempre tocável.
//
// Com MAIS DE UM pedido na fila há trabalho em lote de verdade: ver todos na
// frente, rejeitar todos de uma vez (destrutivo, sem Desfazer depois de enviado).
//
// Com UM SÓ — o caso de ~3 em cada 4 cards — essas duas linhas seriam o card que
// já está na tela, com os três botões logo abaixo: a de rejeitar faria o MESMO
// que o ✕ (o lote tem a mesma janela de Desfazer do card, ver
// `rejeitarLoteDoAutor`), só que num segundo lugar. Então elas somem, e o que
// fica é o que o card NÃO consegue mostrar:
//   · o que "✕ N" quer dizer — o `title` do selo não existe no toque, e este é o
//     único jeito de descobrir num celular o que aquele número conta;
//   · a recusa automática deste autor, que hoje só se alcança por Filtros →
//     Histórico, rolando até achar a pessoa;
//   · o esquecer, pra quando você discorda da contagem.
// Esses três valem nos DOIS tamanhos, então ficam sempre — fora do TREINO, onde
// a folha não oferece o que escreve (ver `noTreino`, R9-7-05).
function abrirFolhaDoAutor(place) {
    if (!place) return;
    const corpo = document.getElementById('autorCorpo');
    const titulo = document.getElementById('autorTitle');
    if (!corpo || !titulo) return;
    // A série deste autor pela régua ÚNICA (`serieDoAutor`), com o card da tela:
    // é o que o "Ver os N" põe na frente e o que o "Rejeitar os N" mostra — o
    // mesmo número do "Ver +N" (mais o card) e da barra depois do toque. A FRASE
    // ("Há N na fila agora") fala do autor e conta os pedidos dele que estão na
    // fila, inclusive o em andamento (R6-2-03).
    const naFila = serieDoAutor(place.creatorId, { naTela: place });
    const doAutorNaFila = serieDoAutor(place.creatorId, { todos: true }).length;
    const emLote = naFila.length > 1;
    // No TREINO a folha abre de um card de EXEMPLO — o clone de um pedido real,
    // com o autor de verdade —, e as linhas que ESCREVEM escreviam de verdade: o
    // interruptor ARMAVA a recusa automática deste autor (depois do "Sair" do
    // treino e do ↻, as rejeições foram ao Waze no nome da pessoa), e o
    // "Rejeitar os N" era oferecido pra ser recusado com a frase do "Marcar
    // todos" (R9-7-05 = R9-2-04, MEDIDO no navegador; auditoria de 2026-10-06).
    // Como os botões da foto, que somem no treino, a folha não oferece o que
    // escreve: o "Rejeitar os N" (e o aviso vermelho dele), o interruptor e o
    // "Esquecer". Ficam a frase que explica o "✕ N" e o "Ver os N", que só põe
    // os exemplos do autor na frente.
    const noTreino = typeof Treino !== 'undefined' && Treino.ativo === true;
    const rejeitarEmLote = emLote && !noTreino;
    // O lote passa pela janela do Desfazer como o card (`scheduleAction`): com
    // ela, "começa ao tocar" e "tocar já escreve no Waze" eram falsos — o
    // banner abria e nada saía (auditoria de 2026-09-29, A10). As frases seguem
    // o estado de verdade, pela mesma pergunta que decide o envio.
    const semJanela = semJanelaDeDesfazer();
    const chave = String(place.creatorId);
    const nome = place.createdBy || chave;
    titulo.textContent = nome;
    const linha = (ic, cor, t1, t2, id) =>
        `<button type="button" id="${id}" class="flex items-center gap-3 w-full min-h-[56px] py-2 text-left`
        + ` border-b border-slate-100 dark:border-slate-700 last:border-0">`
        + `<span class="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${cor}">${ic}</span>`
        + `<span class="flex-1 min-w-0"><span class="block text-[0.9375rem] font-semibold text-slate-800 dark:text-slate-100 leading-tight">`
        + `${escapeHtml(t1)}</span><span class="block text-xs text-slate-500 dark:text-slate-400 leading-snug mt-0.5">`
        + `${escapeHtml(t2)}</span></span></button>`;
    // O interruptor é uma LINHA-label, não um botão: o alvo de 44px é a linha
    // inteira (aqui dá, ao contrário da lista do Histórico, que também tem a
    // lixeira na mesma linha e um toque perto dela alternaria sem querer).
    const linhaAuto = () =>
        `<label class="flex items-center gap-3 w-full min-h-[56px] py-2 text-left cursor-pointer`
        + ` border-b border-slate-100 dark:border-slate-700 last:border-0">`
        + `<span class="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0`
        + ` bg-rose-100 text-rose-700 dark:bg-rose-500/20 dark:text-rose-300">${ICONE_RAIO}</span>`
        + `<span class="flex-1 min-w-0"><span class="block text-[0.9375rem] font-semibold text-slate-800 dark:text-slate-100 leading-tight">`
        + `${escapeHtml(t('stats.autores.auto'))}</span><span class="block text-xs text-slate-500 dark:text-slate-400 leading-snug mt-0.5">`
        + `${escapeHtml(t('stats.autores.autoDesc'))}</span></span>`
        + `<input type="checkbox" id="autorAuto" class="ui-switch flex-shrink-0"${autoLigado(chave) ? ' checked' : ''}></label>`;
    // A frase NÃO diz período: a contagem acumula desde que o autor entrou na
    // lista, e os 30 dias são o prazo pra ele SAIR sem rejeição nova — dizia
    // "nos últimos 30 dias" e mostrava 7 com 2 dentro da janela (auditoria de
    // 2026-09-25).
    corpo.innerHTML =
        `<p class="text-[0.8125rem] text-slate-500 dark:text-slate-400 mb-4 leading-snug">`
        + `${escapeHtml(t(doAutorNaFila > 1 ? 'autor.sheet.sub' : 'autor.sheet.subUm',
                          { n: contagemDoAutor(place), fila: doAutorNaFila }))}</p>`
        + (emLote
            ? linha(ICONE_OLHO, 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300',
                    t('autor.sheet.ver', { n: naFila.length }), t('autor.sheet.ver.desc'), 'autorVer')
              + (rejeitarEmLote
                  ? linha(ICONE_X, 'bg-rose-100 text-rose-700 dark:bg-rose-500/20 dark:text-rose-300',
                          t('autor.sheet.rejeitar', { n: naFila.length }),
                          t(semJanela ? 'autor.sheet.rejeitar.descSemDesfazer' : 'autor.sheet.rejeitar.desc'), 'autorRejeitar')
                  : '')
            : '')
        // Mesmo portão da lista do Histórico: mostrar o interruptor desabilitado
        // anunciaria um recurso que a pessoa não pode usar, e o app não faz isso.
        + (!noTreino && podeRecusarAutomaticoAqui() ? linhaAuto() : '')
        + (noTreino ? '' : linha(ICONE_LIXO, 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300',
                                 t('stats.autores.esquecer'), t('autor.sheet.esquecer.desc'), 'autorEsquecer'))
        // O aviso é da rejeição em LOTE, então acompanha a linha que ele descreve
        // (a MESMA condição). Sem ela na tela, um aviso vermelho sobre "não há
        // segunda pergunta" descreveria o interruptor errado — e o interruptor
        // tem a própria frase.
        + (rejeitarEmLote
            ? `<p class="mt-4 text-xs leading-relaxed text-rose-800 dark:text-rose-200 bg-rose-50 dark:bg-rose-500/10`
              + ` border border-rose-100 dark:border-rose-500/30 rounded-xl px-3 py-2.5">`
              + `${t(semJanela ? 'autor.sheet.avisoSemDesfazer' : 'autor.sheet.aviso')}</p>`
            : '');
    if (emLote) {
        document.getElementById('autorVer').addEventListener('click', (ev) => verPelaFolha(ev, place));
    }
    if (rejeitarEmLote) {
        // Só os que a folha CONTOU e mostrou no botão (L21): a busca que pousa
        // com ela aberta traz mais pedidos do autor, e o toque rejeitava esses
        // também — "Rejeitar os 2", e saíam 4. É a régua do "Marcar todos"
        // (`loteDeLidosContado`): o que o app mostra é o que ele aceita.
        const contados = naFila.map(chaveDoPedido);
        document.getElementById('autorRejeitar').addEventListener('click', (ev) => rejeitarPelaFolha(ev, place, contados));
    }
    const auto = document.getElementById('autorAuto');
    // Relê o estado depois de alternar em vez de confiar no `.checked`: se o
    // `alternarAutoDoAutor` recusar (registro sumiu por poda entre o render e o
    // toque), o interruptor volta sozinho em vez de mentir que ligou.
    if (auto) auto.addEventListener('change', () => {
        alternarAutoDoAutor(chave);
        auto.checked = autoLigado(chave);
    });
    if (!noTreino) document.getElementById('autorEsquecer').addEventListener('click', (ev) => esquecerPelaFolha(ev, chave));
    openModal('autorModal');
}

// O "Esquecer" da folha. O selo que abriu a folha some agora — fechar deixando o
// `✕ N` na tela faria o app afirmar uma contagem que ela acabou de apagar —, e o
// card é refeito. Pelo TECLADO, fechar a folha devolve o foco ao "✕ N", que sai
// com o card refeito, e o foco caía no <body> (MEDIDO nos dois motores, s44; o
// CONTROLE, a folha fechada com Esc, devolve ao "✕ N"; auditoria de 2026-10-02,
// R6-2-12). Era o terceiro botão que fecha a folha, e os outros dois ("Ver os N",
// "Rejeitar os N") já tinham destino. O foco vai ao "Ver +N" do card, se houver,
// senão ao primeiro de ✕ ↑ ✓ vivo — e, travado, ao ✕ prometido: o destino da
// barra que some (`focarDepoisDoFocoNoAutor`). Decidido ANTES de fechar.
function esquecerPelaFolha(ev, chave) {
    const peloTeclado = veioDoTeclado(ev);
    closeModal('autorModal');
    esquecerAutor(chave);
    removeCurrentCardEl();
    showCurrentPlace();
    if (peloTeclado) focarDepoisDoFocoNoAutor(false);
}

// O lote, com a MESMA janela de Desfazer de um card só — a trava dos botões, o
// banner com a contagem, o `resetQueue`. A diferença é `aoSair: 'cancel'`.
//
// `contados`: as chaves que a folha contou ao abrir. O lote é a INTERSEÇÃO
// delas com a fila de agora — nunca mais que o número que o botão mostrou, e
// sem os que saíram da fila nesse meio.
function rejeitarLoteDoAutor(place, contados) {
    // Sem sessão o lote não sai (a folha pode seguir aberta durante a renovação
    // pela extensão), e a folha já fechou com o toque: diz por quê. ANTES da
    // trava, que também é verdadeira sem sessão e diria "espere o Desfazer". O
    // aviso é o da trava sem sessão: na renovação silenciosa, o da espera
    // (R5-2-07), não "Sessão expirada".
    if (!AppState.authenticated) { showToast(t(avisoDaTrava()), 'info'); return; }
    // Na janela do Desfazer nada prossegue — mas a folha já FECHOU com o toque,
    // e sair calado deixava a pessoa achando que rejeitou (auditoria de
    // 2026-09-25). Diz o que fazer.
    if (acoesTravadas()) { showToast(t(avisoDaTrava()), 'info'); return; }
    // Segunda camada: no treino a folha nem oferece o "Rejeitar os N" (R9-7-05),
    // e a fila da tela é de exemplos — um lote aqui decidiria sobre clones.
    if (Treino.ativo) { showToast(t('treino.semLote'), 'info'); return; }
    const naFolha = Array.isArray(contados) ? new Set(contados) : null;
    const places = pedidosDoAutorNaFila(place).filter((p) => !naFolha || naFolha.has(chaveDoPedido(p)));
    if (places.length === 0) { showToast(t('toast.batchEmpty'), 'info'); return; }
    const n = places.length;
    // Otimista, como o card único: o placar anda agora e volta no Desfazer.
    AppState.stats.rejected += n;
    AppState.serverTotal = Math.max(0, AppState.serverTotal - n);
    updateStats();
    saveStats();
    const ids = new Set(places);
    AppState.queue = (AppState.queue || []).filter((x) => !ids.has(x));
    AppState.currentPlace = null;
    updatePendingCount();
    // ANTES dos `show*`: o lote que esvazia a fila desenha o painel vazio aqui
    // mesmo, e sem a marca ele dizia "Confira o país e a região", sem festa,
    // logo depois de a pessoa rejeitar tudo (auditoria da fila, 2026-09-26).
    tratouNestaFila = true;
    if (AppState.queue.length > 0) { removeCurrentCardEl(); showCurrentPlace(); maybePrefetch(); }
    else if (AppState.hasMore) { removeCurrentCardEl(); startFetching(); }
    else { removeCurrentCardEl(); showNoPlaces(); }
    const regiao = API.getRegion();   // a do GESTO: ver `API.markAsRead`
    const gesto = carimboDoGesto();   // o dia e o lugar do GESTO (R6-7-4)
    scheduleAction('reject', places, () => enviarLote(places, { regiao, gesto }), { aoSair: 'cancel' });
}

// Um a um, e o resultado NÃO é um número só: cada pedido tem destino próprio.
// "Já tratado por outro editor" conta como cumprido — é a mesma regra que o app
// usa no card único, e chamá-lo de falha aqui daria dois nomes à mesma coisa.
// `silencioso` existe pra recusa automática: lá quem presta contas é o banner
// (que já diz o número e oferece desligar), e abrir a folha por cima do card
// seria o app interrompendo por algo que o editor não pediu.
// `contarAoLandar` troca o placar OTIMISTA pelo placar que anda junto com o
// envio. O lote manual (que tem janela de Desfazer) precisa do otimista: ele
// mostra o resultado antes de mandar, e o Desfazer devolve. A recusa automática
// não tem janela nenhuma — contar antes ali criaria uma divergência que ninguém
// pode reconciliar se a página morrer no meio do laço.
// `aoProgredir` recebe quantos AINDA FALTAM, pra quem quiser mostrar.
// `aindaVale(p)` é conferido antes de CADA ida ao Waze — a primeira e cada
// retentativa —, e o pedido em que ele diz não fica de fora e volta pra fila: é a
// recusa automática relendo, a cada pedido, as condições que a fizeram começar
// (R10-2-01). A ida que já está no ar segue: não há como cancelá-la.
async function enviarLote(places, opts = {}) {
    // `fila` = foi pra fila de SAÍDA (sem rede): nem "foi pro Waze" nem "falhou".
    // `aprovada` = quem o resolveu foi a APROVAÇÃO desta pessoa, cuja resposta se
    // perdeu (R8-2-01, ver `aprovacaoDelaJaPousou`): nem rejeitado, nem "outro
    // editor" — e a folha não o conta.
    // `naoVale` = o `aindaVale` disse não antes de ele sair (R10-2-01): não foi ao
    // Waze e voltou pra fila — nem rejeitado, nem falha.
    const conta = { ok: 0, fila: 0, ja: 0, erro: 0, aprovada: 0, naoVale: 0 };
    const epoca = epocaDaSessao;
    // E QUEM decide — a sessão e a conta desta mesma hora —, pro pouso que chegar
    // depois de uma queda no meio do laço (R13-2-01, ver o ramo da época abaixo).
    // Aqui e não no gesto, como a época: a janela do Desfazer do "Rejeitar os N"
    // não atravessa uma queda (ela a cancela), e a recusa automática não tem janela.
    const quem = typeof quemDecideAgora === 'function' ? quemDecideAgora() : null;
    // A FILA em que o lote começou. O ↻ e a troca de filtro no meio do laço a
    // refazem (`resetQueue`): a nova já vem sem os pedidos que faltam (estão em
    // andamento), então nem o "Restam" dela desce pelos pousos daqui, nem o que
    // falhar entra nela — era "Restam 0" com 5 cards na tela (auditoria da fila,
    // 2026-09-26). O que falhou volta pela busca, se for da fila nova.
    //
    // E com o TREINO aberto a fila do lote não foi refeita: está GUARDADA nele, e
    // volta no `sair()` com a época dela (`Treino.filaGuardada`). A recusa
    // automática no meio do laço, com a pessoa entrando no treino, pousava "fora
    // da fila do lote": o "Restam" não descia pelos pousos do treino, e a fila
    // real voltava com "Restam 6" sobre 3 cards — "Tudo limpo!" com "Restam 3"
    // no fim (R7-2-03, MEDIDO no navegador; auditoria de 2026-10-02).
    const epocaFila = AppState.fetchEpoch;
    const filaDoLote = () => {
        if (typeof Treino !== 'undefined' && Treino.ativo === true) return Treino.filaGuardada(epocaFila);
        return AppState.fetchEpoch === epocaFila ? AppState.queue : null;
    };
    const naFilaDoLote = () => filaDoLote() !== null;
    // Os que voltam pra fila de pedidos. Na recusa automática (contando ao
    // landar) o "Restam" nunca desceu por eles: voltam pro fim da fila do lote,
    // sem somar. O lote da PESSOA volta como o ✕ de um card volta
    // (`devolverPedidoRecusado`): como o PRÓXIMO card na fila do gesto, com o
    // "Restam" subindo junto — ia pro FIM, e a pilha seguia anunciando outro
    // pedido (auditoria de 2026-09-29, C5) —, ou pela busca numa fila refeita, que
    // agora busca na hora se a tela ficou sem card (ficava "Tudo limpo!" com os
    // pedidos pendentes, V9). Juntos, no fim, na ordem do lote.
    const devolver = [];
    const voltarPraFila = (q) => {
        const fila = aoLandar ? filaDoLote() : null;
        if (fila) { fila.push(q); return; }
        devolver.push(q);
    };
    const placar = AppState.stats;    // o do GESTO: ver `descontarGestoSemSessao`
    const aoLandar = !!opts.contarAoLandar;
    const progresso = () => {
        if (aoLandar) { updateStats(); saveStats(); updatePendingCount(); }
        if (opts.aoProgredir) opts.aoProgredir(places.length - conta.ok - conta.fila - conta.ja - conta.erro - conta.aprovada - conta.naoVale, conta);
    };
    // Em andamento até cada um resolver: uma busca que chegue no meio não os
    // traz de volta como card (ver `semOsJaDecididos`). A marca mora AQUI e não
    // só no `scheduleAction` porque a recusa automática chega sem passar por
    // ele — ela tira os pedidos da fila e manda direto.
    marcarEmAndamento(places, true);
    // O lote da PESSOA vai INTEIRO pra fila de saída antes do primeiro envio
    // (O2, ver `anotarAntesDoEnvio`): o placar já contou os N no gesto, e fechar
    // o app no meio do laço deixava os que não saíram em lugar nenhum — de volta
    // como card na reabertura, contados de novo. Anotados, a reabertura não os
    // devolve e o esvaziamento os manda. Cada resposta tira o seu. Na recusa
    // automática não: lá o placar anda com o envio, e o que não saiu volta pela
    // busca, de graça.
    const anotados = new Set();
    // A decisão destes JÁ esperava na fila de saída: vale a primeira (ver
    // `enfileirarSaida`), e o do lote não sai nem conta — a mesma regra da
    // descarga.
    const repetidos = new Set();
    let esperavamAntes = 0;
    // Uma leitura e uma gravação pro lote inteiro (ver a `lista` do
    // `enfileirarSaida`).
    if (!aoLandar) {
        const lista = carregarFilaDeSaida();
        esperavamAntes = lista.length;
        for (const p of places) {
            const r = enfileirarSaida('reject', p, opts.regiao, { ...opts.gesto, ...reivindicacaoDestaAba() }, true, lista);
            if (r === true) anotados.add(p);
            else if (r === 'repetida') repetidos.add(p);
        }
        if (anotados.size) {
            salvarFilaDeSaida(lista);
            updateInFlightIndicator();
        }
        if (repetidos.size) {
            marcarEmAndamento([...repetidos], false);
            placar.rejected = Math.max(0, (placar.rejected || 0) - repetidos.size);
            updateStats();
            saveStats();
        }
    }
    // A fila de saída ABRIU por este lote: a transição vai pro diário uma vez
    // (a anotação antes do envio é calada, ver `enfileirarSaida`).
    let abriuAnotado = false;
    const ficouNaSaida = () => {
        if (abriuAnotado || esperavamAntes > 0) return;
        abriuAnotado = true;
        dfato('saida.abriu', { tipo: 'reject' });
    };
    AppState.inFlightActions++;
    updateInFlightIndicator();
    // A recusa AUTOMÁTICA confere antes de CADA ida ao Waze — a primeira e cada
    // retentativa do `callWithRetry` — que ainda vale pra este pedido
    // (`opts.aindaVale`, R10-2-01): o interruptor desligado, o "Esquecer", o
    // portão ou a conta que mudaram no meio do laço param o que falta, a partir
    // do gesto. A ida que já está no ar segue: não há como cancelá-la. Só no modo
    // que conta ao pousar: no lote da pessoa o pedido já está anotado na fila de
    // saída e contado no placar. A identidade do objeto é a marca: nada fora
    // daqui o lê.
    const naoVale = { success: false };
    const desistir = (p) => aoLandar && typeof opts.aindaVale === 'function' && !opts.aindaVale(p);
    try {
        for (const p of places) {
            if (repetidos.has(p)) continue;
            const r = await callWithRetry(() => (desistir(p)
                ? naoVale
                : API.rejectPlace(p.venueID, p.updateRequestID, null, opts.regiao)));
            // Saiu no meio (ver `epocaDaSessao`): nada grava — e, no placar
            // OTIMISTA do lote manual, o que não pousou (este, se não pousou, e
            // os que nem saíram) volta (K7). Contando ao pousar não há o que
            // voltar. A anotação deles na fila de saída SAI: ela não pode sair
            // depois com a sessão de agora. E, na renovação da queda, que mantém
            // a fila na tela, eles VOLTAM como card (V1): seguem pendentes no
            // Waze, já passaram pela fila, e nenhuma busca os trazia. Numa fila
            // refeita (o "Sair", outra conta) nada volta. E o que POUSOU tem o
            // pouso registrado, com a marca de quem decidiu (`quem`, lá no
            // começo; R13-2-01, ver `registrarPousoDepoisDaQueda`).
            if (epoca !== epocaDaSessao) {
                const i = places.indexOf(p);
                const pousou = pousouNoWaze(r);
                const naoPousaram = places.slice(i + (pousou ? 1 : 0)).filter((q) => !repetidos.has(q));
                for (const q of places.slice(i)) if (anotados.delete(q)) tirarDaFilaDeSaida('reject', q);
                if (pousou && typeof registrarPousoDepoisDaQueda === 'function') registrarPousoDepoisDaQueda(p, quem);
                if (!aoLandar) descontarGestoSemSessao('rejected', placar, naoPousaram.length);
                if (naFilaDoLote()) for (const q of naoPousaram) voltarPraFila(q);
                return;
            }
            // A OUTRA aba já o pousou e contou (ver `pousouPorOutraAba`): é decisão
            // desta pessoa que chegou ao Waze — sem contar de novo, nem como "outro
            // editor".
            const pousouNaOutra = () => anotados.delete(p) && tirarDaFilaDeSaida('reject', p) === false;
            if (r === naoVale) {
                // Não saiu: volta pra fila como o que a recusa automática não
                // conseguiu mandar (`voltarPraFila`: pro fim da fila do lote, sem
                // somar — o "Restam" nunca desceu por ele, e o card volta a
                // contar nele). Nem rejeitado, nem falha.
                conta.naoVale++;
                // Menos o que a OUTRA aba decidiu com o lote no ar
                // (`opts.decididoNaOutraAba`, R12-2-01): está decidido — de volta
                // como card, seria decidido de novo aqui. Sai, e o "Restam" desce
                // por ele, como desce no aviso de lá (só na fila do lote).
                if (typeof opts.decididoNaOutraAba === 'function' && opts.decididoNaOutraAba(p) === true) {
                    if (naFilaDoLote()) AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
                } else voltarPraFila(p);
            } else if (r && (r.success || r.errorCategory === 'already_processed' || r.errorCategory === 'not_found')
                && pousouNaOutra()) {
                conta.ok++;
                pousouPorOutraAba(p, 'reject');
            } else if (r && r.success) {
                conta.ok++;
                if (anotados.delete(p)) tirarDaFilaDeSaida('reject', p);
                registrarPouso(p);
                recordHistory('reject', 1, opts.gesto && opts.gesto.dia, opts.gesto && opts.gesto.onde);
                registrarRejeicaoDeAutor(p);
                if (aoLandar) {
                    AppState.stats.rejected++;
                    if (naFilaDoLote()) AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
                } else {
                    // O lote da PESSOA conta pras conquistas como o ✕ do card; a
                    // recusa automática (`aoLandar`) é o app agindo, e não conta.
                    registrarAcaoConfirmada('reject', p, opts.gesto);
                }
            } else if (r && (r.errorCategory === 'already_processed' || r.errorCategory === 'not_found')) {
                if (anotados.delete(p)) tirarDaFilaDeSaida('reject', p);
                registrarPouso(p);
                if (aoLandar) { if (naFilaDoLote()) AppState.serverTotal = Math.max(0, AppState.serverTotal - 1); }
                if (aprovacaoDelaJaPousou(p)) {
                    // Quem resolveu foi a APROVAÇÃO desta pessoa, cuja resposta se
                    // perdeu (R8-2-01): o desfecho é o dela, como no ✕ do card
                    // (`handleActionResult`) — nem "outro editor", nem a rejeição
                    // no Histórico e nas conquistas, e o "Curador" conta. O placar
                    // otimista do lote desce; contando ao pousar, ele nem subiu.
                    conta.aprovada++;
                    desfechoDaAprovacaoDela('reject', p, !aoLandar);
                } else {
                    conta.ja++;
                    // No placar otimista ele JÁ contou; o Histórico conta igual,
                    // como no card único (`handleActionResult`) — senão o placar e
                    // o Histórico divergiam por lote (auditoria de 2026-09-25). E
                    // as conquistas também, como lá: o "já tratado" do duplicado
                    // dava o "Detetive" pelo ✕ e não pelo lote, e a "Mão firme"
                    // andava um a menos (R6-7-9, auditoria de 2026-10-01).
                    if (!aoLandar) {
                        recordHistory('reject', 1, opts.gesto && opts.gesto.dia, opts.gesto && opts.gesto.onde);
                        registrarAcaoConfirmada('reject', p, opts.gesto);
                    }
                }
            } else if (r && r.errorCategory === 'unauthorized') {
                // O resto do lote não pode evaporar (ver o 401 no
                // `handleActionResult`): no placar otimista ele vai pra fila de
                // saída — onde a anotação de antes do envio já o pôs, e fica;
                // contando ao pousar, volta pra fila de pedidos. A marca desta aba
                // sai dos anotados: ela não os está mais mandando.
                soltarMarcaDosItens('reject', [...anotados]);
                for (const q of places.slice(places.indexOf(p))) {
                    if (repetidos.has(q)) continue;
                    marcarEmAndamento(q, false);
                    if (!aoLandar && (anotados.has(q) || enfileirarSaida('reject', q, opts.regiao, opts.gesto))) continue;
                    if (!aoLandar) AppState.stats.rejected = Math.max(0, AppState.stats.rejected - 1);
                    voltarPraFila(q);
                }
                // A fila de saída só ABRIU no placar otimista: contando ao pousar
                // (a recusa automática), nada foi pra ela — o que falta voltou pra
                // fila de pedidos —, e o diário dizia "saida.abriu" com ela vazia
                // (MEDIDO: `["saida.abriu","sessao.alarmeFalso"]` e a fila de
                // saída `[]`; auditoria de 2026-10-07, R10-2-07).
                if (!aoLandar) ficouNaSaida();
                handleUnauthorized();
                return;
            } else if (r && r.errorCategory === 'transient' && !aoLandar && (anotados.has(p) || enfileirarSaida('reject', p, opts.regiao, opts.gesto))) {
                // Rede, não recusa: o lote também entra na fila de saída, senão
                // a promessa ("nada do que você fez se perde") valeria só pro
                // swipe e não pro botão de rejeitar em lote. O placar otimista
                // fica (o trabalho foi feito), mas a folha NÃO o conta como
                // "foi pro Waze": ainda não foi — é a linha "esperando envio".
                //
                // `!aoLandar` NÃO é cinto e suspensório. Nesse modo (a recusa
                // automática) o placar só anda no `r.success`, e o pouso da fila
                // de propósito não soma nada — então enfileirar ali faria a ação
                // não contar em lugar NENHUM. E não há nada a salvar: o ramo de
                // erro já devolve o pedido pra `AppState.queue`, onde ele volta
                // a ser um card. O contrato daquele modo ("o número na tela é
                // sempre o que de fato foi enviado") continua valendo.
                conta.fila++;
                soltarMarcaDosItens('reject', [p]);
                ficouNaSaida();
            } else {
                conta.erro++;
                // Recusa de verdade: a anotação sai — repetir não muda a recusa.
                if (anotados.delete(p)) tirarDaFilaDeSaida('reject', p);
                // O que não saiu volta pra fila. Com o placar otimista é preciso
                // devolver o número junto; contando ao landar não há o que devolver,
                // porque o número nunca foi somado (ver `voltarPraFila`).
                if (!aoLandar) AppState.stats.rejected = Math.max(0, AppState.stats.rejected - 1);
                voltarPraFila(p);
            }
            // Resolvido: pousou, está na fila de saída, ou voltou pra fila.
            marcarEmAndamento(p, false);
            progresso();
        }
    } finally {
        // Todos, inclusive os que não chegaram a sair (sessão morta no meio).
        marcarEmAndamento(places, false);
        AppState.inFlightActions = Math.max(0, AppState.inFlightActions - 1);
        updateInFlightIndicator();
        updateStats();
        saveStats();
        // Os que voltam (ver `voltarPraFila`) entram DEPOIS de o "em andamento"
        // sair: a busca que a devolução dispara numa fila refeita não pode
        // filtrá-los. Com a sessão trocada no meio, só na fila que atravessou a
        // queda — nunca uma busca na fila de outra sessão.
        if (devolver.length && (epoca === epocaDaSessao || naFilaDoLote())) devolverPedidoRecusado(devolver, epocaFila);
        updatePendingCount();
        // O que falhou voltou pra fila (`voltarPraFila`). Sem card na tela — o
        // "Rejeitar os N" esvaziou a fila, ou a recusa automática levou tudo o
        // que a busca trouxe —, ninguém o desenhava: ele ficava ATRÁS do painel
        // vazio, com "Restam 1" e o "Tudo limpo!" na tela.
        if (!AppState.currentPlace && AppState.queue.length && AppState.authenticated) showCurrentPlace();
        // E a pilha: o card de fundo e o "Ver +N" do da frente passam a dizer o
        // que a fila tem agora (C5).
        aoMudarAFilaPorBaixo();
    }
    if (!opts.silencioso) mostrarResultadoDoLote(conta);
}

function mostrarResultadoDoLote(conta) {
    const corpo = document.getElementById('autorCorpo');
    const titulo = document.getElementById('autorTitle');
    if (!corpo || !titulo) return;
    const fila = conta.fila || 0;
    const total = conta.ok + fila + conta.ja + conta.erro;
    // Plural por CHAVE (sem ICU): "1 rejeitados" era o que saía com um só.
    const um = (n) => (n === 1 ? 'Um' : '');
    const linhas = [];
    if (conta.ok) linhas.push(['✓', 'bg-emerald-100 text-emerald-800 dark:bg-emerald-400/20 dark:text-emerald-300',
        t('autor.lote.rejeitados' + um(conta.ok), { n: conta.ok }), t('autor.lote.rejeitados.desc' + um(conta.ok))]);
    if (fila) linhas.push(['⏳', 'bg-amber-100 text-amber-800 dark:bg-amber-400/20 dark:text-amber-200',
        t('autor.lote.fila' + um(fila), { n: fila }), t('autor.lote.fila.desc' + um(fila))]);
    if (conta.ja) linhas.push(['👍', 'bg-sky-100 text-sky-800 dark:bg-sky-400/20 dark:text-sky-200',
        t('autor.lote.jaTratados' + um(conta.ja), { n: conta.ja }), t('autor.lote.jaTratados.desc' + um(conta.ja))]);
    if (conta.erro) linhas.push(['!', 'bg-rose-100 text-rose-800 dark:bg-rose-500/20 dark:text-rose-300',
        t('autor.lote.falharam' + um(conta.erro), { n: conta.erro }), t('autor.lote.falharam.desc' + um(conta.erro))]);
    if (!linhas.length) return;
    // Com OUTRA camada aberta — a foto ou o mapa ampliados, Filtros, outra
    // folha —, o resultado sai como AVISO, com as mesmas frases da folha, e a
    // camada fica. A folha abria por cima de qualquer uma: atrás da foto
    // ampliada, com o foco preso nela invisível, ou no lugar dos Filtros,
    // jogando fora a mudança ainda não aplicada (auditoria de 2026-09-29, L27).
    // Nada da folha é escrito antes: a aberta pode ser a de outro autor.
    //
    // O TREINO aberto entra na mesma regra: ele também está POR CIMA da fila em
    // que o lote foi decidido (o "Rejeitar os N" da janela do Desfazer que o
    // "Praticar" despacha). A folha abria sobre o card de treino, com a faixa
    // "nada é enviado ao Waze" e o "Foram pro Waze no seu nome" na mesma tela —
    // quem está aprendendo lia que o treino tinha mandado (R8-7-01, auditoria de
    // 2026-10-03). AVISO, e não a folha guardada pro `sair()`: abrir a folha
    // logo que o treino fecha cairia no MESMO tique do fechamento do fim do
    // treino (o `history.back()` pendente come a entrada nova, gotcha #65) ou
    // depois do voltar do aparelho, sem gesto novo — e é a regra que já vale
    // pra toda camada, sem mais um caminho de abrir diálogo pra manter.
    const outraCamada = !!topOpenModal()
        || (typeof Lightbox !== 'undefined' && Lightbox.isOpen())
        || (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen())
        || (typeof Treino !== 'undefined' && Treino.ativo === true);
    if (outraCamada) {
        showToast(linhas.map((l) => l[2]).join(' · '), conta.erro ? 'error' : fila ? 'info' : 'success');
        return;
    }
    titulo.textContent = t('autor.lote.titulo' + um(total), { n: total });
    const linha = (emoji, cor, t1, t2) =>
        `<div class="flex items-start gap-3 py-2.5 border-b border-slate-100 dark:border-slate-700 last:border-0">`
        + `<span class="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 text-base font-extrabold ${cor}"`
        + ` aria-hidden="true">${emoji}</span>`
        + `<span class="flex-1 min-w-0"><span class="block text-[0.9375rem] font-semibold text-slate-800 dark:text-slate-100 leading-tight">`
        + `${escapeHtml(t1)}</span><span class="block text-xs text-slate-500 dark:text-slate-400 leading-snug mt-0.5">`
        + `${escapeHtml(t2)}</span></span></div>`;
    corpo.innerHTML = linhas.map((l) => linha(...l)).join('');
    openModal('autorModal');
}

// ═══════════════════════════════════════════════════════════════════════════
//  Reincidência de autor — quantos pedidos DESTA pessoa você já rejeitou
// ═══════════════════════════════════════════════════════════════════════════
//
// O caso que originou: um entregador fotografa o PACOTE em cada parada, e o
// rótulo costuma trazer nome, endereço e telefone do destinatário. Não é foto
// ruim — é dado pessoal de terceiro indo pro mapa público, e o mesmo autor
// repete por semanas.
//
// O que o app NÃO consegue: distinguir esse autor do melhor contribuinte da
// fila pelos metadados. Medido — os dois são 100% foto, 1 foto por local, e o
// ritmo se sobrepõe. O único sinal que separa é a SUA rejeição repetida, e
// esse o app jogava fora: o histórico só guardava números por dia.
//
// ── POR QUE DUAS LISTAS, e não um mapa só ────────────────────────────────
// Medido na fila real (4.008 pedidos, 12 países, varredura só-leitura):
// 87% dos autores mandam UM pedido só (81–91% conforme o país), e a fila do
// owner recebe ~360 autores distintos por dia. Guardar todo autor rejeitado
// num mapa com nome e datas estouraria 2.000 registros em menos de uma semana
// e chegaria a 88 ms de gravação POR SWIPE — atacando exatamente o ritmo que
// o recurso existe pra devolver.
//
// Então quem foi rejeitado UMA vez mora num anel de ids (sem nome, sem data) e
// só é promovido ao mapa caro na SEGUNDA rejeição. Medido: 41 KB e 0,87 ms.
const AUTORES_KEY = 'waze_places_autores';
// Teto do mapa dos que repetiram. Ao encher, sai quem tem a rejeição mais
// antiga — é o que torna o custo CONSTANTE, não importa quantos anos de uso.
const AUTORES_MAX_REINCIDENTES = 500;
// Teto do anel dos vistos-uma-vez. Só ids, sem nome e sem data.
//
// O número sai dos 30 DIAS logo abaixo, não de performance — e essa é a parte
// que engana. O mapa expira por IDADE; o anel expira por CAPACIDADE. Se ele não
// segurar 30 dias de rejeições, o app deixa de promover quem foi rejeitado no
// dia 1 e no dia 25, porque o id do dia 1 já saiu por lotação. A promessa que o
// próprio card faz ("entra quem você rejeitou 2 vezes") quebra EM SILÊNCIO, e o
// editor não tem como perceber.
//
// Era 2.000, e a fila real do owner mostrou o buraco: 856 rejeições numa semana
// (~120/dia, ~100 delas entrando no anel) davam **19 dias** de memória contra os
// 30 prometidos. 4.000 deu ~38; hoje são 6.000, ~60.
//
// Performance NÃO é o limite aqui, e a tabela do mapa (mais acima, no
// CLAUDE.md) não vale pra este anel: ela mede `nome → [contagem, datas]`, que é
// muito mais pesado por entrada. MEDIDO no ciclo completo de uma rejeição
// (ler + procurar + gravar), num Chromium com a CPU 6× lenta:
//   anel 2.000 → 4,04 ms · 4.000 → 4,32 ms · 8.000 → 4,72 ms
// 6.000 não foi medido: cai ENTRE os dois últimos, abaixo de 4,72 ms. Um quadro
// a 60fps são 8,3 ms, então a faixa inteira é ruído. Tamanho no aparelho: 39,6
// KB a 2.000 e 63,0 KB a 4.000 — o de 6.000 também não foi medido.
//
// A folga extra compra o editor que rejeita MUITO mais que ~130 por dia, que
// era exatamente o caso que tornava 4.000 errado: com 6.000 a conta só volta a
// apertar acima de ~200/dia. O conserto definitivo continua sendo guardar o DIA
// junto do id e podar por idade, como o mapa faz — aí o teto deixa de ser
// palpite sobre o ritmo de quem usa. Fica como decisão separada: muda o formato
// gravado e exige migração.
const AUTORES_MAX_VISTOS = 6000;
// ANISTIA, e não só arrumação — a razão é do owner: "30 dias é para tirar a
// pessoa do castigo caso o editor esqueça de desmarcar do automático e/ou o
// editor use muito pouco o app". Ou seja, o prazo protege o AUTOR de um
// esquecimento nosso, não o arquivo do tamanho. Quem continua mandando tem a
// data renovada a cada rejeição (inclusive as automáticas), então o prazo só
// corre pra quem de fato parou.
const AUTORES_MAX_DIAS = 30;
// Quantas linhas a lista mostra antes do "Ver mais N". NÃO é gosto: medido na
// fila real do owner, 232 pedidos deram 174 autores distintos e 23 com 2+
// rejeições — e os 10 primeiros são os que repetem de verdade (o resto tem
// contagem 2–3). Cortar em 5 esconderia 8 de 13 num caso comum, o que faz do
// botão parada obrigatória em vez de atalho; cortar em 15 quase não cortaria.
//
// O ganho é a altura ficar CONSTANTE: medido a 390×844, a lista inteira custa
// 2,4 telas com 23 autores, 7,1 com 100 e 34,9 com 500 (59px por linha, sempre);
// com o teto são 1,2 tela em qualquer tamanho. Render nunca foi o problema
// (22ms com 500) — o custo é o polegar.
const AUTORES_VISIVEIS = 10;
// Acima disto o selo passa de cinza (o app CONTA) a rosa (o app DESTACA).
//
// Era 10, e a justificativa escrita aqui dizia que "o maior lote de um mesmo
// autor num único instantâneo foi 7", logo 10 exigiria repetição ENTRE buscas.
// REMEDIDO em 2026-09-01 nos 6 países obrigatórios, 1.967 autores: essa frase
// não vale mais. O maior lote num instantâneo é 30 (Espanha), com 25 em
// Portugal, 24 na França e 17 no Brasil — o 10 já era ultrapassado por uma
// única busca, então ele não garantia mais o que prometia.
//
// Baixar pra 6 é decisão do owner. O efeito medido: num instantâneo dos 6
// países, o rosa passaria de 6 para 17 autores — de 1.967, ou seja menos de 1%
// nos dois casos. Não é a diferença entre "discreto" e "gritante".
//
// Se um dia alguém quiser um limiar que signifique de novo "voltou em outro
// dia", o caminho não é o número: é comparar a DATA da primeira rejeição com a
// da última, que o registro já guarda.
const AUTOR_LIMIAR_DESTAQUE = 6;

// O dia de HOJE no calendário de quem usa, contado em dias desde 1970 — é o
// número que o registro guarda (`e[2]`) e o que a poda e o "rejeitado há N
// dias" comparam. Era o dia UTC (`Date.now() / 86400000`): no Brasil, das 21h à
// meia-noite já era "amanhã", então o rejeitado às 20h aparecia "há 1 dia" às
// 21h30 do mesmo dia, e o das 22h30 seguia "hoje" no dia seguinte inteiro
// (auditoria de 2026-09-25). A conta é de DATA, como no Histórico ("Dia é DATA,
// nunca 24 h"): o dia local vira um número pela data em UTC, sem horário de
// verão no meio. Registro gravado antes disto pode estar a um dia do certo — e
// se corrige sozinho na próxima rejeição, ou sai com a poda de 30 dias.
function diaDeHoje() {
    const d = new Date();
    return Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000;
}
// O dia de CALENDÁRIO local de um instante (ms), no mesmo eixo do `diaDeHoje()`:
// a diferença entre os dois é quantas datas separam o instante de hoje.
function diaLocalDe(ms) {
    const d = new Date(ms);
    return Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000;
}

function loadAutores() {
    // A cópia em memória só vale se a outra aba não gravou (ver `copiaEmDia`).
    if (copiaEmDia(AppState.autores, AUTORES_KEY)) return AppState.autores;
    let texto = null;
    try { texto = localStorage.getItem(AUTORES_KEY); } catch (e) { texto = null; }
    let a = null;
    try { a = JSON.parse(texto || 'null'); } catch (e) { a = null; }
    if (!a || typeof a !== 'object') a = {};
    if (!Array.isArray(a.v)) a.v = [];
    if (!a.r || typeof a.r !== 'object') a.r = {};
    AppState.autores = a;
    lembrarTextoDaCopia(a, AUTORES_KEY, texto);
    if (podarAutores(a)) salvarAutores(a);
    return a;
}

function salvarAutores(a) {
    try {
        localStorage.setItem(AUTORES_KEY, JSON.stringify(a));
        lembrarTextoDaCopia(a, AUTORES_KEY);
    } catch (e) {}
}

// Poda por TEMPO e por TETO, nessa ordem: o tempo tira o que não informa mais,
// o teto garante que o custo pare de crescer mesmo se o tempo não bastar.
function podarAutores(a) {
    let mudou = false;
    const limite = diaDeHoje() - AUTORES_MAX_DIAS;
    for (const id of Object.keys(a.r)) {
        const e = a.r[id];
        if (!Array.isArray(e) || !Number.isFinite(e[2]) || e[2] < limite) { delete a.r[id]; mudou = true; }
    }
    const ids = Object.keys(a.r);
    if (ids.length > AUTORES_MAX_REINCIDENTES) {
        // Sai quem tem a rejeição mais ANTIGA — não quem tem a menor contagem:
        // contagem alta e parada há um mês informa menos que contagem 2 de hoje.
        ids.sort((x, y) => (a.r[x][2] || 0) - (a.r[y][2] || 0));
        for (const id of ids.slice(0, ids.length - AUTORES_MAX_REINCIDENTES)) delete a.r[id];
        mudou = true;
    }
    if (a.v.length > AUTORES_MAX_VISTOS) { a.v = a.v.slice(-AUTORES_MAX_VISTOS); mudou = true; }
    return mudou;
}

// Chaveado pelo ID, nunca pelo nome. 69% dos autores da fila real são anônimos
// `world_xxxxx` — nome GERADO pra quem nunca escolheu um, e que muda no dia em
// que a pessoa escolhe. Pelo nome, o histórico sumiria justamente aí.
function registrarRejeicaoDeAutor(place) {
    const id = place && place.creatorId;
    if (id === null || id === undefined || id === '') return;
    const chave = String(id);
    const a = loadAutores();
    const nome = (place.createdBy && String(place.createdBy)) || chave;
    const hoje = diaDeHoje();
    if (a.r[chave]) {
        const e = a.r[chave];
        e[0] = (e[0] || 1) + 1;
        e[1] = nome;   // o nome de EXIBIÇÃO acompanha: se a pessoa escolheu um, mostra o novo
        e[2] = hoje;
    } else {
        const i = a.v.indexOf(chave);
        if (i === -1) {
            a.v.push(chave);
            if (a.v.length > AUTORES_MAX_VISTOS) a.v.shift();
        } else {
            a.v.splice(i, 1);
            a.r[chave] = [2, nome, hoje];
            podarAutores(a);
        }
    }
    salvarAutores(a);
}

// Quantas rejeições SUAS este autor acumulou. 0 ou 1 devolve 0: o anel não
// guarda contagem, e "1" não é reincidência — é uma rejeição.
function contagemDoAutor(place) {
    const id = place && place.creatorId;
    if (id === null || id === undefined || id === '') return 0;
    const e = loadAutores().r[String(id)];
    return Array.isArray(e) ? (e[0] || 0) : 0;
}

function esquecerAutor(chave) {
    const a = loadAutores();
    if (!a.r[chave]) return;
    delete a.r[chave];
    salvarAutores(a);
    renderHistory();
}

// Ordena por contagem, depois pelo mais recente — quem mais repetiu primeiro.
function listaDeAutores() {
    const a = loadAutores();
    return Object.entries(a.r)
        .map(([id, e]) => ({ id, n: e[0] || 0, nome: e[1] || id, dia: e[2] || 0 }))
        .sort((x, y) => (y.n - x.n) || (y.dia - x.dia));
}

function esquecerAutores() {
    AppState.autores = null;
    safeLS.remove(AUTORES_KEY);
}

// O registro guarda o DIA, não o instante — então a frase é em dias. Usar o
// `formatRelativeTime` do app (que desce a horas e minutos) fazia algo de hoje
// de manhã aparecer como "há 12h": precisão que o dado não tem.
//
// É o MESMO dia que a poda usa (`e[2]`), então esta linha é o relógio da
// anistia à vista: 30 dias depois do que ela mostra, o autor sai da lista.
function rejeitadoQuando(dia) {
    const n = diaDeHoje() - dia;
    if (!Number.isFinite(n) || n <= 0) return t('stats.autores.rejeitadoHoje');
    return t(n === 1 ? 'stats.autores.rejeitadoDias' : 'stats.autores.rejeitadoDiasPlural', { n });
}

// Expandido é estado de SESSÃO da lista, não preferência: o padrão é a lista
// curta, e reabrir o painel volta a ele (limpo em LIMPEZA_AO_FECHAR). Precisa
// sobreviver ao re-render, porém — o painel é redesenhado inteiro a cada
// esquecimento e a cada troca de interruptor, e perder a expansão ali jogaria
// o editor de volta pro topo no meio de uma faxina.
let autoresExpandido = false;

// A lista fica ABAIXO do placar do editor, nunca no lugar dele. E some inteira
// quando ninguém repetiu — seção vazia num painel curto é ruído, não informação.
function renderAutores() {
    const el = document.getElementById('autoresBody');
    if (!el) return;
    const foco = chaveDoFoco(el);   // o innerHTML abaixo mata o elemento focado
    const todas = listaDeAutores();
    if (todas.length === 0) { el.innerHTML = ''; devolverFocoAoPainel(el, foco); return; }
    // Só corta se SOBRA alguém: com 10 autores exatos nada é escondido e o botão
    // não existe. Botão dizendo "ver mais 0" — ou sumindo sem explicação — é pior
    // que não ter teto nenhum.
    const escondidas = autoresExpandido ? 0 : Math.max(0, todas.length - AUTORES_VISIVEIS);
    const linhas = escondidas > 0 ? todas.slice(0, AUTORES_VISIVEIS) : todas;
    const lixo = ICONE_LIXO;
    el.innerHTML =
        `<p class="text-sm font-semibold text-slate-700 dark:text-slate-200 mb-1">${escapeHtml(t('stats.autores.title'))}</p>`
        + `<p class="text-xs text-slate-500 dark:text-slate-400 mb-2 leading-snug">`
        + `${escapeHtml(t('stats.autores.desc', { dias: AUTORES_MAX_DIAS }))}`
        + (podeRecusarAutomaticoAqui() ? ' ' + escapeHtml(t('stats.autores.autoDesc')) : '')
        + `</p>`
        + linhas.map((a) =>
            // `flex-wrap` + `basis-full` na data: ela vai pra uma SEGUNDA linha,
            // com a largura inteira da lista. Dentro da coluna do nome ela não
            // cabia — o selo, o interruptor e a lixeira apertam essa coluna a
            // ~55px num Fold, e "rejeté il y a 22 jours" quebrava em TRÊS
            // pedaços. Medido: a largura do nome é a MESMA nos dois arranjos,
            // então isto não tira nada dele.
            `<div class="autor-lin flex flex-wrap items-center gap-x-2 min-h-[44px] border-b border-slate-100 dark:border-slate-700 last:border-0">`
            + `<span class="flex-1 min-w-0 text-sm font-medium text-slate-700 truncate dark:text-slate-200">${escapeHtml(a.nome)}</span>`
            + `<span class="selo-proc ${a.n >= AUTOR_LIMIAR_DESTAQUE ? 'selo-reinc' : 'selo-src'} flex-shrink-0">`
            + `✕ ${a.n}</span>`
            // O interruptor da recusa automática só EXISTE pra quem passa no
            // portão: mostrá-lo desabilitado anunciaria um recurso que a pessoa
            // não pode usar, e o app não faz isso em nenhum outro lugar.
            + (podeRecusarAutomaticoAqui()
                // O <label> de 44px é o ALVO; o interruptor em si tem 26px de
                // altura (componente padrão do app). Nas Preferências o alvo vem
                // da linha inteira ser um label — aqui não dá, porque a linha
                // também tem a lixeira, e um toque perto dela alternaria o
                // automático sem querer.
                ? `<label class="flex items-center min-h-[44px] flex-shrink-0 cursor-pointer">`
                  + `<input type="checkbox" class="ui-switch autor-auto"`
                  + ` data-autor="${escapeHtml(a.id)}"${autoLigado(a.id) ? ' checked' : ''}`
                  + ` title="${escapeHtml(t('stats.autores.auto'))}"`
                  // O NOME no rótulo: com dez linhas, dez controles iguais
                  // ("Rejeitar sozinho os próximos deste autor") não dizem de
                  // quem — e o leitor de tela lê um de cada vez.
                  + ` aria-label="${escapeHtml(t('stats.autores.auto.aria', { nome: a.nome }))}"></label>`
                : '')
            + `<button type="button" class="autor-esquecer min-w-[44px] min-h-[44px] flex items-center justify-center`
            + ` text-slate-500 hover:text-rose-600 dark:text-slate-400 dark:hover:text-rose-400 rounded-full flex-shrink-0"`
            + ` data-autor="${escapeHtml(a.id)}" title="${escapeHtml(t('stats.autores.esquecer'))}"`
            + ` aria-label="${escapeHtml(t('stats.autores.esquecer.aria', { nome: a.nome }))}">${lixo}</button>`
            // `-mt-1.5` recolhe a folga que o min-h-[44px] da linha de cima já
            // deixou: sem isso a data flutua longe do nome que ela descreve.
            + `<span class="basis-full text-[0.6875rem] text-slate-500 dark:text-slate-400 leading-tight -mt-1.5 pb-1.5">`
            + `${escapeHtml(rejeitadoQuando(a.dia))}</span>`
            + `</div>`).join('')
        // Largura cheia e 44px de alvo, como todo botão do app. O número vai NO
        // rótulo porque "Ver mais" sozinho não diz se são 3 ou 300 — e é isso que
        // decide se vale o toque. O "Ver menos" existe porque sem ele expandir é
        // irreversível sem fechar o modal.
        + (escondidas > 0 || autoresExpandido
            ? `<button type="button" id="autoresVerMais" class="w-full min-h-[44px] mt-2 mb-4`
              + ` border border-slate-300 dark:border-slate-600 rounded-lg text-sm font-semibold`
              + ` text-cyan-700 dark:text-cyan-400 hover:bg-slate-50 dark:hover:bg-slate-700 transition">`
              + `${escapeHtml(autoresExpandido
                    ? t('stats.autores.verMenos')
                    : t(escondidas === 1 ? 'stats.autores.verMais' : 'stats.autores.verMaisPlural',
                        { n: escondidas }))}</button>`
            : '');
    const verMais = document.getElementById('autoresVerMais');
    if (verMais) verMais.addEventListener('click', () => {
        autoresExpandido = !autoresExpandido;
        renderAutores();
        // Ao recolher, o botão sobe junto com a lista e o dedo fica sobre outra
        // coisa. Devolver a lista ao campo de visão é o mínimo pra não parecer
        // que o app pulou pra outro lugar.
        if (!autoresExpandido) el.scrollIntoView({ block: 'nearest' });
    });
    // Delegação seria mais curta, mas o painel é re-renderizado inteiro a cada
    // esquecimento — o listener por linha morre junto com a linha.
    for (const b of el.querySelectorAll('.autor-esquecer')) {
        b.addEventListener('click', () => esquecerAutorDaLista(b.dataset.autor));
    }
    for (const c of el.querySelectorAll('.autor-auto')) {
        c.addEventListener('change', () => alternarAutoDoAutor(c.dataset.autor));
    }
    devolverFocoAoPainel(el, foco);
}

// A lista de autores SAI do DOM quando o painel fecha e na tela de entrada (o
// "Sair", a queda): é nome e id de TERCEIRO, o mesmo dado que o
// `waze_places_autores` apaga. Na tela de entrada também porque a folha do
// autor redesenha o painel FECHADO (`esquecerAutor`, `alternarAutoDoAutor`),
// depois de a limpeza do fechamento o ter esvaziado (R6-1-05).
function esvaziarListaDeAutores() {
    const el = document.getElementById('autoresBody');
    if (el) el.innerHTML = '';
}

// E o painel INTEIRO, pelos mesmos caminhos (o painel que fecha, a tela de
// entrada, a troca de conta): a patente, os totais de hoje à semana, o botão do
// Resumo com o mês e a vitrine de conquistas são o trabalho de QUEM ESTAVA aqui.
// Só a lista de autores saía, e o resto ficava no DOM escondido — depois do
// "Sair" e na sessão da conta que entrou, que o levava no relatório do modo dev
// (MEDIDO; auditoria de 2026-10-03, R8-7-06). Esvaziar é seguro: o painel é
// desenhado ao ENTRAR na aba (`switchFilterTab`) e ao abrir os Filtros
// (`openFiltersModal`), e o ouvinte das conquistas mora no `#historyBody`, que
// fica.
function esvaziarPainelDoHistorico() {
    const el = document.getElementById('historyBody');
    if (el) el.innerHTML = '';
    esvaziarListaDeAutores();
}

// Esquecer pela LISTA do Histórico. O card da frente (atrás do modal) e o de
// fundo podem estar mostrando o `✕ N` desse autor, e sem refazer os dois o app
// seguia afirmando a contagem que a pessoa acabou de apagar — e o selo abria a
// folha dizendo "Você rejeitou 0 pedidos" (auditoria de 2026-09-25). A folha
// do autor já refazia; aqui é o mesmo, só quando o autor está NA TELA:
// refazer à toa devolveria o carrossel do card ao começo.
function esquecerAutorDaLista(chave) {
    esquecerAutor(chave);
    const naTela = [AppState.currentPlace, (AppState.queue || [])[1]]
        .some((p) => p && p.creatorId != null && String(p.creatorId) === String(chave));
    if (naTela && AppState.currentPlace) {
        removeCurrentCardEl();
        showCurrentPlace();
    }
}

// O painel do Histórico é redesenhado INTEIRO (innerHTML) a cada toque nele —
// célula de conquista, "ver a escada", interruptor e lixeira de autor, "Ver
// mais" —, e o elemento focado morre junto: o foco caía no `<body>`, e quem
// navega por teclado ou leitor de tela voltava pro começo da página a cada
// toque (auditoria de 2026-09-25). Estas duas carregam o foco até o elemento
// EQUIVALENTE do desenho novo, pela identidade que sobrevive ao innerHTML: o
// id, o `data-conq` da célula, ou o `data-autor` com a classe do controle.
// Foco FORA do painel não é tocado: redesenho por ação que pousa não rouba o
// foco de ninguém.
function chaveDoFoco(raiz) {
    const a = document.activeElement;
    if (!raiz || !a || a === document.body || !raiz.contains(a)) return null;
    if (a.id) return { id: a.id };
    const conq = a.getAttribute('data-conq');
    if (conq) return { conq };
    const autor = a.getAttribute('data-autor');
    if (autor) {
        const classe = a.classList.contains('autor-auto') ? 'autor-auto' : 'autor-esquecer';
        // A POSIÇÃO também: se o autor saiu (a lixeira), o foco vai pra linha
        // que tomou o lugar dele — como numa lista que se apaga item a item.
        return { autor, classe, i: [...raiz.querySelectorAll('.' + classe)].indexOf(a) };
    }
    return { outro: true };
}
// Nome PRÓPRIO, não "devolverFoco": o fechar de modal tem uma função com esse
// nome, e duas declarações no mesmo escopo global não dão erro — a última
// vence, calada (as duas nasceram em branches paralelos; ver
// `test/nomes-unicos.test.mjs`).
function devolverFocoAoPainel(raiz, chave) {
    if (!raiz || !chave) return;
    let alvo = null;
    if (chave.id) alvo = document.getElementById(chave.id);
    else if (chave.conq) alvo = [...raiz.querySelectorAll('[data-conq]')].find((e) => e.getAttribute('data-conq') === chave.conq);
    else if (chave.autor) {
        const irmaos = [...raiz.querySelectorAll('.' + chave.classe)];
        alvo = irmaos.find((e) => e.getAttribute('data-autor') === chave.autor)
            || irmaos[Math.min(chave.i, irmaos.length - 1)] || null;
    }
    // Sumiu sem equivalente (o último autor esquecido): a aba do painel, que é
    // o "título" dele — nunca o `<body>`.
    if (!alvo || !raiz.contains(alvo)) alvo = document.getElementById('filtersTabHistory');
    if (alvo) alvo.focus({ preventScroll: true });
}

function renderHistory() {
    const el = document.getElementById('historyBody');
    if (!el) return;
    const foco = chaveDoFoco(el);   // o innerHTML abaixo mata o elemento focado
    const s = getHistoryStats();
    renderAutores();
    const vazio = s.total.read + s.total.rejected === 0;
    const rows = [['today', s.today], ['week', s.week], ['month', s.month], ['total', s.total]];
    // A patente e a vitrine aparecem mesmo com histórico VAZIO — e é de propósito.
    // Medido no mockup: como as trancadas mostram nome e ícone, "0 de 16" lê como
    // "eis o que dá pra ganhar", não como parede de cadeados. É a tela que um
    // editor novo vê no primeiro minuto, e ela não pode ser um vazio.
    el.innerHTML = htmlPatente() + (vazio
        ? `<p class="text-xs text-slate-500 dark:text-slate-400">${escapeHtml(t('stats.history.empty'))}</p>`
        : rows.map(([k, v]) =>
            `<div class="flex justify-between items-baseline text-sm py-0.5">` +
            `<span class="text-slate-600 dark:text-slate-300">${escapeHtml(t('stats.history.' + k))}</span>` +
            `<span class="tnum font-medium"><span class="text-emerald-700 dark:text-emerald-400">${v.read}</span>` +
            ` · <span class="text-rose-600 dark:text-rose-400">${v.rejected}</span></span></div>`
        ).join(''));
    // O Resumo do mês só se oferece quando há mês: botão pra um mês vazio é
    // convite pra uma imagem em branco.
    const agora = new Date();
    const mes = dadosDoResumo(loadHistory(), agora.getFullYear(), agora.getMonth());
    if (mes.total > 0) {
        const mesNome = new Date(mes.ano, mes.mesIdx, 1).toLocaleDateString(i18nLocale(), { month: 'long' });
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.id = 'resumoBotao';
        btn.className = 'mt-3 w-full min-h-[44px] rounded-xl bg-cyan-700 hover:bg-cyan-800 dark:bg-cyan-400 dark:hover:bg-cyan-300 text-white dark:text-slate-900 font-semibold text-sm px-4 transition';
        btn.textContent = t('resumo.botao', { mes: mesNome });
        btn.addEventListener('click', abrirResumoDoMes);
        el.appendChild(btn);
    }
    el.insertAdjacentHTML('beforeend', htmlConquistas());
    if (!el.dataset.conqLigado) { ligarConquistas(el); el.dataset.conqLigado = '1'; }
    devolverFocoAoPainel(el, foco);
}

// Na PRIMEIRA vez que cada ação é confirmada pelo Waze, diz o que ela fez lá —
// não o que ela quis dizer aqui. O app explicava a INTENÇÃO ("o pedido não deve
// entrar no mapa") e nunca a CONSEQUÊNCIA, e as duas divergem no caso que mais
// importa: marcar como lido NÃO aprova nada, mas o ✓ verde diz o contrário pra
// quem chegou agora.
//
// Dispara na CONFIRMAÇÃO, não no gesto: durante a janela de Desfazer nada foi
// enviado ainda, e "rejeição enviada" ali seria mentira — além de disputar a
// tela com o banner do Desfazer.
function avisarConsequencia(actionType) {
    if (!CONSEQUENCIA_AVISADA[actionType]) return;
    // Com o TREINO aberto, nem aparece nem fica visto. A decisão é REAL — o ✕
    // da janela do Desfazer que o "Praticar" despacha, pousando com o treino
    // já na tela —, e o aviso de primeira vez saía por cima da faixa "nada é
    // enviado ao Waze": quem está aprendendo lia que o TREINO tinha mandado, e
    // a marca de visto o gastava ali, longe da fila em que ele explica alguma
    // coisa (R8-7-01, auditoria de 2026-10-03). Fica pra próxima confirmação
    // fora do treino — uma decisão de verdade, que é do que ele fala.
    if (typeof Treino !== 'undefined' && Treino.ativo === true) return;
    const vistas = AppState.preferences.consequenciaVista || {};
    if (vistas[actionType]) return;
    // Nem por baixo de uma camada, nem com a página escondida (R13-7-01).
    if (!avisoDeUmaVezSaiAgora('consequencia', actionType)) return;
    vistas[actionType] = true;
    AppState.preferences.consequenciaVista = vistas;
    savePreferences();
    showToast(t('consequencia.' + actionType), 'hint', 7000);
}
// Só as que ESCREVEM no Waze. Pular é local — o pedido volta na próxima busca,
// e isso o treino e o "Como funciona" já dizem.
const CONSEQUENCIA_AVISADA = { reject: true, read: true };

// ── Os avisos de UMA vez só saem onde a pessoa os VÊ ───────────────────────
// São três, e cada um aparece uma vez na vida: a consequência do 1º ✕ e do 1º
// ✓ (acima), o desbloqueio do Desfazer (`checkUndoGateUnlock`) e a dica "você
// nunca desfaz" (`checkDicaDesfazer`). Os três saem no banner do topo
// (#bannerStack, z-55), ABAIXO dos modais (z-60) e da foto e do mapa ampliados
// (z-65), e a marca de visto era gravada na hora. A decisão que pousava com os
// Filtros, a Ajuda ou a foto ampliada abertos — a camada aberta na janela do
// Desfazer, o caso comum — punha o banner inteiro DEBAIXO da caixa da camada e
// o gastava: nunca mais aparecia. O mesmo com a página no FUNDO (a fila de
// saída esvaziando quando a rede volta, o app em segundo plano): o banner saía
// e sumia antes de a pessoa voltar (R13-7-01, MEDIDO no Chromium e no WebKit,
// no Pixel, no SE e no computador: a caixa do modal cobria 100% do banner, e o
// toque caía no título dos Filtros; auditoria de 2026-10-07).
//
// A régua é a do treino (R8-7-01) e a do "Como funciona" adiado: com camada
// aberta ou a página escondida, o aviso sai SEM marcar e fica PENDENTE. Quem
// pede de novo é o fechamento da camada (`aoFecharCamada`) e a volta à página
// (`avisosAdiadosAoVoltar`); e a próxima confirmação o reavalia de qualquer
// jeito, porque nada foi marcado. Nenhum pedido de rede. A pendência é da
// SESSÃO em que a pessoa decidiu (`epocaDaSessao`): o "Sair" e a queda a
// descartam, e a troca de conta também (`esquecerOutraConta`) — o aviso diz
// o que ESTA pessoa fez. Ela mora na memória da aba: fechada a página, quem
// mostra é a próxima confirmação.
let avisosAdiados = null;   // { epoca, consequencia: Set de tipos, desbloqueio, dica }
let avisosAdiadosPedido = false;

// O aviso `qual` (com o `tipo`, na consequência) sai AGORA? Senão, fica
// pendente, e quem chamou sai sem marcar nada.
function avisoDeUmaVezSaiAgora(qual, tipo) {
    if (semCamadaAberta() && document.visibilityState !== 'hidden') return true;
    if (!avisosAdiados || avisosAdiados.epoca !== epocaDaSessao) {
        avisosAdiados = { epoca: epocaDaSessao, consequencia: new Set(), desbloqueio: false, dica: false };
    }
    if (qual === 'consequencia') avisosAdiados.consequencia.add(tipo);
    else avisosAdiados[qual] = true;
    return false;
}

// Decide DEPOIS da tarefa que pediu, numa microtarefa (o padrão do
// `pedirComoFuncionaAdiado`): o fechamento que abre outra camada no mesmo
// tique, ou o "Praticar" que fecha a Ajuda e abre o treino, já disseram o que
// fica na tela quando ela roda.
function pedirAvisosAdiados() {
    if (!avisosAdiados || avisosAdiadosPedido) return;
    avisosAdiadosPedido = true;
    queueMicrotask(() => {
        avisosAdiadosPedido = false;
        // Acessório: uma falha aqui nunca derruba quem pediu.
        try { atenderAvisosAdiados(); } catch (e) { console.error(e); }
    });
}

function atenderAvisosAdiados() {
    const a = avisosAdiados;
    if (!a) return;
    if (a.epoca !== epocaDaSessao || !AppState.authenticated) { avisosAdiados = null; return; }
    // O TREINO segura: os avisos falam da fila real. Sem esta espera, a
    // consequência e o desbloqueio sairiam pela guarda do treino deles (a do
    // R8-7-01), que não os deixa pendentes, e a dica, que não tem uma, sairia
    // por cima do card de treino.
    if (typeof Treino !== 'undefined' && Treino.ativo === true) return;
    avisosAdiados = null;
    // Cada um refaz a SUA conta (o que mudou enquanto esperava vale): a
    // desfeita que zerou a sequência cala a dica, e o desbloqueio, que marca a
    // dica como vista, vem antes dela — os dois não saem juntos. E com a tela
    // ainda sem lugar (outra camada aberta no mesmo tique, a página de novo no
    // fundo), cada um volta a ficar pendente pela régua de sempre.
    for (const tipo of a.consequencia) avisarConsequencia(tipo);
    if (a.desbloqueio) checkUndoGateUnlock();
    if (a.dica) checkDicaDesfazer();
}

// A página VOLTOU à vista: o aviso que esperava por ela (o ouvinte mora no
// `setupAppListeners`).
function avisosAdiadosAoVoltar() {
    if (document.visibilityState !== 'visible') return;
    pedirAvisosAdiados();
}

// ── FILA DE SAÍDA: o que você fez não se perde quando a rede some ─────────
//
// O defeito que isto conserta existe HOJE, pra todo editor, e não precisa de
// viagem nenhuma: basta o sinal oscilar. Medido no código de antes, o caminho
// era — placar sobe e é GRAVADO, card sai da tela, 3s de janela, envia, falha,
// duas retentativas (1,5s e 3,5s), e aí o último ramo do `handleActionResult`
// **reverte o placar e descarta a ação**. O pedido continua no Waze e o editor
// vê o número voltar atrás uns 5 segundos depois de já ter seguido em frente.
//
// O app não tinha NENHUMA noção de estar offline — nem uma chave no dicionário.
//
// Só `transient` entra aqui, e a distinção não é detalhe:
//   · `already_processed`/`not_found` → já é sucesso (outro editor chegou antes)
//   · `unauthorized` ................. → a sessão morreu; enfileirar adiaria o
//                                        relogin sem resolver nada
//   · `unknown` ...................... → segue revertendo. Enfileirar o que não
//                                        se entende é retentar pra sempre.
const SAIDA_KEY = 'waze_places_saida';
// Teto POR CONSTRUÇÃO (regra da casa pra estrutura que cresce por item). A fila
// real do Brasil tem 442 pedidos e o Waze guarda ~3 dias, então 1000 é o dobro
// do que existe pra fazer. Estourar NÃO descarta em silêncio: volta ao
// comportamento antigo (reverte e avisa), porque perda calada é o que este
// trecho existe pra acabar.
const SAIDA_MAX = 1000;
// Pausa entre os envios ao esvaziar. NÃO é número escolhido a dedo: o piso
// MEDIDO do app sem Desfazer é 377 ms por pedido (40 pedidos reais, esperando o
// card trocar de verdade). Esvaziar mais rápido que isso seria o app fazendo o
// que nenhum humano faz — e rajada é o padrão que faz um WAF marcar cliente.
const SAIDA_RITMO_MS = 400;

// Trava: `online` e a abertura podem coincidir. O gatilho que bate nela é
// DESCARTADO, e isso é deliberado — eu cheguei a escrever uma recoleta
// ("rodar de novo no fim") e ela NÃO SOBREVIVEU à sabotagem: tirando-a, os dois
// cenários que montei continuaram drenando. O motivo é que a janela em que ela
// importaria é desprezível: se o esvaziamento está dando certo, ele drena de
// qualquer jeito; se está falhando por rede, a rede voltando faz a PRÓPRIA
// retentativa em voo (1,5s e 3,5s) ter sucesso e o laço segue. Só o instante
// entre a última tentativa falhar e o laço sair ficaria descoberto — e aí a
// abertura do app, que é o outro gatilho, resolve. Guard que não distingue as
// duas versões é decoração (a régua do #67), então a recoleta saiu em vez de
// ser remendada até passar.
let esvaziandoSaida = false;
// O gatilho que chegou COM o esvaziamento no ar. Sem ele a guarda de reentrada
// vira uma PERDA: o `online` do navegador não é promessa de rede boa (o próprio
// `callWithRetry` só confia no `false`), então a rede que volta em dois tempos —
// túnel, elevador, 4G firmando — manda um `online` com a rede ainda ruim e outro
// logo depois já firme. O primeiro entra, quebra no `transient` e SAI; o segundo
// cai na guarda e some. Aí a fila fica presa com a rede ótima, e o próximo
// gatilho é só na abertura seguinte do app — podem ser horas.
// MEDIDO: com o abort atrasado em 900ms pra alargar a janela, a fila ficava em 2
// com `esvaziando:false` e `onLine:true` por toda a medição. É também o que o
// runner do CI produz sozinho, por lentidão — aqui a janela é de ~30ms.
let saidaPedidaDeNovo = false;
// O esvaziamento parou num item de conta ainda DESCONHECIDA (a sessão nova ainda
// sem perfil): a chegada do perfil o chama de novo (ver `aoConhecerConta`).
let saidaEsperandoConta = false;

// ── DUAS ABAS: uma esvazia de cada vez ────────────────────────────────────
// A trava `esvaziandoSaida` é da ABA, e a fila de saída é do APARELHO (o
// localStorage é um só pras abas). Com o app aberto em duas, a rede voltando
// manda o `online` às duas, e as duas esvaziavam a MESMA fila: cada decisão
// saía duas vezes pro Waze, e o pouso contava nas duas — MEDIDO, 3 decisões e 5
// rejeitados no Histórico (auditoria de 2026-09-29, O6).
//
// A trava ENTRE ABAS é a do navegador (`navigator.locks`): quem não a consegue
// NA HORA (`ifAvailable`) não esvazia, e espera a outra aba soltar pra tentar
// uma vez — o gatilho não evapora (a mesma regra do `saidaPedidaDeNovo`). A
// espera é o próprio navegador avisando que a trava soltou: não há relógio.
// O nome da trava é o da FILA que ela protege (não é chave de armazenamento:
// trava do navegador não grava nada).
const SAIDA_TRAVA = SAIDA_KEY;
// Sem `navigator.locks` (Safari antes do iOS 15.4, navegador antigo), a reserva
// é REIVINDICAR o item antes do envio: a marca da aba vai no item, e a outra aba
// que vê uma marca que não é a dela não esvazia. A marca vale por um tempo — a
// aba que a deixou pode ter morrido no meio do envio —, e o envio tem teto de
// 45 s (o do `_post`): 60 s cobrem com folga.
const SAIDA_REIVINDICACAO_MS = 60 * 1000;
// O localStorage não tem "grave só se ninguém gravou": duas abas podem marcar o
// MESMO item no mesmo instante, e vale a última gravação. Por isso quem marca
// espera um instante e relê — se a marca não é mais a dela, a outra ganhou.
const SAIDA_REIVINDICACAO_ASSENTA_MS = 60;
// A marca desta ABA: nasce com ela e SOBREVIVE a recarregar a mesma aba (o
// `sessionStorage` é da aba). Desde que a decisão que sai leva a marca de quem
// a manda (ver `reivindicacaoDestaAba`), a página recarregada — o F5, o Android
// que encerrou o app em segundo plano — tem de reconhecer como DELA o que
// anotou antes de morrer e mandá-lo na abertura, como sempre (O2, O5); com uma
// marca por página, esperava a marca vencer. Outra aba tem outra. Sem o
// `sessionStorage`, uma por página. É `let` porque a aba DUPLICADA troca de
// marca logo ao abrir (ver `segurarMarcaDaAba`).
let ABA_DESTA_PAGINA = (() => {
    const nova = Date.now().toString(36) + '.' + Math.random().toString(36).slice(2, 8);
    try {
        const tinha = sessionStorage.getItem('__abaDaSaida');
        if (tinha) return tinha;
        sessionStorage.setItem('__abaDaSaida', nova);
    } catch (e) { /* armazenamento bloqueado: a marca é desta página */ }
    return nova;
})();
let saidaEsperandoOutraAba = false;

// "Duplicar aba" (Chrome, Firefox, Safari) COPIA o `sessionStorage` — e a marca
// com ele: a aba duplicada nascia com a MESMA marca da original, achava que a
// decisão que a original tinha no ar era DELA e a mandava de novo ao abrir
// (auditoria de 2026-10-02, R6-2-10: dois envios do mesmo pedido). A página
// SEGURA uma trava do navegador com o nome da marca enquanto vive; ao abrir,
// a trava ocupada quer dizer que OUTRA página viva tem a marca — esta é a
// cópia, e ganha outra. Recarregar a mesma aba solta a trava da página que
// morre a tempo de a recarregada pegá-la (MEDIDO no Chromium e no WebKit: 20
// de 20 recargas ficaram com a marca, e a cópia achou a trava ocupada). Sem
// `navigator.locks`, segue como antes. O nome é da trava, não do armazenamento:
// trava do navegador não grava nada. O esvaziamento da fila de saída espera a
// conferência (`travaDaSaida`), que leva milissegundos.
const MARCA_DA_ABA_TRAVA = '__abaDaSaida:';
const marcaDaAbaConferida = segurarMarcaDaAba();
function segurarMarcaDaAba() {
    let locks = null;
    try { locks = navigator.locks && typeof navigator.locks.request === 'function' ? navigator.locks : null; } catch (e) {}
    if (!locks) return Promise.resolve();
    const segurar = (marca) => new Promise((pronto) => {
        locks.request(MARCA_DA_ABA_TRAVA + marca, { ifAvailable: true }, (lock) => {
            pronto(!!lock);
            // Presa pela vida da página: quem a solta é o navegador, quando ela morre.
            return lock ? new Promise(() => {}) : undefined;
        }).catch(() => pronto(true));   // trava recusada: fica a marca que tinha
    });
    return segurar(ABA_DESTA_PAGINA).then((minha) => {
        if (minha) return undefined;
        ABA_DESTA_PAGINA = Date.now().toString(36) + '.' + Math.random().toString(36).slice(2, 8);
        try { sessionStorage.setItem('__abaDaSaida', ABA_DESTA_PAGINA); } catch (e) { /* a marca é desta página */ }
        return segurar(ABA_DESTA_PAGINA);
    });
}

// A trava ENTRE ABAS do esvaziamento: `null` quando outra aba está esvaziando;
// senão `{ reserva, soltar }` — `reserva` quando o navegador não tem a trava, e
// aí vale a reivindicação item a item.
function travaDaSaida() {
    let locks = null;
    try { locks = navigator.locks && typeof navigator.locks.request === 'function' ? navigator.locks : null; } catch (e) {}
    if (!locks) return Promise.resolve({ reserva: true, soltar() {} });
    // A marca desta aba conferida ANTES (ver `segurarMarcaDaAba`): a aba
    // duplicada que esvaziasse com a marca da original mandaria de novo o que a
    // original tem no ar.
    return Promise.resolve(marcaDaAbaConferida).then(() => new Promise((pronto) => {
        let decidiu = false;
        locks.request(SAIDA_TRAVA, { ifAvailable: true }, (lock) => {
            decidiu = true;
            if (!lock) { pronto(null); return undefined; }
            // A trava fica presa enquanto esta promessa não resolve: quem a
            // solta é o fim do esvaziamento (`soltar`). Página que morre solta
            // sozinha — é do navegador.
            return new Promise((soltar) => pronto({ reserva: false, soltar }));
        }).catch(() => { if (!decidiu) pronto({ reserva: true, soltar() {} }); });
    }));
}

// Outra aba está esvaziando: espera ela SOLTAR a trava e tenta uma vez. Uma
// espera por aba; pega e solta na hora — é só pra saber QUANDO a outra
// terminou, e quem esvazia é a chamada de sempre, que tenta a trava de novo.
function esperarOutraAbaEsvaziar() {
    let locks = null;
    try { locks = navigator.locks; } catch (e) {}
    if (!locks || saidaEsperandoOutraAba) return;
    saidaEsperandoOutraAba = true;
    dfato('saida.outraAba');
    locks.request(SAIDA_TRAVA, () => undefined).then(
        () => { saidaEsperandoOutraAba = false; esvaziarFilaDeSaida(); },
        () => { saidaEsperandoOutraAba = false; });
}

// Marca de OUTRA aba, recente: ela está esvaziando (a reserva, sem
// `navigator.locks`) ou MANDANDO o item agora (a anotação antes do envio, ver
// `reivindicacaoDestaAba`).
function reivindicadoPorOutraAba(x) {
    return !!(x && x.rv && x.rv !== ABA_DESTA_PAGINA && Date.now() - (Number(x.rvEm) || 0) < SAIDA_REIVINDICACAO_MS);
}

// A marca DESTA aba na decisão que ela anota na fila de saída antes de mandar
// (o ✕/✓ do card, o lote, a descarga). Desde o O2 toda decisão que sai fica na
// fila enquanto voa, e a fila é do APARELHO: o que impedia o reenvio era o
// `pedidosEmAndamento`, que é da MEMÓRIA desta aba. A outra aba, esvaziando a
// fila em qualquer gatilho (abrir, a resposta de qualquer chamada, o `online`),
// mandava de novo a decisão que esta ainda tinha no ar — MEDIDO: o ✕ saindo pelas
// duas abas e o Histórico contando 3 pra 2 decisões; o "Rejeitar os 5" saindo
// 2× inteiro, 10 no Histórico pra 6 (auditoria de 2026-10-01, R5-1 F1 e
// R5-2-01). A marca vale o mesmo que a do esvaziamento: se esta aba morrer no
// meio do envio, a outra manda depois (at-least-once).
function reivindicacaoDestaAba() {
    return { rv: ABA_DESTA_PAGINA, rvEm: Date.now() };
}

// A decisão que ESTA aba mandou e a OUTRA pousou (e contou) antes: quando a
// resposta daqui chegou, o item já não estava na fila de saída. Contar de novo
// punha o mesmo trabalho duas vezes no Histórico, e o "já tratado" que a cópia
// causou virava "outro editor" — sobre a decisão da própria pessoa. Fica só o
// pouso nesta página, pra busca não trazer o pedido de volta.
function pousouPorOutraAba(place, tipo) {
    registrarPouso(place);
    dfato('saida.saiuPorOutro', { tipo });
}

// A resposta chegou e a decisão FICA na fila de saída (rede, 401): esta aba não
// a está mais mandando, e a marca dela sai — senão a outra aba esperava a marca
// vencer (até 1 min) pra mandar o que ninguém mais estava mandando. Só a marca
// DESTA aba: a de outra é de quem está mandando agora.
function soltarMarcaDosItens(tipo, places) {
    const chaves = new Set(places.map(chaveDoPedido));
    const f = carregarFilaDeSaida();
    let mudou = false;
    for (const x of f) {
        if (x && x.tipo === tipo && x.rv === ABA_DESTA_PAGINA && chaves.has(chaveDoPedido(x))) {
            delete x.rv; delete x.rvEm; mudou = true;
        }
    }
    if (mudou) salvarFilaDeSaida(f);
}

// Marca o item com esta aba e confere, depois de um instante, que a marca ficou
// (ver `SAIDA_REIVINDICACAO_ASSENTA_MS`).
async function reivindicarNaSaida(item) {
    const achar = (f) => f.find((x) => x && x.tipo === item.tipo && x.venueID === item.venueID
        && x.updateRequestID === item.updateRequestID);
    const f = carregarFilaDeSaida();
    const it = achar(f);
    if (!it || f.some(reivindicadoPorOutraAba)) return false;
    it.rv = ABA_DESTA_PAGINA;
    it.rvEm = Date.now();
    salvarFilaDeSaida(f);
    await new Promise((ok) => setTimeout(ok, SAIDA_REIVINDICACAO_ASSENTA_MS));
    const confere = achar(carregarFilaDeSaida());
    return !!confere && confere.rv === ABA_DESTA_PAGINA;
}

// O fim do esvaziamento na reserva: o que esta aba marcou e não saiu (a rede
// caiu, o 5xx mandou pro fim) fica livre pra qualquer aba na hora.
function soltarReivindicacoes({ comAsDoAr = false } = {}) {
    const f = carregarFilaDeSaida();
    let mudou = false;
    // O que esta aba tem NO AR (anotado antes do envio) segue marcado: soltar a
    // marca dele deixava a outra aba mandá-lo de novo. Menos quando a PÁGINA SAI
    // (`comAsDoAr`, no `pagehide`): a resposta dela não chega mais pra contar, e
    // a reabertura ou a outra aba o manda de novo NA HORA — o at-least-once de
    // sempre —, em vez de esperar a marca vencer.
    for (const x of f) {
        if (x && x.rv === ABA_DESTA_PAGINA && (comAsDoAr || !pedidosEmAndamento.has(chaveDoPedido(x)))) {
            delete x.rv; delete x.rvEm; mudou = true;
        }
    }
    if (mudou) salvarFilaDeSaida(f);
}

// ── 401 NA FILA DE SAÍDA: sessão morta ou ESCRITA recusada? ──────────────
//
// Auditoria de 2026-09-26 (O1): um ✕ cuja escrita o Waze recusa com 401/403 de
// forma PERSISTENTE (trava do local, WAF) — e o core põe QUALQUER 403 em
// `unauthorized` —, com a sonda do perfil respondendo, girava sem teto:
// alarme falso → esvaziar → a mesma escrita → 401 → confere → alarme falso…
// MEDIDO: 45 escritas e 22 sondas em 30 s depois de UM ✕, com um toast a cada
// ~1,3 s, até fechar o app. Duas travas, e uma não substitui a outra:
//
//  1. POR ITEM: o item guarda quando levou o 401 (`u401`). Se a sessão foi
//     CONFIRMADA viva depois disso (uma sonda que RESPONDEU com o perfil, não só
//     "não deu pra saber") e ele leva outro 401, não é a sessão — é a escrita
//     DESTE pedido. Sai como a falha de verdade: placar desce, aviso. Repetir
//     não muda nada.
//  2. RECUO no ciclo: cada passada que PARA num 401 espera mais antes de a
//     próxima começar (0, 15 s, 1 min, 5 min), e o primeiro pouso zera. Sem ele,
//     a sonda que não confirma nada (5xx, rede ruim) manteria o laço girando —
//     e todo pedido de uma fila grande faria a sua rodada de sonda. O recuo é da
//     SESSÃO (a marca do token): entrar de novo esvazia na hora.
//
// Nada disso é relógio: quem chama o esvaziamento continua sendo só gatilho que
// já existe (resposta que chega, `online`, abertura, perfil chegando).
let sessaoVivaEm = { s: null, em: 0 };
const SAIDA_RECUO_401_MS = [0, 15 * 1000, 60 * 1000, 5 * 60 * 1000];
let saidaRecuo = { s: null, n: 0, ate: 0 };

// ── 5xx NUM PEDIDO SÓ: a cabeça da fila não segura as outras ─────────────
//
// Auditoria de 2026-09-26 (O8): o esvaziamento dava `break` no primeiro
// `transient` — o certo pra REDE fora —, e um pedido que o Waze recusa SEMPRE
// com erro de servidor (5xx pra aquele local) ficava na cabeça da fila e
// segurava as outras decisões pra sempre (medido: 6 provas de rede, 6 envios do
// mesmo pedido, as outras duas nunca saíram). Quando o Waze RESPONDEU com 5xx
// PRA ESTE pedido (o `httpCode` que o core repassa; rede fora não tem), o item
// vai pro FIM da fila, contando a tentativa (`tt`, desde `tf`), e a passada para
// — uma requisição falhada por gatilho, nunca uma rajada. O destino final é o do
// O1: depois de `SAIDA_TENTATIVAS_POR_ITEM` falhas, e só se OUTRA escrita pousou
// depois de ele começar a falhar (prova de que o Waze aceita escrita — não é ele
// fora do ar), ele sai como a falha de verdade (placar desce, aviso). Sem essa
// prova, fica: o Waze pode estar fora pra todo mundo.
const SAIDA_TENTATIVAS_POR_ITEM = 3;
// Quando uma escrita POUSOU no Waze pela última vez nesta página (ver
// `registrarPouso`, por onde todo pouso passa). Só em memória: reaberta a
// página, a prova recomeça — o lado seguro.
let ultimaEscritaOkEm = 0;

// Manda o item pro FIM da fila de saída (relida, achado pela chave), com os
// campos novos.
function moverProFimDaSaida(item, campos) {
    const f = carregarFilaDeSaida();
    const i = f.findIndex((x) => x && x.tipo === item.tipo && x.venueID === item.venueID
        && x.updateRequestID === item.updateRequestID);
    if (i < 0) return f;
    const [it] = f.splice(i, 1);
    f.push(Object.assign(it, campos));
    salvarFilaDeSaida(f);
    return f;
}

// A marca da sessão DESTA aba — a da MEMÓRIA —, ou `null` sem nenhuma. As
// perguntas "esta aba tem sessão, e qual?" se respondem por aqui, nunca pelo
// `getSession`: com a memória vazia ele GRAVA nela a sessão que outra aba
// guardou no aparelho, e isso já é ADOTÁ-LA (R9-1-03). A resposta de um
// "invisível" que chegava depois da queda (`sessaoVivaDepoisDe`) e o "Conectar
// outro aparelho" tocado durante a renovação (`contaAgora`) adotavam calados a
// sessão da outra aba: a aba ficava "logada" na tela de entrada, a volta a ela
// não adotava mais, e o "Sair" de lá fechava o "Colar cookies" daqui, com o que
// estava sendo colado (auditoria da rodada 12, R12-1-03, MEDIDO).
function marcaDestaAba() {
    return API.sessionToken ? marcaDaSessao(API.sessionToken) : null;
}

// A sonda do `handleUnauthorized` RESPONDEU com o perfil: a sessão de agora está
// viva neste instante.
function marcarSessaoViva() {
    sessaoVivaEm = { s: marcaDestaAba(), em: Date.now() };
}

// Houve confirmação de sessão viva, NESTA sessão, depois de `t`? Sem sessão
// nesta aba, nenhuma.
function sessaoVivaDepoisDe(t) {
    const s = marcaDestaAba();
    return Number.isFinite(t) && !!s && sessaoVivaEm.s === s && sessaoVivaEm.em > t;
}

function recuarSaida() {
    const s = marcaDestaAba();
    const n = saidaRecuo.s === s ? saidaRecuo.n + 1 : 1;
    const espera = SAIDA_RECUO_401_MS[Math.min(n, SAIDA_RECUO_401_MS.length) - 1];
    saidaRecuo = { s, n, ate: Date.now() + espera };
    if (n > 1) dfato('saida.recuo', { n, s: Math.round(espera / 1000) });
}

function saidaEmRecuo() {
    const s = marcaDestaAba();
    return !!s && saidaRecuo.s === s && Date.now() < saidaRecuo.ate;
}

// Tira da fila de saída o item deste pedido, achado pela chave: é a resposta do
// envio da DESCARGA que chegou com a página viva (ver `descargaNaFila`).
function tirarDaFilaDeSaida(tipo, place) {
    const f = carregarFilaDeSaida();
    const i = f.findIndex((x) => x && x.tipo === tipo && x.venueID === place.venueID
        && x.updateRequestID === place.updateRequestID);
    if (i < 0) return false;
    f.splice(i, 1);
    salvarFilaDeSaida(f);
    updateInFlightIndicator();
    return true;
}

// Grava campos num item que JÁ está na fila de saída, achado pela chave (a fila
// é relida: outra aba ou o gesto podem ter mexido nela).
function marcarNaSaida(item, campos) {
    const f = carregarFilaDeSaida();
    const it = f.find((x) => x && x.tipo === item.tipo && x.venueID === item.venueID
        && x.updateRequestID === item.updateRequestID);
    if (!it) return false;
    Object.assign(it, campos);
    salvarFilaDeSaida(f);
    return true;
}

// ── DE QUEM É O QUE ESTÁ NO APARELHO ──────────────────────────────────────
//
// Depois de uma QUEDA de sessão (sem o "Sair"), outra pessoa pode entrar no
// mesmo aparelho. Tudo que o aparelho guarda era de quem estava: a fila de
// saída (as decisões DELA, que iriam pro Waze no nome de quem entrou), a lista
// de autores com a recusa automática que ELA ligou (agindo no nome de quem
// entrou), o placar, o Histórico, as conquistas, as conversas, a fila guardada
// do offline (auditoria de 2026-09-25). A conta de cada gesto vai no item da
// fila de saída, e a do aparelho fica guardada: conta NOVA, dados da anterior
// saem — como no "Sair", de onde saem as mesmas coisas.
//
// Uma marca CURTA do token (FNV-1a, 32 bits): só pra saber se a conta guardada
// foi vista NESTA sessão. Não é segredo nem prova de nada.
function marcaDaSessao(token) {
    let h = 0x811c9dc5;
    const txt = String(token || '');
    for (let i = 0; i < txt.length; i++) { h ^= txt.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
    return h.toString(16);
}

// A conta de AGORA: a do perfil vivo; sem ele (aberto sem rede), a guardada —
// mas só se foi vista nesta MESMA sessão. Numa sessão nova, antes de o perfil
// chegar, é desconhecida (`null`): a guardada é da sessão anterior, que pode
// ser de outra pessoa. E sem sessão NESTA aba (a renovação da queda, a tela de
// entrada), também: a sessão é a da memória (`marcaDestaAba`, R12-1-03).
function contaAgora() {
    const vivo = AppState.profile && AppState.profile.id;
    if (vivo !== undefined && vivo !== null && vivo !== '') return String(vivo);
    try {
        const c = JSON.parse(safeLS.get(CONTA_KEY) || 'null');
        const s = marcaDestaAba();
        if (c && c.id && s && c.s === s) return String(c.id);
    } catch (e) { /* ilegível: desconhecida */ }
    return null;
}

// Os dados do aparelho são DESTA conta, confirmado NESTA sessão: o perfil vivo
// passou pelo `aoConhecerConta` (que tira o que era de outra conta) com o token
// de agora. É a trava de quem age SOZINHO no nome da pessoa — a recusa
// automática lê a lista de autores do aparelho, e com o perfil gravado por fora
// da fonte única (o defeito do alarme falso, auditoria de 2026-09-26) ela agia
// com a lista da conta ANTERIOR. Hoje só o `definirPerfil` grava o perfil; isto
// é o cinto: se um caminho novo escapar dele, a recusa não roda.
//
// "Confirmado nesta sessão" vale por DUAS provas: a marca do aparelho é a
// sessão de agora, ou ESTA aba passou pelo `aoConhecerConta` com a sessão dela
// (`contaConfirmadaNestaAba`). Com duas abas da MESMA conta, cada uma com a sua
// sessão, a marca do aparelho é a da sessão guardada — a da outra aba, que
// entrou de novo —, e só a marca do aparelho deixava esta sem a recusa
// automática, calada, até recarregar (auditoria de 2026-10-02, R7-2-05). O dono
// do aparelho continua tendo que ser o perfil vivo: a lista de autores é dele.
let contaConfirmadaNestaAba = null;   // { id, s }: a conta e a marca da sessão desta aba
function contaConfirmada() {
    const vivo = AppState.profile && AppState.profile.id;
    if (vivo === undefined || vivo === null || vivo === '') return false;
    try {
        const c = JSON.parse(safeLS.get(CONTA_KEY) || 'null');
        if (!c || String(c.id) !== String(vivo)) return false;
        // A sessão DESTA aba, a da memória (R12-1-03): sem ela, nada confirmado.
        const s = marcaDestaAba();
        if (!s) return false;
        const aqui = contaConfirmadaNestaAba;
        return c.s === s || !!(aqui && aqui.id === String(vivo) && aqui.s === s);
    } catch (e) { return false; }
}

// O login disse de quem é a sessão (o `testar-cookies`, o resgate do
// pareamento, a ponte da extensão). Chega de fora — a ponte é `postMessage` —,
// então só o formato do servidor passa; o perfil que chegar confere de novo.
function conhecerContaDoLogin(conta) {
    if (conta === undefined || conta === null || !/^\d{1,19}$/.test(String(conta))) return;
    aoConhecerConta({ id: String(conta) });
}

// O perfil chegou: agora se sabe de quem é a sessão.
function aoConhecerConta(perfil) {
    const id = perfil && perfil.id !== undefined && perfil.id !== null && perfil.id !== '' ? String(perfil.id) : null;
    if (!id) return;
    // ANTES de conferir a troca: o que foi feito NESTA sessão antes de o perfil
    // chegar (conta nula) é desta conta, e sem o carimbo a troca o levaria junto
    // com o da conta anterior.
    carimbarContaNaSaida(id);
    // E o "invisível" pedido nesta sessão antes do perfil, pelo mesmo motivo
    // (R12-5-05): LIDO antes da troca — que tira da memória o pendente da conta
    // anterior (`presencaWmeZerar`) — e carimbado DEPOIS dela, com a conta de
    // quem entrou (`carimbarContaNoInvisivel`, logo abaixo).
    const invisivel = invisivelPedidoAntesDoPerfil();
    let antes = null;
    try { antes = JSON.parse(safeLS.get(CONTA_KEY) || 'null'); } catch (e) { antes = null; }
    if (antes && antes.id && String(antes.id) !== id) esquecerOutraConta(id);
    // A troca que OUTRA aba já fez no aparelho: ela entrou com esta conta (ou deu
    // "Sair") e tirou de lá o que era da anterior — mas esta aba seguia com a
    // MEMÓRIA dela. A aba cuja sessão caiu fica na tela de entrada com o que era
    // de quem estava (a queda o mantém, pra MESMA conta voltar), e ao adotar a
    // sessão da outra aba (ou entrar com os cookies dela) o "invisível" pendente
    // da anterior saía no nome de quem entrou, o rascunho dela aparecia na
    // conversa, e o relatório do modo dev levava o anel e as capturas dela
    // (auditoria da rodada 11, R11-1-01, MEDIDO). A conta que ESTA aba confirmou
    // por último diz: sendo outra, sai só o que a memória guarda — o aparelho a
    // outra aba já limpou.
    else if (contaConfirmadaNestaAba && contaConfirmadaNestaAba.id !== id) esquecerOutraConta(id, { soMemoria: true });
    carimbarContaNoInvisivel(id, invisivel);
    // A fila que atravessou a sessão é desta conta — ou já saiu com a outra.
    filaAtravessouSessao = false;
    // A sessão DESTA aba, a da memória (`marcaDestaAba`): o `getSession`, com ela
    // vazia, adotava a que outra aba guardou (R13-1-04, a régua do R12-1-03).
    const s = marcaDestaAba();
    contaConfirmadaNestaAba = { id, s };
    // A marca do APARELHO é a da sessão GUARDADA nele: só esta aba a regrava
    // quando a sessão dela é a guardada, ou quando a conta muda (nenhuma, ou
    // outra). A aba de OUTRA sessão da MESMA conta — a da dúvida que se resolveu
    // como a mesma conta (R6-1-04), ou a que a outra aba deixou pra trás ao entrar
    // de novo — gravava a marca dela por cima: na aba dona do aparelho a
    // `contaConfirmada` virava falsa, e a recusa automática parava calada
    // (auditoria de 2026-10-02, R7-1-03). A desta aba fica na memória.
    if (!antes || String(antes.id) !== id || sessaoDestaAbaEhAGuardada()) {
        safeLS.set(CONTA_KEY, JSON.stringify({ id, s }));
    }
    // Os avisos de pouso da outra aba que chegaram sem dar pra saber de quem eram
    // (a conta desta ainda desconhecida): os DESTA conta valem agora, os de outra
    // saem (R12-2-05, ver `avisosDePousoSemConta`). Depois da troca de conta, que
    // tira o que era da anterior.
    if (typeof aplicarAvisosQueEsperavamAConta === 'function') aplicarAvisosQueEsperavamAConta(id);
    if (saidaEsperandoConta) { saidaEsperandoConta = false; esvaziarFilaDeSaida(); }
}

// Os itens da fila de saída SEM conta (gesto feito antes de o perfil chegar)
// cuja marca é a da sessão de agora são desta conta: o token é o mesmo. Carimba.
// Os de OUTRA marca ficam sem conta — o dono é desconhecido, e o esvaziamento
// não os manda (auditoria de 2026-09-26, O3). A sessão é a DESTA aba, a da
// memória: sem nenhuma, não há o que carimbar — e o `getSession` que ficava aqui
// adotava, com a memória vazia, a sessão que outra aba guardou (R13-1-04).
function carimbarContaNaSaida(id) {
    const s = marcaDestaAba();
    if (!s) return;
    const f = carregarFilaDeSaida();
    let mudou = false;
    for (const it of f) {
        if (it && !it.conta && it.s === s) { it.conta = id; mudou = true; }
    }
    if (mudou) salvarFilaDeSaida(f);
}

// O "invisível" gravado só com a MARCA da sessão do gesto (o gesto feito antes
// de o perfil chegar, ver `presencaWmeGravarPendente`), com o que a memória
// desta aba sabe dele; sem ele, `null`.
function invisivelPedidoAntesDoPerfil() {
    const g = AppState.preferences && AppState.preferences.presencaWmeDesligar;
    if (!g || g.conta || typeof g.s !== 'string') return null;
    return { s: g.s, em: g.em, pendente: presencaWme.desligarPendente === true };
}

// O perfil da sessão chegou (`aoConhecerConta`): o "invisível" que esperava a
// conta passa a ser DELA, e sai com o perfil dela (`presencaWmeRefazerDesligar`,
// que o `definirPerfil` chama logo depois). Desta sessão, ele volta depois da
// troca de conta, que o tinha tirado com o da conta anterior: o gesto é de quem
// entrou (R12-5-05). O de OUTRA sessão, sem conta, tem dono desconhecido: sai sem
// ir ao Waze, como o item sem dono da fila de saída — o app nunca desliga a
// visibilidade de ninguém por conta própria.
function carimbarContaNoInvisivel(id, invisivel) {
    if (!invisivel) return;
    const p = AppState.preferences;
    if (!p || p.presenca !== false) return;   // religado nesse meio: não vale mais
    if (invisivel.s === marcaDestaAba()) {
        p.presencaWmeDesligar = { conta: String(id), em: invisivel.em };
        if (invisivel.pendente) presencaWme.desligarPendente = true;
    } else {
        const g = p.presencaWmeDesligar;
        if (!g || g.conta || g.s !== invisivel.s) return;
        delete p.presencaWmeDesligar;
    }
    savePreferences();
}

// MIGRACAO: saida-sem-marca
// Item gravado antes de a fila de saída guardar a SESSÃO do gesto (até a
// v2026.09.26-01) não diz de quem é quando vem sem conta. O que ainda espera
// envio na abertura COM sessão foi feito nela: a fila sai a cada abertura com
// sessão, e a entrada de outra pessoa (versão anterior) a esvaziava no nome de
// quem entrou. Adota a marca da sessão aberta; sem sessão, fica sem marca — dono
// desconhecido, e o esvaziamento não o manda.
function adotarSaidaSemMarca() {
    const s = marcaDaSessao(API.getSession());
    const f = carregarFilaDeSaida();
    let mudou = false;
    for (const it of f) {
        if (it && !it.conta && it.s === undefined) { it.s = s; mudou = true; }
    }
    if (mudou) salvarFilaDeSaida(f);
}

// O que o aparelho guardava da conta ANTERIOR e é DELA sai: o trabalho (placar,
// Histórico, conquistas), os autores e a recusa automática, as conversas, a fila
// guardada do offline, as capturas do modo dev e as decisões dela que esperavam
// envio. Da fila de saída fica só o que é da conta que entrou: os feitos nesta
// sessão antes de o perfil chegar já levaram o carimbo (`carimbarContaNaSaida`),
// e o que segue sem conta é de dono desconhecido. Ficam as escolhas do aparelho
// — idioma, tema, filtros e as preferências, menos o que só valia pra conta
// anterior (ver abaixo) — e a fila na tela, que já veio da busca de quem entrou
// (menos a que a renovação da queda manteve: ver o fim).
//
// `soMemoria`: a troca que OUTRA aba já fez no APARELHO (ver `aoConhecerConta`,
// R11-1-01). Ele é de quem entrou e já não guarda nada da anterior; aqui sai só o
// que ESTA aba guarda na memória. É a MESMA lista: as linhas que gravam ou
// apagam no aparelho levam o `soMemoria`, como as do `handleLogout` levam o
// `porOutraAba`. O placar, o Histórico, as preferências e os autores desta aba
// são cópias do aparelho, e o aviso `storage` já as trouxe de lá (ver
// `sincronizarComOutraAba`): zerar o placar aqui apagaria o que quem entrou já
// fez na outra aba. E sem o aviso da troca: ele saiu onde ela aconteceu.
function esquecerOutraConta(id, { soMemoria = false } = {}) {
    dfato('conta.trocou', soMemoria ? { soMemoria: true } : undefined);
    if (!soMemoria) {
        const f = carregarFilaDeSaida();
        const desta = f.filter((it) => it && it.conta && String(it.conta) === id);
        if (desta.length !== f.length) { salvarFilaDeSaida(desta); updateInFlightIndicator(); }
    }
    if (soMemoria) AppState.autores = null;
    else esquecerAutores();
    // O foco da anterior sai ANTES da reordenação que o perfil agenda logo
    // depois (`loadProfileAndAuxData`): a fila de quem entrou volta à ordem dela.
    esquecerFocoAutor();
    // O que a outra aba da conta anterior decidiu, pela chave (R12-2-01).
    if (typeof esquecerDecididasPorOutraAba === 'function') esquecerDecididasPorOutraAba();
    if (soMemoria) window.Presenca?.esquecer?.({ soMemoria: true });
    else window.Presenca?.esquecer?.();
    AppState.history = null;
    if (!soMemoria) {
        safeLS.remove(HISTORY_KEY);
        safeLS.remove(CONQUISTAS_KEY);
        // Os pedidos que o app estrelou eram estrelas DELA (R10-2-05): com o anel
        // da anterior, o ↑ de quem entrou não guardava esses pedidos.
        safeLS.remove(ESTRELADOS_KEY);
    }
    AppState.conquistas = null;
    atualizarSeloDeConquista();
    // E o painel do Histórico dela, que fica no DOM com os Filtros fechados (a
    // folha do autor o redesenha assim; ver a função; R8-7-06).
    esvaziarPainelDoHistorico();
    if (!soMemoria) {
        AppState.stats = { read: 0, rejected: 0, skipped: 0 };
        // A BASE dos pulados desta fila (ver `puladosNestaFila`) é uma leitura do
        // placar, e o placar acabou de zerar: com a base da conta anterior (5
        // pulados, digamos), os pulados de quem entrou não contavam, e a fila que
        // terminava com PULADO dizia "Tudo limpo!", com confete e a conquista — o
        // H9 de volta pela troca de conta (auditoria da costura, 2026-09-26, K4).
        puladosNoInicioDaFila = 0;
    }
    // A presença no WME era da conta anterior: o freio, os contadores e — o que
    // importa — o "invisível" que ela deixou PENDENTE, que sem isto sairia pra
    // quem entrou, sem o gesto dela ("o app nunca desliga por conta própria").
    presencaWmeZerar();
    // As escolhas que valiam pelas regras DELA, as marcas do que só ela viu, e o
    // que ESCREVE no Waze no nome de alguém — que não se herda (ver a função).
    if (!soMemoria) {
        esquecerEscolhasDaContaAnterior();
    }
    // E o aviso de UMA vez que esperava uma camada fechar (R13-7-01): ele dizia
    // o que a ANTERIOR fez — "rejeição enviada em seu nome" pra quem entrou, que
    // não rejeitou nada. Nas duas trocas: a da memória também é outra pessoa.
    avisosAdiados = null;
    // E a ÁREA GERENCIADA do filtro, que vem do perfil dela: a busca de quem
    // entrou saía filtrada pela área de outra pessoa, com os Filtros dizendo
    // "Nenhuma" (auditoria de 2026-10-01, R5-1 F4). O perfil de quem entrou
    // confere de novo (`esquecerAreaForaDoPerfil`). Com "Minha área" a busca vai
    // pela caixa do perfil, não por ela. Os filtros são da ABA (lidos na
    // abertura): na troca só da memória, sai daqui sem gravar.
    const areaNaBusca = !!(AppState.filters && AppState.filters.managedAreaId) && !AppState.filters.myArea;
    if (AppState.filters && AppState.filters.managedAreaId) {
        AppState.filters.managedAreaId = '';
        if (!soMemoria) saveFilters();
    }
    // E o seletor delas nos Filtros, com o NOME das áreas dela (R11-1-05).
    esvaziarSeletorDeAreas();
    // Casa, trabalho e a posição do GPS também eram dela: a fila de quem entrou
    // saía ordenada pela casa da anterior (R4-5 A4). As de quem entrou chegam
    // com o perfil dele.
    referenciasDoPerfil = null;
    posicaoGps = null;
    if (!soMemoria) saveStats();
    updateStats();
    if (soMemoria) {
        offlineEsquecer({ soMemoria: true });
        dlogApagar({ soMemoria: true });
    } else {
        offlineEsquecer();
        dlogApagar();
    }
    // O anel de chamadas, como no "Sair": o `dlogApagar` tira os corpos, mas as
    // entradas ficavam — a rota, o status, a hora e o `n` da fila de cada pedido
    // da conta anterior, em sequência, iam no relatório e na cópia guardada de
    // quem entrou (auditoria da rodada 9, R9-1-04 = R9-4-09, MEDIDO). Sai o que
    // era da sessão ANTERIOR; o que a sessão de quem entrou já fez fica — o login
    // que revelou a troca, e a abertura dela quando a troca só se descobre pelo
    // perfil. Zerar tudo levava junto (auditoria da rodada 10, R10-1-02 =
    // R10-4-07, MEDIDO: o anel de quem entrou pelo código ficava com 1 de 5).
    const ficaASessao = API.sessionToken ? marcaDaSessao(API.sessionToken) : null;
    deixarSoAsChamadasDaSessao(ficaASessao);
    // A lista de recursos do navegador, como no "Sair": a URL da foto de perfil
    // (com o id da conta anterior) e as das fotos da fila dela iam no relatório
    // do modo dev de quem entrou (MEDIDO; auditoria de 2026-10-03, R8-1-05). O
    // que ainda estava no ar também fica de fora — da lista, e do anel de
    // chamadas o que não é da sessão de quem entrou (ver a função; L12-1).
    esquecerRegistrosDaPagina(ficaASessao);
    // As listas de países guardadas por região valem pra uma sessão de UMA
    // conta, como no "Sair" (R9-6-01): quem entrou pede as dele.
    esquecerListasDePaises();
    // A fila na tela, se atravessou a sessão (a renovação silenciosa a manteve),
    // é da conta anterior — dos filtros e das permissões dela: sai, e a de quem
    // entrou é buscada. Nos outros caminhos de entrada a fila já nasceu desta
    // sessão, e refazer seria uma busca a mais no free tier — menos quando ela
    // saiu (ou está saindo) filtrada pela área da anterior: a abertura com a
    // sessão salva busca antes de o perfil dizer de quem ela é. No login, a conta
    // chega antes da primeira busca, e não há fila pra refazer.
    //
    // Com o TREINO aberto, a fila da tela são os EXEMPLOS, e a real é a que ele
    // guarda (`filaRealComDevolvidos`): contar a da tela dava "há fila" sempre. E
    // a troca de conta é a renovação silenciosa — nenhum gesto da pessoa —, então
    // ela não encerra o treino por baixo dela (a regra do R9-7-04): o `resetQueue`
    // daqui o encerrava CALADO, a faixa "nada é enviado ao Waze" sumia, o card da
    // frente virava um pedido de quem entrou e o ✕ seguinte ia ao Waze no nome
    // dela (R10-1-01, MEDIDO no navegador; auditoria da rodada 10). O treino
    // segue, e a fila de quem entrou vem no "Sair" dele (`refazerFilaReal`). A
    // que atravessou a queda é da conta anterior: sai dele já, com os exemplos
    // clonados dela (ver `Treino.esquecerFilaDaContaAnterior`). A que saiu pela
    // área da anterior é de quem entrou (a busca foi com a sessão dela): fica, e
    // só o refazer é anotado. Anotado ANTES de fechar as camadas: o "Treino
    // concluído" aberto fecha por lá, e o `sair()` dele já refaz a fila.
    const noTreino = typeof Treino !== 'undefined' && Treino.ativo === true;
    const refazerFila = filaAtravessouSessao
        || (areaNaBusca && (noTreino ? filaRealComDevolvidos().length > 0 : (AppState.fetching || AppState.queue.length)));
    if (refazerFila && noTreino) {
        if (filaAtravessouSessao) Treino.esquecerFilaDaContaAnterior();
        refazerFilaReal();
    }
    // O que a conta anterior tinha ABERTO na tela sai antes da fila trocar (ver
    // a função). DEPOIS do `Presenca.esquecer` lá em cima: o fechamento da
    // conversa pagaria o "lida" dela com a sessão de quem entrou.
    fecharOQueEraDaContaAnterior(refazerFila);
    if (refazerFila && !noTreino) {
        resetQueue();
        startFetching();
    }
    if (!soMemoria) showToast(t('toast.outraConta'), 'info');
}

// A troca de conta (`esquecerOutraConta`) tirava do aparelho o que era da conta
// anterior e deixava na TELA o que ela tinha aberto (auditoria de 2026-10-02,
// R7-1-01): o QR do "Conectar outro aparelho" — uma CÓPIA da sessão dela, que
// seguia desenhada e válida: quem o escaneasse entrava como ela por até 5 min —,
// a folha do autor com a reincidência dela e o Histórico com o trabalho dela, os
// dois já apagados do aparelho. É o que o "Sair" e a entrada de outra conta
// noutra aba já fazem:
//   · os códigos emitidos nesta página são cancelados no servidor, sem esperar
//     rede (sem ela, vencem sozinhos);
//   · as camadas fecham pela função da queda (`fecharCamadasAbertas`), que roda
//     a limpeza de cada uma e devolve o voltar de uma vez (gotcha #65). Com a
//     fila trocando (`comAFila`), TODAS: a foto e o mapa ampliados são de um
//     pedido dela — a foto da anterior ficava aberta por cima da fila nova, com
//     o "Aprovar" de L6 à mostra pra um L2 (R6-1-06). Com a fila desta sessão,
//     só os diálogos: a foto e o mapa são de um pedido de quem entrou, e ficam;
//   · e, ANTES de fechar a foto, a aprovação que POUSOU esperando ela fechar
//     (`placeResolvidoPorAprovacao`) é esquecida: o pedido é da fila que sai, e
//     fechar a foto andava a fila DA CONTA ANTERIOR — o card seguinte dela era
//     anunciado ("Novo pedido: …") e abria o "Como funciona" de quem entrou no
//     mesmo tique do voltar pendente, e o "Entendi" tirava a pessoa do app
//     (gotcha #65; R7-3-01).
function fecharOQueEraDaContaAnterior(comAFila) {
    for (const code of pareamentosEmitidos) API.cancelarPareamento(code).catch(() => {});
    pareamentosEmitidos.clear();
    if (comAFila) placeResolvidoPorAprovacao = null;
    if (comAFila ? !semCamadaAberta() : !!topOpenModal()) fecharCamadasAbertas();
}

// O que a conta ANTERIOR escolheu sob as regras DELA, e o que só ela viu
// (auditoria de 2026-09-29, R4-5 A3). Desligar o Desfazer foi permitido pela
// cota dela: quem entra tem a própria, e sem isto um L2 recém-chegado já agia
// sem a janela, sem ter cruzado cota nenhuma nem visto o aviso de que ela abre.
// As marcas de "já viu" (o aviso da cota, a dica, o "Como funciona", o aviso
// de consequência do primeiro ✕ e ✓) e a contagem que a dica usa são do que ELA
// viu e fez: quem entra não viu nada disso. O nível guardado também era o
// dela: sai, e a cota espera o perfil de quem entrou, que o regrava.
//
// E o critério pras escolhas que sobram é um só: o que ESCREVE no Waze no nome
// de alguém não se herda. "Pular guarda o pedido" sai: ligado, o ↑ grava a
// estrela do editor no pedido — no nome de quem está logado —, e a preferência
// é opt-in ESTRITO (quem nunca abriu as Preferências não guarda nada); quem
// entra não fez essa escolha. Ficam as que não escrevem no Waze em nome de
// ninguém: "Ver quem está no app" desligado, herdado, erra pro lado da
// privacidade, e o offline é recurso do aparelho. Tema e idioma também ficam,
// como as outras escolhas do aparelho.
function esquecerEscolhasDaContaAnterior() {
    const prefs = AppState.preferences;
    prefs.undoEnabled = true;
    prefs.pularGuarda = false;
    for (const marca of ['undoGateSeen', 'dicaDesfazerVista', 'comoFuncionaVisto', 'consequenciaVista']) delete prefs[marca];
    // Menos o "Como funciona" com o TREINO aberto: a troca de conta pela renovação
    // silenciosa não o encerra (R10-1-01), e quem está nele está aprendendo — o
    // treino É o "Como funciona" (o `Treino.entrar` o marca pelo mesmo motivo).
    // Sem isto, o "Sair" do treino abria o diálogo por cima do 1º card de quem
    // entrou, e pelo teclado o Enter seguinte, dado pra agir no ✕, caía no
    // "Quero treinar antes" e voltava ao treino (R11-7-02, MEDIDO no navegador).
    if (typeof Treino !== 'undefined' && Treino.ativo === true) prefs.comoFuncionaVisto = true;
    prefs.semUndoSeguidas = 0;
    savePreferences();
    safeLS.remove(PERFIL_GATE_KEY);
    // O que MOSTRA as escolhas: o selo do ↑ do card na tela ("Pular ⭐" diria que
    // o ↑ guarda) e as chaves da aba Preferências, se ela estiver aberta.
    atualizarSeloDePular();
    desenharChavesDePreferencia();
}

function carregarFilaDeSaida() {
    try {
        const v = JSON.parse(safeLS.get(SAIDA_KEY) || '[]');
        return Array.isArray(v) ? v : [];
    } catch (e) { return []; }
}

function salvarFilaDeSaida(f) {
    try { safeLS.set(SAIDA_KEY, JSON.stringify(f)); } catch (e) {}
}

// Guarda o MÍNIMO que permite reenviar E prestar contas direito no pouso:
// `creatorId` alimenta a reincidência e a conquista do elefante, `dup` a do
// detetive. Sem eles a ação sairia, mas o trabalho feito offline não contaria
// pras conquistas — divergência silenciosa entre o placar e o Histórico.
//
// O `nome` vai junto porque a reincidência CHAVEIA por id mas EXIBE por nome, e
// o `registrarRejeicaoDeAutor` reescreve o nome a cada rejeição: sem ele, um
// autor que já tinha nome na lista voltaria a aparecer como NÚMERO depois de
// uma rejeição feita offline.
//
// `calado`: a anotação ANTES do envio (`anotarAntesDoEnvio`, e o lote) não é a
// fila abrindo — é toda ação, e o diário não aceita nada por swipe. Ali a
// abertura é anotada quando a decisão FICA na fila (a resposta foi rede ou
// sessão).
//
// `lista`: a fila JÁ lida por quem chama, que a grava UMA vez no fim. É o lote:
// um `enfileirarSaida` por pedido lê e grava a fila inteira a cada um, e o
// `setItem` é SÍNCRONO — MEDIDO, o "Rejeitar os 200" travava a tela 79 ms (390
// ms com a CPU 6× mais lenta, 1,8 s com 500 esperando envio).
function enfileirarSaida(tipo, place, regiao, extra, calado, lista) {
    if (!place || place.venueID === undefined || place.updateRequestID === undefined) return false;
    const f = lista || carregarFilaDeSaida();
    // O MESMO pedido duas vezes na fila é a mesma decisão mandada duas vezes —
    // e, se o tipo mudou, duas decisões diferentes executadas no Waze (ler não
    // resolve o pedido, então um "rejeitar" depois dele vale). Com o filtro de
    // entrada (`semOsJaDecididos`) um pedido que está aqui não volta a ser card,
    // então isto não deveria acontecer: se acontecer, é um caminho novo que
    // escapou do filtro, e o diário diz. Vale a PRIMEIRA decisão, e quem chama
    // desfaz a contagem do gesto repetido. Com DUAS ABAS acontece sem caminho
    // nenhum escapar — a outra decidiu o pedido com o card já aqui —, e o diário
    // diz isso também (`outraAba`, ver `anotarDecididosPorOutraAba`). E a decisão
    // da outra aba vale também DEPOIS de pousar e sair desta fila (R10-2-02): a
    // daqui seria a segunda, e um ✕ depois do ✓ de lá era executado. É o que
    // cobre o gesto que já estava na janela do Desfazer quando a de lá chegou, o
    // lote do autor que leva o card da tela e a descarga ao fechar o app.
    const chave = chaveDoPedido(place);
    const daOutraAba = typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(place) === true;
    if (daOutraAba || (chave && f.some((it) => chaveDoPedido(it) === chave))) {
        dfato('saida.repetida', { tipo, ...(daOutraAba ? { outraAba: true } : {}) });
        return 'repetida';
    }
    if (f.length >= SAIDA_MAX) return false;
    f.push({ tipo, venueID: place.venueID, updateRequestID: place.updateRequestID,
             creatorId: place.creatorId != null ? place.creatorId : null,
             nome: place.createdBy ? String(place.createdBy) : null,
             // O motivo do reporte, como a conquista lê (`registrarAcaoConfirmada`).
             dup: place.flagType === 'DUPLICATE',
             // `t` responde "há quanto tempo isto está preso aqui" no
             // DIAGNÓSTICO (que despeja o localStorage inteiro), e é a HORA do
             // gesto pra "Coruja" no pouso (`registrarPousoDeSaida`).
             t: Date.now(),
             // O dia e a região em que o trabalho foi feito. Lidos no pouso,
             // seriam os do momento em que a rede voltou — que pode ser outro dia
             // e outro filtro. O dia também é o balde do "Centurião", e o idioma
             // o da "Poliglota". Quem enfileira DEPOIS do gesto (a anotação no
             // fim da janela do Desfazer, a resposta que voltou por rede) passa o
             // carimbo do gesto (`carimboDoGesto`) no `extra`, que vale por cima
             // destes — senão um "Aplicar" dentro da janela trocava o país (R6-7-4).
             dia: historyTodayKey(), onde: ondeAgora(),
             lang: typeof getLang === 'function' ? getLang() : '',
             // E a CONTA do gesto (ver `contaAgora`): a fila não pode sair no
             // nome de outra pessoa que entre neste aparelho depois.
             conta: contaAgora(),
             // E a SESSÃO do gesto (a marca do token): numa sessão nova, antes
             // de o perfil chegar, a conta sai nula — e aí é a marca que diz de
             // quem é o item. Sem ela, o item nulo saía no nome de QUALQUER
             // conta que entrasse depois (auditoria de 2026-09-26, O3). A da
             // MEMÓRIA (`marcaDestaAba`): o `getSession`, com ela vazia, adotava
             // a sessão que outra aba guardou (R13-1-04). Sem sessão, `null`: dono
             // desconhecido, e o esvaziamento não o manda.
             s: marcaDestaAba(),
             // E a REGIÃO do Waze (row/na/il/world), pelo mesmo motivo: enviado
             // depois de a pessoa trocar de região, o pedido iria pro servidor
             // errado, voltaria "não encontrado" e contaria como feito.
             regiao: regiao || API.getRegion(),
             // O que quem enfileira já sabe do item (o 401 do gesto: `u401`).
             ...(extra && typeof extra === 'object' ? extra : {}) });
    if (lista) return true;
    salvarFilaDeSaida(f);
    updateInFlightIndicator();
    // Só a ABERTURA da fila entra no diário, nunca cada item: `dfato` é anel de
    // 120 e a regra da casa é "nada por swipe" — 200 pedidos numa sombra de
    // conectividade despejariam todo o resto do diário, que é justamente o que
    // se quer ler junto. O evento é ficar sem rede; quantos couberam sai no
    // `saida.saiu`, e a fila inteira já está no localStorage do diagnóstico.
    if (f.length === 1 && !calado) dfato('saida.abriu', { tipo });
    return true;
}

// Esvazia COM RITMO, um por vez. O pouso NÃO passa pelo `handleActionResult`
// (ele somaria o placar de novo, e o número já subiu no gesto): passa pelo
// `registrarPousoDeSaida`, que é o mesmo conjunto de regras sem essa parte.
// A ÚNICA exceção é `unauthorized`, que precisa do `handleUnauthorized` de lá.
async function esvaziarFilaDeSaida() {
    // Já tem um esvaziamento no ar: ANOTA o pedido em vez de descartá-lo. Duas
    // chamadas simultâneas não podem drenar a mesma fila (é o que a trava
    // impede), mas o gatilho não pode evaporar — ver `saidaPedidaDeNovo`.
    if (esvaziandoSaida) { saidaPedidaDeNovo = true; return; }
    if (!AppState.authenticated) return;
    if (navigator.onLine === false) return;
    // A sessão está sendo CONFERIDA (um 401 acabou de chegar, ver
    // `handleUnauthorized`): espera o veredito. Cada resposta 401 também é
    // prova de rede, e cada prova chamava o esvaziamento — que mandava o 1º
    // item DE NOVO, milissegundos depois (o 1º degrau do recuo é 0). MEDIDO com
    // a sessão morta na abertura: o mesmo pedido 2× em 19 ms (auditoria da
    // costura, 2026-09-26, K14). Viva, quem confere chama o esvaziamento
    // (o alarme falso); morta, a fila espera o próximo login.
    if (verificandoSessao) return;
    // A última passada PAROU num 401 há pouco: espera o recuo (ver
    // `SAIDA_RECUO_401_MS`). O gatilho que chegar depois dele esvazia.
    if (saidaEmRecuo()) return;
    let f = carregarFilaDeSaida();
    // Fila vazia: nenhuma passada a fazer — a prova de rede engolida pela
    // passada anterior (a que pediu esta) é atendida agora (R11-4-01).
    if (!f.length) { atenderProvaDoEsvaziamento(); return; }
    esvaziandoSaida = true;
    // ENTRE ABAS: uma esvazia de cada vez (ver `travaDaSaida`). Com a outra aba
    // esvaziando, esta espera ela soltar e tenta uma vez.
    const trava = await travaDaSaida();
    if (!trava) { esvaziandoSaida = false; esperarOutraAbaEsvaziar(); return; }
    // As guardas do topo valem DE NOVO depois da espera da trava: ela é uma
    // volta do laço de eventos (o navegador entrega a trava numa tarefa), e
    // nela o mundo anda. O caso que mordeu: o ✕ que leva 401. A resposta é prova
    // de rede, e a prova chama este esvaziamento ANTES de a resposta chegar a
    // quem a pediu (ver `API.aoProvarRede`) — com o `verificandoSessao` ainda
    // falso. Durante a espera o executor recebe o 401, solta o pedido
    // (`pedidosEmAndamento`) e começa a conferência; esta passada, que já tinha
    // passado pelas guardas, mandava a MESMA decisão de novo (MEDIDO: duas idas
    // ao Waze em 7 a 11 ms; auditoria de 2026-10-02, R7-1-05). A trava volta pro
    // navegador: quem chama de novo é quem sempre chama (o fim da conferência,
    // a rede voltando, a próxima resposta).
    if (!AppState.authenticated || navigator.onLine === false || verificandoSessao || saidaEmRecuo()) {
        esvaziandoSaida = false;
        trava.soltar();
        return;
    }
    const epoca = epocaDaSessao;
    // Zera ao ENTRAR, não ao sair: o que interessa é o gatilho que chegar DAQUI
    // pra frente. Zerar no fim apagaria justamente o pedido que esta passada
    // ainda não pôde atender.
    saidaPedidaDeNovo = false;
    // Relida com a trava na mão: a outra aba pode ter esvaziado nesse meio.
    f = carregarFilaDeSaida();
    let enviados = 0;
    // Tira o item SEM ir ao Waze — de outra conta, ou de dono desconhecido: o
    // placar que subiu no gesto desce (o mesmo da falha de verdade).
    const tirarSemEnviar = (it, evento) => {
        const g = carregarFilaDeSaida();
        const i = g.findIndex((x) => x && x.tipo === it.tipo && x.venueID === it.venueID
            && x.updateRequestID === it.updateRequestID);
        if (i >= 0) g.splice(i, 1);
        salvarFilaDeSaida(g);
        const statKey = it.tipo === 'read' ? 'read' : 'rejected';
        AppState.stats[statKey] = Math.max(0, AppState.stats[statKey] - 1);
        updateStats();
        saveStats();
        updateInFlightIndicator();
        dfato(evento, { tipo: it.tipo });
        return g;
    };
    try {
        while (f.length) {
            // Sair no meio do esvaziamento: PARA. Sem isto o item já em voo
            // pousaria depois do logout e o `recordHistory` recriaria o
            // histórico que o "Sair" acabou de apagar.
            if (!AppState.authenticated) break;
            // O item cujo envio ainda está NO AR não sai de novo daqui: a descarga
            // o põe na fila e o manda com `keepalive`, e ele fica "em andamento"
            // até a resposta — que decide o destino dele (ver `descargaNaFila`).
            // Sem isto a prova de rede da PRÓPRIA resposta mandava o item de novo
            // e ele contava duas vezes. Pega o primeiro que não está no ar; só
            // com os que estão, para (a resposta deles chama de novo).
            //
            // E o que está no ar NA OUTRA aba também (a marca dela, ver
            // `reivindicacaoDestaAba`), com e sem a trava do navegador: a trava
            // só serializa os esvaziamentos, e a decisão que a outra aba manda
            // não passa por ela.
            //
            // A fila é RELIDA a cada volta, e não só depois do pouso: entre uma
            // volta e a seguinte há o ritmo (400 ms), e nele a decisão do card
            // (ou do "Rejeitar os N") que estava no ar quando a lista foi lida
            // POUSA — sai da fila e do "em andamento". Escolhida na lista de
            // antes do ritmo, ela parecia livre e ia ao Waze DE NOVO (MEDIDO
            // nos dois motores: o ✕ de u2 aos 370 e aos 1017 ms; auditoria de
            // 2026-10-06, R9-2-01). Uma leitura do aparelho por item, só
            // durante a passada.
            f = carregarFilaDeSaida();
            const item = f.find((x) => x && !pedidosEmAndamento.has(chaveDoPedido(x)) && !reivindicadoPorOutraAba(x));
            if (!item) break;
            // A conta do GESTO contra a de agora (ver `contaAgora`). Desconhecida
            // agora (sessão nova, perfil a caminho): espera — o perfil chegando
            // chama de novo. De OUTRA conta: sai da fila sem ir ao Waze, e o
            // placar que subiu no gesto desce (o mesmo da falha de verdade).
            if (item && item.conta) {
                const agora = contaAgora();
                if (!agora) { saidaEsperandoConta = true; break; }
                if (String(item.conta) !== agora) {
                    f = tirarSemEnviar(item, 'saida.outraConta');
                    continue;
                }
            } else if (item && item.s !== marcaDaSessao(API.getSession())) {
                // SEM conta e de OUTRA sessão (ou gravado sem a marca): o dono é
                // desconhecido — pode ser a conta de antes da queda, e o token de
                // agora é de quem entrou. Nunca vai ao Waze. Sem conta e DESTA
                // sessão sai normalmente: o token é o mesmo do gesto.
                f = tirarSemEnviar(item, 'saida.semDono');
                continue;
            }
            // Na RESERVA (sem a trava do navegador), o item é REIVINDICADO antes
            // do envio. Não deu — outra aba tem item marcado há pouco (ela está
            // esvaziando), ou marcou este no mesmo instante e ganhou —: esta sai.
            if (trava.reserva && !(await reivindicarNaSaida(item))) break;
            // As guardas da ENTRADA valem a CADA item — depois do ritmo (e da
            // reivindicação, na reserva) e antes do envio. A conferência de sessão
            // que começa no MEIO da passada não a parava: o ✕ que leva 401 com
            // ela dormindo o ritmo é solto do "em andamento" pelo executor, e a
            // passada acordava e mandava a MESMA decisão de novo, com a
            // conferência no ar; o 401 de qualquer outra chamada deixava os itens
            // seguintes saírem durante ela (MEDIDO nos dois motores; auditoria de
            // 2026-10-06, R8-2-02 e R8-1-06 — o R7-1-05 só valia na entrada). A
            // rede que cai no meio, idem: o envio já nascia condenado. E a sessão
            // é a da ENTRADA (`epoca`): trocada no meio (a queda que renova
            // durante o ritmo), a resposta seria jogada fora e o item, mandado de
            // novo. Quem chama de novo é quem sempre chama: o fim da conferência,
            // a rede voltando, a próxima resposta, a renovação.
            if (!AppState.authenticated || navigator.onLine === false || verificandoSessao || saidaEmRecuo()
                || epoca !== epocaDaSessao) break;
            const place = { venueID: item.venueID, updateRequestID: item.updateRequestID,
                            creatorId: item.creatorId, createdBy: item.nome || undefined,
                            flagType: item.dup ? 'DUPLICATE' : undefined };
            let r = item.tipo === 'read'
                ? await API.markAsRead(item.venueID, item.updateRequestID, null, item.regiao)
                : await API.rejectPlace(item.venueID, item.updateRequestID, null, item.regiao);
            // Saiu (ou entrou OUTRA pessoa) enquanto o item voava: nada daqui
            // pra baixo pode gravar — nem o pouso (histórico, autor), nem a fila.
            if (epoca !== epocaDaSessao) { enviados = 0; break; }
            // Rede fora de novo: PARA e deixa o resto pra próxima. Insistir aqui
            // seria gastar requisição do free tier pra falhar em série.
            if (r && r.errorCategory === 'transient' && !(Number(r.httpCode) >= 500)) break;
            if (r && r.errorCategory === 'transient') {
                // O Waze RESPONDEU com erro de servidor PRA ESTE pedido (ver
                // `SAIDA_TENTATIVAS_POR_ITEM`): ele vai pro fim e a passada para;
                // depois de N, com outra escrita pousada no meio, ele sai.
                const tt = (Number(item.tt) || 0) + 1;
                const tf = Number.isFinite(item.tf) ? item.tf : Date.now();
                if (tt >= SAIDA_TENTATIVAS_POR_ITEM && ultimaEscritaOkEm > tf) {
                    dfato('saida.recusada', { tipo: item.tipo, motivo: 'transient' });
                    r = { success: false, errorCategory: 'unknown' };
                } else {
                    f = moverProFimDaSaida(item, { tt, tf });
                    break;
                }
            }
            if (r && r.errorCategory === 'unauthorized') {
                // O MESMO item já tinha levado 401 e a sessão foi CONFIRMADA viva
                // depois disso: não é a sessão, é a escrita DESTE pedido que o
                // Waze recusa. Sai como a falha de verdade (placar desce, aviso)
                // pelo caminho de baixo — repetir era o laço sem teto (O1).
                if (sessaoVivaDepoisDe(item.u401)) {
                    dfato('saida.recusada', { tipo: item.tipo, motivo: 'unauthorized' });
                    r = { success: false, errorCategory: 'unknown' };
                } else {
                    // Sessão talvez morta: para e mantém a fila. Quem decide o
                    // relogin é o `handleUnauthorized`, e o que foi feito não pode
                    // evaporar por isso. Direto nele, e não pelo `handleActionResult`:
                    // lá o 401 ENFILEIRA a ação, e este item já está na fila —
                    // viraria "repetida" e descontaria o placar de um trabalho que
                    // segue guardado. O item guarda QUANDO levou o 401, e a
                    // próxima passada espera o recuo.
                    marcarNaSaida(item, { u401: Date.now() });
                    recuarSaida();
                    handleUnauthorized();
                    break;
                }
            }
            // O placar JÁ foi contado quando a pessoa deslizou — este ramo não
            // pode somar de novo. Por isso o resultado entra por um caminho que
            // só registra histórico/conquistas e trata o "já tratado".
            // O pouso mexe em histórico, reincidência, conquistas e DOM. Uma
            // exceção ali NÃO pode levar o resto da fila junto: antes ela caía
            // no catch do laço e o esvaziamento morria no meio, deixando o
            // resto encalhado em silêncio (só um `dfato`). O item já saiu do
            // Waze — o que falhou foi a CONTABILIDADE dele, e contabilidade de
            // um item não é motivo pra não mandar os outros sete.
            //
            // Mas só se o item AINDA ESTÁ na fila: a outra aba (a reserva sem a
            // trava do navegador), a resposta de uma descarga ou o "Sair" dado
            // noutra aba podem tê-lo levado enquanto ele voava — e aí o pouso é
            // de quem o levou. Contar aqui também punha o mesmo trabalho duas
            // vezes no Histórico (auditoria de 2026-09-29, O6). Nem pouso, nem
            // "enviado".
            if (!carregarFilaDeSaida().some((x) => x && x.tipo === item.tipo && x.venueID === item.venueID
                && x.updateRequestID === item.updateRequestID)) {
                dfato('saida.saiuPorOutro', { tipo: item.tipo });
                r = null;
            }
            try { registrarPousoDeSaida(item.tipo, place, r, item); }
            catch (e) { dfato('saida.pouso.erro', { tipo: item.tipo }); }
            // RELÊ antes de gravar, e o motivo é PERDA DE DADO na feature que
            // existe pra não perder dado: `f` foi lido antes do `await`, e nesse
            // meio-tempo o editor pode ter deslizado um pedido que também falhou
            // por rede — `enfileirarSaida` gravou `[A,B,C]` e um `salvarFilaDeSaida(f)`
            // com o `f` velho gravaria `[B]` por cima, sumindo com o C em silêncio.
            // O item que acabou de sair é sempre o `[0]` (quem entra é empurrado
            // pro fim), então reler e tirar o primeiro preserva o que chegou.
            //
            // Tira pela CHAVE, não pela posição: com o app aberto em duas abas a
            // outra pode ter mexido na fila durante o `await`, e o `shift()` às
            // cegas tiraria o item de outra pessoa — que então nunca sairia, com
            // o placar já contado.
            f = carregarFilaDeSaida();
            const saiu = f.findIndex((x) => x && x.tipo === item.tipo && x.venueID === item.venueID
                && x.updateRequestID === item.updateRequestID);
            if (saiu >= 0) f.splice(saiu, 1);
            salvarFilaDeSaida(f);
            updateInFlightIndicator();
            // Só conta o que POUSOU (inclusive "já tratado"): a recusa de verdade
            // já avisou com toast de erro, e entrava no "N enviados" de sucesso
            // logo depois — o mesmo pedido dito falho e enviado (auditoria de
            // 2026-09-25). Sai da fila do mesmo jeito: repetir não muda a recusa.
            if (r && (r.success || r.errorCategory === 'already_processed' || r.errorCategory === 'not_found')) {
                enviados++;
                // Um pouso prova que a escrita passa: o recuo do 401 acaba.
                saidaRecuo = { s: null, n: 0, ate: 0 };
            }
            if (f.length) await new Promise((ok) => setTimeout(ok, SAIDA_RITMO_MS));
        }
    } catch (e) {
        dfato('saida.erro', { restam: f.length });
    } finally {
        esvaziandoSaida = false;
        // A trava entre abas solta aqui (ou, na reserva, as marcas desta aba).
        if (trava.reserva) soltarReivindicacoes();
        else trava.soltar();
    }
    if (enviados) {
        dfato('saida.saiu', { enviados, restam: f.length });
        // Plural por chave, que é o que o projeto tem (sem ICU): `{n} enviados`
        // com n=1 daria "1 enviados" em pt/es/fr, e UM é o caso mais comum —
        // uma ação só falhando numa oscilação de sinal.
        showToast(t(enviados === 1 ? 'toast.saidaEnviada' : 'toast.saidaEnviadaPlural',
                    { n: enviados }), 'success');
    }
    // O gatilho que chegou no meio é atendido AGORA. Não vira laço: a passada
    // seguinte só existe se alguém pedir de novo DURANTE ela, e quem pede é o
    // evento `online` do navegador ou a abertura do app — nenhum dos dois é
    // nosso, nenhum é polling. As guardas do topo (deslogado, `onLine === false`,
    // fila vazia) seguem valendo e param na primeira linha.
    if (saidaPedidaDeNovo) {
        saidaPedidaDeNovo = false;
        return esvaziarFilaDeSaida();
    }
    // FIM do esvaziamento: a prova de rede que chegou no meio dele e não pôde
    // varrer o offline (a banda) varre agora (ver `API.aoProvarRede`, R11-4-01).
    atenderProvaDoEsvaziamento();
}

// O pouso de um item da fila de saída. É o `handleActionResult` SEM a parte do
// placar: o número já subiu quando a pessoa deslizou, e somar de novo aqui
// contaria o mesmo trabalho duas vezes.
function registrarPousoDeSaida(actionType, place, result, item) {
    if (!result) return;
    item = item || {};
    const cat = result.errorCategory || (result.success ? null : 'unknown');
    if (result.success || cat === 'already_processed' || cat === 'not_found') {
        registrarPouso(place);
        // O mesmo do `handleActionResult`: o ✕ ou o ✓ dado sem rede, depois de a
        // aprovação desta foto ter pousado sem resposta, sai da fila de saída
        // "já tratado" — o desfecho é a aprovação dela (R7-3-08).
        if (!result.success && aprovacaoDelaJaPousou(place)) { desfechoDaAprovacaoDela(actionType, place); return; }
        recordHistory(actionType, 1, item.dia, item.onde);
        if (actionType === 'reject' && result.success) registrarRejeicaoDeAutor(place);
        // As conquistas também são do GESTO, pelo mesmo motivo do `dia`: o
        // pedido tratado de madrugada e sem rede pousa de manhã, e a "Coruja"
        // (a hora), o "Centurião" (o balde do dia) e a "Poliglota" (o idioma)
        // eram avaliados na hora do POUSO (auditoria de 2026-09-25).
        registrarAcaoConfirmada(actionType, place, { t: item.t, dia: item.dia, lang: item.lang });
        return;
    }
    // Não deu, e não é rede nem sessão: a ação falhou DE VERDADE, então o número
    // que subiu no gesto tem que descer agora. Isto não é simetria estética — o
    // placar é PERSISTIDO (`waze_places_stats`), então deixar só o `serverTotal`
    // voltar deixaria "Rejeitados" inflado para sempre por algo que nunca saiu.
    const statKey = actionType === 'read' ? 'read' : 'rejected';
    AppState.stats[statKey] = Math.max(0, AppState.stats[statKey] - 1);
    updateStats();
    saveStats();
    // E o pedido volta a ser card — pela BUSCA (ver `devolverPedidoRecusado`):
    // o item da fila guarda só os ids, e pode ser de outra fila ou de antes de o
    // app ser reaberto. O "Restam" sobe quando ele chegar; somar aqui, como era,
    // o contava duas vezes na reabertura e deixava "Restam 1" sobre o "Tudo
    // limpo!" na mesma página.
    devolverPedidoRecusado(place);
    const verb = actionType === 'read' ? t('action.verb.read') : t('action.verb.reject');
    showToast(msgDoServidor(result, t('toast.actionError', { verb })), 'error');
}

// ── PEDIDO JÁ DECIDIDO NÃO VOLTA COMO CARD ────────────────────────────────
//
// Relato de 2026-09-22, no modo avião: o owner tratou pedidos, eles foram pra
// fila de saída, o app foi fechado e reaberto — e os MESMOS pedidos voltaram
// como card, com a fila de saída ainda segurando as decisões deles. Dava pra
// decidir de novo: o segundo gesto contava outra vez no placar e mandava uma
// SEGUNDA decisão pro Waze, que pode ser outra ("lido" na primeira, "rejeitado"
// na segunda — e as duas são executadas, porque ler não resolve o pedido).
//
// A causa: a fila guardada do offline só é regravada COM rede (na busca e no
// começo da varredura), e a reabertura sem rede a restaurava INTEIRA. Nada
// perguntava o que este aparelho tinha decidido depois de ela ser tirada.
//
// O mesmo buraco existia com rede, só que estreito: a busca da abertura corre
// junto com o esvaziamento da fila de saída, e o Waze só esquece um pedido
// quando a decisão CHEGA. O que ainda estava na fila de saída — ou pousou
// depois de o Waze montar a lista — voltava como card.
//
// A regra é UMA pros dois caminhos (`semOsJaDecididos`): um pedido só entra na
// fila se este aparelho não o decidiu DEPOIS de a lista ter sido tirada.
// "Decidiu" é: está na fila de saída, está na janela do Desfazer ou em voo, ou
// POUSOU no Waze depois do instante em que a lista foi tirada (`desde`). O que
// pousou ANTES a própria lista já reflete, e aí quem manda é o Waze — um pedido
// LIDO volta com o filtro "só não lidos" desligado, e isso é o de sempre.

// A chave de um pedido é o par que a fila de saída guarda e que o Waze usa pra
// decidir. `String` nos dois lados: o JSON da fila de saída e o da busca não
// prometem o mesmo tipo pro mesmo id, e `12 !== '12'` faria o filtro passar
// calado — que é o defeito inteiro de volta, sem erro nenhum.
function chaveDoPedido(p) {
    if (!p || p.venueID == null || p.updateRequestID == null) return null;
    return String(p.venueID) + '|' + String(p.updateRequestID);
}

// Janela do Desfazer e envio em andamento. Só em memória: morre com a página,
// e o que sobrevive a ela (fila de saída e pousos gravados) mora no aparelho.
// Entra no GESTO, porque é ali que o card sai da fila: uma busca que chegue
// durante a janela traria o pedido de volta, e o Desfazer o devolveria DE NOVO
// — o mesmo pedido duas vezes na fila.
const pedidosEmAndamento = new Set();
// Os pedidos cuja decisão a DESCARGA pôs na fila de saída antes de o envio sair
// (ver `descarregar` no `scheduleAction`). O MESMO objeto do pedido que o
// executor entrega ao `handleActionResult`: a resposta que chegar com a página
// viva decide o destino do item — pousou, sai da fila; rede, fica lá sem contar
// de novo. Só em memória: morta a página, o item segue na fila e o reenvio o
// resolve.
const descargaNaFila = new WeakSet();
// A decisão ANOTADA na fila de saída antes de sair (O2, ver
// `anotarAntesDoEnvio`). A resposta a trata como a da descarga (`jaNaSaida`); a
// diferença é só o diário: esta foi anotada calada, e a abertura da fila é dita
// quando ela FICA lá.
const anotadoAntesDoEnvio = new WeakSet();

// WRITE-AHEAD do ✕ e do ✓ (O2, auditoria de 2026-09-29): a decisão entra na
// fila de saída ANTES do envio, e a resposta decide o destino dela — pousou ou
// foi recusada de vez, sai; rede ou sessão, fica, sem o gesto contar de novo. É
// o contrato que a descarga já tinha (`descargaNaFila`), agora pra toda decisão
// que sai: a EM VOO não estava em lugar nenhum do aparelho, e fechar o app com a
// resposta no ar deixava o +1 no placar e o pedido de volta como card na
// reabertura — dava pra decidir de novo, e um ✕ depois do ✓ vale no Waze. MEDIDO
// (f5-em-voo): `{decididoDeVolta: true, placar: 1, saida: [], pousos: []}`.
// Anotada, a reabertura não o devolve (`semOsJaDecididos`) e o esvaziamento o
// manda — at-least-once: se o envio tinha chegado, volta "já tratado" e conta
// UMA vez. Enquanto voa ele está em andamento (`pedidosEmAndamento`), e o
// esvaziamento não o manda de novo. Fila cheia: segue sem anotar (o caminho de
// antes, que avisa na falha). A descarga já anotou: nada a fazer.
// `gesto`: o dia e o lugar do GESTO (`carimboDoGesto`) — a anotação sai no fim
// da janela do Desfazer, e lidos aqui eles seriam os de depois dela (R6-7-4).
function anotarAntesDoEnvio(tipo, place, regiao, gesto) {
    if (descargaNaFila.has(place)) return true;
    const r = enfileirarSaida(tipo, place, regiao, { ...gesto, ...reivindicacaoDestaAba() }, true);
    if (r === true) anotadoAntesDoEnvio.add(place);
    return r;
}

// A decisão anotada antes do envio FICOU na fila (rede ou sessão): se é a única
// lá, a fila acabou de abrir — é a transição que o diário registra (ver
// `enfileirarSaida`).
function anotarSeAbriuASaida(tipo) {
    if (carregarFilaDeSaida().length === 1) dfato('saida.abriu', { tipo });
}

// Chave → quando a decisão pousou no Waze, NESTA página. É o que cobre a
// corrida da busca com o esvaziamento. Todo mundo tem, com ou sem offline, e
// não custa armazenamento: morre com a página.
const pousosDaPagina = new Map();
// Mais velho que isto, qualquer busca nova já o reflete — a poda só impede que
// o mapa cresça numa sessão longa.
const POUSO_NA_MEMORIA_MS = 10 * 60 * 1000;
// O OBJETO do pedido que pousou NESTA página (ver `registrarPouso`). Quase sempre
// ele já saiu da fila no gesto; os que FICAM nela depois de pousar são o alvo do
// "Marcar todos" (até o fim do lote: os pedaços pousam um a um, e o lote os tira
// da fila só no fim) e o pedido aprovado com a foto ainda aberta
// (`placeResolvidoPorAprovacao`). É a gravação da fila guardada que pergunta
// (`offlineGravarFila`, R13-2-04). Pelo OBJETO, não pela chave: o mesmo pedido
// que volta numa busca de depois (o lido, com "lidos também") é outro objeto, e é
// card legítimo.
const pedidosQuePousaram = new WeakSet();

function marcarEmAndamento(places, sim) {
    for (const p of (Array.isArray(places) ? places : [places])) {
        const k = chaveDoPedido(p);
        if (!k) continue;
        if (sim) pedidosEmAndamento.add(k);
        else pedidosEmAndamento.delete(k);
    }
}

function offlineLerPousos() {
    try {
        const v = JSON.parse(safeLS.get(OFFLINE_POUSOS_KEY) || '[]');
        return Array.isArray(v) ? v.filter((e) => Array.isArray(e) && typeof e[0] === 'string' && Number.isFinite(e[1])) : [];
    } catch (e) { return []; }
}

// FONTE ÚNICA do "a decisão chegou no Waze". Todo pouso passa por aqui — o do
// card, o da fila de saída, o do lote e o da aprovação de foto —, e um caminho
// que não passar deixa o pedido voltar como card depois de reabrir sem rede,
// sem erro nenhum na tela. Aceita um pedido ou uma lista (o lote grava UMA vez).
//
// A cópia GRAVADA só existe com o offline ligado: é ela que a reabertura sem
// rede consulta, e quem não ligou o offline não reabre sem rede. "Quem não
// marca não paga nada."
//
// E é daqui que as OUTRAS abas ficam sabendo do pouso (R11-2-01, ver
// `avisarOutrasAbasDoPouso`): por ser a fonte única, o aviso cobre os caminhos
// que não passam pela fila de saída — o "Marcar todos", a recusa automática e a
// aprovação de foto. `quem`: a marca de quem DECIDIU, tirada no gesto, pra
// decisão que pousa com a sessão já caída (R12-2-04, ver `quemDecideAgora`).
function registrarPouso(places, quem) {
    const agora = Date.now();
    // Uma escrita pousou: o Waze aceita escrita agora (ver `ultimaEscritaOkEm`).
    ultimaEscritaOkEm = agora;
    const chaves = [];
    for (const p of (Array.isArray(places) ? places : [places])) {
        const k = chaveDoPedido(p);
        if (k) {
            chaves.push(k);
            pousosDaPagina.set(k, agora);
            if (typeof pedidosQuePousaram !== 'undefined') pedidosQuePousaram.add(p);
        }
    }
    if (!chaves.length) return;
    if (typeof avisarOutrasAbasDoPouso === 'function') avisarOutrasAbasDoPouso(chaves, quem);
    if (pousosDaPagina.size > 500) {
        for (const [k, t] of pousosDaPagina) if (agora - t > POUSO_NA_MEMORIA_MS) pousosDaPagina.delete(k);
    }
    if (!offlineLigado()) return;
    const lista = offlineLerPousos();
    for (const k of chaves) lista.push([k, agora]);
    while (lista.length > OFFLINE_POUSOS_MAX) lista.shift();
    try { safeLS.set(OFFLINE_POUSOS_KEY, JSON.stringify(lista)); } catch (e) {}
}

// A fila guardada foi regravada: o que pousou ANTES de ela ser tirada já está
// refletido nela e sai da lista. Chamada só DEPOIS de a gravação fechar — se
// ela falhar, a lista tem que continuar valendo contra a foto velha.
function offlinePodarPousos(desde) {
    const lista = offlineLerPousos();
    const ficam = lista.filter((e) => e[1] >= desde);
    if (ficam.length === lista.length) return;
    try {
        if (ficam.length) safeLS.set(OFFLINE_POUSOS_KEY, JSON.stringify(ficam));
        else safeLS.remove(OFFLINE_POUSOS_KEY);
    } catch (e) {}
}

// O filtro, usado pelos DOIS caminhos por onde pedido entra na fila: a busca
// (`fetchNextPage`) e a reabertura sem rede (`offlineTentarAbrirSemRede`).
// `desde` é o instante em que a LISTA foi tirada — o começo da busca, ou o
// `desde` gravado junto da fila guardada. Devolve os que ficam e QUANTOS saíram,
// porque o número vai pro diário: é a prova de que o filtro agiu.
function semOsJaDecididos(places, desde) {
    const lista = Array.isArray(places) ? places : [];
    const naSaida = new Set();
    for (const it of carregarFilaDeSaida()) {
        const k = chaveDoPedido(it);
        if (k) naSaida.add(k);
    }
    const pousoEm = new Map(pousosDaPagina);
    if (offlineLigado()) {
        for (const [k, t] of offlineLerPousos()) if (!(pousoEm.get(k) >= t)) pousoEm.set(k, t);
    }
    const limite = Number.isFinite(desde) ? desde : 0;
    const ficam = [];
    let excluidos = 0;
    for (const p of lista) {
        const k = chaveDoPedido(p);
        const pousou = k ? pousoEm.get(k) : undefined;
        if (k && (naSaida.has(k) || pedidosEmAndamento.has(k) || (pousou !== undefined && pousou >= limite))) {
            excluidos++;
            continue;
        }
        ficam.push(p);
    }
    return { places: ficam, excluidos };
}

// Tudo que ENTROU na fila desde o último `resetQueue`: o que está nela e o que
// já saiu (decidido, pulado, descartado). A busca relê a partir da página 1
// (ver `fetchNextPage`), e o Waze devolve de novo o que continua pendente lá: o
// card que segue na fila, o pulado, o lido com o filtro "lidos também", e o
// local que ficou na divisa entre duas páginas — MEDIDO na fila real do Brasil
// (2026-09-25, 697 pedidos): o Waze pagina por PEDIDO, mas cada página traz o
// LOCAL com todos os pedidos pendentes dele, e 5 pedidos de 2 locais vieram nas
// duas páginas. Nada disso volta como card na mesma fila, que é como sempre
// foi: o que passou pela pessoa só volta quando ela atualiza, e é o
// `resetQueue` que zera isto. Só em memória, como a própria fila.
const pedidosQueEntraramNaFila = new Set();

function registrarEntradaNaFila(places) {
    for (const p of (Array.isArray(places) ? places : [places])) {
        const k = chaveDoPedido(p);
        if (k) pedidosQueEntraramNaFila.add(k);
    }
}

// O filtro da busca: tira o que já passou pela fila, o card na tela (por
// garantia: ele é o `queue[0]`) e o repetido dentro do próprio lote. Devolve
// QUANTOS saíram, que vai pro diário.
function semOsQueJaPassaramPelaFila(places) {
    const vistos = new Set(pedidosQueEntraramNaFila);
    for (const p of AppState.queue) {
        const k = chaveDoPedido(p);
        if (k) vistos.add(k);
    }
    const atual = chaveDoPedido(AppState.currentPlace);
    if (atual) vistos.add(atual);
    const ficam = [];
    let repetidos = 0;
    for (const p of Array.isArray(places) ? places : []) {
        const k = chaveDoPedido(p);
        if (k && vistos.has(k)) { repetidos++; continue; }
        if (k) vistos.add(k);
        ficam.push(p);
    }
    return { places: ficam, repetidos };
}

// Os DOIS gatilhos, e nenhum deles é polling (o free tier proíbe): o navegador
// avisando que voltou, e a abertura do app. Quem ficou offline e fechou tudo
// encontra a fila esperando na próxima vez que abrir.
window.addEventListener('online', async () => {
    // EM ORDEM, nunca em paralelo — e a ordem é "trabalho do editor primeiro".
    //
    // O motivo é o free tier: a rede acabou de voltar, muitas vezes em dados
    // móveis, e disparar duas correntes de requisição no mesmo instante é
    // competir justamente no pior momento. Esperar não trava nada — o
    // esvaziamento tem fim garantido (para no primeiro `transient`).
    //
    // Além disso o `resetQueue()` roda SÍNCRONO e mexe em `pendingAction`, na
    // fila e no `serverTotal`; rodá-lo no meio de um `await` do esvaziamento é
    // corrida por construção, mesmo que nenhuma medição a tenha pego.
    //
    // NÃO foi isto que reprovou o bloco da fila de saída no CI — eu afirmei que
    // era e estava errado. A causa, reproduzida depois e determinística, era o
    // gatilho ENGOLIDO pela guarda de reentrada (ver `saidaPedidaDeNovo`).
    await esvaziarFilaDeSaida();
    // A rede voltou: é a janela pra repor o que venceu na sombra. Sai calado
    // com o toggle desligado, e só baixa o que de fato faltava.
    //
    // Com a varredura JÁ NO AR, não pede outra. As respostas do esvaziamento
    // provam a rede, e o FIM dele varre pela prova engolida
    // (`atenderProvaDoEsvaziamento`) — pela MESMA volta da rede e na mesma
    // janela. Pedida de novo aqui com ela no ar (`offlinePedidaDeNovo`), saía uma
    // passada inteira a mais logo depois da primeira: a fila regravada, a janela
    // e a poda refeitas, o `offline.gravou`/`offline.pronto` duas vezes no
    // diário — e, com a primeira "parcial", os itens que falharam repetidos na
    // hora, com a rede ainda firmando (auditoria da rodada 12, R12-4-03, MEDIDO:
    // duas varreduras começavam depois do `online`).
    if (!offlineVarrendo) offlineTalvezVarrer();
    recuperarCardSemFoto();
    // E refaz a BUSCA se ela tinha falhado. Sem isto o editor ficava olhando
    // "Falha ao carregar" com 4g funcionando até tocar no botão — a fila de
    // saída se resolvia sozinha e a de PEDIDOS não, o que é incoerente. O
    // `loadError` é o portão: sem ele isto viraria uma requisição a cada
    // oscilação de rede, e o free tier é restrição de projeto.
    // `hasMore` volta a ser verdade ANTES (ver `retomarBusca`), e não é zelo: a
    // falha o deixou em `false`, e o `fetchNextPage` sai na PRIMEIRA linha com
    // isso. MEDIDO — sem isso o app trocava "Falha ao carregar" por **"Tudo
    // limpo!"** com a fila vazia, que é pior que o erro original. Era um
    // `resetQueue()`, que resolvia isso e trazia de volta o que a pessoa pulou.
    // É o mesmo caminho do botão "Tentar de novo": o automático e o manual
    // têm que fazer a mesma coisa.
    if (AppState.authenticated && AppState.loadError && !AppState.fetching) {
        retomarBusca();
    }
});

// Retoma a busca DEPOIS de uma falha, SEM zerar a fila. A busca relê do topo e
// tira o que já passou por ela, então não há o que ganhar esquecendo: era o que
// o `resetQueue` fazia aqui — os pedidos que a pessoa PULOU nesta sessão
// voltavam, e com card na tela ele ainda arrancava o card e despachava a ação
// da janela do Desfazer antes da hora. `hasMore` volta a ser verdade porque a
// falha o tinha desligado, e o `fetchNextPage` sai na primeira linha sem ele.
function retomarBusca() {
    // Com a fila VAZIA (a tela de "sem conexão"), voltar é ATUALIZAR: os pedidos
    // que passaram pela fila sem decisão — pulados sem sinal, como o card de foto
    // cuja foto não veio — voltam. Sem o reset, a rede voltava e a fila terminava
    // VAZIA com eles pendentes: "parece que acabou" (MEDIDO na auditoria em
    // produção de 2026-09-25, reaberto sem rede, tudo pulado, rede de volta: 0
    // cards). Com card na tela só retoma: o reset arrancaria o card da mão e
    // despacharia a ação da janela do Desfazer antes da hora.
    // A fila VAZIA é a REAL (`filaReal`), e o atualizar passa pela função que
    // respeita o treino aberto (`refazerFilaReal`): pela da tela, no treino, a
    // fila real vazia não era vista (os exemplos estão nela) e o "Sair" buscava
    // sem refazer — os pulados sem sinal não voltavam —, e no ÚLTIMO card do
    // treino o `resetQueue` daqui o encerrava por baixo do "Treino concluído"
    // (auditoria de 2026-10-06, junto do R9-7-04).
    if (filaReal().length === 0) {
        refazerFilaReal();
        return;
    }
    AppState.loadError = false;
    AppState.hasMore = true;
    startFetching();
}

// O TERCEIRO gatilho, e o único que não depende do navegador avisar nada: uma
// resposta NOSSA que chegou prova que a rede existe.
//
// RELATADO pelo owner, no iPhone: modo avião, trata 3, sai do modo avião — e o
// "3 esperando envio" fica parado. Ele então trata mais 2, que saem NA HORA, e
// os 3 continuam lá. O app tinha a prova de rede na mão (duas requisições
// bem-sucedidas) e não a usava.
//
// REPRODUZIDO com sonda, e a causa não é o evento faltar: ele CHEGA quando o
// rádio liga, e nesse instante a rede ainda não passa tráfego. O esvaziamento
// entra, quebra no `transient` e sai — e nenhum gatilho novo vem depois, porque
// os dois que existiam eram o `online` (já gasto) e a ABERTURA do app (e ele
// nunca foi fechado). Consertar isso pelo evento é impossível: `onLine === true`
// não prova rede, e o projeto não confia nele em lugar nenhum.
//
// Não é polling e não custa requisição (o free tier é restrição de projeto):
// isto só REAGE ao que já saiu. Com a fila vazia sai na segunda linha do
// `esvaziarFilaDeSaida`.
//
// SAI CEDO durante o esvaziamento, e não é zelo: cada item que ele manda com
// sucesso passaria por aqui e marcaria `saidaPedidaDeNovo`, fazendo a passada
// re-executar no fim. Isso contraria o "para no primeiro `transient`" — o laço
// que quebrou por rede ruim tentaria de novo NA HORA, gastando requisição
// justamente quando ela falha. Quem está no ar já vai processar a fila inteira,
// então não há nada a anotar PRA FILA — a prova engolida fica anotada só pra
// varredura do offline, que sai no fim dele (ver `atenderProvaDoEsvaziamento`).
API.aoProvarRede = () => {
    // Uma resposta CHEGOU: a rede anda, e a foto que falhar daqui em diante não
    // é "falta de sinal" (ver `buscaSemResposta`). ANTES da saída abaixo: no
    // meio do esvaziamento também é prova.
    buscaSemResposta = false;
    // A resposta que chegou JÁ prova a rede: a foto que ainda falhar é falha
    // dela, e o card sai do "precisa de sinal" (ver `recuperarCardSemFoto`).
    // ANTES da saída abaixo, como a marca do lie-fi: redesenhar o card não pede
    // nada à rede e não disputa nada com o esvaziamento. Morava depois dela, e a
    // prova que chegava com a fila de saída esvaziando (a resposta do perfil,
    // ou a da própria decisão que saía) era engolida: o card seguia com "A foto
    // precisa de sinal" e ✕/✓ travados, e o fim do esvaziamento não chama nada
    // — só uma próxima resposta da nossa API o soltava (auditoria da rodada 10,
    // R10-4-03, MEDIDO: 15,9 s travado e contando, nos dois motores).
    recuperarCardSemFoto({ redeProvada: true });
    // Os três ganchos de TETO PRÓPRIO também vêm ANTES da saída cedo: o perfil
    // que faltou (1×/min), o "invisível" do WME que não saiu (1×/min, um envio
    // por vez) e o token do tempo real (5 min). Nenhum disputa a fila de saída —
    // é um pedido cada, só quando falta —, e nenhum dos dois motivos da saída
    // cedo (logo abaixo) vale pra eles. Moravam DEPOIS dela: com a rede voltando
    // pelo `online` e decisões esperando envio, as respostas do esvaziamento
    // eram as únicas provas de rede, todas engolidas, e o fim dele não chama
    // nada — o perfil que faltava seguia faltando (sem nome, sem os portões de
    // L6, sem a recusa automática e a presença) e o "invisível" pendente não
    // saía, até a próxima resposta FORA de um esvaziamento: o próximo gesto
    // (auditoria da rodada 11, R11-4-01 = R11-2-07 = R11-5-02, MEDIDO nos dois
    // motores: duas decisões saindo e o perfil `null` 3 s depois do fim).
    refazerPerfilSeFaltar();
    presencaWmeRefazerDesligar();
    // O token do tempo real que faltou ou falhou: sem isto, nada mais o pedia
    // de novo e o chat ficava sem tempo real até reabrir o app. Com o teto de
    // 5 min da própria presença (ver `presencaAoProvarRede`).
    window.Presenca?.aoProvarRede?.();
    // SAI CEDO durante o esvaziamento, e agora por DOIS motivos. O primeiro já
    // estava escrito abaixo (retentar na hora contraria a política de rede). O
    // segundo é novo: varrer o offline no meio do esvaziamento é competir por
    // banda exatamente no pior momento — a rede acabou de voltar, muitas vezes
    // em dados móveis. O guard de `test/fila-saida.test.mjs` cobra isto, e
    // estava certo quando eu tentei tirar. A prova engolida fica ANOTADA, e o
    // fim do esvaziamento varre (ver `atenderProvaDoEsvaziamento`): sem a nota,
    // a varredura esperava a próxima resposta, que podia não vir.
    if (esvaziandoSaida) { provaNoEsvaziamento = true; return; }
    // Esta prova varre logo abaixo: a que foi engolida antes (e ainda não
    // atendida) vai junto, sem uma segunda varredura.
    provaNoEsvaziamento = false;
    esvaziarFilaDeSaida();
    // Resposta que CHEGA prova rede, e as duas pontas do offline pegam carona
    // nela: o que estava preso pra SAIR e o que falta ENTRAR.
    offlineTalvezVarrer();
};

// A prova de rede que chegou com o esvaziamento no AR (ver `API.aoProvarRede`):
// a varredura do offline não sai no meio dele (a banda), e o FIM dele a chama —
// o fim de uma passada sem outra pedida, ou a passada pedida que nem começou
// porque a fila já estava vazia. Sem rede, sem sessão, conferindo um 401 ou no
// recuo, a nota espera o próximo esvaziamento (o próximo gatilho).
let provaNoEsvaziamento = false;
function atenderProvaDoEsvaziamento() {
    if (!provaNoEsvaziamento || esvaziandoSaida) return;
    provaNoEsvaziamento = false;
    offlineTalvezVarrer();
}

// ═══════════════════════════════════════════════════════════════════════════
// DISPONÍVEL OFFLINE — o TRABALHO sobrevive à sombra de sinal
// ═══════════════════════════════════════════════════════════════════════════
//
// O Degrau 1 (fila de saída) fez a AÇÃO sobreviver: você desliza sem rede e o
// envio sai sozinho depois. Isto faz o TRABALHO sobreviver: os pedidos, o mapa
// e as fotos ficam no aparelho, e o app se vira sozinho no vai-e-volta de sinal
// de uma estrada.
//
// OPT-IN ESTRITO, e isso é o contrato: quem não marcou não paga NADA. Nem um
// byte, nem uma requisição, nem sequer uma URL diferente (ver `urlDaFoto`).
//
// ── OS TRÊS ITENS TÊM PRAZOS DIFERENTES, e isso decide o desenho ───────────
//   texto   →  IndexedDB nosso        →  permanente
//   mapa    →  Cache API nosso        →  permanente (o tile TEM CORS: guardável)
//   foto    →  cache do navegador     →  60 min, e NÃO dá pra guardar
//
// A foto não é guardável porque `venue-image.waze.com` não manda CORS (medido:
// `access-control-allow-origin` ausente em toda variante e toda origem). Sem
// CORS a resposta é OPACA, e o Chrome cobra ~7,8 MB de orçamento por resposta
// opaca — medido com controle: os mesmos bytes custam 1,01× com CORS e 132×
// sem. As 226 fotos de uma fila custariam 1,76 GB contra ~1 GB de orçamento.
//
// ── O RELÓGIO ROLANTE ─────────────────────────────────────────────────────
// A foto vale 60 min A PARTIR DO DOWNLOAD, e o app não estica isso: reaquecer
// uma foto viva sai do cache, custa zero e NÃO renova o prazo (medido). O que
// renova é baixar de novo — e pra forçar isso o app troca o SUFIXO da URL
// (`?w=<janela>`), que o CDN do Waze aceita devolvendo bytes idênticos (medido
// em 5 variantes) e que o navegador trata como entrada separada, com relógio
// próprio (medido, com controle: a URL velha morre no prazo dela).
//
// Ciclo de 20 min = toda foto tem SEMPRE ao menos 40 min de vida quando o sinal
// cai. Custa uma varredura completa a cada 20 min: ~41 MB/h no Brasil. A conta
// só corre com o app ABERTO e COM SINAL — na sombra não há o que gastar.
const OFFLINE_CICLO_MS = 20 * 60 * 1000;
const OFFLINE_DB = 'waze_places_offline';
const OFFLINE_STORE = 'fila';
// O cache dos tiles é SEPARADO do da versão de propósito: o `activate` do
// service worker apaga todo cache que não seja o `CACHE_NAME`, então guardar
// tile lá dentro faria cada deploy apagar o que você provisionou — e você
// descobriria no meio da estrada. O SW isenta este nome explicitamente.
const OFFLINE_TILES_CACHE = 'waze-places-tiles';
// Os pedidos que POUSARAM no Waze depois de a fila guardada ser tirada (ver
// `registrarPouso`). É o que falta pra reabertura sem rede não devolver como
// card o que o editor já tratou COM rede. localStorage e não a base: a
// gravação é pequena e tem que valer mesmo se o app morrer logo depois do
// pouso — transação de IndexedDB pode não fechar a tempo.
const OFFLINE_POUSOS_KEY = 'waze_places_offline_pousos';
// Teto POR CONSTRUÇÃO. A lista é podada toda vez que a fila guardada é
// regravada (a cada busca e a cada varredura, no máximo 20 min de uso), então
// na prática ela guarda uns minutos de trabalho — o teto é só pra que um
// defeito na poda não a faça crescer sem fim.
const OFFLINE_POUSOS_MAX = 1000;
// Quantas imagens em voo ao mesmo tempo. Baixo de propósito: a varredura não
// pode atropelar a foto do card que o editor está olhando AGORA — é o defeito
// que o `agendarAquecimento` já existe pra evitar.
const OFFLINE_CONCORRENCIA = 3;
// Sem gesto na tela por este tempo, a varredura dorme. Sem isto o app cobraria
// dados de quem o deixou aberto no bolso.
const OFFLINE_OCIOSO_MS = 3 * 60 * 1000;
// Tentativas por ITEM antes de desistir dele nesta varredura (ver `offlineVarrer`).
const OFFLINE_TENTATIVAS_POR_ITEM = 3;

let offlineVarrendo = false;
let offlinePedidaDeNovo = false;
let offlineUltimoGesto = Date.now();
// A janela que o app SERVE — e ela NÃO é a hora atual. Só avança quando uma
// varredura termina de aquecer tudo sob o sufixo novo. Sem isso, virar a janela
// OFFLINE faria o card pedir uma URL que ninguém aqueceu e a foto sumiria com
// a cópia boa parada no cache, a um sufixo de distância.
let offlineJanelaServida = null;
// QUAL fila a última preparação COMPLETA cobriu. A fila guardada é regravada na
// busca e no começo de cada varredura, e a preparação "pronta" de uma fila velha
// não diz nada da nova: o pedido que a busca trouxe depois — ou DURANTE a
// varredura — não tem mapa nem foto no aparelho. As duas são o `t` da fila
// guardada: `offlineFilaGravadaEm` é o da que está na base (gravada por esta
// página, ou a que a reabertura sem rede abriu), e `offlineFilaPreparada` é o da
// que a última varredura PRONTA gravou no começo dela. Esta vai gravada junto da
// janela (`filaCoberta`), e é assim que ela sobrevive a fechar e reabrir. A
// linha das Preferências só diz "Pronto" quando as duas são a MESMA: dizia sobre
// qualquer fila guardada depois, por até uma hora (auditoria de 2026-09-30, a
// sobra do R5-4-6). Pela HORA não dá: a fila que a busca grava DURANTE a
// varredura fica com hora anterior ao fim dela (MEDIDO no navegador: a janela
// 49 ms depois da fila, e o tile do pedido novo fora do aparelho).
let offlineFilaGravadaEm = null;
let offlineFilaPreparada = null;
// OS PEDIDOS da fila guardada agora (as chaves de `chaveDoPedido`), junto do `t`
// dela. É com eles que a regravação da MESMA fila — a renovação de cada janela,
// que grava a fila de novo no começo — mantém o carimbo (ver `offlineGravarFila`).
let offlineFilaGravadaChaves = null;
// E a fila guardada sobre a qual a última varredura TRABALHOU — a que ela gravou
// no começo, ou a que já estava lá quando a gravação dela falhou. A fila não
// coberta volta pro gatilho uma vez só (ver `offlinePrecisaVarrer`).
let offlineFilaVarrida = null;
// Quando a varredura avisou o service worker pela última vez (`offlineAnunciarTiles`).
// O aviso é assíncrono: tile guardado há menos de um instante pode ainda não
// estar na lista do worker — `registrarFalhaDeTile` respeita essa janela.
let offlineUltimoAnuncio = 0;

// ── Pedaço de mapa GUARDADO que falhou na tela ────────────────────────────
// O app tira da tela o tile que falha (ícone quebrado no meio do mapa não
// informa nada) — e com ele sumia também a PROVA: nas 6 capturas do relato de
// 2026-09-22 não há tile quebrado nenhum, e nem poderia haver. Agora o mapa
// conta quantos pediu e quantos falharam (`data-tiles-*`, lidos pela geometria
// do diagnóstico) antes de apagar, e o tile que falhou ESTANDO GUARDADO entra
// no anel abaixo, que a sentinela `tileGuardadoFalhou` lê.
//
// "Guardado que falhou" só é anomalia com as três condições — é isso que faz
// dele INVARIANTE e não palpite:
//   · há service worker no comando (sem ele o cache não serve ninguém);
//   · nenhuma varredura em andamento e o último aviso ao worker tem mais de 2s
//     — tile guardado DURANTE a varredura só é servido depois do aviso, e o
//     aviso é assíncrono;
//   · o tile ESTÁ no cache de tiles na hora da falha. `caches.match` com
//     `cacheName` não CRIA o cache (o `caches.open` criaria), então quem nunca
//     ligou o offline não ganha um cache vazio por um tile falhar na rede.
const DIAG_TILES_FALHOS_TETO = 20;
let diagTilesGuardadosQueFalharam = [];
// Até onde o anel acima já foi LIDO por uma captura ou por um relatório. A
// sentinela acusa só o que veio DEPOIS: lendo o anel inteiro, UMA falha saía em
// toda captura e em todo relatório da página, inclusive num card sem mapa
// minutos depois — e alerta que se repete é alerta que se aprende a ignorar
// (auditoria de 2026-09-26). O total segue na seção `offline` do relatório.
let diagTilesLidosAte = 0;
function diagTilesParaAlerta() {
    return diagTilesGuardadosQueFalharam.filter((x) => x.t > diagTilesLidosAte).slice(-5);
}
function registrarFalhaDeTile(box, url) {
    try {
        if (box && box.dataset) {
            box.dataset.tilesFalharam = String((parseInt(box.dataset.tilesFalharam, 10) || 0) + 1);
        }
        if (!url || !window.caches) return;
        if (!(navigator.serviceWorker && navigator.serviceWorker.controller)) return;
        if (offlineVarrendo || Date.now() - offlineUltimoAnuncio < 2000) return;
        caches.match(url, { cacheName: OFFLINE_TILES_CACHE }).then((hit) => {
            if (!hit) return;
            diagTilesGuardadosQueFalharam.push({ t: Date.now(), url: String(url).slice(0, 200) });
            if (diagTilesGuardadosQueFalharam.length > DIAG_TILES_FALHOS_TETO) diagTilesGuardadosQueFalharam.shift();
            dfato('mapa.guardadoFalhou');
        }).catch(() => {});
    } catch (e) { /* o diagnóstico nunca derruba o mapa */ }
}

// Como a ÚLTIMA varredura terminou: 'pronto' | 'parcial' | null (nunca correu).
// Sem isto a linha congelava em "Preparando… 197 de 530" PARA SEMPRE quando a
// varredura desistia — o relato do owner. A varredura tinha ACABADO; quem
// mentia era a tela, porque o único redesenho acontecia com `offlineVarrendo`
// ainda true e nada redesenhava depois que ele virava false.
let offlineUltimoResultado = null;
// ÉPOCA do offline, no mesmo espírito do `fetchEpoch` da fila. `offlineEsquecer`
// a incrementa, e a varredura desiste se ela mudou DURANTE um `await`.
//
// Sem isto existe uma corrida REAL e com consequência de privacidade: o
// worker checa a preferência no topo do laço, mas o download já a caminho
// pousa DEPOIS do apagamento e faz `cache.put` num cache que acabou de ser
// deletado — recriando-o. O editor pediu pra esquecer e dado de mapa de
// terceiro volta a ser gravado. MEDIDO: `offlineEsquecer()` deixava 1 entrada
// no cache e a janela servida com valor.
//
// É a mesma regra que a fila de saída já tinha escrita: "sair no meio também
// PARA o laço".
let offlineEpoca = 0;
// O que já ficou PRONTO nesta janela (as URLs que baixaram, e as que se
// mostraram defeito do item): a retomada da preparação "parcial" baixa só o que
// FALTOU. Ela refazia a lista INTEIRA, e cada prova de rede pedia de novo todos
// os tiles (39 por prova numa fila de 30 pedidos, auditoria de 2026-09-30,
// R5-4-1). Vale pra janela E a época em que foi enchida: janela nova renova
// tudo (a foto vence), e esquecer apaga o cache que ela descreve. `guardados`:
// os TILES que baixaram, o pedaço da lista que o cache do aparelho tem que ter —
// conferido com ele no começo de cada varredura, porque a poda de OUTRA aba
// apaga dele sem esta saber (R13-4-03).
let offlineFeitosNaJanela = { janela: null, epoca: -1, us: new Set(), guardados: new Set() };

function offlineLigado() {
    return AppState.preferences.offlineDisponivel === true;
}

// ── A fila guardada é de UM LUGAR ─────────────────────────────────────────
// A região (o servidor do Waze) e o país do filtro da BUSCA que a trouxe
// (auditoria de 2026-09-26, O4). Ela não dizia de onde era: trocar de região,
// ver a busca nova vir vazia e reabrir sem rede mostrava a fila da região
// VELHA sob o filtro novo — e o ✕ saía pro servidor da região nova, voltava
// "não encontrado" e contava como feito (medido no navegador, p10). Hoje a
// fila leva o lugar e a reabertura recusa a de outro lugar — sem apagá-la:
// trocar de lugar SEM REDE e voltar ao de antes a encontra, e a busca com rede
// do lugar novo a regrava (R5-4-2). `filaDeOnde` é o lugar da fila EM MEMÓRIA:
// o da busca que a trouxe
// (a região pode mudar antes de a fila ser zerada — o país do perfil troca a
// região e ainda espera a lista de países), zerado a cada fila nova.
//
// E o "lugar" é também o FILTRO da busca (`busca`: a `assinaturaDeBusca` sem a
// ordem — estado, tipos, categoria, "Minha área", residencial, "lidos também").
// Os filtros eram gravados junto da fila e nunca lidos: trocar de estado, ver a
// busca nova vir vazia e reabrir sem rede mostrava a fila do filtro VELHO sob o
// novo (auditoria de 2026-09-29, O8, medido no navegador: estado 5 e só "Nova
// foto" abriam a fila do Brasil inteiro). Trocar só a ORDEM não muda a busca.
let filaDeOnde = null;
function lugarAgora() {
    return { regiao: API.getRegion(), pais: String(API.getCountry()), busca: assinaturaDeBusca(true) };
}
// A fila guardada SEM a assinatura (versão anterior) não é deste lugar: não há
// como saber de que filtro ela é, e a próxima busca com rede a regrava.
function mesmoLugar(a, b) {
    return !!a && !!b && typeof a.regiao === 'string' && a.regiao === b.regiao
        && a.pais !== undefined && a.pais !== null && String(a.pais) === String(b.pais)
        && a.busca === b.busca;
}

// FONTE ÚNICA da URL da foto. Card, lightbox e aquecimento passam TODOS por
// aqui — se um deles usar a URL crua, ele pede um endereço que ninguém aqueceu
// e a foto some offline, sem erro nenhum na tela. `test/offline.test.mjs`
// reprova quem atribuir `.src` a partir de `imageUrls` sem passar por aqui.
function urlDaFoto(u) {
    if (!u || !offlineLigado() || offlineJanelaServida === null) return u;
    return u + (u.indexOf('?') === -1 ? '?' : '&') + 'w=' + offlineJanelaServida;
}

// ── IndexedDB, o mínimo ───────────────────────────────────────────────────
// `localStorage` está fora: é SÍNCRONO e travaria a thread do swipe, que é o
// valor central do app (medido no projeto: 16,5 ms por gravação com 10 mil
// registros). Aqui são 357 KB de uma vez.
// Abrir a base tem TETO: o IndexedDB do WebKit às vezes não responde, e a
// reabertura sem rede esperava a fila guardada com o esqueleto na tela, sem fim
// (auditoria de 2026-09-25). Estourado, é "sem base" — o app segue como sem
// fila guardada.
const OFFLINE_DB_TETO_MS = 5000;
function offlineDB() {
    return new Promise((ok, erro) => {
        let req;
        try { req = indexedDB.open(OFFLINE_DB, 1); } catch (e) { return erro(e); }
        let estourou = false;
        const teto = setTimeout(() => { estourou = true; erro(new Error('timeout')); }, OFFLINE_DB_TETO_MS);
        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(OFFLINE_STORE)) db.createObjectStore(OFFLINE_STORE);
        };
        req.onsuccess = () => {
            clearTimeout(teto);
            // Abriu DEPOIS do teto: ninguém mais espera por ela — fecha, senão a
            // conexão esquecida seguraria as próximas aberturas.
            if (estourou) { try { req.result.close(); } catch (e) {} return; }
            ok(req.result);
        };
        req.onerror = () => { clearTimeout(teto); erro(req.error); };
        req.onblocked = () => { clearTimeout(teto); erro(new Error('blocked')); };
    });
}

// `desde` é o instante a partir do qual a lista gravada vale: o começo da busca
// que a trouxe, ou AGORA quando quem grava é a varredura (aí a lista é a fila
// viva, que já não tem nada do que foi decidido nesta página — o que segue nela
// decidido sai logo abaixo, R13-2-04). Vai gravado junto porque é contra ele que
// a reabertura sem rede filtra os pousos.
async function offlineGravarFila(desde) {
    // A fila REAL (`filaReal`), lida AGORA, antes do `await`. No treino a da tela
    // é a de EXEMPLOS (`_treino`, e parte sintética, com id que não existe):
    // gravada, ela voltaria como fila de verdade na próxima abertura sem rede, e
    // as ações iriam pro Waze (auditoria de 2026-09-25). E não gravar nada no
    // treino, como era, fazia o interruptor ligado SEM SINAL dizer "4 pedidos
    // guardados" com a base vazia: fechado e reaberto sem sinal, a tela era a de
    // "sem sinal" (R9-4-02, MEDIDO no navegador; auditoria de 2026-10-06). A real,
    // que o treino guarda, é a que a estrada vai precisar.
    //
    // SEM o que a OUTRA aba decidiu com o card ainda aqui (o da tela fica, por
    // decisão do R10-2-02, e o em andamento também): a lista vale a partir de
    // `desde`, e a poda logo abaixo apaga o pouso de lá, que é mais velho —
    // reaberto sem rede, o pedido voltava como card, e a segunda decisão, outra,
    // ia ao Waze (R12-4-01, MEDIDO no navegador: lido lá e rejeitado aqui). Pelo
    // OBJETO anotado, não pela chave: o mesmo pedido que volta numa busca de
    // depois (com "lidos também") é card legítimo, e vai.
    //
    // E SEM o que ESTA página já decidiu e segue na fila (R13-2-04): o que está EM
    // ANDAMENTO (`pedidosEmAndamento`: o alvo do "Marcar todos", que só sai da
    // fila no fim do lote, e a aprovação de foto no ar) e o que já POUSOU com o
    // card ainda nela (`pedidosQuePousaram`: os pedaços do lote que já pousaram, e
    // o pedido aprovado com a foto aberta). A poda logo abaixo apaga todo pouso
    // mais velho que `desde`, porque a lista "já o reflete" — e isso só é verdade
    // se ela não traz pedido decidido. A varredura que uma prova de rede dispara
    // no meio de um "Marcar todos" gravava os 30 alvos e podava os pousos dos 25
    // que o Waze já tinha marcado: reaberto sem rede, os 25 voltavam como card, e
    // o ✕ num deles ia ao Waze (MEDIDO no navegador, o1 da rodada 13). O que o
    // lote não marcar segue na fila e entra na próxima gravação.
    const fila = filaReal().filter((p) => !(typeof decididosPorOutraAbaComCardAqui !== 'undefined'
            && decididosPorOutraAbaComCardAqui.has(p) === true)
        && !(typeof pedidosEmAndamento !== 'undefined' && pedidosEmAndamento.has(chaveDoPedido(p)) === true)
        && !(typeof pedidosQuePousaram !== 'undefined' && pedidosQuePousaram.has(p) === true));
    if (!offlineLigado() || !fila.length) return false;
    // E o DONO: a sessão DESTA aba, a da MEMÓRIA (`marcaDestaAba`, R12-1-03), e
    // sem ela nada é gravado (R13-4-04). Era o `getSession`, que com a memória
    // vazia GRAVA nela a sessão que outra aba guardou no aparelho: a busca que
    // respondia depois da queda (a sessão desta aba caiu com o ↻ no ar, e a outra
    // aba da mesma conta tinha entrado de novo) ADOTAVA calada a sessão de lá —
    // a aba seguia na tela de entrada "logada", e o "Sair" da outra fechava o
    // "Colar cookies" daqui com o que estava sendo colado —, e a fila saía SEM
    // DONO (a conta é lida pela memória), por cima da boa (MEDIDO no navegador,
    // p7 da rodada 13). Sem sessão a fila não tem de quem ser; a próxima busca ou
    // varredura com sessão a grava.
    const sessao = marcaDestaAba();
    if (!sessao) return false;
    const valeDesde = Number.isFinite(desde) ? desde : Date.now();
    // Os filtros também são lidos antes do `await`.
    const filtros = JSON.parse(JSON.stringify(AppState.filters || {}));
    // O LUGAR da fila (ver `filaDeOnde`), lido AGORA pelo mesmo motivo.
    const lugar = filaDeOnde || lugarAgora();
    // E a conta (gravada antes de o perfil chegar, ela ainda é desconhecida, e a
    // sessão responde). Ver `filaGuardadaDestaConta`.
    const conta = contaAgora();
    let gravadaEm = null;
    let chaves = null;
    let mesmaFila = false;
    try {
        const db = await offlineDB();
        await new Promise((ok, erro) => {
            const tx = db.transaction(OFFLINE_STORE, 'readwrite');
            // Os pedidos do que vai pra base, lidos junto do `put` (a fila pode ter
            // mudado durante o `await`).
            chaves = fila.map(chaveDoPedido);
            // A MESMA fila — ou parte dela: o que foi decidido saiu — por cima da
            // fila guardada que a última preparação COMPLETA cobriu MANTÉM o
            // carimbo. A renovação de cada janela grava a fila de novo no começo,
            // e o carimbo novo quebrava a cobertura: com o sinal caindo no meio
            // dela (o "sai de casa"), ou o app fechado no meio, a linha sem sinal
            // voltava a "O mapa e as fotos chegam quando houver rede" com os dois
            // no aparelho (auditoria de 2026-10-01, R6-4-2). Pedido NOVO na fila
            // é carimbo novo — e "não coberta", como sempre.
            mesmaFila = offlineFilaGravadaEm !== null && offlineFilaGravadaEm === offlineFilaPreparada
                && offlineFilaGravadaChaves !== null
                && chaves.every((k) => k !== null && offlineFilaGravadaChaves.has(k));
            gravadaEm = mesmaFila ? offlineFilaGravadaEm : Date.now();
            tx.objectStore(OFFLINE_STORE).put({
                t: gravadaEm,
                desde: valeDesde,
                filtros,
                regiao: lugar.regiao,
                pais: lugar.pais,
                // A assinatura da busca, sem a ordem: é ela que a reabertura
                // compara (`mesmoLugar`). Os `filtros` acima vão pro diagnóstico.
                busca: lugar.busca,
                conta,
                s: sessao,
                places: fila,
            }, 'fila');
            tx.oncomplete = ok; tx.onerror = () => erro(tx.error);
            // `onabort` também: a cota estourada ABORTA a transação sem sempre
            // passar pelo `onerror`, e a promessa pendurada prendia a varredura
            // (`offlineVarrendo`) pra sempre (auditoria de 2026-09-25).
            tx.onabort = () => erro(tx.error || new Error('abort'));
        });
        db.close();
        // A fila que está na base AGORA (ver `offlineFilaPreparada`).
        offlineFilaGravadaEm = gravadaEm;
        offlineFilaGravadaChaves = new Set(chaves);
        // E as OUTRAS abas ficam sabendo que a fila guardada é esta (R13-4-03,
        // ver `aoGravarFilaGuardadaEmOutraAba`).
        if (typeof avisarOutrasAbasDaFilaGuardada === 'function') avisarOutrasAbasDaFilaGuardada(gravadaEm);
        // Só DEPOIS de a gravação fechar: se ela falhar, os pousos continuam
        // valendo contra a fila velha, que é a que a reabertura vai ler.
        offlinePodarPousos(valeDesde);
        dfato('offline.gravou', { n: fila.length, ...(mesmaFila ? { mesma: true } : {}) });
        return true;
    } catch (e) { return false; }
}

// ── Duas abas, UMA fila guardada (R13-4-03) ──────────────────────────────
// A base e o cache do mapa são do APARELHO; a MEMÓRIA de cada aba diz qual fila
// está guardada (`offlineFilaGravadaEm`) e se a preparação a cobriu. Com a fila
// de OUTRA aba gravada por cima, a linha desta seguia dizendo "Pronto — 12
// pedidos no aparelho" — com a fila guardada sendo a da outra, e a poda de lá
// tendo apagado o mapa dos pedidos que só esta tinha (MEDIDO no navegador, p3 da
// rodada 13: 6 dos 12 sem mapa). A gravação avisa as outras abas por um
// `BroadcastChannel` — nada vai pro aparelho, e a mensagem leva só o carimbo da
// fila —, e quem recebe passa a saber que a fila guardada é outra: a linha diz
// "Ainda não preparado", e o próximo gatilho (a prova de rede, abrir as
// Preferências) prepara a fila DESTA aba, com o mapa que a poda de lá levou (ver
// os `guardados` da varredura). A fila guardada é a da última aba que gravou, a
// do uso. Sem `BroadcastChannel` (iOS < 15.4), segue como antes. O canal é
// aberto uma vez por página (`setupSincroniaEntreAbas`).
const CANAL_DO_OFFLINE = 'waze-places-offline';
let canalDoOffline = null;

function abrirCanalDoOffline() {
    if (canalDoOffline || typeof BroadcastChannel !== 'function') return;
    try { canalDoOffline = new BroadcastChannel(CANAL_DO_OFFLINE); } catch (e) { canalDoOffline = null; return; }
    canalDoOffline.onmessage = (ev) => aoGravarFilaGuardadaEmOutraAba(ev && ev.data);
}

// O canal não entrega a mensagem ao objeto que a mandou: esta aba não recebe o
// próprio aviso.
function avisarOutrasAbasDaFilaGuardada(t) {
    if (!canalDoOffline || !Number.isFinite(t)) return;
    try { canalDoOffline.postMessage({ v: 1, filaGuardada: t }); } catch (e) { /* canal fechado: segue como antes */ }
}

// A fila guardada agora é a que OUTRA aba gravou. Nada aqui grava no aparelho.
// A varredura no ar desta aba segue: no fim, a poda dela confere de quem é a fila
// na base (R12-4-05). O aviso da MESMA fila que esta aba tem (o mesmo carimbo) não
// muda nada.
function aoGravarFilaGuardadaEmOutraAba(aviso) {
    if (!aviso || aviso.v !== 1 || !Number.isFinite(aviso.filaGuardada)) return;
    if (aviso.filaGuardada === offlineFilaGravadaEm) return;
    offlineFilaGravadaEm = aviso.filaGuardada;
    dfato('offline.outraAba', {});
    // As Preferências podem estar abertas: a linha diz o que é verdade agora.
    atualizarLinhaDoOffline(0, 0);
}

// A JANELA SERVIDA também fica guardada, na mesma base e com a mesma vida (o
// `offlineEsquecer` apaga as duas). É ela que monta a URL que a varredura
// aqueceu (`urlDaFoto`), e ela morava só em memória: o app REABERTO sem rede
// nascia com a janela nula, pedia a foto CRUA — que ninguém aqueceu — e TODO
// card de foto abria com "a foto precisa de sinal". É o caso do Android, que
// encerra o app em segundo plano e o faz renascer justamente na sombra.
// Gravada só quando a varredura TERMINA, igual à janela em memória: sufixo de
// varredura pela metade é foto que não está no cache. Vai junto QUAL fila ela
// cobriu (`filaCoberta`, ver `offlineFilaPreparada`); o registro de versão
// anterior não tem o campo, e a linha das Preferências o lê como não coberta.
async function offlineGravarJanela(janela, filaCoberta = null) {
    try {
        const db = await offlineDB();
        await new Promise((ok, erro) => {
            const tx = db.transaction(OFFLINE_STORE, 'readwrite');
            tx.objectStore(OFFLINE_STORE).put({ janela, t: Date.now(), filaCoberta }, 'janela');
            tx.oncomplete = ok; tx.onerror = () => erro(tx.error);
            // `onabort` também: a cota estourada ABORTA a transação sem sempre
            // passar pelo `onerror`, e a promessa pendurada prendia a varredura
            // (`offlineVarrendo`) pra sempre (auditoria de 2026-09-25).
            tx.onabort = () => erro(tx.error || new Error('abort'));
        });
        db.close();
    } catch (e) {}
}

// O registro inteiro: `{ janela, t, filaCoberta }`.
async function offlineLerRegistroDaJanela() {
    try {
        const db = await offlineDB();
        const v = await new Promise((ok, erro) => {
            const tx = db.transaction(OFFLINE_STORE, 'readonly');
            const r = tx.objectStore(OFFLINE_STORE).get('janela');
            r.onsuccess = () => ok(r.result); r.onerror = () => erro(r.error);
        });
        db.close();
        return v && Number.isFinite(v.janela) ? v : null;
    } catch (e) { return null; }
}

async function offlineLerJanela() {
    const v = await offlineLerRegistroDaJanela();
    return v ? v.janela : null;
}

// A janela da última preparação COMPLETA volta da base, e com ela QUAL fila
// essa preparação cobriu. Só quando a memória não tem uma: com o app vivo, a de
// memória é a mais nova.
async function offlineRecuperarJanela() {
    const r = await offlineLerRegistroDaJanela();
    if (!r || offlineJanelaServida !== null) return;
    offlineJanelaServida = r.janela;
    offlineFilaPreparada = Number.isFinite(r.filaCoberta) ? r.filaCoberta : null;
}

async function offlineLerFila() {
    try {
        const db = await offlineDB();
        const v = await new Promise((ok, erro) => {
            const tx = db.transaction(OFFLINE_STORE, 'readonly');
            const r = tx.objectStore(OFFLINE_STORE).get('fila');
            r.onsuccess = () => ok(r.result); r.onerror = () => erro(r.error);
        });
        db.close();
        return v && Array.isArray(v.places) && v.places.length ? v : null;
    } catch (e) { return null; }
}

// `soMemoria`: o "Sair" (ou o desligar do offline) foi em OUTRA aba, que já
// apagou a base, o cache e os pousos. Esta só para a varredura em voo — que
// gravaria de novo no que a outra acabou de apagar — e solta a memória.
async function offlineEsquecer({ soMemoria = false } = {}) {
    offlineEpoca++;                 // invalida qualquer varredura em voo
    offlineJanelaServida = null;
    offlineUltimoResultado = null;
    offlineFilaGravadaEm = null;
    offlineFilaGravadaChaves = null;
    offlineFilaPreparada = null;
    offlineFilaVarrida = null;
    // O que estava pronto descreve o cache que sai logo abaixo (e são endereços
    // de pedidos de terceiros): vai junto.
    offlineFeitosNaJanela = { janela: null, epoca: -1, us: new Set(), guardados: new Set() };
    // As URLs de tile dizem ONDE ficam pedidos de terceiros: vão junto com o
    // resto do que o offline guardou.
    diagTilesGuardadosQueFalharam = [];
    // A fila guardada que espera o "Sair" do treino é a da base que sai — aqui,
    // ou na outra aba (`soMemoria`) —: a anotação dela sai junto (R10-4-04).
    if (typeof Treino !== 'undefined') Treino.esquecerFilaGuardada?.();
    if (soMemoria) return;
    // Os pousos só existem pra filtrar a fila guardada, que sai na linha de
    // baixo: sem ela não há o que filtrar, e são ids de pedidos de terceiros.
    safeLS.remove(OFFLINE_POUSOS_KEY);
    try { indexedDB.deleteDatabase(OFFLINE_DB); } catch (e) {}
    try { if (window.caches) await caches.delete(OFFLINE_TILES_CACHE); } catch (e) {}
    // E o worker esquece a LISTA dele, que é o mesmo dado em memória: sem o
    // aviso, ela seguiria com centenas de endereços até ele adormecer — e o
    // relatório o mostraria "conhecendo" tiles que já não existem. Relida com
    // o cache apagado, ela sai vazia.
    offlineAnunciarTiles();
}

// ── A VARREDURA ───────────────────────────────────────────────────────────
// Ordem de FILA (o card 1 primeiro), e o que FALHA volta pro fim. A retomada
// não é zelo: MEDIDO numa estrada simulada de 20s de sinal / 40s de buraco, com
// retomada saem 160 cards prontos e ZERO perdidos; sem ela, 77 cards e 404
// pedaços perdidos PARA SEMPRE. É metade do recurso numa linha.
// A caixa do mapa NÃO é a mesma em todo card. Ela é o que sobra depois do
// texto, e encolhe quando o card tem comentário de reporte ou diff: MEDIDO no
// aparelho do owner, 378×337 num card de foto e 378×189 no reporte com
// comentário. Caixa diferente pode escolher OUTRO ZOOM — logo outros tiles. A
// varredura usava a caixa do card que estivesse na frente pra TODOS, e na fila
// real dele isso deixava 7 de 172 cards com buraco no mapa numa caixa de 189px
// e 12 numa de 144 (e 37 numa de 88, o piso). Por isso os tiles saem da FAIXA
// de alturas que um card pode ter, não de uma altura só.
//
// O PISO é o menor `min-height` do `.card-photo` no styles.css (o card com
// comentário, 5.5rem), convertido pela fonte da raiz na hora — rem acompanha a
// fonte do sistema. `test/offline.test.mjs` cobra que o CSS não desça abaixo.
//
// O TETO é a pilha, limitado a MAPA_TILE − 8: MEDIDO, até 504px o custo é o
// mesmo (313 tiles na fila do owner), e em 512 salta pra 470 — é onde a caixa
// deixa de caber numa fileira de tiles. Foto de card de celular nunca chega
// perto disso: o texto ocupa ~190px.
//
// O PASSO de 16px é exato: na fila real, toda altura inteira de 88 a 504 dá os
// MESMOS 313 tiles que passos de 4, 8, 16, 32 e até 64px. 16 fica com folga.
const OFFLINE_CAIXA_MIN_REM = 5.5;
const OFFLINE_CAIXA_PASSO_PX = 16;

function offlineFaixaDeCaixas() {
    const frente = cardDaFrente();
    const cx = frente && frente.querySelector('.card-photo');
    const w = (cx && cx.clientWidth) || 400;
    const hFrente = (cx && cx.clientHeight) || 240;
    const pilha = document.getElementById('cardStack');
    const hPilha = (pilha && pilha.clientHeight) || hFrente;
    const rem = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
    const hMin = Math.round(OFFLINE_CAIXA_MIN_REM * rem);
    const hMax = Math.max(hFrente, Math.min(hPilha, MAPA_TILE - 8));
    return { w, hMin: Math.min(hMin, hMax), hMax };
}

// Os tiles de TODAS as alturas da faixa. Mesmo zoom em caixa menor pede um
// subconjunto; o que a faixa acrescenta é o zoom que muda quando a caixa encolhe.
function tilesDaFaixa(place, faixa) {
    const s = new Set();
    for (let h = faixa.hMax; h >= faixa.hMin; h -= OFFLINE_CAIXA_PASSO_PX) {
        for (const u of tilesDoCard(place, faixa.w, h)) s.add(u);
    }
    for (const u of tilesDoCard(place, faixa.w, faixa.hMin)) s.add(u);
    return s;
}

async function offlineItensDaFila(janela) {
    const itens = [];
    const vistos = new Set();   // pedido vizinho divide tile: baixa uma vez só
    const faixa = offlineFaixaDeCaixas();
    // CÓPIA da fila: o laço cede a thread, e quem tria desliza no meio — o
    // `shift()` do avanço deslocaria o iterador e pularia um pedido calado.
    // E a fila REAL (`filaReal`): a varredura a lê DEPOIS de gravá-la (um
    // `await`), e o treino que abria nesse meio a fazia preparar os EXEMPLOS,
    // dar a fila real por "Pronto" e a poda apagar do cache o mapa dos pedidos
    // reais que não viraram exemplo (R9-4-01, MEDIDO no navegador: 10 de 40
    // pedidos sem nenhum tile; auditoria de 2026-10-06).
    const fila = filaReal().slice();
    let i = 0;
    for (const p of fila) {
        for (const u of tilesDaFaixa(p, faixa)) {
            if (vistos.has(u)) continue;
            vistos.add(u);
            itens.push({ u, tile: true });
        }
        // A foto em que o card ABRE, pela mesma regra do carrossel: num pedido de
        // foto é a EM DECISÃO, que em 13 de 76 da fila do owner não é a primeira.
        const fotos = fotosDoCard(p);
        const f = fotos.urls[fotos.inicial];
        if (f) itens.push({ u: f + (f.indexOf('?') === -1 ? '?' : '&') + 'w=' + janela, tile: false });
        // ~16 ms num desktop pra fila inteira, e 4–6× isso num celular: sem
        // ceder a thread vira tarefa longa no meio do arraste de quem tria.
        if (++i % 20 === 0) await new Promise((r) => setTimeout(r, 0));
    }
    return itens;
}

// Teto de UM download da varredura (tile ou foto), da primeira byte à gravação.
// Sem ele, a conexão que PENDURA — portal cativo, sinal indo e voltando: a
// requisição sai e nada volta — deixava a varredura "varrendo" pra sempre, e
// todo gatilho novo só marcava `offlinePedidaDeNovo` (auditoria de 2026-09-26,
// O9). Estourado, o item conta como falha de REDE ('teto'). 30 s cobrem uma foto
// de ~200 KB a ~55 kbps; tile tem 10–30 KB.
const OFFLINE_ITEM_TETO_MS = 30 * 1000;

function offlineBaixar(u, tile) {
    // Tile vai pro NOSSO cache (tem CORS, então a resposta é transparente e
    // custa 1,01× de orçamento). Foto vai pro cache do navegador via <img>, que
    // é o MESMO caminho que o card usa — `fetch` popula outra entrada, e a
    // <img> não a enxerga (medido: aquecido por fetch, o card quebra offline).
    if (!tile) {
        return new Promise((r) => {
            const i = new Image();
            let feito = false;
            let teto = 0;
            const fim = (v) => {
                if (feito) return;
                feito = true;
                clearTimeout(teto);
                i.onload = i.onerror = null;
                // Desistir é CANCELAR: trocar o `src` aborta o download pendurado.
                if (v === 'teto') i.src = '';
                r(v);
            };
            teto = setTimeout(() => fim('teto'), OFFLINE_ITEM_TETO_MS);
            i.fetchPriority = 'low'; i.decoding = 'async';
            i.onload = () => fim(true); i.onerror = () => fim(false);
            i.src = u;
        });
    }
    const epoca = offlineEpoca;
    return (async () => {
        // O teto vale até a GRAVAÇÃO no cache: o `put` lê o corpo, e um corpo que
        // pendura depois do cabeçalho prendia a varredura do mesmo jeito. Abortar
        // o pedido aborta o corpo junto. `AbortController`, e não o
        // `AbortSignal.timeout`, pra valer também no iPhone antes do iOS 16.
        const ctrl = new AbortController();
        let estourou = false;
        const teto = setTimeout(() => { estourou = true; ctrl.abort(); }, OFFLINE_ITEM_TETO_MS);
        try {
            // `no-cache`: cópia CONFERIDA com o servidor (condicional — o de tile
            // responde 304 quando nada mudou). E o service worker não a responde
            // do cache guardado (ver lá): respondida por ele, a varredura nunca
            // revalidava o tile, e o guardado ficava o da primeira vez pra sempre.
            const resp = await fetch(u, { mode: 'cors', cache: 'no-cache', signal: ctrl.signal });
            // 4xx é DEFINITIVO (o tile não existe): repetir não muda nada, e era
            // o que fazia a varredura martelar a mesma URL centenas de vezes.
            // 5xx segue como falha de rede: o servidor pode voltar.
            if (resp.status >= 400 && resp.status < 500) return 'definitivo';
            if (!resp.ok) return false;
            // Última trava antes de ESCREVER: se esqueceram durante o download,
            // gravar aqui recria o cache que o "Sair" acabou de apagar.
            if (epoca !== offlineEpoca) return false;
            const c = await caches.open(OFFLINE_TILES_CACHE);
            await c.put(u, resp);
            return true;
        } catch (e) { return estourou ? 'teto' : false; }
        finally { clearTimeout(teto); }
    })();
}

// A rede ANDA? Um pedido de um tile DESTA fila, conferido com o servidor
// (`no-cache`: o de tile responde 304 quando nada mudou, é barato). Qualquer
// resposta é rede de pé — até um erro do servidor, que respondeu; falha de rede
// ou o teto, não. Não grava nada: é só a pergunta (ver `offlineVarrer`).
const OFFLINE_SONDA_TETO_MS = 10 * 1000;
async function offlineSondarRede(u) {
    const ctrl = new AbortController();
    const teto = setTimeout(() => ctrl.abort(), OFFLINE_SONDA_TETO_MS);
    try {
        const r = await fetch(u, { mode: 'cors', cache: 'no-cache', signal: ctrl.signal });
        if (r.body) r.body.cancel().catch(() => {});
        return true;
    } catch (e) { return false; }
    finally { clearTimeout(teto); }
}

// PODA o cache do mapa ao que a fila guardada usa. Sem ela o cache só crescia:
// cada fila nova somava os tiles dela aos de todas as anteriores, pra sempre
// (auditoria de 2026-09-25). Renovar não era problema — MEDIDO: o servidor de
// tile responde `If-None-Match` com 304, então a varredura a cada janela já
// revalida o tile barato. `caches.has` antes de `open` pelo mesmo motivo da
// hidratação do worker (`open` CRIA o cache), e a época pra não mexer num cache
// que o "Sair" acabou de apagar.
//
// O que ela apaga sai TAMBÉM da lista do "já pronto" desta janela
// (`offlineFeitosNaJanela`): a lista não sabia da poda, e o pedido que VOLTA à
// fila na mesma janela — o filtro de antes aplicado de novo, o pulado que o ↻
// traz, o recusado que a `devolverPedidoRecusado` devolve — era pulado como
// pronto. A linha dizia "Pronto" e, sem rede, o mapa dele abria vazio, sem
// sentinela nenhuma (o tile nem estava no cache). Auditoria de 2026-10-01, R6-4-1.
async function offlinePodarTiles(manter, epoca) {
    try {
        if (!(await caches.has(OFFLINE_TILES_CACHE))) return 0;
        const c = await caches.open(OFFLINE_TILES_CACHE);
        if (epoca !== offlineEpoca) return 0;
        let n = 0;
        for (const req of await c.keys()) {
            if (epoca !== offlineEpoca) return n;
            if (!manter.has(req.url)) {
                // Sai da lista ANTES do cache: o contrário deixaria, nesse meio, um
                // tile "pronto" que já não está no aparelho.
                if (offlineFeitosNaJanela.epoca === epoca) {
                    offlineFeitosNaJanela.us.delete(req.url);
                    offlineFeitosNaJanela.guardados?.delete(req.url);
                }
                await c.delete(req);
                n++;
            }
        }
        return n;
    } catch (e) { return 0; }
}

// Avisa o service worker que há tile novo no cache. Ele só responde pelo que
// CONHECE (lista síncrona), e sem o aviso só saberia na próxima partida — a
// sombra de sinal chegaria antes. Sai a cada `OFFLINE_ANUNCIAR_A_CADA` tiles
// guardados e em todo fim de varredura; reler a lista custa um `keys()` de
// algumas centenas de entradas.
const OFFLINE_ANUNCIAR_A_CADA = 50;
function offlineAnunciarTiles() {
    offlineUltimoAnuncio = Date.now();
    try { navigator.serviceWorker?.controller?.postMessage({ type: 'TILES_GUARDADOS' }); } catch (e) {}
}

async function offlineVarrer() {
    if (!offlineLigado()) return;
    if (offlineVarrendo) { offlinePedidaDeNovo = true; return; }
    if (!AppState.authenticated || !AppState.queue.length) return;
    // No treino nenhuma varredura COMEÇA: a próxima prova de rede depois do "Sair"
    // a dispara. A que já estava no ar quando ele abriu segue sobre a fila REAL
    // (`offlineGravarFila` e `offlineItensDaFila` leem a `filaReal`, R9-4-01).
    if (Treino.ativo) return;
    // `onLine === false` é confiável pra "não tem rede"; `true` não prova nada
    // (portal cativo diz true e mente). Só o false muda comportamento — a mesma
    // regra de uma mão só da fila de saída.
    if (navigator.onLine === false) return;
    if (Date.now() - offlineUltimoGesto > OFFLINE_OCIOSO_MS) return;

    offlineVarrendo = true;
    offlinePedidaDeNovo = false;
    const janela = Math.floor(Date.now() / OFFLINE_CICLO_MS);
    const epoca = offlineEpoca;
    let tilesNovos = 0;
    try {
        // A fila que ESTA varredura cobre é a que ela grava agora; a que uma
        // busca gravar depois — ou durante — não é (ver `offlineFilaPreparada`).
        // A gravação que falhou não diz qual fila está na base: aí nenhuma.
        const filaGravada = await offlineGravarFila();
        const filaCoberta = filaGravada ? offlineFilaGravadaEm : null;
        // Cobrindo ou não, esta é a fila guardada sobre a qual ela trabalha: o
        // gatilho da fila não coberta não a traz de volta (ver `offlinePrecisaVarrer`).
        offlineFilaVarrida = offlineFilaGravadaEm;
        const todos = await offlineItensDaFila(janela);
        const total = todos.length;
        // Os tiles DESTA fila, da lista inteira: é o que a poda do fim mantém.
        const tilesDaFila = new Set(todos.filter((it) => it.tile).map((it) => it.u));
        // Baixa só o que FALTA nesta janela (ver `offlineFeitosNaJanela`): a
        // retomada do "parcial" e a reposição não repetem o que já ficou pronto.
        if (offlineFeitosNaJanela.janela !== janela || offlineFeitosNaJanela.epoca !== epoca) {
            offlineFeitosNaJanela = { janela, epoca, us: new Set(), guardados: new Set() };
        }
        const feitos = offlineFeitosNaJanela.us;
        // Os TILES que esta aba guardou no cache nesta janela: o pedaço do "feito"
        // que o cache tem que ter (o que se mostrou defeito do item — o 4xx, o que
        // esgotou as tentativas — não está lá, e não volta a ser pedido).
        const guardados = offlineFeitosNaJanela.guardados || (offlineFeitosNaJanela.guardados = new Set());
        // O cache do mapa é do APARELHO, e a poda da OUTRA aba (a varredura pronta
        // dela, sobre a fila guardada dela) apaga os tiles dos pedidos que só esta
        // aba tem. O "feito" desta janela é da MEMÓRIA desta aba e não sabia disso:
        // a varredura seguinte, na mesma janela, pulava esses tiles como prontos e
        // terminava "Pronto — 13 pedidos no aparelho" com 6 sem mapa (R13-4-03,
        // MEDIDO no navegador, p3 da rodada 13). Antes de pular, confere com o
        // cache: o que sumiu dele volta pro que falta. Uma leitura do cache (o
        // mesmo `keys()` da poda), nenhuma requisição — e só quando há o que
        // conferir: a primeira varredura da janela não lê nada.
        if (guardados.size && typeof caches !== 'undefined') {
            let noCache = null;
            try {
                noCache = (await caches.has(OFFLINE_TILES_CACHE))
                    ? new Set((await (await caches.open(OFFLINE_TILES_CACHE)).keys()).map((r) => r.url))
                    : new Set();
            } catch (e) { noCache = null; }   // sem como ler: fica como estava
            if (epoca !== offlineEpoca) return;   // esqueceram no meio
            if (noCache) for (const u of [...guardados]) if (!noCache.has(u)) { guardados.delete(u); feitos.delete(u); }
        }
        const pend = todos.filter((it) => !feitos.has(it.u));
        const jaFeitos = total - pend.length;
        let falhas = 0;
        let sucessos = 0;
        // A SONDA: o item esgotou as tentativas SEM que nada mais andasse nesse
        // meio — a rede parou, ou ele é o ÚLTIMO da fila (a foto do último
        // pedido, um 404 mais lento que o resto), sem ninguém atrás dele pra
        // provar que a rede anda. Era esse o caso que deixava a preparação
        // "parcial" PRA SEMPRE: a janela nunca virava (o card pedia a foto crua,
        // que ninguém guardou) e cada prova de rede refazia a varredura inteira
        // (auditoria de 2026-09-30, R5-4-1). Antes de culpar a rede, pergunta a
        // ela com UM pedido barato. A resposta NEGATIVA vale até o próximo
        // sucesso (a rede não volta sem que algo ande) — sem isso, numa rede
        // parada cada item esgotado esperaria a sua; a positiva não passa pro
        // item seguinte (a rede pode ter caído depois dela). Dois itens
        // esgotando juntos esperam a MESMA sonda.
        let sondas = 0;
        let sondaNegativaEm = -1;
        let sondaNoAr = null;
        const redeAnda = () => {
            if (sondaNegativaEm === sucessos) return Promise.resolve(false);
            if (sondaNoAr) return sondaNoAr;
            const u = [...tilesDaFila].find((x) => feitos.has(x)) || tilesDaFila.values().next().value;
            if (!u) return Promise.resolve(false);
            sondas++;
            sondaNoAr = offlineSondarRede(u).then((anda) => {
                sondaNoAr = null;
                if (!anda) sondaNegativaEm = sucessos;
                return anda;
            });
            return sondaNoAr;
        };
        // O que desistiu por REDE (a varredura toda parada) e o que desistiu por
        // ser o ITEM (foto que o Waze tirou do ar, tile 4xx): o primeiro deixa a
        // preparação "parcial" pra próxima rede; o segundo não tem conserto e
        // não pode segurar a preparação pra sempre — era o que fazia 1 foto
        // quebrada gastar 1.000 tentativas e a linha ficar em "499 de 500".
        const desistidosPorRede = [];
        let definitivos = 0;
        // Downloads que estouraram o teto em SEQUÊNCIA, sem nenhum sucesso no meio
        // (ver `OFFLINE_ITEM_TETO_MS`). Uma rodada inteira deles — um por
        // trabalhador — é a rede pendurada mesmo com `onLine` (portal cativo): a
        // varredura para, "parcial", em vez de gastar o teto em cada item da fila
        // (500 itens × 3 tentativas × 30 s era "varrendo" por mais de uma hora).
        let penduradasSeguidas = 0;
        const trabalhar = async () => {
            while (pend.length) {
                if (epoca !== offlineEpoca) return;   // esqueceram no meio
                if (!offlineLigado() || navigator.onLine === false) return;
                if (penduradasSeguidas >= OFFLINE_CONCORRENCIA) return;
                const it = pend.shift();
                const ok = await offlineBaixar(it.u, it.tile);
                // DEPOIS do await também: é aqui que a corrida mora — o
                // download pousa e o `cache.put` recriaria o que foi apagado.
                if (epoca !== offlineEpoca) return;
                // O worker só serve o tile que ele CONHECE, e ele só fica
                // sabendo pelo aviso. Avisar só no fim deixava o que já foi
                // guardado invisível pra ele a varredura inteira — e numa rede
                // ruim, que é quando ela demora, é justamente quando o mapa
                // precisa do cache.
                if (ok === true) {
                    sucessos++;
                    feitos.add(it.u);
                    if (it.tile) guardados.add(it.u);
                    penduradasSeguidas = 0;
                    if (it.tile && ++tilesNovos % OFFLINE_ANUNCIAR_A_CADA === 0) offlineAnunciarTiles();
                } else if (ok === 'definitivo') {
                    definitivos++;
                    feitos.add(it.u);
                    penduradasSeguidas = 0;   // o servidor respondeu: a rede anda
                } else {
                    falhas++;
                    if (ok === 'teto') penduradasSeguidas++;
                    it.tentativas = (it.tentativas || 0) + 1;
                    if (it.tentativas === 1) it.sucessosAntes = sucessos;
                    if (it.tentativas >= OFFLINE_TENTATIVAS_POR_ITEM) {
                        // Esgotou. Se o RESTO andou nesse meio, a rede está de
                        // pé e o defeito é o item; se nada andou, a SONDA diz
                        // se é a rede (ver `redeAnda`).
                        if (sucessos > it.sucessosAntes || await redeAnda()) {
                            definitivos++;
                            feitos.add(it.u);
                        } else desistidosPorRede.push(it);
                    } else {
                        if (falhas > total * 2) return;   // teto: rede morta, para
                        // volta pro FIM: buraco de sinal não pode perder o item
                        pend.push(it);
                        await new Promise((r) => setTimeout(r, 400));
                    }
                }
                atualizarLinhaDoOffline(total - pend.length, total);
            }
        };
        await Promise.all(Array.from({ length: OFFLINE_CONCORRENCIA }, trabalhar));
        // Só AGORA a janela vira: enquanto a varredura não terminou, o card
        // segue pedindo o sufixo anterior, cuja cópia está viva no cache.
        if (epoca !== offlineEpoca) return;   // esqueceram: não grava resultado
        if (!pend.length && !desistidosPorRede.length) {
            offlineFilaPreparada = filaCoberta;
            offlineJanelaServida = janela;
            // SEM `await` antes, e isso importa: o `open` sai neste mesmo tique,
            // logo depois da checagem de época acima — um "Sair" que venha em
            // seguida entra na fila do IndexedDB DEPOIS dele e apaga tudo.
            offlineGravarJanela(janela, filaCoberta);
            offlineUltimoResultado = 'pronto';
            dfato('offline.pronto', { n: filaReal().length, itens: total, ...(definitivos ? { definitivos } : {}),
                                      ...(jaFeitos ? { jaFeitos } : {}), ...(sondas ? { sondas } : {}) });
            // Só no "pronto": a lista inteira é a da fila guardada. AGUARDADA, com
            // a varredura ainda no ar (`offlineVarrendo`): o gatilho que chegar
            // nesse meio fica pra depois dela (`offlinePedidaDeNovo`). Solta, a
            // varredura seguinte — a da busca que chegou durante esta — começava
            // com a poda ainda apagando: contava como pronto o tile de um pedido
            // que voltou à fila e terminava "pronto" sem ele (R6-4-1). O resultado
            // já está decidido acima; a poda só arruma o cache.
            //
            // E só se a fila guardada AINDA é a que esta varredura gravou
            // (`filaCoberta`, o `t` dela), relida da base agora. A base e o cache do
            // mapa são do APARELHO, e outra aba grava a fila DELA por cima: com duas
            // abas varrendo juntas (o `online` chega às duas), a poda desta mantinha
            // só os tiles da fila desta e apagava os dos pedidos que só a outra tem —
            // a fila guardada era a da outra, e sem rede esses cards abriam sem mapa,
            // com a linha dizendo "Pronto — 12 pedidos no aparelho" (auditoria da
            // rodada 12, R12-4-05, MEDIDO no navegador: 6 de 12 sem mapa, em 3 de 3
            // rodadas). Se outra gravação veio depois (a outra aba, ou a busca desta
            // durante a varredura), quem poda é a varredura DELA, que cobre a fila
            // que ficou. A gravação que falhou (`filaCoberta` nulo) também não poda:
            // a fila na base é outra, e o mapa dela fica.
            const naBase = Number.isFinite(filaCoberta) ? await offlineLerFila() : null;
            if (naBase && naBase.t === filaCoberta && epoca === offlineEpoca) {
                const n = await offlinePodarTiles(tilesDaFila, epoca);
                if (n && epoca === offlineEpoca) { offlineAnunciarTiles(); dfato('offline.podou', { n }); }
            }
        } else {
            offlineUltimoResultado = 'parcial';
            dfato('offline.parcial', { feitos: total - pend.length - desistidosPorRede.length, total, falhas, definitivos,
                                       ...(jaFeitos ? { jaFeitos } : {}), ...(sondas ? { sondas } : {}) });
        }
    } catch (e) {
        offlineUltimoResultado = 'parcial';
        dfato('offline.erro', { e: String((e && e.message) || e).slice(0, 60) });
    } finally {
        // O aviso ao worker sai em TODO fim — pronto, parcial ou erro —, e não
        // só no "pronto", como era. A varredura interrompida (o sinal caindo no
        // meio da preparação, que é o caso comum de quem sai de casa) guardava
        // tiles que o worker não servia até a próxima partida dele: o mapa
        // estava no aparelho e sumia do card. Achado desenhando a sentinela
        // `tileGuardadoFalhou`, que acusaria exatamente isso. Não avisa se
        // esqueceram no meio: aí o cache foi apagado.
        if (epoca === offlineEpoca && tilesNovos) offlineAnunciarTiles();
        offlineVarrendo = false;
        // DEPOIS de baixar a bandeira, senão a linha fica no "Preparando…" de
        // uma varredura que já acabou.
        atualizarLinhaDoOffline(0, 0);
        if (offlinePedidaDeNovo) { offlinePedidaDeNovo = false; return offlineVarrer(); }
    }
}

// ── A LINHA DA PREFERÊNCIA ────────────────────────────────────────────────
// Cinco estados, e nenhum deles é uma barra de status ambiente: isto é
// RESPOSTA A UM GESTO que a pessoa acabou de fazer. Aviso permanente de
// "offline parcial" seria ansiedade sem ação — ninguém faz sinal aparecer.
function atualizarLinhaDoOffline(feitos, total) {
    const el = document.getElementById('prefOfflineDesc');
    if (!el) return;
    if (!offlineLigado()) { el.textContent = t('prefs.offline.desc'); return; }
    const semRede = navigator.onLine === false;
    // Os pedidos no aparelho são os da fila REAL (`filaReal`): com o treino
    // aberto, a da tela são os EXEMPLOS, e a linha dizia "Pronto — 30 pedidos no
    // aparelho" (os clones do treino) com 40 guardados — e, com a fila curta, os
    // exemplos inventados contavam junto (auditoria de 2026-10-03, R8-4-05). Com a
    // fila real do treino VAZIA e a fila guardada esperando o "Sair" dele
    // (`filaGuardadaEsperandoOTreino`, R8-4-04), os pedidos no aparelho são os
    // DELA, e a fila guardada agora é ela (o carimbo `t`): a linha dizia "Sem
    // sinal agora. Vai preparar sozinho…" sobre uma fila preparada (R9-4-03).
    const esperando = filaReal().length ? null : filaGuardadaEsperandoOTreino();
    const n = esperando ? esperando.n : filaReal().length;
    const gravadaEm = esperando ? esperando.t : offlineFilaGravadaEm;
    // A última preparação completa cobriu a fila que está guardada AGORA? Uma
    // fila gravada depois dela com pedido NOVO — pela busca, ou pela varredura
    // que ficou pela metade ou nem começou — tem pedido sem mapa e sem foto no
    // aparelho (ver `offlineFilaPreparada`); a MESMA fila regravada mantém o
    // carimbo (ver `offlineGravarFila`). Registro de versão anterior: não coberta.
    const cobreAFila = offlineFilaPreparada !== null && offlineFilaPreparada === gravadaEm;
    // Preparado AGORA: a última varredura completa é da janela atual.
    const preparado = offlineJanelaServida !== null && !offlinePrecisaVarrer() && cobreAFila;
    // SEM rede, quem decide é o que a última preparação COMPLETA guardou, e não
    // a janela de agora: o mapa não vence, e a foto vale 60 min do download —
    // baixada na janela J, até o fim da J+2. Pela janela de agora, 20 min depois
    // de tudo pronto a linha já dizia "o mapa e as fotos chegam quando houver
    // rede" com os dois no aparelho (auditoria de 2026-09-30, R5-4-6). E o
    // resultado da ÚLTIMA TENTATIVA não entra: a renovação da mesma fila cortada
    // no meio fica "parcial", e o que a preparação completa de antes guardou
    // segue no aparelho — quem diz se ela vale pra esta fila é a cobertura
    // (auditoria de 2026-10-01, R6-4-2).
    const completa = offlineJanelaServida !== null && cobreAFila;
    const fotosValem = completa && Math.floor(Date.now() / OFFLINE_CICLO_MS) - offlineJanelaServida <= 2;
    if (semRede && fotosValem && n) {
        // Sem sinal e com tudo no aparelho: dizer que "o mapa e as fotos chegam
        // quando houver rede" era mentir sobre o que já está guardado.
        el.innerHTML = `<span class="text-emerald-700 dark:text-emerald-400 font-semibold">${escapeHtml(
            t(n === 1 ? 'prefs.offline.prontoA' : 'prefs.offline.prontoAPlural', { n }))}</span> `
            + escapeHtml(t('prefs.offline.prontoSemRedeB'));
        return;
    }
    if (semRede) {
        // Depois disso o MAPA segue no aparelho, e só a foto pode precisar de sinal.
        el.innerHTML = n
            ? `<span class="text-amber-800 dark:text-amber-300 font-semibold">${escapeHtml(
                t(n === 1 ? 'prefs.offline.esperaA' : 'prefs.offline.esperaAPlural', { n }))}</span> `
              + escapeHtml(t(completa ? 'prefs.offline.mapaGuardadoB' : 'prefs.offline.esperaB'))
            : `<span class="text-amber-800 dark:text-amber-300 font-semibold">${escapeHtml(
                t('prefs.offline.vazioA'))}</span> ` + escapeHtml(t('prefs.offline.vazioB'));
        return;
    }
    if (offlineVarrendo && total) {
        el.innerHTML = `<span class="text-cyan-800 dark:text-cyan-300">${escapeHtml(
            t('prefs.offline.enchendo', { feitos, total }))}</span>`;
        return;
    }
    if (offlineUltimoResultado === 'parcial') {
        // Nem "Pronto" (seria mentira) nem "Preparando…" (já acabou). O próximo
        // gatilho retoma sozinho — a janela servida não avançou.
        el.innerHTML = `<span class="text-amber-800 dark:text-amber-300 font-semibold">${escapeHtml(
            t('prefs.offline.parcialA'))}</span> ` + escapeHtml(t('prefs.offline.parcialB'));
        return;
    }
    // Nada varrido ainda nesta janela: "Pronto" aqui era a linha caindo no
    // último ramo por exclusão — e a pessoa saía de casa achando que estava
    // tudo no aparelho.
    if (!preparado) {
        el.innerHTML = `<span class="text-amber-800 dark:text-amber-300 font-semibold">${escapeHtml(
            t('prefs.offline.pendenteA'))}</span> ` + escapeHtml(t('prefs.offline.pendenteB'));
        return;
    }
    el.innerHTML = `<span class="text-emerald-700 dark:text-emerald-400 font-semibold">${escapeHtml(
        t(n === 1 ? 'prefs.offline.prontoA' : 'prefs.offline.prontoAPlural', { n }))}</span> `
        + escapeHtml(t('prefs.offline.prontoB'));
}

// ── OS GATILHOS: quatro, e NENHUM deles é polling ─────────────────────────
// O free tier é restrição de projeto, então nada aqui "atualiza a cada N
// minutos" por conta própria. Todos pegam carona no que já ia acontecer:
//   1. a prova de rede (resposta que CHEGA — o mesmo gancho da fila de saída)
//   2. o evento `online` do navegador
//   3. a abertura do app
//   4. o card que troca (o gesto de quem está trabalhando)
// O relógio de 20 min NÃO é um timer: é a comparação de `offlineJanelaServida`
// com a janela atual, feita quando um dos quatro acima acontece de qualquer
// jeito. Sem rede, nenhum deles dispara nada.
function offlinePrecisaVarrer() {
    if (!offlineLigado()) return false;
    if (offlineJanelaServida === null) return true;          // nunca encheu
    // A preparação que ficou PELA METADE na MESMA janela também volta — é a da
    // REPOSIÇÃO (os pedidos novos que a busca trouxe), e o sinal caindo no meio
    // dela é o caso comum de quem sai de casa. Só a janela virando (20 min) a
    // retomava: a linha dizia "Continua sozinho quando houver rede", a rede
    // voltava e nada acontecia, e o que chegou ficava sem foto e sem mapa no
    // próximo buraco de sinal (auditoria de 2026-09-29, O3). Com a varredura no
    // ar, quem decide é o fim dela — o próximo gatilho depois dele retoma.
    if (offlineUltimoResultado === 'parcial' && !offlineVarrendo) return true;
    // A fila guardada que a última preparação completa NÃO cobriu também volta
    // (ver `offlineFilaPreparada`): a busca a gravou com a pessoa parada, ou
    // DURANTE a varredura anterior, e a preparação dela não começou. Ela esperava
    // a janela virar — até 20 min de cards novos sem mapa nem foto pra quem saísse
    // do sinal, com a linha dizendo "Ainda não preparado" e nada preparando
    // (auditoria de 2026-09-30, a sobra do R5-4-6). A retomada baixa SÓ o que
    // falta nesta página (`offlineFeitosNaJanela`); a página reaberta confere a
    // fila inteira, como toda abertura com rede já faz. Uma vez por fila gravada:
    // a varredura que já trabalhou sobre ela (`offlineFilaVarrida`) e não
    // conseguiu gravar a cobertura — a gravação da fila falhou — não volta a cada
    // gatilho.
    if (!offlineVarrendo && offlineFilaGravadaEm !== null && offlineFilaGravadaEm !== offlineFilaPreparada
        && offlineFilaGravadaEm !== offlineFilaVarrida) return true;
    return Math.floor(Date.now() / OFFLINE_CICLO_MS) !== offlineJanelaServida;
}

function offlineTalvezVarrer() {
    if (!offlinePrecisaVarrer()) return;
    offlineVarrer();
}

function offlineMarcarGesto() { offlineUltimoGesto = Date.now(); }

// O interruptor "Disponível offline" (aba Preferências). Aplica NA HORA, como
// toda preferência.
function offlineAoMudarInterruptor(ligado) {
    AppState.preferences.offlineDisponivel = ligado;
    savePreferences();
    // Zera ANTES dos dois ramos: alternar o toggle apaga o resultado da
    // varredura anterior, senão religar mostraria o "parcial" de antes.
    offlineUltimoResultado = null;
    if (ligado) {
        offlineMarcarGesto();       // marcar JÁ é o gesto: não dorme
        // A FILA vai pro aparelho agora, com ou sem sinal: guardar o texto não
        // precisa de rede — ele já está aqui. Ligado JÁ sem rede, a varredura
        // sai antes de gravar (ela só baixa com rede), e a linha dizia "3
        // pedidos guardados" com NADA guardado: fechado e reaberto sem rede, a
        // tela era a de "sem conexão" (auditoria de 2026-09-29, O9). Com rede a
        // varredura grava de novo no começo dela — a mesma fila, e é barato.
        offlineGravarFila();
        offlineVarrer();            // enche agora, com o custo na tela
    } else {
        offlineEsquecer();          // desligou: some o que foi guardado
    }
    atualizarLinhaDoOffline(0, 0);
}

// Abre o app sem rede: em vez da tela de falha, a fila que ficou guardada.
// Todos os pedidos entram — inclusive os de FOTO, cuja foto a varredura
// guardou no cache do navegador. O que não abrir de lá trava ✕/✓ no próprio
// card (`marcarCardSemFoto`, pelo `onerror`), em vez de sair do baralho por
// suposição. (Este comentário dizia que os de foto "saíam do baralho"; o
// código nunca fez isso.)
// A fila guardada é da conta de AGORA? Da MESMA sessão, é — o token é o mesmo,
// então a conta também (inclusive a gravada antes de o perfil chegar, sem
// conta). De outra sessão, só se a conta que a gravou for a conhecida agora.
// Como a fila de saída (O3).
//
// A sessão de agora é a DESTA aba, a da memória (`marcaDestaAba`, R13-4-04):
// pelo `getSession`, a busca que falhava depois da queda (a memória vazia) lia a
// sessão que outra aba guardou no aparelho — e já a ADOTAVA —, e a fila guardada
// abria na aba deslogada, por baixo da tela de entrada (MEDIDO no navegador, p7
// da rodada 13 com a busca falhando).
function filaGuardadaDestaConta(g) {
    if (!g) return false;
    const s = marcaDestaAba();
    if (g.s && s && g.s === s) return true;
    const agora = contaAgora();
    return !!(g.conta && agora && String(g.conta) === agora);
}

// `aposFalha`: a BUSCA acabou de falhar por rede ou pelo servidor (ver
// `ultimaBuscaFalhouPorRede`) — aí a fila guardada entra mesmo com `onLine`
// verdadeiro, que no "lie-fi" mente. `epoca`: a da fila da busca que falhou; se
// ela mudou enquanto a base era lida (↻, filtro trocado), a fila é outra e a
// guardada não entra nela.
async function offlineTentarAbrirSemRede(aposFalha = false, epoca = null) {
    if (!offlineLigado() || (navigator.onLine !== false && !aposFalha)) return false;
    // Só com SESSÃO (R13-4-04). A busca que falhava depois da queda chegava aqui
    // pelo `startFetching` com a aba já na tela de entrada, e a fila guardada
    // entrava por baixo dela — cards de uma sessão que esta aba não tem (MEDIDO
    // no navegador, p7 da rodada 13: `offline.abriu` com 6 cards e a tela de
    // entrada por cima). Sem sessão nada decide (`acoesTravadas`); quem volta a
    // buscar é a entrada. Conferido de novo depois de ler a base, lá embaixo.
    if (!AppState.authenticated) return false;
    // A fila desta abertura é a da tela no COMEÇO da leitura (ver o treino, abaixo).
    const epocaDaLeitura = AppState.fetchEpoch;
    const guardada = await offlineLerFila();
    if (!guardada) return false;
    // A fila de OUTRO lugar (a região, o país ou o FILTRO mudou depois dela) não
    // entra: seria a fila da região velha sob o filtro novo, e a decisão sairia
    // pro servidor errado (ver `filaDeOnde`) — ou a fila do Brasil inteiro sob
    // "só Nova foto" (O8). Fila guardada sem o lugar (versão anterior) também
    // não: não há como saber de onde ela é, e a próxima busca com rede a
    // regrava. A tela é a de sempre sem rede — e a fila guardada FICA: voltar
    // ao filtro dela, ainda sem rede, a encontra (R5-4-2).
    const agora = lugarAgora();
    if (!mesmoLugar(guardada, agora)) {
        // `filtro`: o lugar é o mesmo e só o filtro mudou.
        const soOFiltro = guardada.regiao === agora.regiao && String(guardada.pais) === agora.pais;
        dfato('offline.outroLugar', { regiao: guardada.regiao || null, ...(soOFiltro ? { filtro: true } : {}) });
        return false;
    }
    // E a fila de OUTRA conta também não: a sessão de A caiu, B entrou, o
    // perfil e a busca de B não chegaram (sinal ruim), e a reabertura sem rede
    // mostrava a fila de A a B — com as decisões de B saindo sobre ela
    // (auditoria da costura, 2026-09-26, K6). Sem como saber de quem é (fila de
    // versão anterior, ou a conta de agora desconhecida), também não entra: a
    // próxima busca com rede a regrava.
    if (!filaGuardadaDestaConta(guardada)) {
        dfato('offline.outraConta', { temConta: !!guardada.conta });
        return false;
    }
    // A janela da última varredura COMPLETA, antes de qualquer card nascer: sem
    // ela o card pede a foto crua, que ninguém guardou. Só quando a memória não
    // tem uma — com o app vivo, a de memória é a mais nova (ver a função).
    await offlineRecuperarJanela();
    // A sessão caiu enquanto a base era lida (ver o topo, R13-4-04).
    if (!AppState.authenticated) return false;
    // A fila guardada é uma FOTO: não sabe do que foi decidido depois dela — na
    // sombra (está na fila de saída) nem com rede (pousou depois da foto). Sem
    // este filtro, tudo isso voltava como card (relato de 2026-09-22). Fila
    // guardada por versão anterior não tem `desde`: vale a hora em que foi
    // gravada, que é o mais perto que se sabe.
    // MIGRACAO: fila-guardada-desde
    const desde = Number.isFinite(guardada.desde) ? guardada.desde : guardada.t;
    const filtrada = semOsJaDecididos(guardada.places, desde);
    // Tudo decidido: não há o que mostrar, e a tela certa é a de sempre (a
    // falha de rede), não uma fila vazia que se passaria por "Tudo limpo!".
    if (!filtrada.places.length) {
        dfato('offline.abriu', { n: 0, excluidos: filtrada.excluidos,
                                 idade: Math.round((Date.now() - guardada.t) / 60000) });
        return false;
    }
    // O TREINO abriu enquanto a base era lida (ⓘ → "Praticar" durante a leitura,
    // que no WebKit pode levar segundos): a fila desta abertura ficou guardada
    // nele, e a da tela passou a ser a de EXEMPLOS. A guardada entrava por cima
    // deles — os pedidos REAIS como cards do treino, sob a faixa "nada é enviado
    // ao Waze" —, e o "Sair" devolvia a fila vazia que o treino tinha guardado: a
    // fila do aparelho sumia da tela até o "Tentar de novo" (auditoria de
    // 2026-10-03, R8-4-04, MEDIDO). Não entra por cima dos exemplos: fica anotada
    // no treino, e o `sair()` tenta de novo pelo MESMO caminho
    // (`abrirGuardadaDepoisDoTreino`) — a abertura (a ordem, a cobertura da linha
    // do offline, o que já entrou na fila) segue sendo uma só. Só a fila DESTA
    // leitura: o treino guardou a época dela (`filaGuardada`). Quantos entram e o
    // carimbo dela vão junto: é dela que a linha do offline fala até lá (R9-4-03).
    if (typeof Treino !== 'undefined' && Treino.ativo === true) {
        if (Treino.filaGuardada(epocaDaLeitura)) Treino.anotarFilaGuardada(filtrada.places.length, guardada.t);
        return false;
    }
    // Depois de uma busca que falhou: a fila mudou enquanto a base era lida
    // (↻, filtro trocado), ou outra busca já pôs pedido nela — a guardada não
    // entra por cima.
    if (aposFalha && ((epoca !== null && epoca !== AppState.fetchEpoch) || AppState.queue.length)) return false;
    AppState.queue = filtrada.places;
    filaDeOnde = { regiao: guardada.regiao, pais: String(guardada.pais), busca: guardada.busca };
    // A fila aberta é a GUARDADA: é dela que a linha das Preferências fala (ver
    // `offlineFilaPreparada`), e é contra os pedidos DELA — os gravados, não só os
    // que entraram — que a próxima gravação confere se é a mesma fila.
    offlineFilaGravadaEm = Number.isFinite(guardada.t) ? guardada.t : null;
    offlineFilaGravadaChaves = new Set(guardada.places.map(chaveDoPedido));
    // A fila guardada começa uma fila: o que ela traz já ENTROU, e a busca,
    // quando a rede voltar, relê do topo sem repetir nada disso.
    pedidosQueEntraramNaFila.clear();
    registrarEntradaNaFila(AppState.queue);
    AppState.serverTotal = AppState.queue.length;
    // "Pode haver mais", e não "acabou": a fila guardada é uma foto de antes, e
    // o Waze tem o que chegou depois e o que estava além dela. Sem rede a busca
    // nem tenta (ver `fetchNextPage`) e, se a fila esvaziar, a tela é a de "sem
    // sinal". Com `false` aqui, terminar a fila guardada mostrava "Tudo limpo!"
    // — mesmo com a rede de volta, porque nada mais buscava.
    AppState.hasMore = true;
    AppState.loadError = false;
    updatePendingCount();
    sortQueue();
    showCurrentPlace();
    // `aposFalha`: abriu com o aparelho dizendo que há rede — a busca é que
    // falhou (o "lie-fi", a origem fora do ar).
    dfato('offline.abriu', { n: AppState.queue.length, excluidos: filtrada.excluidos,
                             idade: Math.round((Date.now() - guardada.t) / 60000),
                             ...(navigator.onLine !== false ? { aposFalha: true } : {}) });
    return true;
}

// O `Treino.sair()` com a fila guardada do offline à espera (ver o treino no
// `offlineTentarAbrirSemRede`, R8-4-04): a tentativa que o "Tentar de novo"
// faria, sem a pessoa precisar achar o botão. Sem ela (o sinal voltou, o filtro
// mudou, tudo já decidido), o que o `sair()` faria com a fila real vazia.
async function abrirGuardadaDepoisDoTreino() {
    showLoading(true);
    if (await offlineTentarAbrirSemRede(ultimaBuscaFalhouPorRede).catch(() => false)) return;
    // O treino abriu DE NOVO durante a leitura (e ela anotou outra vez), ou uma
    // fila já entrou na tela: quem decide agora são eles.
    if ((typeof Treino !== 'undefined' && Treino.ativo === true) || AppState.queue.length) return;
    if (AppState.hasMore) startFetching();
    else showNoPlaces();
}

// O card de FOTO sem a foto: diz na PRÓPRIA CAIXA da imagem, e trava ✕ e ✓
// deixando o ↑ vivo. Botão morto com cara de vivo lê como app quebrado, e
// decidir foto sem ver a foto é decidir no escuro.
//
// Chamada SÓ pelo `onerror` da foto em decisão — ou seja, depois de a imagem
// falhar de verdade. "Sem rede" não é "sem foto": a varredura do offline
// guarda a foto no cache do navegador exatamente pra ela abrir sem sinal.
// `test/offline.test.mjs` reprova quem voltar a chamá-la no render.
function marcarCardSemFoto(card, place) {
    if (!card || !place) return false;
    const tipoDeFoto = place.purType === 'NEW_PHOTO' || place.purType === 'FLAGGED_PHOTO';
    // "Sem rede" é também o LIE-FI: o `onLine` diz que há rede, a busca ficou
    // sem resposta e nada respondeu depois (`buscaSemResposta`) — a fila guardada
    // que abriu assim tinha o card de foto com "Sem Imagem" e ✕/✓ VIVOS, ou seja
    // decidir a foto sem vê-la, enquanto no modo avião o mesmo card travava
    // (auditoria de 2026-09-30, R5-4-4). A primeira resposta que chegar devolve
    // a foto (`recuperarCardSemFoto`).
    if (!tipoDeFoto || (navigator.onLine !== false && !buscaSemResposta)) return false;
    const caixa = card.querySelector('.card-photo');
    if (!caixa || caixa.querySelector('.card-sem-foto')) return false;
    for (const f of Array.from(caixa.children)) f.classList.add('hidden');
    const av = document.createElement('div');
    av.className = 'card-sem-foto';
    av.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">'
        + '<path d="M3 3l18 18M10.6 5.2A9 9 0 0 1 21 12M2 12a9 9 0 0 1 4-7.4M8.5 16.5a5 5 0 0 1 7 0"/>'
        + '<circle cx="12" cy="20" r="1"/></svg>'
        + `<strong>${escapeHtml(t('card.semFoto.titulo'))}</strong>`
        + `<span>${escapeHtml(t('card.semFoto.desc'))}</span>`;
    caixa.appendChild(av);
    // Quem tinha o foco no ✕ ou no ✓ — o teclado, que o C10 põe no botão do
    // card novo antes de a foto chegar — vai pro ↑, o único vivo, que é o que o
    // `aplicarFocoDoTeclado` escolhe num card sem a foto. Sem isto o botão focado
    // virava `disabled` e o foco caía no <body> (MEDIDO nos dois motores, com a
    // foto falhando DEPOIS de o foco pousar; auditoria do card, 2026-09-29). O
    // dedo não põe foco nos botões do card, então nada muda pra quem toca.
    const focado = document.activeElement;
    const perdeFoco = !!(focado && card.contains(focado) && focado.matches('.card-btn-reject, .card-btn-read'));
    for (const sel of ['.card-btn-reject', '.card-btn-read']) {
        const b = card.querySelector(sel);
        if (b) { b.disabled = true; b.classList.add('acoes-travadas'); }
    }
    if (perdeFoco) {
        const pular = card.querySelector('.card-btn-skip');
        if (focavelNaTela(pular)) pular.focus({ preventScroll: true });
    }
    return true;
}

// A foto que não veio sem rede VOLTA quando a rede volta — é o que o aviso
// promete ("Ela chega sozinha quando a rede voltar"), e nada a buscava de novo:
// o card ficava travado até a pessoa pular (auditoria de 2026-09-25). Antes de
// redesenhar, a foto é PROVADA numa <img> solta: redesenhar com a rede ainda
// firmando (o `online` chega antes do sinal) daria "Sem Imagem" com ✕ e ✓
// VIVOS — `marcarCardSemFoto` só trava sem rede (ou no lie-fi, até a primeira
// resposta chegar) —, ou seja decidir foto não vista. Com a prova, o redesenho
// já acha a foto no cache HTTP.
//
// A foto que o Waze TIROU DO AR (404) nunca passa na prova: o card aberto sem
// sinal seguia com "A foto precisa de sinal" e ✕/✓ travados com a rede DE
// VOLTA, até a pessoa pular — o mesmo pedido aberto com sinal mostra "Sem
// Imagem" com ✕/✓ vivos (R7-4-06, MEDIDO: o `online` chega, a prova sai e dá
// 404, e o card fica como estava). A falha da prova sozinha não solta o card (o
// `online` chega antes de a rede passar tráfego); a rede PROVADA solta: uma
// resposta NOSSA chegou (`redeProvada`, do `API.aoProvarRede`), ou o servidor
// da FOTO respondeu (`fotoServidorResponde`). Aí a falha é da foto, e o
// redesenho é o card aberto com sinal — o `marcarCardSemFoto` não trava com
// rede. Depois do `online`, nenhuma resposta nossa chega sozinha (o free tier
// não deixa pedir uma), e é o servidor da foto que prova a rede.
//
// A rede provada que chega com a prova NO AR redesenha NA HORA (R8-4-08): ela
// só era anotada, e a prova da <img> não tinha teto — com o 1º pedido à foto
// pendurado (a conexão que não responde logo depois de o sinal voltar), o card
// seguia com "A foto precisa de sinal" e ✕/✓ travados com a rede já provada
// (MEDIDO, r8 da auditoria: 12 s depois da volta, travado; soltando o pedido
// preso, destravou em 86 ms). E a prova ganhou TETO (`FOTO_PROVA_TETO_MS`): ao
// estourar, conta como falha — com a rede provada, redesenha; senão, pergunta ao
// servidor da foto, como no `onerror`.
//
// E a rede que JÁ CHEGA provada, sem prova no ar, também redesenha na hora
// (R9-4-06): é o caminho do lie-fi — o `onLine` segue verdadeiro, e a primeira
// resposta nossa (o `aoProvarRede`) é quem chama aqui. Ela começava uma prova da
// <img> mesmo assim, e com o 1º pedido à foto pendurado o card ficava travado
// até o teto (MEDIDO, n4 da auditoria da rodada 9: 10,1 s; com a mesma rede
// provada chegando com a prova JÁ no ar, 11 ms). Provar a foto serve pra saber se
// a REDE anda — e isso a resposta nossa já disse: o redesenho é o card aberto com
// sinal, que pede a foto ele mesmo.
//
// O redesenho é do MESMO pedido e passa pelo `mantendoFocoNoCard`: o teclado no
// ↑ (o único botão vivo do card sem a foto) ia pro <body> (R8-4-03).
//
// Com um GESTO no card (o dedo nele, a volta pro lugar, a saída), o redesenho
// não arranca o card de debaixo do dedo: ESPERA o fim do gesto
// (`redesenhoDoCardAdiado`, que o `aoFimDoGesto` atende). Quem dizia "há gesto"
// era o `style.transform` do card, e a volta pro lugar o deixa escrito
// (`translate(0, 0) rotate(0deg)`): o card de foto travado que a pessoa tentou
// arrastar — a reação natural a ✕ e ✓ apagados — nunca mais saía do aviso com
// o sinal de volta, e a promessa "a próxima prova de rede tenta de novo" não se
// cumpria no lie-fi, onde não vem outra (auditoria da rodada 10, R10-4-01,
// MEDIDO: 15 s travado no modo avião e no lie-fi, nos dois motores; sem o
// arraste, 105 e 7 ms).
let provandoFotoDe = null;   // { place, redeProvada, comRede }: a prova em voo
let redesenhoDoCardAdiado = null;   // { place, porque }: o redesenho que espera o gesto acabar
function recuperarCardSemFoto({ redeProvada = false } = {}) {
    if (navigator.onLine === false) return;
    const place = AppState.currentPlace;
    const card = cardDaFrente();
    if (!place || !card || !card.querySelector('.card-sem-foto')) return;
    if (provandoFotoDe && provandoFotoDe.place === place) {
        // A prova em voo NÃO segura a rede provada que chega durante ela.
        if (redeProvada) provandoFotoDe.comRede();
        return;
    }
    const f = fotosDoCard(place);
    const u = f.urls[f.inicial];
    if (!u) return;
    if (redeProvada) {
        // Com um gesto no card, o redesenho espera o fim dele (a mesma regra do
        // `redesenhar`).
        const porque = 'foto.redeProvada';
        if (cardSobGesto(card)) { redesenhoDoCardAdiado = { place, porque }; return; }
        redesenhoDoCardAdiado = null;
        dfato(porque);
        mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
        return;
    }
    const prova = { place, redeProvada };
    provandoFotoDe = prova;
    const src = urlDaFoto(u);
    let teto = null;
    // Uma falha só (o `onerror` e o teto não perguntam ao servidor duas vezes), e
    // um redesenho só: o desfecho que chega DEPOIS dele não mexe no card de novo.
    let falhou = false, redesenhou = false;
    const soltar = () => { clearTimeout(teto); if (provandoFotoDe === prova) provandoFotoDe = null; };
    const redesenhar = (porque) => {
        if (redesenhou) return;
        soltar();
        // O card pode ter mudado: aí não se mexe nele. Com um GESTO nele, o
        // redesenho espera o fim do gesto (`aoFimDoGesto`).
        if (AppState.currentPlace !== place) return;
        const agora = cardDaFrente();
        if (!agora || !agora.querySelector('.card-sem-foto')) return;
        redesenhou = true;
        if (cardSobGesto(agora)) { redesenhoDoCardAdiado = { place, porque }; return; }
        redesenhoDoCardAdiado = null;
        dfato(porque);
        mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
    };
    const aoFalhar = () => {
        if (falhou) return;
        falhou = true;
        clearTimeout(teto);
        if (prova.redeProvada) return redesenhar('foto.falhouComRede');
        fotoServidorResponde(src).then((respondeu) => {
            if (respondeu || prova.redeProvada) redesenhar('foto.falhouComRede');
            else soltar();
        });
    };
    prova.comRede = () => { prova.redeProvada = true; redesenhar('foto.redeProvada'); };
    const img = new Image();
    img.onload = () => redesenhar('foto.voltou');
    img.onerror = aoFalhar;
    teto = setTimeout(() => { dfato('foto.provaSemResposta'); aoFalhar(); }, FOTO_PROVA_TETO_MS);
    img.src = src;
}
// O teto da prova da <img> (R8-4-08), o mesmo da sonda do servidor da foto:
// passou dele sem desfecho, a prova conta como FALHA, e quem decide se a rede
// anda é a sonda (ou a rede já provada) — o card não fica preso à prova
// pendurada. Numa rede só LENTA, o servidor da foto responde à sonda e o card é
// redesenhado como o aberto com sinal: a foto aparece quando terminar de chegar.
const FOTO_PROVA_TETO_MS = 10 * 1000;

// O redesenho do card de foto que ESPERAVA o gesto acabar (ver
// `recuperarCardSemFoto`), chamado no fim dele (`aoFimDoGesto`). As mesmas
// conferências do redesenho na hora: o card ainda é o do pedido e ainda está
// sem a foto, e não começou OUTRO gesto nele (aí segue esperando). Sem rede
// agora, não redesenha: a foto falharia de novo, e o `online` que vier chama a
// recuperação desde o começo.
function redesenharCardAdiado() {
    const a = redesenhoDoCardAdiado;
    if (!a) return;
    const card = cardDaFrente();
    if (cardSobGesto(card)) return;
    redesenhoDoCardAdiado = null;
    if (navigator.onLine === false || AppState.currentPlace !== a.place) return;
    if (!card || !card.querySelector('.card-sem-foto')) return;
    dfato(a.porque);
    mantendoFocoNoCard(showCurrentPlace, { mesmoBotao: true });
}

// O servidor da foto RESPONDE? O CDN de foto não manda CORS, então o pedido vai
// sem (`no-cors`): a resposta é opaca, mas o `fetch` só REJEITA quando a rede
// falha — qualquer resposta HTTP, o 404 da foto tirada do ar inclusive,
// resolve. `no-store`: pergunta à rede e não guarda nada (a foto do card é a do
// cache da `<img>`, que é outra entrada). Com teto: rede pendurada não anda. O
// host da foto já está no `connect-src` das três cópias da CSP.
const FOTO_SONDA_TETO_MS = 10 * 1000;
async function fotoServidorResponde(src) {
    const ctrl = new AbortController();
    const teto = setTimeout(() => ctrl.abort(), FOTO_SONDA_TETO_MS);
    try {
        await fetch(src, { mode: 'no-cors', cache: 'no-store', credentials: 'omit', signal: ctrl.signal });
        return true;
    } catch (e) { return false; }
    finally { clearTimeout(teto); }
}

// Um pedido cuja decisão o Waze RECUSOU de vez (`unknown`, ou a fila de saída
// cheia) segue PENDENTE lá, e tem que voltar a ser card. Antes o placar voltava
// e o pedido SUMIA: ele já tinha passado pela fila (`pedidosQueEntraramNaFila`),
// então nenhuma busca o trazia, e o fim da fila dizia "Tudo limpo!", com a
// conquista, sobre um pedido pendente (auditoria da fila, 2026-09-26).
//
// Na fila do GESTO (`epocaFila` igual à de agora) ele volta como o PRÓXIMO
// card — nunca no lugar do que está na tela, que seria trocar o card debaixo do
// dedo —, e o "Restam" sobe junto. Numa fila refeita desde o gesto (↻, filtro)
// ele nem entrou (estava em andamento), e sem o pedido inteiro na mão
// (a fila de saída guarda só os ids) não há card pra montar: nos dois casos
// quem o traz é a BUSCA, que diz o que o Waze tem agora e sob os filtros de
// agora. Ele sai do "já passou pela fila", a fila volta a dizer "pode haver
// mais", e o "Restam" sobe quando ele chegar — somar agora o contaria duas vezes.
//
// Com o TREINO aberto a fila do gesto não foi refeita: está GUARDADA nele, e
// volta no `sair()` com a época dela. O recusado espera lá e volta como o
// próximo card quando ela voltar (`Treino.guardarDevolucao`) — tratado como
// fila refeita, ele sumia até uma busca o trazer, com o "Restam" um abaixo
// (R7-7-04, auditoria de 2026-10-02: o ✕ que o "Praticar" despacha da janela do
// Desfazer, recusado com o treino aberto).
//
// Aceita um pedido ou uma LISTA (o "Rejeitar os N" que volta junto): um por um,
// cada `splice` na posição 1 inverteria a ordem dos que voltam — sem erro
// visível, só a fila discordando do WME na hora de conferir.
function devolverPedidoRecusado(place, epocaFila) {
    if (typeof Treino !== 'undefined' && Treino.ativo === true && Treino.guardarDevolucao(place, epocaFila)) return;
    const naFila = new Set(AppState.queue.map(chaveDoPedido));
    const voltam = [];
    for (const p of (Array.isArray(place) ? place : [place])) {
        const k = chaveDoPedido(p);
        if (!k || naFila.has(k)) continue;
        naFila.add(k);
        voltam.push(p);
    }
    if (!voltam.length) return;
    if (epocaFila === AppState.fetchEpoch) {
        AppState.queue.splice(AppState.currentPlace ? 1 : 0, 0, ...voltam);
        AppState.serverTotal += voltam.length;
        // Com o foco num autor ("Primeiro os de X"), o recusado de OUTRO autor
        // entrava no MEIO da série: depois do card da tela vinha ele, a barra
        // sumia e o resto da série perdia a prioridade (R5-2-09). O foco é uma
        // ordem que a pessoa pediu: a série segue na frente, e o devolvido vem
        // logo depois dela — o próximo assim que a série acaba.
        if (AppState.autorEmFoco !== null && AppState.autorEmFoco !== undefined
            && AppState.currentPlace && AppState.currentPlace.creatorId === AppState.autorEmFoco) manterFocoNaFrente();
    } else {
        for (const p of voltam) pedidosQueEntraramNaFila.delete(chaveDoPedido(p));
        AppState.hasMore = true;
    }
    updatePendingCount();
    // Com card na tela, o de FUNDO passa a anunciar o que voltou. Sem card (o
    // "Tudo limpo!" do último gesto), o que voltou é o card — ou a busca o traz.
    if (AppState.currentPlace) aoMudarAFilaPorBaixo();
    else if (AppState.queue.length) showCurrentPlace();
    else if (AppState.hasMore) startFetching();
}

// `gesto`: o MOMENTO da decisão (`carimboDoGesto`) — o dia e o lugar em que ela
// entra no Histórico, e a hora, o dia e o idioma com que conta nas conquistas,
// os mesmos do pouso da fila de saída. Lidos AQUI eles seriam os da resposta:
// "Aplicar" outro país dentro da janela do Desfazer creditava a decisão ao país
// novo (R6-7-4). Sem ele (quem chama sem carimbo), vale agora.
function handleActionResult(actionType, place, result, regiao, epocaFila, gesto) {
    dlog('acao.fim', { tipo: actionType, ok: !!(result && result.success),
                       cat: (result && result.errorCategory) || null,
                       key: (result && result.errorKey) || null });
    if (!result) return;
    // A DESCARGA já pôs esta decisão na fila de saída antes de o envio sair (ver
    // `descarregar` no `scheduleAction`) — e, desde o O2, toda decisão que sai
    // (`anotarAntesDoEnvio`): a resposta que chegou com a página viva decide o
    // destino do item — pousou, ele sai da fila; rede ou sessão, ele fica lá sem
    // o gesto contar de novo.
    const anotado = anotadoAntesDoEnvio.delete(place);
    const jaNaSaida = descargaNaFila.delete(place) || anotado;
    if (result.success) {
        if (jaNaSaida && tirarDaFilaDeSaida(actionType, place) === false) return pousouPorOutraAba(place, actionType);
        registrarPouso(place);
        recordHistory(actionType, 1, gesto && gesto.dia, gesto && gesto.onde);
        // Só REJEIÇÃO conta reincidência. Marcar como lido não é juízo
        // sobre o pedido — é "eu vi" —, e contá-lo transformaria quem
        // manda muita coisa BOA em reincidente.
        if (actionType === 'reject') registrarRejeicaoDeAutor(place);
        avisarConsequencia(actionType);
        registrarAcaoConfirmada(actionType, place, gesto);
        return;
    }

    const cat = result.errorCategory || 'unknown';

    if (cat === 'already_processed' || cat === 'not_found') {
        if (jaNaSaida && tirarDaFilaDeSaida(actionType, place) === false) return pousouPorOutraAba(place, actionType);
        registrarPouso(place);
        // Quem resolveu foi a aprovação DESTA pessoa, cuja resposta se perdeu
        // (ver a função): nem "outro editor", nem a decisão do card contada.
        if (aprovacaoDelaJaPousou(place)) { desfechoDaAprovacaoDela(actionType, place); return; }
        recordHistory(actionType, 1, gesto && gesto.dia, gesto && gesto.onde);
        // Conta como tratada pelos mesmos motivos que ela conta no placar: o
        // objetivo de quem agiu foi cumprido, tenha sido por você ou não.
        registrarAcaoConfirmada(actionType, place, gesto);
        showToast(t('toast.alreadyProcessed'), 'info');
        return;
    }

    // 401 NÃO prova que a sessão morreu (WAF, blip do KV — ver o
    // `handleUnauthorized`), e mesmo quando morreu, o que a pessoa FEZ não pode
    // evaporar: o card já saiu da tela e o placar já contou. Antes a ação
    // sumia aqui, sem reverter nem reenviar — e o pedido voltava depois do
    // relogin pra ser tratado (e contado) de novo. Vai pra fila de saída, que
    // sai quando a sessão se confirma viva ou depois de entrar de novo; ela para
    // e SEGURA o item enquanto a sessão estiver morta.
    if (cat === 'unauthorized' && jaNaSaida) {
        // Já está na fila: só anota QUANDO levou o 401 e confere a sessão.
        marcarNaSaida({ tipo: actionType, venueID: place.venueID, updateRequestID: place.updateRequestID },
                      { u401: Date.now() });
        soltarMarcaDosItens(actionType, [place]);
        if (anotado) anotarSeAbriuASaida(actionType);
        handleUnauthorized();
        return;
    }
    if (cat === 'unauthorized') {
        // `u401`: QUANDO este pedido levou o 401. Se a sonda confirmar a sessão
        // viva e ele levar outro, é a escrita dele que o Waze recusa, não a
        // sessão (ver `sessaoVivaDepoisDe` no esvaziamento).
        const naFila = enfileirarSaida(actionType, place, regiao, { ...gesto, u401: Date.now() });
        if (naFila === 'repetida' || !naFila) {
            const k = actionType === 'read' ? 'read' : 'rejected';
            AppState.stats[k] = Math.max(0, AppState.stats[k] - 1);
            updateStats();
            saveStats();
            // Fila de saída cheia: a decisão não coube em lugar nenhum, e o
            // pedido segue pendente no Waze — volta a ser card.
            if (!naFila) devolverPedidoRecusado(place, epocaFila);
        }
        handleUnauthorized();
        return;
    }

    // REDE, não recusa: a ação vai pra fila de saída em vez de sumir. O placar
    // NÃO reverte, porque o trabalho foi feito — só não saiu ainda.
    //
    // Sem toast por ação: 150 pedidos numa sombra de conectividade dariam 150
    // interrupções. Quem presta contas é o indicador ("N esperando envio"), que
    // some sozinho quando a fila esvazia.
    // Já está na fila (a descarga, ou a anotação de antes do envio): o placar
    // fica, e ela sai quando a rede vier.
    if (cat === 'transient' && jaNaSaida) {
        soltarMarcaDosItens(actionType, [place]);
        if (anotado) anotarSeAbriuASaida(actionType);
        return;
    }
    if (cat === 'transient') {
        const naFila = enfileirarSaida(actionType, place, regiao, gesto);
        // A decisão deste pedido JÁ estava esperando: a primeira vale, e este
        // gesto não pode contar de novo no placar. O `serverTotal` fica: o card
        // repetido também tinha sido contado nele, então o desconto do gesto
        // acertou a conta.
        if (naFila === 'repetida') {
            const k = actionType === 'read' ? 'read' : 'rejected';
            AppState.stats[k] = Math.max(0, AppState.stats[k] - 1);
            updateStats();
            saveStats();
            return;
        }
        if (naFila) return;
    }

    // Recusa de verdade: se a descarga tinha posto a decisão na fila, ela sai —
    // repetir não muda a recusa, e o placar desce aqui embaixo.
    if (jaNaSaida) tirarDaFilaDeSaida(actionType, place);
    const statKey = actionType === 'read' ? 'read' : 'rejected';
    AppState.stats[statKey] = Math.max(0, AppState.stats[statKey] - 1);
    updateStats();
    saveStats();
    // O pedido segue pendente no Waze: volta a ser card, e o "Restam" com ele.
    devolverPedidoRecusado(place, epocaFila);
    const verb = actionType === 'read' ? t('action.verb.read') : t('action.verb.reject');
    showToast(msgDoServidor(result, t('toast.actionError', { verb })), 'error');
}


// ── Modo treino: errar sem consequência ───────────────────────────────────
// Duas das três ações ESCREVEM no Waze em nome da pessoa, e a rejeição não tem
// volta depois dos 3s. Num app assim, poder errar de mentira vale mais que
// qualquer texto explicativo — e é a única forma de "pegar na mão" que não cobra
// nada de quem já sabe, porque só entra quem pede.
//
// O owner apontou o que decide o desenho: "os testadores atuais não enxergam
// problemas de UX/UI pois já estão acostumados, só os novos que ficam
// perguntando". Ajuda que interrompe todo mundo pra atender o novato cobra o
// preço da fila inteira — daí sob demanda, e não automático.
//
// A TRAVA É ESTRUTURAL, não uma promessa: o guard está no TOPO de
// handleReject/handleMarkAsRead/handleSkip, antes de mexer em stat, em fila ou
// em `scheduleAction`. Não existe caminho em que um card de treino chegue ao
// `API.rejectPlace`. O smoke mede isso pela REDE, não lendo o código.
// Fecha as camadas presas ao pedido atual. Usada nas duas pontas da troca de
// modo (entrar/sair do treino): o que está aberto pertence ao pedido do outro
// lado, e reaproveitar a camada exigiria manter cada controle dela coerente com
// o modo novo — uma regra por controle, todas dependentes de ordem.
function fecharCamadasDeFoto() {
    if (typeof Lightbox !== 'undefined' && Lightbox.isOpen()) Lightbox.close();
    if (typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()) MapaLightbox.close();
}

// O treino pedido por um DIÁLOGO — o "Praticar" da Ajuda, o "Quero treinar
// antes" do "Como funciona" — que o `Treino.entrar` vai recusar. Sem sessão (a
// renovação silenciosa pela extensão), o diálogo fechava e nada acontecia,
// calado (R8-7-09, auditoria de 2026-10-03). Com o "Marcar todos" ou a
// aprovação de uma foto no ar, ele fechava ANTES de o `entrar` recusar, e o
// aviso mandava "toque de novo" num botão que tinha saído da tela (R9-7-07,
// MEDIDO no navegador; auditoria de 2026-10-06). A conferência vem ANTES de
// fechar e é a do `entrar` (`Treino.motivoDeRecusa`): diz o que esperar, e o
// diálogo FICA — tocar de novo depois vale. Devolve se recusou.
function recusarTreino() {
    const motivo = Treino.motivoDeRecusa();
    if (!motivo) return false;
    showToast(t(motivo), 'info');
    return true;
}

const Treino = {
    ativo: false,
    _salvo: null,
    passo: 0,
    // Quantas vezes o treino ABRIU nesta página. A busca guarda o número de
    // quando saiu, e a que estava no ar quando ele abriu segue DESCARTADA mesmo
    // pousando depois do `sair()` (ver `fetchNextPage`): o `sair()` devolve a
    // época da fila real, e só pela época ela valeria de novo.
    entradas: 0,
    // O placar do treino é DELE. Trocar o `AppState.stats` pelo do treino (como
    // era) fazia a resposta de uma ação REAL que pousasse durante o treino
    // reverter e GRAVAR o número do treino no lugar do real (`saveStats`), e o
    // "Restam" real some igual. Aqui o real fica intocado e só a TELA mostra
    // estes (`updateStats`/`updatePendingCount`).
    stats: { read: 0, rejected: 0, skipped: 0 },
    restam: 0,

    // O `updateRequestID` que substitui o real. As duas escritas do card
    // (`validar-place` e `marcar-lido`) precisam de venueID E updateRequestID,
    // então um pedido de treino não endereça pedido nenhum: se algum dia
    // vazasse, o Waze responderia 702 "not found on venue" — que o app já trata
    // como "já tratado por outro editor". É a segunda camada; a primeira é o
    // guard no topo dos handlers.
    //
    // O `venueID` fica REAL de propósito: é ele que o ↗ usa pra abrir o lugar
    // certo no WME, e um treino que leva a um editor vazio ensinaria errado.
    // Quem protege as escritas que usam só o venueID (foto) é o guard delas.
    UR_INERTE: 'treino-inerte',

    // Clona fundo: o objeto real continua intocado na fila salva, e nada do que
    // acontecer no treino pode alcançá-lo por referência.
    neutralizar(p) {
        const c = JSON.parse(JSON.stringify(p));
        c.updateRequestID = this.UR_INERTE;
        c._treino = true;
        // O id de verdade, SÓ pra LER: achar a foto em decisão (`fotosDoCard`): o
        // treino escolhe os cards por variedade justamente pra ensinar o card de
        // foto, e sem ele ensinava na foto errada — a antiga, sem ✨ nem a borda
        // âmbar (R6-7-6, auditoria de 2026-10-01; em 13 de 76 pedidos de foto da
        // fila do owner a proposta não é a 1ª). Escrita nenhuma o lê: as de foto
        // têm o guard do treino, e as do card a trava no topo dos handlers. A
        // outra leitura é a frase do ↑ (`pularGuardaria`: o app já estrelou o
        // pedido de verdade?), que só lê o anel das estrelas.
        c._urFoto = p.updateRequestID;
        return c;
    },

    // Quantos pedidos reais o treino usa. 30 é o tamanho de UMA PÁGINA do WME
    // (ele pagina a lista em blocos de 30), então é a unidade mental que o
    // editor já tem — pedido do owner.
    MAX_REAIS: 30,
    // Piso: abaixo disto o treino completa com sintéticos. Fila vazia não pode
    // deixar ninguém sem treino, e é justamente no primeiro minuto — logo depois
    // do "Como funciona" — que a fila tem menos chance de já ter carregado.
    MIN_CARDS: 3,

    // O que faz um card ENSINAR algo que o anterior não ensinou. `updateTypeKey`
    // é o rótulo do card (separa UPDATE com e sem diff), e ter foto muda a tela
    // inteira: é o carrossel, o lightbox, a lixeira e o aprovar.
    chaveDeVariedade(p) {
        return (p.updateTypeKey || '—') + '|' + ((p.imageUrls || []).length ? 'foto' : 'sem');
    },

    // Reais em ordem de VARIEDADE, não a ordem da fila — e a diferença é enorme,
    // não cosmética. MEDIDO na fila real do owner (170 pedidos, 10 tipos
    // distintos): os 3 PRIMEIROS da fila são todos do MESMO tipo, então o treino
    // que pegava `slice(0, 3)` mostrava UM tipo de pedido e chamava isso de
    // treino. Pegando 30 em ordem, ainda seriam 7 dos 10.
    //
    // Rodízio (um de cada tipo, depois o segundo de cada…) porque a pessoa PODE
    // sair no meio: assim quem parar no 5º card viu 5 tipos diferentes, e não 5
    // vezes o mesmo. Com 10 grupos, os 10 primeiros cobrem os 10 tipos.
    porVariedade(fila) {
        const grupos = new Map();
        for (const p of fila) {
            const k = this.chaveDeVariedade(p);
            if (!grupos.has(k)) grupos.set(k, []);
            grupos.get(k).push(p);
        }
        const baldes = [...grupos.values()];
        const out = [];
        for (let i = 0; baldes.some((b) => i < b.length); i++) {
            for (const b of baldes) if (i < b.length) out.push(b[i]);
        }
        return out;
    },

    // Reais quando existem, sintéticos só como piso. O exemplo inventado ensina
    // o gesto; o julgamento — foto borrada, nome ruim, endereço errado — só vem
    // no pedido de verdade, e é ele que o treino precisa treinar.
    cards() {
        const fila = (this._salvo && this._salvo.queue) ? this._salvo.queue : [];
        const reais = this.porVariedade(fila).slice(0, this.MAX_REAIS).map((p) => this.neutralizar(p));
        if (reais.length >= this.MIN_CARDS) return reais;
        return [...reais, ...this.sinteticos()].slice(0, this.MIN_CARDS);
    },

    // Exemplos sintéticos: sem foto de propósito (não dependem de rede, e
    // "pedido sem foto" é caso real — 20% da fila medida). Os três cobrem os
    // três desfechos que a pessoa vai encontrar de verdade.
    //
    // São de TREINO (`_treino`), como os clones do `neutralizar`: só os clones
    // levavam a marca, e com a fila real curta (vazia: os três) a conversa
    // oferecia "Mandar o pedido aberto" num exemplo e o mandava ao chat do WME
    // de verdade — "📍 Padaria Exemplo" e um link `venues=treino1` que não abre
    // nada, debaixo da faixa "nada é enviado ao Waze" (R10-7-01, MEDIDO no
    // navegador; auditoria de 2026-10-07). Quem lê a marca é o
    // `cardParaConversa`. Sem lugar de verdade, o card deles também não tem o ↗
    // (`prepararLinkDoWme`, pelo `_exemplo`).
    sinteticos() {
        const base = {
            _treino: true,
            updateRequestID: 'treino', reqSubType: '', isDelete: false,
            creatorRank: 0, source: null,
            flagType: null, flagSubjectType: null, flagEntityID: null, flagComment: '',
            brand: null, brandKnown: null, camposSemMudanca: 0, imageUrls: [],
            mapa: null, isStarred: false, lat: null, lon: null,
            dateAdded: Date.now() - 3600000,
        };
        return [
            { ...base, venueID: 'treino1', _exemplo: 'c1',
              categories: ['RESTAURANT'],
              updateType: 'Novo Local', updateTypeKey: 'VENUE', purType: 'NEW_PLACE',
              reqType: 'VENUE', changes: [] },
            { ...base, venueID: 'treino2', _exemplo: 'c2',
              categories: ['PHARMACY'],
              updateType: 'Atualização', updateTypeKey: 'UPDATE_DETAILS', purType: 'DETAILS_UPDATE',
              reqType: 'REQUEST',
              changes: [{ field: 'phone', label: 'phone', from: '(11) 3333-0000', to: '(11) 4444-1111' }] },
            { ...base, venueID: 'treino3', _exemplo: 'c3',
              categories: ['GAS_STATION'],
              updateType: 'Novo Local', updateTypeKey: 'VENUE', purType: 'NEW_PLACE',
              reqType: 'VENUE', changes: [] },
        ].map((p) => this.traduzirExemplo(p));
    },

    // O texto dos exemplos sai do dicionário pela CHAVE (`_exemplo`), não fica
    // escrito no card: trocar o idioma com o treino aberto deixava os exemplos no
    // idioma de antes, com a faixa e os botões já no novo (R6-7-10, auditoria de
    // 2026-10-01). O `aplicarIdioma` os retraduz (`retraduzirExemplos`).
    traduzirExemplo(p) {
        p.name = t('treino.' + p._exemplo + '.nome');
        p.address = t('treino.' + p._exemplo + '.endereco');
        p.createdBy = t('treino.autor');
        return p;
    },
    retraduzirExemplos() {
        if (!this.ativo) return;
        for (const p of AppState.queue || []) if (p && p._exemplo) this.traduzirExemplo(p);
    },

    // Por que o treino NÃO pode abrir agora — a chave do aviso que diz o que
    // esperar —, ou null. A conferência ÚNICA do `entrar` e dos diálogos que o
    // pedem (`recusarTreino`, antes de fechar): duas listas divergiriam caladas.
    motivoDeRecusa() {
        // Sem sessão: a renovação silenciosa pela extensão, com o card travado
        // por baixo. O aviso é o da guarda do "Rejeitar os N" (`avisoDaTrava`).
        if (!AppState.authenticated) return avisoDaTrava();
        // O lote de lidos no ar termina sobre a fila REAL: trocada pela de
        // treino, os pedidos que ele marcou voltavam no `sair()` como card.
        if (loteDeLidosEmVoo) return 'toast.esperaLote';
        // A aprovação de foto NO AR pousa sobre a fila REAL, como o lote: trocada
        // pela de treino, o pedido aprovado não saía dela (o `tirarAprovadoDaFila`
        // procura na fila de treino) e voltava no `sair()` como card, destravado —
        // MEDIDO (s15): o ✕ seguinte mandava uma rejeição do pedido aprovado
        // (R5-2-04). E a de uma sessão que CAIU, na fila que atravessou a queda: o
        // pouso dela tira o pedido desta fila (ver `aprovacoesDaQueda`). A
        // aprovação ainda na JANELA do Desfazer (`aprovacaoPendente`) conta
        // junto: o despacho do `entrar` a poria no ar.
        if (aprovacaoPendente || aprovacoesNoAr.size || [...aprovacoesDaQueda.values()].includes(AppState.fetchEpoch)) {
            return 'toast.esperaAprovacao';
        }
        return null;
    },

    entrar() {
        if (this.ativo) return;
        // Deslogado não há tela de card: o treino aberto pela Ajuda na tela de
        // entrada ficava ATIVO e invisível, e o login seguinte rodava a fila
        // real em modo treino — sem enviar nada — até a pessoa sair dele e
        // cair num "Tudo limpo!" falso.
        if (!AppState.authenticated) return;
        // O lote de lidos e a aprovação de foto no ar (`motivoDeRecusa`, a MESMA
        // conferência que os diálogos fazem antes de fechar). Ela vem ANTES de
        // despachar qualquer coisa: o treino que ia ser recusado mandava antes o
        // ✕ da janela do Desfazer (o banner sumia, e com ele a chance de
        // desfazer) e então não abria — o efeito sem a ação pedida (MEDIDO, s35:
        // o ✕ saiu em ~470 ms e o treino ficou fechado; auditoria de 2026-10-02,
        // R6-2-07).
        const motivo = this.motivoDeRecusa();
        if (motivo) { showToast(t(motivo), 'info'); return; }
        // Uma janela de Desfazer pendente é de um pedido REAL: despacha antes de
        // trocar a fila debaixo dela, senão ela executaria sobre outro estado.
        // A do card E as do lightbox (L25: só o banner saía, e a janela delas
        // seguia correndo, sem ele, por baixo do treino).
        if (AppState.pendingAction) { AppState.pendingAction.execute(); AppState.pendingAction = null; }
        enviarPendenciasDoLightbox();
        removeUndoBanner();
        // A busca que estiver em voo é DESCARTADA (a época muda): sem isto os
        // pedidos reais pousavam na fila de TREINO, crus e registrados como "já
        // passaram pela fila", e sumiam no `sair()`. Quem busca de novo é o
        // `sair()`. E o `fetching` NÃO é salvo nem restaurado: restaurar
        // `fetching = true` sem a promessa (que já tinha terminado) fazia o
        // `startFetching` do `sair()` girar em microtarefa pra sempre — a aba
        // congelava (gotcha #19).
        //
        // A época da fila REAL fica GUARDADA com ela e volta no `sair()`. O que
        // estava no ar sobre essa fila — o ✕ que o "Praticar" acabou de despachar
        // logo acima, a recusa automática no meio do laço — pousa na fila do
        // GESTO, e com a época do treino no lugar o pouso a dava por refeita
        // (MEDIDO no navegador, auditoria de 2026-10-02): o ✕ recusado de vez com
        // o treino aberto não voltava como o próximo card (R7-7-04), e a recusa
        // automática terminando no treino não descontava o "Restam" — "Tudo
        // limpo!" com "Restam 3" (R7-2-03). Com o treino aberto, quem pousa acha
        // a fila guardada (`filaGuardada`, `guardarDevolucao`). E a busca no ar
        // segue descartada depois do `sair()`, pelo `entradas` (ver o topo).
        const epocaDaFilaReal = AppState.fetchEpoch;
        AppState.fetchEpoch++;
        this.entradas++;
        // O FOCO num autor ("Primeiro os de…") é ordem da fila REAL: fica guardado
        // com ela e sai da tela, senão a barra dizia "2 de 4" sobre a ordem de
        // variedade do treino e se apagava no 1º card de outro autor — e a fila
        // real voltava com a série na frente e sem a barra, sem como voltar à
        // ordem normal. O foco escolhido NO treino também não atravessa: o
        // `encerrar` devolve o de antes (R6-7-7, auditoria de 2026-10-01).
        // `devolver`: o que o Waze recusou de vez com o treino aberto, e
        // `perfilChegou`: o perfil que chegou nele — os dois esperam a fila real
        // voltar (ver o `sair()`). Como a recusa automática pedida nele
        // (`recusaPedida`), a fila guardada do offline que a abertura sem rede
        // leu nele (`abrirGuardada`, e quantos e de quando: `filaGuardadaLida`) e
        // a fila que o perfil mandou refazer nele (`refazerFila`, com o aviso do
        // país: `avisoDoPais`).
        this._salvo = { queue: AppState.queue, currentPlace: AppState.currentPlace, autorEmFoco: AppState.autorEmFoco,
            epoca: epocaDaFilaReal, epocaDoTreino: AppState.fetchEpoch, devolver: [], perfilChegou: false, ordemMudou: false,
            recusaPedida: false, abrirGuardada: false, filaGuardadaLida: null, refazerFila: false, avisoDoPais: null };
        AppState.autorEmFoco = null;
        this.ativo = true;
        this.passo = 0;
        // Quem entra no treino já foi aprender: o "Como funciona" por cima dos
        // cards de treino abria DOIS modais no mesmo tique que fechava a Ajuda
        // (gotcha #65: o voltar seguinte saía do app).
        if (!AppState.preferences.comoFuncionaVisto) { AppState.preferences.comoFuncionaVisto = true; savePreferences(); }
        this.stats = { read: 0, rejected: 0, skipped: 0 };
        AppState.queue = this.cards();
        // Do TAMANHO da fila de treino, nunca de um número cravado. Estava em 3
        // enquanto o treino montava 4 cards (1 sintético + 3 reais): o "Restam"
        // zerava com um card ainda na tela — o que o app MOSTRA divergindo do
        // que ele ACEITA, que é a regra de ouro de consistência do projeto.
        this.restam = AppState.queue.length;
        AppState.currentPlace = AppState.queue[0];
        document.getElementById('treinoBanner')?.classList.replace('hidden', 'flex');
        document.getElementById('noMoreCards')?.classList.add('hidden');
        showLoading(false);
        updateStats(true);   // troca de contexto: pula, não conta
        updatePendingCount(true);
        showCurrentPlace();
        // Trocar de modo ZERA as camadas: o lightbox (e a renomeação dentro
        // dele) pertencem ao pedido do OUTRO lado, e mantê-los abertos deixaria
        // na tela o confirmar/cancelar de um nome que este modo não vai gravar.
        //
        // Fechar é melhor do que manter cada controle coerente com o modo novo:
        // uma linha em vez de uma regra por controle, e sem depender de ORDEM —
        // que é a forma exata dos dois defeitos que o owner relatou hoje.
        fecharCamadasDeFoto();
    },

    sair() {
        if (!this.ativo) return;
        const s = this._salvo || {};
        this.encerrar();
        AppState.queue = s.queue || [];
        AppState.currentPlace = s.currentPlace || null;
        // A ÉPOCA volta com a fila (ver `entrar`): o que ainda estiver no ar sobre
        // ela pousa nela, como se o treino não tivesse existido. Só se a época é
        // a que o treino pôs: outra (nada a muda sem encerrar o treino hoje) seria
        // uma fila refeita, e voltar a época apagaria isso. E nunca com a fila
        // REFEITA logo abaixo (`refazerFila`): o `resetQueue` dela subiria a época
        // de volta à do TREINO, e quem a guardou tomaria a fila nova pela mesma —
        // era o "sua fila continua aqui" junto do "Mostrando a fila do país…"
        // (R11-7-03). Sem repor, a fila nova ganha uma época que ninguém guardou.
        if (Number.isInteger(s.epoca) && AppState.fetchEpoch === s.epocaDoTreino && !s.refazerFila) AppState.fetchEpoch = s.epoca;
        removeCurrentCardEl();
        // O PERFIL que chegou com o treino aberto (R7-2-04, auditoria de
        // 2026-10-02): a ordem por casa/trabalho e a recusa automática esperavam
        // por ele — o `completarPerfilChegado` só anotou (`anotarPerfil`), porque
        // ordenar ali era ordenar os EXEMPLOS, e a fila real voltava na ordem de
        // data e com os pedidos do autor marcado na tela. Aplicados agora, ANTES
        // de o card ser desenhado: o da frente fica (`semTrocarOCardDaTela`), e o
        // de fundo nasce do próximo de verdade.
        // A ORDEM trocada nos Filtros com o treino aberto (`anotarOrdem`) é gesto
        // da pessoa e vale como no `reordenarFilaNaTela`: encerra o foco no autor
        // e o primeiro da fila é outro (o card da frente TROCA). Ela vence o
        // `semTrocarOCardDaTela` do perfil, que é o app ordenando sozinho.
        // E a RECUSA AUTOMÁTICA pedida com o treino aberto (`anotarRecusa`): a 2ª
        // passada que uma página pediu com a 1ª no ar se perdia (R8-7-03).
        if (s.ordemMudou) {
            limparFocoAutor();
            if (s.perfilChegou || s.recusaPedida) aplicarRecusaAutomatica();
            sortQueue();
        } else if (s.perfilChegou) {
            aplicarRecusaAutomatica();
            sortQueue({ semTrocarOCardDaTela: true });
        } else if (s.recusaPedida) aplicarRecusaAutomatica();
        // A fila que o PERFIL mandou refazer com o treino aberto (`anotarFilaRefeita`,
        // R9-7-04): é ela que vem, e não a guardada, com o aviso do país — e o
        // recusado de vez volta pela busca dela, como numa fila refeita.
        if (s.refazerFila) { updateStats(true); refazerFilaReal(s.avisoDoPais); return; }
        // O que o Waze RECUSOU de vez com o treino aberto (R7-7-04): volta como o
        // PRÓXIMO card, com o "Restam" junto — o que teria acontecido sem o treino
        // (`devolverPedidoRecusado`, que o guardou em `guardarDevolucao`).
        if (s.devolver && s.devolver.length) devolverPedidoRecusado(s.devolver, s.epoca);
        updateStats(true);
        updatePendingCount(true);
        // A busca que o `entrar()` descartou volta aqui: pela fila vazia, ou pelo
        // prefetch de sempre quando sobram poucos.
        if (AppState.queue.length) {
            AppState.currentPlace = AppState.queue[0];
            showCurrentPlace();
            // A ordem escolhida só vale sobre a fila inteira: as páginas que
            // faltam vêm agora, como no `reordenarFilaNaTela`.
            if (s.ordemMudou && ordemPrecisaDaFilaInteira()) buscarORestoDaFila();
            maybePrefetch();
        }
        // A fila guardada do offline que a abertura sem rede leu com o treino
        // aberto (`anotarFilaGuardada`, R8-4-04): entra agora.
        else if (s.abrirGuardada) abrirGuardadaDepoisDoTreino();
        else if (AppState.hasMore) startFetching();
        else showNoPlaces();
    },

    // A fila REAL da época `epoca` enquanto o treino está aberto: a que ele
    // GUARDOU (e o `sair()` devolve), ou null — fila de outra época é fila
    // refeita. É por aqui que quem pousa no meio do treino acha a fila do gesto
    // (o `enviarLote`, o `devolverPedidoRecusado`, a queda da sessão).
    filaGuardada(epoca) {
        return this.ativo && this._salvo && this._salvo.epoca === epoca ? this._salvo.queue : null;
    },

    // A época da fila REAL que o treino guarda — a que o `sair()` devolve —, ou
    // null quando ela NÃO volta: a que o perfil mandou refazer no "Sair"
    // (`anotarFilaRefeita`) e a da conta anterior (`esquecerFilaDaContaAnterior`,
    // que tira a época). É por ela que a renovação da queda decide se a fila
    // "continua aqui" (`derrubarSessao`, R11-7-03).
    epocaDaFilaGuardada() {
        if (!this.ativo || !this._salvo) return null;
        const s = this._salvo;
        return s.refazerFila || !Number.isInteger(s.epoca) ? null : s.epoca;
    },

    // O recusado de vez com o treino aberto, cuja fila é a guardada: espera o
    // `sair()` pra voltar como o próximo card dela — o `devolverPedidoRecusado`
    // de agora o poria na fila de EXEMPLOS. Num `encerrar` (fila nova) ele sai
    // com o resto: quem o traz é a busca da fila nova, como numa fila refeita.
    guardarDevolucao(place, epoca) {
        if (!this.filaGuardada(epoca)) return false;
        this._salvo.devolver.push(...(Array.isArray(place) ? place : [place]));
        return true;
    },

    // O perfil chegou com o treino aberto: ver o `sair()`.
    anotarPerfil() {
        if (this.ativo && this._salvo) this._salvo.perfilChegou = true;
    },

    // A ordem trocada nos Filtros com o treino aberto (`aplicarSoAOrdem`): ver o `sair()`.
    anotarOrdem() {
        if (this.ativo && this._salvo) this._salvo.ordemMudou = true;
    },

    // A recusa automática pedida com o treino aberto (`aplicarRecusaAutomatica`): ver o `sair()`.
    anotarRecusa() {
        if (this.ativo && this._salvo) this._salvo.recusaPedida = true;
    },

    // A fila guardada do offline lida com o treino aberto (`offlineTentarAbrirSemRede`): ver o `sair()`.
    // `n` e `t`: quantos pedidos dela entram e o carimbo dela, pra linha do
    // "Disponível offline" (`filaGuardadaEsperandoOTreino`).
    anotarFilaGuardada(n, t) {
        if (!this.ativo || !this._salvo) return;
        this._salvo.abrirGuardada = true;
        this._salvo.filaGuardadaLida = { n: Number.isFinite(n) ? n : 0, t: Number.isFinite(t) ? t : null };
    },

    // O perfil mandou REFAZER a fila real com o treino aberto (`refazerFilaReal`,
    // R9-7-04): ver o `sair()`. O aviso do país que chegar depois vale; o de um
    // refazer sem país (a área, a busca que esperava o perfil) não apaga o anterior.
    anotarFilaRefeita(aviso) {
        if (!this.ativo || !this._salvo) return;
        this._salvo.refazerFila = true;
        if (aviso) this._salvo.avisoDoPais = aviso;
    },

    // O aviso do país que o perfil anotou (`anotarFilaRefeita`) e espera o
    // "Sair", ou null. O ↻ e o "Aplicar" com busca nova encerram o treino pelo
    // `resetQueue`, que leva o `_salvo` — e o aviso — junto: eles o leem ANTES
    // (`avisarPaisDoTreinoEncerrado`, R10-7-02).
    avisoDoPaisAnotado() {
        return this.ativo && this._salvo && this._salvo.refazerFila && this._salvo.avisoDoPais ? this._salvo.avisoDoPais : null;
    },

    // A base do offline foi apagada (`offlineEsquecer`: o interruptor desligado,
    // aqui ou noutra aba, e a troca de conta): a fila guardada que a abertura sem
    // rede leu com o treino aberto (`anotarFilaGuardada`) não está mais no
    // aparelho. A anotação ficava: religado o interruptor, a linha dizia "4
    // pedidos guardados" com a base VAZIA, e o "Sair" do treino caía em "sem
    // sinal" com 0 cards (R10-4-04, MEDIDO no navegador; auditoria da rodada 10).
    esquecerFilaGuardada() {
        if (!this.ativo || !this._salvo) return;
        this._salvo.abrirGuardada = false;
        this._salvo.filaGuardadaLida = null;
    },

    // OUTRA conta entrou com o treino aberto e a fila real que ele guarda é da
    // ANTERIOR — a que atravessou a queda da sessão (`esquecerOutraConta`,
    // R10-1-01). Sai do treino tudo o que era dela: a fila, o pedido da frente, o
    // foco no autor, os recusados que voltariam no "Sair", a fila guardada do
    // offline anotada e o que o perfil dela anotou (o aviso do país, a recusa
    // automática). E os exemplos NA TELA, que são clones dos pedidos dela: no
    // lugar deles, os sintéticos — o treino de quem tem a fila vazia —, sem dado
    // de terceiro no DOM nem no relatório (`diagTreinoGuardado`). A fila de quem
    // entrou vem no "Sair" (quem chama anota o `refazerFilaReal`). A ÉPOCA da
    // fila guardada sai também: o que estava no ar sobre ela (o ✕ que a queda
    // devolve) acha uma fila refeita, como sem o treino; e a da tela sobe — a fila
    // da tela mudou, e a renovação da queda não diz "sua fila continua aqui".
    esquecerFilaDaContaAnterior() {
        if (!this.ativo || !this._salvo) return;
        const s = this._salvo;
        s.queue = [];
        s.currentPlace = null;
        s.autorEmFoco = null;
        s.devolver = [];
        s.perfilChegou = false;
        s.recusaPedida = false;
        s.avisoDoPais = null;
        this.esquecerFilaGuardada();
        s.epoca = null;
        AppState.fetchEpoch++;
        s.epocaDoTreino = AppState.fetchEpoch;
        AppState.autorEmFoco = null;
        // O card da frente é TROCADO sem gesto, e o teclado pode estar nele (a
        // trava da queda devolve o foco ao ✕ quando a sessão volta): ia pro
        // <body>. Vai ao mesmo botão do exemplo novo (`mantendoFocoNoCard`).
        mantendoFocoNoCard(() => {
            removeCurrentCardEl();
            AppState.queue = this.cards();
            this.restam = AppState.queue.length;
            AppState.currentPlace = AppState.queue[0] || null;
            updateStats(true);
            updatePendingCount(true);
            if (AppState.currentPlace) showCurrentPlace();
        }, { mesmoBotao: true });
    },

    // Encerra SEM devolver a fila salva: é o que o `resetQueue` quer (troca de
    // filtro, atualizar, sair, entrar), já que ele vai montar uma fila nova de
    // qualquer jeito. Sem isto, sair da conta com o treino aberto deixava o
    // treino ativo, e o `sair()` seguinte devolvia a fila da conta ANTERIOR.
    // A época da fila guardada NÃO volta aqui: o `resetQueue` sobe a de agora,
    // e o que estava no ar sobre a fila guardada pousa como numa fila refeita.
    encerrar() {
        if (!this.ativo) return;
        this.ativo = false;
        // O aviso que o treino pôs no último gesto ("No modo real, isto
        // enviaria…") sai com ele: ficava até 5 s sobre os ✕ ↑ ✓ do card REAL,
        // falando de um gesto que não existe mais (auditoria da rodada 10, R10-7).
        // Só o dele: os avisos de verdade têm o prazo deles. Pelo "Sair" (que passa
        // por aqui) e pelo ↻ e o "Aplicar".
        this.tirarAviso();
        // O foco da fila real volta (ver `entrar`), e a barra que estiver na tela
        // é a do TREINO: sai. Quem a desenha de novo é o card seguinte
        // (`renderFocoAutor`, no `sair()` com a fila real, ou na fila nova do
        // `resetQueue`), pela regra de sempre.
        AppState.autorEmFoco = this._salvo ? (this._salvo.autorEmFoco ?? null) : null;
        this._salvo = null;
        document.getElementById('focoAutorBar')?.classList.add('hidden');
        document.getElementById('treinoBanner')?.classList.replace('flex', 'hidden');
    },

    // O aviso que o PRÓPRIO treino pôs na tela — o efeito do último gesto, o
    // punho que o `showToast` devolve —, pra sair no próximo (`limparAvisos`).
    aviso: null,

    // Tira esse aviso NA HORA, sem a animação (`remover`; ver `limparAvisos`).
    tirarAviso() {
        if (!this.aviso) return;
        try { this.aviso.remover?.(); } catch (e) { /* o aviso já saiu */ }
        this.aviso = null;
    },

    // Chamado do TOPO dos handlers reais. Explica o que TERIA acontecido e
    // avança — sem stat, sem fila real, sem rede.
    // Um aviso por vez, e o modal final só entra depois que o último foi lido.
    // Sem isso os três se empilham e TAPAM o "Ir para a fila": medido, o botão
    // ficava inalcançável no Galaxy Fold, no iPhone SE e no celular deitado —
    // 3 de 4 aparelhos. É o gotcha #26 de novo (feedback transitório cobrindo o
    // alvo que ainda precisa ser tocado), agora numa tela de aprender a usar.
    limparAvisos() {
        // Só o aviso que o PRÓPRIO treino pôs (`this.aviso`). Varrer a pilha
        // inteira apagava também os avisos de VERDADE que chegaram com o treino
        // aberto — o resultado do "Rejeitar os N", o "Não deu pra excluir a
        // foto", o "Acesso renovado pelo WME", o "Erro ao rejeitar" — no primeiro
        // ✕/✓/↑ de treino, ~1 s depois de aparecerem: o único lugar que dizia o
        // desfecho da decisão real sumia (R9-7-02 = R9-2-02, MEDIDO no
        // navegador; auditoria de 2026-10-06). Eles têm o prazo deles. Sai NA
        // HORA, sem a animação (`remover`): o que ainda estivesse saindo contava
        // no teto de 3 da pilha, e o aviso seguinte do treino empurrava pra fora
        // um de verdade.
        this.tirarAviso();
        // Simétrico ao entrar(): sair com uma foto de TREINO aberta deixaria o
        // lightbox do modo real em cima de um pedido inerte.
        fecharCamadasDeFoto();
    },

    // O ↑ deste exemplo GUARDARIA o pedido no modo real? A régua do `handleSkip`:
    // o "Pular guarda o pedido" ligado, e o pedido sem a estrela — nem a ⭐ do
    // card (`isStarred`, R9-7-06) nem a que o app já deu, nesta aba ou noutra
    // (`estreladoPeloApp`, R10-2-05). Nesses o ↑ de verdade não manda nada, e o
    // treino dizia "pular daria ⭐" (R11-7-05, MEDIDO no navegador; auditoria da
    // rodada 11). O clone leva o `updateRequestID` inerte: a chave do pedido de
    // verdade é a do `_urFoto` (só lida aqui; escrita nenhuma o usa).
    pularGuardaria(p) {
        if (AppState.preferences.pularGuarda !== true || !p || p.isStarred === true) return false;
        return estreladoPeloApp({ venueID: p.venueID, updateRequestID: p._urFoto || p.updateRequestID }) !== true;
    },

    agir(tipo) {
        if (!this.ativo) return;
        const ultimo = AppState.queue.length <= 1;
        this.limparAvisos();
        // No último, o efeito vai DENTRO do modal final: fora dele viraria um
        // aviso flutuante sobre a área do card já vazia (o swipe animou o card
        // pra fora), e esperar pra ler deixava 2,2s de tela em branco.
        // O ↑ com o "Pular guarda o pedido" ligado ENVIA a estrela no modo real:
        // "pular não envia nada" seria falso justamente pra quem o ligou. Menos
        // no pedido que já a tem (ver `pularGuardaria`).
        const efeitoChave = 'treino.efeito.' + (tipo === 'skip' && this.pularGuardaria(AppState.queue[0]) ? 'skipGuarda' : tipo);
        if (!ultimo) this.aviso = showToast(t(efeitoChave), tipo === 'reject' ? 'error' : 'info', 5000);
        this.stats[tipo === 'reject' ? 'rejected' : tipo === 'read' ? 'read' : 'skipped']++;
        this.restam = Math.max(0, this.restam - (tipo === 'skip' ? 0 : 1));
        updateStats();
        AppState.queue.shift();
        AppState.currentPlace = AppState.queue[0] || null;
        this.passo++;
        updatePendingCount();
        // No ÚLTIMO, o card fica na tela enquanto o aviso é lido: tirá-lo deixava
        // 2,2s de área em branco antes do modal final, o que lê como app quebrado.
        // Quem limpa é o `sair()`.
        if (AppState.currentPlace) { removeCurrentCardEl(); showCurrentPlace(); return; }
        const efeito = document.getElementById('treinoFimEfeito');
        if (efeito) {
            efeito.textContent = t(efeitoChave);
            efeito.classList.remove('hidden');
        }
        // "O Desfazer te dá 3s em cada ação" só é verdade com a janela: com o
        // Desfazer desligado, a primeira ação de verdade saía na hora, logo
        // depois da promessa (auditoria de 2026-09-29, A6).
        trocarTextoI18n(document.getElementById('treinoFimCorpo'),
            semJanelaDeDesfazer() ? 'treino.fim.bodySemDesfazer' : 'treino.fim.body');
        openModal('treinoFimModal');
    },
};
window.Treino = Treino;

// A fila REAL — a que o Waze tem pra esta pessoa —, esteja ou não na tela. Com
// o TREINO aberto, a `AppState.queue` é a fila de EXEMPLOS (clones com o
// `updateRequestID` inerte) e a real fica guardada nele (`Treino._salvo.queue`)
// até o `sair()` a devolver. Quem pergunta pela fila de VERDADE pergunta aqui:
// olhar a da tela com o treino aberto era olhar os exemplos — a escrita da foto
// que a queda da sessão pegou no ar não chegava ao pedido nem avisava
// (`pedidoAindaNaTela`, R8-3-02), a decisão da outra aba não era anotada
// (`anotarDecididosPorOutraAba`, R8-4-02) e a linha do "Disponível offline"
// contava os exemplos como "pedidos no aparelho" (R8-4-05; auditoria de
// 2026-10-03, rodada 8, MEDIDO no navegador). Fora do treino, é a da tela.
function filaReal() {
    if (typeof Treino !== 'undefined' && Treino.ativo === true && Treino._salvo && Array.isArray(Treino._salvo.queue)) {
        return Treino._salvo.queue;
    }
    return AppState.queue || [];
}

// A fila real E o que o Waze recusou de vez com o treino aberto e volta como o
// próximo card no `sair()` (`Treino._salvo.devolver`, ver `guardarDevolucao`). É
// a régua das perguntas de IDENTIDADE — "este pedido ainda é desta tela?"
// (`pedidoAindaNaTela`), "quem são os irmãos dele?" (`aplicarNosIrmaos`), "a
// decisão da outra aba caiu num card daqui?" (`anotarDecididosPorOutraAba`): o
// devolvido é pedido da tela de quem volta do treino. Pela `filaReal()`, a
// exclusão (ou o nome) que pousou não chegava a ele — de volta à fila, a lixeira
// oferecia a foto que já tinha saído e dizia "Outro editor já tinha excluído 👍"
// sobre a exclusão da própria pessoa —, e a que não chegou ao Waze não voltava
// nem avisava (R9-7-01 = R9-3-03, MEDIDO no navegador; auditoria de
// 2026-10-06). Quem CONTA a fila (a linha do offline, o "Restam") segue na
// `filaReal()`: o devolvido volta a contar quando volta à fila.
function filaRealComDevolvidos() {
    const real = filaReal();
    const devolver = (typeof Treino !== 'undefined' && Treino.ativo === true && Treino._salvo
        && Array.isArray(Treino._salvo.devolver)) ? Treino._salvo.devolver : [];
    return devolver.length ? [...real, ...devolver] : real;
}

// A fila guardada do offline que a reabertura sem rede leu com o treino aberto e
// espera o "Sair" dele (`Treino.anotarFilaGuardada`, R8-4-04): `{ n, t }` —
// quantos pedidos dela entram e o carimbo dela —, ou null. A linha do
// "Disponível offline" fala dela enquanto a fila real do treino está vazia
// (R9-4-03).
function filaGuardadaEsperandoOTreino() {
    if (typeof Treino === 'undefined' || Treino.ativo !== true || !Treino._salvo) return null;
    const g = Treino._salvo.filaGuardadaLida;
    return g && g.n > 0 ? g : null;
}

// ── Presença no WME, de carona nas ações (fase 2) ─────────────────────────
//
// Quem usa o app aparece no mapa do WME, no lugar do card que está olhando. A
// posição vai DENTRO da ação que o app já manda (rejeitar, marcar como lido) e
// o servidor a escreve no WME com a marca de quem está no app
// (`server/marca-app.mjs`). Zero requisição nova: o app roda no free tier do
// Cloudflare, e uma chamada por card seria a conveniência pagando com o recurso
// contado (decisão do owner, 2026-09-23).
//
// Decisões que não são gosto:
//   · só o envio AO VIVO leva posição. A fila de saída manda depois, quando a
//     posição já é velha; o lote e a recusa automática não são alguém olhando
//     um card. Por isso a posição é montada DENTRO do executor, na hora do
//     envio, e nunca guardada em item nenhum;
//   · FREIO de 30 s entre escritas. Quem olha pelo WME não percebe: o WME não
//     redesenha sozinho (MEDIDO, fase 1). E dobrar as chamadas ao Waze em nome
//     de cada editor, no ritmo do swipe, é a assinatura que faz um WAF marcar a
//     conta de quem está triando;
//   · a posição é a do card NA TELA quando a ação sai (o próximo, depois do
//     gesto): é onde a pessoa está olhando. Sem card na tela, a do pedido;
//   · a VISIBILIDADE liga sozinha e em silêncio (decisão do owner). O perfil diz
//     como ela está (`visivelNoWme`, de graça no `/Session`) e, se estiver
//     desligada, a próxima ação a liga de carona. Quem decide é SÓ o "Ver quem
//     está no app" (decisão do owner, 2026-09-24: por padrão a pessoa aparece,
//     como a comunidade decidiu). Até ali, invisível no WME DEPOIS de o app já
//     a ter visto ligada desligava o interruptor por 9 dias; saiu. Consequência
//     assumida: é a mesma chave nos dois lugares, então quem se esconde pelo WME
//     e segue triando com o interruptor ligado volta a aparecer na ação
//     seguinte — pra ficar invisível usando o app, o caminho é o interruptor.
//     E abrir o WME NÃO desliga ninguém (MEDIDO: ele só escreve no `moveend`,
//     com a máscara só em `location`);
//   · nada disso pode derrubar a ação: qualquer erro aqui vira "sem posição".
const PRESENCA_WME_FREIO_MS = 30000;
const presencaWme = {
    ligarNaProxima: false,
    ultimaEm: 0,
    enviadas: 0,
    falhas: 0,
    ultimaFalha: null,
    falhaAnotada: null,     // a última falha que foi pro diário, e quando (ver o limitador)
    falhaAnotadaEm: 0,
    marcaPerdida: false,
    perfilVisivel: null,    // o que o `/Session` disse da visibilidade na última leitura
    perfilEm: 0,
    // O `visivel: false` do GESTO de desligar que não saiu por falta de rede: é
    // a MESMA chave do perfil do WME, e sem refazê-lo a pessoa que desligou o
    // interruptor seguia visível lá (auditoria de 2026-09-25). A próxima prova
    // de rede o manda de novo. E ele fica GRAVADO no aparelho também, com a
    // conta (ver `presencaWmeGravarPendente`).
    desligarPendente: false,
    // Quando o desligar saiu por último, pro teto da repetição (ver
    // `presencaWmeRefazerDesligar`). Zero = a repetição sai na próxima prova.
    desligarEm: 0,
    // A marca da SESSÃO desse último envio (`marcaDaSessao`).
    desligarSessao: null,
    // A marca da sessão cujo envio levou 401 NESTA aba: trocada essa sessão (a
    // renovação depois do 401), o carimbo dela não segura o teto, e o pendente
    // sai já (R5-5-8). Só ela: o teto é da CONTA, não da sessão (R9-5-02; ver
    // `presencaWmeRefazerDesligar`).
    desligar401Sessao: null,
    // A conferência de que a aba de um carimbo ainda VIVE, no ar (ver
    // `presencaWmeConferirAbaDoCarimbo`): uma por vez.
    conferindoAba: false,
    // O desligar que FALHA, no diário (ver `presencaWmeAnotarDesligar`): o
    // total, e a última falha que foi pro diário e quando.
    desligarFalhas: 0,
    desligarFalhaAnotada: null,
    desligarFalhaAnotadaEm: 0,
    // QUANDO o desligar levou o 401 que mandou conferir a sessão: o critério do
    // `u401` da fila de saída (ver `presencaWmeDesligar`). `null` = nenhum ainda
    // nesta série — e tem de ser `null`, não 0: com 0, uma sessão confirmada
    // viva por OUTRO motivo, antes, dispensaria a conferência do primeiro 401.
    desligar401Em: null,
    // O número do ÚLTIMO envio do desligar, e o do que está no ar (0 = nenhum):
    // com o "invisível" gravado ANTES de sair (R7-5-03), quem decide o gravado
    // é a resposta do último envio, e nenhuma repetição sai por cima dele (ver
    // `presencaWmeDesligar`).
    desligarVez: 0,
    desligarNoAr: 0,
};

// Refazer o desligar que o WAZE recusou por estar fora (a resposta veio, com
// 5xx ou gRPC 14): no máximo uma vez por minuto. Sem o teto, CADA resposta da
// nossa API — uma por swipe — refazia o `visivel: false` enquanto o Waze
// estivesse fora (MEDIDO: 6 ✕ → 6 pedidos a mais; auditoria de 2026-09-29). O
// que não chegou a ter resposta (a rede) não conta: a próxima prova de rede o
// refaz na hora, como o pedido do token do tempo real.
const PRESENCA_WME_DESLIGAR_REPETIR_MS = 60 * 1000;

// `paisDoGesto`: o país do filtro na hora do GESTO. A ação pode sair DEPOIS de
// a pessoa trocar de país — a janela do Desfazer despachada pelo "Aplicar" dos
// Filtros, ou a resposta ainda no ar —, e a posição (a marca leva o país) e a
// lista que volta de carona são do país em que o card estava, não do de agora
// (auditoria de 2026-09-26).
function presencaWmeDaAcao(placeDaAcao, paisDoGesto) {
    try {
        if (Treino.ativo) return null;
        // A DESCARGA (a página indo pro fundo ou fechando com a ação na janela do
        // Desfazer) não leva posição: ninguém está olhando o card, e a regra é
        // a da fila de saída e do lote (auditoria de 2026-09-29). É ela quem
        // liga o `saindo` antes de despachar (`descarregarAcaoPendente`).
        if (API.saindo) return null;
        const ligada = typeof presencaLigada === 'function'
            ? presencaLigada() : AppState.preferences.presenca !== false;
        if (!ligada || !AppState.authenticated) return null;
        if (navigator.onLine === false) return null;
        const id = AppState.profile && AppState.profile.id;
        if (id === null || id === undefined || !/^\d{1,19}$/.test(String(id))) return null;
        const place = AppState.currentPlace || placeDaAcao;
        // `mapa.centro` é [lat, lon] — o core inverte o GeoJSON. Ler ao contrário
        // põe a pessoa num lugar plausível e ERRADO, sem erro nenhum.
        const centro = place && place.mapa && place.mapa.centro;
        if (!Array.isArray(centro) || !Number.isFinite(centro[0]) || !Number.isFinite(centro[1])) return null;
        const agora = Date.now();
        if (agora - presencaWme.ultimaEm < PRESENCA_WME_FREIO_MS) return null;
        presencaWme.ultimaEm = agora;
        const pais = paisDoGesto !== undefined && paisDoGesto !== null ? paisDoGesto : API.getCountry();
        const presenca = { userId: String(id), lat: centro[0], lon: centro[1], pais };
        if (presencaWme.ligarNaProxima) presenca.visivel = true;
        // Fase 3: a lista de quem usa o app volta de carona, e as conversas que
        // o aparelho já conhece vão junto pra ela incluir as que foram
        // respondidas pelo WME (sem a marca do app).
        const conhecidos = window.Presenca?.conhecidos?.();
        if (Array.isArray(conhecidos) && conhecidos.length) presenca.conhecidos = conhecidos;
        // O instante desta carona vai COM ela, fora do que é mandado (não
        // enumerável: o JSON do pedido não o leva) — é ele que diz de quando é a
        // lista que volta (ver `presencaWmeAoResponder`).
        Object.defineProperty(presenca, 'saiuEm', { value: agora });
        return presenca;
    } catch (e) {
        return null;
    }
}

function presencaWmeAoResponder(presenca, result) {
    try {
        // A lista de quem usa o app e as conversas (fase 3), de carona. O
        // instante é o de quando a carona SAIU: mensagem que chegou ao vivo
        // depois disso a lista ainda não contou. E é o DESTA carona (`saiuEm`),
        // não o `ultimaEm` lido agora: com o Waze lento (além do freio de 30 s),
        // a resposta de uma ação velha chegava depois de a carona da seguinte
        // sair, entrava com o instante da nova e passava pela régua da lista
        // mais velha que não pousa — a conversa lida nesse meio voltava como
        // "1 mensagem nova" (auditoria de 2026-10-02, R7-5-04). E o país é o
        // DELA: a lista é do país que a carona levou, e a presença a descarta se
        // ele não for mais o do filtro.
        const saiuEm = presenca && Number.isFinite(presenca.saiuEm) ? presenca.saiuEm : presencaWme.ultimaEm;
        if (presenca && result && result.presencaApp) window.Presenca?.aoCarona?.(result.presencaApp, saiuEm, presenca.pais);
        const r = presenca && result && result.presenca;
        if (!r) return;
        if (r.ok) {
            presencaWme.enviadas++;
            if (presenca.visivel === true) {
                presencaWme.ligarNaProxima = false;
                dfato('presencaWme.visivel', { ligou: true, via: 'carona', marca: r.marca });
            }
            // O Waze devolve a posição gravada: se os dígitos voltarem diferentes,
            // a marca de quem está no app se perdeu (o dia em que ele arredondar).
            if (r.marca === false && !presencaWme.marcaPerdida) {
                presencaWme.marcaPerdida = true;
                dfato('presencaWme.marcaPerdida', {});
            }
        } else {
            presencaWme.falhas++;
            presencaWme.ultimaFalha = r.categoria || 'erro';
            // No diário, a falha NOVA (categoria que ainda não entrou) e, da
            // mesma, uma a cada 10 min. Zerar no sucesso não serve: com o Waze
            // falhando uma escrita sim, outra não, cada falha virava uma linha —
            // até duas por minuto, pelo freio de 30 s — e empurrava o resto do
            // anel (120) pra fora em uma hora. O total fica em `falhas`.
            const agora = Date.now();
            if (presencaWme.falhaAnotada !== presencaWme.ultimaFalha || agora - presencaWme.falhaAnotadaEm >= 10 * 60000) {
                presencaWme.falhaAnotada = presencaWme.ultimaFalha;
                presencaWme.falhaAnotadaEm = agora;
                dfato('presencaWme.falhou', { categoria: presencaWme.ultimaFalha, visivel: presenca.visivel === true, total: presencaWme.falhas });
            }
        }
    } catch (e) { /* diagnóstico nunca derruba a ação */ }
}

// O WME só INFORMA: invisível lá, com o interruptor do app ligado, vira "ligar
// na próxima ação". Nunca desliga o interruptor nem grava preferência — quem
// decide é a pessoa, no app (ver o cabeçalho desta seção).
function presencaWmeAoCarregarPerfil(visivel) {
    if (typeof visivel !== 'boolean') return;   // servidor antigo: não decide nada
    presencaWme.perfilVisivel = visivel;
    presencaWme.perfilEm = Date.now();
    if (AppState.preferences.presenca === false) return;   // desligado: o app não mexe no WME
    presencaWme.ligarNaProxima = !visivel;
    if (!visivel) dfato('presencaWme.visivel', { perfil: false, ligarNaProxima: true });
}

// A pessoa desligou o "Ver quem está na fila": some do WME na hora. É a única
// requisição própria da fase 2, e só acontece no GESTO. `repeticao`: quem chama
// é o `presencaWmeRefazerDesligar`, refazendo o gesto que não chegou.
function presencaWmeDesligar({ repeticao = false } = {}) {
    presencaWme.ligarNaProxima = false;
    presencaWme.desligarPendente = false;
    // O resultado do GESTO entra no diário sempre; a repetição que falha, pelo
    // limitador (ver `presencaWmeAnotarDesligar`). E o gesto é uma série NOVA:
    // o 401 dele confere a sessão (ver o `desligar401Em`, abaixo).
    if (!repeticao) { presencaWme.desligarFalhaAnotada = null; presencaWme.desligar401Em = null; }
    // Sem SESSÃO (a janela da renovação pela extensão, com os Filtros abertos),
    // o gesto era descartado: a pessoa seguia visível no WME (auditoria de
    // 2026-09-30, R5-5-8). Fica pendente, como o sem perfil logo abaixo, e o
    // perfil que chegar com a sessão nova o manda (`definirPerfil`). A sessão
    // DESTA aba é a da memória: o `getSession`, com ela vazia, GRAVA nela a que
    // outra aba guardou no aparelho — é adotá-la (R9-1-03; R11-1-02).
    if (!API.temSessaoNaMemoria()) {
        if (AppState.preferences.presenca === false) { presencaWme.desligarPendente = true; presencaWmeGravarPendente(); }
        return;
    }
    const id = AppState.profile && AppState.profile.id;
    // Sem o PERFIL (o app aberto sem rede com a fila guardada, ou o perfil que
    // falhou na abertura) o `visivel: false` não tem pra quem ir — e era
    // descartado: a volta da rede e a chegada do perfil não o mandavam nunca, e
    // a pessoa seguia visível no WME (auditoria da costura, 2026-09-26, K5).
    // Fica pendente, e o perfil chegando o manda (`definirPerfil`). Gravado com
    // a SESSÃO do gesto quando a conta dela ainda não se sabe (ver
    // `presencaWmeGravarPendente`, R12-5-05).
    if (id === null || id === undefined) {
        if (AppState.preferences.presenca === false) {
            presencaWme.desligarPendente = true;
            presencaWmeGravarPendente({ doGesto: marcaDestaAba() });
        }
        return;
    }
    presencaWme.desligarEm = Date.now();
    presencaWme.desligarSessao = marcaDaSessao(API.getSession());
    // GRAVADO antes de sair, e não só quando a falha volta: com o pedido
    // pendurado (o sinal fraco: o `_post` espera até 45 s) e o app fechado — ou
    // encerrado pelo Android — antes da resposta, nada ficava no aparelho, e a
    // reabertura com rede não mandava o "invisível": a pessoa seguia visível no
    // WME contra o gesto (auditoria de 2026-10-02, R7-5-03). A resposta decide o
    // gravado: o sucesso e a recusa de verdade o apagam (abaixo). E a OUTRA aba,
    // que relê as preferências, o herda: se esta fechar com o pedido no ar, a
    // prova de rede de lá o manda.
    //
    // E o gravado leva a hora DESTE envio e a sessão dele (`tentadoEm`): o teto
    // de um por minuto é do APARELHO, não da aba. A outra aba adotava o gravado
    // com este envio no ar, e mandava o mesmo "invisível" de novo; com o Waze
    // fora, cada aba repetia no teto dela — 2 por minuto com duas abas
    // (auditoria da rodada 8, R8-5-07; ver `presencaWmeRefazerDesligar`). E a
    // MARCA desta aba (`aba`): o carimbo só segura o teto enquanto a aba que o
    // deixou vive (R9-5-04). O `typeof`: os testes que fatiam isto sem a marca.
    const sessaoDoEnvio = presencaWme.desligarSessao;
    if (AppState.preferences.presenca === false) {
        presencaWmeGravarPendente({ tentadoEm: presencaWme.desligarEm, sessao: sessaoDoEnvio,
            aba: typeof ABA_DESTA_PAGINA === 'string' ? ABA_DESTA_PAGINA : null });
    }
    // Quem decide o gravado é a resposta do ÚLTIMO envio: a de um envio anterior
    // que chega depois (o gesto de novo, a troca de conta no meio) não apaga o
    // gravado do envio no ar nem cria pendente por cima dele. E, com um envio no
    // ar, a repetição espera a resposta dele (ver `presencaWmeRefazerDesligar`):
    // adotar o gravado mandaria o mesmo "invisível" duas vezes.
    const vez = (presencaWme.desligarVez || 0) + 1;
    presencaWme.desligarVez = vez;
    presencaWme.desligarNoAr = vez;
    API.presencaWaze({ userId: String(id), visivel: false })
        .then((r) => {
            const ultimo = vez === presencaWme.desligarVez;
            if (presencaWme.desligarNoAr === vez) presencaWme.desligarNoAr = 0;
            // Só o TRANSIENTE e o 401 ficam pendentes; recusa de verdade não se
            // repete sozinha. E o que nem teve resposta (a rede; o `_post` põe
            // `_motivo`) sai na próxima prova de rede, sem o teto de um minuto:
            // é a resposta que chega que prova a rede (ver o teto, acima).
            //
            // O 401 era descartado e não conferia a sessão: o `visivel: false`
            // nunca chegava ao WME (auditoria de 2026-09-30, R5-5-8). Fica
            // pendente, COM o teto (a sonda do alarme falso traz o perfil, e o
            // perfil refaz o desligar: sem o teto, um 401 que se repete com a
            // sessão viva viraria um laço de pedido e sonda), e a sessão é
            // conferida — morta, a renovação traz uma sessão NOVA, que não herda
            // o teto (`presencaWmeRefazerDesligar`).
            const e401 = !!(r && r.errorCategory === 'unauthorized');
            // A sessão que levou o 401: a renovação a troca, e o carimbo dela
            // deixa de segurar o teto (ver `presencaWmeRefazerDesligar`).
            if (e401) presencaWme.desligar401Sessao = sessaoDoEnvio;
            if (!(r && r.success) && (!r || r.errorCategory === 'transient' || e401)
                && AppState.preferences.presenca === false) {
                if (ultimo) {
                    presencaWme.desligarPendente = true;
                    // Sem resposta (a rede), o teto não vale — em NENHUMA aba: o
                    // carimbo deste envio sai do gravado (R8-5-07).
                    const semResposta = !r || typeof r._motivo === 'string';
                    presencaWmeGravarPendente(semResposta ? { tentadoEm: 0 } : {});
                    if (semResposta) presencaWme.desligarEm = 0;
                }
            } else if (ultimo && !presencaWme.desligarPendente) {
                // Chegou (ou foi recusado de vez, ou religaram no meio): o
                // gravado não vale mais. Só sem pendente NA MEMÓRIA: um desligar
                // novo sem sessão ou sem perfil, feito com este no ar, já gravou
                // o dele.
                presencaWmeEsquecerGravado();
            }
            // O 401 confere a sessão — menos quando ela foi CONFIRMADA viva
            // depois do 401 que já a conferiu (`sessaoVivaDepoisDe`, o critério
            // do `u401` da fila de saída): aí não é a sessão, é o "invisível"
            // que o Waze recusa, e conferir de novo era uma sonda do perfil e um
            // "Sua sessão continua válida" a cada minuto (o teto da repetição),
            // na cara de quem tria. Ele segue pendente, com o teto, e o diário
            // anota pelo limitador. A sonda que não confirmou nada (5xx, rede)
            // não é prova, e numa sessão nova a marca é outra: o 401 dela
            // confere de novo — a sessão morta de verdade segue caindo.
            //
            // Perguntado SÓ com o 401: a resposta pode chegar depois da queda,
            // com a memória desta aba vazia, e qualquer leitura da sessão pelo
            // `getSession` ali adotava calada a que outra aba guardou no aparelho
            // (R12-1-03; a pergunta, hoje, lê a memória — `marcaDestaAba`).
            const vivaDepois = e401 && typeof sessaoVivaDepoisDe === 'function'
                && sessaoVivaDepoisDe(presencaWme.desligar401Em) === true;
            if (e401 && !vivaDepois) {
                presencaWme.desligar401Em = Date.now();
                if (typeof handleUnauthorized === 'function') handleUnauthorized();
            }
            presencaWmeAnotarDesligar(r);
        })
        // O envio que nem voltou não segura a repetição pra sempre.
        .catch(() => { if (presencaWme.desligarNoAr === vez) presencaWme.desligarNoAr = 0; });
}

// O "invisível" pendente fica GRAVADO no aparelho, com a CONTA, nas
// preferências (`presencaWmeDesligar: { conta, em }`). Só na memória, fechar o
// app antes de ele sair — sem rede, na janela da renovação — o perdia: o
// interruptor seguia desligado, o perfil dizia "visível" e nada saía, e a
// pessoa seguia visível no WME contra o gesto dela (auditoria de 2026-10-01,
// R6-5-2, MEDIDO: fechar e abrir → 0 `visivel: false`). Quem decide a
// visibilidade é SÓ o interruptor do app, e o gesto dele tem de chegar ao WME.
// Por isso ele é gravado no GESTO, antes de o pedido sair, e não só quando a
// falha volta: o pedido pendurado no sinal fraco não volta nunca se o app
// fechar (R7-5-03, ver `presencaWmeDesligar`).
// Só a MESMA conta o manda (`presencaWmeRefazerDesligar`, com o perfil na mão);
// sai no sucesso, no religar, na troca de conta e no "Sair"
// (`presencaWmeZerar`, e o "Sair" repõe as preferências de fábrica).
//
// A conta é a do perfil vivo; sem ele (a renovação, o app aberto sem rede), a
// última que o aparelho conheceu — o perfil que chegar confere, e outra conta
// apaga o gravado na troca. Sem nenhuma, fica só na memória: não há a quem
// conferir.
//
// `doGesto` (a marca da sessão DESTA aba, `marcaDestaAba`): o GESTO feito com
// sessão e sem o perfil. Aí a conta é a DESTA sessão — a do aparelho só se foi
// vista com ela (`contaAgora`) —, e desconhecida, o gesto é gravado com a marca
// da sessão (`{ s, em }`), e a conta sai do perfil DELA quando chegar
// (`aoConhecerConta`), como os itens da fila de saída (`carimbarContaNaSaida`).
// Lida do aparelho sem conferir a marca, a conta era a de OUTRA sessão: o perfil
// que chegava era de quem entrou, a troca de conta jogava fora o gesto dela, e o
// interruptor ficava desligado com a pessoa visível no WME (auditoria da rodada
// 12, R12-5-05, MEDIDO).
//
// `tentadoEm` (com a `sessao` e a `aba`, a marca da aba do envio): a hora do
// último ENVIO, que o gravado carrega pras outras abas respeitarem o teto da
// repetição (R8-5-07, R9-5-04); 0 tira o carimbo (o envio que não teve
// resposta, ou que morreu com a página). Sem ele, só grava o que ainda não está
// gravado.
function presencaWmeGravarPendente({ tentadoEm, sessao, aba, doGesto = null } = {}) {
    let conta = AppState.profile && AppState.profile.id;
    if (conta === null || conta === undefined || conta === '') {
        if (doGesto) conta = contaAgora();
        else {
            try { const c = JSON.parse(safeLS.get(CONTA_KEY) || 'null'); conta = c && c.id; } catch (e) { conta = null; }
        }
    }
    if ((conta === null || conta === undefined || conta === '') && doGesto) {
        const g = AppState.preferences.presencaWmeDesligar;
        if (g && !g.conta && g.s === String(doGesto)) return;   // já gravado
        AppState.preferences.presencaWmeDesligar = { s: String(doGesto), em: Date.now() };
        savePreferences();
        return;
    }
    if (conta === null || conta === undefined || conta === '') return;
    conta = String(conta);
    const g = AppState.preferences.presencaWmeDesligar;
    const mesma = !!(g && g.conta === conta);
    if (tentadoEm === undefined) {
        if (mesma) return;   // já gravado: o `setItem` é síncrono, e cada repetição passaria aqui
        AppState.preferences.presencaWmeDesligar = { conta, em: Date.now() };
    } else {
        const novo = { conta, em: mesma ? g.em : Date.now() };
        if (tentadoEm > 0) {
            novo.tentadoEm = tentadoEm;
            novo.sessao = sessao;
            if (typeof aba === 'string' && aba) novo.aba = aba;
        }
        if (mesma && g.tentadoEm === novo.tentadoEm && g.sessao === novo.sessao && g.aba === novo.aba) return;
        AppState.preferences.presencaWmeDesligar = novo;
    }
    savePreferences();
}

// A página SAI com o "invisível" no AR: o envio morre com ela (o `fetch` sem
// keepalive é cancelado no unload), e o carimbo dele faria a outra aba — ou a
// reabertura — esperar o teto à toa. O gravado fica, sem o carimbo: quem o
// manda é a próxima prova de rede de lá (R7-5-03, R8-5-07). Chamado no
// `pagehide` (`setupDescargaAoSair`); a página só ESCONDIDA segue viva e
// mantém o carimbo.
function presencaWmeSoltarAoSair() {
    if (presencaWme.desligarNoAr && AppState.preferences.presenca === false) presencaWmeGravarPendente({ tentadoEm: 0 });
}

function presencaWmeEsquecerGravado() {
    if (!AppState.preferences.presencaWmeDesligar) return;
    delete AppState.preferences.presencaWmeDesligar;
    savePreferences();
}

// O desligar no diário (R6-5-3). O GESTO entra sempre — com o resultado. A
// repetição (`presencaWmeRefazerDesligar`, até uma por minuto com o Waze fora)
// entra quando a falha MUDA de categoria e, a mesma, uma a cada 10 min: o
// limitador da falha da carona (`presencaWmeAoResponder`). Sem ele, cada
// repetição era uma linha, e 2 h de triagem com o Waze fora enchiam o anel
// (120) só com elas, empurrando a queda da sessão e a da rede pra fora (MEDIDO:
// 121 linhas em 2 h, contra 12 da carona). O total vai em `desligarFalhas`.
function presencaWmeAnotarDesligar(r) {
    if (r && r.success) {
        dfato('presencaWme.visivel', { desligou: true, via: 'interruptor', ok: true });
        return;
    }
    presencaWme.desligarFalhas = (presencaWme.desligarFalhas || 0) + 1;
    const categoria = (r && r.errorCategory) || 'sem resposta';
    const agora = Date.now();
    if (presencaWme.desligarFalhaAnotada === categoria && agora - presencaWme.desligarFalhaAnotadaEm < 10 * 60000) return;
    presencaWme.desligarFalhaAnotada = categoria;
    presencaWme.desligarFalhaAnotadaEm = agora;
    dfato('presencaWme.visivel', { desligou: true, via: 'interruptor', ok: false, categoria, total: presencaWme.desligarFalhas });
}

// A prova de rede refaz o desligar que não saiu (ver `desligarPendente`), com o
// teto de um minuto pro Waze que responde fora (`PRESENCA_WME_DESLIGAR_REPETIR_MS`).
// E retoma o que ficou GRAVADO (o app fechou antes de ele sair): com o perfil
// da MESMA conta na mão — é o `definirPerfil` que chama isto quando ele chega.
// `abaMorta`: a aba cujo carimbo a conferência achou MORTA (ver
// `presencaWmeConferirAbaDoCarimbo`) — o carimbo dela não segura nada.
function presencaWmeRefazerDesligar({ abaMorta = null } = {}) {
    // Sem sessão nesta aba (a tela de entrada, a renovação no ar), o pendente
    // ESPERA: quem o manda é o perfil que chegar com a sessão nova
    // (`definirPerfil`). Seguir até o envio lia a sessão pelo `getSession`, que
    // com a memória vazia GRAVA nela a que outra aba guardou no aparelho: a
    // resposta de um código errado na tela de entrada ADOTAVA calada a sessão da
    // outra aba — a volta à aba não a adotava mais, e o "Sair" de lá fechava o
    // "Colar cookies" daqui (o R9-1-03 por outra porta; auditoria da rodada 11,
    // R11-1-02, MEDIDO).
    //
    // E sem o PERFIL também: a sessão nova pode ser de OUTRA conta (a adotada da
    // outra aba, a que a extensão trouxe), e só o perfil diz de quem ela é — a
    // troca tira da memória o pendente da conta anterior (`aoConhecerConta`).
    // Antes dele, a repetição gravava o pendente com a conta do APARELHO
    // (`presencaWmeGravarPendente`), a de quem entrou na outra aba: MEDIDO, a
    // busca respondendo antes do perfil, e a outra aba mandava o "invisível" de
    // quem nunca o pediu (R11-1-01).
    if (!AppState.authenticated || !AppState.profile) return;
    if (AppState.preferences.presenca !== false) return;
    // Com um envio no AR, quem decide é a resposta dele: o gravado é dele
    // (gravado no gesto, R7-5-03), e adotá-lo aqui marcava o pendente na memória
    // — a resposta boa já não o apagava, e o mesmo "invisível" saía de novo um
    // minuto depois, a cada desligar com uma prova de rede no meio.
    if (presencaWme.desligarNoAr) return;
    // Nada pendente nem gravado na cópia desta aba (que a releitura das
    // preferências mantém em dia): nada a fazer, e sem ler o aparelho a cada
    // resposta da API de quem só deixou o interruptor desligado.
    if (!presencaWme.desligarPendente && !AppState.preferences.presencaWmeDesligar) return;
    // O gravado como está no APARELHO agora: a OUTRA aba o manda, carimba e
    // apaga, e o aviso `storage` chega quando chega (R8-5-07). Ilegível
    // (`undefined`), vale a cópia desta aba.
    let noAparelho;
    try {
        const p = JSON.parse(localStorage.getItem(PREFERENCES_KEY) || 'null');
        const x = p && p.presenca === false ? p.presencaWmeDesligar : null;
        noAparelho = x && typeof x === 'object' ? x : null;
    } catch (e) { noAparelho = undefined; }
    const g = noAparelho === undefined ? AppState.preferences.presencaWmeDesligar : noAparelho;
    if (presencaWme.desligarPendente) {
        // O gravado que esta aba conhecia SUMIU do aparelho: a outra aba o
        // entregou (a resposta boa de lá o apaga) — o pendente daqui era o
        // mesmo "invisível", e mandá-lo de novo seria o envio repetido.
        if (noAparelho === null && AppState.preferences.presencaWmeDesligar) {
            presencaWme.desligarPendente = false;
            delete AppState.preferences.presencaWmeDesligar;
            return;
        }
    } else {
        const id = AppState.profile && AppState.profile.id;
        if (!g || id === null || id === undefined || String(g.conta) !== String(id)) return;
    }
    // O teto é do APARELHO: conta o último envio desta página e o de QUALQUER
    // aba, que o gravado carrega (`tentadoEm`). A outra aba adotava o gravado
    // com o envio desta no ar — o mesmo "invisível" duas vezes — e, com o Waze
    // fora, cada aba repetia no teto dela (MEDIDO: 11 envios em 5 min com duas
    // abas, contra 6 com uma; auditoria da rodada 8, R8-5-07). Só depois do teto
    // o gravado é adotado: adotado antes, o pendente ficava na memória mesmo com
    // a outra aba entregando.
    //
    // E é da CONTA, não da sessão: duas abas da mesma conta com sessões
    // diferentes (uma entrou de novo pelo botão do WME, colando os cookies, ou
    // renovou pela extensão) ignoravam o carimbo uma da outra — o R8-5-07 de
    // volta, 11 envios em 5 min (auditoria da rodada 9, R9-5-02). A exceção é
    // a sessão que ESTA aba trocou depois de um 401 do desligar
    // (`desligar401Sessao`): o carimbo dela não segura nada, e a renovação o
    // manda já; o alarme falso (a MESMA sessão) segue com o teto, e não vira
    // laço (R5-5-8).
    //
    // O carimbo com a marca DESTA aba vale pela memória (`desligarEm`): o do
    // gravado é desta página — e a memória já o tem — ou de uma anterior dela,
    // que morreu sem `pagehide` com o envio no ar (o Android descarta a aba no
    // fundo). O de OUTRA aba só segura enquanto ela VIVE: se ela morreu assim,
    // o envio morreu junto, e esperar o teto era só atraso (R9-5-04; ver
    // `presencaWmeConferirAbaDoCarimbo`). O `typeof`: os testes que fatiam isto
    // sem a marca.
    const sessao = marcaDaSessao(API.sessionToken);
    const renovadaAqui = (s) => !!s && s === presencaWme.desligar401Sessao && s !== sessao;
    const daqui = renovadaAqui(presencaWme.desligarSessao) ? 0 : presencaWme.desligarEm;
    const aba = typeof ABA_DESTA_PAGINA === 'string' ? ABA_DESTA_PAGINA : null;
    const conta = AppState.profile && AppState.profile.id;
    const deOutraAba = g && Number.isFinite(g.tentadoEm) && g.tentadoEm > 0
        && !(aba && g.aba === aba) && !(abaMorta && g.aba === abaMorta) && !renovadaAqui(g.sessao)
        && (conta === null || conta === undefined || String(g.conta) === String(conta)) ? g.tentadoEm : 0;
    const agora = Date.now();
    if (agora - daqui < PRESENCA_WME_DESLIGAR_REPETIR_MS) return;
    if (agora - deOutraAba < PRESENCA_WME_DESLIGAR_REPETIR_MS) {
        // Sem a marca (o gravado de antes dela), vale o teto.
        if (g.aba) presencaWmeConferirAbaDoCarimbo(g.aba);
        return;
    }
    presencaWme.desligarPendente = true;
    presencaWmeDesligar({ repeticao: true });
}

// O carimbo de OUTRA aba segura o teto da repetição só enquanto ela VIVE
// (R9-5-04): a página que o sistema descarta no fundo, sem `pagehide`, leva o
// envio junto — e o carimbo, que só o `pagehide` tirava (`presencaWmeSoltarAoSair`),
// fazia a outra aba e a reabertura esperarem o teto à toa (MEDIDO: a reabertura
// 15 s depois não mandava o "invisível" na chegada do perfil, só no ✕ seguinte,
// 73 s depois do envio morto). Viva é a aba que segura a trava da marca dela
// (`segurarMarcaDaAba`), como a fila de saída confere — e quem diz é o
// navegador, pelo `navigator.locks.query()`, que só LÊ: pegar a trava da outra,
// nem por um instante, podia fazê-la se achar uma cópia e trocar de marca. Sem
// a marca no carimbo (o gravado de antes), sem a trava no navegador ou sem
// resposta, vale o teto, como antes. Uma conferência por vez, e a resposta só
// vale se nenhum envio saiu no meio.
function presencaWmeConferirAbaDoCarimbo(aba) {
    if (typeof aba !== 'string' || !aba || presencaWme.conferindoAba) return;
    let locks = null;
    try { locks = navigator.locks && typeof navigator.locks.query === 'function' ? navigator.locks : null; } catch (e) {}
    if (!locks) return;
    presencaWme.conferindoAba = true;
    const vez = presencaWme.desligarVez;
    Promise.resolve().then(() => locks.query()).then((r) => {
        presencaWme.conferindoAba = false;
        if (!r || !Array.isArray(r.held)) return;
        const nome = MARCA_DA_ABA_TRAVA + aba;
        if (r.held.some((l) => l && l.name === nome)) return;   // viva: o teto vale
        if (vez !== presencaWme.desligarVez) return;
        presencaWmeRefazerDesligar({ abaMorta: aba });
    }).catch(() => { presencaWme.conferindoAba = false; });
}

// Religou à mão: a próxima ação liga a visibilidade de carona, sem esperar o
// freio (quem acabou de pedir pra aparecer não espera 30 s pra aparecer). O
// "invisível" gravado sai junto (quem chama grava as preferências logo depois).
function presencaWmeReligar() {
    presencaWme.desligarPendente = false;
    delete AppState.preferences.presencaWmeDesligar;
    presencaWme.ligarNaProxima = true;
    presencaWme.ultimaEm = 0;
    dfato('presencaWme.visivel', { religou: true, via: 'interruptor' });
}

// A troca de conta e o "Sair". O "invisível" gravado sai da MEMÓRIA aqui, e
// quem chama grava: a troca (`esquecerEscolhasDaContaAnterior`, logo depois) e
// o "Sair" (que já repôs as de fábrica) — o "Sair" de OUTRA aba não grava nada
// no aparelho, e esta função não pode gravar por ele.
function presencaWmeZerar() {
    presencaWme.ligarNaProxima = false;
    presencaWme.desligarPendente = false;
    presencaWme.desligar401Em = null;
    if (AppState.preferences) delete AppState.preferences.presencaWmeDesligar;
    presencaWme.desligarFalhas = 0;
    presencaWme.desligarFalhaAnotada = null;
    presencaWme.desligarFalhaAnotadaEm = 0;
    presencaWme.desligarEm = 0;
    presencaWme.desligarSessao = null;
    presencaWme.desligar401Sessao = null;
    // O envio no ar é da conta que saiu: a resposta dele não decide o gravado de
    // quem entrar, e ele não segura a repetição dela (ver `presencaWmeDesligar`).
    presencaWme.desligarVez = (presencaWme.desligarVez || 0) + 1;
    presencaWme.desligarNoAr = 0;
    presencaWme.ultimaEm = 0;
    presencaWme.enviadas = 0;
    presencaWme.falhas = 0;
    presencaWme.ultimaFalha = null;
    presencaWme.falhaAnotada = null;
    presencaWme.falhaAnotadaEm = 0;
    presencaWme.marcaPerdida = false;
    presencaWme.perfilVisivel = null;
    presencaWme.perfilEm = 0;
}

function presencaWmeDiag() {
    const ligada = typeof presencaLigada === 'function' ? presencaLigada() : AppState.preferences.presenca !== false;
    return {
        ligada,
        ligarNaProxima: presencaWme.ligarNaProxima,
        enviadas: presencaWme.enviadas,
        falhas: presencaWme.falhas,
        ultimaFalha: presencaWme.ultimaFalha,
        marcaPerdida: presencaWme.marcaPerdida,
        ultimaHaS: presencaWme.ultimaEm ? Math.round((Date.now() - presencaWme.ultimaEm) / 1000) : null,
        // O que o `/Session` disse da visibilidade (e há quanto tempo): com o
        // interruptor ligado, `false` aqui vira "ligar na próxima ação".
        perfilVisivel: presencaWme.perfilVisivel,
        perfilHaS: presencaWme.perfilEm ? Math.round((Date.now() - presencaWme.perfilEm) / 1000) : null,
        // O "invisível" do gesto de desligar que ainda não chegou ao WME, e
        // quantas vezes ele falhou (o diário anota só a mudança).
        desligarPendente: presencaWme.desligarPendente || !!AppState.preferences.presencaWmeDesligar,
        desligarFalhas: presencaWme.desligarFalhas || 0,
    };
}

// A decisão POUSOU no Waze (inclusive "já tratado por outro editor", que é o
// objetivo cumprido — a regra de todo o app)?
function pousouNoWaze(r) {
    return !!(r && (r.success || r.errorCategory === 'already_processed' || r.errorCategory === 'not_found'));
}

// A resposta de uma ação EM VOO chegou depois de a sessão acabar (a época
// mudou): nada dela grava (ver `epocaDaSessao`) — mas o +1 que o GESTO já tinha
// GRAVADO no placar ficava, por uma decisão que não pousou no Waze. MEDIDO na
// reprodução do auditor: o ✕ levou 401 depois da queda, "Rejeitados 1" gravado,
// a decisão fora da fila de saída, e o pedido de volta como card quando a mesma
// conta entrou de novo (auditoria da costura, 2026-09-26, K7). É o que o
// `cancel` da queda já faz com a ação que ainda estava na janela. O desconto é
// no placar DO GESTO (o objeto), nunca no `AppState.stats` de agora: o "Sair" e
// a troca de conta põem um NOVO, zerado, e o do gesto fica órfão — descontar
// nele não tira nada de quem entrou.
function descontarGestoSemSessao(chave, placar, n) {
    if (!(n > 0) || !placar) return;
    placar[chave] = Math.max(0, (placar[chave] || 0) - n);
    // O placar do gesto ÓRFÃO (o "Sair", outra conta) não é mais o desta aba nem
    // o do aparelho: o desconto fica no objeto que ficou pra trás, e não há o que
    // desenhar nem gravar. Gravar daqui regravava o placar de AGORA — e, na aba
    // que só soube do "Sair" pela outra, era uma escrita no aparelho depois dele,
    // contra o "não grava nada" (auditoria de 2026-10-01, R5-1 F3).
    if (placar !== AppState.stats) return;
    updateStats();
    saveStats();
}

// A decisão que POUSOU no Waze com a época da sessão já trocada: a queda (com a
// renovação no ar, ou já feita), a conta desta aba em dúvida (R6-1-04), o login
// de novo com a fila refeita. Do que é da SESSÃO nada grava (placar, Histórico,
// conquistas: a regra da época), mas o POUSO é fato do PEDIDO — e era só ele que
// faltava. Sem a prova no aparelho, a fila guardada do offline (tirada antes do
// gesto) devolvia o pedido como card na reabertura sem rede, ou no lie-fi:
// decidido de novo, o Waze recebia a segunda decisão — "Já tratado por outro
// editor" sobre a da própria pessoa, o placar contando duas vezes, e o ✓ seguido
// do ✕ executava os dois, porque ler não resolve o pedido. E a OUTRA aba não
// ficava sabendo pelo canal dos pousos: o card seguia lá, e o ✕ dela ia ao Waze
// (auditoria da rodada 13, R13-2-01 = R13-1-02 = R13-4-01, MEDIDO no navegador
// no ✕/✓ do card, no "Rejeitar os N" e na recusa automática; e R13-2-02, nos
// dois irmãos com a fila refeita: o "Marcar todos" e a aprovação de foto). O
// pouso de depois da troca passa por aqui, com a marca de QUEM decidiu, tirada
// no gesto (`quemDecideAgora`): a memória desta aba pode estar sem sessão (a
// renovação no meio), e é com ela que as outras abas conferem a conta (R12-2-04).
// Os dois irmãos, na fila do GESTO, registram direto (o R12-2-04): a fila de pé
// já prova que nem o "Sair" nem a troca de conta aconteceram — os dois a refazem.
//
// Menos em dois casos, e nos dois não falta a ninguém:
//  · depois do "Sair" sem um login novo (`saiuNestaPagina`): "sair é limpar de
//    tudo", e o pouso devolveria à memória da página (`pousosDaPagina`) o id de
//    um pedido de terceiro, depois da limpeza. As outras abas saem junto, e a
//    fila guardada do offline saiu com o "Sair";
//  · com OUTRA conta nesta aba agora (`contaAgora`, que só diz uma conta
//    confirmada — na renovação no meio ela é desconhecida, e o pouso vale): a
//    fila é dela, e o "lido" é de CADA pessoa — o pouso do "Marcar todos" de
//    quem estava tiraria da busca no ar de quem entrou um pedido que, pra ela,
//    segue não lido. A fila guardada da conta anterior saiu na troca
//    (`esquecerOutraConta`), e as abas dela saem quando outra conta entra.
// `=== true`: os harnesses dos testes devolvem objeto verdadeiro pra nome que
// não conhecem.
function registrarPousoDepoisDaQueda(places, quem) {
    if (saiuNestaPagina === true) return;
    const agora = contaAgora();
    if (agora && !(quem && quem.conta && String(quem.conta) === agora)) return;
    registrarPouso(places, quem);
}

// O ✕/✓ EM VOO cuja resposta chegou depois de a sessão acabar (a época mudou).
// Nada dela grava (ver `epocaDaSessao`), e a anotação dela na fila de saída
// (O2, `anotarAntesDoEnvio`) sai: ela não pode sair depois com a sessão de
// agora, que pode ser de outra pessoa. Se ela não pousou, o +1 do placar do
// gesto volta (K7) — e, na renovação da queda, que mantém a fila na tela, o
// pedido VOLTA como o próximo card (V1, auditoria de 2026-09-29): ele segue
// pendente no Waze e já passou pela fila, então nenhuma busca o trazia, e a
// fila terminava em "Tudo limpo!" com ele pendente. Numa fila refeita (o
// "Sair", outra conta) nada volta — a fila é de outra sessão. A fila que o
// TREINO guardou é a do gesto (a sessão caiu com ele aberto): o pedido volta
// quando ela voltar (ver `Treino.guardarDevolucao`, R7-7-04).
//
// Se ela POUSOU, o pouso é registrado, com a marca de quem decidiu (`quem`,
// tirada no gesto), em qualquer fila (R13-2-01, ver `registrarPousoDepoisDaQueda`).
function decisaoDepoisDaQueda(tipo, place, result, placar, epocaFila, quem) {
    const anotado = anotadoAntesDoEnvio.delete(place);
    if (descargaNaFila.delete(place) || anotado) tirarDaFilaDeSaida(tipo, place);
    if (pousouNoWaze(result)) {
        if (typeof registrarPousoDepoisDaQueda === 'function') registrarPousoDepoisDaQueda(place, quem);
        return;
    }
    descontarGestoSemSessao(tipo === 'read' ? 'read' : 'rejected', placar, 1);
    if (epocaFila === AppState.fetchEpoch
        || (typeof Treino !== 'undefined' && Treino.ativo === true && Treino.filaGuardada(epocaFila))) devolverPedidoRecusado(place, epocaFila);
}

function handleMarkAsRead() {
    if (!AppState.currentPlace) return;
    if (acoesTravadas()) return;   // janela do Desfazer correndo
    if (direcaoTravada('right')) return;   // foto em decisão que não veio (sem rede)
    // Treino ANTES de tudo: nem stat, nem fila, nem rede.
    if (Treino.ativo) return Treino.agir('read');
    // A OUTRA aba já decidiu este pedido: vale a primeira decisão (R10-2-02).
    if (typeof gestoNoDecididoPorOutraAba === 'function' && gestoNoDecididoPorOutraAba('read') === true) return;
    const place = AppState.currentPlace;
    tratouNestaFila = true;
    AppState.stats.read++;
    AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
    updateStats();
    saveStats();
    advanceQueue();
    const epoca = epocaDaSessao;
    const placar = AppState.stats;    // o do GESTO: ver `descontarGestoSemSessao`
    const regiao = API.getRegion();   // a do GESTO: ver `API.markAsRead`
    const pais = paisDaFila();        // o do GESTO: a carona leva o país em que o card estava (R7-6-05)
    const epocaFila = AppState.fetchEpoch;   // a FILA do gesto: ver `devolverPedidoRecusado`
    const gesto = carimboDoGesto();   // o dia e o lugar do GESTO, pro Histórico (R6-7-4)
    // E QUEM decide, pro pouso que chegar depois da queda (R13-2-01, ver `decisaoDepoisDaQueda`).
    const quem = typeof quemDecideAgora === 'function' ? quemDecideAgora() : null;
    scheduleAction('read', place, async () => {
        // Anotada na fila de saída ANTES de sair (O2, ver `anotarAntesDoEnvio`).
        // A decisão deste pedido já esperava lá: vale a primeira, e este gesto
        // não sai nem conta (a mesma regra da descarga).
        if (anotarAntesDoEnvio('read', place, regiao, gesto) === 'repetida') {
            placar.read = Math.max(0, (placar.read || 0) - 1);
            updateStats();
            saveStats();
            // Foi a OUTRA aba, durante a janela do Desfazer (R10-2-02): diz.
            if (typeof avisarDecididoNaOutraAba === 'function') avisarDecididoNaOutraAba(place);
            return;
        }
        const presenca = presencaWmeDaAcao(place, pais);
        const result = await callWithRetry(() => API.markAsRead(place.venueID, place.updateRequestID, presenca, regiao), epoca);
        // Saiu no meio (ver `epocaDaSessao`): nada grava; o placar do gesto
        // volta se a decisão não pousou (K7), e o pedido volta pra fila que
        // atravessou a queda (V1).
        if (epoca !== epocaDaSessao) {
            decisaoDepoisDaQueda('read', place, result, placar, epocaFila, quem);
            return;
        }
        presencaWmeAoResponder(presenca, result);
        handleActionResult('read', place, result, regiao, epocaFila, gesto);
    }, { gesto });
}

function handleReject() {
    if (!AppState.currentPlace) return;
    if (acoesTravadas()) return;   // janela do Desfazer correndo
    if (direcaoTravada('left')) return;   // foto em decisão que não veio (sem rede)
    // Treino ANTES de tudo: nem stat, nem fila, nem rede.
    if (Treino.ativo) return Treino.agir('reject');
    // A OUTRA aba já decidiu este pedido: vale a primeira decisão (R10-2-02).
    if (typeof gestoNoDecididoPorOutraAba === 'function' && gestoNoDecididoPorOutraAba('reject') === true) return;
    const place = AppState.currentPlace;
    tratouNestaFila = true;
    AppState.stats.rejected++;
    AppState.serverTotal = Math.max(0, AppState.serverTotal - 1);
    updateStats();
    saveStats();
    advanceQueue();
    const epoca = epocaDaSessao;
    const placar = AppState.stats;    // o do GESTO: ver `descontarGestoSemSessao`
    const regiao = API.getRegion();   // a do GESTO: ver `API.markAsRead`
    const pais = paisDaFila();        // o do GESTO: a carona leva o país em que o card estava (R7-6-05)
    const epocaFila = AppState.fetchEpoch;   // a FILA do gesto: ver `devolverPedidoRecusado`
    const gesto = carimboDoGesto();   // o dia e o lugar do GESTO, pro Histórico (R6-7-4)
    // E QUEM decide, pro pouso que chegar depois da queda (R13-2-01, ver `decisaoDepoisDaQueda`).
    const quem = typeof quemDecideAgora === 'function' ? quemDecideAgora() : null;
    scheduleAction('reject', place, async () => {
        // Anotada na fila de saída ANTES de sair (O2, ver `anotarAntesDoEnvio`).
        // A decisão deste pedido já esperava lá: vale a primeira, e este gesto
        // não sai nem conta (a mesma regra da descarga).
        if (anotarAntesDoEnvio('reject', place, regiao, gesto) === 'repetida') {
            placar.rejected = Math.max(0, (placar.rejected || 0) - 1);
            updateStats();
            saveStats();
            // Foi a OUTRA aba, durante a janela do Desfazer (R10-2-02): diz.
            if (typeof avisarDecididoNaOutraAba === 'function') avisarDecididoNaOutraAba(place);
            return;
        }
        const presenca = presencaWmeDaAcao(place, pais);
        const result = await callWithRetry(() => API.rejectPlace(place.venueID, place.updateRequestID, presenca, regiao), epoca);
        // Saiu no meio (ver `epocaDaSessao`): nada grava; o placar do gesto
        // volta se a decisão não pousou (K7), e o pedido volta pra fila que
        // atravessou a queda (V1).
        if (epoca !== epocaDaSessao) {
            decisaoDepoisDaQueda('reject', place, result, placar, epocaFila, quem);
            return;
        }
        presencaWmeAoResponder(presenca, result);
        handleActionResult('reject', place, result, regiao, epocaFila, gesto);
    }, { gesto });
}

// ── O que o APP estrelou ("Pular guarda o pedido"), no aparelho ────────────
// O `isStarred` que a busca traz é o do MOMENTO da busca, e cada aba tem a sua.
// Com o app aberto em duas abas, a B carregou a fila antes de a A pular o
// pedido: o ↑ na B mandava OUTRA estrela e contava de novo no "Colecionador" —
// MEDIDO: duas estrelas e `guardados: 2` com um pedido só, o mesmo defeito do
// R9-7-06 por outro caminho (auditoria de 2026-10-07, R10-2-05). A fila
// guardada do offline traz o `isStarred` da hora da busca dela, pelo mesmo
// motivo. Daqui, o aparelho lembra as CHAVES (`chaveDoPedido`) dos pedidos que
// o app estrelou com sucesso: o ↑ confere no gesto (e de novo no fim da janela
// do Desfazer, onde a estrela da outra aba pode ter pousado), e o
// "Colecionador" conta pedido DISTINTO — a estrela só conta se a chave entrou
// agora.
//
// Teto POR CONSTRUÇÃO (a regra da casa pra estrutura que cresce por item): o
// mais velho sai. 500 chaves são ~22 KB, lidas no ↑ (1,1% das ações, MEDIDO na
// fila do owner) e gravadas só quando a estrela pousa; é bem mais que o tempo
// em que uma aba esquecida aberta ou a fila guardada seguem com o dado velho.
// O custo assumido: tirar a estrela no WME não tira a chave daqui — o ↑ do
// mesmo pedido não manda outra até ela sair do anel.
//
// São ids de pedidos de TERCEIROS e estado do EDITOR sobre eles: saem no
// "Sair" (`handleLogout`) e na troca de conta (`esquecerOutraConta`).
const ESTRELADOS_KEY = 'waze_places_estrelados';
const ESTRELADOS_MAX = 500;

function estreladosNoAparelho() {
    try {
        const v = JSON.parse(safeLS.get(ESTRELADOS_KEY) || '[]');
        return Array.isArray(v) ? v.filter((k) => typeof k === 'string') : [];
    } catch (e) { return []; }
}

// O app JÁ estrelou este pedido (nesta aba ou noutra)?
function estreladoPeloApp(place) {
    const k = chaveDoPedido(place);
    return !!k && estreladosNoAparelho().includes(k);
}

// A estrela POUSOU: a chave entra no anel. Devolve se ela entrou AGORA — é o
// "pedido distinto" do "Colecionador" (duas abas pulando o mesmo pedido no
// mesmo instante mandam duas estrelas, e só a primeira a pousar conta).
function anotarEstreladoPeloApp(place) {
    const k = chaveDoPedido(place);
    if (!k) return false;
    const lista = estreladosNoAparelho();
    if (lista.includes(k)) return false;
    lista.push(k);
    while (lista.length > ESTRELADOS_MAX) lista.shift();
    safeLS.set(ESTRELADOS_KEY, JSON.stringify(lista));
    return true;
}

function handleSkip() {
    if (!AppState.currentPlace) return;
    if (acoesTravadas()) return;   // janela do Desfazer correndo
    // Treino ANTES de tudo: nem stat, nem fila, nem rede.
    if (Treino.ativo) return Treino.agir('skip');
    // A OUTRA aba já decidiu este pedido: vale a primeira decisão (R10-2-02).
    if (typeof gestoNoDecididoPorOutraAba === 'function' && gestoNoDecididoPorOutraAba('skip') === true) return;
    const place = AppState.currentPlace;
    AppState.stats.skipped++;
    updateStats();
    saveStats();
    advanceQueue();
    // A decisão é do MOMENTO DO GESTO, não do despacho: o executor roda até
    // UNDO_WINDOW_MS depois, e nesse intervalo dá pra abrir Filtros e mexer no
    // interruptor. Quem pulou com a preferência ligada quis guardar aquele
    // pedido; mudar de ideia sobre o recurso não reescreve o que já foi feito.
    //
    // E o pedido que JÁ tem a estrela (o `isStarred` que a busca traz, a ⭐ do
    // card) não ganha outra: ela não muda nada no Waze, gasta uma requisição e
    // contava de novo no "Colecionador" — o mesmo pedido pulado dez vezes dava
    // a conquista (MEDIDO: 2 estrelas e `guardados: 2` com um pedido só;
    // auditoria de 2026-10-06, R9-7-06). O ↑ segue sendo pular. O que o APP já
    // estrelou, nesta aba ou noutra, é conferido no executor (R10-2-05).
    const guardar = AppState.preferences.pularGuarda === true && place.isStarred !== true;
    // Sem a preferência, o Pular continua sendo o que sempre foi: REDE ZERO.
    // O place segue pendente no Waze e o executor é no-op — o scheduleAction
    // está aqui só pela janela do Desfazer. Com a preferência, o mesmo executor
    // passa a guardar o pedido na estrela do editor, e o Desfazer segue valendo
    // de graça: desfazer é não rodar o executor.
    const epoca = epocaDaSessao;
    const epocaFila = AppState.fetchEpoch;   // a FILA do gesto: ver a queda, abaixo
    const regiao = API.getRegion();   // a do GESTO: ver `API.markAsRead`
    scheduleAction('skip', place, async () => {
        if (!guardar) return;
        if (!place || !place.venueID || !place.updateRequestID) return;
        // O que o APP já estrelou, nesta aba ou noutra (`estreladoPeloApp`,
        // R10-2-05): o `isStarred` desta aba pode ser de antes da estrela. A
        // conferência é AQUI, na hora de mandar — no gesto sem o Desfazer, no
        // fim da janela com ele —, e não no gesto: a estrela da outra aba pode
        // pousar durante a janela, e o anel só cresce até lá.
        if (estreladoPeloApp(place) === true) return;
        const enviar = () => API.guardarPedido(place.venueID, place.updateRequestID, true, regiao);
        let r = await callWithRetry(enviar, epoca);
        // Um 401 NÃO é prova de sessão morta (gotcha #42), e aqui ele virava
        // "Sessão expirada" sem conferir nada — o ✕ com o mesmo 401 confere a
        // sessão e manda de novo (auditoria do card, 2026-09-29, C7). A estrela
        // não tem fila de saída, então passa pela conferência das escritas que
        // moram fora dela (`refazerDepoisDo401`): com a sessão confirmada viva,
        // ela sai de novo UMA vez.
        if (epoca === epocaDaSessao && r && r.errorCategory === 'unauthorized') {
            r = await refazerDepoisDo401(epoca, enviar);
        }
        // A sessão ACABOU com a estrela no ar (ver `epocaDaSessao`): nada grava.
        // Mas a estrela que não chegou se perdia CALADA — "quem avisa é a queda",
        // e com a extensão renovando a queda diz "Acesso renovado… sua fila
        // continua aqui", com o pedido pulado fora da tela e sem a estrela, que
        // não é mandada de novo (MEDIDO, s46; auditoria de 2026-10-02, R6-2-08).
        // Avisa com a fila do gesto ainda na tela (a renovação, ou a queda antes
        // da tela de entrada), como as escritas do lightbox
        // (`escritaDoLightboxSemSessao`). Depois do "Sair" (ou com outra conta) a
        // fila foi embora, e não há a quem avisar. Não manda de novo: sem a conta
        // do gesto, seria a escrita de A com a sessão de B (K1).
        if (epoca !== epocaDaSessao) {
            if (!(r && r.success === true) && epocaFila === AppState.fetchEpoch) showToast(t('toast.guardarFalhou'), 'error');
            return;
        }
        // Falhar aqui não corrompe contador nenhum — o Pular não mexe em
        // `serverTotal` e o `skipped` já subiu —, então não há o que reverter.
        // O que não pode é falhar CALADO: o app prometeu guardar. E o aviso diz
        // QUE a estrela falhou, com o motivo de COMPLEMENTO: era o motivo
        // sozinho ("Erro de conexão", "Servidor Waze indisponível") que ganhava,
        // ~3 s depois do ↑, com o pedido já fora da tela — nada o ligava à
        // estrela (MEDIDO, s37; R6-2-09). O " · " é o separador do app (o
        // resultado do lote junta as linhas assim).
        if (!r || r.success !== true) {
            const motivo = r ? msgDoServidor(r) : null;
            showToast(t('toast.guardarFalhou') + (motivo ? ' · ' + motivo : ''), 'error');
            return;
        }
        // O "Colecionador" conta pedido DISTINTO (R10-2-05): a estrela que a
        // outra aba pousou antes desta não conta de novo.
        if (anotarEstreladoPeloApp(place)) contarConquista('guardados');
    });
}

// ── Marcar em lote (o backend já aceita items[]; feature de UI) ────────────
// Marca como lido TODOS os places atualmente na fila local. Como o Waze devolve
// tudo de uma vez (hasMore geralmente false), a fila local ≈ tudo que resta.
// Os pedidos que o diálogo CONTOU ao abrir. Marcar como lido não tem Desfazer,
// e a releitura da fila pode pousar com o diálogo aberto (ela sai justamente
// quando sobram poucos cards): sem isto, o confirmar marcava centenas de
// pedidos que a pessoa nunca viu, sob um "Marcar os 3" na tela.
let loteDeLidosContado = null;
// O lote NO AR. Entra no `acoesTravadas()`: enquanto ele está no ar, ✕ ↑ ✓, o
// gesto, o teclado, o "Rejeitar os N" do autor e um SEGUNDO lote esperam — os
// pedidos dele seguem na fila até a resposta, e qualquer outra decisão sobre
// eles seria a segunda (MEDIDO: 8 lidos + 1 rejeitado pra 8 pedidos; e o lote
// repetido contava o placar em dobro).
let loteDeLidosEmVoo = false;
// Pedidos por requisição. O Waze processa o lote EM ORDEM e PARA no primeiro
// pedido que outro editor já resolveu — MEDIDO em 2026-09-25 com a conta L2:
// [real, inexistente, real] → HTTP 500, código 300, com o PRIMEIRO marcado e o
// terceiro não. Ele não diz qual falhou, então o pedaço que falha vai um a um:
// em pedaços, uma divergência custa um pedaço, não a fila inteira.
const LOTE_LIDOS_PEDACO = 25;

function openBatchReadConfirm() {
    // Sem sessão o lote não sai — e saía CALADO: durante a renovação pela
    // extensão (até 8 s, com os Filtros abertos), o diálogo contava, o toque
    // dizia "Marcando 3 como lidos…", o `api.js` devolvia "sem sessão" sem ir à
    // rede e o `handleUnauthorized` voltava na hora (já sem sessão). Depois vinha
    // "Acesso renovado… sua fila continua aqui", com os pedidos pendentes, e a
    // pessoa achando que tinha marcado (auditoria de 2026-10-02, R6-2-01). É a
    // guarda do "Rejeitar os N" (`rejeitarLoteDoAutor`), com o mesmo aviso: na
    // renovação, o da espera da sessão; fora dela, "Sessão expirada".
    //
    // E o lote segue a trava do CARD, menos a janela do Desfazer (que ele
    // despacha): um lote por vez (os pedidos do primeiro ainda estão na fila e o
    // diálogo contaria os MESMOS de novo), a conferência de um 401 e a conta
    // desta aba em DÚVIDA — com ela, o card travava e o lote marcava a fila
    // inteira no aparelho de outra conta (R7-2-02). Ver a função.
    if (acoesTravadasForaDaJanela()) { showToast(t(avisoDaTrava()), 'info'); return; }
    // Marcar o LOTE também escreve. No treino a fila é de exemplos: deixar o
    // botão vivo mandaria um lote de ids inertes ao Waze — sem efeito, mas é
    // requisição que ninguém pediu, e o aviso mente sobre o que aconteceu.
    if (Treino.ativo) { showToast(t('treino.semLote'), 'info'); return; }
    // O pedido EM ANDAMENTO fica de fora (`pedidosEmAndamento`): a aprovação de
    // foto no ar deixa o card na fila até a resposta, e o lote o levava junto —
    // uma SEGUNDA decisão sobre o mesmo pedido, contada no placar (MEDIDO: o
    // diálogo dizia 3 com 2 pedidos a decidir; auditoria de 2026-09-29, V7). É a
    // mesma régua da recusa automática.
    //
    // E o que JÁ FOI LIDO também (`isRead`, a faixa "já lido" do card), que só
    // vem com "Apenas pedidos não lidos" desmarcado: o diálogo dizia "os 5",
    // mandava os 5, avisava "5 pedidos marcados" e somava 5 no placar e no
    // Histórico, com 3 deles já lidos (MEDIDO no navegador; auditoria de
    // 2026-10-07, R10-2-04). Fica na fila como card — segue pendente no Waze,
    // pra ser rejeitado ou pulado. Sobrando nenhum, é a fila sem o que marcar
    // ("Nada na fila para marcar"), e a frase do diálogo diz "não lidos" quando
    // a fila tem os dois, pro número bater com o que a pessoa vê.
    //
    // E o card que a OUTRA aba já decidiu (R10-2-02): a decisão de lá é a que
    // vale, e o lote o levava junto — o mesmo pedido lido aqui e decidido lá, e
    // contado de novo no placar (MEDIDO no navegador, q07c do lote 14). Os de
    // trás já saíram da fila no aviso da outra aba; sobra o da tela, que fica.
    loteDeLidosContado = AppState.queue.filter((p) => p.venueID && p.updateRequestID && p.isRead !== true
        && !pedidosEmAndamento.has(chaveDoPedido(p))
        && !(typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(p) === true)).map(chaveDoPedido);
    const n = loteDeLidosContado.length;
    if (n === 0) { showToast(t('toast.batchEmpty'), 'info'); return; }
    const comJaLidos = AppState.queue.some((p) => p && p.isRead === true);
    const msgEl = document.getElementById('batchReadMessage');
    if (msgEl) {
        msgEl.textContent = comJaLidos
            ? t(n === 1 ? 'modal.batchRead.bodyNaoLidos' : 'modal.batchRead.bodyNaoLidosPlural', { n })
            : t(n === 1 ? 'modal.batchRead.body' : 'modal.batchRead.bodyPlural', { n });
    }
    openModal('batchReadModal');
}

async function handleBatchMarkRead() {
    closeModal('batchReadModal');
    // Só o que o diálogo CONTOU e segue na fila (ver `loteDeLidosContado`).
    const contados = new Set(loteDeLidosContado || []);
    loteDeLidosContado = null;
    // A sessão caiu com o diálogo ABERTO (a renovação pela extensão): o lote não
    // sai, e o diálogo já fechou com o toque — diz por quê (R6-2-01, ver o
    // `openBatchReadConfirm`). Antes do "Marcando N…", que mentiria. O mesmo
    // com o resto da trava do card que pode acender com o diálogo aberto (a conta
    // desta aba em dúvida, R7-2-02; a conferência de um 401).
    if (acoesTravadasForaDaJanela()) { showToast(t(avisoDaTrava()), 'info'); return; }
    // E o que entrou em andamento com o diálogo aberto também fica de fora (V7).
    // (O já lido nem foi contado: ver o `openBatchReadConfirm`, R10-2-04.)
    // E o que a outra aba decidiu com o diálogo aberto (R10-2-02).
    const alvos = AppState.queue.filter((p) => p.venueID && p.updateRequestID && contados.has(chaveDoPedido(p))
        && !pedidosEmAndamento.has(chaveDoPedido(p))
        && !(typeof decididosPorOutraAbaComCardAqui !== 'undefined' && decididosPorOutraAbaComCardAqui.has(p) === true));
    if (alvos.length === 0) { showToast(t('toast.batchEmpty'), 'info'); return; }
    // Descarrega qualquer undo pendente antes (consistência de estado) — o do
    // card E os das ações de FOTO, que dividem o mesmo banner: o
    // `removeUndoBanner` logo abaixo deixaria a janela delas correndo sem o
    // botão de desfazer, e a aprovação é uma decisão sobre um pedido do lote.
    if (AppState.pendingAction) { AppState.pendingAction.execute(); AppState.pendingAction = null; }
    if (aprovacaoPendente) aprovacaoPendente.enviar();
    if (exclusaoPendente) exclusaoPendente.enviar();
    if (renomeacaoPendente) renomeacaoPendente.enviar();
    removeUndoBanner();
    const epoca = epocaDaSessao;
    const epocaFila = AppState.fetchEpoch;   // a FILA do gesto: ver o fim (V9)
    const regiao = API.getRegion();   // a do GESTO: ver `API.markAsRead`
    // O dia e o lugar do GESTO (`carimboDoGesto`): o lote anda em pedaços, e os
    // Filtros seguem alcançáveis com ele no ar (R6-7-4).
    const gesto = carimboDoGesto();
    // E QUEM decide, pro aviso às outras abas do que pousar depois da queda (R12-2-04).
    const quem = typeof quemDecideAgora === 'function' ? quemDecideAgora() : null;
    const itens = (ps) => ps.map((p) => ({ venueID: p.venueID, updateRequestID: p.updateRequestID }));
    // No ar: trava as outras decisões e tira os pedidos das buscas que chegarem
    // no meio (`semOsJaDecididos`) — o ↻ trazia de volta, como card, o que o
    // lote já tinha marcado. Sai no `finally`, em QUALQUER desfecho.
    loteDeLidosEmVoo = true;
    marcarEmAndamento(alvos, true);
    aplicarTravaDeAcao();
    AppState.inFlightActions++;
    updateInFlightIndicator();
    showToast(t(alvos.length === 1 ? 'toast.batchMarking' : 'toast.batchMarkingPlural', { n: alvos.length }), 'info');
    const feitos = [];   // lidos agora, ou já resolvidos por outro editor: saem da fila
    // Os que a APROVAÇÃO desta pessoa já tinha resolvido, com a resposta perdida
    // (R8-2-01, ver `aprovacaoDelaJaPousou`): saem da fila e do "Restam" como os
    // `feitos`, mas não são lidos — nem no placar, nem no Histórico, nem no aviso.
    const aprovadas = [];
    let falhou = null;
    // A sessão trocou no meio (ver `epocaDaSessao`): o laço PARA e nada mais
    // sai. `posQueda`: o que a resposta que chegou DEPOIS da troca diz que o
    // Waze marcou — vai sair da fila junto com os `feitos` (ver o fim).
    let sessaoTrocou = false;
    const posQueda = [];
    // O 401 NÃO prova sessão morta (gotcha #42), e o lote que o levava não
    // marcava, não mandava de novo e não dizia — "Marcando 3 como lidos…" e só
    // "Conexão instável — sua sessão continua válida", com os 3 pendentes
    // (auditoria de 2026-10-06, R8-2-04, MEDIDO nos dois motores). O lote não
    // tem fila de saída: o 401 passa pela conferência das escritas que moram
    // fora dela (`refazerDepoisDo401`, a do "Pular guarda" e a do lightbox) e,
    // com a sessão confirmada VIVA, o que o levou sai de novo — UMA vez por
    // lote; o resto segue o laço. O 401 que fica é o que não se refaz (a sessão
    // não se confirmou, ou a 2ª ida levou outro) e o de um pedaço SEGUINTE, que
    // chega depois de a sessão ter sido confirmada viva neste lote: aí é a
    // escrita que o Waze recusa, não a sessão (o critério do `u401` da fila de
    // saída), e conferir de novo seria outra sonda e outro "conexão instável".
    // O lote para e avisa (lá embaixo).
    let refez = false;
    const mandar = async (enviar) => {
        const r = await callWithRetry(enviar);
        if (refez || epoca !== epocaDaSessao || !(r && r.errorCategory === 'unauthorized')) return r;
        refez = true;
        return (await refazerDepoisDo401(epoca, enviar)) || r;
    };
    // O que o Waze marcou CONTA NA HORA, a cada pedaço (e a cada pedido do um a
    // um) que pousa: placar, Histórico e conquistas, como o ✓ de um card conta.
    // Somado só no fim do laço, fechar o app no meio deixava fora do placar e do
    // Histórico o que o Waze JÁ tinha marcado, com a resposta recebida e o pouso
    // registrado — o pedido não volta como card, e nada na tela dizia que o
    // trabalho foi feito (MEDIDO no navegador: lote de 60, o 1º pedaço pousa e a
    // página fecha — reaberta, Lidos 40 e Histórico 0, com 50 marcados no Waze;
    // auditoria de 2026-10-07, R10-2-03). Conta na sessão da RESPOSTA, como o
    // card: o que pousou antes de uma queda conta, o que chega depois não (o
    // `sessaoTrocou`, abaixo). O aviso "N marcados" segue um só, no fim.
    //
    // E o "Restam" desce JUNTO, pelo mesmo pedaço (R11-2-05): o placar subia a
    // cada pedaço e o "Restam" só descia no fim do laço, então no meio o que o
    // Waze já marcou contava nos DOIS números (MEDIDO no navegador: lote de 60, o
    // 1º pedaço pousado — "Lidos 65" e "Restam 60", 125 de 100; auditoria de
    // 2026-10-07). Só na fila do GESTO (`epocaFila`), a régua do fim: a fila
    // refeita no meio (↻, filtro) tem o "Restam" dela, que não conta estes
    // pedidos. Eles seguem NA FILA até o fim do lote, o card da frente inclusive
    // (o "Restam" é o `serverTotal`, não o tamanho da fila), e o fim desconta só
    // o que não desceu aqui (`descontados`).
    const descontados = new Set();
    const contarLidos = (ps) => {
        const n = ps.length;
        AppState.stats.read += n;
        recordHistory('read', n, gesto.dia, gesto.onde);
        registrarLoteConfirmado(n, gesto);
        updateStats();
        saveStats();
        if (epocaFila !== AppState.fetchEpoch) return;
        for (const p of ps) descontados.add(chaveDoPedido(p));
        AppState.serverTotal = Math.max(0, AppState.serverTotal - n);
        updatePendingCount();
    };
    // O que a OUTRA aba decidiu COM O LOTE NO AR (R11-2-02). Os alvos deixam de
    // fora o anotado uma vez só, no começo (a junção do R10-2-02), e o lote
    // mandava depois o que a pessoa decidiu na outra aba no meio dele, e o
    // contava como lido — por cima da rejeição de lá, ou lido duas vezes
    // (MEDIDO no navegador: lote de 30, a outra aba rejeita o 28º com o 1º
    // pedaço no ar — Histórico 31 pra 30 pedidos, e "30 marcados"; auditoria de
    // 2026-10-07). Cada pedaço, e cada pedido do um a um, pergunta de novo antes
    // de sair; e o "já tratado" de um anotado no meio da ida é a decisão de lá
    // (`pousouPorOutraAba`), sem contar. Vale a primeira decisão. Eles saem da
    // fila no fim (`daOutraAba`, lá embaixo), como sairiam no aviso da outra aba
    // se não estivessem em andamento aqui (`tirarDaFilaOQueAOutraAbaDecidiu`).
    //
    // E a pergunta vale pra CADA IDA, não só pra primeira (R12-2-03): o pedaço
    // (ou o pedido do um a um) que leva 401 sai de novo depois da conferência da
    // sessão (`refazerDepoisDo401`, uma sonda inteira — segundos), e a ida da
    // rede que falhou é retentada (`callWithRetry`). O reenvio levava o pedaço
    // montado ANTES da espera: o pedido que a outra aba decidiu nesse meio ia ao
    // Waze e contava como lido (MEDIDO no navegador: lote de 30, o 2º pedaço leva
    // 401, a outra aba rejeita o 28º durante a sonda — o reenvio leva os 5,
    // "Lidos 30 + Rejeitados 1" pra 30 pedidos e "30 marcados"; auditoria de
    // 2026-10-07, rodada 12). O que vai é montado NA HORA de cada ida (`enviar`),
    // e o que foi na que valeu é o que pousa e conta. Sobrando nada, não sai
    // nada (`{ success: true }` sem pedido: nada pousa, nada conta).
    const decididoNaOutraAba = (p) => typeof decididosPorOutraAbaComCardAqui !== 'undefined'
        && decididosPorOutraAbaComCardAqui.has(p) === true;
    try {
        for (let i = 0; i < alvos.length && !falhou && !sessaoTrocou; i += LOTE_LIDOS_PEDACO) {
            const doPedaco = alvos.slice(i, i + LOTE_LIDOS_PEDACO);
            let pedaco = doPedaco.filter((p) => !decididoNaOutraAba(p));
            if (!pedaco.length) continue;
            const r = await mandar(() => {
                pedaco = doPedaco.filter((p) => !decididoNaOutraAba(p));
                return pedaco.length ? API.markAsReadBatch(itens(pedaco), regiao) : { success: true };
            });
            if (epoca !== epocaDaSessao) {
                sessaoTrocou = true;
                if (r && r.success) posQueda.push(...pedaco);
                break;
            }
            // O pouso é registrado A CADA PEDAÇO, não no fim do laço: fechar o
            // app no meio de um lote de 60 deixava os 25 que o Waze já marcou sem
            // pouso, e a reabertura sem rede os devolvia como card — dava pra
            // decidi-los de novo (MEDIDO: 25 de volta; auditoria de 2026-09-29, O4).
            // E conta junto (R10-2-03, ver `contarLidos`), DEPOIS do pouso: se a
            // conta quebrar, o pedido não volta por causa disso.
            if (r && r.success) {
                if (pedaco.length) { feitos.push(...pedaco); registrarPouso(pedaco); contarLidos(pedaco); }
                continue;
            }
            if (r && r.errorCategory === 'unauthorized') { falhou = r; break; }
            if (!(r && (r.errorCategory === 'already_processed' || r.errorCategory === 'not_found'))) { falhou = r || {}; break; }
            // Um do pedaço já estava resolvido e o Waze parou nele: um a um.
            for (const p of pedaco) {
                // A outra aba pode ter decidido enquanto o pedaço ia (R11-2-02).
                if (decididoNaOutraAba(p)) continue;
                // E a cada ida deste pedido, como a do pedaço (R12-2-03): `saiu`
                // diz se a que valeu foi mesmo ao Waze.
                let saiu = true;
                const r1 = await mandar(() => {
                    saiu = !decididoNaOutraAba(p);
                    return saiu ? API.markAsRead(p.venueID, p.updateRequestID, null, regiao) : { success: true };
                });
                if (epoca !== epocaDaSessao) {
                    sessaoTrocou = true;
                    if (saiu && r1 && (r1.success || r1.errorCategory === 'already_processed' || r1.errorCategory === 'not_found')) posQueda.push(p);
                    break;
                }
                // A outra aba o decidiu antes de ele sair de novo: a decisão de lá
                // vale, e ele sai da fila no fim (`daOutraAba`).
                if (!saiu) continue;
                if (r1 && (r1.success || r1.errorCategory === 'already_processed' || r1.errorCategory === 'not_found')) {
                    // O "já tratado" de um pedido que a outra aba decidiu enquanto
                    // ele ia é a decisão de lá, já contada lá (R11-2-02).
                    if (!r1.success && decididoNaOutraAba(p)) { pousouPorOutraAba(p, 'read'); continue; }
                    registrarPouso(p);
                    // O "já tratado" de um pedido cuja aprovação desta pessoa
                    // pousou sem resposta é a aprovação DELA (R8-2-01): o
                    // "Curador", e nenhum lido — este lote conta ao pousar, então
                    // o placar dele nem subiu (`desfechoDaAprovacaoDela` sem
                    // `contado`). Na hora, como o lido (R10-2-03).
                    if (!r1.success && aprovacaoDelaJaPousou(p)) { aprovadas.push(p); desfechoDaAprovacaoDela('read', p, false); }
                    else { feitos.push(p); contarLidos([p]); }
                }
                else if (r1 && r1.errorCategory === 'unauthorized') { falhou = r1; break; }
                else { falhou = r1 || {}; break; }
            }
        }
    } catch (e) {
        falhou = {};
    } finally {
        // Só o lote DESTA sessão solta a trava: a queda e o "Sair" já a soltaram
        // (ver `loteDeLidosEmVoo`), e um lote velho que voltar depois não pode
        // soltar o que um lote da sessão nova travou.
        if (epoca === epocaDaSessao) loteDeLidosEmVoo = false;
        marcarEmAndamento(alvos, false);
        AppState.inFlightActions = Math.max(0, AppState.inFlightActions - 1);
        updateInFlightIndicator();
        aplicarTravaDeAcao();
    }
    // Sai da fila o que ESTÁ nela, pela chave, e o "Restam" desce pelo que de
    // fato SAIU — nunca por quantos o lote marcou. É isso que amarra o desconto
    // à fila do gesto: o ↻ e a troca de filtro no meio do lote refazem a fila
    // (`fetchEpoch`), e a nova já vem sem estes pedidos (eles estavam em
    // andamento), então nada sai dela e nada é descontado — antes o "Restam" da
    // fila nova descia pelos pedidos da velha. E uma aprovação de foto que pousou
    // no meio já tirou o pedido dela e descontou sozinha. O que já desceu pedaço
    // a pedaço (`descontados`, R11-2-05) não desce de novo. `saiuDaFila`: a fila
    // mudou por baixo do card que fica (R11-2-04, lá embaixo).
    let saiuDaFila = 0;
    const tirarDaFilaNoFim = (ps) => {
        const fora = new Set(ps.map(chaveDoPedido));
        const saem = AppState.queue.filter((p) => fora.has(chaveDoPedido(p)));
        if (!saem.length) return;
        AppState.queue = AppState.queue.filter((p) => !fora.has(chaveDoPedido(p)));
        AppState.serverTotal = Math.max(0, AppState.serverTotal - saem.filter((p) => !descontados.has(chaveDoPedido(p))).length);
        saiuDaFila += saem.length;
    };
    // O que a OUTRA aba decidiu enquanto estava em andamento aqui (R11-2-02): o
    // que o lote deixou de fora, o que ele nem alcançou (parou numa falha) e o
    // "já tratado" de lá. Sai da fila, menos o card da TELA, que fica — trocar o
    // card debaixo do dedo é pior que um gesto a mais, e o gesto nele diz por quê
    // (`gestoNoDecididoPorOutraAba`): a régua do aviso da outra aba.
    const daOutraAba = alvos.filter(decididoNaOutraAba);
    const daOutraAbaForaDaTela = () => daOutraAba.filter((p) => p !== AppState.currentPlace);
    // A sessão TROCOU no meio do lote: nada MAIS grava — placar, Histórico,
    // avisos —, porque a resposta é da sessão que acabou (ver `epocaDaSessao`); o
    // que pousou ANTES da queda já contou na hora, na sessão dele (R10-2-03). Mas na
    // renovação da queda com a MESMA conta a fila ATRAVESSOU a queda
    // (`epocaFila === AppState.fetchEpoch`), e o que o Waze já marcou seguia nela
    // como card: decidível de novo, com o "Restam" contando. MEDIDO (s15): lote
    // de 60, o 1º pedaço pousa, a sessão cai e renova — a fila seguia com os 60
    // cards, 25 já marcados no Waze. Agora o que pousou (os `feitos` e o pedaço
    // cuja resposta pousou depois da queda) sai da fila pela chave, o "Restam"
    // desce pelo que saiu, e o fim da função refaz o card da frente. Com OUTRA
    // conta (ou o "Sair") a fila foi refeita, e não há o que tirar.
    //
    // E o que NÃO saiu diz que não saiu (R8-2-04): a queda cortava o lote calada,
    // e a renovação dizia "sua fila continua aqui" com os pedidos pendentes — a
    // pessoa achando que tinha marcado. Só com a fila do gesto na tela (a
    // renovação, ou a queda antes da tela de entrada), como a estrela do "Pular
    // guarda" que a queda pega no ar (R6-2-08). Nada mais é dito nem contado.
    let naoSaiuNaQueda = false;
    if (sessaoTrocou) {
        // A fila REFEITA (a pessoa entrou de novo, ou outra conta entrou): nada
        // dela é deste lote — mas o pouso do que pousou depois da queda vale,
        // pela régua de depois da queda (o "Sair" e a outra conta não gravam).
        // Saía antes de registrar, e com a MESMA conta entrando de novo a outra
        // aba seguia com os pedidos como card — o ✕ de lá ia ao Waze, lido e
        // rejeitado (R13-2-02, MEDIDO no navegador; ver `registrarPousoDepoisDaQueda`).
        if (epocaFila !== AppState.fetchEpoch) {
            if (posQueda.length && typeof registrarPousoDepoisDaQueda === 'function') registrarPousoDepoisDaQueda(posQueda, quem);
            return;
        }
        // O pouso do que pousou depois da queda (o de antes já foi registrado a
        // cada pedaço): é a mesma conta, e a fila guardada do offline não pode
        // devolvê-los como card. Com a marca de quem DECIDIU: sem sessão na
        // memória (a renovação no meio), o aviso às outras abas não saía (R12-2-04).
        if (posQueda.length) registrarPouso(posQueda, quem);
        tirarDaFilaNoFim([...feitos, ...aprovadas, ...posQueda, ...daOutraAbaForaDaTela()]);
        // O que a outra aba decidiu não é "o que não saiu": está decidido.
        const resolvidos = new Set([...feitos, ...aprovadas, ...posQueda, ...daOutraAba].map(chaveDoPedido));
        naoSaiuNaQueda = alvos.some((p) => !resolvidos.has(chaveDoPedido(p)));
        // Daqui pra baixo, só a TELA: nada a contar.
        feitos.length = 0;
        aprovadas.length = 0;
        daOutraAba.length = 0;
        falhou = null;
    }
    if (feitos.length || aprovadas.length || daOutraAba.length) {
        // O que saiu conta como o ✓ de um card conta: placar, Histórico e
        // conquistas. Antes o lote subia só o placar, e o Histórico, o Resumo do
        // mês e a patente discordavam dele. O pouso E a conta já foram feitos a
        // cada pedaço, lá no laço (O4, R10-2-03): aqui fica a fila e o aviso.
        // O que a outra aba decidiu também é trabalho dela nesta fila, como no
        // gesto (`gestoNoDecididoPorOutraAba`), e não entra no aviso.
        tratouNestaFila = true;
        tirarDaFilaNoFim([...feitos, ...aprovadas, ...daOutraAbaForaDaTela()]);
        updateStats();
        saveStats();
        if (feitos.length) showToast(t(feitos.length === 1 ? 'toast.batchDone' : 'toast.batchDonePlural', { n: feitos.length }), 'success');
    }
    // O lote que NÃO saiu avisa — também pelo 401 que não se refez (a sessão não
    // se confirmou viva, ou a 2ª ida levou outro 401) e pela queda (acima), os
    // dois desfechos que eram calados (R8-2-04). A frase é a do lote
    // (`toast.batchError`): a do servidor diria "sessão expirada" de uma sessão
    // que pode estar viva, e o "espere a conferência e toque de novo" só é
    // verdade enquanto ela corre — depois da queda sem a extensão, o que vem é a
    // tela de entrada.
    if (falhou) showToast(falhou.errorCategory === 'unauthorized' ? t('toast.batchError') : msgDoServidor(falhou, t('toast.batchError')), 'error');
    else if (naoSaiuNaQueda) showToast(t('toast.batchError'), 'error');
    // O que o lote NÃO marcou segue pendente no Waze. Na mesma fila ele nunca
    // saiu dela (o lote trava as outras decisões). Numa fila REFEITA no meio (↻,
    // filtro) ele não entrou — estava em andamento —, e ninguém o trazia: a fila
    // terminava em "Tudo limpo! … Confira o país" com os pedidos pendentes
    // (auditoria de 2026-09-29, V9). Volta pela busca (`devolverPedidoRecusado`),
    // que sai na hora se a tela ficou sem card. O que a aprovação resolveu não
    // volta, e o que a outra aba decidiu (R11-2-02) também não.
    const marcados = new Set([...feitos, ...aprovadas, ...daOutraAba]);
    const naoMarcados = epocaFila !== AppState.fetchEpoch ? alvos.filter((p) => !marcados.has(p)) : [];
    // A fila na tela: o card da frente pode ter saído no lote.
    if (AppState.currentPlace && !AppState.queue.includes(AppState.currentPlace)) {
        AppState.currentPlace = null;
        removeCurrentCardEl();
    }
    // A devolução já desenha o card ou busca quando a tela está vazia.
    if (naoMarcados.length) devolverPedidoRecusado(naoMarcados, epocaFila);
    else if (!AppState.currentPlace) {
        if (AppState.queue.length) showCurrentPlace();
        else if (AppState.hasMore) startFetching();
        else showNoPlaces();
    }
    // O card da frente FICOU — já lido (R10-2-04), decidido na outra aba ou em
    // andamento, que o lote deixa de fora — e a fila mudou por baixo dele: o
    // card de FUNDO seguia mostrando um pedido que acabou de sair da fila, e o
    // "Ver +N" e a barra do foco no autor contavam os que saíram (MEDIDO no
    // navegador: fila u1–u5 do mesmo autor, u1 já lido — depois do lote, fila
    // [u1], "Restam 1", o fundo ainda u2 e "Ver +4"; tocado, a barra "1 de 1";
    // auditoria de 2026-10-07, R11-2-04). Quem acerta os três é o
    // `aoMudarAFilaPorBaixo`, o mesmo da página que chega e da recusa automática.
    else if (saiuDaFila) aoMudarAFilaPorBaixo();
    updatePendingCount();
}

function advanceQueue() {
    AppState.queue.shift();
    AppState.currentPlace = null;
    // A ordem que uma página nova (ou o perfil) pediu já foi aplicada ao RESTO
    // quando chegou (`sortQueue` com `semTrocarOCardDaTela`, R6-2-06): o topo
    // que fica é o próximo na ordem, o mesmo que o card de fundo anunciava.
    updatePendingCount();

    if (AppState.queue.length > 0) {
        showCurrentPlace();
        maybePrefetch();
    } else if (AppState.hasMore) {
        startFetching();
    } else {
        showNoPlaces();
    }

    setTimeout(() => {
        const stack = document.getElementById('cardStack');
        if (!stack) return;
        const hasCard = !!cardDaFrente();
        const loadingHidden = document.getElementById('loadingCard').classList.contains('hidden');
        const noMoreHidden = document.getElementById('noMoreCards').classList.contains('hidden');
        if (!hasCard && loadingHidden && noMoreHidden) {
            console.warn('Estado inconsistente após advanceQueue, forçando recuperação');
            if (AppState.queue.length > 0) {
                showCurrentPlace();
            } else if (AppState.hasMore) {
                startFetching();
            } else {
                showNoPlaces();
            }
        }
    }, 200);
}

// `place` aceita UM place ou um ARRAY deles (o lote). Um mecanismo só, de
// propósito: o Desfazer do lote tem que seguir exatamente as mesmas regras do
// Desfazer de um card — a trava dos botões, o banner com a contagem regressiva,
// o descarregamento ao sair, o `resetQueue`. Dois mecanismos seriam duas
// listas de regras pra manter em sincronia, e a segunda envelheceria.
//
// `opts.aoSair` diz o que fazer quando a página morre no meio da janela:
//   'execute' (padrão) — despacha com keepalive. Uma requisição: ou vai ou não.
//   'cancel'           — descarta sem enviar. É o certo pro LOTE, e o motivo é
//                        que N requisições disparadas no `pagehide` completam
//                        PARCIALMENTE: sete vão, sete não, e o placar já contou
//                        as catorze. Meio-lote enviado é a única falha aqui sem
//                        sintoma nenhum — perder o lote se refaz em dois toques.
function scheduleAction(type, place, executor, opts = {}) {
    dlog('acao', { tipo: type, place: dlogPlace(place),
                   undo: AppState.preferences.undoEnabled !== false });
    const places = Array.isArray(place) ? place : [place];
    const n = places.length;
    const aoSair = opts.aoSair === 'cancel' ? 'cancel' : 'execute';
    const regiaoDoGesto = API.getRegion();   // ver `API.markAsRead`
    // O dia e o lugar do gesto (`carimboDoGesto`), que o handler carimbou: a
    // descarga põe a decisão na fila de saída no FIM da janela, e lidos ali eles
    // seriam os de depois de um "Aplicar" dentro dela (R6-7-4).
    const gestoDoAgendamento = opts.gesto || null;
    // Reverte o placar otimista. `salvar` existe porque o `cancel` do logout
    // não precisa gravar (tudo é apagado depois) mas o do `pagehide` precisa:
    // o número inflado JÁ foi pro armazenamento quando a ação foi agendada.
    const reverterPlacar = (salvar) => {
        if (type === 'read') AppState.stats.read = Math.max(0, AppState.stats.read - n);
        else if (type === 'reject') AppState.stats.rejected = Math.max(0, AppState.stats.rejected - n);
        else if (type === 'skip') AppState.stats.skipped = Math.max(0, AppState.stats.skipped - n);
        if (salvar) { updateStats(); saveStats(); }
    };
    if (AppState.pendingAction) {
        AppState.pendingAction.execute();
        AppState.pendingAction = null;
    }
    removeUndoBanner();
    // Do gesto até o fim do envio o pedido está "em andamento": uma busca que
    // chegar nesse meio não o traz de volta (ver `semOsJaDecididos`). Sai no fim
    // do envio — quando ele já está no pouso ou na fila de saída — e no
    // Desfazer/cancelar, quando ele volta a ser só um pedido da fila.
    marcarEmAndamento(places, true);

    let executed = false;
    const runExecutor = async () => {
        // A ação saiu: a janela do Desfazer acabou e os botões voltam.
        AppState.pendingAction = null;
        aplicarTravaDeAcao();
        AppState.inFlightActions++;
        updateInFlightIndicator();
        try {
            await executor();
        } catch (err) {
            console.error('action error', err);
        } finally {
            // O "em andamento" sai ANTES de o indicador ser redesenhado, como no
            // fim do lote e do "Marcar todos": a decisão que ficou na fila de
            // saída (rede, sessão) só conta como ESPERANDO envio depois de sair
            // daqui — redesenhado antes, o "1 esperando" nascia sem o
            // `nao-cobrir` (ver `updateInFlightIndicator`, R10-4-05).
            marcarEmAndamento(places, false);
            AppState.inFlightActions = Math.max(0, AppState.inFlightActions - 1);
            updateInFlightIndicator();
        }
    };

    // Gate de experiência: mesmo se a pref está salva como false (ex: legado de
    // versão sem gate, ou outro dispositivo), só pula o undo se o user qualifica.
    if (AppState.preferences.undoEnabled === false && canDisableUndo()) {
        executed = true;
        runExecutor();
        return;
    }
    // Com a folha da presença aberta (a lista, a conversa), a janela não abre
    // por baixo dela: o banner do Desfazer ficaria em cima da linha da pessoa e
    // do "Enviar", e o toque caía nele (ver `despacharJanelaDoDesfazer`). É a
    // decisão que CHEGA com a folha já aberta — o gesto saiu antes, e a animação
    // do card dura 350 ms: tocar a pílula nesse meio abria a janela por baixo da
    // lista (auditoria de 2026-10-01, R6-5-4). Ela sai na hora, como sairia ao
    // abrir a folha com a janela correndo. `=== true`: só a folha de verdade.
    if (typeof presencaFolhaAberta === 'function' && presencaFolhaAberta() === true) {
        executed = true;
        runExecutor();
        return;
    }

    const timerId = setTimeout(() => {
        if (!executed) {
            executed = true;
            AppState.pendingAction = null;
            removeUndoBanner();
            // A janela correu inteira e ninguém desfez: evidência de que, pra
            // este editor, o Desfazer é só espera (ver DICA_SEM_UNDO).
            registrarJanelaSemUndo();
            runExecutor();
        }
    }, UNDO_WINDOW_MS);

    AppState.pendingAction = {
        type,
        place,
        execute: () => {
            if (!executed) {
                executed = true;
                clearTimeout(timerId);
                // A janela acabou: o banner sai JUNTO. Ficava na tela quando a
                // execução vinha da descarga (app indo pro fundo), e tocar
                // "Desfazer" ao voltar só apagava o banner — a ação já tinha
                // saído, e a pessoa achava que tinha desfeito.
                removeUndoBanner();
                runExecutor();
            }
        },
        // Descarta a ação sem enviar e reverte o stat otimista. Usado no logout e
        // na sessão expirada (não há sessão válida pra enviar). Não re-enfileira
        // nem re-renderiza — o chamador reseta/zera a fila.
        //
        // `salvarPlacar` é o caminho da DESCARGA (app indo pro fundo, página
        // morrendo), e só o lote cancela nele. Ali a página pode seguir viva —
        // a pessoa trocou de app e volta —, então os pedidos voltam pra fila,
        // como no Desfazer: eles seguem pendentes no Waze. E a janela FECHA
        // (banner fora, botões de volta): sem isto `pendingAction` ficava
        // preso, `acoesTravadas()` verdadeiro pra sempre, e ✕ ↑ ✓, gesto e
        // teclado morriam até recarregar.
        cancel: (salvarPlacar) => {
            if (!executed) {
                executed = true;
                clearTimeout(timerId);
                marcarEmAndamento(places, false);
                reverterPlacar(!!salvarPlacar);
                if (AppState.pendingAction && AppState.pendingAction.place === place) AppState.pendingAction = null;
                removeUndoBanner();
                if (salvarPlacar) {
                    if (type !== 'skip') AppState.serverTotal += n;
                    AppState.queue.unshift(...places);
                    updatePendingCount();
                    showCurrentPlace();
                }
                aplicarTravaDeAcao();
            }
        },
        // O que fazer quando a página está morrendo. Ver o comentário da
        // assinatura: o lote CANCELA porque meio-lote enviado não tem sintoma.
        aoSair,
        // Página indo pro fundo ou morrendo COM rede — ou com o "lie-fi" que diz
        // `onLine` e não passa nada (túnel, portal cativo). O `keepalive` leva o
        // envio com a página morta, mas se ele não chegasse a decisão sumia: o
        // pouso já tinha sido gravado antes do envio (a reabertura sem rede
        // escondia o pedido) e o placar ficava com o +1 (auditoria de
        // 2026-09-26, O5). Agora a decisão entra na fila de saída de forma
        // SÍNCRONA, ANTES do envio — at-least-once: se o envio chegou e a
        // resposta morreu com a página, o reenvio volta "já tratado" e conta UMA
        // vez; se a resposta chegar com a página viva, ela tira o item da fila
        // (`descargaNaFila`, no `handleActionResult`). O pouso vem da resposta.
        descarregar: () => {
            if (executed) return;
            if (n === 1 && (type === 'read' || type === 'reject')) {
                const r = enfileirarSaida(type, places[0], regiaoDoGesto, { ...gestoDoAgendamento, ...reivindicacaoDestaAba() });
                if (r === 'repetida') {
                    // A decisão deste pedido JÁ esperava na fila: vale a primeira
                    // (ver `enfileirarSemRede`), e este gesto não sai nem conta.
                    executed = true;
                    clearTimeout(timerId);
                    AppState.pendingAction = null;
                    marcarEmAndamento(places, false);
                    reverterPlacar(true);
                    removeUndoBanner();
                    aplicarTravaDeAcao();
                    return;
                }
                if (r) descargaNaFila.add(places[0]);
            }
            AppState.pendingAction.execute();
        },
        // Página morrendo SEM REDE: a decisão vai direto pra fila de saída, na
        // hora e sem tentar a rede. O caminho normal chegaria lá do mesmo jeito
        // — tenta, falha por rede, enfileira —, mas por uma cadeia ASSÍNCRONA
        // que precisa de mais uma volta do laço de eventos, e a página que está
        // sendo encerrada pode não ter essa volta. Aí a decisão sumia com o
        // placar já contado, e o pedido voltava como card na reabertura. Só pra
        // um pedido de ✕ ou ✓: o lote tem regra própria (`aoSair: 'cancel'`) e o
        // Pular não escreve nada no Waze.
        enfileirarSemRede: () => {
            if (executed || n !== 1 || (type !== 'read' && type !== 'reject')) return false;
            const r = enfileirarSaida(type, places[0], regiaoDoGesto, gestoDoAgendamento);
            if (!r) return false;          // fila cheia: segue o caminho de sempre
            executed = true;
            clearTimeout(timerId);
            AppState.pendingAction = null;
            marcarEmAndamento(places, false);
            // Já estava na fila de saída: o placar contou este gesto em cima de
            // uma decisão que já tinha sido contada.
            if (r === 'repetida') reverterPlacar(true);
            removeUndoBanner();
            aplicarTravaDeAcao();
            return true;
        },
        undo: () => {
            if (!executed) {
                executed = true;
                clearTimeout(timerId);
                // Volta a ser um pedido da fila como qualquer outro.
                marcarEmAndamento(places, false);
                // Usou: a evidência de "nunca desfaz" morre aqui e recomeça do
                // zero. Quem desfaz de vez em quando não deve receber a dica.
                zerarJanelasSemUndo();
                reverterPlacar(false);
                if (type !== 'skip') AppState.serverTotal += n; // skip nunca decrementou o total
                updateStats();
                saveStats();
                // `unshift(...places)` e NÃO um laço: um laço de unshift inverte
                // a ordem, e a fila voltaria embaralhada — sem erro visível, só
                // discordando do WME na hora de conferir.
                AppState.queue.unshift(...places);
                updatePendingCount();
                // Volta pro PRIMEIRO dos restaurados. Sem isto, desfazer um lote
                // mostraria o card de outro autor, e leria como se o Desfazer
                // tivesse feito outra coisa.
                showCurrentPlace();
            }
        }
    };

    const undoMsg = n > 1
        ? t('undo.lote', { n })
        : type === 'reject' ? t('undo.reject') : type === 'skip' ? t('undo.skip') : t('undo.read');
    showUndoBanner(undoMsg);
    aplicarTravaDeAcao();
}

function showUndoBanner(message) {
    removeUndoBanner();
    const container = document.getElementById('undoContainer');
    const banner = document.createElement('div');
    banner.className = 'undo-banner';
    banner.innerHTML = `
        <span>${escapeHtml(message)}</span>
        <button type="button" id="undoBtn">${escapeHtml(t('undo.button'))}</button>
        <span class="undo-progress" style="animation-duration: ${UNDO_WINDOW_MS}ms" aria-hidden="true"></span>
    `;
    container.appendChild(banner);
    document.getElementById('undoBtn').addEventListener('click', desfazerAcaoPendente);
}

// Desfazer, pelos DOIS caminhos (o botão do banner e a tecla z).
//
// O `aplicarTravaDeAcao()` no fim é o que conserta um defeito que existia desde
// antes do lote e que ninguém tinha visto: os dois caminhos limpavam o
// `pendingAction` e o banner, mas nunca reabilitavam os botões do card. E não
// dava pra perceber pela ordem certa — o `undo()` chama `showCurrentPlace()`
// ANTES de o chamador zerar o `pendingAction`, então o card novo nascia travado
// e nada voltava a olhar pra ele. O gesto seguia funcionando (o `acoesTravadas`
// já era falso), o que escondia o problema: só o caminho canônico e acessível,
// os três botões, é que ficava morto — inclusive pra quem usa leitor de tela,
// porque `disabled` também tira da ordem do Tab.
//
// `ev` é o clique no botão (a tecla z chama sem evento, e É teclado): com o
// foco no "Desfazer", o banner sumir o jogaria no <body> — ele vai ao botão da
// ação desfeita, no card que voltou (ver `pedirFocoDoTeclado`, C10).
function desfazerAcaoPendente(ev) {
    if (AppState.pendingAction) {
        pedirFocoDoTeclado(document.getElementById('undoBtn'), !ev || ev.detail === 0, AppState.pendingAction.type);
        AppState.pendingAction.undo();
        AppState.pendingAction = null;
        registrarDesfazer();
    }
    removeUndoBanner();
    aplicarTravaDeAcao();
}

// A tecla z desfaz o que o banner do Desfazer oferece AGORA — a ação do card
// ou a da foto (excluir, aprovar, renomear). Até a auditoria de 2026-09-26 ela
// só olhava o `pendingAction` do card: a exclusão de uma foto não se desfazia
// pelo teclado, nem dentro do lightbox nem depois de fechá-lo, com a janela
// correndo e o banner na tela.
//
// A da foto vai pelo PRÓPRIO botão do banner, e não pelo `desfazer` de cada
// pendência: o banner é a fonte única do que "Desfazer" faz ali (o que ele
// registra, o que ele limpa), e dois caminhos pro mesmo conceito é como o
// teclado e o dedo passam a discordar sem ninguém ver. Devolve se desfez.
function desfazerPeloTeclado() {
    if (AppState.pendingAction) { desfazerAcaoPendente(); return true; }
    if (!(exclusaoPendente || aprovacaoPendente || renomeacaoPendente)) return false;
    const btn = document.getElementById('undoBtn');
    if (!btn) return false;
    btn.click();
    return true;
}

// A janela do Desfazer SAI agora — a do card e as do lightbox (aprovar,
// excluir, renomear) — e o banner sai com ela, na ordem do "Marcar todos" e do
// treino (`handleBatchMarkRead`, `Treino.entrar`). Quem chama é a folha da
// presença ao abrir (`presencaDespacharJanela`): ela mora no rodapé, embaixo do
// banner, e o toque no "Enviar" da conversa caía no "Desfazer" — a decisão do
// card era desfeita atrás da folha, e a mensagem não saía (auditoria de
// 2026-10-01, R6-5-4).
function despacharJanelaDoDesfazer() {
    if (AppState.pendingAction) { AppState.pendingAction.execute(); AppState.pendingAction = null; }
    enviarPendenciasDoLightbox();
    removeUndoBanner();
}

function removeUndoBanner() {
    const container = document.getElementById('undoContainer');
    const tinhaOFoco = !!(container && container.contains(document.activeElement));
    if (container) container.innerHTML = '';
    // O "Desfazer" entra na volta do Tab da foto ampliada: se o foco estava
    // nele, sumir com o banner o jogaria no <body>, fora da camada `aria-modal`.
    manterFocoNoLightbox();
    // E na do mapa ampliado (L29): ali o foco volta pro ✕, onde ele nasce.
    if (tinhaOFoco && typeof MapaLightbox !== 'undefined' && MapaLightbox.isOpen()) {
        const a = document.activeElement;
        if (!a || a === document.body) document.getElementById('mapaLbClose')?.focus({ preventScroll: true });
    }
}

// As decisões da fila de saída que a OUTRA aba está MANDANDO agora (a marca dela
// no item, `reivindicadoPorOutraAba`): pro indicador desta aba elas são
// "enviando", como as daqui. E a marca VENCE sozinha (`SAIDA_REIVINDICACAO_MS`:
// a outra aba pode ter morrido com o envio no ar), sem nada que redesenhe o
// indicador: um temporizador LOCAL no prazo da primeira que vence o redesenha —
// sem rede, uma vez por prazo, e sai quando o indicador é redesenhado de novo.
let indicadorMarcaVence = null;
function saindoPelaOutraAba(fila) {
    let n = 0, vence = Infinity;
    for (const x of fila) {
        if (!x || pedidosEmAndamento.has(chaveDoPedido(x)) || !reivindicadoPorOutraAba(x)) continue;
        n++;
        vence = Math.min(vence, (Number(x.rvEm) || 0) + SAIDA_REIVINDICACAO_MS);
    }
    clearTimeout(indicadorMarcaVence);
    indicadorMarcaVence = null;
    // A folga: o redesenho cai DEPOIS do prazo, e a marca já lê como vencida.
    if (n) indicadorMarcaVence = setTimeout(() => { indicadorMarcaVence = null; updateInFlightIndicator(); },
        Math.max(0, vence - Date.now()) + 50);
    return n;
}

// UM indicador para os dois estados, e não dois: eles disputam o mesmo canto e
// nunca dizem coisas independentes — "enviando" é o que está saindo AGORA,
// "esperando" é o que ficou pra depois. Enviando ganha, porque é o estado que
// está mudando.
function updateInFlightIndicator() {
    // O diálogo do "Sair", aberto, conta a MESMA fila (ver a função).
    if (!document.getElementById('logoutModal')?.classList.contains('hidden')) desenharAvisoDoSair();
    let el = document.getElementById('inFlightIndicator');
    // Ele era NÚMERO A NÃO COBRIR (o `nao-cobrir` lá embaixo) antes desta volta?
    const eraLeitura = !!el && /(^|\s)nao-cobrir(\s|$)/.test(el.className);
    const fila = AppState.authenticated ? carregarFilaDeSaida() : [];
    const esperando = fila.length;
    // O que a OUTRA aba está mandando é "enviando" aqui também (R11-4-03): dizia
    // "1 esperando envio", com o relógio que quer dizer "parado esperando rede" —
    // e, desde o R10-4-05, sem a marca de número a não cobrir, então no
    // computador o FAB ficava por cima dele, cobrindo-o inteiro (auditoria da
    // rodada 11, MEDIDO nos dois motores). O texto e a régua do FAB passam a
    // dizer a mesma coisa: alguém está mandando.
    const pelaOutraAba = saindoPelaOutraAba(fila);
    if (AppState.inFlightActions <= 0 && esperando <= 0) {
        // Sumiu: o canto que ele ocupava pode voltar a ser o do FAB (ver abaixo)
        // — se ele era número a não cobrir; o "enviando" nunca afastou o FAB.
        if (el) { el.remove(); if (eraLeitura) atualizarFabDev(); }
        return;
    }
    if (!el) {
        el = document.createElement('div');
        el.id = 'inFlightIndicator';
        // ANCORADO NO CABEÇALHO MEDIDO (`--header-h`, o mesmo do `#bannerStack`).
        // Era `top-20` (80 px fixos): no iPhone com o app INSTALADO a margem de
        // segurança de cima (47 px; 59 com a Dynamic Island) entra no cabeçalho,
        // que vai a 116–128 px, e o número ficava DEBAIXO dele — o único sinal de
        // que há decisão esperando envio, sumido justo no app instalado, que é
        // onde se usa o modo avião (auditoria da rodada 10, R10-4-02, MEDIDO: o
        // dedo no meio dele caía no ⓘ). O vão de hoje até o cabeçalho (69 px de
        // altura, 11 px de vão) fica, e o `max` com os 80 px de antes deixa a
        // posição IDÊNTICA onde não há margem — inclusive deitado, onde o
        // cabeçalho é mais baixo (53 px; MEDIDO a 390×844, 375×667, 280×653,
        // 1280×800 e 844×390: 0 px de diferença).
        el.style.top = 'max(5rem, calc(var(--header-h, 4rem) + 11px))';
        document.body.appendChild(el);
    }
    // Girando só quando está MESMO saindo — por esta aba ou pela outra (a marca
    // dela). "Esperando" com giro seria o app fingindo trabalho que não está
    // acontecendo — e é justamente o estado em que não há rede pra trabalhar.
    const saindo = Math.max(0, AppState.inFlightActions) + pelaOutraAba;
    const enviando = saindo > 0;
    const n = enviando ? saindo : esperando;
    const texto = enviando
        ? t('indicator.sending', { n: saindo })
        : t('indicator.waiting', { n: esperando });

    // ÍCONE + NÚMERO, sem pílula (decisão do owner, 2026-09-21, olhando mockups
    // na tela real: *"o texto não poderia ser mais discreto?"*).
    //
    // MEDIDO nas cinco variantes, no iPhone dele e no Fold: a frase inteira
    // custava 128px e tapava **100% da tinta do RESTAM**; isto custa 23px e
    // **zero**. Ou seja, encolher resolveu de graça o que tinha sido avaliado e
    // mantido a contragosto uma hora antes — foi o dado novo que a régua de
    // "não re-proponha sem dado novo" pedia.
    //
    // O ÍCONE é que carrega o estado, nunca a cor sozinha (WCAG 1.4.1, a mesma
    // régua que fez a pílula da presença trocar de ícone): spinner girando =
    // saindo agora, relógio = parado esperando rede. A cor só reforça.
    //
    // SÓ NÚMERO foi medido e RECUSADO: "2" e "3" ficam visualmente idênticos, e
    // aí se perde exatamente a distinção que importa quando não há sinal —
    // entre o trabalho estar saindo e estar encalhado.
    const icone = enviando ? `
        <svg class="w-3 h-3 animate-spin" fill="none" viewBox="0 0 24 24" aria-hidden="true">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"></path>
        </svg>` : `
        <svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor"
             stroke-width="2.5" stroke-linecap="round" aria-hidden="true">
            <circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 2"></path>
        </svg>`;
    // As shades do CLARO são -800 e não -700: sem pílula o contraste é contra o
    // cartão do placar, e -700 media 4,8:1 contra um mínimo de 4,5 — passa, mas
    // com 0,3 de folga. O `.valor-ausente` já nasceu numa margem dessas e teve
    // que ser corrigido depois (gotcha #40: constante de contraste tem ESCOPO).
    //
    // `nao-cobrir`: é um NÚMERO, e o FAB do modo dev não pousa em cima de número
    // (ver `DEV_FAB_LEITURA`) — cobrir "3" é sumir com a única coisa que diz que há
    // decisão esperando sinal, justo o que se olha ao depurar o offline. Deitado,
    // no tablet e no computador o placar não passa por baixo do `cima-dir`, o canto
    // lia como livre, e o FAB tapava 100% do indicador (auditoria da rodada 9,
    // R9-4-05, MEDIDO a 1280×800, 844×390 e 768×1024, nos dois motores).
    //
    // SÓ com decisão ESPERANDO envio (na fila de saída e parada esperando a
    // rede), e não no "enviando" de cada decisão com rede, que dura a ida ao
    // Waze: com a marca nele também, o FAB atravessava a tela larga DUAS vezes a
    // cada ✕/✓ — pro `cima-esq` quando o "1 enviando" nascia e de volta quando
    // sumia (auditoria da rodada 10, R10-4-05, MEDIDO: 6 trocas de canto em 3
    // decisões a 1280×800, 844×390 e 768×1024, nos dois motores). A decisão que
    // está SAINDO também mora na fila de saída (anotada antes do envio, ver
    // `anotarAntesDoEnvio`), então "tem fila" não basta: ESPERANDO é o item que
    // ninguém está mandando agora — nem esta aba (`pedidosEmAndamento`), nem a
    // outra (a marca dela). E com decisão esperando, a marca fica também
    // enquanto outra sai ("1 enviando" na frente do número): sem rede, cada ✕
    // ia de "enviando" a "esperando" em milissegundos, e o FAB iria e voltaria
    // a cada um.
    const leitura = fila.some((x) => x && !pedidosEmAndamento.has(chaveDoPedido(x)) && !reivindicadoPorOutraAba(x));
    el.className = (leitura ? 'nao-cobrir ' : '') + 'fixed right-4 z-40 flex items-center gap-1 text-[0.6875rem] font-semibold '
        + (enviando ? 'text-cyan-800 dark:text-cyan-300'
                    : 'text-amber-800 dark:text-amber-300');
    el.title = texto;
    // A FRASE INTEIRA continua existindo pra quem usa leitor de tela: o que
    // encolheu foi o pixel, não a informação. Sem o `sr-only` ele ouviria "3" e
    // mais nada — e "3" sozinho não diz nem o que são, nem em que estado estão.
    el.innerHTML = icone + `<span class="tnum" aria-hidden="true">${escapeHtml(String(n))}</span>`
        + `<span class="sr-only">${escapeHtml(texto)}</span>`;
    // O número a não cobrir aparece SEM camada mudando — e o FAB só reavalia o
    // canto quando uma camada muda (ver `ligarFabDev`): sem isto, ele ficava onde
    // estava, em cima do número que acabou de nascer. Só quando ele PASSA a ser
    // número a não cobrir ou DEIXA de ser (e no sumir, acima), não a cada número:
    // é o que o FAB evita que muda ali. Sem o modo dev, não faz nada.
    if (leitura !== eraLeitura) atualizarFabDev();
}

// Feedback quando um número muda. São DOIS mecanismos, porque contar não serve
// pro caso mais comum: cada swipe move o contador em 1, e entre 12 e 13 não
// existe inteiro nenhum pra mostrar — a "contagem" seria invisível.
//   · pulo (pop):  SEMPRE que o número muda. É o que comunica "isso mexeu".
//   · contagem:    só com |Δ| >= 2, aí sim há valores intermediários (ex.: a
//                  fila carregando de 0 pra 191).
// Ambos rodam em paralelo com o próximo card entrando: custo zero pro editor.
const COUNT_ANIM_MIN_MS = 220;
const COUNT_ANIM_MAX_MS = 650;

// `semAnimar` existe pra UMA situação: a troca de CONTEXTO do placar (entrar e
// sair do treino). Contar de 7 pra 0 sugere que o trabalho da pessoa mudou —
// quando o que mudou foi o placar que ela está olhando. É o mesmo raciocínio do
// "contador que muda de 1 PULA, não conta", visto do outro lado: animação aqui
// conta uma história falsa. Medido: 7/2/1/99 contando até 0/0/0/3 levava ~1s.
function setCount(el, valor, sufixo = '', semAnimar = false) {
    if (!el) return;
    // Os QUATRO pontos de escrita passam pelo mesmo lugar — inclusive os
    // quadros da animação. Hoje ele só concatena o sufixo, mas é o que garante
    // que o '+' do "Restam" não fique de fora de um deles.
    const esc = (n) => String(n) + sufixo;
    if (semAnimar) {
        if (el._countRaf) cancelAnimationFrame(el._countRaf);
        el.textContent = esc(valor);
        return;
    }
    const anterior = parseInt(String(el.textContent).replace(/\D/g, ''), 10);
    const alvo = Number(valor);
    const mudou = !Number.isFinite(anterior) || anterior !== alvo;

    // Toda escrita direta CANCELA a contagem que estiver correndo: ela terminava
    // escrevendo o alvo VELHO por cima do novo, e a tela ficava errada até a
    // próxima mudança — MEDIDO (s16): uma página chega (+30, contagem de 400 ms),
    // um ✕ confirmado 300 ms depois → "Restam" 33 na tela com 32 de verdade
    // (R5-2-10). O ramo `semAnimar` já cancelava; estes dois, não.
    const pararContagem = () => {
        if (el._countRaf) { cancelAnimationFrame(el._countRaf); el._countRaf = null; }
    };
    if (!Number.isFinite(alvo) || prefersReducedMotion()) {
        pararContagem();
        el.textContent = esc(valor);
        return;
    }
    // Sem valor anterior legível ('—', '…'): escreve direto, mas ainda pula.
    if (!Number.isFinite(anterior) || Math.abs(alvo - anterior) < 2) {
        pararContagem();
        el.textContent = esc(alvo);
        if (mudou) popCount(el);
        return;
    }

    // Um contador por elemento: cancela o anterior antes de começar outro,
    // senão dois rAF disputam o mesmo textContent e o número treme.
    if (el._countRaf) cancelAnimationFrame(el._countRaf);
    const dur = Math.min(COUNT_ANIM_MAX_MS, COUNT_ANIM_MIN_MS + Math.abs(alvo - anterior) * 6);
    const inicio = performance.now();
    const passo = (agora) => {
        const p = Math.min(1, (agora - inicio) / dur);
        const eased = 1 - Math.pow(1 - p, 3); // ease-out: rápido no começo
        el.textContent = esc(Math.round(anterior + (alvo - anterior) * eased));
        if (p < 1) el._countRaf = requestAnimationFrame(passo);
        else el._countRaf = null;
    };
    el._countRaf = requestAnimationFrame(passo);
    popCount(el);
}

// Reinicia o pulo mesmo em mudanças seguidas (swipe rápido): tirar a classe,
// forçar reflow e recolocar — sem o reflow o browser junta tudo num estilo só
// e a animação não toca de novo.
function popCount(el) {
    el.classList.remove('count-pop');
    void el.offsetWidth;
    el.classList.add('count-pop');
    el.addEventListener('animationend', () => el.classList.remove('count-pop'), { once: true });
}

function prefersReducedMotion() {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
}

// O aviso de que o Desfazer ficou opcional (`checkUndoGateUnlock`) NÃO sai
// mais daqui. Saía, e o placar é OTIMISTA: o gesto que cruzava a cota
// comemorava dentro da janela do Desfazer, que ainda podia devolver o pedido —
// desfeito, o aviso seguia na tela levando a um interruptor travado ("falta 1"),
// e a marca de "visto" já estava gravada: o desbloqueio de verdade, um pedido
// depois, nunca era anunciado (R6-7-5, auditoria de 2026-10-01). Ele é avaliado
// na CONFIRMAÇÃO, como as conquistas (`registrarAcaoConfirmada`,
// `registrarLoteConfirmado`).
function updateStats(semAnimar = false) {
    desenharPlacar(semAnimar);
}

// Só DESENHA o placar e o "Restam". O placar que chega de OUTRA aba também só
// se desenha (`relerPlacarDeOutraAba`): o aviso de que o Desfazer ficou
// opcional é da aba em que a decisão se CONFIRMOU, e a marca de "visto" chega
// pelas preferências.
function desenharPlacar(semAnimar = false) {
    // No treino a TELA mostra o placar dele; o real segue intocado por baixo.
    const st = Treino.ativo ? Treino.stats : AppState.stats;
    setCount(document.getElementById('readCount'), st.read, '', semAnimar);
    setCount(document.getElementById('rejectedCount'), st.rejected, '', semAnimar);
    setCount(document.getElementById('skippedCount'), st.skipped, '', semAnimar);
    updatePendingCount(semAnimar);
}

// ── Ponto no ícone do app instalado ──────────────────────────────────────
// PONTO, não número, e a razão é honestidade: o badge só é escrito quando o app
// RODA, então um número fica velho no instante em que a pessoa fecha. "118" no
// ícone dois dias depois é uma afirmação falsa; o ponto diz "há trabalho", que
// continua verdadeiro enquanto a fila não zera — e a fila medida do owner nunca
// zerou (211, 196, 108 em três dias).
//
// Nunca PEDE permissão. No iOS o badge exige notificação autorizada, e um
// prompt não solicitado é exatamente a interrupção que a régua do projeto
// proíbe. Sem autorização a promessa rejeita, e aqui isso é silêncio: o recurso
// simplesmente não existe naquele aparelho.
function atualizarPontoNoIcone() {
    try {
        if (!('setAppBadge' in navigator)) return;
        const temTrabalho = AppState.authenticated && AppState.serverTotal > 0;
        // `setAppBadge()` sem argumento é o PONTO; com número seria a contagem.
        const p = temTrabalho ? navigator.setAppBadge() : navigator.clearAppBadge();
        if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (e) { /* aparelho sem suporte não pode derrubar o placar */ }
}

// ── Aviso de sessão vencendo ─────────────────────────────────────────────
// Existe porque o fim da sessão chega como surpresa no pior lugar possível: no
// celular, onde não há como renovar. Quem entrou pelo QR precisa de um
// computador, e descobrir isso no meio da fila custa a sessão inteira de
// triagem.
//
// O prazo é o do WAZE, não o do app, e a diferença é o que torna a conta
// honesta. O `SESSION_TTL` do app (21 dias) é DESLIZANTE — o `loadSession`
// renova a cada uso, então quem usa nunca chega perto dele e contar a partir
// dali seria inventar um prazo que não vence. Já o cookie do Waze tem prazo
// FIXO: MEDIDO com 3 chamadas de leitura seguidas, o valor do `_web_session`
// mudou nas três (o Waze rotaciona a cada resposta, gotcha #43) e o `Expires`
// ficou parado, com o `Max-Age` só decrescendo. O servidor lê esse prazo do
// `Set-Cookie` que já recebe e manda junto (`sessaoExpiraEm`).
//
// Não guarda nada a mais no servidor e não encosta na criptografia: o prazo
// vem de um cabeçalho que a resposta já trazia, e mora no aparelho.
const AVISO_SESSAO_DIAS = 5;

function carregarPrazoDaSessao() {
    const bruto = Number(safeLS.get(SESSAO_KEY));
    AppState.sessaoExpiraEm = Number.isFinite(bruto) && bruto > 0 ? bruto : null;
}

// Ausente NÃO é "não vence": o Waze só manda `Set-Cookie` quando rotaciona, e
// uma resposta sem ele não desmente a anterior. Por isso só grava valor válido
// — apagar aqui faria o aviso piscar a cada chamada que não trouxe o cabeçalho.
function guardarPrazoDaSessao(body) {
    if (!body || typeof body !== 'object') return;
    const prazo = Number(body.sessaoExpiraEm);
    if (!Number.isFinite(prazo) || prazo <= 0) return;
    // Só registra quando MUDA: o Waze manda o cabeçalho ao rotacionar, e sem
    // esta condição o diário viraria uma linha por resposta — o custo de
    // escrita que a regra de entrada existe pra evitar.
    const mudou = AppState.sessaoExpiraEm !== prazo;
    AppState.sessaoExpiraEm = prazo;
    safeLS.set(SESSAO_KEY, String(prazo));
    if (mudou) registrarEventoDeSessao('prazo', { prazo, emDias: Math.round((prazo - Date.now() / 1000) / 8640) / 10 });
    atualizarAvisoDeSessao();
}

// `soMemoria`: a queda só desta aba (ver `derrubarSessao`) — o guardado no
// aparelho é o prazo da sessão da outra aba, viva.
function esquecerPrazoDaSessao({ soMemoria = false } = {}) {
    AppState.sessaoExpiraEm = null;
    if (!soMemoria) safeLS.remove(SESSAO_KEY);
    atualizarAvisoDeSessao();
}

function atualizarAvisoDeSessao() {
    const el = document.getElementById('avisoSessao');
    if (!el) return;
    const prazo = AppState.sessaoExpiraEm;
    const esconder = () => { el.classList.add('hidden'); el.textContent = ''; };
    if (!AppState.authenticated || !prazo) return esconder();
    const faltaMs = prazo * 1000 - Date.now();
    // Já venceu: quem avisa é o 401, que leva pra tela de entrar. Repetir aqui
    // seria dizer "vence em -1 dia" atrás de uma tela que nem está mais visível.
    if (faltaMs <= 0) return esconder();
    // Dia é DATA, nunca 24 h: quantas DATAS separam hoje do dia em que ela vence.
    // Era `floor(falta / 24 h)`, e às 20h com 20 h de prazo dizia "vence hoje"
    // pra uma sessão que vence amanhã às 16h (auditoria de 2026-09-26). Pela
    // data, cada frase é verdade: "hoje" é hoje, "amanhã" é amanhã, e "em N dias"
    // é o dia em que ela vence — às vezes cedo nesse dia, e a frase manda renovar.
    const dias = diaLocalDe(prazo * 1000) - diaDeHoje();
    if (dias > AVISO_SESSAO_DIAS) return esconder();
    el.textContent = dias <= 0 ? t('sessao.vence.hoje')
        : dias === 1 ? t('sessao.vence.amanha')
        : t('sessao.vence.diasPlural', { n: dias });
    el.classList.remove('hidden');
}

// As escritas DIRETAS do "Restam" (o "—" e o "…") PARAM a contagem animada que
// estiver correndo — a regra que o `setCount` já segue (R5-2-10), e estas não
// seguiam: no ↻ com 40 pedidos a contagem 40 → 0 leva ~460 ms, a busca que
// falha rápido (a borda com a origem fora dá 502 em ~50 ms) escrevia "—", e o
// quadro seguinte da contagem escrevia por cima: "Restam 0+" sob o "Falha ao
// carregar" (MEDIDO, s36, Chromium e WebKit; auditoria de 2026-10-02, R6-2-05).
function pararContagemEmCurso(el) {
    if (el._countRaf) { cancelAnimationFrame(el._countRaf); el._countRaf = null; }
}

function updatePendingCount(semAnimar = false) {
    const el = document.getElementById('pendingCount');
    atualizarPontoNoIcone();
    atualizarAvisoDeSessao();
    if (!el) return;
    if (!AppState.authenticated) {
        el.textContent = '—';
        pararContagemEmCurso(el);
        return;
    }
    if (Treino.ativo) {
        setCount(el, Treino.restam, '', semAnimar);
        // O "de N na região" é da fila REAL: embaixo do "Restam" do treino ele
        // dizia "30 de 135 na região" sobre 30 exemplos (R6-7-8). Esconde aqui e
        // volta no `sair()`, que redesenha o contador.
        updatePendingTotalHint();
        return;
    }
    // CARREGANDO: a busca no ar, ou o `startFetching` esperando o perfil pra
    // buscar (`buscaEsperaOPerfil`), com a fila vazia (R6-2-04).
    if ((AppState.fetching || buscaEsperaOPerfil) && AppState.serverTotal === 0) {
        el.textContent = '…';
        pararContagemEmCurso(el);
        return;
    }
    // FALHOU: o app NÃO SABE quantos restam, e zero não é "não sei" — zero é
    // "tudo limpo", que é o oposto. Medido no relato do owner: a tela dizia
    // RESTAM 0 com 426 pedidos esperando do outro lado. O traço é o mesmo
    // símbolo que o deslogado já usa, então o editor não precisa aprender nada.
    if (AppState.loadError) {
        el.textContent = '—';
        pararContagemEmCurso(el);
        return;
    }
    setCount(el, AppState.serverTotal, AppState.hasMore ? '+' : '', semAnimar);
    updatePendingTotalHint();
}

// D13: "de N na região". `serverBlocked` são pedidos que existem na região mas
// cujo venue este editor não pode editar — o backend os tira da fila (senão o
// editor via card que não consegue tratar). Sem essa linha, o número do app
// parece "errado" contra o que o WME mostra. Só aparece quando há bloqueados.
function updatePendingTotalHint() {
    const hint = document.getElementById('pendingTotalHint');
    if (!hint) return;
    const blocked = AppState.serverBlocked || 0;
    if (!AppState.authenticated || blocked <= 0 || Treino.ativo) {
        hint.classList.add('hidden');
        hint.textContent = '';
        hint.removeAttribute('title');
        return;
    }
    // "+" quando a contagem é piso (paramos por MAX_EMPTY_PAGES com o Waze
    // ainda oferecendo páginas) — mesma convenção do contador "Restam".
    const total = AppState.serverTotal + blocked;
    const rotulo = AppState.blockedPartial ? total + '+' : String(total);
    hint.textContent = t('stats.pending.ofRegion', { total: rotulo });
    // Plural por CHAVE (sem ICU): "1 pedido(s)" era a forma de antes.
    hint.title = t(blocked === 1 ? 'stats.pending.ofRegion.titleUm' : 'stats.pending.ofRegion.title', { blocked });
    hint.classList.remove('hidden');
}

function saveStats() {
    try {
        localStorage.setItem(STATS_KEY, JSON.stringify(AppState.stats));
    } catch (e) {}
}

function loadStats() {
    const guardado = placarGuardado();
    if (guardado) AppState.stats = guardado;
    updateStats();
}

// O placar como está no APARELHO; `null` quando não há o que ler (nada
// guardado, ou ilegível). A abertura e o aviso de OUTRA aba leem por aqui.
function placarGuardado() {
    try {
        const raw = localStorage.getItem(STATS_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        return {
            read: parsed.read || 0,
            rejected: parsed.rejected || 0,
            skipped: parsed.skipped || 0
        };
    } catch (e) { return null; }
}

function saveFilters() {
    try {
        localStorage.setItem(FILTERS_KEY, JSON.stringify(AppState.filters));
    } catch (e) {}
}

function loadFilters() {
    try {
        const raw = localStorage.getItem(FILTERS_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            AppState.filters.types = sanearTiposSalvos(parsed.types);
            AppState.filters.residential = parsed.residential || '';
            AppState.filters.stateId = parsed.stateId || '';
            AppState.filters.managedAreaId = parsed.managedAreaId || '';
            AppState.filters.myArea = !!parsed.myArea;
            AppState.filters.unreadOnly = parsed.unreadOnly !== false;
            AppState.filters.categories = Array.isArray(parsed.categories) ? parsed.categories : [];
            // O GPS NUNCA volta de uma sessão anterior: posição é um momento e
            // amanhã a pessoa está em outro lugar — restaurá-la ordenaria a fila
            // por onde ela esteve ontem. Casa e trabalho voltam (saem do perfil
            // a cada sessão), e o `ordemValida` confere se ainda existem.
            AppState.filters.sortOrder = ['oldest', 'casa', 'trabalho'].includes(parsed.sortOrder)
                ? parsed.sortOrder : ORDEM_PADRAO;
        }
    } catch (e) {}
}

// Gravar preferência ANTES de tê-las lido apaga a escolha da pessoa com o
// padrão. E não é hipotético: com o `/api/perfil` falhando, o
// `checkUndoGateUnlock` chega a `savePreferences()` num momento em que a
// memória ainda é o literal de origem — medido, com o `undoEnabled: false` do
// editor virando `true` no armazenamento, de forma PERMANENTE.
//
// ── ANISTIA DA PRESENÇA ─────────────────────────────────────────────────────
// Desligar "Ver quem está na fila" é decisão de um dia; ficar invisível pra
// sempre por causa dela raramente é a intenção. Quem experimentou o desligar
// no primeiro contato e esqueceu nunca mais vê o recurso — e não tem como
// descobrir que ele existe, porque a pílula (que é a única coisa que o anuncia)
// é justamente o que ele desligou.
//
// Depois de 9 dias desligado, volta sozinho e EM SILÊNCIO: sem toast, sem
// banner. Anunciar seria transformar uma reativação discreta numa interrupção,
// que é o oposto do que ela existe pra consertar.
//
// Quem quiser desligar de novo desliga, e ganha outros 9 dias. Quem religa à
// mão zera o carimbo — a contagem é do DESLIGAR, não do calendário.
const PRESENCA_ANISTIA_DIAS = 9;
const PRESENCA_ANISTIA_MS = PRESENCA_ANISTIA_DIAS * 24 * 60 * 60 * 1000;

// A ordem certa é garantida por invariante, não por sorte de quem chama antes:
// enquanto não se leu, não se escreve.
let preferenciasCarregadas = false;

function savePreferences() {
    if (!preferenciasCarregadas) return;
    try {
        localStorage.setItem(PREFERENCES_KEY, JSON.stringify(AppState.preferences));
    } catch (e) {}
}

function loadPreferences() {
    lerPreferenciasGuardadas();
    preferenciasCarregadas = true;
    if (aplicarAnistiaDaPresenca()) savePreferences();
}

// O que está no APARELHO, por cima do que já está no `AppState.preferences`.
// Fonte ÚNICA da leitura: a abertura e o aviso de que OUTRA aba gravou
// (`relerPreferenciasDeOutraAba`, que parte das de fábrica) passam por aqui —
// preferência nova se lê num lugar só.
function lerPreferenciasGuardadas() {
    try {
        const raw = localStorage.getItem(PREFERENCES_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            AppState.preferences.undoEnabled = parsed.undoEnabled !== false;
            // Opt-out: só desliga quem DISSE que quer desligado. `undefined`
            // (quem nunca abriu as Preferências) fica ligado, que é o padrão.
            if (typeof parsed.presenca === 'boolean') AppState.preferences.presenca = parsed.presenca;
            // Opt-IN, ao contrário da presença logo acima: só liga quem DISSE
            // que quer. `undefined` fica desligado, que é o padrão.
            AppState.preferences.pularGuarda = parsed.pularGuarda === true;
            // Opt-IN estrito tambem: quem nunca marcou nao paga byte nenhum.
            AppState.preferences.offlineDisponivel = parsed.offlineDisponivel === true;
            // undefined = nunca decidido (user antigo ou primeira visita).
            // Só copia se for boolean, pra initUndoGateSeen poder decidir depois.
            if (typeof parsed.undoGateSeen === 'boolean') {
                AppState.preferences.undoGateSeen = parsed.undoGateSeen;
            }
            if (typeof parsed.dicaDesfazerVista === 'boolean') {
                AppState.preferences.dicaDesfazerVista = parsed.dicaDesfazerVista;
            }
            if (typeof parsed.comoFuncionaVisto === 'boolean') {
                AppState.preferences.comoFuncionaVisto = parsed.comoFuncionaVisto;
            }
            if (parsed.consequenciaVista && typeof parsed.consequenciaVista === 'object') {
                AppState.preferences.consequenciaVista = parsed.consequenciaVista;
            }
            if (typeof parsed.semUndoSeguidas === 'number' && parsed.semUndoSeguidas >= 0) {
                AppState.preferences.semUndoSeguidas = parsed.semUndoSeguidas;
            }
            if (Number.isFinite(parsed.presencaOffEm) && parsed.presencaOffEm > 0) {
                AppState.preferences.presencaOffEm = parsed.presencaOffEm;
            }
            // O "invisível" do gesto de desligar que ainda não chegou ao WME, e
            // de QUAL conta (ver `presencaWmeGravarPendente`). Só com o
            // interruptor desligado: ligado, ele não vale mais.
            const pend = parsed.presencaWmeDesligar;
            if (parsed.presenca === false && pend && typeof pend === 'object'
                && /^\d{1,19}$/.test(String(pend.conta)) && Number.isFinite(pend.em)) {
                const g = { conta: String(pend.conta), em: pend.em };
                // O último envio (de qualquer aba) e a sessão dele: o teto da
                // repetição é do aparelho (R8-5-07).
                if (Number.isFinite(pend.tentadoEm) && pend.tentadoEm > 0 && typeof pend.sessao === 'string') {
                    g.tentadoEm = pend.tentadoEm;
                    g.sessao = pend.sessao.slice(0, 16);
                    // E a marca da aba do envio: o carimbo só segura o teto
                    // enquanto ela vive (R9-5-04).
                    if (typeof pend.aba === 'string' && pend.aba) g.aba = pend.aba.slice(0, 40);
                }
                AppState.preferences.presencaWmeDesligar = g;
            } else if (parsed.presenca === false && pend && typeof pend === 'object' && pend.conta === undefined
                && typeof pend.s === 'string' && /^[0-9a-f]{1,8}$/.test(pend.s) && Number.isFinite(pend.em)) {
                // O gesto feito antes de o perfil dizer de quem era a sessão: só
                // a marca dela, e a conta sai do perfil que chegar com ela
                // (`aoConhecerConta`, R12-5-05).
                AppState.preferences.presencaWmeDesligar = { s: pend.s, em: pend.em };
            }
            // O `presencaWmeVisto` da fase 2 não é mais lido: sem carregar, o
            // próximo `savePreferences` já grava sem ele.
        }
    } catch (e) {}
}

// Devolve true quando MUDOU alguma coisa (pra quem chama saber se grava).
//
// Roda depois do `preferenciasCarregadas = true` de propósito: o
// `savePreferences` sai calado antes disso, e a anistia precisa PERSISTIR —
// senão ela reavalia a cada carga e o carimbo velho fica pra sempre no
// aparelho.
function aplicarAnistiaDaPresenca() {
    const p = AppState.preferences;
    if (p.presenca !== false) {
        // Ligado não tem contagem correndo. Carimbo sobrando é resíduo de uma
        // versão anterior ou de armazenamento editado à mão.
        if (p.presencaOffEm === undefined) return false;
        delete p.presencaOffEm;
        return true;
    }
    // Desligado SEM carimbo: não há de quando contar, então NÃO se conta.
    //
    // Isto já foi migração (carimbava a hora, pra quem desligou antes de a
    // anistia existir) e virou DEFESA quando o legado saiu, em 2026-09-10.
    // A diferença importa: a migração ESCREVIA, esta linha não faz nada.
    //
    // E ela não é opcional. Sem este `return`, `Date.now() - undefined` dá NaN,
    // `NaN < PRESENCA_ANISTIA_MS` é **false**, e o fluxo cai direto no religar
    // lá embaixo — ou seja, todo mundo que estava com a presença desligada
    // seria RELIGADO de uma vez, que é exatamente a mudança em massa que a
    // anistia de 9 dias existe pra evitar. MEDIDO antes de remover o ramo.
    // Vale pra qualquer origem do estado torto: armazenamento editado à mão,
    // gravação truncada, relógio maluco — não só pro legado que saiu.
    if (!Number.isFinite(p.presencaOffEm) || p.presencaOffEm <= 0) return false;
    // Relógio que andou pra trás dá diferença negativa: isso não é 9 dias.
    const decorrido = Date.now() - p.presencaOffEm;
    if (decorrido < PRESENCA_ANISTIA_MS) return false;
    p.presenca = true;
    delete p.presencaOffEm;
    // O "invisível" que ainda esperava ir pro WME era do desligar que a
    // anistia acabou de desfazer (ver `presencaWmeGravarPendente`).
    delete p.presencaWmeDesligar;
    return true;
}

// Modo Desenvolvedor: easter egg estilo Android. User toca 7 vezes na versão
// no rodapé (timeout de 3s entre taps reseta contador). Quando desbloqueado,
// uma seção "Avançado" aparece no modal de Preferências com toggle para ativar.
// Quando ativo, AppState.devMode.active = true bypassa restrições (hoje só o
// gate do undo). NÃO é segurança — qualquer um pode setar via DevTools.
// É só pra esconder de usuário comum.
function saveDevMode() {
    try {
        localStorage.setItem(DEVMODE_KEY, JSON.stringify(AppState.devMode));
    } catch (e) {}
}

// O modo dev como está no ARMAZENAMENTO, que as abas dividem. `null` quando não
// dá pra ler (armazenamento bloqueado): aí ninguém decide nada por ele.
function devModeDoArmazenamento() {
    try {
        const p = JSON.parse(localStorage.getItem(DEVMODE_KEY) || 'null');
        const unlocked = !!(p && p.unlocked);
        return { unlocked, active: unlocked && !!(p && p.active) };
    } catch (e) { return null; }
}
// O armazenamento DIZ que está desligado (desligado noutra aba, ou o "Sair" de
// outra aba). Só a leitura que deu certo decide — ilegível não desliga nada.
function modoDevDesligadoNoArmazenamento() {
    const m = devModeDoArmazenamento();
    return !!m && !m.active;
}

function loadDevMode() {
    try {
        const raw = localStorage.getItem(DEVMODE_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            AppState.devMode.unlocked = !!parsed.unlocked;
            AppState.devMode.active = !!parsed.active && !!parsed.unlocked;
            // O boot também precisa mostrar o FAB: quem já estava com o dev
            // ligado não vai desligar e religar só pra ele aparecer.
            setTimeout(atualizarFabDev, 0);
            diagAjustarRecursos();
        }
    } catch (e) {}
}

// ── Teclado virtual ────────────────────────────────────────────────────────
// Todo campo de texto é um teclado esperando pra ocupar metade da tela. No
// celular, o modal "Entrar com um código" ficava ATRÁS do teclado: campo e
// botões invisíveis, sem nada indicando que era só rolar. Aqui a altura coberta
// vira `--kb-inset`, que os modais usam pra subir e pra encolher (styles.css +
// `max-h-[calc(...)]` no HTML). É a segunda camada: a primeira é o
// `interactive-widget=resizes-content` do <meta viewport>, que alguns
// navegadores ignoram.
// A ação fica UNDO_WINDOW_MS (3s) no buffer do "Desfazer" ANTES de ir pro Waze — mas o contador
// já foi incrementado e salvo em localStorage na hora do swipe. Fechar a aba
// nessa janela fazia a ação sumir com o placar dizendo que ela aconteceu: o
// pedido voltava na próxima busca, mas o número ficava errado pra sempre. E
// fechar logo depois do último swipe não é caso raro — é como se termina de usar.
//
// `pagehide` cobre fechar/navegar. `visibilitychange` para oculto cobre o
// celular: quando o sistema mata uma aba em segundo plano, esse é o último
// callback confiável (page lifecycle). O preço é que trocar de app comita na
// hora, encurtando o "Desfazer" — e é o lado certo de errar: a ação ia comitar
// em 3s de qualquer jeito, enquanto perdê-la é dano permanente no placar.
function descarregarAcaoPendente() {
    // A exclusão ou a aprovação da foto que JÁ saiu da janela do Desfazer e
    // espera só a resposta do toque na lixeira (o Waze lento): solta agora, ela
    // sai com `keepalive` — antes ficava pendurada, e sumia com a página
    // (auditoria da rodada 13, R13-3-01, ver `vezLiberada`).
    soltarEsperasDoAquecimento();
    // As três escritas do lightbox têm a mesma janela e o mesmo risco: sair da
    // página com uma pendente a faria sumir depois de a tela já ter mudado.
    for (const p of [renomeacaoPendente, aprovacaoPendente, exclusaoPendente]) {
        if (!p) continue;
        if (typeof API !== 'undefined' && API.setSaindo) API.setSaindo(true);
        try { p.enviar(); } catch (e) { console.error('Falha ao descarregar:', e); }
    }
    if (!AppState.pendingAction) return;
    // Sem rede não há o que tentar: a decisão vai pra fila de saída de forma
    // SÍNCRONA, antes de a página morrer (ver `enfileirarSemRede`). Só o `false`
    // decide — `onLine === true` não prova rede, e aí vale o caminho de sempre.
    try {
        if (navigator.onLine === false && AppState.pendingAction.enfileirarSemRede
            && AppState.pendingAction.enfileirarSemRede()) return;
    } catch (e) {
        console.error('Falha ao enfileirar a ação pendente:', e);
    }
    // Fetch normal é cancelado no unload; keepalive sobrevive.
    if (typeof API !== 'undefined' && API.setSaindo) API.setSaindo(true);
    try {
        // O LOTE cancela em vez de despachar (ver `aoSair` no scheduleAction).
        // `true` grava o placar revertido: o número inflado já foi pro
        // armazenamento quando o lote foi agendado, e sem isto ele sobreviveria
        // ao recarregamento contando pedidos que nunca saíram.
        if (AppState.pendingAction.aoSair === 'cancel') AppState.pendingAction.cancel(true);
        // A decisão entra na fila de saída ANTES do envio (ver `descarregar`):
        // a página pode morrer antes da resposta — e o envio com ela, no
        // "lie-fi". Na fila, a reabertura sem rede já não a devolve como card
        // (`semOsJaDecididos`), e ela sai quando houver rede. O POUSO não vai
        // mais antes do envio: gravado sem a resposta, ele escondia o pedido de
        // uma decisão que talvez nunca tenha saído.
        else AppState.pendingAction.descarregar();
    } catch (e) {
        console.error('Falha ao descarregar a ação pendente:', e);
    }
}

function setupDescargaAoSair() {
    window.addEventListener('pagehide', () => {
        descarregarAcaoPendente();
        // A página SAI (fechar a aba, navegar, recarregar): as marcas desta aba
        // na fila de saída saem com ela, inclusive a do que está no ar (ver
        // `soltarReivindicacoes`). A aba só ESCONDIDA segue viva e as mantém.
        try { soltarReivindicacoes({ comAsDoAr: true }); } catch (e) { /* a saída segue */ }
        // E o "invisível" no ar: o carimbo dele sai do gravado (ver a função).
        try { presencaWmeSoltarAoSair(); } catch (e) { /* a saída segue */ }
    });
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') descarregarAcaoPendente();
    });
    // O FIM do modo "saindo" (a página voltou) não mora aqui: é o
    // `setupFimDoModoSaindo`, registrado antes de todo ouvinte da volta.
}

// A página VOLTOU (a pessoa trocou de app e retornou, ou ela voltou do bfcache,
// com o `pagehide` tendo ligado o modo): o modo "saindo" acaba. Sem isto ele
// ficava ligado pra sempre depois da primeira ida ao fundo com ação pendente, e
// TODA requisição seguinte ia com `keepalive` e sem o teto de 45 s — uma busca
// pendurada prendia a fila, e o login por cookies.txt grande estourava o limite
// de 64 KB do keepalive.
//
// E ele é registrado ANTES de todo outro ouvinte da volta (no `initApp`, antes
// do `setupAppListeners`), porque os ouvintes de um mesmo evento rodam na
// ordem em que foram registrados. Morava no `setupDescargaAoSair`, registrado
// DEPOIS: a presença (o `Presenca.montar()`, dentro do `setupAppListeners`)
// pede a lista na volta do fundo, e o pedido saía com o modo ainda ligado —
// com `keepalive` e sem o teto. Pendurado, ele segurava o `Presenca.pedindo`, e
// a lista, o token do tempo real e as confirmações de carona paravam até
// recarregar (auditoria da rodada 8, R8-5-02, medido no Chromium: aos 46,5 s o
// pedido seguia no ar, e tocar na pílula mandava 0 pedidos).
function setupFimDoModoSaindo() {
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible' && typeof API !== 'undefined' && API.setSaindo) API.setSaindo(false);
    });
    window.addEventListener('pageshow', () => { if (typeof API !== 'undefined' && API.setSaindo) API.setSaindo(false); });
}

// O banner do topo se ancora abaixo do header, e o header não tem altura fixa:
// cresce com a safe-area do iPhone e com a preferência de fonte do sistema.
// Número chutado no CSS erraria em algum aparelho — daí medir e publicar.
function setupAlturaDoHeader() {
    const header = document.querySelector('header');
    if (!header) return;
    const medir = () => {
        document.documentElement.style.setProperty('--header-h', header.getBoundingClientRect().height + 'px');
    };
    // A caixa de BORDA, não a de conteúdo (a padrão): a margem de segurança do
    // iPhone entra no cabeçalho como PADDING, e o padding que muda sem mudar o
    // conteúdo não dispara o observador da caixa de conteúdo. MEDIDO na emulação
    // (auditoria da rodada 11, R11-4-06): a margem que chega depois do resize
    // deixava o `--header-h` em 69 px com o cabeçalho em 116, e o "N esperando
    // envio" ia pra baixo dele. A caixa de borda inclui o padding; navegador sem
    // a opção a ignora e segue com a de conteúdo, como antes.
    if (typeof ResizeObserver === 'function') new ResizeObserver(medir).observe(header, { box: 'border-box' });
    window.addEventListener('resize', medir);
    medir();
}

// Só estes abrem teclado ou seletor do sistema. É ALLOWLIST, não denylist, e a
// direção importa: errar pra menos deixa um campo novo atrás do teclado (chato);
// errar pra mais devolve o bug que motivou esta função — o app tem 12 checkboxes
// e 70 botões, e `openModal` foca o primeiro focável do modal, então um seletor
// frouxo daria "campo focado" em quase toda abertura.
const CAMPOS_COM_TECLADO = 'textarea, select, [contenteditable=""], [contenteditable="true"], '
    + 'input[type="text"], input[type="search"], input[type="url"], input[type="tel"], '
    + 'input[type="email"], input[type="password"], input[type="number"], input[type="date"], '
    + 'input[type="time"], input[type="datetime-local"], input[type="month"], input[type="week"]';

function campoDeTextoFocado() {
    const a = document.activeElement;
    if (!a || typeof a.matches !== 'function') return false;
    try { return a.matches(CAMPOS_COM_TECLADO); } catch (e) { return false; }
}

// Quanto o teclado está cobrindo, em px — a decisão isolada pra poder ser testada.
// Três defesas, uma por modo de falha, e só a primeira conserta o bug relatado:
//
// 1. PORTÃO NO FOCO. O inset existe pra sair da frente do TECLADO, e não há
//    teclado sem campo focado. Sem o portão o app acreditava em qualquer leitura
//    do `visualViewport`: no PWA do iOS de um editor ela ficou cravada em 388px
//    com nada focado, e como o valor só é recalculado em `resize`/`scroll` do
//    visualViewport — que o scroll-lock do modal (`body{overflow:hidden}`)
//    impede de disparar — durou a sessão inteira. Medido no vídeo dele: o modal
//    de Filtros com 305pt de altura onde deviam ser 690pt.
// 2. TETO. Teclado nenhum ocupa 75% da janela (medido: iPhone SE 53%, paisagem
//    ~55%). Não é o conserto — é o limite do estrago se a leitura mentir COM um
//    campo focado. Folgado de propósito: teto apertado devolveria o defeito
//    original, com o campo atrás do teclado.
// 3. PISO de 80px: barra do navegador entrando/saindo não é teclado — reagir a
//    isso faria o modal pular a cada rolagem.
function insetDoTeclado(coberto, alturaJanela, temCampoFocado) {
    if (!temCampoFocado) return 0;
    if (!(coberto > 80)) return 0;
    const teto = Math.round((Number(alturaJanela) || 0) * 0.75);
    return Math.max(0, Math.min(coberto, teto));
}

function setupKeyboardInset() {
    const vv = window.visualViewport;
    if (!vv) return;
    let ultimoInset = null;
    const aplicar = () => {
        const coberto = Math.round(window.innerHeight - vv.height - vv.offsetTop);
        const foco = campoDeTextoFocado();
        const inset = insetDoTeclado(coberto, window.innerHeight, foco);
        document.documentElement.style.setProperty('--kb-inset', inset + 'px');
        // Só quando MUDA: `resize`/`scroll` do visualViewport disparam em rajada
        // enquanto o teclado sobe, e anel de 120 não sobrevive a isso. Este é o
        // fato que teria respondido em minutos o caso dos 11 modais achatados no
        // iOS — lá o inset ficou cravado em 388px SEM campo focado, e o arquivo
        // não trouxe uma linha do que levou até ali. Vai o `coberto` cru junto
        // do que foi APLICADO: a diferença entre os dois é a resposta.
        if (inset !== ultimoInset) {
            dfato('kb', { inset, coberto, foco, jan: window.innerHeight });
            ultimoInset = inset;
        }
    };
    vv.addEventListener('resize', aplicar);
    vv.addEventListener('scroll', aplicar);
    // O foco entra e sai sem que o visualViewport mexa (trocar de campo pra
    // botão, fechar o modal pelo scrim). Sem estes dois o portão acima só
    // valeria até a próxima vez que o teclado se mexesse — e era justamente
    // "nunca mais" que criava o bug. Adiados um tick porque no `focusout` o
    // `activeElement` ainda é o campo que está SAINDO.
    const aplicarDepois = () => setTimeout(aplicar, 0);
    document.addEventListener('focusin', aplicarDepois);
    document.addEventListener('focusout', aplicarDepois);
    aplicar();

    // Rede de segurança pra navegador sem nenhum dos dois mecanismos: leva o
    // campo focado pra área visível. O atraso espera o teclado assentar —
    // medir antes disso mede a tela errada.
    document.addEventListener('focusin', (e) => {
        const campo = e.target;
        if (!campo || typeof campo.matches !== 'function') return;
        if (!campo.matches('input, textarea, select')) return;
        if (!campo.closest('.modal-root')) return;
        setTimeout(() => {
            try { campo.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (err) {}
        }, 250);
    });
}

// ── Extensão do Chrome: só onde ela existe ─────────────────────────────────
// Chrome/Edge de Android e qualquer navegador de iOS não instalam extensão da
// Chrome Web Store. Oferecer isso num celular não é "opção de baixa
// prioridade": é beco sem saída — e ainda vinha marcado como "RECOMENDADO",
// mandando o editor justamente pro caminho que não funciona ali. Reordenar
// resolve o que é inconveniente; o que é impossível sai da frente.
// Os outros três caminhos (código, upload, colar) seguem visíveis, então
// errar a detecção não tranca ninguém do lado de fora.
// E só em navegador CHROMIUM de computador — Chrome, Edge, Brave, Opera: a
// extensão é da Chrome Web Store. No Firefox e no Safari ela não existe, e no
// iPad o Safari se anuncia como Mac: oferecê-la como caminho ali era o beco sem
// saída que a régua de "isto é acionável AQUI?" proíbe (auditoria de
// 2026-09-25). Com Client Hints, a marca "Chromium" (todo navegador Chromium a
// traz); sem eles (Firefox e Safari não têm), o `Chrome/` da UA sem ser celular.
//
// E `mobile: false` NÃO é "computador": o Chrome de TABLET Android se anuncia
// assim (a UA de tablet não tem "Mobile"), com `platform: "Android"` — e não
// instala extensão. Daí o sistema também ser conferido (auditoria de 2026-09-26).
// Limite conhecido, LIDO na fonte do Chromium (content_utils.cc): a "versão para
// computador" do Chrome no Android se anuncia `platform: "Linux"`, igual a um
// Linux de mesa, e ali a extensão segue oferecida — é a camuflagem funcionando.
function podeInstalarExtensao() {
    const dados = navigator.userAgentData;
    if (dados && typeof dados.mobile === 'boolean') {
        return !dados.mobile && !/Android|iOS/i.test(dados.platform || '')
            && (dados.brands || []).some((b) => /Chromium/i.test((b && b.brand) || ''));
    }
    const ua = navigator.userAgent || '';
    return /Chrome\//.test(ua) && !/Android|iPhone|iPad|iPod|Mobile|CriOS|EdgiOS/i.test(ua);
}

// As DUAS marcas, e a que a tela usa é a positiva: o card da extensão (e o
// passo dela na Ajuda) só aparece com `com-extensao`. Antes de o JS chegar não
// há nenhuma das duas, e aí a extensão fica escondida — era o celular mostrando
// "RECOMENDADO" enquanto o app.js vinha por rede lenta. A negativa fica pro
// diagnóstico (a classe do <html> vai nele): distingue "decidiu que não" de
// "o JS nem rodou".
function marcarSuporteAExtensao() {
    document.documentElement.classList.add(podeInstalarExtensao() ? 'com-extensao' : 'sem-extensao');
}

// ── iPhone com o app INSTALADO na tela de início ─────────────────────────────
// No iOS, o app instalado tem armazenamento SEPARADO do Safari. Apontar a câmera
// pro QR do pareamento abre o LINK no Safari: a sessão entra lá, e o app
// instalado segue na tela de entrada. Isto é conhecimento da PLATAFORMA, não
// medição — não há iPhone neste ambiente, e o WebKit do Playwright não simula
// app instalado (auditoria de 2026-09-26). Por isso o ajuste é só de TEXTO: onde
// a instrução mandava apontar a câmera, ela manda pro código digitado, que não
// passa pelo Safari. `navigator.standalone` só existe no iOS (e é `true` só no
// app instalado); o Android instalado divide o armazenamento com o Chrome.
function ajustarEntradaAoIPhoneInstalado() {
    if (navigator.standalone !== true) return;
    const trocas = [
        ['.auth-precondicao', 'data-i18n', 'auth.needsComputer.codigo'],
        ['.ajuda-passo-codigo', 'data-i18n-html', 'help.howToUse.codigoSemCamera'],
    ];
    for (const [seletor, atributo, chave] of trocas) {
        const el = document.querySelector(seletor);
        if (!el) continue;
        // A CHAVE troca (a troca de idioma relê dela); o texto sai do dicionário.
        el.setAttribute(atributo, chave);
        if (atributo === 'data-i18n') el.textContent = t(chave);
        else el.innerHTML = t(chave);
    }
}

// ── Convite de instalação do PWA ───────────────────────────────────────────
// Sem `preventDefault()`, o Chrome mostra a própria barra de instalação: fica
// grudada no rodapé, tapa conteúdo (inclusive o meio dos modais) e não sai da
// frente. Convite persistente que cobre conteúdo é anti-padrão M3/HIG. Então
// guardamos o evento e oferecemos a instalação num lugar previsível — o menu
// de Ajuda — onde o editor decide quando.
let promptInstalacao = null;

// Já rodando instalada? Nada de convidar quem já aceitou. `display-mode` cobre
// Android/desktop; `navigator.standalone` é o jeito do iOS, que não implementa
// a media query.
function appJaInstalada() {
    try {
        if (window.matchMedia('(display-mode: standalone)').matches) return true;
        if (window.matchMedia('(display-mode: window-controls-overlay)').matches) return true;
    } catch (e) { /* matchMedia pode faltar em WebView antiga */ }
    return navigator.standalone === true;
}

// iOS não tem `beforeinstallprompt`: no Safari a instalação é manual. Sem
// detectar isso, o iPhone fica SEM CAMINHO NENHUM — e o pareamento por QR
// empurra justamente pro celular. iPadOS se identifica como Mac desde o iOS 13,
// daí o teste extra por toque.
function ehIOS() {
    const ua = navigator.userAgent || '';
    if (/iPad|iPhone|iPod/.test(ua)) return true;
    return /Macintosh/.test(ua) && (navigator.maxTouchPoints || 0) > 1;
}

// O navegador do iPhone que NÃO é o Safari: o Chrome (CriOS), o Firefox (FxiOS)
// e o Edge (EdgiOS). Todo navegador do iPhone é WebKit por baixo, e a UA traz a
// marca dele. O convite mandava tocar "na barra do Safari" a quem não está no
// Safari — e o QR do pareamento abre no navegador PADRÃO do iPhone, que pode
// ser um desses (R13-7-03, MEDIDO com a UA de cada um no WebKit; auditoria de
// 2026-10-07).
function navegadorDoIOSForaDoSafari() {
    return /\b(?:CriOS|FxiOS|EdgiOS)\//.test(navigator.userAgent || '');
}

// A versão do iOS que a UA diz ("iPhone OS 16_3"; no iPad, "CPU OS 16_4"), como
// [maior, menor]. `null` quando ela não vem: o iPad que se anuncia como Mac.
function versaoDoIOS() {
    const m = /(?:iPhone|CPU) OS (\d+)_(\d+)/.exec(navigator.userAgent || '');
    return m ? [Number(m[1]), Number(m[2])] : null;
}

// Dá pra pôr o app na Tela de Início DAQUI? No Safari, sempre. Nos outros
// navegadores do iPhone, só a partir do iOS 16.4: antes dele o menu de
// compartilhar deles não tem o "Adicionar à Tela de Início", e o convite seria o
// beco sem saída que a régua "isto é acionável AQUI?" proíbe — ele não aparece,
// como a extensão no celular. É conhecimento da PLATAFORMA, não medição: não há
// iPhone neste ambiente. Sem a versão na UA (o iPad que se diz Mac), vale como
// recente: o iPadOS de antes do 16.4 é raro, e esconder tiraria o caminho de quem
// pode.
function iOSAdicionaATelaDeInicioAqui() {
    if (!navegadorDoIOSForaDoSafari()) return true;
    const v = versaoDoIOS();
    return !v || v[0] > 16 || (v[0] === 16 && v[1] >= 4);
}

const CHAVE_INSTALL_DISPENSADO = 'waze_places_install_dispensado';

function convitePodeAparecer() {
    if (appJaInstalada()) return false;
    if (safeLS && safeLS.get && safeLS.get(CHAVE_INSTALL_DISPENSADO) === '1') return false;
    // Só há o que oferecer se houver prompt (Chrome/Android/desktop) ou se for
    // iOS, onde mostramos o passo a passo manual — onde ele funciona.
    return !!promptInstalacao || (ehIOS() && iOSAdicionaATelaDeInicioAqui());
}

// O convite vive no "Tudo limpo!" porque é o ÚNICO momento em que o editor
// terminou algo: não há próxima ação esperando e a tela já é de festa. Em
// qualquer outro lugar ele disputaria com o gesto.
function atualizarConviteInstalar() {
    const box = document.getElementById('installInvite');
    if (!box) return;
    // Só no painel de quem terminou a fila (ver `filaTerminouLimpa`). O convite
    // mora DENTRO do painel vazio, então fora dele não aparece de qualquer jeito;
    // é aqui, e não só no `showNoPlaces`, porque o prompt do navegador chega a
    // qualquer hora (`beforeinstallprompt`) e redesenha o convite por conta própria.
    const mostra = convitePodeAparecer() && filaTerminouLimpa();
    box.classList.toggle('hidden', !mostra);
    if (!mostra) return;
    // Com prompt: botão. Sem prompt e iOS: passo a passo. Nunca os dois.
    document.getElementById('installInviteBtn').classList.toggle('hidden', !promptInstalacao);
    document.getElementById('installIosSteps').classList.toggle('hidden', !!promptInstalacao);
    // O 1º passo diz ONDE está o "Compartilhar": na barra do Safari, ou no menu
    // do navegador fora dele (R13-7-03). A CHAVE troca — a troca de idioma relê
    // dela —, e o texto sai do dicionário.
    const passo = !promptInstalacao && document.getElementById('installIosStep1');
    if (!passo) return;
    const chave = navegadorDoIOSForaDoSafari() ? 'install.ios.step1Navegador' : 'install.ios.step1';
    if (passo.getAttribute('data-i18n-html') === chave) return;
    passo.setAttribute('data-i18n-html', chave);
    passo.innerHTML = t(chave);
}

function atualizarBotaoInstalar() {
    const btn = document.getElementById('installAppBtn');
    if (btn) btn.classList.toggle('hidden', !promptInstalacao || appJaInstalada());
    atualizarConviteInstalar();
}

function setupInstalarApp() {
    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        promptInstalacao = e;
        atualizarBotaoInstalar();
    });
    window.addEventListener('appinstalled', () => {
        promptInstalacao = null;
        atualizarBotaoInstalar();
    });
    // Os três botões SOMEM depois do toque (o convite dispensado, o prompt que é
    // de uso único), e com eles o foco de quem usa o TECLADO, que caía no <body>
    // — com a Ajuda (`aria-modal`) ainda aberta, no caso do botão dela (R6-7-12,
    // auditoria de 2026-10-01). Ele vai a um vizinho que FICA: no painel vazio, o
    // "Verificar novamente"; na Ajuda, o ✕ dela. Só pelo teclado, como no resto
    // do app (`veioDoTeclado`): quem usa o dedo não tem o foco movido. E o foco
    // num botão que acabou de sumir ainda É ele até o navegador o soltar (no
    // quadro seguinte): por isso a pergunta é "está nele ou perdido".
    const devolverSeSumiu = (botao, vizinho) => {
        if (document.activeElement === botao || focoPerdido()) devolverFoco(document.getElementById(vizinho));
    };
    const instalar = async (ev, vizinho) => {
        if (!promptInstalacao) return;
        const botao = veioDoTeclado(ev) ? ev.currentTarget : null;
        promptInstalacao.prompt();
        // O evento é de uso único: depois de escolher, some de qualquer jeito.
        try { await promptInstalacao.userChoice; } catch (err) {}
        promptInstalacao = null;
        atualizarBotaoInstalar();
        if (botao) devolverSeSumiu(botao, vizinho);
    };
    document.getElementById('installAppBtn')?.addEventListener('click', (ev) => instalar(ev, 'closeHelp'));
    document.getElementById('installInviteBtn')?.addEventListener('click', (ev) => instalar(ev, 'reloadBtn'));
    document.getElementById('installDismissBtn')?.addEventListener('click', (ev) => {
        const botao = veioDoTeclado(ev) ? ev.currentTarget : null;
        // "Agora não" é pra valer: sem persistir, a fila zerar de novo traria o
        // convite de volta, e convite que não aceita não é convite.
        safeLS.set(CHAVE_INSTALL_DISPENSADO, '1');
        atualizarConviteInstalar();
        if (botao) devolverSeSumiu(botao, 'reloadBtn');
    });
    atualizarBotaoInstalar();
}

function setupDevModeTapTrigger(el) {
    let tapCount = 0;
    let resetTimer = null;
    el.addEventListener('click', () => {
        if (AppState.devMode.unlocked) return;
        tapCount++;
        const hint = document.getElementById('devTapHint');
        const limparHint = () => {
            if (hint) { hint.textContent = ''; hint.classList.add('hidden'); hint.classList.remove('block'); }
        };
        if (resetTimer) clearTimeout(resetTimer);
        // Parou de tocar? zera a contagem E some com o countdown, senão ficaria
        // "faltam 2" pendurado ao lado da versão para sempre.
        resetTimer = setTimeout(() => { tapCount = 0; limparHint(); }, DEVMODE_TAP_TIMEOUT_MS);
        const remaining = DEVMODE_TAPS_NEEDED - tapCount;
        if (remaining === 0) {
            AppState.devMode.unlocked = true;
            saveDevMode();
            tapCount = 0;
            limparHint();
            // O toast de conquista é seguro: já desbloqueou, não há mais toque a
            // receber. É o do COUNTDOWN que não podia ser toast (ver abaixo).
            if (window.showToast) window.showToast(t('toast.devUnlocked'), 'success');
        } else if (remaining > 0 && remaining <= 3) {
            // Countdown fica ao LADO da versão, nunca num toast. O toast é
            // bottom-center em z-[70] e cobria o próprio alvo: do 5º toque em
            // diante quem recebia o clique era ele, os 3 últimos toques não
            // chegavam e o dev mode era impossível de desbloquear — em todo
            // aparelho, desde sempre. Overlay transitório não pode ficar por
            // cima de um alvo que ainda precisa ser tocado.
            if (hint) {
                hint.textContent = t(remaining === 1 ? 'toast.devCountdownUm' : 'toast.devCountdown', { n: remaining });
                // `block` e não `inline`: em tela estreita o texto embolava com o
                // serial da versão em vez de virar uma linha própria.
                hint.classList.remove('hidden');
                hint.classList.add('block');
            }
        }
    });
}

function updateDevBadge() {
    const badge = document.getElementById('devModeBadge');
    if (!badge) return;
    badge.classList.toggle('hidden', !AppState.devMode.active);
}

function renderDevModeSection() {
    const section = document.getElementById('devModeSection');
    const checkbox = document.getElementById('prefDevModeActive');
    if (!section || !checkbox) return;
    if (AppState.devMode.unlocked) {
        section.classList.remove('hidden');
        checkbox.checked = !!AppState.devMode.active;
    } else {
        section.classList.add('hidden');
        checkbox.checked = false;
    }
}

// A linha REQUEST do filtro (e a função que a mostrava) MORREU: ela virou as
// quatro do WME — atualização de detalhes, local marcado, excluir local e foto
// sinalizada. Fica o registro do que ela custou enquanto esteve fechada atrás
// do modo dev, porque a lição vale pro próximo gate: numa fila real de 137
// pedidos, 135 eram REQUEST — o editor abria o app e via DOIS. Meça quanto da
// fila um gate esconde antes de deixá-lo fechado mais um mês.
//
// Não há mais tipo gated por dev mode. A função fica como ponto de extensão
// (o próximo recurso a ser solto passa por aqui) e para não quebrar os call
// sites, mas hoje não tira nada de ninguém — tirava REQUEST do filtro salvo,
// que era justamente o que mantinha o editor sem ver 98% da fila.
function enforceDevGatedFilters() {
    /* nada gated no momento */
}

// Gate de experiência pro toggle "Permitir desfazer ações".
// Ideia: novatos não conseguem desligar o undo até pegarem ritmo. Editores de
// nível mais alto têm cota menor (são mais experientes).
// Fórmula: ceil(UNDO_GATE_BASE / (rank + 1)). Waze devolve rank 0-indexed:
//   rank 5 (L6) → 10 PURs, rank 4 (L5) → 12, rank 3 (L4) → 15, rank 2 (L3) → 20,
//   rank 1 (L2) → 30, rank 0 (L1) → 60.
// A linha do L1 é inalcançável desde que a entrada virou L2+AM — fica na tabela
// porque a fórmula a produz, não porque alguém a atinge.
// "PURs tratados" = read + rejected (skipped não treina o ritmo de ação destrutiva).
// Staff são isentos. Esta NÃO é proteção de segurança — é UX/educação. localStorage
// pode ser editado pelo user esperto; o objetivo é proteger quem é genuinamente novato.
//
// Histórico da base, porque o parágrafo que estava aqui ficou MENTINDO: ele
// argumentava contra "baixar mais (30/60)" com os números `L5=6 vs L6=5`, que
// são de base 30 — e foi escrito quando a base era 300. A base já era 120 e o
// texto seguia decidindo por uma tabela que não existia mais. 3000 → 300 → 120
// → 60; quem for mexer de novo, refaça a conta em vez de herdar a frase.
//
// 60 é decisão do owner (2026-09-09), tomada junto com baixar a entrada pra
// L2+AM, e com o custo na mesa: o gate inteiro vale ~2,4s de espera por pedido
// tratado (2431ms travado contra 33ms sem trava), então ele custa 1 a 2 minutos
// UMA vez na vida — a 120 eram ~144s pro L2 e ~48s pro L6; a 60 são ~72s e
// ~24s. O que se perde no topo: o L6 desbloqueia em 10 pedidos, ~25 segundos de
// trabalho, o que é quase nenhum gate. Se um dia isso incomodar, o caminho não
// é mexer na base (ela move todo mundo junto) — é achatar a curva por baixo,
// tipo um piso, que baixa as cotas altas sem isentar quem tem rank.
const UNDO_GATE_BASE = 60;

function getUndoTreatedCount() {
    return (AppState.stats.read || 0) + (AppState.stats.rejected || 0);
}

function guardarPerfilDoPortao(p) {
    if (!p || typeof p.rank !== 'number') return;
    safeLS.set(PERFIL_GATE_KEY, JSON.stringify({ rank: p.rank, isStaff: !!p.isStaff }));
    // O perfil ACABOU de ficar conhecido, e era a única peça que faltava pra
    // estabelecer a linha de base da conquista. Aqui e não no `initApp` porque
    // é este o momento em que a cota deixa de ser Infinity — nas DUAS entradas
    // de perfil, sem depender de quem lembra de chamar.
    initUndoGateSeen();
}

// O perfil que a COTA usa: o vivo, se houver; senão o último que carregou.
// A cota mede a EXPERIÊNCIA da pessoa, que não muda porque a rede caiu.
function perfilDoPortao() {
    if (AppState.profile && typeof AppState.profile.rank === 'number') return AppState.profile;
    try {
        const c = JSON.parse(safeLS.get(PERFIL_GATE_KEY) || 'null');
        return c && typeof c.rank === 'number' ? c : null;
    } catch (e) { return null; }
}

function getUndoUnlockThreshold() {
    const p = perfilDoPortao();
    if (p && p.isStaff) return 0;
    const rank = p && p.rank;
    if (typeof rank !== 'number') return Infinity;
    return Math.ceil(UNDO_GATE_BASE / (rank + 1));
}

// ── Aviso de desbloqueio do gate ──────────────────────────────────────────
// Antes disso o desbloqueio era INVISÍVEL: a pessoa cruzava a cota e nada
// acontecia — só descobriria abrindo Filtros → Preferências por acaso. Esforço
// feito e não reconhecido é pior que não ter recompensa.
//
// Repare que usa a comparação CRUA (tratados >= cota), e não canDisableUndo():
// aquele devolve true com o Modo Desenvolvedor ligado, e aí ligar o dev mode
// dispararia um "parabéns" por conquista nenhuma.
function undoGateAtingido() {
    return getUndoTreatedCount() >= getUndoUnlockThreshold();
}

// Chamado quando perfil E stats já existem. Quem JÁ está acima da cota nasce
// marcado como "visto": parabenizar por trabalho feito antes de a comemoração
// existir soaria falso — e apareceria pra toda a base no primeiro deploy.
function initUndoGateSeen() {
    // Mesma invariante do savePreferences: sem ter lido, não se decide.
    if (!preferenciasCarregadas) return;
    if (typeof AppState.preferences.undoGateSeen === 'boolean') return;
    // Sem cota conhecida NÃO HÁ decisão a tomar — adiar é o certo. Cota Infinity
    // responderia "não atingiu" pra quem tem 200 tratados, e o pedido seguinte
    // viraria uma falsa conquista pelo acumulado de meses.
    if (!isFinite(getUndoUnlockThreshold())) return;
    AppState.preferences.undoGateSeen = undoGateAtingido();
    savePreferences();
}

// Quantos pedidos o placar já contou e a janela do Desfazer ainda pode devolver.
function pedidosNaJanelaDoDesfazer() {
    const p = AppState.pendingAction;
    if (!p || (p.type !== 'read' && p.type !== 'reject')) return 0;
    return Array.isArray(p.place) ? p.place.length : 1;
}

// Quantos pedidos o Waze JÁ CONFIRMOU: o acumulador do Histórico só anda no
// pouso (`recordHistory`, sempre ANTES do `registrarAcaoConfirmada`), nunca no
// gesto — o placar anda no gesto e conta também o que ainda está no ar e na
// fila de saída.
function pedidosConfirmados() {
    const total = (loadHistory() || {})._total || {};
    return (total.read || 0) + (total.rejected || 0);
}

// Chamado na CONFIRMAÇÃO de uma decisão (ver `updateStats`), e conta só o que
// foi CONFIRMADO. Descontar só a janela do Desfazer não bastava: com duas
// decisões no ar (rede lenta), a confirmação da 9ª já avisava "10 pedidos
// tratados", com a 10ª ainda no Waze — recusada, o placar voltava a 9, o
// interruptor ficava travado ("falta 1") e a marca de "visto" já estava gravada,
// então o desbloqueio de verdade nunca era anunciado (R7-7-05, auditoria de
// 2026-10-02; o mesmo com um "Rejeitar os N" no ar). O placar sem a janela
// entra junto, pelo MENOR dos dois: o aviso leva ao interruptor, e ele obedece
// ao placar (`canDisableUndo`) — avisar com o interruptor travado é o defeito.
function checkUndoGateUnlock() {
    // `undefined` = a LINHA DE BASE ainda não foi estabelecida: `initUndoGateSeen`
    // não pôde decidir se este acumulado é trabalho de ANTES. Celebrar aqui
    // parabeniza pelo histórico, e é o que fazia o aviso sair a cada recarga.
    // Só `false` — decisão tomada, ainda não atingiu — libera a comemoração.
    if (typeof AppState.preferences.undoGateSeen !== 'boolean') return;
    if (AppState.preferences.undoGateSeen) return;
    // Com o TREINO aberto, espera — sem marcar como visto. A decisão que cruza a
    // cota é REAL (a da janela do Desfazer que o "Praticar" despacha), mas o
    // banner dourado e o confete saíam sobre o card de TREINO, debaixo da faixa
    // "nada é enviado ao Waze", e o aviso é de uma vez na vida: gasto ali, nunca
    // mais aparecia onde o interruptor vale (R8-7-01, auditoria de 2026-10-03).
    // Quem avisa é a próxima confirmação fora do treino: ela refaz esta mesma
    // conta, e o que o Waze confirmou aqui segue contado nela.
    if (typeof Treino !== 'undefined' && Treino.ativo === true) return;
    const tratados = Math.min(getUndoTreatedCount() - pedidosNaJanelaDoDesfazer(), pedidosConfirmados());
    if (tratados < getUndoUnlockThreshold()) return;
    // Nem por baixo de uma camada, nem com a página escondida (R13-7-01): o
    // banner e o confete saíam onde ninguém via, e a marca abaixo o gastava.
    if (!avisoDeUmaVezSaiAgora('desbloqueio')) return;
    AppState.preferences.undoGateSeen = true;
    // Este aviso já abre a mesma porta. Sem isto, quem cruza a cota com 20
    // janelas sem desfazer nas costas (o L6 passa em 20 pedidos — dá empate)
    // levaria os dois banners quase juntos, dizendo a mesma coisa duas vezes.
    AppState.preferences.dicaDesfazerVista = true;
    savePreferences();
    dispararConfeteNaFila();
    showToast(
        t('toast.undoUnlocked', { n: getUndoUnlockThreshold() }),
        'achievement',
        // 20s. A mensagem tem 16 palavras: a ~200 palavras/min de leitura atenta
        // são ~4,8s só de leitura, mais notar que apareceu e decidir se toca —
        // os 8s anteriores ficavam exatamente no limite, e o owner sentiu isso
        // usando. 20s cobre leitura tranquila com folga.
        //
        // Ficar aqui não custa mais nada: desde que virou banner no TOPO, ele
        // não tapa botão nenhum (medido em 4 aparelhos × 2 temas), e aparece uma
        // vez na vida (undoGateSeen). Toque dispensa e abre as Preferências.
        //
        // O desenho que dispensaria o número — banner persistente com ✕ próprio,
        // que é o comportamento de banner no M3 — foi oferecido e o owner
        // preferiu o ajuste simples.
        20000,
        abrirPreferenciaDoUndo
    );
}

// Confete por cima da fila, reaproveitando o mesmo CSS do "Tudo limpo!".
// Some sozinho — nada fica pendurado no DOM.
function dispararConfeteNaFila() {
    if (prefersReducedMotion()) return;
    const stack = document.getElementById('cardStack');
    if (!stack) return;
    const burst = document.createElement('div');
    burst.className = 'confetti confetti-burst';
    burst.setAttribute('aria-hidden', 'true');
    burst.innerHTML = '<span></span>'.repeat(12);
    stack.appendChild(burst);
    setTimeout(() => burst.remove(), 2200);
}

// Abre o modal JÁ na aba pedida, sem esperar a rede.
//
// `openFiltersModal` termina com `await popularPaisEstado()`, que vai ao Waze.
// Esperar a promise INTEIRA antes de trocar de aba deixava o editor olhando a
// aba Filtros por 480ms em rede boa e 1337ms em rede ruim (os números estão
// medidos no comentário de lá) — e só então a tela saltava pra outra aba. Era
// o que o caminho do Desfazer fazia; hoje os dois passam por aqui.
//
// Não esperar é seguro por razão ESTRUTURAL, não por sorte: tudo que importa
// pra este desvio — `renderHistory()` e o `openModal()` — é SÍNCRONO e roda
// ANTES do primeiro `await` da função. Chamar sem `await` executa esse trecho
// inteiro no mesmo tick, então a troca de aba acontece antes de qualquer
// pintura e ninguém vê a aba errada.
//
// `test/patentes.test.mjs` cobra essa ordem. Um `await` novo enfiado antes do
// `renderHistory()` quebraria isto EM SILÊNCIO — e de um jeito pior que a
// piscada: a aba Histórico apaga as marcas ao abrir (`marcarConquistasVistas`),
// então o painel renderizaria DEPOIS, já sem nada marcado.
function abrirModalNaAba(aba) {
    const pendente = openFiltersModal();
    switchFilterTab(aba);
    return pendente;
}

// Leva direto ao interruptor em vez de mandar procurar em Filtros → Preferências.
async function abrirPreferenciaDoUndo() {
    const pendente = abrirModalNaAba('filtersTabPrefs');
    const linha = document.getElementById('prefUndoRow');
    if (linha && !prefersReducedMotion()) {
        linha.classList.remove('pref-highlight');
        void linha.offsetWidth;   // reflow: sem isso a animação não reinicia
        linha.classList.add('pref-highlight');
        linha.addEventListener('animationend', () => linha.classList.remove('pref-highlight'), { once: true });
    }
    await pendente;
}

// O MESMO desvio, para o ponto no botão de Filtros: leva direto ao que
// destravou, em vez de largar a pessoa na aba Filtros pra procurar entre 16
// células. É o irmão do aviso do Desfazer — mudou o jeito de ANUNCIAR (ponto
// discreto em vez de banner, decisão do owner em 2026-09-16), não o que
// acontece quando a pessoa aceita o convite.
async function abrirConquistaNova() {
    const pendente = abrirModalNaAba('filtersTabHistory');
    destacarConquistaNova();
    await pendente;
}

// Rola até o que destravou e pisca uma vez.
//
// O ALVO pode ser uma célula da vitrine OU o cartão da patente: patente NÃO
// tem célula, então mirar só na grade deixaria sem alvo justamente quem subiu
// de patente — e o ponto teria aceso mesmo assim.
//
// A classe não precisa de limpeza no fechamento do modal (a regra do
// `LIMPEZA_AO_FECHAR`): o `renderHistory()` reescreve o innerHTML do painel a
// cada abertura, então ela não sobrevive nem ao próximo `openFiltersModal`.
function destacarConquistaNova() {
    const painel = document.getElementById('filtersPanelHistory');
    if (!painel) return;
    const novos = painel.querySelectorAll('.conq-card.nova, .conq-cel.nova');
    if (!novos.length) return;
    // O primeiro em ordem de DOM. O cartão da patente fica ACIMA da grade,
    // então quem subiu de patente e ganhou conquista na mesma ação vê a
    // patente primeiro — a mesma ordem em que as duas coisas estão na tela.
    //
    // `center` e não `nearest` (que é o que a dica da conquista usa): ali o
    // gesto é da pessoa e rolar o mínimo evita mexer a tela sob o dedo; aqui
    // NINGUÉM rolou nada, o app é que está apontando, e deixar o alvo colado
    // na borda inferior seria apontar pra beira da tela.
    novos[0].scrollIntoView({ block: 'center' });
    // O pulso é ENFEITE, e sai inteiro em reduced-motion: sem ele a pessoa
    // continua caindo na aba certa, com o alvo na tela e o contorno âmbar que
    // já existia. O que aponta é a ROLAGEM, não a animação.
    if (prefersReducedMotion()) return;
    novos.forEach((el) => {
        el.classList.remove('conq-alvo');
        void el.offsetWidth;   // reflow: sem isso a animação não reinicia
        el.classList.add('conq-alvo');
        el.addEventListener('animationend', () => el.classList.remove('conq-alvo'), { once: true });
    });
}

// ── Dica por COMPORTAMENTO: "você nunca desfaz" ───────────────────────────
// O aviso de desbloqueio dispara na TRANSIÇÃO de cruzar a cota — e por isso
// nunca alcança quem já estava acima dela quando a comemoração foi lançada
// (`initUndoGateSeen` marca essa pessoa como "já viu", pra não parabenizar por
// trabalho anterior ao deploy). O efeito colateral é que os editores MAIS
// ativos são justamente os que nunca ficam sabendo que a espera pode ser
// desligada — e são os que mais perdem com ela: 2431ms por pedido contra 33ms.
//
// Este gatilho não depende de transição nenhuma: conta janelas do Desfazer que
// expiraram SEM ninguém desfazer — evidência do próprio editor de que, pra ele,
// o recurso é só espera. Dispara uma vez.
//
// O LIMIAR NÃO É NÚMERO ESCOLHIDO A DEDO: é um orçamento de tempo. Quanto da
// vida do editor o app deixa evaporar antes de mencionar que existe um
// interruptor. Um minuto é a régua — dá pra sentir, e ainda é um oitavo do que
// 200 pedidos custam (~8 min).
const ESPERA_DESPERDICADA_ANTES_DA_DICA_MS = 60000;

// Só a expiração NATURAL conta (ver registrarJanelaSemUndo), e uma janela que
// expira sozinha custa exatamente UNDO_WINDOW_MS de tela travada: enquanto ela
// corre, acoesTravadas() barra botão, gesto e tecla. Então o limiar é o orçamento
// dividido pelo custo de UMA janela — hoje 60000/3000 = 20, o mesmo valor de
// antes, agora derivado. Mexer no UNDO_WINDOW_MS reajusta sozinho, porque o que
// o app promete é o MINUTO, não o vinte.
//
// Rank não entra aqui, de propósito: a cota do gate escala por rank porque mede
// COMPETÊNCIA, e rank é proxy razoável disso. Isto mede PREFERÊNCIA revelada pelo
// comportamento — existe L6 cauteloso e L1 apressado, e um minuto perdido é um
// minuto perdido nos dois. Escalar por rank também disparia na hora pra quem a
// dica existe: `stats` é acumulado (waze_places_stats), então quem já está muito
// acima da cota satisfaz "cota + N" antes de tocar em nada, sem evidência alguma.
const DICA_SEM_UNDO = Math.ceil(ESPERA_DESPERDICADA_ANTES_DA_DICA_MS / UNDO_WINDOW_MS);

// Só a expiração natural conta. `execute()` forçado (sair da página, trocar
// filtro) despacha sem dar a janela inteira — não é a pessoa decidindo não
// desfazer, e contar isso inflaria a evidência.
function registrarJanelaSemUndo() {
    AppState.preferences.semUndoSeguidas = (AppState.preferences.semUndoSeguidas || 0) + 1;
    savePreferences();
    checkDicaDesfazer();
}

function zerarJanelasSemUndo() {
    if (!AppState.preferences.semUndoSeguidas) return;
    AppState.preferences.semUndoSeguidas = 0;
    savePreferences();
}

function checkDicaDesfazer() {
    if (AppState.preferences.dicaDesfazerVista) return;
    if (AppState.preferences.undoEnabled === false) return;   // já desligado: nada a oferecer
    // A cota acabou de ser cruzada e a comemoração dela vem na CONFIRMAÇÃO
    // que a completar (ver `checkUndoGateUnlock`: conta só o confirmado): ela
    // já diz isto, e os dois banners sairiam quase juntos dizendo a mesma coisa.
    // Recusada a decisão que faltava, o placar desce e o `canDisableUndo` abaixo
    // segura a dica do mesmo jeito.
    if (AppState.preferences.undoGateSeen === false && undoGateAtingido()) return;
    if ((AppState.preferences.semUndoSeguidas || 0) < DICA_SEM_UNDO) return;
    // Nunca ofereça o que não dá pra fazer AQUI: sem passar a cota o toggle está
    // desabilitado, e a dica viraria beco sem saída. O contador continua correndo
    // — quando a cota cair, a evidência já está pronta.
    if (!canDisableUndo()) return;
    // Nem por baixo de uma camada, nem com a página escondida (R13-7-01): a
    // janela vence sozinha com os Filtros abertos, e a dica saía debaixo deles.
    if (!avisoDeUmaVezSaiAgora('dica')) return;
    AppState.preferences.dicaDesfazerVista = true;
    savePreferences();
    showToast(
        // {undoSeg} é global (setI18nVars) — não passa aqui de propósito, pra ter
        // UMA definição servindo esta frase e a de prefs.undo.desc, que é aplicada
        // por applyI18n() e não tem call site onde passar parâmetro.
        t('toast.undoHint', { n: DICA_SEM_UNDO }),
        'hint',
        // Mesma régua do aviso de conquista: banner do topo, com ação, uma vez
        // na vida. 20s cobrem leitura tranquila e decisão sem correria.
        20000,
        abrirPreferenciaDoUndo
    );
}

function canDisableUndo() {
    // Modo Desenvolvedor bypassa o gate de experiência completamente.
    if (AppState.devMode && AppState.devMode.active) return true;
    return getUndoTreatedCount() >= getUndoUnlockThreshold();
}

// A ação sai NA HORA, sem a janela do Desfazer? É a MESMA condição do
// `scheduleAction`: a preferência desligada só vale com a cota do gate. Quem
// PROMETE (ou não) a janela pergunta aqui — o fim do treino e a folha do autor
// diziam "o Desfazer te dá 3s" e "tocar já escreve no Waze" sem olhar, e cada
// frase mentia num dos dois estados (auditoria de 2026-09-29, A6 e A10).
// `test/textos-desfazer.test.mjs` cobra que as duas condições sejam a mesma.
function semJanelaDeDesfazer() {
    return AppState.preferences.undoEnabled === false && canDisableUndo();
}

function renderPularGuardaPref() {
    const cb = document.getElementById('prefPularGuarda');
    if (cb) cb.checked = AppState.preferences.pularGuarda === true;
    // A linha do offline se redesenha junto: ela tem cinco estados e o modal é
    // por onde a pessoa vem olhar. Abrir o modal também é gesto — sem isto,
    // abrir pra conferir encontraria a varredura dormindo.
    const off = document.getElementById('prefOfflineDisponivel');
    if (off) off.checked = AppState.preferences.offlineDisponivel === true;
    offlineMarcarGesto();
    offlineTalvezVarrer();   // quem veio conferir vê a preparação acontecendo, não um "Pronto" velho
    atualizarLinhaDoOffline(0, 0);
}

// O texto do selo de arrastar-pra-cima. Fonte única porque são DOIS chamadores
// (o card que nasce e a preferência que muda com o card já na tela), e a regra
// de consistência do projeto cobra que o que o app FAZ e o que ele DIZ sejam a
// mesma coisa: com a preferência ligada, o ↑ guarda — então ele tem que dizer.
//
// Escreve o ATRIBUTO e deixa o applyI18n traduzir, em vez de cravar o texto:
// assim trocar de idioma com o card na tela reescreve o selo certo (o card vive
// no documento, então o applyI18n global o alcança).
function atualizarSeloDePular(card, place) {
    const alvo = card || cardDaFrente();
    const el = alvo && alvo.querySelector('.swipe-stamp-up span[data-i18n]');
    if (!el) return;
    // O selo promete a ⭐ só onde o ↑ a MANDA: a régua do `handleSkip`, que é a do
    // treino (`Treino.pularGuardaria`) — o "Pular guarda o pedido" ligado e o pedido
    // sem a estrela, nem a do card (`isStarred`, R9-7-06) nem a que o app já deu
    // (`estreladoPeloApp`, R10-2-05). Dizia "Pular ⭐" num pedido já estrelado,
    // onde o ↑ não manda nada (o que o app MOSTRA e o que ele FAZ; lote 15). O
    // `montarCard` passa o pedido (o card ainda não foi registrado); os outros
    // chamadores falam do card da frente. Sem pedido conhecido, só a preferência.
    const p = place || pedidoDoCard(alvo);
    const guarda = AppState.preferences.pularGuarda === true && (!p || Treino.pularGuardaria(p));
    el.setAttribute('data-i18n', guarda ? 'card.stamp.skipGuarda' : 'card.stamp.skip');
    if (typeof applyI18n === 'function') applyI18n(alvo);
}

function renderPresencaPref() {
    const cb = document.getElementById('prefPresenca');
    if (cb) cb.checked = AppState.preferences.presenca !== false;
}

function renderUndoGateUI() {
    // O perfil já existe quando isto roda, então é o momento certo de decidir
    // se este usuário nasce com o aviso "já visto" (quem já passou da cota).
    initUndoGateSeen();
    const checkbox = document.getElementById('prefUndoEnabled');
    const gateMsg = document.getElementById('prefUndoGateMsg');
    if (canDisableUndo()) {
        checkbox.disabled = false;
        checkbox.checked = AppState.preferences.undoEnabled !== false;
        gateMsg.classList.add('hidden');
        gateMsg.textContent = '';
        return;
    }
    checkbox.disabled = true;
    checkbox.checked = true; // gate força ligado
    const threshold = getUndoUnlockThreshold();
    const current = getUndoTreatedCount();
    if (!isFinite(threshold)) {
        gateMsg.textContent = t('prefs.undo.gate.noProfile');
    } else {
        const remaining = Math.max(0, threshold - current);
        gateMsg.textContent = t(remaining === 1 ? 'prefs.undo.gate.countdownUm' : 'prefs.undo.gate.countdown', { threshold, current, remaining });
    }
    gateMsg.classList.remove('hidden');
}

// Tema: preferência explícita do user (localStorage) vence; sem preferência,
// segue o sistema (M3/HIG). O listener em initApp acompanha mudanças do SO.
function getPreferredTheme() {
    let stored = null;
    try { stored = localStorage.getItem(THEME_KEY); } catch (e) {}
    if (stored === 'light' || stored === 'dark') return stored;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

// A raiz fica IGUAL à que o script do tema (index.src.html) deixa na carga: o
// botão e a recarga não podem pintar coisas diferentes. Até a auditoria de
// 2026-09-29 (A8), com o sistema escuro, trocar pro claro pelo botão deixava a
// barra do sistema e o fundo escuros até recarregar — o claro não ganhava o
// `tema-claro`, e só a PRIMEIRA meta mudava.
function applyTheme(theme) {
    const isDark = theme === 'dark';
    document.documentElement.classList.toggle('dark', isDark);
    // O par do `dark`: é o `tema-claro` que desliga a regra do styles.css que
    // pinta o fundo escuro por media query num sistema escuro.
    document.documentElement.classList.toggle('tema-claro', !isDark);
    document.body.classList.toggle('dark', isDark);
    document.getElementById('themeIconLight').classList.toggle('hidden', isDark);
    document.getElementById('themeIconDark').classList.toggle('hidden', !isDark);
    const themeBtn = document.getElementById('themeBtn');
    if (themeBtn) themeBtn.setAttribute('aria-pressed', isDark ? 'true' : 'false');
    // Status bar (Android/PWA) acompanha a surface do header, não a cor da marca.
    // TODAS as metas: seguindo o sistema elas são duas, uma por esquema, e o
    // navegador usa a que casa com o SISTEMA — que não é a primeira.
    document.querySelectorAll('meta[name="theme-color"]')
        .forEach((m) => m.setAttribute('content', isDark ? '#0f172a' : '#f8fafc'));
}

function toggleTheme() {
    const isDark = document.documentElement.classList.contains('dark');
    const next = isDark ? 'light' : 'dark';
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
    applyTheme(next);
}

// Snackbar M3: bottom-center (via #notifyStack), desliza de baixo, um clique
// dispensa. Duração 4s (mínimo M3). aria-live está no container (index.html).
// `onClick` opcional: quando presente, o toast vira um atalho (executa a ação
// E dispensa). Sem ele, o comportamento de sempre — clicar só dispensa.
// `copiavel`: o toast traz um texto pra COPIAR À MÃO (o link do pareamento
// quando a área de transferência falha). Aí selecionar não pode dispensá-lo:
// arrastar o mouse sobre o texto termina num clique, e o clique o tirava da
// tela junto com a seleção; e o relógio espera enquanto houver texto dele
// selecionado (auditoria de 2026-09-26). A aparência não muda.
// `sensivel`: o texto é credencial e fica FORA do diário (ver abaixo).
function showToast(message, type = 'info', durationMs = 4000, onClick = null, { copiavel = false, sensivel = false } = {}) {
    // Conquista é BANNER (topo), não snackbar (rodapé) — distinção do M3, e aqui
    // com motivo medido: no rodapé ela tapava os três botões do card por 8s em 2
    // de 3 aparelhos (gotcha #26). Snackbar confirma o que você acabou de fazer;
    // banner é proeminente, tem ação e fica mais tempo. Este convida a abrir as
    // Preferências — não confirma nada.
    // 'hint' segue a mesma régua da conquista: é banner, não snackbar — tem ação
    // (abre as Preferências), fica mais tempo e não confirma nada que acabou de
    // acontecer. O que muda é a cor: informar não é comemorar.
    // FUNIL do diário: todo aviso que a pessoa vê passa por aqui, e é isto que
    // reconstrói "o que estava na tela". O toast dura 4s — sem registrar, ele
    // some antes de qualquer captura, que foi exatamente o que aconteceu no
    // diagnóstico do owner (tela com erro, zero toast no DOM).
    // `sensivel`: o texto é CREDENCIAL (o link do pareamento, quando a área de
    // transferência falha) — o diário anota que houve o aviso, nunca o texto.
    // O diário vai pro relatório e pra cópia guardada no aparelho (auditoria de
    // 2026-09-26, D1).
    dlog('toast', sensivel ? { tipo: type, sensivel: true }
                           : { tipo: type, txt: String(message).replace(/<[^>]+>/g, '').slice(0, 140) });
    const ehBanner = type === 'achievement' || type === 'hint';
    const container = document.getElementById(ehBanner ? 'bannerContainer' : 'toastContainer');
    const toast = document.createElement('div');

    const colors = {
        success: 'bg-emerald-700',
        error: 'bg-rose-600',
        info: 'bg-slate-800 dark:bg-slate-100 dark:text-slate-900',
        // Conquista: dourado, pra não se confundir com um "sucesso" qualquer.
        achievement: 'bg-gradient-to-r from-amber-700 to-amber-800',
        // Dica: cyan da marca. Não é conquista (não houve mérito), não é erro e
        // não é confirmação — é o app contando algo que ele observou.
        hint: 'bg-gradient-to-r from-cyan-700 to-cyan-800'
    };

    const icons = {
        success: '<svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>',
        error: '<svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>',
        info: '<svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>',
        achievement: '<svg class="w-6 h-6 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 21h8m-4-4v4m6-17v4a6 6 0 11-12 0V4h12zm0 2h2a2 2 0 010 4h-2m-12-4H4a2 2 0 000 4h2"></path></svg>',
        // Cronômetro: a dica é sobre TEMPO, e o ícone diz isso antes do texto.
        hint: '<svg class="w-6 h-6 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>'
    };

    toast.className = `toast ${colors[type] || colors.info} text-white font-medium text-sm`;
    toast.innerHTML = `${(icons[type] || icons.info)}<span class="flex-1">${escapeHtml(message)}</span>`;
    toast.title = t('toast.dismissHint');

    let removed = false;
    const dismiss = () => {
        if (removed) return;
        removed = true;
        toast.style.transition = 'opacity 0.25s ease, transform 0.25s ease';
        toast.style.opacity = '0';
        // Sai por onde entrou: pra cima no topo, pra baixo no rodapé.
        toast.style.transform = `translateY(${type === 'achievement' ? '-20px' : '20px'})`;
        setTimeout(() => toast.remove(), 250);
    };
    // Há texto DESTE toast selecionado agora? (Só o copiável pergunta.)
    const selecionandoAqui = () => {
        try {
            const sel = window.getSelection && window.getSelection();
            if (!sel || sel.isCollapsed) return false;
            return toast.contains(sel.anchorNode) || !!(sel.containsNode && sel.containsNode(toast, true));
        } catch (e) { return false; }
    };
    toast.addEventListener('click', () => {
        // Soltar o botão depois de arrastar pra selecionar é um CLIQUE: sem isto
        // o toast sumia com a seleção junto, e o link não dava pra copiar.
        if (copiavel && selecionandoAqui()) return;
        if (onClick) {
            try { onClick(); } catch (e) { console.error('onClick do toast falhou', e); }
        }
        dismiss();
    });

    // Teto de empilhamento: no máx. 3 toasts (remove o mais antigo) pra não cobrir
    // os botões do card numa rajada de erros.
    while (container.children.length >= 3) {
        container.removeChild(container.firstElementChild);
    }
    container.appendChild(toast);
    // O copiável não some com texto dele selecionado: o relógio espera mais um
    // pouco e confere de novo (a pessoa está copiando).
    let relogio;
    const armar = (ms) => {
        relogio = setTimeout(() => {
            if (copiavel && selecionandoAqui()) { armar(TOAST_COPIAVEL_RECHECA_MS); return; }
            dismiss();
        }, ms);
    };
    armar(durationMs);
    // Punho pra quem precisa ACOMPANHAR algo: trocar o texto no lugar em vez de
    // empilhar um toast por passo. Call site que não precisa simplesmente ignora.
    return {
        texto(novo) {
            const alvo = toast.querySelector('span.flex-1');
            if (alvo) alvo.textContent = novo;
        },
        dispensar() { clearTimeout(relogio); dismiss(); },
        // Sai NA HORA, sem a animação de saída: quem chama põe outro aviso no
        // lugar dele (o treino, um por vez), e o que ainda estivesse saindo
        // contava no teto de 3 acima — o novo empurraria outro pra fora.
        remover() { clearTimeout(relogio); removed = true; toast.remove(); },
    };
}

// O arraste entrega o CARD em que começou: a ação só vale se o pedido dele
// ainda é o da frente (ver `agirNoPedidoDoGesto`).
function onSwipeLeft(card) { agirNoPedidoDoGesto(pedidoDoCard(card), handleReject); }
function onSwipeRight(card) { agirNoPedidoDoGesto(pedidoDoCard(card), handleMarkAsRead); }
function onSwipeUp(card) { agirNoPedidoDoGesto(pedidoDoCard(card), handleSkip); }
window.onSwipeLeft = onSwipeLeft;
window.onSwipeRight = onSwipeRight;
window.onSwipeUp = onSwipeUp;
window.showToast = showToast;

// Usado pelo swipe.js: o arraste não pode furar a janela do Desfazer — e quem
// tenta arrastar o card travado fica sabendo por quê (`avisarTravaAoTocar`).
window.acoesTravadas = acoesTravadas;
window.avisarTravaAoTocar = avisarTravaAoTocar;
window.direcaoTravada = direcaoTravada;
window.cardDaFrente = cardDaFrente;
window.aoFimDoGesto = aoFimDoGesto;

// Usados pelo presenca.js, que carrega DEPOIS deste arquivo.
window.cardParaConversa = cardParaConversa;
window.abrirPedidoRecebido = abrirPedidoRecebido;
